# Native iOS Habit Tracking Application (Swift)

Here's a complete native iOS habit tracking application written in Swift. This implementation includes:

1. A `Habit` model to represent habits
2. `HabitStore` for persistence using UserDefaults
3. Main habit list view with add functionality
4. Detailed habit view with completion tracking
5. Basic progress tracking

## 1. Habit Model

```swift
// Habit.swift
import Foundation

struct Habit: Codable {
    let id: String
    let title: String
    let description: String
    let targetFrequency: Int // Number of days to complete the habit
    var completionCount: Int
    var lastCompletionDate: Date?

    var isCompleted: Bool {
        completionCount >= targetFrequency
    }

    var progress: Float {
        guard targetFrequency > 0 else { return 0 }
        return Float(completionCount) / Float(targetFrequency)
    }
}
```

## 2. Habit Store (Persistence)

```swift
// HabitStore.swift
import Foundation

class HabitStore {
    private let habitsKey = "habits"

    func loadHabits() -> [Habit] {
        guard let data = UserDefaults.standard.data(forKey: habitsKey) else {
            return []
        }
        do {
            let habits = try JSONDecoder().decode([Habit].self, from: data)
            return habits
        } catch {
            print("Error decoding habits: \(error)")
            return []
        }
    }

    func saveHabits(_ habits: [Habit]) {
        do {
            let data = try JSONEncoder().encode(habits)
            UserDefaults.standard.set(data, forKey: habitsKey)
        } catch {
            print("Error encoding habits: \(error)")
        }
    }

    func addHabit(_ habit: Habit) {
        var habits = loadHabits()
        habits.append(habit)
        saveHabits(habits)
    }

    func updateHabit(_ habit: Habit) {
        var habits = loadHabits()
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            saveHabits(habits)
        }
    }

    func deleteHabit(at index: Int) {
        var habits = loadHabits()
        habits.remove(at: index)
        saveHabits(habits)
    }
}
```

## 3. Main Habits View Controller

```swift
// HabitsViewController.swift
import UIKit

class HabitsViewController: UITableViewController {
    private let habitStore = HabitStore()
    private var habits: [Habit] = []

    override func viewDidLoad() {
        super.viewDidLoad()
        setupNavigation()
        setupTableView()
        loadHabits()
    }

    private func setupNavigation() {
        title = "Habits"
        navigationController?.navigationBar.prefersLargeTitles = true
        navigationItem.rightBarButtonItem = UIBarButtonItem(
            barButtonSystemItem: .add,
            target: self,
            action: #selector(addHabitTapped)
        )
    }

    private func setupTableView() {
        tableView.register(UITableViewCell.self, forCellReuseIdentifier: "HabitCell")
        tableView.rowHeight = UITableView.automaticDimension
        tableView.estimatedRowHeight = 60
    }

    private func loadHabits() {
        habits = habitStore.loadHabits()
        tableView.reloadData()
    }

    @objc private func addHabitTapped() {
        let alert = UIAlertController(title: "New Habit", message: nil, preferredStyle: .alert)

        alert.addTextField { textField in
            textField.placeholder = "Title (required)"
        }

        alert.addTextField { textField in
            textField.placeholder = "Description"
        }

        alert.addTextField { textField in
            textField.placeholder = "Target frequency (days)"
            textField.keyboardType = .numberPad
        }

        let addAction = UIAlertAction(title: "Add", style: .default) { [weak self] _ in
            guard let title = alert.textFields?[0].text?.trimmingCharacters(in: .whitespacesAndNewlines),
                  !title.isEmpty else {
                self?.showAlert(title: "Error", message: "Please enter a title")
                return
            }

            let description = alert.textFields?[1].text ?? ""
            let targetFrequencyText = alert.textFields?[2].text ?? "1"
            let targetFrequency = Int(targetFrequencyText) ?? 1

            let newHabit = Habit(
                id: UUID().uuidString,
                title: title,
                description: description,
                targetFrequency: targetFrequency,
                completionCount: 0,
                lastCompletionDate: nil
            )

            self?.habitStore.addHabit(newHabit)
            self?.loadHabits()
        }

        let cancelAction = UIAlertAction(title: "Cancel", style: .cancel)

        alert.addAction(addAction)
        alert.addAction(cancelAction)

        present(alert, animated: true)
    }

    private func showAlert(title: String, message: String) {
        let alert = UIAlertController(title: title, message: message, preferredStyle: .alert)
        alert.addAction(UIAlertAction(title: "OK", style: .default))
        present(alert, animated: true)
    }

    // MARK: - Table View Data Source

    override func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
        habits.count
    }

    override func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "HabitCell", for: indexPath)
        let habit = habits[indexPath.row]

        cell.textLabel?.text = habit.title
        cell.detailTextLabel?.text = habit.description
        cell.detailTextLabel?.numberOfLines = 0

        // Progress indicator
        if habit.isCompleted {
            cell.accessoryType = .checkmark
            cell.tintColor = .systemGreen
        } else {
            cell.accessoryType = .none
        }

        return cell
    }

    override func tableView(_ tableView: UITableView, didSelectRowAt indexPath: IndexPath) {
        tableView.deselectRow(at: indexPath, animated: true)
        let habit = habits[indexPath.row]
        let detailVC = HabitDetailViewController(habit: habit, habitStore: habitStore)
        navigationController?.pushViewController(detailVC, animated: true)
    }

    override func tableView(_ tableView: UITableView, commit editingStyle: UITableViewCell.EditingStyle, forRowAt indexPath: IndexPath) {
        if editingStyle == .delete {
            habitStore.deleteHabit(at: indexPath.row)
            loadHabits()
        }
    }
}
```

