        return progressView
    }()

    private let progressLabel: UILabel = {
        let label = UILabel()
        label.font = UIFont.preferredFont(forTextStyle: .body)
        label.textAlignment = .center
        return label
    }()

    private let completionButton: UIButton = {
        let button = UIButton(type: .system)
        button.titleLabel?.font = UIFont.preferredFont(forTextStyle: .headline)
        button.backgroundColor = .systemBlue
        button.setTitleColor(.white, for: .normal)
        button.layer.cornerRadius = 8
        button.contentEdgeInsets = UIEdgeInsets(top: 12, left: 16, bottom: 12, right: 16)
        return button
    }()

    private let lastCompletionLabel: UILabel = {
        let label = UILabel()
        label.font = UIFont.preferredFont(forTextStyle: .footnote)
        label.textColor = .secondaryLabel
        return label
    }()

    init(habit: Habit, habitStore: HabitStore) {
        self.habit = habit
        self.habitStore = habitStore
        super.init(nibName: nil, bundle: nil)
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    override func viewDidLoad() {
        super.viewDidLoad()
        setupView()
        updateUI()
    }

    private func setupView() {
        view.backgroundColor = .systemBackground
        title = habit.title

        let stackView = UIStackView()
        stackView.axis = .vertical
        stackView.spacing = 20
        stackView.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(stackView)

        NSLayoutConstraint.activate([
            stackView.topAnchor.constraint(equalTo: view.safeAreaLayoutGuide.topAnchor, constant: 20),
            stackView.leadingAnchor.constraint(equalTo: view.leadingAnchor, constant: 20),
            stackView.trailingAnchor.constraint(equalTo: view.trailingAnchor, constant: -20)
        ])

        stackView.addArrangedSubview(titleLabel)
        stackView.addArrangedSubview(descriptionLabel)
        stackView.addArrangedSubview(progressView)
        stackView.addArrangedSubview(progressLabel)
        stackView.addArrangedSubview(completionButton)
        stackView.addArrangedSubview(lastCompletionLabel)

        progressView.heightAnchor.constraint(equalToConstant: 8).isActive = true

        completionButton.addTarget(self, action: #selector(completionButtonTapped), for: .touchUpInside)
    }

    private func updateUI() {
        titleLabel.text = habit.title
        descriptionLabel.text = habit.description.isEmpty ? "No description" : habit.description

        progressView.progress = habit.progress
        progressView.progressTintColor = habit.isCompleted ? .systemGreen : .systemBlue

        let progressText = "Progress: \(habit.completionCount)/\(habit.targetFrequency) (\(Int(habit.progress * 100))%)"
        progressLabel.text = progressText

        if habit.isCompleted {
            completionButton.setTitle("Completed! 🎉", for: .normal)
            completionButton.backgroundColor = .systemGreen
            completionButton.isEnabled = false
        } else {
            completionButton.setTitle("Mark as Completed", for: .normal)
            completionButton.backgroundColor = .systemBlue
            completionButton.isEnabled = true
        }

        if let lastCompletionDate = habit.lastCompletionDate {
            let formatter = DateFormatter()
            formatter.dateStyle = .medium
            formatter.timeStyle = .short
            lastCompletionLabel.text = "Last completed: \(formatter.string(from: lastCompletionDate))"
        } else {
            lastCompletionLabel.text = "Not completed yet"
        }
    }

    @objc private func completionButtonTapped() {
        var updatedHabit = habit
        updatedHabit.completionCount += 1
        updatedHabit.lastCompletionDate = Date()
        habitStore.updateHabit(updatedHabit)
        updateUI()
    }
}
