## 4. HabitListViewController.swift

```swift
import UIKit
import CoreData

class HabitListViewController: UIViewController {
    private let tableView = UITableView()
    private let addButton = UIBarButtonItem(barButtonSystemItem: .add, target: self, action: #selector(addHabit))
    private var habits: [Habit] = []
    private let context = (UIApplication.shared.delegate as! AppDelegate).persistentContainer.viewContext

    override func viewDidLoad() {
        super.viewDidLoad()
        setupUI()
        fetchHabits()
    }

    private func setupUI() {
        title = "Habits"
        view.backgroundColor = .systemBackground
        navigationItem.rightBarButtonItem = addButton

        tableView.dataSource = self
        tableView.delegate = self
        tableView.register(HabitTableViewCell.self, forCellReuseIdentifier: "HabitCell")
        tableView.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(tableView)

        NSLayoutConstraint.activate([
            tableView.topAnchor.constraint(equalTo: view.topAnchor),
            tableView.bottomAnchor.constraint(equalTo: view.bottomAnchor),
            tableView.leadingAnchor.constraint(equalTo: view.leadingAnchor),
            tableView.trailingAnchor.constraint(equalTo: view.trailingAnchor)
        ])
    }

    private func fetchHabits() {
        let request: NSFetchRequest<Habit> = Habit.fetchRequest()
        do {
            habits = try context.fetch(request)
            tableView.reloadData()
        } catch {
            print("Error fetching habits: \(error)")
        }
    }

    @objc private func addHabit() {
        let alert = UIAlertController(title: "New Habit", message: "Enter habit name", preferredStyle: .alert)
        alert.addTextField()
        alert.addAction(UIAlertAction(title: "Cancel", style: .cancel))
        alert.addAction(UIAlertAction(title: "Add", style: .default) { [weak self] _ in
            guard let self = self, let textField = alert.textFields?.first, let name = textField.text, !name.isEmpty else { return }
            let habit = Habit(context: self.context)
            habit.id = UUID()
            habit.name = name
            habit.createdAt = Date()
            habit.completionDates = []
            self.saveContext()
            self.fetchHabits()
        })
        present(alert, animated: true)
    }

    private func saveContext() {
        do {
            try context.save()
        } catch {
            print("Error saving context: \(error)")
        }
    }

    private func toggleHabitCompletion(for habit: Habit) {
        let today = Calendar.current.startOfDay(for: Date())
        if let index = habit.completionDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: today) }) {
            // Already completed today, remove completion
            habit.completionDates.remove(at: index)
        } else {
            // Mark as completed today
            habit.completionDates.append(today)
        }
        saveContext()
        tableView.reloadData()
    }
}

extension HabitListViewController: UITableViewDataSource, UITableViewDelegate {
    func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
        habits.count
    }

    func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "HabitCell", for: indexPath) as! HabitTableViewCell
        let habit = habits[indexPath.row]
        cell.configure(with: habit)
        return cell
    }

    func tableView(_ tableView: UITableView, didSelectRowAt indexPath: IndexPath) {
        tableView.deselectRow(at: indexPath, animated: true)
        let habit = habits[indexPath.row]
        toggleHabitCompletion(for: habit)
    }

    func tableView(_ tableView: UITableView, trailingSwipeActionsConfigurationForRowAt indexPath: IndexPath) -> UISwipeActionsConfiguration? {
        let deleteAction = UIContextualAction(style: .destructive, title: "Delete") { [weak self] _, _, completion in
            guard let self = self else { return }
            let habit = self.habits[indexPath.row]
            self.context.delete(habit)
            self.saveContext()
            self.fetchHabits()
            completion(true)
        }
        return UISwipeActionsConfiguration(actions: [deleteAction])
    }
}
```

## 5. HabitTableViewCell.swift

```swift
import UIKit

class HabitTableViewCell: UITableViewCell {
    private let nameLabel = UILabel()
    private let streakLabel = UILabel()
    private let checkmarkImageView = UIImageView()

    override init(style: UITableViewCell.CellStyle, reuseIdentifier: String?) {
        super.init(style: style, reuseIdentifier: reuseIdentifier)
        setupUI()
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    private func setupUI() {
        nameLabel.font = .systemFont(ofSize: 16, weight: .medium)
        streakLabel.font = .systemFont(ofSize: 14, weight: .regular)
        streakLabel.textColor = .systemGray

        checkmarkImageView.tintColor = .systemGreen
        checkmarkImageView.contentMode = .scaleAspectFit

        let stackView = UIStackView(arrangedSubviews: [nameLabel, streakLabel])
        stackView.axis = .vertical
        stackView.spacing = 4

        contentView.addSubview(stackView)
        contentView.addSubview(checkmarkImageView)

        stackView.translatesAutoresizingMaskIntoConstraints = false
        checkmarkImageView.translatesAutoresizingMaskIntoConstraints = false

        NSLayoutConstraint.activate([
            stackView.leadingAnchor.constraint(equalTo: contentView.leadingAnchor, constant: 16),
            stackView.centerYAnchor.constraint(equalTo: contentView.centerYAnchor),

            checkmarkImageView.trailingAnchor.constraint(equalTo: contentView.trailingAnchor, constant: -16),
            checkmarkImageView.centerYAnchor.constraint(equalTo: contentView.centerYAnchor),
            checkmarkImageView.widthAnchor.constraint(equalToConstant: 24),
            checkmarkImageView.heightAnchor.constraint(equalToConstant: 24)
        ])
    }

    func configure(with habit: Habit) {
        nameLabel.text = habit.name

        // Calculate streak
        let calendar = Calendar.current
        let completionDates = habit.completionDates.sorted()
        var streak = 0
        if !completionDates.isEmpty {
            streak = 1
            for i in 1..<completionDates.count {
                if calendar.isDate(completionDates[i], equalTo: completionDates[i-1], toGranularity: .day) {
                    // Same day, skip
                } else if calendar.isDate(completionDates[i], inSameDayAs: calendar.date(byAdding: .day, value: 1, to: completionDates[i-1])!) {
                    streak += 1
                } else {
                    break
                }
            }
        }
        streakLabel.text = "Streak: \(streak)"

        // Update checkmark
        let today = calendar.startOfDay(for: Date())
        let isCompletedToday = habit.completionDates.contains { calendar.isDate($0, inSameDayAs: today) }
        checkmarkImageView.image = isCompletedToday ? UIImage(systemName: "checkmark.circle.fill") : UIImage(systemName: "circle")
    }
}
```

