Here's a complete native iOS habit tracking application written in Swift using SwiftUI:

```swift
import SwiftUI

// MARK: - Habit Model
struct Habit: Identifiable, Codable {
    let id: UUID
    var title: String
    var description: String?
    var completionDates: [Date]
    var targetFrequency: Int // e.g., 1 for daily, 2 for every other day, etc.

    init(id: UUID = UUID(), title: String, description: String? = nil, completionDates: [Date] = [], targetFrequency: Int = 1) {
        self.id = id
        self.title = title
        self.description = description
        self.completionDates = completionDates
        self.targetFrequency = targetFrequency
    }
}

// MARK: - Habit Manager
class HabitManager: ObservableObject {
    @Published var habits: [Habit] = []

    private let habitsKey = "savedHabits"

    init() {
        loadHabits()
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        saveHabits()
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            saveHabits()
        }
    }

    func deleteHabit(at indexSet: IndexSet) {
        habits.remove(atOffsets: indexSet)
        saveHabits()
    }

    func toggleCompletion(for habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            let today = Calendar.current.startOfDay(for: Date())
            if let completionIndex = habits[index].completionDates.firstIndex(where: {
                Calendar.current.isDate($0, inSameDayAs: today)
            }) {
                // Remove completion if already marked for today
                habits[index].completionDates.remove(at: completionIndex)
            } else {
                // Add completion for today
                habits[index].completionDates.append(today)
            }
            updateHabit(habits[index])
        }
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: habitsKey)
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: habitsKey),
           let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
            habits = decoded
        }
    }
}

// MARK: - Habit List View
struct HabitListView: View {
    @StateObject private var habitManager = HabitManager()
    @State private var isAddingHabit = false

    var body: some View {
        NavigationStack {
            List {
                ForEach(habitManager.habits) { habit in
                    NavigationLink {
                        HabitDetailView(habit: habit, habitManager: habitManager)
                    } label: {
                        HStack {
                            VStack(alignment: .leading) {
                                Text(habit.title)
                                    .font(.headline)
                                Text(habit.description ?? "")
                                    .font(.subheadline)
                                    .foregroundColor(.gray)
                                Text("\(habit.completionDates.count) completions")
