import Foundation
import CoreData

@objc(Habit)
public class Habit: NSManagedObject {
    @nonobjc public class func fetchRequest() -> NSFetchRequest<Habit> {
        return NSFetchRequest<Habit>(entityName: "Habit")
    }

    @NSManaged public var name: String
    @NSManaged public var completionCount: Int64
    @NSManaged public var lastCompletionDate: Date?
}

extension Habit {
    func markCompleted() {
        let calendar = Calendar.current
        let today = Date()

        if let lastDate = lastCompletionDate,
           calendar.isDate(lastDate, inSameDayAs: today) {
            // Already completed today
            return
        }

        completionCount += 1
        lastCompletionDate = today
    }

    var streak: Int {
        guard let lastDate = lastCompletionDate else { return 0 }
        let calendar = Calendar.current
        let daysPassed = calendar.dateComponents([.day], from: lastDate, to: Date()).day ?? 0
        return daysPassed == 1 ? Int(completionCount) : 0
    }
}
