    }

    override func viewDidLoad() {
        super.viewDidLoad()
        view.backgroundColor = .white
        title = habit.title

        setupViews()
        updateUI()
    }

    private func setupViews() {
        let stackView = UIStackView()
        stackView.axis = .vertical
        stackView.spacing = 16
