import Foundation
import CoreData

class HabitStore: ObservableObject {
    let container: NSPersistentContainer
    @Published var habits: [Habit] = []

    init() {
        container = NSPersistentContainer(name: "HabitTracker")
        container.loadPersistentStores { description, error in
            if let error = error {
                print("Error loading Core Data: \(error)")
            }
        }
        fetchHabits()
    }

    func fetchHabits() {
        let request = NSFetchRequest<Habit>(entityName: "Habit")
        do {
            habits = try container.viewContext.fetch(request)
        } catch {
            print("Error fetching habits: \(error)")
        }
    }

    func addHabit(name: String, frequency: String) {
        let newHabit = Habit(context: container.viewContext)
        newHabit.id = UUID()
        newHabit.name = name
        newHabit.frequency = frequency
        newHabit.createdAt = Date()

        do {
            try container.viewContext.save()
            fetchHabits()
        } catch {
            print("Error saving habit: \(error)")
        }
    }

    func toggleCompletion(for habit: Habit, on date: Date) {
        let calendar = Calendar.current
        let components = calendar.dateComponents([.year, .month, .day], from: date)
        let startOfDay = calendar.date(from: components)!

        // Check if completion already exists for this habit on this day
        if let existingCompletion = habit.completions?.first(where: { calendar.isDate($0.date, inSameDayAs: startOfDay) }) {
            // Remove completion
            container.viewContext.delete(existingCompletion)
        } else {
            // Add completion
            let completion = HabitCompletion(context: container.viewContext)
            completion.id = UUID()
            completion.date = startOfDay
            completion.habit = habit
            habit.addToCompletions(completion)
        }

        do {
            try container.viewContext.save()
            fetchHabits() // Refresh the list to update streaks
        } catch {
            print("Error toggling completion: \(error)")
        }
    }

    func deleteHabit(_ habit: Habit) {
        container.viewContext.delete(habit)
        do {
            try container.viewContext.save()
            fetchHabits()
        } catch {
            print("Error deleting habit: \(error)")
        }
    }
}
```

