extension Habit {
    var currentStreak: Int {
        guard let completions = completions else { return 0 }
        let sortedCompletions = completions.sorted { $0.date < $1.date }
        guard !sortedCompletions.isEmpty else { return 0 }

        var streak = 1
        for i in 1..<sortedCompletions.count {
            let calendar = Calendar.current
            if calendar.isDate(sortedCompletions[i].date, equalTo: sortedCompletions[i-1].date, toGranularity: .day) {
                // Same day, shouldn't happen but just in case
                continue
            }
            if calendar.isDate(sortedCompletions[i].date, inSameDayAs: sortedCompletions[i-1].date.addingTimeInterval(86400)) {
                streak += 1
            } else {
                break
            }
        }
        return streak
    }
}
