// MARK: - Habit Model
@Model
final class Habit {
    var name: String
    var frequency: Int // Number of times per day/week
    var completionCount: Int
    var lastCompletionDate: Date?
    var color: String // Hex color string for customization

    init(name: String, frequency: Int = 1, color: String = "#FF6B6B") {
        self.name = name
        self.frequency = frequency
        self.completionCount = 0
        self.color = color
    }

    var completionPercentage: Double {
        guard frequency > 0 else { return 0 }
        return Double(completionCount) / Double(frequency) * 100
    }

    func markCompleted() {
        completionCount += 1
        lastCompletionDate = Date()
    }

    func resetCompletion() {
        completionCount = 0
        lastCompletionDate = nil
    }
}

// MARK: - Data Manager
@MainActor
class HabitDataManager {
    private let modelContainer: ModelContainer
    private let modelContext: ModelContext

    init() {
        let schema = Schema([
            Habit.self,
        ])
        let config = ModelConfiguration(schema: schema, isStoredInMemoryOnly: false)
        do {
            modelContainer = try ModelContainer(for: schema, configurations: config)
            modelContext = modelContainer.mainContext
        } catch {
            fatalError("Failed to initialize ModelContainer: \(error)")
        }
    }

    func addHabit(_ habit: Habit) {
        modelContext.insert(habit)
        saveContext()
    }

    func deleteHabit(_ habit: Habit) {
        modelContext.delete(habit)
        saveContext()
    }

    func updateHabit(_ habit: Habit) {
        saveContext()
    }

    func fetchHabits() -> [Habit] {
        let fetchDescriptor = FetchDescriptor<Habit>(sortBy: [SortDescriptor(\.name)])
        do {
            return try modelContext.fetch(fetchDescriptor)
        } catch {
            print("Fetch failed: \(error)")
            return []
        }
    }

    private func saveContext() {
        do {
            try modelContext.save()
        } catch {
            print("Failed to save context: \(error)")
        }
    }
}

