### Data Store:
We'll create an `ObservableObject` to manage the list of habits.

```swift
class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    func addHabit(name: String, description: String, frequency: Habit.Frequency) {
        let newHabit = Habit(name: name, description: description, frequency: frequency, completionHistory: [])
        habits.append(newHabit)
    }

    func toggleCompletion(for habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            if habits[index].completionHistory.contains(Date().startOfDay) {
                // If already completed today, remove the completion
                habits[index].completionHistory.removeAll { $0.startOfDay == Date().startOfDay }
            } else {
                // Mark as completed today
                habits[index].completionHistory.append(Date().startOfDay)
            }
        }
    }
}

extension Date {
    var startOfDay: Date {
        Calendar.current.startOfDay(for: self)
    }
}
```

