    let id: UUID
    var name: String
    var completionCount: Int

    init(id: UUID = UUID(), name: String, completionCount: Int = 0) {
        self.id = id
        self.name = name
        self.completionCount = completionCount
    }
}

// MARK: - Data Manager (Persistence)
class HabitDataManager: ObservableObject {
    @Published var habits: [Habit] = []

    private let saveKey = "SavedHabits"

    init() {
        loadHabits()
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        saveHabits()
    }

    func toggleCompletion(for habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index].completionCount += 1
            saveHabits()
        }
    }

    func deleteHabit(at indexSet: IndexSet) {
        habits.remove(atOffsets: indexSet)
        saveHabits()
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: saveKey)
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: saveKey),
           let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
            habits = decoded
        }
    }
}

