### Repository (data/repository/UserRepository.kt)

```kotlin
package com.example.bankingapp.data.repository

import com.example.bankingapp.data.model.AuthResponse
import com.example.bankingapp.data.model.LoginRequest
import com.example.bankingapp.data.model.RegisterRequest
import com.example.bankingapp.data.model.User
import com.example.bankingapp.data.source.ApiService
import com.example.bankingapp.data.source.SecureStorage
import com.example.bankingapp.utils.Resource
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.flow
import retrofit2.HttpException
import java.io.IOException

class UserRepository(
    private val apiService: ApiService,
    private val secureStorage: SecureStorage
) {
    suspend fun login(email: String, password: String): Flow<Resource<AuthResponse>> = flow {
        emit(Resource.Loading())
        try {
            val response = apiService.login(LoginRequest(email, password))
            if (response.isSuccessful && response.body() != null) {
                secureStorage.saveToken(response.body()!!.token)
                secureStorage.saveUser(response.body()!!.user)
                emit(Resource.Success(response.body()!!))
            } else {
                emit(Resource.Error(response.errorBody()?.string() ?: "Login failed"))
            }
        } catch (e: HttpException) {
            emit(Resource.Error(e.localizedMessage ?: "An error occurred"))
        } catch (e: IOException) {
            emit(Resource.Error("Couldn't reach server. Check your internet connection."))
        }
    }

    suspend fun register(name: String, email: String, password: String): Flow<Resource<AuthResponse>> = flow {
        emit(Resource.Loading())
        try {
            val response = apiService.register(RegisterRequest(name, email, password))
            if (response.isSuccessful && response.body() != null) {
                secureStorage.saveToken(response.body()!!.token)
                secureStorage.saveUser(response.body()!!.user)
                emit(Resource.Success(response.body()!!))
            } else {
                emit(Resource.Error(response.errorBody()?.string() ?: "Registration failed"))
            }
        } catch (e: HttpException) {
            emit(Resource.Error(e.localizedMessage ?: "An error occurred"))
        } catch (e: IOException) {
            emit(Resource.Error("Couldn't reach server. Check your internet connection."))
        }
    }

    fun getCurrentUser(): User? = secureStorage.getUser()

    fun logout() {
        secureStorage.clearToken()
    }
}
