import com.example.bankingapp.data.model.TransactionType
import com.example.bankingapp.presentation.components.LoadingIndicator
import java.text.SimpleDateFormat
import java.util.Locale

@Composable
fun TransactionsScreen(
    viewModel: TransactionsViewModel,
    navController: NavController
) {
    val transactions = viewModel.transactions.collectAsState().value
    val isLoading = viewModel.isLoading.collectAsState().value

    LaunchedEffect(Unit) {
        viewModel.loadTransactions()
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp),
        verticalArrangement = Arrangement.Top
    ) {
        Text(
            text = "Transaction History",
            style = MaterialTheme.typography.headlineMedium,
            modifier = Modifier.padding(bottom = 16.dp)
        )

        when {
            isLoading -> LoadingIndicator()
            transactions != null -> {
                if (transactions.isEmpty()) {
                    Text("No transactions found")
                } else {
                    LazyColumn {
                        items(transactions) { transaction ->
                            TransactionItem(transaction = transaction)
                            Spacer(modifier = Modifier.height(8.dp))
                        }
                    }
                }
            }
            else -> {
                Text("Failed to load transactions")
                Button(onClick = { viewModel.loadTransactions() }) {
                    Text("Retry")
                }
            }
        }
    }
}

@Composable
fun TransactionItem(transaction: Transaction) {
    val dateFormat = SimpleDateFormat("MMM dd, yyyy hh:mm a", Locale.getDefault())
    val formattedDate = dateFormat.format(transaction.date)

    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(8.dp),
        horizontalArrangement = Arrangement.SpaceBetween
    ) {
        Column {
            Text(
                text = transaction.description,
                fontWeight = FontWeight.Bold
            )
            Text(
                text = formattedDate,
                style = MaterialTheme.typography.bodySmall
            )
            if (transaction.type == TransactionType.TRANSFER) {
                Text(
                    text = "To: ${transaction.recipient}",
                    style = MaterialTheme.typography.bodySmall
                )
            }
        }
        Text(
            text = when (transaction.type) {
                TransactionType.DEPOSIT -> "+$${"%.2f".format(transaction.amount)}"
                TransactionType.WITHDRAWAL, TransactionType.TRANSFER -> "-$${"%.2f".format(transaction.amount)}"
            },
            color = when (transaction.type) {
                TransactionType.DEPOSIT -> MaterialTheme.colorScheme.primary
                TransactionType.WITHDRAWAL, TransactionType.TRANSFER -> MaterialTheme.colorScheme.error
            },
            fontWeight = FontWeight.Bold
        )
    }
}
