package com.example.bankingapp.di

import com.example.bankingapp.data.repository.TransactionRepository
import com.example.bankingapp.data.repository.UserRepository
import com.example.bankingapp.data.source.ApiService
import com.example.bankingapp.data.source.SecureStorage
import com.example.bankingapp.domain.usecase.GetCurrentUserUseCase
import com.example.bankingapp.domain.usecase.LoginUseCase
import com.example.bankingapp.domain.usecase.LogoutUseCase
import com.example.bankingapp.domain.usecase.RegisterUseCase
import com.example.bankingapp.presentation.screens.AuthViewModel
import com.example.bankingapp.presentation.screens.HomeViewModel
import com.example.bankingapp.presentation.screens.TransactionsViewModel
import okhttp3.OkHttpClient
import okhttp3.logging.HttpLoggingInterceptor
import org.koin.android.ext.koin.androidContext
import org.koin.androidx.viewmodel.dsl.viewModel
import org.koin.dsl.module
import retrofit2.Retrofit
import retrofit2.converter.gson.GsonConverterFactory
import java.util.concurrent.TimeUnit

val appModule = module {
    // Secure Storage
    single { SecureStorage(androidContext()) }

    // API Service
    single<ApiService> {
        val loggingInterceptor = HttpLoggingInterceptor().apply {
            level = HttpLoggingInterceptor.Level.BODY
        }
        val client = OkHttpClient.Builder()
            .addInterceptor(loggingInterceptor)
            .connectTimeout(30, TimeUnit.SECONDS)
            .readTimeout(30, TimeUnit.SECONDS)
            .build()

        Retrofit.Builder()
            .baseUrl("https://api.example.com/") // Replace with your API base URL
            .addConverterFactory(GsonConverterFactory.create())
            .client(client)
            .build()
            .create(ApiService::class.java)
    }

    // Repositories
    single { UserRepository(get(), get()) }
    single { TransactionRepository(get(), get()) }

    // Use Cases
    single { LoginUseCase(get()) }
    single { RegisterUseCase(get()) }
    single { GetCurrentUserUseCase(get()) }
    single { LogoutUseCase(get()) }

    // ViewModels
    viewModel { AuthViewModel(get(), get()) }
    viewModel { HomeViewModel(get(), get()) }
    viewModel { TransactionsViewModel(get()) }
}
