import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch

class AuthViewModel : ViewModel() {
    private val _currentUser = mutableStateOf<User?>(null)
    val currentUser: User? get() = _currentUser.value

    private val _loginState = mutableStateOf<LoginState>(LoginState.Idle)
    val loginState: LoginState get() = _loginState.value

    private val _registerState = mutableStateOf<RegisterState>(RegisterState.Idle)
    val registerState: RegisterState get() = _registerState.value

    fun login(username: String, password: String) {
        viewModelScope.launch {
            _loginState.value = LoginState.Loading
            delay(1000) // Simulate network call

            // In a real app, you would verify credentials with a backend
            if (username == "user" && password == "password") {
                _currentUser.value = User(
                    username = username,
                    passwordHash = "", // In real app, store hashed password
                    accountNumber = "1234567890",
                    fullName = "John Doe",
                    email = "john@example.com",
                    phone = "123-456-7890"
                )
                _loginState.value = LoginState.Success
            } else {
                _loginState.value = LoginState.Error("Invalid credentials")
            }
        }
    }

    fun register(user: User) {
        viewModelScope.launch {
            _registerState.value = RegisterState.Loading
            delay(1500) // Simulate network call

            // In a real app, you would register with a backend
            _currentUser.value = user.copy(
                accountNumber = generateAccountNumber()
            )
            _registerState.value = RegisterState.Success
        }
    }

    private fun generateAccountNumber(): String {
        return (1000000000L..9999999999L).random().toString()
    }

    fun logout() {
        _currentUser.value = null
    }
}

sealed class LoginState {
    object Idle : LoginState()
    object Loading : LoginState()
    object Success : LoginState()
    data class Error(val message: String) : LoginState()
}

sealed class RegisterState {
    object Idle : RegisterState()
    object Loading : RegisterState()
    object Success : RegisterState()
    data class Error(val message: String) : RegisterState()
}

