                        TransactionType.WITHDRAWAL -> MaterialTheme.colorScheme.onErrorContainer
                        TransactionType.TRANSFER -> MaterialTheme.colorScheme.onTertiaryContainer
                        TransactionType.PAYMENT -> MaterialTheme.colorScheme.onSecondaryContainer
