interface BankingApiService {
    @POST("auth/login")
    suspend fun login(@Body request: LoginRequest): Response<AuthResponse>

    @POST("auth/register")
    suspend fun register(@Body request: RegisterRequest): Response<AuthResponse>

    @GET("accounts/{accountNumber}")
    suspend fun getAccount(@Path("accountNumber") accountNumber: String): Response<User>

    @GET("transactions")
    suspend fun getTransactions(
        @Query("accountNumber") accountNumber: String,
        @Query("limit") limit: Int = 20
    ): Response<List<Transaction>>

    @POST("transactions/transfer")
    suspend fun transferMoney(@Body request: TransferRequest): Response<Transaction>
}

// Request models
data class LoginRequest(val email: String, val password: String)
data class RegisterRequest(
    val name: String,
    val email: String,
    val password: String,
    val initialDeposit: Double
)
