```kotlin
// repository/AuthRepository.kt
import android.content.Context
import androidx.security.crypto.EncryptedSharedPreferences
import androidx.security.crypto.MasterKeys
import com.example.bankingapp.api.BankingApiService
import com.example.bankingapp.models.ApiResponse
import com.example.bankingapp.models.AuthResponse
import com.example.bankingapp.models.LoginRequest
import com.example.bankingapp.models.RegisterRequest
import dagger.hilt.android.qualifiers.ApplicationContext
import javax.inject.Inject

class AuthRepository @Inject constructor(
    private val apiService: BankingApiService,
    @ApplicationContext private val context: Context
) {
    private val masterKeyAlias = MasterKeys.getOrCreate(MasterKeys.AES256_GCM_SPEC)
    private val sharedPreferences = EncryptedSharedPreferences.create(
        "secure_auth_prefs",
        masterKeyAlias,
        context,
        EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
        EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
    )

    suspend fun login(email: String, password: String): ApiResponse<AuthResponse> {
        return try {
            val response = apiService.login(LoginRequest(email, password))
            if (response.isSuccessful) {
                response.body()?.let { authResponse ->
                    // Store token securely
                    sharedPreferences.edit().putString("auth_token", authResponse.token).apply()
                    ApiResponse.Success(authResponse)
                } ?: ApiResponse.Error("Empty response")
            } else {
                ApiResponse.Error(response.errorBody()?.string() ?: "Login failed")
            }
        } catch (e: Exception) {
            ApiResponse.Error(e.message ?: "Network error")
        }
    }

    suspend fun register(request: RegisterRequest): ApiResponse<AuthResponse> {
        return try {
            val response = apiService.register(request)
            if (response.isSuccessful) {
                response.body()?.let { authResponse ->
                    sharedPreferences.edit().putString("auth_token", authResponse.token).apply()
                    ApiResponse.Success(authResponse)
                } ?: ApiResponse.Error("Empty response")
            } else {
                ApiResponse.Error(response.errorBody()?.string() ?: "Registration failed")
            }
        } catch (e: Exception) {
            ApiResponse.Error(e.message ?: "Network error")
        }
    }

    fun getAuthToken(): String? {
        return sharedPreferences.getString("auth_token", null)
    }

    fun logout() {
        sharedPreferences.edit().clear().apply()
    }
}

