fun TransactionItem(transaction: Transaction) {
    val isCredit = transaction.type == TransactionType.DEPOSIT || transaction.type == TransactionType.TRANSFER
    val amountColor = if (isCredit) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.error

    Card(
        modifier = Modifier.fillMaxWidth()
    ) {
        Column(
            modifier = Modifier.padding(16.dp)
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                Text(
                    text = transaction.description,
                    style = MaterialTheme.typography.bodyLarge
                )

                Text(
                    text = if (isCredit) "+$${"%.2f".format(transaction.amount)}"
                    else "-$${"%.2f".format(transaction.amount)}",
                    color = amountColor,
                    fontWeight = FontWeight.Bold
                )
            }

            Spacer(modifier = Modifier.height(4.dp))

            Text(
                text = SimpleDateFormat("MMM dd, yyyy", Locale.getDefault()).format(
                    SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss", Locale.getDefault()).parse(transaction.date)!!
                ),
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
            )

            if (transaction.type == TransactionType.TRANSFER && transaction.toAccount != null) {
                Spacer(modifier = Modifier.height(4.dp))
                Text(
                    text = "To: ${transaction.toAccount}",
