## 4. Repository

### `data/repository/BankingRepository.kt`
```kotlin
package com.example.bankingapp.data.repository

import com.example.bankingapp.data.model.Transaction
import com.example.bankingapp.data.model.User
import com.example.bankingapp.data.service.BankingApiService
import com.example.bankingapp.data.storage.SecureStorage
import com.example.bankingapp.domain.model.LoginRequest
import com.example.bankingapp.domain.model.LoginResponse
import com.example.bankingapp.domain.model.Result
import com.example.bankingapp.domain.model.asDomainModel
import com.example.bankingapp.domain.model.toJson
import com.example.bankingapp.domain.model.toUser
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

class BankingRepository(
    private val apiService: BankingApiService,
    private val secureStorage: SecureStorage
) {
    suspend fun login(request: LoginRequest): Result<LoginResponse> = withContext(Dispatchers.IO) {
        try {
            val response = apiService.login(request.email, request.password)
            if (response.isSuccessful) {
                response.body()?.let { loginResponse ->
                    secureStorage.saveToken(loginResponse.token)
                    secureStorage.saveUser(loginResponse.user.toJson())
                    Result.Success(loginResponse.asDomainModel())
                } ?: Result.Error(Exception("Empty response"))
            } else {
                Result.Error(Exception("Login failed: ${response.message()}"))
            }
        } catch (e: Exception) {
            Result.Error(e)
        }
    }

    suspend fun getUser(): Result<User> = withContext(Dispatchers.IO) {
        try {
            secureStorage.getToken()?.let { token ->
                val response = apiService.getUser("Bearer $token")
                if (response.isSuccessful) {
                    response.body()?.let { user ->
                        secureStorage.saveUser(user.toJson())
                        Result.Success(user)
                    } ?: Result.Error(Exception("Empty user data"))
                } else {
                    Result.Error(Exception("Failed to fetch user: ${response.message()}"))
                }
            } ?: Result.Error(Exception("No auth token found"))
        } catch (e: Exception) {
            Result.Error(e)
        }
    }

    suspend fun getTransactions(): Result<List<Transaction>> = withContext(Dispatchers.IO) {
        try {
            secureStorage.getToken()?.let { token ->
                val response = apiService.getTransactions("Bearer $token")
                if (response.isSuccessful) {
                    Result.Success(response.body() ?: emptyList())
                } else {
                    Result.Error(Exception("Failed to fetch transactions: ${response.message()}"))
                }
            } ?: Result.Error(Exception("No auth token found"))
        } catch (e: Exception) {
            Result.Error(e)
        }
    }

    fun logout() {
        secureStorage.clearToken()
        secureStorage.clearUser()
    }

    fun isLoggedIn(): Boolean {
        return secureStorage.getToken() != null
    }
}
```

