import java.text.SimpleDateFormat
import java.util.Locale

@Composable
fun TransactionsScreen(
    viewModel: TransactionsViewModel,
    navController: NavController
) {
    val transactionsState = viewModel.transactionsState.collectAsState()

    LaunchedEffect(Unit) {
        viewModel.loadTransactions()
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp)
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically
        ) {
            IconButton(onClick = { navController.popBackStack() }) {
                Icon(
                    imageVector = Icons.Default.ArrowBack,
                    contentDescription = "Back"
                )
            }
            Text(
                text = "Transaction History",
                style = MaterialTheme.typography.headlineSmall,
                modifier = Modifier.padding(start = 8.dp)
            )
        }

        Spacer(modifier = Modifier.height(16.dp))

        when (val state = transactionsState.value) {
            is TransactionsViewModel.TransactionsState.Loading -> {
                Column(
                    modifier = Modifier.fillMaxSize(),
                    verticalArrangement = Arrangement.Center,
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    CircularProgressIndicator()
                }
            }
            is TransactionsViewModel.TransactionsState.Success -> {
                if (state.transactions.isEmpty()) {
                    Text(
                        text = "No transactions found",
                        modifier = Modifier.fillMaxWidth(),
                        textAlign = androidx.compose.ui.text.style.TextAlign.Center
                    )
                } else {
                    TransactionList(transactions = state.transactions)
                }
            }
            is TransactionsViewModel.TransactionsState.Error -> {
                Column(
                    modifier = Modifier.fillMaxSize(),
                    verticalArrangement = Arrangement.Center,
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    Text(
                        text = state.message,
                        color = MaterialTheme.colorScheme.error
                    )
                    Spacer(modifier = Modifier.height(8.dp))
                    Text(
                        text = "Pull to refresh",
                        style = MaterialTheme.typography.bodySmall
                    )
                }
            }
            else -> {}
        }
    }
}

@Composable
fun TransactionList(transactions: List<Transaction>) {
    LazyColumn(
        verticalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        items(transactions) { transaction ->
            TransactionItem(transaction = transaction)
        }
    }
}

@Composable
fun TransactionItem(transaction: Transaction) {
    val dateFormat = SimpleDateFormat("MMM dd, yyyy hh:mm a", Locale.getDefault())
    val formattedDate = dateFormat.format(transaction.date)

    Card(
        modifier = Modifier.fillMaxWidth()
    ) {
        Column(
            modifier = Modifier.padding(16.dp)
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                Text(
                    text = formattedDate,
                    style = MaterialTheme.typography.bodySmall
                )
                Text(
                    text = when (transaction.type) {
                        TransactionType.DEPOSIT -> "+ $${"%.2f".format(transaction.amount)}"
                        TransactionType.WITHDRAWAL -> "- $${"%.2f".format(transaction.amount)}"
                        TransactionType.TRANSFER -> "$${"%.2f".format(transaction.amount)}"
                    },
                    color = when (transaction.type) {
                        TransactionType.DEPOSIT -> MaterialTheme.colorScheme.primary
                        TransactionType.WITHDRAWAL -> MaterialTheme.colorScheme.error
                        TransactionType.TRANSFER -> MaterialTheme.colorScheme.primary
                    },
                    fontWeight = FontWeight.Bold
                )
            }

            Spacer(modifier = Modifier.height(8.dp))

            Text(
                text = transaction.description,
                style = MaterialTheme.typography.bodyMedium
            )

            Spacer(modifier = Modifier.height(8.dp))

            Text(
                text = "Balance after: $${"%.2f".format(transaction.balanceAfter)}",
                style = MaterialTheme.typography.bodySmall
            )
        }
    }
}
