class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        // Initialize dependencies
        val secureStorage = SecureStorage(applicationContext)

        val retrofit = Retrofit.Builder()
            .baseUrl("https://api.example.com/") // Replace with your API base URL
            .addConverterFactory(GsonConverterFactory.create())
            .build()

        val apiService = retrofit.create(BankingApiService::class.java)
        val repository = BankingRepository(apiService, secureStorage)

        val loginUseCase = LoginUseCase(repository)
        val getUserUseCase = GetUserUseCase(repository)
        val getTransactionsUseCase = GetTransactionsUseCase(repository)

        val loginViewModel = LoginViewModel(loginUseCase)
        val homeViewModel = HomeViewModel(getUserUseCase)
        val transactionsViewModel = TransactionsViewModel(getTransactionsUseCase)

        setContent {
            BankingAppTheme {
                Surface(
                    modifier = Modifier.fillMaxSize(),
                    color = MaterialTheme.colorScheme.background
                ) {
                    val navController = rememberNavController()
                    NavGraph(
                        navController = navController,
                        loginViewModel = loginViewModel,
                        homeViewModel = homeViewModel,
                        transactionsViewModel = transactionsViewModel,
                        startDestination = if (secureStorage.isLoggedIn()) "home" else "login"
                    )
                }
            }
        }
    }
}
