// TransactionViewModel.kt
class TransactionViewModel(
    private val transactionRepository: TransactionRepository,
    private val accountRepository: AccountRepository
) : ViewModel() {
    private val _transactions = MutableStateFlow<List<Transaction>>(emptyList())
    val transactions: StateFlow<List<Transaction>> = _transactions

    private val _isLoading = MutableStateFlow(false)
    val isLoading: StateFlow<Boolean> = _isLoading

    fun loadTransactions(accountId: Int) {
        viewModelScope.launch {
            _isLoading.value = true
            try {
                _transactions.value = transactionRepository.getTransactions(accountId)
            } catch (e: Exception) {
                // Handle error
            } finally {
                _isLoading.value = false
            }
        }
    }

    fun transferFunds(fromAccountId: Int, toAccountNumber: String, amount: Double, description: String) {
        viewModelScope.launch {
            _isLoading.value = true
            try {
                val fromAccount = accountRepository.getAccountById(fromAccountId)
                val toAccount = accountRepository.getAccount(toAccountNumber)

                if (fromAccount == null || toAccount == null) {
                    // Handle error
                    return@launch
                }

                if (fromAccount.balance < amount) {
                    // Handle insufficient funds
                    return@launch
                }

                // Update balances (in a real app, this would be a transaction)
                val newFromBalance = fromAccount.balance - amount
                val newToBalance = toAccount.balance + amount

                // In a real app, you'd update the balances in the database here

                // Record transactions
                val transaction1 = Transaction(
                    id = 0,
                    accountId = fromAccountId,
                    amount = -amount,
                    type = "Transfer",
                    date = SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.getDefault()).format(Date()),
                    description = "Transfer to $toAccountNumber: $description",
                    toAccount = toAccountNumber
                )

                val transaction2 = Transaction(
                    id = 0,
                    accountId = toAccount.id,
                    amount = amount,
                    type = "Transfer",
                    date = SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.getDefault()).format(Date()),
                    description = "Transfer from ${fromAccount.accountNumber}: $description",
                    toAccount = fromAccount.accountNumber
                )

                transactionRepository.addTransaction(transaction1)
                transactionRepository.addTransaction(transaction2)

                // Refresh data
                loadTransactions(fromAccountId)
            } catch (e: Exception) {
                // Handle error
            } finally {
                _isLoading.value = false
            }
        }
    }
}
