#### `AccountViewModel.kt`
```kotlin
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch
import java.util.UUID

class AccountViewModel(
    private val accountRepository: AccountRepository
) : ViewModel() {
    private val _accountState = MutableStateFlow<AccountState>(AccountState.Idle)
    val accountState: StateFlow<AccountState> = _accountState

    private val _transactionsState = MutableStateFlow<List<Transaction>>(emptyList())
    val transactionsState: StateFlow<List<Transaction>> = _transactionsState

    fun createAccount(userId: String) {
        viewModelScope.launch {
            _accountState.value = AccountState.Loading
            val account = Account(
                id = UUID.randomUUID().toString(),
                userId = userId,
                balance = 0.0,
                accountNumber = "ACC-${System.currentTimeMillis() % 10000}"
            )
            accountRepository.createAccount(account)
            _accountState.value = AccountState.Success(account)
        }
    }

    fun loadAccount(userId: String) {
        viewModelScope.launch {
            _accountState.value = AccountState.Loading
            val account = accountRepository.getAccount(userId)
            _accountState.value = if (account != null) {
                AccountState.Success(account)
            } else {
                AccountState.Error("Account not found")
            }
        }
    }

    fun loadTransactions(accountId: String) {
        viewModelScope.launch {
            _transactionsState.value = accountRepository.getTransactions(accountId)
        }
    }

    fun addTransaction(transaction: Transaction) {
        viewModelScope.launch {
            accountRepository.addTransaction(transaction)
            loadTransactions(transaction.accountId)
        }
    }
}

sealed class AccountState {
    object Idle : AccountState()
    object Loading : AccountState()
    data class Success(val account: Account) : AccountState()
    data class Error(val message: String) : AccountState()
}
