### 4. Repository (`data/repository/TransactionRepository.kt`)
```kotlin
// data/repository/TransactionRepository.kt
import com.example.bankingapp.data.local.TransactionDao
import com.example.bankingapp.data.local.TransactionEntity
import com.example.bankingapp.model.Transaction
import com.example.bankingapp.model.TransactionType
import javax.inject.Inject

class TransactionRepository @Inject constructor(
    private val transactionDao: TransactionDao
) {
    suspend fun addTransaction(transaction: Transaction) {
        transactionDao.insert(
            TransactionEntity(
                id = transaction.id,
                amount = transaction.amount,
                date = transaction.date,
                description = transaction.description,
                type = transaction.type.name,
                accountId = transaction.accountId
            )
        )
    }

    suspend fun getTransactions(accountId: String): List<Transaction> {
        return transactionDao.getTransactions(accountId).map {
            Transaction(
                id = it.id,
                amount = it.amount,
                date = it.date,
                description = it.description,
                type = TransactionType.valueOf(it.type),
                accountId = it.accountId
            )
        }
    }
}
