class TransactionRepository(private val transactionDao: TransactionDao) {
    suspend fun addTransaction(transaction: Transaction) {
        transactionDao.insertTransaction(transaction.toEntity())
    }

    suspend fun getTransactions(userId: String): List<Transaction> {
        return transactionDao.getTransactions(userId).map { it.toTransaction() }
    }

    suspend fun transferFunds(fromUserId: String, toAccount: String, amount: Double, description: String) {
        // In a real app, this would involve backend validation
        // For demo, we'll just record the transactions

        // Record withdrawal from sender
        val withdrawal = Transaction(
            id = UUID.randomUUID().toString(),
            userId = fromUserId,
            amount = -amount,
            type = TransactionType.TRANSFER,
            date = System.currentTimeMillis(),
            description = "Transfer to $toAccount: $description",
            toAccount = toAccount
        )

        // Record deposit to receiver (in a real app, this would be a different user)
        val deposit = Transaction(
            id = UUID.randomUUID().toString(),
            userId = "receiver_id", // In real app, this would be the receiver's userId
            amount = amount,
            type = TransactionType.DEPOSIT,
            date = System.currentTimeMillis(),
            description = "Transfer from $fromUserId: $description",
            toAccount = fromUserId
        )

        transactionDao.insertTransaction(withdrawal.toEntity())
        transactionDao.insertTransaction(deposit.toEntity())
    }
}

