class TransferViewModel(
    private val userRepository: UserRepository,
    private val transactionRepository: TransactionRepository
) : ViewModel() {
    private val _transferState = MutableStateFlow<TransferState>(TransferState.Idle)
    val transferState: StateFlow<TransferState> = _transferState

    fun transferFunds(fromUserId: String, toAccount: String, amount: Double, description: String) {
        viewModelScope.launch {
            _transferState.value = TransferState.Loading
            try {
                if (amount <= 0) {
                    _transferState.value = TransferState.Error("Amount must be positive")
                    return@launch
                }

                val user = userRepository.getUser(fromUserId)
                if (user == null || user.balance < amount) {
                    _transferState.value = TransferState.Error("Insufficient funds")
                    return@launch
                }

                transactionRepository.transferFunds(fromUserId, toAccount, amount, description)
                _transferState.value = TransferState.Success
            } catch (e: Exception) {
                _transferState.value = TransferState.Error(e.message ?: "Transfer failed")
            }
        }
    }
}

sealed class TransferState {
    object Idle : TransferState()
    object Loading : TransferState()
    object Success : TransferState()
    data class Error(val message: String) : TransferState()
}
