```kotlin
// BankingApiService.kt
interface BankingApiService {
    @POST("auth/login")
    suspend fun login(@Body loginRequest: LoginRequest): AuthResponse

    @GET("accounts/{userId}")
    suspend fun getAccounts(@Path("userId") userId: String): List<Account>

    @GET("transactions/{accountId}")
    suspend fun getTransactions(@Path("accountId") accountId: String): List<Transaction>

    companion object {
        private const val BASE_URL = "https://api.examplebank.com/v1/"

        fun create(): BankingApiService {
            val client = OkHttpClient.Builder()
                .addInterceptor(HttpLoggingInterceptor().apply {
                    level = HttpLoggingInterceptor.Level.BODY
                })
                .build()

            return Retrofit.Builder()
                .baseUrl(BASE_URL)
                .client(client)
                .addConverterFactory(GsonConverterFactory.create())
                .build()
                .create(BankingApiService::class.java)
        }
    }
}

// LoginRequest.kt
data class LoginRequest(
    val email: String,
    val password: String
