Next, let's create the repository:

```kotlin
// BankingRepository.kt
interface BankingRepository {
    suspend fun login(email: String, password: String): AuthResponse
    suspend fun getAccounts(): List<Account>
    suspend fun getTransactions(accountId: String): List<Transaction>
}

class BankingRepositoryImpl(
    private val apiService: BankingApiService,
    private val secureStorage: SecureStorage
) : BankingRepository {

    override suspend fun login(email: String, password: String): AuthResponse {
        val response = apiService.login(LoginRequest(email, password))
        secureStorage.saveAuthToken(response.token)
        secureStorage.saveUser(response.user)
        return response
    }

    override suspend fun getAccounts(): List<Account> {
        val userId = secureStorage.getUser()?.id ?: throw IllegalStateException("User not logged in")
        return apiService.getAccounts(userId)
    }

    override suspend fun getTransactions(accountId: String): List<Transaction> {
        return apiService.getTransactions(accountId)
    }
}
```

Now, let's create the secure storage helper:

```kotlin
// SecureStorage.kt
class SecureStorage @Inject constructor(@ApplicationContext context: Context) {
    private val sharedPreferences = EncryptedSharedPreferences.create(
        "secure_prefs",
        MasterKey.Builder(context)
            .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)
            .build(),
        context,
        EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
        EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
    )

    fun saveAuthToken(token: String) {
        sharedPreferences.edit().putString("auth_token", token).apply()
    }

    fun getAuthToken(): String? = sharedPreferences.getString("auth_token", null)

    fun saveUser(user: User) {
        sharedPreferences.edit().putString("user_id", user.id).apply()
        sharedPreferences.edit().putString("user_name", user.name).apply()
        sharedPreferences.edit().putString("user_email", user.email).apply()
    }

    fun getUser(): User? {
        val id = sharedPreferences.getString("user_id", null) ?: return null
        return User(
            id = id,
            name = sharedPreferences.getString("user_name", "") ?: "",
            email = sharedPreferences.getString("user_email", "") ?: "",
            phone = ""
        )
    }

    fun clear() {
        sharedPreferences.edit().clear().apply()
    }
}
