dependencies:
  flutter:
    sdk: flutter
  hive: ^2.2.3
  hive_flutter: ^1.1.0
  connectivity_plus: ^5.0.2
  http: ^1.1.0
  provider: ^6.0.5
  path_provider: ^2.1.1

dev_dependencies:
  flutter_lints: ^3.0.0
