  build_runner: ^2.4.6
```

## 2. Data Model (`survey_entry.dart`)

```dart
import 'package:hive/hive.dart';

part 'survey_entry.g.dart';

@HiveType(typeId: 0)
class SurveyEntry {
  @HiveField(0)
  final String id;

  @HiveField(1)
  final String location;

  @HiveField(2)
  final double latitude;

  @HiveField(3)
  final double longitude;

  @HiveField(4)
  final String notes;

  @HiveField(5)
  final DateTime timestamp;

  @HiveField(6)
  final bool isSynced;

  SurveyEntry({
    required this.id,
    required this.location,
    required this.latitude,
    required this.longitude,
    required this.notes,
    required this.timestamp,
    this.isSynced = false,
  });

  SurveyEntry copyWith({
    String? id,
    String? location,
    double? latitude,
    double? longitude,
    String? notes,
    DateTime? timestamp,
    bool? isSynced,
  }) {
    return SurveyEntry(
      id: id ?? this.id,
      location: location ?? this.location,
      latitude: latitude ?? this.latitude,
      longitude: longitude ?? this.longitude,
      notes: notes ?? this.notes,
      timestamp: timestamp ?? this.timestamp,
      isSynced: isSynced ?? this.isSynced,
    );
  }
}
```

## 3. Run `build_runner` to generate Hive adapters

```bash
flutter pub run build_runner build
```

## 4. Database Service (`database_service.dart`)

```dart
import 'package:hive/hive.dart';
import 'package:path_provider/path_provider.dart' as path_provider;
import 'survey_entry.dart';

class DatabaseService {
  static const String _boxName = 'survey_entries';

  static late Box<SurveyEntry> _box;

  static Future<void> init() async {
    final appDocumentDir = await path_provider.getApplicationDocumentsDirectory();
    Hive.init(appDocumentDir.path);
    Hive.registerAdapter(SurveyEntryAdapter());
    _box = await Hive.openBox<SurveyEntry>(_boxName);
  }

  static Future<void> saveEntry(SurveyEntry entry) async {
    await _box.put(entry.id, entry);
  }

  static List<SurveyEntry> getAllEntries() {
    return _box.values.toList();
  }

  static Future<void> updateEntry(SurveyEntry entry) async {
    await _box.put(entry.id, entry);
  }

  static Future<void> deleteEntry(String id) async {
    await _box.delete(id);
  }

  static Future<void> markAsSynced(String id) async {
    final entry = _box.get(id);
    if (entry != null) {
      await updateEntry(entry.copyWith(isSynced: true));
    }
  }

  static List<SurveyEntry> getUnsyncedEntries() {
    return _box.values.where((entry) => !entry.isSynced).toList();
  }
}
```

## 5. API Service (`api_service.dart`)

```dart
import 'dart:convert';
import 'package:http/http.dart' as http;
import 'survey_entry.dart';

class ApiService {
  static const String _baseUrl = 'https://your-backend-api.com/api/surveys';

  static Future<bool> syncEntry(SurveyEntry entry) async {
    try {
      final response = await http.post(
        Uri.parse('$_baseUrl'),
        headers: {'Content-Type': 'application/json'},
        body: jsonEncode({
          'id': entry.id,
          'location': entry.location,
          'latitude': entry.latitude,
          'longitude': entry.longitude,
          'notes': entry.notes,
          'timestamp': entry.timestamp.toIso8601String(),
        }),
      );

      if (response.statusCode == 201 || response.statusCode == 200) {
        return true;
      }
      return false;
    } catch (e) {
      return false;
    }
  }

  static Future<bool> syncAll(List<SurveyEntry> entries) async {
    try {
      final response = await http.post(
        Uri.parse('$_baseUrl/bulk'),
        headers: {'Content-Type': 'application/json'},
        body: jsonEncode(entries.map((e) => {
          'id': e.id,
          'location': e.location,
          'latitude': e.latitude,
          'longitude': e.longitude,
          'notes': e.notes,
          'timestamp': e.timestamp.toIso8601String(),
        }).toList()),
      );

      return response.statusCode == 200 || response.statusCode == 201;
    } catch (e) {
      return false;
    }
  }
}
```

## 6. Sync Service (`sync_service.dart`)

```dart
import 'package:connectivity_plus/connectivity_plus.dart';
import 'database_service.dart';
import 'api_service.dart';
import 'survey_entry.dart';

class SyncService {
  static bool _isSyncing = false;

  static Future<void> startSyncListener() async {
    Connectivity().onConnectivityChanged.listen((result) async {
      if (result != ConnectivityResult.none) {
        await _syncPendingEntries();
      }
    });
  }

  static Future<void> _syncPendingEntries() async {
    if (_isSyncing) return;

    _isSyncing = true;
    try {
      final unsyncedEntries = DatabaseService.getUnsyncedEntries();

      if (unsyncedEntries.isNotEmpty) {
        final success = await ApiService.syncAll(unsyncedEntries);

        if (success) {
          for (final entry in unsyncedEntries) {
            await DatabaseService.markAsSynced(entry.id);
          }
        }
      }
    } catch (e) {
      // Handle error
    } finally {
      _isSyncing = false;
    }
  }

  static Future<void> syncNow() async {
    await _syncPendingEntries();
  }
}
```

