## 1. Database Helper (`lib/database/database_helper.dart`)

```dart
import 'package:sqflite/sqflite.dart';
import 'package:path/path.dart';
import '../models/survey.dart';
import '../models/survey_response.dart';

class DatabaseHelper {
  static final DatabaseHelper instance = DatabaseHelper._init();
  static Database? _database;

  DatabaseHelper._init();

  Future<Database> get database async {
    if (_database != null) return _database!;
    _database = await _initDB('survey_app.db');
    return _database!;
  }

  Future<Database> _initDB(String filePath) async {
    final dbPath = await getDatabasesPath();
    final path = join(dbPath, filePath);

    return await openDatabase(path, version: 1, onCreate: _createDB);
  }

  Future _createDB(Database db, int version) async {
    await db.execute('''
      CREATE TABLE surveys (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        description TEXT,
        createdAt TEXT NOT NULL
      )
    ''');

    await db.execute('''
      CREATE TABLE survey_responses (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        surveyId INTEGER NOT NULL,
        responseData TEXT NOT NULL,
        isSynced INTEGER DEFAULT 0,
        createdAt TEXT NOT NULL,
        FOREIGN KEY (surveyId) REFERENCES surveys (id)
      )
    ''');
  }

  // Survey CRUD operations
  Future<int> insertSurvey(Survey survey) async {
    final db = await instance.database;
    return await db.insert('surveys', survey.toMap());
  }

  Future<List<Survey>> getAllSurveys() async {
    final db = await instance.database;
    final List<Map<String, dynamic>> maps = await db.query('surveys');
    return List.generate(maps.length, (i) => Survey.fromMap(maps[i]));
  }

  // Response CRUD operations
  Future<int> insertSurveyResponse(SurveyResponse response) async {
    final db = await instance.database;
    return await db.insert('survey_responses', response.toMap());
  }

  Future<List<SurveyResponse>> getUnsyncedResponses() async {
    final db = await instance.database;
    final List<Map<String, dynamic>> maps = await db.query(
      'survey_responses',
      where: 'isSynced = ?',
      whereArgs: [0],
    );
    return List.generate(maps.length, (i) => SurveyResponse.fromMap(maps[i]));
  }

  Future<void> markResponseAsSynced(int responseId) async {
    final db = await instance.database;
    await db.update(
      'survey_responses',
      {'isSynced': 1},
      where: 'id = ?',
      whereArgs: [responseId],
    );
  }

  Future close() async {
    final db = await instance.database;
    db.close();
  }
}
```

