## 4. Sync Service (`lib/services/sync_service.dart`)

```dart
import 'dart:convert';
import 'package:http/http.dart' as http;
import '../database/database_helper.dart';
import '../models/survey_response.dart';

class SyncService {
  final String apiUrl = 'https://your-api-endpoint.com/sync'; // Replace with your API
  final DatabaseHelper _dbHelper = DatabaseHelper.instance;

  Future<void> syncData() async {
    try {
      final unsyncedResponses = await _dbHelper.getUnsyncedResponses();

      if (unsyncedResponses.isEmpty) return;

      final response = await http.post(
        Uri.parse(apiUrl),
        headers: {'Content-Type': 'application/json'},
        body: json.encode({
          'responses': unsyncedResponses.map((r) => r.toMap()).toList(),
        }),
      );

      if (response.statusCode == 200) {
        final responseData = json.decode(response.body);
        if (responseData['success']) {
          // Mark responses as synced
          for (final response in unsyncedResponses) {
            await _dbHelper.markResponseAsSynced(response.id!);
          }
        }
      }
    } catch (e) {
      print('Sync failed: $e');
      // Optionally: Implement retry logic or queue for later
    }
  }
}
```

