## 2. Database Service (`Database.ts`)

```typescript
// Database.ts
import SQLite from 'react-native-sqlite-storage';

const db = SQLite.openDatabase(
  { name: 'survey.db', location: 'default' },
  () => console.log('Database opened'),
  error => console.error('Database error', error)
);

export const initDatabase = () => {
  db.transaction(tx => {
    tx.executeSql(
      'CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT, location TEXT, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP, status TEXT DEFAULT "pending", data TEXT);'
    );
    tx.executeSql(
      'CREATE TABLE IF NOT EXISTS sync_log (id INTEGER PRIMARY KEY AUTOINCREMENT, survey_id INTEGER, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP, status TEXT, message TEXT);'
    );
  });
};

export const saveSurvey = (userId: string, location: string, data: any) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'INSERT INTO surveys (user_id, location, data) VALUES (?, ?, ?)',
        [userId, location, JSON.stringify(data)],
        (_, result) => resolve(result.insertId),
        (_, error) => reject(error)
      );
    });
  });
};

export const getPendingSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys WHERE status = "pending" ORDER BY timestamp ASC',
        [],
        (_, { rows }) => resolve(rows._array),
        (_, error) => reject(error)
      );
    });
  });
};

export const markSurveySynced = (surveyId: number) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'UPDATE surveys SET status = "synced" WHERE id = ?',
        [surveyId],
        () => resolve(true),
        (_, error) => reject(error)
      );
    });
  });
};

export const logSyncEvent = (surveyId: number, status: string, message: string) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'INSERT INTO sync_log (survey_id, status, message) VALUES (?, ?, ?)',
        [surveyId, status, message],
        () => resolve(true),
        (_, error) => reject(error)
      );
    });
  });
};
```

## 3. Sync Service (`SyncService.ts`)

```typescript
// SyncService.ts
import NetInfo from '@react-native-community/netinfo';
import axios from 'axios';
import { getPendingSurveys, markSurveySynced, logSyncEvent } from './Database';

const API_URL = 'https://your-api-endpoint.com/surveys';

export const startSyncService = () => {
  // Check network status periodically
  NetInfo.addEventListener(state => {
    if (state.isConnected) {
      console.log('Network connected - attempting sync');
      syncPendingSurveys();
    }
  });

  // Initial check
  NetInfo.fetch().then(state => {
    if (state.isConnected) {
      syncPendingSurveys();
    }
  });
};

const syncPendingSurveys = async () => {
  try {
    const pendingSurveys = await getPendingSurveys();
    if (pendingSurveys.length === 0) return;

    console.log(`Found ${pendingSurveys.length} surveys to sync`);

    for (const survey of pendingSurveys) {
      try {
        const response = await axios.post(API_URL, {
          user_id: survey.user_id,
          location: survey.location,
          timestamp: survey.timestamp,
          data: JSON.parse(survey.data)
        });

        await markSurveySynced(survey.id);
        await logSyncEvent(survey.id, 'success', 'Survey synced successfully');
        console.log(`Synced survey ${survey.id}`);
      } catch (error) {
        await logSyncEvent(survey.id, 'failed', error.message);
        console.error(`Failed to sync survey ${survey.id}:`, error.message);
      }
    }
  } catch (error) {
    console.error('Sync error:', error);
  }
};
```

