// SurveyForm.tsx
import React, { useState } from 'react';
import { View, Text, TextInput, Button, StyleSheet, Alert } from 'react-native';
import { saveSurvey } from './Database';
import * as Location from 'expo-location';

const SurveyForm = () => {
  const [userId, setUserId] = useState('');
  const [location, setLocation] = useState<{lat: number, lng: number} | null>(null);
  const [responses, setResponses] = useState({
    question1: '',
    question2: '',
    question3: '',
  });

  const getCurrentLocation = async () => {
    try {
      const { status } = await Location.requestForegroundPermissionsAsync();
      if (status !== 'granted') {
        Alert.alert('Permission denied', 'Location permission is required');
        return;
      }

      const location = await Location.getCurrentPositionAsync({});
      setLocation({
        lat: location.coords.latitude,
        lng: location.coords.longitude
      });
    } catch (error) {
      console.error('Error getting location:', error);
      Alert.alert('Error', 'Could not get location');
    }
  };

  const handleSubmit = async () => {
    if (!userId || !location) {
      Alert.alert('Error', 'Please fill all fields and get location');
      return;
    }

    try {
      const surveyData = {
        ...responses,
        location: `${location.lat},${location.lng}`,
        timestamp: new Date().toISOString()
      };

      await saveSurvey(userId, `${location.lat},${location.lng}`, surveyData);
      Alert.alert('Success', 'Survey saved offline - will sync when online');
      setResponses({ question1: '', question2: '', question3: '' });
    } catch (error) {
      Alert.alert('Error', 'Failed to save survey');
      console.error(error);
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Field Survey</Text>

      <TextInput
        style={styles.input}
        placeholder="User ID"
        value={userId}
        onChangeText={setUserId}
      />

      <Button title="Get Current Location" onPress={getCurrentLocation} />

      {location && (
        <Text style={styles.locationText}>
          Location: {location.lat.toFixed(4)}, {location.lng.toFixed(4)}
        </Text>
      )}

      <TextInput
        style={styles.input}
        placeholder="Question 1 Response"
        value={responses.question1}
        onChangeText={text => setResponses({...responses, question1: text})}
      />

      <TextInput
        style={styles.input}
        placeholder="Question 2 Response"
        value={responses.question2}
        onChangeText={text => setResponses({...responses, question2: text})}
      />

      <TextInput
        style={styles.input}
        placeholder="Question 3 Response"
        value={responses.question3}
        onChangeText={text => setResponses({...responses, question3: text})}
      />

      <Button title="Save Survey Offline" onPress={handleSubmit} />
    </View>
  );
};

const styles = StyleSheet.create({
