import 'package:hive/hive.dart';
import 'package:survey_app/models/survey_response.dart';

class SurveyRepository {
  final Box<SurveyResponse> _surveyBox = Hive.box<SurveyResponse>('surveys');

  Future<void> saveSurvey(SurveyResponse survey) async {
    await _surveyBox.put(survey.id, survey);
  }

  Future<List<SurveyResponse>> getUnsyncedSurveys() async {
    return _surveyBox.values.where((survey) => !survey.isSynced).toList();
  }

  Future<void> markAsSynced(String surveyId) async {
    final survey = _surveyBox.get(surveyId);
    if (survey != null) {
      await _surveyBox.put(
        surveyId,
        survey.copyWith(isSynced: true),
      );
    }
  }

  Future<void> deleteSurvey(String surveyId) async {
    await _surveyBox.delete(surveyId);
  }

  Future<List<SurveyResponse>> getAllSurveys() async {
    return _surveyBox.values.toList();
  }
}
