import 'dart:async';
import 'package:connectivity_plus/connectivity_plus.dart';
import 'package:survey_app/models/survey_response.dart';
import 'package:survey_app/repositories/survey_repository.dart';

class SyncService {
  final SurveyRepository _repository;
  StreamSubscription? _connectivitySubscription;
  Timer? _syncTimer;
  bool _isSyncing = false;

  SyncService(this._repository);

  Future<void> initialize() async {
    // Initial sync check
    await _syncData();

    // Set up connectivity listener
    _connectivitySubscription = Connectivity().onConnectivityChanged.listen((result) {
      if (result != ConnectivityResult.none) {
        _syncData();
      }
    });

    // Periodic sync (every 5 minutes)
    _syncTimer = Timer.periodic(const Duration(minutes: 5), (timer) {
      if (!_isSyncing) {
        _syncData();
      }
    });
  }

  Future<void> _syncData() async {
    if (_isSyncing) return;
    _isSyncing = true;

    try {
      final unsyncedSurveys = await _repository.getUnsyncedSurveys();
      if (unsyncedSurveys.isEmpty) return;

      for (final survey in unsyncedSurveys) {
        try {
          // Simulate API call
          await _sendToBackend(survey);
          await _repository.markAsSynced(survey.id);
        } catch (e) {
          // Log error but continue with other surveys
          print('Sync failed for survey ${survey.id}: $e');
        }
      }
    } finally {
      _isSyncing = false;
    }
  }

  Future<void> _sendToBackend(SurveyResponse survey) async {
    // Replace with your actual API endpoint
    const apiUrl = 'https://api.example.com/surveys';

    final response = await HttpClient().post(
      Uri.parse(apiUrl),
      body: {
        'id': survey.id,
        'name': survey.name,
        'latitude': survey.latitude.toString(),
        'longitude': survey.longitude.toString(),
        'satisfaction': survey.satisfaction.toString(),
        'timestamp': survey.timestamp.toIso8601String(),
      },
    );

    if (response.statusCode != 200) {
      throw Exception('Failed to sync survey');
    }
  }

  void dispose() {
    _connectivitySubscription?.cancel();
    _syncTimer?.cancel();
  }
}

// Simple HTTP client helper
class HttpClient {
  Future<HttpResponse> post(Uri uri, {required Map<String, String> body}) async {
    // In a real app, use the http package
    // This is a simplified version for demonstration
    await Future.delayed(const Duration(milliseconds: 500)); // Simulate network delay

    // Simulate occasional failures
    if (DateTime.now().second % 5 == 0) {
      throw Exception('Simulated network error');
    }

    return HttpResponse(200);
  }
}

class HttpResponse {
  final int statusCode;
  HttpResponse(this.statusCode);
}
