// services/syncService.ts
import NetInfo from '@react-native-community/netinfo'
import axios from 'axios'
import { database } from '../database/database'
import Survey from '../models/Survey'
import Response from '../models/Response'

// Assuming your backend API is at this URL
const API_BASE_URL = 'https://your-api-endpoint.com/api'

export const syncData = async () => {
  try {
    // Check if the device is online
    const state = await NetInfo.fetch()
    if (!state.isConnected) {
      console.log('Device is offline. Skipping sync.')
      return
    }

    console.log('Device is online. Starting sync...')

    // Get unsynced surveys
    const unsyncedSurveys = await database.get('surveys').query(
      Q.where('is_synced', false)
    ).fetch()

    // Sync surveys
    for (const survey of unsyncedSurveys) {
      try {
        const response = await axios.post(`${API_BASE_URL}/surveys`, {
          title: survey.title,
          description: survey.description,
          created_at: survey.createdAt,
          updated_at: survey.updatedAt,
        })

        // Mark as synced locally
        await survey.update((record) => {
          record.isSynced = true
        })
      } catch (error) {
        console.error('Failed to sync survey:', error)
        // Optionally, you can mark it as failed or retry later
      }
    }

    // Get unsynced responses
    const unsyncedResponses = await database.get('responses').query(
      Q.where('is_synced', false)
    ).fetch()

    // Sync responses
    for (const response of unsyncedResponses) {
      try {
        const survey = await response.survey.fetch()
        const responseData = {
          survey_id: survey.id,
          data: response.data,
          created_at: response.createdAt,
          updated_at: response.updatedAt,
        }

        const apiResponse = await axios.post(`${API_BASE_URL}/responses`, responseData)

        // Mark as synced locally
        await response.update((record) => {
          record.isSynced = true
        })
      } catch (error) {
        console.error('Failed to sync response:', error)
      }
    }

    console.log('Sync completed successfully.')
  } catch (error) {
    console.error('Sync failed:', error)
  }
}

// Set up a listener for network state changes
export const setupNetworkListener = () => {
  const unsubscribe = NetInfo.addEventListener(state => {
    if (state.isConnected) {
      console.log('Network connection established. Syncing...')
      syncData()
    }
  })

  return unsubscribe
}
