## 2. Local Storage Service (`src/services/LocalStorageService.ts`)

```typescript
import AsyncStorage from '@react-native-async-storage/async-storage';

const STORAGE_KEY = 'survey_data';

export interface SurveyData {
  id: string;
  name: string;
  location: string;
  notes: string;
  timestamp: number;
  synced?: boolean;
}

export const saveSurveyData = async (data: Omit<SurveyData, 'id' | 'timestamp' | 'synced'>): Promise<void> => {
  try {
    const existingData = await getSurveyData();
    const newData: SurveyData = {
      ...data,
      id: Date.now().toString(),
      timestamp: Date.now(),
      synced: false
    };
    const updatedData = [...existingData, newData];
    await AsyncStorage.setItem(STORAGE_KEY, JSON.stringify(updatedData));
  } catch (error) {
    console.error('Error saving survey data:', error);
    throw error;
  }
};

export const getSurveyData = async (): Promise<SurveyData[]> => {
  try {
    const data = await AsyncStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (error) {
    console.error('Error getting survey data:', error);
    return [];
  }
};

export const updateSurveyAsSynced = async (id: string): Promise<void> => {
  try {
    const data = await getSurveyData();
    const updatedData = data.map(item =>
      item.id === id ? { ...item, synced: true } : item
    );
    await AsyncStorage.setItem(STORAGE_KEY, JSON.stringify(updatedData));
  } catch (error) {
    console.error('Error updating survey as synced:', error);
    throw error;
  }
};

export const clearSurveyData = async (): Promise<void> => {
  try {
    await AsyncStorage.removeItem(STORAGE_KEY);
  } catch (error) {
    console.error('Error clearing survey data:', error);
    throw error;
  }
};
```

## 3. Sync Service (`src/services/SyncService.ts`)

```typescript
import { SurveyData, getSurveyData, updateSurveyAsSynced } from './LocalStorageService';

export const syncData = async (apiUrl: string): Promise<void> => {
  try {
    const surveyData = await getSurveyData();
    const unsyncedData = surveyData.filter(item => !item.synced);

    if (unsyncedData.length === 0) {
      console.log('No data to sync');
      return;
    }

    console.log(`Syncing ${unsyncedData.length} surveys...`);

    // Simulate API call to sync data
    const response = await fetch(apiUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ surveys: unsyncedData }),
    });

    if (response.ok) {
      const responseData = await response.json();
      console.log('Sync successful:', responseData);

      // Mark all synced items as synced in local storage
      for (const item of unsyncedData) {
        await updateSurveyAsSynced(item.id);
      }
    } else {
      console.error('Failed to sync data:', response.statusText);
      throw new Error('Sync failed');
    }
  } catch (error) {
    console.error('Error syncing data:', error);
    throw error;
  }
};
```

