const App = () => {
  const [isConnected, setIsConnected] = useState<boolean | null>(null);
  const [surveyData, setSurveyData] = useState<SurveyData[]>([]);
  const [syncStatus, setSyncStatus] = useState<string>('');

  useEffect(() => {
    // Check initial connectivity
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsConnected(state.isConnected || false);
      if (state.isConnected) {
        syncPendingData();
      }
    });

    // Load existing survey data
    loadSurveyData();

    return () => unsubscribe();
  }, []);

  const loadSurveyData = async () => {
    const data = await getSurveyData();
    setSurveyData(data);
  };

  const handleSubmit = async (data: Omit<SurveyData, 'id' | 'timestamp' | 'synced'>) => {
    try {
      await saveSurveyData(data);
      setSyncStatus('Survey saved locally (offline)');
      setTimeout(() => setSyncStatus(''), 3000);
      loadSurveyData();
    } catch (error) {
      setSyncStatus('Failed to save survey');
      setTimeout(() => setSyncStatus(''), 3000);
    }
  };

  const syncPendingData = async () => {
    if (isConnected) {
      try {
        setSyncStatus('Syncing data...');
        await syncData('https://your-api-endpoint.com/survey/sync');
        setSyncStatus('Sync successful!');
        setTimeout(() => setSyncStatus(''), 3000);
        loadSurveyData();
      } catch (error) {
        setSyncStatus('Sync failed. Will retry when online.');
        setTimeout(() => setSyncStatus(''), 5000);
      }
    }
