              <Paragraph style={styles.syncStatus}>{syncStatus}</Paragraph>
            ) : (
              <Paragraph style={styles.syncStatus}>
                {pendingSurveys > 0
                  ? `${pendingSurveys} survey(s) pending sync`
                  : 'All surveys synced'}
              </Paragraph>
            )}
          </Card.Content>
        </Card>

        <Card style={styles.formCard}>
          <Card.Content>
            <Title style={styles.sectionTitle}>New Survey</Title>
            <SurveyForm onSubmit={handleSubmit} />
          </Card.Content>
        </Card>

        <Card style={styles.dataCard}>
          <Card.Content>
            <Title style={styles.sectionTitle}>Pending Surveys ({pendingSurveys})</Title>
            {surveyData.length === 0 ? (
              <Paragraph>No surveys collected yet</Paragraph>
            ) : (
