### 2. Database Setup (`src/database/db.ts`)

```typescript
import SQLite from 'react-native-sqlite-storage';
import { SurveyData } from '../types';

// Enable SQL statements logging
SQLite.enablePromise(true);

let db: SQLite.Database | null = null;

export const initDatabase = async (): Promise<void> => {
  try {
    db = await SQLite.openDatabase({
      name: 'surveys.db',
      location: 'default',
    });

    await db.executeSql(`
      CREATE TABLE IF NOT EXISTS surveys (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        location TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
        data TEXT NOT NULL,
        synced INTEGER DEFAULT 0
      )
    `);

    await db.executeSql(`
      CREATE TABLE IF NOT EXISTS sync_status (
        id INTEGER PRIMARY KEY,
        last_sync DATETIME
      )
    `);
  } catch (error) {
    console.error('Database initialization error:', error);
    throw error;
  }
};

export const saveSurvey = async (surveyData: Omit<SurveyData, 'id' | 'timestamp'>): Promise<number> => {
  if (!db) throw new Error('Database not initialized');

  const { location, data } = surveyData;
  const result = await db.executeSql(
    'INSERT INTO surveys (location, data) VALUES (?, ?)',
    [location, JSON.stringify(data)]
  );

  return result.insertId;
};

export const getAllSurveys = async (): Promise<SurveyData[]> => {
  if (!db) throw new Error('Database not initialized');

  const result = await db.executeSql('SELECT * FROM surveys ORDER BY timestamp DESC');
  return result.rows.raw().map((row: any) => ({
    id: row.id,
    location: row.location,
    timestamp: row.timestamp,
    data: JSON.parse(row.data),
    synced: row.synced === 1,
  }));
};

export const getUnsyncedSurveys = async (): Promise<SurveyData[]> => {
  if (!db) throw new Error('Database not initialized');

  const result = await db.executeSql(
    'SELECT * FROM surveys WHERE synced = 0 ORDER BY timestamp ASC'
  );
  return result.rows.raw().map((row: any) => ({
    id: row.id,
    location: row.location,
    timestamp: row.timestamp,
    data: JSON.parse(row.data),
    synced: row.synced === 1,
  }));
};

export const markSurveyAsSynced = async (id: number): Promise<void> => {
  if (!db) throw new Error('Database not initialized');

  await db.executeSql('UPDATE surveys SET synced = 1 WHERE id = ?', [id]);
};

export const getLastSyncTime = async (): Promise<Date | null> => {
  if (!db) throw new Error('Database not initialized');

  const result = await db.executeSql('SELECT last_sync FROM sync_status WHERE id = 1');
  if (result.rows.length === 0) return null;

  const lastSync = result.rows.item(0).last_sync;
  return lastSync ? new Date(lastSync) : null;
};

export const updateLastSyncTime = async (): Promise<void> => {
  if (!db) throw new Error('Database not initialized');

  const now = new Date().toISOString();
  await db.executeSql(`
    INSERT OR REPLACE INTO sync_status (id, last_sync)
    VALUES (1, ?)
  `, [now]);
};
```

