### 4. Sync Service (`src/services/syncService.ts`)

```typescript
import NetInfo from '@react-native-community/netinfo';
import {
  getUnsyncedSurveys,
  markSurveyAsSynced,
  updateLastSyncTime,
  getLastSyncTime
} from '../database/db';
import { syncSurveys } from './api';

let isSyncing = false;

export const setupSyncListener = () => {
  // Initial sync check
  checkAndSync();

  // Listen for network changes
  NetInfo.addEventListener(state => {
    if (state.isConnected && !isSyncing) {
      checkAndSync();
    }
  });
};

const checkAndSync = async () => {
  try {
    isSyncing = true;
    const lastSync = await getLastSyncTime();
    const unsyncedSurveys = await getUnsyncedSurveys();

    if (unsyncedSurveys.length > 0) {
      console.log(`Found ${unsyncedSurveys.length} unsynced surveys, syncing...`);
      await syncData();
    }
  } catch (error) {
    console.error('Sync check failed:', error);
  } finally {
    isSyncing = false;
  }
};

const syncData = async () => {
  try {
    const unsyncedSurveys = await getUnsyncedSurveys();

    if (unsyncedSurveys.length === 0) {
      console.log('No unsynced surveys to send');
      return;
    }

    // Send surveys to server
    await syncSurveys(unsyncedSurveys);

    // Mark all as synced
    for (const survey of unsyncedSurveys) {
      await markSurveyAsSynced(survey.id);
    }

    // Update last sync time
    await updateLastSyncTime();

    console.log(`Successfully synced ${unsyncedSurveys.length} surveys`);
  } catch (error) {
    console.error('Failed to sync data:', error);
    throw error;
  }
};

// Manual sync trigger
export const triggerSync = async () => {
  await checkAndSync();
};
```

