import React, { useState } from 'react';
import { View, Text, TextInput, Button, StyleSheet, Alert } from 'react-native';
import { saveSurvey } from '../database/db';
import { SurveyFormData } from '../types';
import * as Location from 'expo-location';

const SurveyForm = () => {
  const [formData, setFormData] = useState<SurveyFormData>({
    question1: '',
    question2: '',
    notes: '',
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async () => {
    try {
      setIsSubmitting(true);

      // Get current location
      let location = 'Unknown';
      try {
        const { status } = await Location.requestForegroundPermissionsAsync();
        if (status !== 'granted') {
          Alert.alert('Permission denied', 'Location permission is required for survey data');
          return;
        }

        const locationData = await Location.getCurrentPositionAsync({});
        location = `${locationData.coords.latitude},${locationData.coords.longitude}`;
      } catch (error) {
        console.error('Error getting location:', error);
      }

      // Save to local database
      await saveSurvey({
        location,
        data: formData,
      });

      Alert.alert('Success', 'Survey saved locally. It will sync when connection is available.');
      setFormData({ question1: '', question2: '', notes: '' });
    } catch (error) {
      console.error('Error saving survey:', error);
      Alert.alert('Error', 'Failed to save survey locally');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Field Survey Form</Text>

      <Text style={styles.label}>Question 1:</Text>
      <TextInput
        style={styles.input}
        value={formData.question1 as string}
        onChangeText={(text) => setFormData({ ...formData, question1: text })}
        placeholder="Enter answer"
