import { SurveyData } from '../types';

const SurveyList = () => {
  const [surveys, setSurveys] = useState<SurveyData[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchSurveys();
  }, []);

  const fetchSurveys = async () => {
    try {
      setLoading(true);
      const data = await getAllSurveys();
      setSurveys(data);
    } catch (error) {
      console.error('Error fetching surveys:', error);
    } finally {
      setLoading(false);
    }
  };

  const renderItem = ({ item }: { item: SurveyData }) => (
    <View style={[
      styles.item,
      !item.synced && styles.unsyncedItem
    ]}>
      <Text style={styles.itemTitle}>Survey #{item.id}</Text>
      <Text style={styles.itemText}>Location: {item.location}</Text>
      <Text style={styles.itemText}>Time: {new Date(item.timestamp).toLocaleString()}</Text>
      <Text style={styles.itemText}>Synced: {item.synced ? 'Yes' : 'No'}</Text>

      {!item.synced && (
        <Text style={styles.syncPending}>Pending sync</Text>
      )}
    </View>
  );

  if (loading) {
    return (
      <View style={styles.container}>
        <Text>Loading surveys...</Text>
      </View>
    );
  }

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Saved Surveys ({surveys.length})</Text>

      {surveys.length === 0 ? (
        <Text style={styles.emptyText}>No surveys saved yet</Text>
