import SQLite from 'react-native-sqlite-storage';
import { SurveyResponse } from '../types/types';

const db = SQLite.openDatabase(
  { name: 'survey.db', location: 'default' },
  () => console.log('Database opened'),
  error => console.error('Database error:', error)
);

// Initialize database
export const initDB = () => {
  db.transaction(tx => {
    tx.executeSql(
      'CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, location TEXT, notes TEXT, timestamp TEXT, isSynced INTEGER);'
    );
  });
};

// Save survey locally
export const saveSurvey = (survey: Omit<SurveyResponse, 'id'>): Promise<void> => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'INSERT INTO surveys (title, location, notes, timestamp, isSynced) VALUES (?, ?, ?, ?, ?);',
        [survey.title, survey.location, survey.notes, survey.timestamp, 0],
        (_, result) => resolve(),
        (_, error) => reject(error)
      );
    });
  });
};

// Get all unsynced surveys
export const getUnsyncedSurveys = (): Promise<SurveyResponse[]> => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys WHERE isSynced = 0;',
        [],
        (_, { rows }) => {
          const surveys: SurveyResponse[] = [];
          for (let i = 0; i < rows.length; i++) {
            surveys.push(rows.item(i));
          }
          resolve(surveys);
        },
        (_, error) => reject(error)
      );
    });
  });
};

// Mark survey as synced
export const markAsSynced = (id: number): Promise<void> => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'UPDATE surveys SET isSynced = 1 WHERE id = ?;',
        [id],
        () => resolve(),
        (_, error) => reject(error)
      );
    });
  });
};

// Get all surveys (for UI)
export const getAllSurveys = (): Promise<SurveyResponse[]> => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys ORDER BY timestamp DESC;',
        [],
        (_, { rows }) => {
          const surveys: SurveyResponse[] = [];
          for (let i = 0; i < rows.length; i++) {
            surveys.push(rows.item(i));
          }
          resolve(surveys);
        },
        (_, error) => reject(error)
      );
    });
  });
};
```

