import NetInfo from '@react-native-community/netinfo';
import { getUnsyncedSurveys, markAsSynced } from '../database/db';
import { submitSurveyToBackend } from './api';

export const startSyncService = () => {
  // Check connectivity every 30 seconds
  setInterval(async () => {
    const state = await NetInfo.fetch();
    if (state.isConnected) {
      console.log('Online! Syncing data...');
      const unsyncedSurveys = await getUnsyncedSurveys();
      for (const survey of unsyncedSurveys) {
        try {
          await submitSurveyToBackend(survey);
          await markAsSynced(survey.id);
          console.log(`Synced survey ${survey.id}`);
        } catch (error) {
          console.error('Sync failed:', error);
        }
      }
    }
  }, 30000); // Sync every 30 seconds
};
