export const markSurveysAsSynced = (ids) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'UPDATE surveys SET synced = 1 WHERE id IN (' + ids.join(',') + ')',
        [],
        (_, result) => resolve(result),
        (_, error) => reject(error)
      );
    });
  });
};
```

### 3. Sync Service (`services/sync.js`)

```javascript
import NetInfo from '@react-native-community/netinfo';
import axios from 'axios';
import { getUnsyncedSurveys, markSurveysAsSynced } from './database';

export const syncSurveys = async () => {
  try {
    const state = await NetInfo.fetch();
    if (state.isConnected) {
      console.log('Checking for pending surveys to sync...');
      const unsyncedSurveys = await getUnsyncedSurveys();

      if (unsyncedSurveys.length > 0) {
        const surveyIds = unsyncedSurveys.map(s => s.id);
        const surveyData = unsyncedSurveys.map(s => JSON.parse(s.data));

        console.log(`Syncing ${surveyData.length} surveys...`);

        // Send to server
        await axios.post('http://YOUR_SERVER_IP:3000/api/surveys', { data: surveyData });

        // Mark as synced locally
        await markSurveysAsSynced(surveyIds);
        console.log('Synced successfully');
      }
    }
  } catch (error) {
    console.error('Sync failed:', error.message);
    if (error.response) {
      console.error('Server responded with:', error.response.status);
    }
  }
};

// Check connectivity periodically
export const startSyncInterval = () => {
  // Sync immediately on app start
  syncSurveys();

  // Then sync every 30 seconds
  setInterval(syncSurveys, 30000);
};
```

