import 'package:hive/hive.dart';
import '../models/survey.dart';

class SurveyService {
  final Box<Survey> _surveyBox = Hive.box<Survey>('surveys');

  List<Survey> getAllSurveys() {
    return _surveyBox.values.toList();
  }

  Survey? getSurvey(String id) {
    return _surveyBox.get(id);
  }

  Future<void> addSurvey(Survey survey) async {
    await _surveyBox.put(survey.id, survey);
  }

  Future<void> updateSurvey(Survey survey) async {
    await _surveyBox.put(survey.id, survey);
  }

  Future<void> deleteSurvey(String id) async {
    await _surveyBox.delete(id);
  }

  Future<void> markAsSynced(String id) async {
    final survey = _surveyBox.get(id);
    if (survey != null) {
      await _surveyBox.put(
        id,
        survey.copyWith(isSynced: true),
      );
    }
  }

  List<Survey> getUnsyncedSurveys() {
    return _surveyBox.values.where((survey) => !survey.isSynced).toList();
  }
}
