### 4. `services/sync_service.dart` (Sync Logic)
```dart
import 'package:connectivity_plus/connectivity_plus.dart';
import 'package:http/http.dart' as http;
import 'dart:convert';
import '../models/survey.dart';
import 'survey_service.dart';

class SyncService {
  final SurveyService _surveyService = SurveyService();

  Future<bool> syncData() async {
    final connectivityResult = await Connectivity().checkConnectivity();
    if (connectivityResult == ConnectivityResult.none) {
      return false; // No internet connection
    }

    final unsyncedSurveys = _surveyService.getUnsyncedSurveys();
    if (unsyncedSurveys.isEmpty) {
      return true; // Nothing to sync
    }

    try {
      // Simulate API endpoint (replace with your actual backend)
      const apiUrl = 'https://your-backend-api.com/surveys';

      for (final survey in unsyncedSurveys) {
        final response = await http.post(
          Uri.parse(apiUrl),
          headers: {'Content-Type': 'application/json'},
          body: jsonEncode({
            'id': survey.id,
            'title': survey.title,
            'questions': survey.questions,
            'responses': survey.responses,
          }),
        );

        if (response.statusCode == 200) {
          await _surveyService.markAsSynced(survey.id);
        } else {
          return false; // Sync failed for at least one survey
        }
      }

      return true; // All surveys synced successfully
    } catch (e) {
      return false; // Sync failed
    }
  }
}
