import NetInfo from '@react-native-community/netinfo';
import { getUnsyncedSurveys, markSurveyAsSynced } from '../database/db';
import { syncSurveys } from './api';

export const setupSyncListener = () => {
  NetInfo.addEventListener(state => {
    if (state.isConnected) {
      syncData();
    }
  });
};

const syncData = async () => {
  try {
    const { error, surveys } = await new Promise((resolve) => {
      getUnsyncedSurveys((err, data) => {
        if (err) resolve({ error: err });
        else resolve({ surveys: data });
      });
    });

    if (error) throw error;
    if (!surveys || surveys.length === 0) return;

    await syncSurveys(surveys);

    // Mark surveys as synced
    for (const survey of surveys) {
      await new Promise((resolve) => {
        markSurveyAsSynced(survey.id, (err) => {
          if (err) console.error('Failed to mark survey as synced', err);
          resolve(undefined);
        });
      });
    }
  } catch (error) {
    console.error('Sync failed:', error);
  }
};
```

