// server.js
const express = require('express');
const bodyParser = require('body-parser');
const { Pool } = require('pg'); // Using PostgreSQL

const app = express();
app.use(bodyParser.json());

const pool = new Pool({
  user: 'postgres',
  host: 'localhost',
  database: 'survey_db',
  password: 'password',
  port: 5432,
});

// Create table if not exists
pool.query(`
  CREATE TABLE IF NOT EXISTS surveys (
    id SERIAL PRIMARY KEY,
    data JSONB NOT NULL,
    synced BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMP DEFAULT NOW()
  );
`);

// API to submit a survey
app.post('/api/surveys', async (req, res) => {
  const { data } = req.body;
  try {
    const result = await pool.query(
      'INSERT INTO surveys (data) VALUES ($1) RETURNING *',
      [data]
    );
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// API to get pending surveys (for sync)
app.get('/api/surveys/pending', async (req, res) => {
  try {
    const result = await pool.query(
      'SELECT * FROM surveys WHERE synced = FALSE'
    );
    res.json(result.rows);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// API to mark surveys as synced
app.post('/api/surveys/sync', async (req, res) => {
  const { ids } = req.body;
  try {
    await pool.query(
      'UPDATE surveys SET synced = TRUE WHERE id = ANY($1)',
      [ids]
    );
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

