export const addSurvey = async (surveyData: { title: string; description: string }) => {
  try {
    const response = await localDB.post({
      ...surveyData,
      createdAt: new Date().toISOString(),
      synced: false, // Track sync status
    });
    console.log('📝 Survey saved locally:', response.id);
    await syncSurveys(); // Attempt sync immediately
    return response;
  } catch (error) {
    console.error('❌ Error adding survey:', error);
    throw error;
  }
};

// Fetch all surveys (synced + unsynced)
export const getSurveys = async () => {
  try {
    const response = await localDB.allDocs({ include_docs: true });
    return response.rows.map((row: any) => row.doc);
  } catch (error) {
    console.error('❌ Error fetching surveys:', error);
    throw error;
  }
};

// Listen for network changes
NetInfo.addEventListener((state) => {
  if (state.isConnected) {
    syncSurveys();
  }
});
