### **5. `SyncStatus.tsx` (Sync Indicator)**
```tsx
import React, { useEffect, useState } from 'react';
import { View, StyleSheet } from 'react-native';
import { Text } from 'react-native-paper';
import NetInfo from '@react-native-community/netinfo';

const SyncStatus = () => {
  const [isOnline, setIsOnline] = useState<boolean | null>(null);
  const [syncStatus, setSyncStatus] = useState<string>('');

  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsOnline(state.isConnected);
      if (state.isConnected) syncData();
    });

    NetInfo.fetch().then(state => setIsOnline(state.isConnected));
    return () => unsubscribe();
  }, []);

  const syncData = async () => {
    setSyncStatus('Syncing...');
    try {
      const db = await getDB();
      const remoteDB = new (require('pouchdb-react-native'))(
        'http://admin:password@localhost:5984/survey_app',
        { skip_setup: true }
      );

      await db.replicate.to(remoteDB);
      await db.replicate.from(remoteDB);
      setSyncStatus('Synced successfully!');
    } catch (error) {
      console.error('Sync error:', error);
      setSyncStatus('Sync failed');
    }
  };

  const getDB = async () => {
    const PouchDB = require('pouchdb-react-native');
    const SQLite = require('react-native-sqlite-storage');
    PouchDB.plugin(require('pouchdb-adapter-react-native-sqlite'));
    return new PouchDB('survey_app', { adapter: 'react-native-sqlite' });
  };

  return (
    <View style={styles.container}>
      <Text style={styles.status}>
        {isOnline === null ? 'Checking connection...' : isOnline ? 'Online' : 'Offline'}
      </Text>
      <Text style={styles.syncStatus}>{syncStatus}</Text>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    position: 'absolute',
    bottom: 0,
    left: 0,
    right: 0,
    backgroundColor: 'rgba(0,0,0,0.1)',
    padding: 10,
    alignItems: 'center',
  },
  status: { fontWeight: 'bold' },
  syncStatus: { fontSize: 12 },
});

export default SyncStatus;
```

