```dart
import 'package:flutter/material.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:cloud_firestore/cloud_firestore.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp();
  runApp(const MyApp());
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Field Survey App',
      theme: ThemeData(primarySwatch: Colors.blue),
      home: const SurveyScreen(),
    );
  }
}

class SurveyScreen extends StatefulWidget {
  const SurveyScreen({super.key});

  @override
  State<SurveyScreen> createState() => _SurveyScreenState();
}

class _SurveyScreenState extends State<SurveyScreen> {
  final _formKey = GlobalKey<FormState>();
  final TextEditingController _locationController = TextEditingController();
  final TextEditingController _notesController = TextEditingController();

  Future<void> _submitSurvey() async {
    if (_formKey.currentState!.validate()) {
      // Add survey to Firestore (offline persistence enabled by default)
      await FirebaseFirestore.instance.collection('surveys').add({
        'location': _locationController.text,
        'notes': _notesController.text,
        'timestamp': FieldValue.serverTimestamp(),
      });
      _locationController.clear();
      _notesController.clear();
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Field Survey')),
      body: Column(
        children: [
          // List of surveys (auto-updates when synced)
          Expanded(
            child: StreamBuilder<QuerySnapshot>(
              stream: FirebaseFirestore.instance
                  .collection('surveys')
                  .orderBy('timestamp', descending: true)
                  .snapshots(),
              builder: (context, snapshot) {
                if (snapshot.hasError) {
                  return Center(child: Text('Error: ${snapshot.error}'));
                }
                if (snapshot.connectionState == ConnectionState.waiting) {
                  return const Center(child: CircularProgressIndicator());
                }
                return ListView(
                  children: snapshot.data!.docs.map((DocumentSnapshot document) {
                    final data = document.data() as Map<String, dynamic>;
                    return ListTile(
                      title: Text(data['location'] ?? 'No location'),
                      subtitle: Text(data['notes'] ?? 'No notes'),
                      trailing: Text(
                        data['timestamp']?.toDate().toString() ?? 'No timestamp',
                      ),
                    );
                  }).toList(),
                );
              },
            ),
          ),
          // Survey form
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Form(
              key: _formKey,
              child: Column(
                children: [
                  TextFormField(
                    controller: _locationController,
                    decoration: const InputDecoration(labelText: 'Location'),
                    validator: (value) =>
                        value!.isEmpty ? 'Enter location' : null,
                  ),
                  TextFormField(
                    controller: _notesController,
                    decoration: const InputDecoration(labelText: 'Notes'),
                    validator: (value) =>
                        value!.isEmpty ? 'Enter notes' : null,
                  ),
                  const SizedBox(height: 16),
                  ElevatedButton(
                    onPressed: _submitSurvey,
                    child: const Text('Submit Survey'),
                  ),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }
}
```

