import 'package:hive/hive.dart';
import 'package:uuid/uuid.dart';

part 'survey.g.dart';

@HiveType(typeId: 0)
class Survey {
  @HiveField(0)
  final String id;

  @HiveField(1)
  final String name;

  @HiveField(2)
  final Map<String, dynamic> responses;

  @HiveField(3)
  final DateTime timestamp;

  @HiveField(4)
  final bool isSynced;

  Survey({
    String? id,
    required this.name,
    required this.responses,
    required this.timestamp,
    this.isSynced = false,
  }) : id = id ?? const Uuid().v4();

  Survey copyWith({
    String? id,
    String? name,
    Map<String, dynamic>? responses,
    DateTime? timestamp,
    bool? isSynced,
  }) {
    return Survey(
      id: id ?? this.id,
      name: name ?? this.name,
      responses: responses ?? this.responses,
      timestamp: timestamp ?? this.timestamp,
      isSynced: isSynced ?? this.isSynced,
    );
  }
}
