import 'package:hive_flutter/hive_flutter.dart';
import '../models/survey.dart';

class LocalStorageService {
  static const String _boxName = 'surveys';
  late Box<Survey> _box;

  Future<void> init() async {
    await Hive.initFlutter();
    Hive.registerAdapter(SurveyAdapter());
    _box = await Hive.openBox<Survey>(_boxName);
  }

  Future<void> saveSurvey(Survey survey) async {
    await _box.put(survey.id, survey);
  }

  List<Survey> getUnsyncedSurveys() {
    return _box.values.where((survey) => !survey.isSynced).toList();
  }

  Future<void> markAsSynced(String id) async {
    final survey = _box.get(id);
    if (survey != null) {
      await _box.put(
        id,
        survey.copyWith(isSynced: true),
      );
    }
  }

  List<Survey> getAllSurveys() {
    return _box.values.toList();
  }
}
