import PouchDB from 'pouchdb-react-native';
import NetInfo from '@react-native-community/netinfo';
import axios from 'axios';

// Initialize local PouchDB
const localDB = new PouchDB('surveys');

// Remote CouchDB URL (or mock backend)
const remoteDB = new PouchDB('http://localhost:5984/surveys', {
  skip_setup: true,
});

// Sync function
export const syncSurveys = async () => {
  try {
    const netInfo = await NetInfo.fetch();
    if (netInfo.isConnected) {
      console.log('Online: Syncing data...');
      await localDB.sync(remoteDB, {
        live: true,
        retry: true,
      });
      console.log('Sync successful');
    } else {
      console.log('Offline: Data will sync when online');
    }
  } catch (error) {
    console.error('Sync error:', error);
  }
};

// Add a new survey
export const addSurvey = async (surveyData: any) => {
  try {
    const response = await localDB.post(surveyData);
    console.log('Survey added locally:', response);
    await syncSurveys(); // Attempt to sync immediately
    return response;
  } catch (error) {
    console.error('Error adding survey:', error);
    throw error;
  }
};

// Get all surveys
