#### 2. `services/database_helper.dart`
```dart
import 'package:sqflite/sqflite.dart';
import 'package:path/path.dart';
import '../models/survey.dart';

class DatabaseHelper {
  static final DatabaseHelper instance = DatabaseHelper._init();
  static Database? _database;

  DatabaseHelper._init();

  Future<Database> get database async {
    if (_database != null) return _database!;
    _database = await _initDB('surveys.db');
    return _database!;
  }

  Future<Database> _initDB(String filePath) async {
    final dbPath = await getDatabasesPath();
    final path = join(dbPath, filePath);

    return await openDatabase(path, version: 1, onCreate: _createDB);
  }

  Future _createDB(Database db, int version) async {
    await db.execute('''
      CREATE TABLE surveys (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        location TEXT NOT NULL,
        notes TEXT NOT NULL,
        date TEXT NOT NULL
      )
    ''');
  }

  Future<int> insertSurvey(Survey survey) async {
    final db = await instance.database;
    return await db.insert('surveys', survey.toMap());
  }

  Future<List<Survey>> getSurveys() async {
    final db = await instance.database;
    final List<Map<String, dynamic>> maps = await db.query('surveys');
    return List.generate(maps.length, (i) {
      return Survey.fromMap(maps[i]);
    });
  }

  Future<int> updateSurvey(Survey survey) async {
    final db = await instance.database;
    return await db.update(
      'surveys',
      survey.toMap(),
      where: 'id = ?',
      whereArgs: [survey.id],
    );
  }

  Future<int> deleteSurvey(int id) async {
    final db = await instance.database;
    return await db.delete(
      'surveys',
      where: 'id = ?',
      whereArgs: [id],
    );
  }

  Future close() async {
    final db = await instance.database;
    db.close();
  }
}
```

#### 3. `services/sync_service.dart`
```dart
import 'package:connectivity_plus/connectivity_plus.dart';
import 'package:http/http.dart' as http;
import '../models/survey.dart';
import 'database_helper.dart';

class SyncService {
  final DatabaseHelper dbHelper = DatabaseHelper.instance;
  final String apiUrl = 'https://your-api-endpoint.com/surveys'; // Replace with your API endpoint

  Future<bool> isConnected() async {
    final connectivityResult = await Connectivity().checkConnectivity();
    return connectivityResult != ConnectivityResult.none;
  }

  Future<void> syncData() async {
    if (!await isConnected()) {
      print('No internet connection. Cannot sync.');
      return;
    }

    try {
      final surveys = await dbHelper.getSurveys();
      for (var survey in surveys) {
        final response = await http.post(
          Uri.parse(apiUrl),
          body: {
            'location': survey.location,
            'notes': survey.notes,
            'date': survey.date.toIso8601String(),
          },
        );

        if (response.statusCode == 200 || response.statusCode == 201) {
          // On successful sync, delete the local record
          await dbHelper.deleteSurvey(survey.id!);
          print('Synced survey with ID: ${survey.id}');
        } else {
          print('Failed to sync survey with ID: ${survey.id}');
        }
      }
    } catch (e) {
      print('Error during sync: $e');
    }
  }
}
```

