```dart
import 'package:hive_flutter/hive_flutter.dart';
import 'survey.dart';

class LocalStorageService {
  static const String _boxName = 'surveys';

  Future<void> init() async {
    await Hive.initFlutter();
    Hive.registerAdapter(SurveyAdapter());
    await Hive.openBox<Survey>(_boxName);
  }

  Box<Survey> get _box => Hive.box<Survey>(_boxName);

  Future<void> saveSurvey(Survey survey) async {
    await _box.add(survey);
  }

  List<Survey> getUnsyncedSurveys() {
    return _box.values.where((survey) => !survey.isSynced).toList();
  }

  Future<void> markAsSynced(String id) async {
    final survey = _box.values.firstWhere((s) => s.id == id);
    survey.isSynced = true;
    await survey.save();
  }
}
```

#### 4. Network Service:
```dart
import 'package:connectivity_plus/connectivity_plus.dart';
import 'package:http/http.dart' as http;
import 'dart:convert';
import 'survey.dart';

class NetworkService {
  static const String _apiUrl = 'https://your-backend-api.com/surveys';

  Future<bool> hasInternet() async {
    final connectivityResult = await Connectivity().checkConnectivity();
    return connectivityResult != ConnectivityResult.none;
  }

  Future<void> syncSurveys(List<Survey> surveys) async {
    for (final survey in surveys) {
      try {
        final response = await http.post(
          Uri.parse(_apiUrl),
          headers: {'Content-Type': 'application/json'},
          body: jsonEncode({
            'id': survey.id,
            'name': survey.name,
            'responses': survey.responses,
            'timestamp': survey.timestamp.toIso8601String(),
          }),
        );

        if (response.statusCode == 200) {
          // Mark as synced in local storage
          await LocalStorageService().markAsSynced(survey.id);
        } else {
          throw Exception('Failed to sync survey');
        }
      } catch (e) {
        print('Sync failed for survey ${survey.id}: $e');
      }
    }
  }
}
```

