  Future<void> _submitForm() async {
    if (_formKey.currentState!.validate()) {
      final survey = Survey(
        id: DateTime.now().millisecondsSinceEpoch.toString(),
        name: _nameController.text,
        responses: {
          'textResponse': _textResponseController.text,
          'numberResponse': int.tryParse(_numberResponseController.text) ?? 0,
          'multipleChoice': _selectedOption,
        },
        timestamp: DateTime.now(),
        isSynced: false,
      );

      await LocalStorageService().saveSurvey(survey);
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Survey saved offline')),
      );
      _formKey.currentState!.reset();
    }
  }

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.all(16.0),
      child: Form(
        key: _formKey,
        child: Column(
          children: [
            TextFormField(
              controller: _nameController,
              decoration: InputDecoration(labelText: 'Survey Name'),
              validator: (value) {
                if (value == null || value.isEmpty) {
                  return 'Please enter a survey name';
                }
                return null;
              },
            ),
            TextFormField(
              controller: _textResponseController,
              decoration: InputDecoration(labelText: 'Text Response'),
            ),
            TextFormField(
              controller: _numberResponseController,
              decoration: InputDecoration(labelText: 'Number Response'),
              keyboardType: TextInputType.number,
            ),
            DropdownButtonFormField<String>(
              value: _selectedOption,
              decoration: InputDecoration(labelText: 'Multiple Choice'),
              items: ['Option 1', 'Option 2', 'Option 3'].map((String value) {
                return DropdownMenuItem<String>(
                  value: value,
                  child: Text(value),
                );
              }).toList(),
              onChanged: (newValue) {
                setState(() {
                  _selectedOption = newValue;
                });
              },
              validator: (value) {
                if (value == null) {
                  return 'Please select an option';
                }
                return null;
              },
            ),
            SizedBox(height: 20),
            ElevatedButton(
              onPressed: _submitForm,
              child: Text('Submit Survey'),
            ),
            SizedBox(height: 20),
            ElevatedButton(
              onPressed: () async {
                final hasInternet = await NetworkService().hasInternet();
                if (hasInternet) {
                  final unsyncedSurveys = LocalStorageService().getUnsyncedSurveys();
                  if (unsyncedSurveys.isNotEmpty) {
                    await NetworkService().syncSurveys(unsyncedSurveys);
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(content: Text('Surveys synced successfully')),
