### Payment Service (`services/paymentService.js`)

```javascript
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
const Purchase = require('../models/Purchase');
const User = require('../models/User');
const NotificationService = require('./notificationService');

class PaymentService {
  static async createPaymentIntent(userId, amount, currency = 'usd') {
    const user = await User.findById(userId);
    if (!user) throw new Error('User not found');

    const paymentIntent = await stripe.paymentIntents.create({
      amount: amount * 100, // Convert to cents
      currency,
      metadata: { userId: userId.toString() }
    });

    // Create purchase record
    const purchase = new Purchase({
      user: userId,
      productId: 'tokens',
      amount,
      currency,
      paymentIntentId: paymentIntent.id
    });

    await purchase.save();

    return {
      clientSecret: paymentIntent.client_secret,
      purchaseId: purchase._id
    };
  }

  static async handlePaymentSuccess(paymentIntentId) {
    const purchase = await Purchase.findOne({ paymentIntentId });
    if (!purchase) throw new Error('Purchase not found');

    // Update user tokens
    await User.findByIdAndUpdate(purchase.user, {
      $inc: { tokens: purchase.amount * 10 } // 10 tokens per dollar
    });

    // Update purchase status
    purchase.status = 'completed';
    await purchase.save();

    // Create notification
    await NotificationService.createNotification(
      purchase.user,
      'payment',
      `You received ${purchase.amount * 10} tokens!`,
      { tokensAdded: purchase.amount * 10 }
    );

    return purchase;
  }

  static async handlePaymentFailure(paymentIntentId) {
    const purchase = await Purchase.findOne({ paymentIntentId });
    if (!purchase) throw new Error('Purchase not found');

    purchase.status = 'failed';
    await purchase.save();

    // Create notification
    await NotificationService.createNotification(
      purchase.user,
      'payment',
      'Your payment failed. Please try again.',
      { error: 'Payment failed' }
    );

    return purchase;
  }
}

module.exports = PaymentService;
```

