const express = require('express');
const router = express.Router();
const Message = require('../models/Message');
const User = require('../models/User');
const Notification = require('../models/Notification');

// Send message
router.post('/', async (req, res) => {
  try {
    const { recipientId, content, isPremium } = req.body;
    const senderId = req.user.id;

    // Check if sender has enough credits for premium messages
    if (isPremium) {
      const sender = await User.findById(senderId);
      if (sender.credits < 10) {
        return res.status(400).json({ error: 'Insufficient credits' });
      }
    }

    const message = new Message({
      sender: senderId,
      recipient: recipientId,
      content,
      isPremium
    });

    await message.save();

    // Deduct credits if premium
    if (isPremium) {
      await User.findByIdAndUpdate(senderId, { $inc: { credits: -10 } });
    }

    // Create notification for recipient
    const notification = new Notification({
      user: recipientId,
      type: 'message',
      message: `New message from ${req.user.username}`
    });
    await notification.save();

    res.json({ message: 'Message sent successfully' });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

// Get messages for user
router.get('/', async (req, res) => {
  try {
    const messages = await Message.find({
      $or: [{ sender: req.user.id }, { recipient: req.user.id }]
    }).populate('sender', 'username').sort({ timestamp: -1 });

    res.json(messages);
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

module.exports = router;
