}

// Socket.io connection
let socket = null;

function initSocket() {
  socket = io({
    auth: {
      token: localStorage.getItem('token')
    }
  });

  socket.on('connect', () => {
    console.log('Connected to socket server');
    socket.emit('join', currentUser.id);
  });

  socket.on('receiveMessage', (data) => {
    console.log('New message received:', data);
    loadMessages();
    showNotification(`New message from ${data.senderUsername}`);
  });
}

// Message functions
async function sendMessage() {
  const recipient = recipientInput.value.trim();
  const content = messageContent.value.trim();
  const isPremium = premiumMessage.checked;

  if (!recipient || !content) {
    alert('Please fill in all fields');
    return;
  }

  try {
    const response = await fetch('/api/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${localStorage.getItem('token')}`
      },
      body: JSON.stringify({
        recipientId: recipient, // In a real app, this would be the user ID
        content,
        isPremium
      })
    });

    const data = await response.json();
    if (response.ok) {
      messageContent.value = '';
      recipientInput.value = '';
      premiumMessage.checked = false;
      loadMessages();
    } else {
      alert(data.error || 'Failed to send message');
    }
  } catch (err) {
    console.error('Send message error:', err);
    alert('Failed to send message');
  }
}

async function loadMessages() {
  try {
    const response = await fetch('/api/messages', {
      headers: {
        'Authorization': `Bearer ${localStorage.getItem('token')}`
      }
    });

    const messages = await response.json();
    if (response.ok) {
      messagesList.innerHTML = messages.map(msg => `
        <div class="message ${msg.isPremium ? 'premium-message' : ''}">
          <strong>${msg.sender.username}:</strong> ${msg.content}
          <small>${new Date(msg.timestamp).toLocaleString()}</small>
        </div>
      `).join('');
    }
  } catch (err) {
    console.error('Load messages error:', err);
  }
}

// Notification functions
async function loadNotifications() {
  try {
    const response = await fetch('/api/notifications', {
      headers: {
        'Authorization': `Bearer ${localStorage.getItem('token')}`
      }
    });

    const notifications = await response.json();
    if (response.ok) {
      notificationsList.innerHTML = notifications.map(notification => `
        <div class="notification ${!notification.read ? 'unread' : ''}">
          ${notification.message}
          <small>${new Date(notification.timestamp).toLocaleString()}</small>
        </div>
      `).join('');
    }
  } catch (err) {
    console.error('Load notifications error:', err);
