// App state
let currentUserId = null;
let currentUserEmail = null;
let socket = null;
let stripe = null;
let elements = null;

// DOM elements
const authSection = document.getElementById('authSection');
const appSection = document.getElementById('appSection');
const loginBtn = document.getElementById('loginBtn');
