    paymentModal.style.display = 'none';
  }
});

// Handle login
async function handleLogin() {
  const email = loginEmail.value;
  const password = loginPassword.value;

  try {
    const res = await fetch('http://localhost:3000/api/auth/login', {
      method: 'POST',
