          ${user.email}
        </li>
      `).join('');

      // Add click handlers
      document.querySelectorAll('#userList li').forEach(li => {
        li.addEventListener('click', () => {
          const userId = li.getAttribute('data-id');
          const userEmail = li.getAttribute('data-email');
          loadMessages(userId);
        });
      });
    }
  } catch (err) {
    console.error('Error loading users:', err);
  }
}

// Load messages between current user and selected user
async function loadMessages(userId = null) {
  const receiverId = userId || document.querySelector('#userList li.active')?.getAttribute('data-id');
  if (!receiverId) return;

  try {
    const res = await fetch(`http://localhost:3000/api/messages/${receiverId}`, {
      headers: { 'x-auth-token': localStorage.getItem('token') }
    });
    const messages = await res.json();
    if (res.ok) {
      messagesContainer.innerHTML = messages.map(msg => {
        const isSent = msg.senderId === currentUserId;
        return `
          <div class="message ${isSent ? 'sent' : 'received'}">
            ${msg.text}
          </div>
        `;
      }).join('');
      messagesContainer.scrollTop = messagesContainer.scrollHeight;
    }
  } catch (err) {
    console.error('Error loading messages:', err);
  }
}

// Send a message
async function sendMessage() {
  const text = messageInput.value.trim();
  const receiverId = document.querySelector('#userList li.active')?.getAttribute('data-id');
  if (!text || !receiverId) return;

  try {
    const res = await fetch('http://localhost:3000/api/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-auth-token': localStorage.getItem('token')
      },
      body: JSON.stringify({ receiverId, text })
    });

    if (res.ok) {
      const message = await res.json();
      displayMessage(message, 'sent');
      socket.emit('sendMessage', {
        senderId: currentUserId,
        receiverId,
        text
      });
      messageInput.value = '';
    }
  } catch (err) {
    console.error('Error sending message:', err);
  }
}

// Display a message in the chat
function displayMessage(message, type) {
  const div = document.createElement('div');
  div.className = `message ${type}`;
  div.textContent = message.text;
  messagesContainer.appendChild(div);
  messagesContainer.scrollTop = messagesContainer.scrollHeight;
}

// Handle payment with Stripe
async function handlePayment() {
  const { error, paymentMethod } = await stripe.createPaymentMethod({
    type: 'card',
    card: card,
  });

  if (error) {
    paymentError.textContent = error.message;
    return;
  }

  const amount = 1000; // $10.00 in cents

  try {
    const res = await fetch('http://localhost:3000/api/payments/create-payment-intent', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-auth-token': localStorage.getItem('token')
      },
      body: JSON.stringify({ amount })
    });

    const { clientSecret } = await res.json();
    if (res.ok) {
      const { error: stripeError, paymentIntent } = await stripe.confirmCardPayment(clientSecret, {
        payment_method: paymentMethod.id
      });

      if (stripeError) {
        paymentError.textContent = stripeError.message;
      } else if (paymentIntent.status === 'succeeded') {
        alert('Payment successful! Funds added to your balance.');
        paymentModal.style.display = 'none';
        userBalance.textContent = (parseFloat(userBalance.textContent) + 10).toFixed(2);
        card.clear();
      }
    }
  } catch (err) {
    console.error('Payment error:', err);
    paymentError.textContent = 'Payment failed. Please try again.';
  }
}
