## 🔧 Backend Implementation

### 1. Real-Time Messaging Channel (`lib/social_messaging_app_web/channels/message_channel.ex`)

```elixir
defmodule SocialMessagingAppWeb.MessageChannel do
  use SocialMessagingAppWeb, :channel

  def join("message:" <> user_id, _params, socket) do
    {:ok, socket}
  end

  def handle_in("new_message", %{"content" => content}, socket) do
    user_id = socket.assigns.user_id

    message = SocialMessagingApp.Messaging.create_message(%{
      user_id: user_id,
      content: content
    })

    # Broadcast to all subscribers
    broadcast!(socket, "new_message", %{message: message})

    # Create notification
    SocialMessagingApp.Notifications.create_notification(%{
      user_id: user_id,
      message_id: message.id,
      read: false
    })

    {:noreply, socket}
  end
end
```

### 2. Notifications Channel (`lib/social_messaging_app_web/channels/notification_channel.ex`)

```elixir
defmodule SocialMessagingAppWeb.NotificationChannel do
  use SocialMessagingAppWeb, :channel

  def join("notification:" <> user_id, _params, socket) do
    {:ok, socket}
  end

  def handle_in("mark_as_read", %{"notification_id" => notification_id}, socket) do
    notification = SocialMessagingApp.Notifications.get_notification!(notification_id)
    SocialMessagingApp.Notifications.mark_as_read(notification)

    {:noreply, socket}
  end
end
```

### 3. Subscription Controller (`lib/social_messaging_app_web/controllers/subscription_controller.ex`)

```elixir
defmodule SocialMessagingAppWeb.SubscriptionController do
  use SocialMessagingAppWeb, :controller
  alias SocialMessagingApp.Monetization

  def create(conn, %{"plan" => plan}) do
    user = conn.assigns.current_user

    subscription = Monetization.create_subscription(%{
      user_id: user.id,
      plan: plan,
      status: "active"
    })

    conn
    |> put_status(:created)
    |> put_view(SocialMessagingAppWeb.SubscriptionView)
    |> render("show.json", subscription: subscription)
  end
end
```

### 4. Real-Time Feature Setup (`lib/social_messaging_app_web/channels/user_socket.ex`)

```elixir
defmodule SocialMessagingAppWeb.UserSocket do
  use Phoenix.Socket

  channel "message:*", SocialMessagingAppWeb.MessageChannel
  channel "notification:*", SocialMessagingAppWeb.NotificationChannel

  def connect(_params, socket, _connect_info) do
    {:ok, socket}
  end

  def id(_socket), do: nil
end
