### 1. Messaging Component (`src/components/Messaging.tsx`)

```tsx
import React, { useState, useEffect } from 'react';
import { Socket } from 'phoenix';

const Messaging: React.FC = () => {
  const [messages, setMessages] = useState<string[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [socket, setSocket] = useState<Socket | null>(null);

  useEffect(() => {
    const newSocket = new Socket("ws://localhost:4000/socket", {
      params: { token: localStorage.getItem('token') }
    });
    newSocket.connect();
    setSocket(newSocket);

    const channel = newSocket.channel(`message:${localStorage.getItem('userId')}`, {});
    channel.join()
      .receive("ok", () => console.log("Joined message channel"))
      .receive("error", (resp) => console.log("Unable to join", resp));

    channel.on("new_message", (payload) => {
      setMessages((prev) => [...prev, payload.message.content]);
    });

    return () => {
      channel.leave();
      newSocket.disconnect();
    };
  }, []);

  const sendMessage = () => {
    if (socket && newMessage.trim()) {
      const channel = socket.channel(`message:${localStorage.getItem('userId')}`, {});
      channel.push("new_message", { content: newMessage })
        .receive("ok", () => setNewMessage(''));
    }
  };

  return (
    <div className="messaging">
      <h2>💬 Messages</h2>
      <div className="message-list">
        {messages.map((msg, i) => (
          <div key={i} className="message">{msg}</div>
        ))}
      </div>
      <input
        type="text"
        value={newMessage}
        onChange={(e) => setNewMessage(e.target.value)}
        placeholder="Type a message..."
      />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
};

export default Messaging;
```

### 2. Notifications Component (`src/components/Notifications.tsx`)

```tsx
import React, { useState, useEffect } from 'react';
import { Socket } from 'phoenix';

const Notifications: React.FC = () => {
  const [notifications, setNotifications] = useState<any[]>([]);
  const [socket, setSocket] = useState<Socket | null>(null);

  useEffect(() => {
    const newSocket = new Socket("ws://localhost:4000/socket", {
      params: { token: localStorage.getItem('token') }
    });
    newSocket.connect();
    setSocket(newSocket);

    const channel = newSocket.channel(`notification:${localStorage.getItem('userId')}`, {});
    channel.join()
      .receive("ok", () => console.log("Joined notification channel"))
      .receive("error", (resp) => console.log("Unable to join", resp));

    channel.on("new_notification", (payload) => {
      setNotifications((prev) => [...prev, payload.notification]);
    });

    return () => {
      channel.leave();
      newSocket.disconnect();
    };
  }, []);

  const markAsRead = (id: string) => {
    if (socket) {
      const channel = socket.channel(`notification:${localStorage.getItem('userId')}`, {});
      channel.push("mark_as_read", { notification_id: id });
      setNotifications(notifications.filter(n => n.id !== id));
    }
  };

  return (
    <div className="notifications">
      <h2>🔔 Notifications</h2>
      <ul>
        {notifications.map((n) => (
          <li key={n.id}>
            {n.message}
            <button onClick={() => markAsRead(n.id)}>Mark as read</button>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default Notifications;
```

