## 🚀 Backend Implementation (Node.js)

### 1. Set up the backend server

```bash
mkdir social-messaging-app
cd social-messaging-app
mkdir server
cd server
npm init -y
npm install express socket.io cors jsonwebtoken
```

### 2. `server/server.js`

```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const cors = require('cors');
const jwt = require('jsonwebtoken');

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

// Mock database
let users = [];
let messages = [];
let premiumUsers = new Set(); // For demo monetization

// JWT secret (in production, use environment variables)
const JWT_SECRET = 'your_jwt_secret_here_12345';

// Authentication middleware for Socket.io
const authenticate = (socket, next) => {
  const token = socket.handshake.auth.token;
  if (!token) {
    return next(new Error('Authentication error: No token provided'));
  }
  jwt.verify(token, JWT_SECRET, (err, decoded) => {
    if (err) {
      return next(new Error('Authentication error: Invalid token'));
    }
    socket.user = decoded;
    next();
  });
};

// Socket.io connection with authentication
io.use(authenticate).on('connection', (socket) => {
  console.log(`✅ User connected: ${socket.user.username}`);

  // Send previous messages to the user
  socket.emit('previous_messages', messages);

  // Handle new messages
  socket.on('send_message', (message) => {
    const newMessage = {
      id: messages.length + 1,
      sender: socket.user.username,
      text: message.text,
      timestamp: new Date().toISOString(),
      isPremium: premiumUsers.has(socket.user.username)
    };
    messages.push(newMessage);
    io.emit('receive_message', newMessage);

    // Notify all users about the new message
    io.emit('notification', {
      type: 'new_message',
      message: `New message from ${socket.user.username}`,
      timestamp: new Date().toISOString()
    });
  });

  socket.on('disconnect', () => {
    console.log(`❌ User disconnected: ${socket.user.username}`);
  });
});

// REST API routes
app.post('/api/login', (req, res) => {
  const { username, password } = req.body;

  // In a real app, validate credentials against a database
  // For demo, we'll just create a new user if not exists
  if (!users.some(u => u.username === username)) {
    users.push({ id: users.length + 1, username });
  }

  const token = jwt.sign({ id: users.length, username }, JWT_SECRET, { expiresIn: '1h' });
  res.json({ token });
});

app.post('/api/premium', (req, res) => {
  const { username } = req.body;
  premiumUsers.add(username);
  res.json({
    success: true,
    message: 'Premium status granted!',
    premiumFeatures: [
      "Priority message delivery",
      "Custom emoji support",
      "Ad-free experience",
      "Early access to new features"
    ]
  });
});

app.get('/api/premium/status', (req, res) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });

  jwt.verify(token, JWT_SECRET, (err, decoded) => {
    if (err) return res.status(401).json({ error: 'Unauthorized' });

    const isPremium = premiumUsers.has(decoded.username);
    res.json({ isPremium });
  });
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'healthy', timestamp: new Date().toISOString() });
});

const PORT = 5000;
server.listen(PORT, () => {
  console.log(`🚀 Server running on http://localhost:${PORT}`);
});
```

