```javascript
import React, { useState, useEffect } from 'react';
import io from 'socket.io-client';
import axios from 'axios';
import './App.css';

const socket = io('http://localhost:5000', {
  auth: { token: localStorage.getItem('token') }
});

function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [messages, setMessages] = useState([]);
  const [messageInput, setMessageInput] = useState('');
  const [notifications, setNotifications] = useState([]);
  const [isPremium, setIsPremium] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [premiumFeatures, setPremiumFeatures] = useState([]);

  useEffect(() => {
    // Check if user is logged in
    const token = localStorage.getItem('token');
    if (token) {
      setIsLoggedIn(true);
      // Decode token to get username
      const decoded = JSON.parse(atob(token.split('.')[1]));
      setUsername(decoded.username);
    }

    // Listen for messages
    socket.on('receive_message', (message) => {
      setMessages(prev => [...prev, message]);
    });

    // Listen for notifications
    socket.on('notification', (notification) => {
      setNotifications(prev => [...prev, notification]);
      // Auto-dismiss after 5 seconds
      setTimeout(() => {
        setNotifications(prev => prev.filter(n => n.timestamp !== notification.timestamp));
      }, 5000);
    });

    // Check premium status
    if (token) {
      checkPremiumStatus(token);
    }

    return () => {
      socket.off('receive_message');
      socket.off('notification');
    };
  }, []);

  const checkPremiumStatus = async (token) => {
    try {
      const res = await axios.get('http://localhost:5000/api/premium/status', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setIsPremium(res.data.isPremium);
    } catch (err) {
      console.error('Failed to check premium status:', err);
    }
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    try {
      const res = await axios.post('http://localhost:5000/api/login', {
        username,
        password
      });
      localStorage.setItem('token', res.data.token);
      setIsLoggedIn(true);
      setIsPremium(false); // Reset premium status on new login
    } catch (err) {
      alert('Login failed. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleSendMessage = () => {
    if (messageInput.trim()) {
      socket.emit('send_message', { text: messageInput });
      setMessageInput('');
    }
  };

  const handlePremiumUpgrade = async () => {
    setIsLoading(true);
    try {
      const token = localStorage.getItem('token');
      const res = await axios.post('http://localhost:5000/api/premium', {
        username
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });

      setIsPremium(true);
      setPremiumFeatures(res.data.premiumFeatures);
      alert(`🎉 Success! You're now a premium user!\n\nFeatures unlocked:\n${res.data.premiumFeatures.join('\n')}`);
    } catch (err) {
      alert('Failed to upgrade to premium. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    setIsLoggedIn(false);
    setUsername('');
    setPassword('');
    setMessages([]);
    setNotifications([]);
    setIsPremium(false);
    window.location.reload();
  };

  return (
    <div className="app-container">
      <header className="app-header">
        <h1>💬 Social Messenger</h1>
        {isLoggedIn && (
          <div className="user-info">
            <span>Welcome, <strong>{username}</strong>!</span>
            <button onClick={handleLogout} className="logout-btn">Logout</button>
          </div>
        )}
      </header>

      {!isLoggedIn ? (
        <div className="login-section">
          <h2>Login to Chat</h2>
          <form onSubmit={handleLogin} className="login-form">
            <div className="form-group">
              <label>Username:</label>
              <input
                type="text"
                placeholder="Enter username"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label>Password:</label>
              <input
                type="password"
                placeholder="Enter password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
            </div>
            <button type="submit" disabled={isLoading}>
              {isLoading ? 'Logging in...' : 'Login'}
            </button>
          </form>
          <p className="hint">(Any username/password works for demo purposes)</p>
        </div>
      ) : (
        <div className="chat-section">
          <div className="notifications-panel">
            <h3>🔔 Notifications ({notifications.length})</h3>
            <div className="notification-list">
              {notifications.length === 0 ? (
                <p>No new notifications</p>
              ) : (
                notifications.map((notification, index) => (
                  <div key={index} className="notification-item">
                    <span className="notification-text">{notification.message}</span>
                    <span className="notification-time">
                      {new Date(notification.timestamp).toLocaleTimeString()}
                    </span>
                  </div>
                ))
              )}
            </div>
          </div>

          <div className="chat-panel">
            <h3>💬 Messages</h3>
            <div className="message-list">
              {messages.length === 0 ? (
                <p className="empty-message">No messages yet. Send one to start the conversation!</p>
              ) : (
                messages.map((msg) => (
                  <div key={msg.id} className={`message-item ${msg.sender === username ? 'sent' : 'received'}`}>
                    <div className="message-header">
                      <strong>{msg.sender}</strong>
                      <span className="message-time">
                        {new Date(msg.timestamp).toLocaleTimeString()}
                      </span>
                    </div>
                    <div className="message-content">
                      {msg.text}
                      {msg.isPremium && <span className="premium-badge">👑 Premium</span>}
                    </div>
                  </div>
                ))
              )}
            </div>

            <div className="message-input-area">
              <input
                type="text"
                value={messageInput}
                onChange={(e) => setMessageInput(e.target.value)}
                placeholder="Type your message here..."
                disabled={isLoading}
              />
              <button
                onClick={handleSendMessage}
                disabled={isLoading || !messageInput.trim()}
              >
                Send
              </button>
            </div>
          </div>

          {!isPremium && (
            <div className="premium-upgrade">
              <h3>💎 Go Premium!</h3>
              <p>Upgrade to unlock exclusive features:</p>
              <ul>
                <li>Priority message delivery</li>
                <li>Custom emoji support</li>
                <li>Ad-free experience</li>
                <li>Early access to new features</li>
              </ul>
              <button
                onClick={handlePremiumUpgrade}
                disabled={isLoading}
                className="premium-btn"
              >
                {isLoading ? 'Processing...' : 'Upgrade Now ($4.99/month)'}
              </button>
              {premiumFeatures.length > 0 && (
                <div className="premium-features">
                  <h4>Your Premium Features:</h4>
                  <ul>
                    {premiumFeatures.map((feature, index) => (
                      <li key={index}>{feature}</li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default App;
