```tsx
// src/components/Messaging.tsx
import React, { useState, useEffect } from 'react';
import { Socket } from 'phoenix';

const Messaging: React.FC = () => {
  const [messages, setMessages] = useState<string[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [socket, setSocket] = useState<Socket | null>(null);

  useEffect(() => {
    // Connect to the Phoenix WebSocket
    const newSocket = new Socket("ws://localhost:4000/socket", {
      params: { token: localStorage.getItem('token') }
    });
    newSocket.connect();
    setSocket(newSocket);

    // Join the message channel
    const channel = newSocket.channel(`message:${localStorage.getItem('userId')}`, {});
    channel.join()
      .receive("ok", () => {
        console.log("Joined message channel");
      })
      .receive("error", (resp) => {
        console.log("Unable to join message channel", resp);
      });

    // Listen for new messages
    channel.on("new_message", (payload) => {
      setMessages((prevMessages) => [...prevMessages, payload.message.content]);
    });

    return () => {
      channel.leave();
      newSocket.disconnect();
    };
  }, []);

  const sendMessage = () => {
    if (socket && newMessage.trim()) {
      const channel = socket.channel(`message:${localStorage.getItem('userId')}`, {});
      channel.push("new_message", { content: newMessage })
        .receive("ok", () => {
          setNewMessage('');
        });
    }
  };

  return (
    <div>
      <h2>Messaging</h2>
      <div>
        {messages.map((msg, index) => (
          <div key={index}>{msg}</div>
        ))}
      </div>
      <input
        type="text"
        value={newMessage}
        onChange={(e) => setNewMessage(e.target.value)}
      />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
};

export default Messaging;
```

