        console.log("Joined notification channel");
      })
      .receive("error", (resp) => {
        console.log("Unable to join notification channel", resp);
      });

    // Listen for new notifications
    channel.on("new_notification", (payload) => {
      setNotifications((prevNotifications) => [...prevNotifications, payload.notification]);
    });

    return () => {
