### Backend Implementation

First, the backend server setup with Express and Socket.io.

**server.js**:
```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const cors = require('cors');
const jwt = require('jsonwebtoken');

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

// Mock database
let users = [];
let messages = [];
let premiumUsers = new Set(); // For demo monetization

// JWT secret (in a real app, use an environment variable)
const JWT_SECRET = 'your_jwt_secret';

// Authentication middleware
const authenticate = (socket, next) => {
  const token = socket.handshake.auth.token;
  if (!token) {
    return next(new Error('Authentication error'));
  }
  jwt.verify(token, JWT_SECRET, (err, decoded) => {
    if (err) {
      return next(new Error('Authentication error'));
    }
    socket.user = decoded;
    next();
  });
};

// Socket.io connection
io.use(authenticate).on('connection', (socket) => {
  console.log(`User connected: ${socket.user.username}`);

  // Send previous messages to the user
  socket.emit('previous_messages', messages);

  // Handle new messages
  socket.on('send_message', (message) => {
    const newMessage = {
      id: messages.length + 1,
      sender: socket.user.username,
      text: message.text,
      timestamp: new Date(),
      isPremium: premiumUsers.has(socket.user.username)
    };
    messages.push(newMessage);
    io.emit('receive_message', newMessage);

    // Notify all users (or just the recipient in a real app)
    io.emit('notification', {
      type: 'new_message',
      message: `New message from ${socket.user.username}`,
      timestamp: new Date()
    });
  });

  socket.on('disconnect', () => {
    console.log(`User disconnected: ${socket.user.username}`);
  });
});

// REST API routes
app.post('/api/login', (req, res) => {
  const { username, password } = req.body;
  // In a real app, validate credentials against a database
  const user = { id: users.length + 1, username };
  users.push(user);

  const token = jwt.sign(user, JWT_SECRET, { expiresIn: '1h' });
  res.json({ token });
});

app.post('/api/premium', (req, res) => {
  const { username } = req.body;
  premiumUsers.add(username);
  res.json({ success: true, message: 'Premium status granted' });
});

app.get('/api/premium/status', (req, res) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });

  jwt.verify(token, JWT_SECRET, (err, decoded) => {
    if (err) return res.status(401).json({ error: 'Unauthorized' });

    const isPremium = premiumUsers.has(decoded.username);
    res.json({ isPremium });
  });
});

const PORT = 5000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

