**App.js**:
```javascript
import React, { useState, useEffect } from 'react';
import io from 'socket.io-client';
import axios from 'axios';

const socket = io('http://localhost:5000', {
  auth: { token: localStorage.getItem('token') }
});

function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [messages, setMessages] = useState([]);
  const [messageInput, setMessageInput] = useState('');
  const [notifications, setNotifications] = useState([]);
  const [isPremium, setIsPremium] = useState(false);

  useEffect(() => {
    // Check if user is logged in
    const token = localStorage.getItem('token');
    if (token) {
      setIsLoggedIn(true);
      // Verify token and get username
      const decoded = JSON.parse(atob(token.split('.')[1]));
      setUsername(decoded.username);
    }

    // Listen for messages
    socket.on('receive_message', (message) => {
      setMessages(prev => [...prev, message]);
    });

    // Listen for notifications
    socket.on('notification', (notification) => {
      setNotifications(prev => [...prev, notification]);
    });

    // Check premium status
    if (token) {
      axios.get('http://localhost:5000/api/premium/status', {
        headers: { Authorization: `Bearer ${token}` }
      }).then(res => {
        setIsPremium(res.data.isPremium);
      });
    }

    return () => {
      socket.off('receive_message');
      socket.off('notification');
    };
  }, []);

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('http://localhost:5000/api/login', {
        username,
        password
      });
      localStorage.setItem('token', res.data.token);
      setIsLoggedIn(true);
    } catch (err) {
      alert('Login failed');
    }
  };

  const handleSendMessage = () => {
    if (messageInput.trim()) {
      socket.emit('send_message', { text: messageInput });
      setMessageInput('');
    }
  };

  const handlePremium = async () => {
    try {
      await axios.post('http://localhost:5000/api/premium', {
        username
      }, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      });
      setIsPremium(true);
      alert('You are now a premium user!');
    } catch (err) {
      alert('Failed to upgrade to premium');
    }
  };

  return (
    <div className="App">
      {!isLoggedIn ? (
        <div className="login-form">
          <h2>Login</h2>
          <form onSubmit={handleLogin}>
            <input
              type="text"
              placeholder="Username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
            />
            <input
              type="password"
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
            <button type="submit">Login</button>
          </form>
        </div>
      ) : (
        <div className="chat-container">
          <div className="notifications">
            <h3>Notifications</h3>
            <ul>
              {notifications.map((notification, index) => (
                <li key={index}>{notification.message}</li>
              ))}
            </ul>
          </div>
          <div className="messages">
            <h3>Messages</h3>
            <div className="message-list">
              {messages.map((msg, index) => (
                <div key={index} className={msg.sender === username ? 'sent' : 'received'}>
                  <strong>{msg.sender}:</strong> {msg.text}
                  {msg.isPremium && <span> (Premium)</span>}
                </div>
              ))}
            </div>
            <div className="message-input">
              <input
                type="text"
                value={messageInput}
                onChange={(e) => setMessageInput(e.target.value)}
                placeholder="Type a message..."
              />
              <button onClick={handleSendMessage}>Send</button>
            </div>
          </div>
          {!isPremium && (
            <div className="premium-section">
              <button onClick={handlePremium}>Upgrade to Premium ($4.99/month)</button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default App;
```

