```javascript
import React, { useState, useEffect } from 'react';
import io from 'socket.io-client';
import StripeCheckout from 'react-stripe-checkout';

const socket = io('http://localhost:3001', {
  auth: { token: localStorage.getItem('token') }
});

function App() {
  const [messages, setMessages] = useState([]);
  const [message, setMessage] = useState('');
  const [token, setToken] = useState(localStorage.getItem('token') || '');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [isLoggedIn, setIsLoggedIn] = useState(!!token);
  const [isPremium, setIsPremium] = useState(false);

  // Handle login/signup
  const handleAuth = async (e) => {
    e.preventDefault();
    const endpoint = isLoggedIn ? '/login' : '/signup';
    const response = await fetch(`http://localhost:3001${endpoint}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username, password })
    });
    const data = await response.json();
    if (data.token) {
      localStorage.setItem('token', data.token);
      setToken(data.token);
      setIsLoggedIn(true);
    } else {
      alert('Login/Signup failed!');
    }
  };

  // Handle messages and premium status
  useEffect(() => {
    if (!token) return;

    socket.on('newMessage', (msg) => {
      setMessages(prev => [...prev, msg]);
    });

    socket.on('premiumPurchased', ({ success }) => {
      if (success) {
        setIsPremium(true);
        alert('Premium purchased! You now have premium features.');
      } else {
        alert('Payment failed. Please try again.');
      }
    });

    // Fetch user's premium status
    const fetchUser = async () => {
      const response = await fetch('http://localhost:3001/user', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await response.json();
      setIsPremium(data.premium);
    };
    fetchUser();

    return () => {
      socket.off('newMessage');
      socket.off('premiumPurchased');
    };
  }, [token]);

  const sendMessage = () => {
    if (!message.trim()) return;
    socket.emit('sendMessage', message);
    setMessage('');
  };

  const handleToken = (token) => {
    socket.emit('purchasePremium', token);
  };

  if (!isLoggedIn) {
    return (
      <div style={{ padding: '20px', maxWidth: '400px', margin: '0 auto' }}>
        <h2>{isLoggedIn ? 'Login' : 'Signup'}</h2>
        <form onSubmit={handleAuth}>
          <input
            type="text"
            placeholder="Username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            style={{ width: '100%', padding: '8px', margin: '8px 0' }}
          />
          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={{ width: '100%', padding: '8px', margin: '8px 0' }}
          />
          <button type="submit" style={{ width: '100%', padding: '10px' }}>
            {isLoggedIn ? 'Login' : 'Signup'}
          </button>
        </form>
        <button
          onClick={() => setIsLoggedIn(!isLoggedIn)}
          style={{ width: '100%', padding: '10px', marginTop: '10px' }}
        >
          {isLoggedIn ? 'Switch to Signup' : 'Switch to Login'}
        </button>
      </div>
    );
  }

  return (
    <div style={{ padding: '20px', maxWidth: '600px', margin: '0 auto' }}>
      <h1>Welcome, {username}</h1>
      <p>Premium Status: <strong>{isPremium ? '✅ Premium' : '❌ Free'}</strong></p>

      <div style={{ height: '300px', overflowY: 'auto', border: '1px solid #ccc', padding: '10px', margin: '20px 0' }}>
        {messages.map((msg, i) => (
          <div key={i} style={{ margin: '5px 0' }}>
            <strong>{msg.user}:</strong> {msg.message}
          </div>
        ))}
      </div>

      <input
        type="text"
        value={message}
        onChange={(e) => setMessage(e.target.value)}
        onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
        placeholder="Type a message..."
        style={{ width: '70%', padding: '8px' }}
      />
      <button onClick={sendMessage} style={{ width: '25%', padding: '8px', marginLeft: '5px' }}>
        Send
      </button>

      {!isPremium && (
        <div style={{ marginTop: '20px' }}>
          <StripeCheckout
            token={handleToken}
            stripeKey="pk_test_51ABC123" // Replace with your Stripe publishable key
            amount={1000} // $10.00
            currency="USD"
            name="Upgrade to Premium"
            description="Unlock premium features!"
          >
            <button style={{ padding: '10px', background: '#6772e5', color: 'white', border: 'none', borderRadius: '4px' }}>
              Buy Premium ($10)
            </button>
          </StripeCheckout>
        </div>
      )}
    </div>
  );
}

export default App;
```

