const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const mongoose = require('mongoose');
const jwt = require('jsonwebtoken');
const stripe = require('stripe')('sk_test_...'); // Replace with your Stripe key

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// MongoDB setup
mongoose.connect('mongodb://localhost:27017/messaging_app', { useNewUrlParser: true, useUnifiedTopology: true });

// User schema
const UserSchema = new mongoose.Schema({
  username: String,
  password: String,
  premium: { type: Boolean, default: false }
});
const User = mongoose.model('User', UserSchema);

// Middleware for JWT auth
const authenticate = (socket, next) => {
  const token = socket.handshake.auth.token;
  if (!token) return next(new Error('Authentication error'));
  jwt.verify(token, 'secret', (err, decoded) => {
    if (err) return next(new Error('Authentication error'));
    socket.user = decoded;
    next();
  });
};

// Socket.io setup with auth
io.use(authenticate).on('connection', (socket) => {
  console.log('New user connected:', socket.user.username);

  // Handle messages
  socket.on('sendMessage', (message) => {
    io.emit('newMessage', { user: socket.user.username, message });
  });

  // Handle premium purchase (simplified)
  socket.on('purchasePremium', async (token) => {
    try {
      const charge = await stripe.charges.create({
        amount: 1000, // $10.00
        currency: 'usd',
        source: token,
      });
      await User.findByIdAndUpdate(socket.user.id, { premium: true });
      socket.emit('premiumPurchased', { success: true });
    } catch (err) {
      socket.emit('premiumPurchased', { success: false, error: err.message });
    }
  });

  socket.on('disconnect', () => {
    console.log('User disconnected:', socket.user.username);
  });
});

// REST endpoints for auth and Stripe
app.use(express.json());

// Login endpoint
app.post('/login', async (req, res) => {
  const { username, password } = req.body;
  const user = await User.findOne({ username, password });
  if (!user) return res.status(401).send('Invalid credentials');
  const token = jwt.sign({ id: user._id, username: user.username }, 'secret');
  res.json({ token });
});

// Signup endpoint
app.post('/signup', async (req, res) => {
  const { username, password } = req.body;
  const user = new User({ username, password });
  await user.save();
  const token = jwt.sign({ id: user._id, username: user.username }, 'secret');
  res.json({ token });
});

server.listen(3001, () => console.log('Server running on port 3001'));
