// server.js
const express = require('express');
const WebSocket = require('ws');
const path = require('path');

const app = express();
const PORT = process.env.PORT || 3000;

// Serve static files
app.use(express.static(path.join(__dirname, 'public')));

// Parse JSON bodies
app.use(express.json());

// In-memory data store
let dataPoints = [
  { time: new Date().toISOString(), value: 10 },
  { time: new Date(Date.now() - 10000).toISOString(), value: 15 },
  { time: new Date(Date.now() - 20000).toISOString(), value: 7 }
];

// API endpoint to get data
app.get('/api/data', (req, res) => {
  res.json(dataPoints);
});

// API endpoint to add new data point
app.post('/api/data', (req, res) => {
  const { value } = req.body;

  if (value === undefined || isNaN(value)) {
    return res.status(400).json({ error: 'Invalid value' });
  }

  const newPoint = {
    time: new Date().toISOString(),
    value: Number(value)
  };

  dataPoints.push(newPoint);
  // Keep only last 100 points
  if (dataPoints.length > 100) {
    dataPoints.shift();
  }

  // Broadcast to all connected clients
  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(JSON.stringify(newPoint));
    }
  });

  res.json(newPoint);
});

// Start HTTP server
const server = app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});

// WebSocket server
const wss = new WebSocket.Server({ server });

wss.on('connection', (ws) => {
  console.log('New client connected');

  // Send all existing data to the new client
  ws.send(JSON.stringify({ type: 'initial', data: dataPoints }));

  ws.on('close', () => {
    console.log('Client disconnected');
  });
});
