## 4. Client-Side Logic (public/script.js)

```javascript
// script.js
document.addEventListener('DOMContentLoaded', () => {
  // Chart setup
  const ctx = document.getElementById('dataChart').getContext('2d');
  let dataChart;

  // Initialize chart
  function initChart() {
    dataChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: [],
        datasets: [{
          label: 'Data Values',
          data: [],
          borderColor: 'rgb(52, 152, 219)',
          backgroundColor: 'rgba(52, 152, 219, 0.1)',
          tension: 0.1,
          borderWidth: 2,
          pointRadius: 4,
          pointBackgroundColor: 'rgb(52, 152, 219)'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true
          }
        },
        animation: {
          duration: 1000
        }
      }
    });
  }

  // Update chart with new data
  function updateChart(dataPoint) {
    const time = new Date(dataPoint.time).toLocaleTimeString();
    const value = dataPoint.value;

    // Add new data
    dataChart.data.labels.push(time);
    dataChart.data.datasets[0].data.push(value);

    // Remove old data if we have too many points
    if (dataChart.data.labels.length > 20) {
      dataChart.data.labels.shift();
      dataChart.data.datasets[0].data.shift();
    }

    dataChart.update();

    // Update stats
    document.getElementById('pointCount').textContent = dataChart.data.labels.length;
    document.getElementById('lastUpdate').textContent = time;
  }

  // Form handling
  const form = document.getElementById('dataForm');
  const valueInput = document.getElementById('value');
  const valueError = document.getElementById('valueError');

  form.addEventListener('submit', async (e) => {
    e.preventDefault();

    // Validate input
    if (!valueInput.value || isNaN(valueInput.value)) {
      valueError.textContent = 'Please enter a valid number';
      valueError.style.display = 'block';
      return;
    }

    valueError.style.display = 'none';

    try {
      const response = await fetch('/api/data', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          value: parseFloat(valueInput.value)
        })
      });

      if (!response.ok) {
        throw new Error('Failed to submit data');
      }

      valueInput.value = '';
    } catch (error) {
      console.error('Error:', error);
      alert('Failed to submit data. Please try again.');
    }
  });

  // WebSocket connection
  const socket = new WebSocket(`ws://${window.location.host}`);

  socket.onopen = () => {
    console.log('Connected to WebSocket server');
  };

  socket.onmessage = (event) => {
    const data = JSON.parse(event.data);

    if (data.type === 'initial') {
      // Initial data load
      data.data.forEach(point => updateChart(point));
    } else {
      // Real-time update
      updateChart(data);
    }
  };

  socket.onerror = (error) => {
    console.error('WebSocket error:', error);
  };

  socket.onclose = () => {
    console.log('Disconnected from WebSocket server');
  };

  // Initialize chart when page loads
  initChart();
});
```

