const express = require('express');
const WebSocket = require('ws');
const path = require('path');

const app = express();
const PORT = 3000;

// Serve static files
app.use(express.static(path.join(__dirname, 'public')));

// Parse JSON and form data
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Store data points (simulated database)
let dataPoints = [
  { time: new Date().toISOString(), value: 10 },
  { time: new Date().toISOString(), value: 20 },
  { time: new Date().toISOString(), value: 30 }
];

// API endpoint to get current data
app.get('/api/data', (req, res) => {
  res.json(dataPoints);
});

// API endpoint to add new data point
app.post('/api/data', (req, res) => {
  const { value } = req.body;
  if (value === undefined || isNaN(value)) {
    return res.status(400).json({ error: 'Invalid value' });
  }

  const newPoint = {
    time: new Date().toISOString(),
    value: parseFloat(value)
  };

  dataPoints.push(newPoint);
  broadcastData(newPoint); // Send to all WebSocket clients
  res.json({ success: true, data: newPoint });
});

// WebSocket server setup
const server = app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});

const wss = new WebSocket.Server({ server });

wss.on('connection', (ws) => {
  console.log('New client connected');
  ws.send(JSON.stringify({ type: 'INITIAL_DATA', data: dataPoints }));

  ws.on('close', () => {
    console.log('Client disconnected');
  });
});

function broadcastData(newPoint) {
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(JSON.stringify({ type: 'NEW_DATA', data: newPoint }));
    }
  });
}
