            const statusElement = document.getElementById('statusMessage');
            statusElement.textContent = message;
            statusElement.className = 'status-message ' + type;

            // Hide message after 3 seconds
            setTimeout(() => {
                statusElement.className = 'status-message';
            }, 3000);
        }

        // Connect to SSE and update chart in real-time
        const eventSource = new EventSource('/sse');
        eventSource.onmessage = function(e) {
            const data = JSON.parse(e.data);
            const timestamp = new Date(data.timestamp).toLocaleTimeString();

            // Add data to appropriate dataset based on type
            switch(data.type) {
                case 'temperature':
                    dataChart.data.labels.push(timestamp);
                    dataChart.data.datasets[0].data.push(data.value);
                    break;
                case 'humidity':
                    dataChart.data.labels.push(timestamp);
                    dataChart.data.datasets[1].data.push(data.value);
                    break;
                case 'pressure':
                    dataChart.data.labels.push(timestamp);
                    dataChart.data.datasets[2].data.push(data.value);
                    break;
                default:
                    // For custom data, use the first dataset
                    dataChart.data.labels.push(timestamp);
                    dataChart.data.datasets[0].data.push(data.value);
            }

            // Limit the number of data points to keep the chart readable
            if (dataChart.data.labels.length > 20) {
                dataChart.data.labels.shift();
                dataChart.data.datasets.forEach(dataset => {
                    dataset.data.shift();
                });
            }

            dataChart.update();
        };

        // Toggle dataset visibility when clicking legend
        dataChart.options.onClick = (e, elements) => {
            if (elements.length > 0) {
                const meta = dataChart.getDatasetMeta(elements[0].datasetIndex);
                meta.hidden = meta.hidden === null ? !dataChart.data.datasets[elements[0].datasetIndex].hidden : null;
                dataChart.update();
            }
        };
    </script>
