import { Server } from "socket.io";
import { SensorData } from "./types";

let activeSensors: SensorData[] = [];

export const setupSocket = (io: Server) => {
  io.on("connection", (socket) => {
    console.log("Client connected:", socket.id);

    // Send current sensor data to new client
    socket.emit("initial-data", activeSensors);

    socket.on("disconnect", () => {
      console.log("Client disconnected:", socket.id);
    });
  });

  // Simulate real-time sensor data updates
  setInterval(() => {
    const newData: SensorData = {
      id: `sensor-${Math.floor(Math.random() * 5) + 1}`,
      temperature: Math.floor(Math.random() * 30) + 10,
      humidity: Math.floor(Math.random() * 50) + 30,
      timestamp: new Date().toISOString(),
    };

    activeSensors = [...activeSensors.filter(s => s.id !== newData.id), newData];
    io.emit("sensor-update", newData);
  }, 2000);
};
