```tsx
import React, { useState, useEffect } from 'react';
import { Line } from 'react-chartjs-2';
import { io, Socket } from 'socket.io-client';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import { SensorData } from '../types';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend
);

interface DashboardProps {
  onFormSubmit: (data: any) => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ onFormSubmit }) => {
  const [sensorData, setSensorData] = useState<SensorData[]>([]);
  const [socket, setSocket] = useState<Socket | null>(null);

  useEffect(() => {
    // Connect to WebSocket server
    const newSocket = io('http://localhost:5000');
    setSocket(newSocket);

    // Listen for initial data
    newSocket.on('initial-data', (data: SensorData[]) => {
      setSensorData(data);
    });

    // Listen for real-time updates
    newSocket.on('sensor-update', (data: SensorData) => {
      setSensorData(prev => [...prev.filter(s => s.id !== data.id), data]);
    });

    return () => {
      newSocket.disconnect();
    };
  }, []);

  // Prepare chart data
  const chartData = {
    labels: sensorData.map(d => new Date(d.timestamp).toLocaleTimeString()),
    datasets: [
      {
        label: 'Temperature (°C)',
        data: sensorData.map(d => d.temperature),
        borderColor: 'rgb(255, 99, 132)',
        tension: 0.1,
      },
      {
        label: 'Humidity (%)',
        data: sensorData.map(d => d.humidity),
        borderColor: 'rgb(53, 162, 235)',
        tension: 0.1,
      },
    ],
  };

  return (
    <div className="dashboard">
      <h2>Real-Time Sensor Dashboard</h2>
      <div className="chart-container">
        <Line data={chartData} />
      </div>
      <div className="data-table">
