import React from 'react';
import { useFormik } from 'formik';
import * as Yup from 'yup';

interface FormProps {
  onSubmit: (data: any) => void;
}

export const Form: React.FC<FormProps> = ({ onSubmit }) => {
  const formik = useFormik({
    initialValues: {
      name: '',
      email: '',
      sensorId: 'sensor-1',
      threshold: 25,
    },
    validationSchema: Yup.object({
      name: Yup.string().required('Required'),
      email: Yup.string().email('Invalid email address').required('Required'),
      sensorId: Yup.string().required('Required'),
      threshold: Yup.number().min(0).max(50).required('Required'),
    }),
    onSubmit: (values) => {
      onSubmit(values);
      formik.resetForm();
    },
  });

  return (
    <div className="form-container">
      <h2>Configure Alerts</h2>
      <form onSubmit={formik.handleSubmit}>
        <div>
          <label>Name</label>
          <input
            type="text"
            name="name"
            onChange={formik.handleChange}
            value={formik.values.name}
          />
          {formik.errors.name && <div className="error">{formik.errors.name}</div>}
        </div>
        <div>
          <label>Email</label>
          <input
            type="email"
            name="email"
            onChange={formik.handleChange}
            value={formik.values.email}
          />
          {formik.errors.email && <div className="error">{formik.errors.email}</div>}
        </div>
        <div>
          <label>Sensor ID</label>
          <select
            name="sensorId"
            onChange={formik.handleChange}
            value={formik.values.sensorId}
          >
            <option value="sensor-1">Sensor 1</option>
            <option value="sensor-2">Sensor 2</option>
            <option value="sensor-3">Sensor 3</option>
            <option value="sensor-4">Sensor 4</option>
            <option value="sensor-5">Sensor 5</option>
          </select>
        </div>
        <div>
          <label>Temperature Threshold (°C)</label>
          <input
            type="number"
            name="threshold"
            onChange={formik.handleChange}
