### **1. `server.js` (Backend)**
Handles real-time data updates and form submissions via Socket.IO.

```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server, {
    cors: {
        origin: "*", // Allow all origins (for development only)
        methods: ["GET", "POST"]
    }
});

// Serve static files (HTML, CSS, JS)
app.use(express.static('public'));

// Simulate real-time data updates (e.g., sensor data)
setInterval(() => {
    const data = {
        timestamp: new Date().toISOString(),
        value: Math.random() * 100,
        label: 'Sensor Data'
    };
    io.emit('data-update', data); // Broadcast to all clients
}, 2000);

// Handle form submissions
app.post('/submit-form', express.json(), (req, res) => {
    const formData = req.body;
    console.log('Form submitted:', formData);
    io.emit('form-submission', formData); // Broadcast to all clients
    res.status(200).send('Form submitted successfully');
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on http://localhost:${PORT}`);
});
```

