### **4. `public/script.js` (Frontend Logic)**
Handles real-time updates and form submissions.

```javascript
document.addEventListener('DOMContentLoaded', () => {
    const socket = io();
    const form = document.getElementById('data-form');
    const chartDiv = document.getElementById('chart');

    // Initialize Plotly chart
    const data = [{
        x: [],
        y: [],
        type: 'scatter',
        mode: 'lines+markers',
        name: 'Real-Time Data',
        line: { color: '#4CAF50' }
    }];

    const layout = {
        title: 'Real-Time Data Stream',
        xaxis: { title: 'Time' },
        yaxis: { title: 'Value' },
        hovermode: 'closest'
    };

    Plotly.newPlot(chartDiv, data, layout);

    // Handle real-time data updates from server
    socket.on('data-update', (data) => {
        const time = new Date(data.timestamp).toLocaleTimeString();
        Plotly.extendTraces(chartDiv, {
            x: [[time]],
            y: [[data.value]]
        }, [0]);
    });

    // Handle form submissions
    form.addEventListener('submit', (e) => {
        e.preventDefault();
        const formData = {
            label: document.getElementById('label').value,
            value: parseFloat(document.getElementById('value').value)
        };

        // Send to server
        fetch('/submit-form', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(formData)
        })
        .then(response => response.text())
        .then(() => form.reset())
        .catch(error => console.error('Error:', error));
    });

    // Listen for form submissions from other clients
    socket.on('form-submission', (formData) => {
        const time = new Date().toLocaleTimeString();
        Plotly.extendTraces(chartDiv, {
            x: [[time]],
            y: [[formData.value]]
        }, [0]);
    });
});
```

