                y: parseFloat(y),
                label: label.trim() || '',
                timestamp: timestamp
            };

            state.dataPoints.push(dataPoint);
            state.chart.data.datasets[0].data.push(dataPoint);
            state.chart.update();

            updateStats();
            renderTable();
            return dataPoint;
        }

        // Remove a data point by ID
        function removeDataPoint(id) {
            state.dataPoints = state.dataPoints.filter(point => point.id !== id);
            state.chart.data.datasets[0].data = state.dataPoints;
            state.chart.update();

            updateStats();
            renderTable();
        }

        // Clear all data points
        function clearAllData() {
            state.dataPoints = [];
            state.chart.data.datasets[0].data = [];
            state.chart.update();

            updateStats();
            renderTable();
