        // Update statistics display
        function updateStats() {
            const yValues = state.dataPoints.map(point => point.y);

            elements.totalPoints.textContent = state.dataPoints.length;

            if (yValues.length > 0) {
                const sum = yValues.reduce((a, b) => a + b, 0);
                const avg = (sum / yValues.length).toFixed(2);
                const min = Math.min(...yValues).toFixed(2);
                const max = Math.max(...yValues).toFixed(2);

                elements.avgValue.textContent = avg;
                elements.minValue.textContent = min;
                elements.maxValue.textContent = max;
            } else {
                elements.avgValue.textContent = '0';
                elements.minValue.textContent = '0';
                elements.maxValue.textContent = '0';
