                elements.tableBody.appendChild(row);
            });
        }

        // Toggle real-time updates
        function toggleRealTimeUpdates() {
            if (state.realTimeInterval) {
                // Stop real-time updates
                clearInterval(state.realTimeInterval);
                state.realTimeInterval = null;

                elements.statusIndicator.className = 'status-indicator status-stopped';
                elements.statusLabel.textContent = 'Stopped';
                elements.toggleRealTimeBtn.textContent = 'Start Real-time';
                elements.toggleRealTimeBtn.className = 'btn btn-secondary';
            } else {
                // Start real-time updates
                state.realTimeInterval = setInterval(() => {
                    const x = Math.random() * 10;
                    const y = Math.random() * 10;
                    const labels = ['Sensor A', 'Sensor B', 'Input 1', 'Input 2', 'Measurement', 'Data Point'];
                    const randomLabel = labels[Math.floor(Math.random() * labels.length)];

                    addDataPoint(x, y, randomLabel);
                }, 1500);

                elements.statusIndicator.className = 'status-indicator status-running';
                elements.statusLabel.textContent = 'Running';
                elements.toggleRealTimeBtn.textContent = 'Stop Real-time';
                elements.toggleRealTimeBtn.className = 'btn btn-danger';
            }
        }

        // Event listeners
        elements.dataForm.addEventListener('submit', function(e) {
            e.preventDefault();

            const xValue = elements.xValueInput.value;
            const yValue = elements.yValueInput.value;
            const label = elements.labelInput.value;

            if (xValue && yValue) {
                addDataPoint(xValue, yValue, label);

                // Reset form
                elements.xValueInput.value = '';
                elements.yValueInput.value = '';
                elements.labelInput.value = '';
                elements.xValueInput.focus();
            }
        });

        elements.clearBtn.addEventListener('click', clearAllData);
        elements.toggleRealTimeBtn.addEventListener('click', toggleRealTimeUpdates);

        // Initialize the dashboard when the page loads
        window.addEventListener('load', function() {
            initChart();
            updateStats();
        });

        // Expose removeDataPoint to global scope for table buttons
        window.removeDataPoint = removeDataPoint;
    </script>
</body>
</html>
