  (details) => {
    const url = new URL(details.url);
    for (const domain of TRACKING_DOMAINS) {
      if (url.hostname.includes(domain)) {
        blockedCount++;
        chrome.storage.sync.set({ blockedCount });
        console.log(`[Privacy Shield] Blocked: ${details.url}`);
        return { cancel: true };
      }
    }
    return { cancel: false };
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);

// Initialize blocked count
