  const script = event.target;
  if (script.src) {
    const url = new URL(script.src);
    const isTracking = TRACKING_DOMAINS.some(domain =>
      url.hostname.includes(domain)
    );
    if (isTracking) {
      event.preventDefault();
      console.log(`[Privacy Shield] Blocked inline script: ${script.src}`);
    }
  }
});

// Remove tracking iframes and scripts dynamically
const observer = new MutationObserver((mutations) => {
  mutations.forEach((mutation) => {
    mutation.addedNodes.forEach((node) => {
      if (node.nodeType === Node.ELEMENT_NODE) {
        // Check for tracking iframes
        const iframes = node.querySelectorAll("iframe[src*='tracking'], iframe[src*='ads']");
        iframes.forEach((iframe) => iframe.remove());

        // Check for tracking scripts
        const scripts = node.querySelectorAll("script[src*='tracking'], script[src*='ads']");
        scripts.forEach((script) => script.remove());
      }
    });
  });
});

observer.observe(document.body, {
  childList: true,
  subtree: true,
});
