Now, let's create a content script that can also block scripts by modifying the DOM. This is an alternative approach to blocking scripts by preventing them from loading in the first place.

content.js:
```javascript
// This script runs in the context of the web page
// It can be used to modify the DOM to block tracking scripts

// Function to check if a script is a tracking script
function isTrackingScript(script) {
  try {
    const src = script.src;
    if (!src) return false;
    const domain = new URL(src).hostname;
    return TRACKING_DOMAINS.some(trackingDomain =>
      domain === trackingDomain || domain.endsWith(`.${trackingDomain}`)
    );
  } catch (e) {
    return false;
  }
}

// Remove tracking scripts from the DOM
document.addEventListener('beforescriptexecute', (event) => {
  const script = event.target;
  if (isTrackingScript(script)) {
    console.log(`Blocking tracking script: ${script.src}`);
    event.preventDefault();
    event.stopImmediatePropagation();
    script.remove();
  }
});

// Also try to block dynamically added scripts
const observer = new MutationObserver((mutations) => {
  mutations.forEach((mutation) => {
    mutation.addedNodes.forEach((node) => {
      if (node.tagName === 'SCRIPT' && isTrackingScript(node)) {
        console.log(`Blocking dynamically added tracking script: ${node.src}`);
        node.remove();
      } else if (node.querySelectorAll) {
        node.querySelectorAll('script').forEach((script) => {
          if (isTrackingScript(script)) {
            console.log(`Blocking dynamically added tracking script: ${script.src}`);
            script.remove();
          }
        });
      }
    });
  });
});

observer.observe(document, {
  childList: true,
  subtree: true
});
```

