            background-color: #f0f0f0;
            border: 1px solid #ccc;
            border-radius: 4px;
        }
        button:hover {
            background-color: #e0e0e0;
        }
        button:disabled {
            background-color: #f5f5f5;
            color: #999;
            cursor: not-allowed;
        }
    </style>
</head>
<body>
    <h1>Stock Price Heatmap</h1>
    <div id="controls">
        <button id="start">Start Updates</button>
        <button id="stop" disabled>Stop Updates</button>
    </div>
    <div id="heatmap-container"></div>

    <script>
        // Configuration
        const config = {
            width: 800,
            height: 600,
            margin: { top: 50, right: 30, bottom: 50, left: 100 },
            numStocks: 10,
            numTimePoints: 24,
            updateInterval: 1000 // ms
        };

        // Stock names
        const stocks = ["AAPL", "MSFT", "GOOGL", "AMZN", "TSLA", "META", "NVDA", "JPM", "V", "WMT"];

        // Time labels (e.g., "00:00", "01:00", ...)
        const timeLabels = d3.range(config.numTimePoints).map(h =>
            `${h.toString().padStart(2, '0')}:00`
        );

        // Color scale for price changes (red for negative, green for positive)
        const colorScale = d3.scaleSequential(d3.interpolateRdYlGn)
            .domain([-1, 1]);

        // Calculate inner dimensions
        const innerWidth = config.width - config.margin.left - config.margin.right;
        const innerHeight = config.height - config.margin.top - config.margin.bottom;

        // Scales
        const xScale = d3.scaleBand()
            .domain(timeLabels)
            .range([0, innerWidth])
            .padding(0.05);

        const yScale = d3.scaleBand()
            .domain(stocks)
            .range([0, innerHeight])
            .padding(0.05);

        // Create SVG container
        const svg = d3.select("#heatmap-container")
            .append("svg")
            .attr("width", config.width)
            .attr("height", config.height);

        const g = svg.append("g")
            .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

        // Create axes
        const xAxis = d3.axisBottom(xScale);
        const yAxis = d3.axisLeft(yScale);

        g.append("g")
            .attr("class", "x-axis")
            .attr("transform", `translate(0,${innerHeight})`)
            .call(xAxis);

        g.append("g")
            .attr("class", "y-axis")
            .call(yAxis);

        // Add axis labels
        g.append("text")
            .attr("class", "axis-label")
            .attr("x", innerWidth / 2)
            .attr("y", innerHeight + 40)
            .style("text-anchor", "middle")
            .text("Time (24h)");

        g.append("text")
            .attr("class", "axis-label")
            .attr("transform", "rotate(-90)")
            .attr("x", -innerHeight / 2)
            .attr("y", -60)
            .style("text-anchor", "middle")
            .text("Stocks");

        // Initial data: random price changes between -1 and 1
        let data = Array.from({ length: config.numStocks }, () =>
            Array.from({ length: config.numTimePoints }, () => Math.random() * 2 - 1)
        );

        // Function to update data (shift left and add new column)
        function updateData() {
            const newColumn = Array.from({ length: config.numStocks }, () => Math.random() * 2 - 1);
            data = data.map((row, i) => [...row.slice(1), newColumn[i]]);
        }

        // Function to draw the heatmap
        function drawHeatmap() {
            const numCols = xScale.domain().length;
            const flatData = data.flat();

            // Join new data
            const cells = g.selectAll(".cell")
                .data(flatData, (d, i) => i);

            // Enter new cells
            cells.enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", (d, i) => xScale(timeLabels[i % numCols]))
                .attr("y", (d, i) => yScale(stocks[Math.floor(i / numCols)]))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d))
                .merge(cells)
                .transition()
                .duration(500)
                .attr("x", (d, i) => xScale(timeLabels[i % numCols]))
                .attr("y", (d, i) => yScale(stocks[Math.floor(i / numCols)]))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d));

            // Remove old cells
            cells.exit().remove();
        }

        // Initial draw
        drawHeatmap();

        // Zoom and pan behavior (only translation, no scaling)
        const zoom = d3.zoom()
            .scaleExtent([1, 1]) // Disable scaling
            .on("zoom", (event) => {
                g.attr("transform", event.transform);
            });

        svg.call(zoom);

        // Real-time update controls
        let intervalId;
        const startButton = document.getElementById("start");
        const stopButton = document.getElementById("stop");

        startButton.addEventListener("click", () => {
            if (!intervalId) {
                intervalId = setInterval(() => {
                    updateData();
                    drawHeatmap();
                }, config.updateInterval);
                startButton.disabled = true;
                stopButton.disabled = false;
            }
        });

        stopButton.addEventListener("click", () => {
            if (intervalId) {
                clearInterval(intervalId);
                intervalId = null;
                startButton.disabled = false;
                stopButton.disabled = true;
            }
        });

        // Add tooltip for cell values
        const tooltip = d3.select("body").append("div")
            .attr("class", "tooltip")
            .style("position", "absolute")
            .style("background-color", "rgba(0,0,0,0.7)")
            .style("color", "white")
            .style("padding", "5px 10px")
            .style("border-radius", "5px")
            .style("pointer-events", "none")
            .style("opacity", 0);

        g.selectAll(".cell")
            .on("mouseover", function(event, d) {
                const [x, y] = d3.pointer(event);
                const stockIndex = Math.floor(y / yScale.bandwidth());
                const timeIndex = Math.floor(x / xScale.bandwidth());
                const stock = stocks[stockIndex];
                const time = timeLabels[timeIndex];
                const value = d.toFixed(2);

                tooltip.transition()
                    .duration(200)
                    .style("opacity", .9);
                tooltip.html(`<strong>${stock}</strong><br/>${time}<br/>Change: ${value}`)
                    .style("left", (event.pageX + 10) + "px")
                    .style("top", (event.pageY - 28) + "px");
            })
            .on("mouseout", function() {
                tooltip.transition()
                    .duration(500)
                    .style("opacity", 0);
            });
    </script>
</body>
</html>
```

