<body>
    <div class="controls">
        <button id="resetZoom">Reset Zoom</button>
        <span>Status: <span id="status">Paused</span></span>
        <button id="toggleUpdates">Start Real-time Updates</button>
        <div class="instructions">
            Use mouse wheel to zoom, click and drag to pan. Click cells for details.
        </div>
    </div>
    <div id="chart-container">
        <canvas id="heatmapChart"></canvas>
    </div>

    <script>
        // Configuration
        const stocks = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'TSLA', 'NVDA', 'META', 'JPM', 'V', 'WMT'];
        const timeIntervals = Array.from({length: 30}, (_, i) => {
            const hours = Math.floor(i / 6) + 9;
            const minutes = (i % 6) * 10;
            return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`;
        });

        // Initial data: stocks x time intervals (random prices between 50-200)
        let data = stocks.map(() =>
            timeIntervals.map(() => Math.random() * 150 + 50)
        );

        // Chart.js configuration
        const ctx = document.getElementById('heatmapChart').getContext('2d');
        let chart = new Chart(ctx, {
            type: 'heatmap',
            data: {
                labels: timeIntervals,
                datasets: [{
                    label: 'Stock Prices ($)',
                    data: data,
                    backgroundColor: (ctx) => {
                        const numColumns = chart.data.labels.length;
                        const row = Math.floor(ctx.dataIndex / numColumns);
                        const col = ctx.dataIndex % numColumns;
                        const value = ctx.dataset.data[row][col];
                        // Red gradient: low values = light red, high values = dark red
                        const alpha = Math.min(1, (value - 50) / 150);
                        return `rgba(255, 50, 50, ${alpha})`;
                    },
                    borderWidth: 1,
                    borderColor: 'rgba(255,255,255,0.3)'
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: {
                        title: {
                            display: true,
                            text: 'Time of Day',
                            font: { size: 14, weight: 'bold' }
                        },
                        ticks: {
                            maxRotation: 45,
