                                return stocks[value] || '';
                            }
                        }
                    }
                },
                plugins: {
                    title: {
                        display: true,
                        text: 'Real-time Stock Price Heatmap',
                        font: { size: 18, weight: 'bold' },
                        padding: { top: 10, bottom: 20 }
                    },
                    zoom: {
                        limits: {
                            x: { min: 1, max: timeIntervals.length, minRange: 5 },
                            y: { min: 1, max: stocks.length, minRange: 2 }
                        },
                        zoom: {
                            wheel: {
                                enabled: true,
                            },
                            pinch: {
                                enabled: true
                            },
                            mode: 'xy',
                            onZoomComplete: ({chart}) => {
                                console.log('Zoomed to:', chart.getZoomLevel());
                            }
                        },
                        pan: {
                            enabled: true,
                            mode: 'xy',
                            onPanComplete: ({chart}) => {
                                console.log('Panned to:', chart.getDecimalForPixel(chart.chartArea.left));
                            }
                        }
                    },
                    tooltip: {
                        callbacks: {
                            label: function(context) {
                                const numColumns = chart.data.labels.length;
                                const row = Math.floor(context.dataIndex / numColumns);
                                const col = context.dataIndex % numColumns;
                                return [
                                    `Stock: ${stocks[row]}`,
                                    `Time: ${timeIntervals[col]}`,
                                    `Price: $${context.dataset.data[row][col].toFixed(2)}`
                                ];
                            }
                        },
                        backgroundColor: 'rgba(0, 0, 0, 0.8)',
                        titleFont: { size: 14 },
                        bodyFont: { size: 13 },
                        padding: 10,
                        displayColors: false
                    }
                },
                onClick: (e) => {
                    const points = chart.getElementsAtEventForMode(
                        e, 'nearest', { intersect: true }, true
                    );
                    if (points.length) {
                        const point = points[0];
                        const numColumns = chart.data.labels.length;
                        const stockIndex = Math.floor(point.index / numColumns);
                        const timeIndex = point.index % numColumns;
                        const price = data[stockIndex][timeIndex];

                        // Create a detailed modal
                        const modal = document.createElement('div');
                        modal.style.position = 'fixed';
                        modal.style.top = '0';
                        modal.style.left = '0';
                        modal.style.width = '100%';
                        modal.style.height = '100%';
                        modal.style.backgroundColor = 'rgba(0,0,0,0.7)';
                        modal.style.display = 'flex';
                        modal.style.justifyContent = 'center';
                        modal.style.alignItems = 'center';
