                                </div>
                                <button id="closeModal" style="padding: 10px 20px; background: #f44336; color: white; border: none; border-radius: 4px; cursor: pointer;">Close</button>
                            </div>
                        `;

                        document.body.appendChild(modal);

                        document.getElementById('closeModal').addEventListener('click', () => {
                            document.body.removeChild(modal);
                        });
                    }
                }
            }
        });

        // Real-time updates simulation
        let isUpdating = false;
        let updateInterval;
        const updateIntervalMs = 1500; // Update every 1.5 seconds

        function updateData() {
            // Update a random cell in the data
            const stockIndex = Math.floor(Math.random() * stocks.length);
            const timeIndex = Math.floor(Math.random() * timeIntervals.length);
            const newPrice = Math.random() * 150 + 50;

            // Simulate price change (smaller changes more likely)
            const change = (Math.random() - 0.5) * 10;
            data[stockIndex][timeIndex] = Math.max(50, Math.min(200, newPrice + change));

            // Update the chart
            chart.update();
        }

        document.getElementById('toggleUpdates').addEventListener('click', function() {
            isUpdating = !isUpdating;
            if (isUpdating) {
                updateInterval = setInterval(updateData, updateIntervalMs);
                document.getElementById('status').textContent = 'Running';
                this.textContent = 'Pause Updates';
            } else {
                clearInterval(updateInterval);
                document.getElementById('status').textContent = 'Paused';
                this.textContent = 'Start Real-time Updates';
            }
        });

        document.getElementById('resetZoom').addEventListener('click', function() {
            chart.resetZoom();
        });
    </script>
