            .attr("width", width)
            .attr("height", height)
            .append("g")
            .attr("transform", `translate(${margin.left},${margin.top})`);

        // Create scales
        const xScale = d3.scaleLinear()
            .domain([0, timePeriods - 1])
            .range([0, innerWidth]);

        const yScale = d3.scaleBand()
            .domain(stocks)
            .range([0, innerHeight])
            .padding(0.1);

        // Create axes
        const xAxis = svg.append("g")
            .attr("class", "axis")
            .attr("transform", `translate(0,${innerHeight})`)
            .call(d3.axisBottom(xScale).ticks(timePeriods).tickFormat(d => `T${d}`));

        const yAxis = svg.append("g")
            .attr("class", "axis")
            .call(d3.axisLeft(yScale));

        // Add axis labels
        svg.append("text")
            .attr("class", "axis-label")
            .attr("x", innerWidth / 2)
            .attr("y", innerHeight + 40)
            .style("text-anchor", "middle")
            .text("Time Periods");

        svg.append("text")
            .attr("class", "axis-label")
            .attr("transform", "rotate(-90)")
            .attr("x", -innerHeight / 2)
            .attr("y", -40)
            .style("text-anchor", "middle")
            .text("Stocks");

