            // Calculate percentage changes from initial price (100)
            const cells = heatmap.selectAll(".cell")
                .data(data.flatMap((stockData, stockIndex) =>
                    stockData.map((price, timeIndex) => ({
                        stock: stocks[stockIndex],
                        time: timeIndex,
                        price: price,
                        change: ((price - 100) / 100) * 100 // Percentage change
                    }))
                ));

            // Enter new cells
            cells.enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d.time))
                .attr("y", d => yScale(d.stock))
                .attr("width", innerWidth / timePeriods)
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.change / 100))
                .attr("stroke", "#fff")
                .attr("stroke-width", 0.5)
                .attr("rx", 2)
                .attr("ry", 2)
                .merge(cells)
