                stockData.shift();

                // Calculate new price based on last price
                const lastPrice = stockData.length > 0 ?
                    stockData[stockData.length - 1] :
                    100;

                // Generate random change between -1% and +1%
                const change = (Math.random() - 0.5) * 2;
                const newPrice = lastPrice * (1 + change / 100);

                stockData.push(newPrice);
                return stockData;
            });

            updateHeatmap(currentData);
        }, 2000);

