    <script>
        // Configuration
        const config = {
            width: 800,
            height: 600,
            margin: { top: 50, right: 50, bottom: 50, left: 80 },
            cellSize: 25,
            colors: ['#ffffff', '#ffffcc', '#ffeda0', '#fed976', '#feb24c',
                    '#fd8d3c', '#fc4e2a', '#e31a1c', '#bd0026', '#800026']
        };

        // Mock data generation
        function generateMockStockData(numStocks = 20, numTimestamps = 20) {
            const symbols = Array.from({ length: numStocks }, (_, i) => `AAPL${i + 1}`);
            const timestamps = Array.from({ length: numTimestamps }, (_, i) =>
                new Date(Date.now() - i * 300000) // 5 minutes apart
            );

            return symbols.flatMap(symbol =>
                timestamps.map(timestamp => ({
                    symbol,
                    price: 100 + Math.random() * 100,
                    change: (Math.random() - 0.5) * 10,
                    timestamp
                }))
            );
        }

        // Convert stock data to heatmap format
        function convertToHeatmapData(stockData) {
            // Group by timestamp and symbol to get the latest price for each symbol at each timestamp
            const groupedData = new Map();

            stockData.forEach(data => {
                const dateKey = data.timestamp.toISOString().split('T')[0];
                if (!groupedData.has(dateKey)) {
                    groupedData.set(dateKey, new Map());
                }
                groupedData.get(dateKey).set(data.symbol, data.price);
            });

            // Convert to heatmap format
            const heatmapData = [];
            const timestamps = Array.from(groupedData.keys()).sort().reverse(); // Most recent first
            const symbols = Array.from(new Set(stockData.map(d => d.symbol))).sort();

            timestamps.forEach((timestamp, x) => {
                symbols.forEach((symbol, y) => {
                    const price = groupedData.get(timestamp)?.get(symbol) || 0;
                    heatmapData.push({
                        x,
                        y,
                        value: price,
                        change: stockData.find(d => d.symbol === symbol && d.timestamp.toISOString().split('T')[0] === timestamp)?.change || 0,
                        symbol,
                        timestamp
                    });
                });
            });

            return heatmapData;
        }

