```javascript
// heatmap.js
document.addEventListener('DOMContentLoaded', function() {
    const width = 800;
    const height = 600;
    const margin = { top: 50, right: 50, bottom: 50, left: 100 };

    // Create SVG container
    const svg = d3.select("#heatmap-container")
        .append("svg")
        .attr("width", width)
        .attr("height", height);

    // Create a group for the heatmap and axes
    const g = svg.append("g")
        .attr("transform", `translate(${margin.left},${margin.top})`);

    // Define scales
    const xScale = d3.scaleBand()
        .range([0, width - margin.left - margin.right])
        .padding(0.05);

    const yScale = d3.scaleBand()
        .range([0, height - margin.top - margin.bottom])
        .padding(0.05);

    // Color scale
    const colorScale = d3.scaleSequential(d3.interpolateRdYlGn)
        .domain([-1, 1]);

    // Axes
    const xAxis = g.append("g")
        .attr("class", "axis axis-x")
        .attr("transform", `translate(0,${height - margin.top - margin.bottom})`);

    const yAxis = g.append("g")
        .attr("class", "axis axis-y");

    // Labels
    g.append("text")
        .attr("x", (width - margin.left - margin.right) / 2)
        .attr("y", height - margin.top - margin.bottom + 40)
        .style("text-anchor", "middle")
        .text("Time");

    g.append("text")
        .attr("transform", "rotate(-90)")
        .attr("x", -(height - margin.top - margin.bottom) / 2)
        .attr("y", -margin.left + 20)
        .style("text-anchor", "middle")
        .text("Stock");

    // Zoom and pan behavior
    const zoom = d3.zoom()
        .scaleExtent([0.5, 5])
        .on("zoom", (event) => {
            g.attr("transform", event.transform);
        });

    svg.call(zoom);

    // Initial data
    let data = generateData(10, 10);

    // Update heatmap
    function updateHeatmap(data) {
        // Update scales
        xScale.domain(d3.range(data[0].values.length));
        yScale.domain(d3.range(data.length));

        // Update axes
        xAxis.call(d3.axisBottom(xScale).tickFormat(i => `T${i}`));
        yAxis.call(d3.axisLeft(yScale).tickFormat(i => `Stock ${i}`));

        // Create cells
        const cells = g.selectAll(".cell")
            .data(data.flatMap((d, i) =>
                d.values.map((value, j) => ({ row: i, col: j, value }))
            ));

        cells.enter()
            .append("rect")
            .attr("class", "cell")
            .merge(cells)
            .attr("x", d => xScale(d.col))
            .attr("y", d => yScale(d.row))
            .attr("width", xScale.bandwidth())
            .attr("height", yScale.bandwidth())
            .attr("fill", d => colorScale(d.value))
            .on("mouseover", function(event, d) {
                d3.select(this).attr("stroke", "black").attr("stroke-width", 2);
                // Show tooltip
                tooltip.style("visibility", "visible")
                    .text(`Stock ${d.row}, Time ${d.col}: ${d.value}`);
            })
            .on("mouseout", function() {
                d3.select(this).attr("stroke", null);
                tooltip.style("visibility", "hidden");
            });

        cells.exit().remove();
    }

    // Tooltip
    const tooltip = d3.select("body")
        .append("div")
        .attr("class", "tooltip")
        .style("position", "absolute")
        .style("background-color", "white")
        .style("border", "solid")
        .style("border-width", "1px")
        .style("border-radius", "5px")
        .style("padding", "5px")
        .style("visibility", "hidden");

    // Generate random data
    function generateData(rows, cols) {
        return Array.from({ length: rows }, (_, i) =>
            ({
                id: `Stock ${i}`,
                values: Array.from({ length: cols }, () => Math.random() * 2 - 1)
            })
        );
    }

    // Initial update
    updateHeatmap(data);

    // Simulate real-time updates
    setInterval(() => {
        // Add a new column of data
        data = data.map(stock => ({
            ...stock,
            values: [...stock.values.slice(1), Math.random() * 2 - 1]
        }));
        updateHeatmap(data);
    }, 2000);
});
```

