Now, let's write the TypeScript code for the heatmap. We'll use D3.js to create the heatmap and implement zoom/pan interactions.

First, we'll define the types for our data:

```typescript
interface StockData {
    symbol: string;
    price: number;
    timestamp: Date;
}

interface HeatmapData {
    x: number; // row index
    y: number; // column index
    value: number; // price or change
    symbol: string;
}
```

Next, we'll create the heatmap visualization:

```typescript
// heatmap.ts
import * as d3 from 'd3';

// Configuration
const config = {
    width: 800,
    height: 600,
    margin: { top: 50, right: 50, bottom: 50, left: 50 },
    cellSize: 20,
    colors: ['#ffffff', '#ffffcc', '#ffeda0', '#fed976', '#feb24c', '#fd8d3c', '#fc4e2a', '#e31a1c', '#bd0026', '#800026']
};

// Mock data generation
function generateMockStockData(numStocks: number = 20, numTimestamps: number = 20): StockData[] {
    const symbols = Array.from({ length: numStocks }, (_, i) => `STK${i + 1}`);
    const timestamps = Array.from({ length: numTimestamps }, (_, i) => new Date(Date.now() - i * 60000));

    return symbols.flatMap(symbol =>
        timestamps.map(timestamp => ({
            symbol,
            price: 100 + Math.random() * 50,
            timestamp
        }))
    );
}

// Convert stock data to heatmap format
function convertToHeatmapData(stockData: StockData[]): HeatmapData[] {
    // Group by timestamp and symbol to get the latest price for each symbol at each timestamp
    const groupedData = new Map<string, Map<string, number>>();

    stockData.forEach(data => {
        const dateKey = data.timestamp.toISOString().split('T')[0];
        if (!groupedData.has(dateKey)) {
            groupedData.set(dateKey, new Map());
        }
        groupedData.get(dateKey)!.set(data.symbol, data.price);
    });

    // Convert to heatmap format
    const heatmapData: HeatmapData[] = [];
    const timestamps = Array.from(groupedData.keys()).sort();
    const symbols = Array.from(new Set(stockData.map(d => d.symbol))).sort();

    timestamps.forEach((timestamp, x) => {
        symbols.forEach((symbol, y) => {
            const price = groupedData.get(timestamp)?.get(symbol) || 0;
            heatmapData.push({ x, y, value: price, symbol });
        });
    });

    return heatmapData;
}

// Create heatmap
function createHeatmap(containerId: string, data: HeatmapData[]) {
    const { width, height, margin, cellSize, colors } = config;
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    const svg = d3.select(`#${containerId}`)
        .append('svg')
        .attr('width', width)
        .attr('height', height);

    const g = svg.append('g')
        .attr('transform', `translate(${margin.left},${margin.top})`);

    // Create scales
    const xScale = d3.scaleLinear()
        .domain([0, d3.max(data, d => d.x) || 0])
        .range([0, innerWidth]);

    const yScale = d3.scaleLinear()
        .domain([0, d3.max(data, d => d.y) || 0])
        .range([0, innerHeight]);

    // Create color scale
    const colorScale = d3.scaleQuantile<string>()
        .domain(data.map(d => d.value))
        .range(colors);

    // Create cells
    g.selectAll('.cell')
        .data(data)
        .enter()
        .append('rect')
        .attr('class', 'cell')
        .attr('x', d => xScale(d.x))
        .attr('y', d => yScale(d.y))
        .attr('width', cellSize)
        .attr('height', cellSize)
        .attr('fill', d => colorScale(d.value))
        .attr('stroke', '#ddd')
        .append('title')
        .text(d => `${d.symbol}: $${d.value.toFixed(2)}`);

    // Add axes
    const xAxis = d3.axisTop(xScale).ticks(5);
    const yAxis = d3.axisLeft(yScale).ticks(5);

    g.append('g')
        .attr('class', 'axis x-axis')
        .call(xAxis);

    g.append('g')
        .attr('class', 'axis y-axis')
        .call(yAxis);

    // Add zoom/pan behavior
    const zoom = d3.zoom()
        .scaleExtent([0.5, 10])
        .on('zoom', (event) => {
            g.attr('transform', event.transform);
        });

    svg.call(zoom);
}

// Update heatmap with new data
function updateHeatmap(data: HeatmapData[]) {
    const { cellSize, colors } = config;

    // Update color scale
    const colorScale = d3.scaleQuantile<string>()
        .domain(data.map(d => d.value))
        .range(colors);

    // Update cells
    d3.selectAll('.cell')
        .data(data)
        .attr('x', d => d.x * cellSize)
        .attr('y', d => d.y * cellSize)
        .attr('fill', d => colorScale(d.value))
        .select('title')
        .text(d => `${d.symbol}: $${d.value.toFixed(2)}`);
}

// Main function
function main() {
    const containerId = 'heatmap-container';

    // Generate initial data
    let stockData = generateMockStockData(20, 20);
    let heatmapData = convertToHeatmapData(stockData);

    // Create heatmap
    createHeatmap(containerId, heatmapData);

    // Simulate real-time updates
    setInterval(() => {
        // Generate new mock data
        stockData = generateMockStockData(20, 20);
        heatmapData = convertToHeatmapData(stockData);

        // Update heatmap
        updateHeatmap(heatmapData);
    }, 5000); // Update every 5 seconds
}

// Run main function when DOM is loaded
document.addEventListener('DOMContentLoaded', main);
```

