            const yScale = d3.scaleLinear()
                .domain([0, d3.max(data, d => d.y) || 0])
                .range([0, innerHeight]);

            // Create color scale
            const colorScale = d3.scaleQuantile()
                .domain(data.map(d => d.value))
                .range(colors);

            // Create cells
            g.selectAll('.cell')
                .data(data)
                .enter()
                .append('rect')
                .attr('class', 'cell')
                .attr('x', d => xScale(d.x))
                .attr('y', d => yScale(d.y))
                .attr('width', cellSize)
                .attr('height', cellSize)
                .attr('fill', d => colorScale(d.value))
                .attr('stroke', '#ddd')
                .append('title')
                .text(d => `${d.symbol}: $${d.value.toFixed(2)}`);

            // Add axes
            const xAxis = d3.axisTop(xScale).ticks(5);
            const yAxis = d3.axisLeft(yScale).ticks(5);

            g.append('g')
                .attr('class', 'axis x-axis')
                .call(xAxis);

            g.append('g')
                .attr('class', 'axis y-axis')
                .call(yAxis);

            // Add zoom/pan behavior
            const zoom = d3.zoom()
                .scaleExtent([0.5, 10])
                .on('zoom', (event) => {
                    g.attr('transform', event.transform);
                });

            svg.call(zoom);
        }

        // Update heatmap with new data
        function updateHeatmap(data) {
            const { cellSize, colors } = config;

            // Update color scale
            const colorScale = d3.scaleQuantile()
                .domain(data.map(d => d.value))
                .range(colors);

            // Update cells
            d3.selectAll('.cell')
                .data(data)
                .attr('x', d => d.x * cellSize)
                .attr('y', d => d.y * cellSize)
                .attr('fill', d => colorScale(d.value))
                .select('title')
                .text(d => `${d.symbol}: $${d.value.toFixed(2)}`);
        }

        // Main function
        function main() {
            const containerId = 'heatmap-container';

            // Generate initial data
            let stockData = generateMockStockData(20, 20);
            let heatmapData = convertToHeatmapData(stockData);

            // Create heatmap
            createHeatmap(containerId, heatmapData);

            // Simulate real-time updates
            setInterval(() => {
                // Generate new mock data
                stockData = generateMockStockData(20, 20);
                heatmapData = convertToHeatmapData(stockData);

                // Update heatmap
                updateHeatmap(heatmapData);
            }, 5000); // Update every 5 seconds
        }

        // Run main function when DOM is loaded
        document.addEventListener('DOMContentLoaded', main);
    </script>
</body>
</html>
```

