        <div class="status">Status: <span id="statusText">Ready</span></div>

        <div class="heatmap-container">
            <div id="heatmap"></div>
        </div>
    </div>

    <script>
        // Configuration
        const config = {
            width: 900,
            height: 600,
            margin: { top: 60, right: 50, bottom: 60, left: 80 },
            cellSize: 25,
            numRows: 20,
            numCols: 35,
            updateInterval: 1500, // ms
            minPrice: 50,
            maxPrice: 300,
            initialColorScheme: 'RdYlGn',
            colorSchemes: ['RdYlGn', 'RdBu', 'YlOrRd', 'PuOr', 'Spectral']
        };

        // State
        let isRunning = false;
        let updateIntervalId = null;
        let currentData = [];
        let colorScale = null;
        let svg = null;
        let g = null;
        let zoom = null;
        let currentColorSchemeIndex = 0;

        // Initialize the heatmap
        function initHeatmap() {
            // Clear previous heatmap
            d3.select("#heatmap").html("");

            // Calculate dimensions
            const width = config.width - config.margin.left - config.margin.right;
            const height = config.height - config.margin.top - config.margin.bottom;

            // Create SVG
            svg = d3.select("#heatmap")
                .append("svg")
                .attr("width", config.width)
                .attr("height", config.height)
                .attr("viewBox", `0 0 ${config.width} ${config.height}`);

            // Create main group with margins
            g = svg.append("g")
                .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

            // Create initial color scale
            updateColorScale();

            // Create axes
            const xAxis = g.append("g")
                .attr("class", "axis axis--x")
                .attr("transform", `translate(0,${height})`);

            const yAxis = g.append("g")
                .attr("class", "axis axis--y");

            // Add axis labels
            g.append("text")
                .attr("class", "axis-label")
                .attr("x", width / 2)
                .attr("y", height + 45)
                .style("text-anchor", "middle")
                .style("font-size", "14px")
                .text("Stocks");

            g.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -height / 2)
                .attr("y", -60)
                .style("text-anchor", "middle")
                .style("font-size", "14px")
                .text("Time");

            // Create zoom behavior
            zoom = d3.zoom()
                .scaleExtent([0.5, 8])
                .on("zoom", (event) => {
                    g.attr("transform", event.transform);
                });

            svg.call(zoom);

            // Initialize with empty data
            updateHeatmap([]);
            document.getElementById("statusText").textContent = "Ready";
        }

        // Update color scale based on current scheme
        function updateColorScale() {
            const scheme = config.colorSchemes[currentColorSchemeIndex];
            colorScale = d3.scaleSequential(d3[`interpolate${scheme}`])
                .domain([config.minPrice, config.maxPrice]);
        }

        // Generate random stock price data
        function generateRandomData() {
            const now = new Date();
            const data = [];

            for (let row = 0; row < config.numRows; row++) {
                for (let col = 0; col < config.numCols; col++) {
                    // Simulate price changes with some randomness
                    const basePrice = config.minPrice + Math.random() * (config.maxPrice - config.minPrice);
                    const change = (Math.random() - 0.3) * 15; // Random change between -4.5 and +10.5
                    const price = Math.max(config.minPrice, Math.min(config.maxPrice, basePrice + change));

                    data.push({
                        row: row,
                        col: col,
                        price: price.toFixed(2),
                        change: change.toFixed(2),
                        time: new Date(now.getTime() - (config.numRows - row) * 1000)
                    });
                }
            }

            return data;
        }

        // Update the heatmap with new data
        function updateHeatmap(data) {
            currentData = data;

            const width = config.width - config.margin.left - config.margin.right;
            const height = config.height - config.margin.top - config.margin.bottom;

            // Create scales for positioning
            const xScale = d3.scaleLinear()
                .domain([0, config.numCols])
                .range([0, width]);

            const yScale = d3.scaleLinear()
                .domain([0, config.numRows])
                .range([height, 0]);

            // Create cells
            const cells = g.selectAll(".cell")
                .data(data, d => `${d.row}-${d.col}`);

            // Enter new cells
            cells.enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d.col))
                .attr("y", d => yScale(d.row))
                .attr("width", config.cellSize)
                .attr("height", config.cellSize)
                .attr("fill", d => colorScale(d.price))
                .attr("stroke", "#e0e0e0")
                .attr("stroke-width", 0.5)
                .attr("rx", 2)
                .attr("ry", 2)
                .on("mouseover", function(event, d) {
                    // Show tooltip
                    const tooltip = d3.select("body").append("div")
                        .attr("class", "tooltip")
                        .style("position", "absolute")
                        .style("background-color", "white")
                        .style("border", "1px solid #ddd")
                        .style("padding", "8px")
                        .style("pointer-events", "none")
                        .style("opacity", 0)
                        .style("font-size", "12px")
                        .style("max-width", "200px");

                    tooltip.transition()
                        .duration(200)
                        .style("opacity", .95);

                    const changeColor = d.change > 0 ? "#e74c3c" : d.change < 0 ? "#2ecc71" : "#95a5a6";
                    const changeSymbol = d.change > 0 ? "▲" : d.change < 0 ? "▼" : "•";

                    tooltip.html(`
                        <div style="font-weight: bold; margin-bottom: 5px;">Stock ${d.row}-${d.col}</div>
                        <div style="margin: 3px 0;">
                            <span>Price: </span>
                            <span style="color: ${colorScale(d.price)}; font-weight: bold;">$${d.price}</span>
                        </div>
                        <div style="margin: 3px 0;">
                            <span>Change: </span>
                            <span style="color: ${changeColor}; font-weight: bold;">${changeSymbol} $${Math.abs(d.change)}</span>
                        </div>
                        <div style="margin: 3px 0; color: #7f8c8d;">
                            ${d.time.toLocaleTimeString()}
                        </div>
                    `)
                        .style("left", (event.pageX + 15) + "px")
                        .style("top", (event.pageY - 10) + "px");
                })
                .on("mouseout", function() {
                    d3.select(".tooltip").remove();
                });

            // Update existing cells
            cells
                .transition()
                .duration(800)
                .attr("x", d => xScale(d.col))
                .attr("y", d => yScale(d.row))
                .attr("fill", d => colorScale(d.price));

            // Remove old cells
            cells.exit().remove();

            // Update axes
            const xAxis = d3.axisBottom(xScale)
                .ticks(Math.max(5, Math.floor(config.numCols / 5)))
                .tickFormat(d => `S${d}`);

            const yAxis = d3.axisLeft(yScale)
                .ticks(Math.max(5, Math.floor(config.numRows / 5)))
                .tickFormat(d => `T-${config.numRows - d}s`);

            g.select(".axis--x")
                .transition()
                .duration(800)
                .call(xAxis);

            g.select(".axis--y")
                .transition()
                .duration(800)
                .call(yAxis);
        }

        // Start real-time updates
        function startUpdates() {
            if (isRunning) return;

            isRunning = true;
            document.getElementById("statusText").textContent = "Running";
            document.getElementById("startBtn").disabled = true;
            document.getElementById("stopBtn").disabled = false;

            updateIntervalId = setInterval(() => {
                const data = generateRandomData();
                updateHeatmap(data);
            }, config.updateInterval);
        }

        // Stop real-time updates
        function stopUpdates() {
            if (!isRunning) return;

            isRunning = false;
            clearInterval(updateIntervalId);
            document.getElementById("statusText").textContent = "Stopped";
            document.getElementById("startBtn").disabled = false;
            document.getElementById("stopBtn").disabled = true;
        }

        // Reset view to original position
        function resetView() {
            svg.transition()
                .duration(750)
                .call(zoom.transform, d3.zoomIdentity);
        }

        // Randomize color scheme
        function randomizeColorScheme() {
            currentColorSchemeIndex = Math.floor(Math.random() * config.colorSchemes.length);
            updateColorScale();
            updateHeatmap(currentData);
        }

        // Initialize the application
        document.addEventListener("DOMContentLoaded", () => {
            initHeatmap();

            // Set up button event listeners
            document.getElementById("startBtn").addEventListener("click", startUpdates);
            document.getElementById("stopBtn").addEventListener("click", stopUpdates);
            document.getElementById("resetBtn").addEventListener("click", resetView);
            document.getElementById("randomizeBtn").addEventListener("click", randomizeColorScheme);

            // Start with stopped state
            stopUpdates();
        });
    </script>
</body>
</html>
