            updateInterval: 2000 // ms between updates
        };

        // Initialize heatmap
        function initHeatmap() {
            const container = d3.select('#heatmap-container');
            const width = config.cellSize * config.timePeriods + config.margin.left + config.margin.right;
            const height = config.cellSize * config.stocks.length + config.margin.top + config.margin.bottom;

            // Create SVG with container
            const svg = container.append('svg')
                .attr('width', width)
                .attr('height', height)
                .append('g')
                .attr('transform', `translate(${config.margin.left},${config.margin.top})`);

            // Create main heatmap group that will be transformed during zoom/pan
            const heatmapGroup = svg.append('g').attr('class', 'heatmap-group');

            // Create scales
            const xScale = d3.scaleBand()
                .domain(d3.range(config.timePeriods))
                .range([0, config.timePeriods * config.cellSize])
                .padding(0.05);

            const yScale = d3.scaleBand()
                .domain(config.stocks)
                .range([0, config.stocks.length * config.cellSize])
                .padding(0.05);

            // Color scale for price changes (percentage)
            const colorScale = d3.scaleLinear()
                .domain([-10, -2, 0, 2, 10]) // -10% to +10% change
                .range(config.colorRange)
                .interpolate(d3.interpolateRgb);

            // Create axes
            const xAxis = svg.append('g')
                .attr('class', 'x-axis')
                .attr('transform', `translate(0,${config.stocks.length * config.cellSize})`)
                .call(d3.axisBottom(xScale)
                    .tickFormat(i => `T${i}`)
                    .tickSizeOuter(0));

            const yAxis = svg.append('g')
                .attr('class', 'y-axis')
                .call(d3.axisLeft(yScale)
                    .tickSizeOuter(0));

            // Add axis labels
            svg.append('text')
                .attr('class', 'axis-label')
                .attr('x', -config.margin.left + 10)
                .attr('y', -20)
