                .text('Time Periods');

            // Tooltip
            const tooltip = d3.select('body').append('div')
                .attr('class', 'tooltip')
                .style('position', 'absolute')
                .style('background', 'rgba(0,0,0,0.8)')
                .style('color', 'white')
                .style('padding', '5px 10px')
                .style('border-radius', '4px')
                .style('pointer-events', 'none')
                .style('opacity', 0);

            // Create zoom behavior
            const zoom = d3.zoom()
                .scaleExtent([0.5, 8])
                .on('zoom', (event) => {
                    heatmapGroup.attr('transform', event.transform);
                });

            container.call(zoom);

            // Store references
            return {
                svg: svg,
                heatmapGroup: heatmapGroup,
                xScale: xScale,
                yScale: yScale,
                colorScale: colorScale,
                tooltip: tooltip,
                data: generateMockData()
            };
        }

        // Generate initial mock data
        function generateMockData() {
            const data = [];
            const basePrices = {
                'AAPL': 175,
                'MSFT': 320,
                'GOOGL': 2600,
                'AMZN': 3300,
                'META': 470,
                'TSLA': 720,
                'NVDA': 850,
                'JPM': 160,
                'V': 240,
                'WMT': 165
            };

            for (let i = 0; i < config.timePeriods; i++) {
                config.stocks.forEach(stock => {
                    const basePrice = basePrices[stock];
                    // Simulate price change with some correlation between stocks
                    const baseChange = (Math.random() - 0.5) * 2;
                    // Add some correlation (market movement)
                    const marketChange = (Math.random() - 0.5) * 1.5;
                    const stockChange = baseChange + marketChange * 0.3;

                    const price = basePrice + stockChange * 10;
                    const changePercent = (stockChange * 10 / basePrice) * 100;

                    data.push({
                        stock: stock,
                        time: i,
                        price: price.toFixed(2),
                        changePercent: changePercent.toFixed(2)
                    });
                });
            }
            return data;
        }

        // Render heatmap
        function renderHeatmap(state) {
            const { heatmapGroup, xScale, yScale, colorScale, tooltip, data } = state;

            // Create cells
            heatmapGroup.selectAll('.heat-cell')
                .data(data, d => `${d.stock}-${d.time}`)
                .join(
                    enter => enter.append('rect')
                        .attr('class', 'heat-cell')
                        .attr('x', d => xScale(d.time))
                        .attr('y', d => yScale(d.stock))
                        .attr('width', xScale.bandwidth())
                        .attr('height', yScale.bandwidth())
                        .attr('fill', d => colorScale(d.changePercent))
                        .attr('rx', 2)
                        .attr('ry', 2)
                        .style('opacity', 0)
                        .on('mouseover', function(event, d) {
                            tooltip.transition()
                                .duration(200)
                                .style('opacity', .9);
                            tooltip.html(`
                                <strong>${d.stock}</strong><br/>
                                Time: T${d.time}<br/>
                                Price: $${d.price}<br/>
                                Change: ${d.changePercent > 0 ? '+' : ''}${d.changePercent}%
                            `)
                                .style('left', (event.pageX + 10) + 'px')
                                .style('top', (event.pageY - 28) + 'px');
                        })
                        .on('mouseout', function() {
                            tooltip.transition()
                                .duration(500)
                                .style('opacity', 0);
                        })
                        .call(enter => enter.transition()
                            .duration(500)
                            .style('opacity', 1)),
                    update => update
                        .attr('x', d => xScale(d.time))
                        .attr('y', d => yScale(d.stock))
                        .attr('width', xScale.bandwidth())
                        .attr('height', yScale.bandwidth())
                        .attr('fill', d => colorScale(d.changePercent))
                        .on('mouseover', function(event, d) {
                            tooltip.transition()
                                .duration(200)
                                .style('opacity', .9);
                            tooltip.html(`
                                <strong>${d.stock}</strong><br/>
                                Time: T${d.time}<br/>
                                Price: $${d.price}<br/>
                                Change: ${d.changePercent > 0 ? '+' : ''}${d.changePercent}%
                            `)
                                .style('left', (event.pageX + 10) + 'px')
                                .style('top', (event.pageY - 28) + 'px');
                        })
                        .on('mouseout', function() {
                            tooltip.transition()
                                .duration(500)
                                .style('opacity', 0);
                        }),
                    exit => exit
                        .transition()
                        .duration(500)
                        .style('opacity', 0)
                        .remove()
                );
        }

        // Update data with new random changes
        function updateData(state) {
            const { data } = state;

            // Update each data point with new price changes
            data.forEach(d => {
                // Get the stock's base price from the first occurrence
                const basePrice = parseFloat(d.price);
                const change = (Math.random() - 0.5) * 2;
                const newPrice = basePrice + change * 10;
                d.price = newPrice.toFixed(2);
                d.changePercent = (change * 10 / basePrice * 100).toFixed(2);
            });

            return data;
        }

        // Main function
        function main() {
            const state = initHeatmap();
            renderHeatmap(state);

            // Simulate real-time updates
            setInterval(() => {
                state.data = updateData(state);
                renderHeatmap(state);
            }, config.updateInterval);
        }

        // Start the application
        main();
    </script>
</body>
</html>
```

