```javascript
// Configuration
const config = {
  width: 1000,
  height: 600,
  margin: { top: 40, right: 20, bottom: 40, left: 60 },
  cellSize: 15,
  colors: ["#1a9850", "#91cf60", "#fee08b", "#fc8d59", "#d73027"],
  maxChanges: { min: -15, max: 15 }
};

// DOM elements
const container = d3.select("#heatmap-container");
const svg = container.append("svg")
  .attr("width", config.width)
  .attr("height", config.height);

const g = svg.append("g")
  .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

const tooltip = d3.select("body").append("div")
  .attr("class", "tooltip");

// Zoom and pan setup
const zoom = d3.zoom()
  .scaleExtent([1, 8])
  .on("zoom", (event) => {
    g.attr("transform", event.transform);
  });

svg.call(zoom);

// Add reset zoom button
d3.select("#reset-zoom").on("click", () => {
  svg.transition()
    .duration(750)
    .call(zoom.transform, d3.zoomIdentity);
});

// Color scale for heatmap
const colorScale = d3.scaleLinear()
  .domain([config.maxChanges.min, 0, config.maxChanges.max])
  .range(config.colors);

// Axis scales
const xScale = d3.scaleLinear().range([0, config.width - config.margin.left - config.margin.right]);
const yScale = d3.scaleBand().range([0, config.height - config.margin.top - config.margin.bottom]);

// Stock data structure
let stockData = {
  stocks: ["AAPL", "MSFT", "GOOGL", "AMZN", "META", "TSLA", "NVDA", "INTC"],
  timeIntervals: Array.from({ length: 60 }, (_, i) => new Date(Date.now() - (60 - i) * 60000)), // Last 60 minutes
  values: []
};

// Generate initial data structure
function initializeData() {
  stockData.values = stockData.stocks.map(stock => ({
    stock,
    changes: Array(stockData.timeIntervals.length).fill(0)
  }));
}

// Simulate WebSocket connection
function setupWebSocket() {
  // In a real app, you would connect to a WebSocket endpoint
  // For this demo, we'll simulate updates
  const socket = {
    close: () => console.log("Connection closed"),
    send: () => {}
  };

  // Simulate receiving data every 2 seconds
  const interval = setInterval(() => {
    updateStockPrices();
  }, 2000);

  // Update status
  d3.select("#status").text("Connected (Simulated)");

  return {
    close: () => {
      clearInterval(interval);
      d3.select("#status").text("Disconnected");
    }
  };
}

// Update stock prices with random changes
function updateStockPrices() {
  stockData.values.forEach(stock => {
    // Random change between -2 and +2
    const change = (Math.random() * 4 - 2).toFixed(2);
    stock.changes.push(parseFloat(change));
    stock.changes.shift(); // Remove oldest value to maintain array length
  });

  renderHeatmap();
}

// Render the heatmap
function renderHeatmap() {
  // Update x scale domain based on current data
  xScale.domain([0, stockData.timeIntervals.length - 1]);
  yScale.domain(stockData.stocks).range([0, stockData.stocks.length * config.cellSize]);

  // Update axes if they exist
  g.select(".x-axis").remove();
  g.select(".y-axis").remove();

  // Add X axis
  g.append("g")
    .attr("class", "x-axis")
    .attr("transform", `translate(0,${yScale.range()[1]})`)
    .call(d3.axisBottom(xScale)
      .tickFormat(i => {
        const date = stockData.timeIntervals[i];
        return `${date.getHours()}:${date.getMinutes().toString().padStart(2, '0')}`;
      })
      .ticks(5));

  // Add Y axis
  g.append("g")
    .attr("class", "y-axis")
    .call(d3.axisLeft(yScale));

  // Add axis labels
  g.select(".x-axis").append("text")
    .attr("x", config.width - config.margin.left - config.margin.right)
    .attr("y", 30)
    .attr("fill", "#000")
    .attr("text-anchor", "end")
    .text("Time");

  g.select(".y-axis").append("text")
    .attr("transform", "rotate(-90)")
    .attr("y", -40)
    .attr("x", -10)
    .attr("dy", "1em")
    .attr("fill", "#000")
    .text("Stock");

  // Create cells
  const cells = g.selectAll(".cell")
    .data(stockData.values.flatMap((stock, stockIndex) =>
      stock.changes.map((change, timeIndex) => ({
        stock: stock.stock,
        time: stockData.timeIntervals[timeIndex],
        change: change,
        x: timeIndex,
        y: stockIndex
      }))
    ));

  // Enter new cells
  cells.enter()
    .append("rect")
    .attr("class", "cell")
    .attr("x", d => xScale(d.x))
    .attr("y", d => yScale(d.stock))
    .attr("width", config.cellSize)
    .attr("height", config.cellSize)
    .attr("fill", d => colorScale(d.change))
    .attr("stroke", "#fff")
    .attr("stroke-width", 0.5)
    .on("mouseover", function(event, d) {
      tooltip.style("opacity", 0.9)
        .html(`
          <strong>${d.stock}</strong><br/>
          Time: ${d.time.toLocaleTimeString()}<br/>
          Change: ${d.change.toFixed(2)}%
        `)
        .style("left", (event.pageX + 10) + "px")
        .style("top", (event.pageY - 28) + "px");
    })
    .on("mouseout", () => {
      tooltip.style("opacity", 0);
    })
    .merge(cells)
    .transition()
    .duration(500)
    .attr("x", d => xScale(d.x))
    .attr("y", d => yScale(d.stock))
    .attr("fill", d => colorScale(d.change));

  // Remove old cells
  cells.exit().remove();
}

// Initialize and render
initializeData();
renderHeatmap();
const socketSimulator = setupWebSocket();

// Clean up on page unload
window.addEventListener("beforeunload", () => {
  socketSimulator.close();
});
