                .domain(d3.range(config.timePeriods))
                .range([0, config.timePeriods * config.cellSize])
                .padding(0.1);

            const yScale = d3.scaleBand()
                .domain(config.stocks)
                .range([0, config.stocks.length * config.cellSize])
                .padding(0.1);

            // Color scale for price changes
            const colorScale = d3.scaleLinear()
                .domain([-5, 0, 5]) // -5% to +5% change
                .range(config.colors);

            // Create axes
            const xAxis = svg.append('g')
                .attr('class', 'x-axis')
                .attr('transform', `translate(0,${config.stocks.length * config.cellSize})`)
                .call(d3.axisBottom(xScale).tickFormat(i => `T${i}`));

            const yAxis = svg.append('g')
                .attr('class', 'y-axis')
                .call(d3.axisLeft(yScale));

            // Add labels
