        { symbol: 'WMT', initialPrice: 140, price: 140 },
        { symbol: 'INTC', initialPrice: 30, price: 30 },
        { symbol: 'CSCO', initialPrice: 50, price: 50 },
        { symbol: 'DIS', initialPrice: 180, price: 180 },
        { symbol: 'PFE', initialPrice: 40, price: 40 },
        { symbol: 'KO', initialPrice: 55, price: 55 },
        { symbol: 'PEP', initialPrice: 150, price: 150 },
        { symbol: 'XOM', initialPrice: 80, price: 80 },
        { symbol: 'CVX', initialPrice: 120, price: 120 },
        { symbol: 'BA', initialPrice: 200, price: 200 },
        { symbol: 'MMM', initialPrice: 180, price: 180 }
    ];

    // Color scale for price changes
    const colorScale = d3.scaleLinear()
        .domain([-5, 0, 5]) // -5% to +5% change
        .range(['#ff4d4d', '#ffffff', '#4CAF50']); // red to white to green

    // SVG container dimensions
    const width = GRID_SIZE * CELL_SIZE;
    const height = GRID_SIZE * CELL_SIZE;

    // Create SVG container
    const svg = d3.select('#heatmap')
        .append('svg')
        .attr('width', width)
        .attr('height', height)
        .attr('viewBox', [0, 0, width, height])
        .attr('style', 'max-width: 100%; height: auto;');

    // Create a group for the heatmap cells
    const heatmapGroup = svg.append('g');

    // Create grid cells
    const cells = heatmapGroup.selectAll('rect')
        .data(stocks)
        .enter()
        .append('rect')
        .attr('x', (d, i) => (i % GRID_SIZE) * CELL_SIZE)
        .attr('y', (d, i) => Math.floor(i / GRID_SIZE) * CELL_SIZE)
        .attr('width', CELL_SIZE - 1)
        .attr('height', CELL_SIZE - 1)
        .attr('fill', d => {
            // Initial color based on price change (0% for now)
            const priceChangePercent = ((d.price - d.initialPrice) / d.initialPrice) * 100;
            return colorScale(priceChangePercent);
        })
        .attr('stroke', '#ddd')
        .attr('stroke-width', 0.5);

    // Add text labels
    heatmapGroup.selectAll('text')
        .data(stocks)
        .enter()
        .append('text')
        .attr('x', (d, i) => (i % GRID_SIZE) * CELL_SIZE + CELL_SIZE / 2)
        .attr('y', (d, i) => Math.floor(i / GRID_SIZE) * CELL_SIZE + CELL_SIZE / 2)
        .attr('text-anchor', 'middle')
        .attr('dominant-baseline', 'middle')
        .attr('font-size', '10px')
        .text(d => d.symbol);

    // Zoom and pan setup
    const zoom = d3.zoom()
        .scaleExtent([0.5, 5]) // Limit zoom scale
        .on('zoom', (event) => {
            heatmapGroup.attr('transform', event.transform);
        });

    svg.call(zoom);

    // Real-time updates simulation
    let updateInterval;
    const startBtn = d3.select('#startBtn');
    const stopBtn = d3.select('#stopBtn');
    const statusText = d3.select('#status');

    function updatePrices() {
        // Simulate price changes
        stocks.forEach(stock => {
            const changePercent = (Math.random() * 10 - 5).toFixed(2); // Random change between -5% and +5%
            const changeFactor = 1 + changePercent / 100;
            stock.price *= changeFactor;
        });

        // Update cell colors
        cells.attr('fill', d => {
            const priceChangePercent = ((d.price - d.initialPrice) / d.initialPrice) * 100;
            return colorScale(priceChangePercent);
        });
    }

    startBtn.on('click', function() {
        if (!updateInterval) {
            updateInterval = setInterval(updatePrices, UPDATE_INTERVAL);
            statusText.text('Running');
        }
    });

    stopBtn.on('click', function() {
        if (updateInterval) {
            clearInterval(updateInterval);
            updateInterval = null;
            statusText.text('Stopped');
        }
    });
});
