```typescript
import * as d3 from 'd3';

// Mock data: an array of stock prices over time
interface StockData {
    date: Date;
    price: number;
    stock: string;
}

// Mock data generator
function generateMockData(days: number = 30, stocks: number = 10): StockData[] {
    const data: StockData[] = [];
    const stockNames = Array.from({ length: stocks }, (_, i) => `Stock ${i + 1}`);

    for (let i = 0; i < days; i++) {
        const date = new Date();
        date.setDate(date.getDate() - (days - i));

        for (const stock of stockNames) {
            // Simulate price changes
            const basePrice = 100 + Math.random() * 50;
            const change = (Math.random() - 0.5) * 10;
            const price = basePrice + change;
            data.push({ date, price, stock });
        }
    }

    return data;
}

// Heatmap dimensions
const width = 800;
const height = 600;
const margin = { top: 50, right: 20, bottom: 50, left: 60 };

// Create SVG container
const svg = d3.select("#heatmap-container")
    .append("svg")
    .attr("width", width)
    .attr("height", height);

// Add a group for the heatmap with margins
const g = svg.append("g")
    .attr("transform", `translate(${margin.left},${margin.top})`);

// Define scales
const xScale = d3.scaleTime()
    .range([0, width - margin.left - margin.right]);

const yScale = d3.scaleBand()
    .range([0, height - margin.top - margin.bottom]);

const colorScale = d3.scaleLinear<string>()
    .range(["#ffffff", "#ff0000"]); // White to red

// Define axes
const xAxis = d3.axisBottom(xScale);
const yAxis = d3.axisLeft(yScale);

// Add axes to the SVG
const xAxisGroup = g.append("g")
    .attr("class", "x-axis")
    .attr("transform", `translate(0,${height - margin.top - margin.bottom})`);

const yAxisGroup = g.append("g")
    .attr("class", "y-axis");

// Add axis labels
g.append("text")
    .attr("x", (width - margin.left - margin.right) / 2)
    .attr("y", height - margin.top - margin.bottom + 40)
    .style("text-anchor", "middle")
    .text("Date");

g.append("text")
    .attr("transform", "rotate(-90)")
    .attr("x", -(height - margin.top - margin.bottom) / 2)
    .attr("y", -40)
    .style("text-anchor", "middle")
    .text("Stock");

// Zoom and pan behavior
const zoom = d3.zoom<SVGSVGElement, unknown>()
    .scaleExtent([1, 8])
    .translateExtent([[0, 0], [width, height]])
    .extent([[0, 0], [width, height]])
    .on("zoom", (event) => {
        g.attr("transform", event.transform);
    });

svg.call(zoom);

// Function to update the heatmap
function updateHeatmap(data: StockData[]) {
    // Group data by date and stock
    const nestedData = d3.group(data, d => d.date.toISOString().split('T')[0], d => d.stock);

    // Extract unique dates and stocks
    const dates = Array.from(new Set(data.map(d => d.date.toISOString().split('T')[0])));
    const stocks = Array.from(new Set(data.map(d => d.stock)));

    // Update scales
    xScale.domain(d3.extent(dates, d => new Date(d)) as [Date, Date]);
    yScale.domain(stocks);
    colorScale.domain([d3.min(data, d => d.price) || 0, d3.max(data, d => d.price) || 1]);

    // Create a matrix of prices for the heatmap
    const matrix: number[][] = [];
    for (const stock of stocks) {
        const row: number[] = [];
        for (const date of dates) {
            const price = nestedData.get(date)?.get(stock)?.[0]?.price || 0;
            row.push(price);
        }
        matrix.push(row);
    }

    // Remove old heatmap cells
    g.selectAll(".heatmap-cell").remove();

    // Add new heatmap cells
    const cellSize = (width - margin.left - margin.right) / dates.length;
    const rowHeight = (height - margin.top - margin.bottom) / stocks.length;

    g.selectAll(".heatmap-cell")
        .data(matrix.flatMap((row, i) =>
            row.map((price, j) => ({ stock: stocks[i], date: dates[j], price }))
        ))
        .enter()
        .append("rect")
        .attr("class", "heatmap-cell")
        .attr("x", (_, i) => (i % dates.length) * cellSize)
        .attr("y", (_, i) => Math.floor(i / dates.length) * rowHeight)
        .attr("width", cellSize)
        .attr("height", rowHeight)
        .attr("fill", d => colorScale(d.price))
        .append("title")
        .text(d => `${d.stock} on ${d.date}: $${d.price.toFixed(2)}`);

    // Update axes
    xAxisGroup.call(xAxis);
    yAxisGroup.call(yAxis);
}

// Initial data load
let data = generateMockData(30, 10);
updateHeatmap(data);

// Simulate real-time updates
setInterval(() => {
    data = generateMockData(30, 10);
    updateHeatmap(data);
}, 5000);
```

### Explanation:
1. **Mock Data**: The `generateMockData` function creates random stock data for demonstration.
2. **SVG Setup**: We create an SVG container and a group (`g`) with margins.
3. **Scales**: We define scales for the x-axis (time), y-axis (stocks), and color (price).
4. **Axes**: We add x and y axes to the SVG.
5. **Zoom/Pan**: We use D3's zoom behavior to enable zoom and pan interactions.
6. **Heatmap Update**: The `updateHeatmap` function processes the data, creates a matrix of prices, and renders the heatmap as a grid of rectangles colored by price.
7. **Real-time Updates**: We simulate real-time updates by regenerating mock data every 5 seconds.

