                        .attr("y", d => yScale(d.stock))
                        .attr("width", xScale(1) - xScale(0))
                        .attr("height", yScale.bandwidth())
                        .attr("fill", d => colorScale(d.price))
                        .call(enter => enter.transition()
                            .duration(500)
                            .attr("fill", d => colorScale(d.price))),
                    update => update
                        .call(update => update.transition()
                            .duration(500)
                            .attr("x", d => xScale(d.hour))
                            .attr("y", d => yScale(d.stock))
                            .attr("width", xScale(1) - xScale(0))
                            .attr("height", yScale.bandwidth())
                            .attr("fill", d => colorScale(d.price))),
                    exit => exit
                        .call(exit => exit.transition()
                            .duration(500)
                            .attr("width", 0)
                            .remove())
                );

            // Remove old groups
            groups.exit().remove();
        }

        // Generate initial data
        function generateInitialData() {
            const stocks = d3.range(10).map(i => `Stock ${i + 1}`);
            const hours = d3.range(24);
            const data = [];

            stocks.forEach(stock => {
                hours.forEach(hour => {
                    data.push({
                        stock,
                        hour,
                        price: 30 + Math.random() * 70 // Base price between 30-100
                    });
                });
            });

            return data;
        }

        // Simulate real-time updates
        function updateData() {
            currentTime = new Date();
            data = data.map(d => {
                // Simulate price changes with some trend
                const baseChange = Math.sin(currentTime.getTime() / 2000) * 5;
                const randomChange = (Math.random() - 0.5) * 8;
                const newPrice = d.price + baseChange + randomChange;

                return {
                    ...d,
                    price: Math.max(0, Math.min(100, newPrice))
                };
            });
            renderHeatmap(data);
        }

        // Initial render
        renderHeatmap(data);

        // Update data every second to simulate real-time
        setInterval(updateData, 1000);

        // Add tooltip
        const tooltip = d3.select("body").append("div")
            .attr("class", "tooltip")
            .style("position", "absolute")
            .style("background-color", "rgba(0,0,0,0.7)")
            .style("color", "white")
            .style("padding", "5px 10px")
            .style("border-radius", "5px")
            .style("pointer-events", "none")
            .style("opacity", 0);

        svg.selectAll(".heatmap-cell")
            .on("mouseover", function(event, d) {
                tooltip.transition()
                    .duration(200)
                    .style("opacity", .9);
                tooltip.html(`<strong>${d.stock}</strong><br/>Hour: ${d.hour}:00<br/>Price: $${d.price.toFixed(2)}`)
                    .style("left", (event.pageX + 10) + "px")
                    .style("top", (event.pageY - 28) + "px");
            })
            .on("mouseout", function() {
                tooltip.transition()
                    .duration(500)
                    .style("opacity", 0);
            });
    </script>
</body>
</html>
