      stroke: #fff;
      stroke-width: 0.5px;
      cursor: pointer;
    }
    .axis text {
      font-size: 10px;
    }
    .axis path,
    .axis line {
      fill: none;
      stroke: #000;
      shape-rendering: crispEdges;
    }
  </style>
</head>
<body>
  <div id="heatmap-container">
    <svg id="heatmap"></svg>
  </div>

  <script>
    // Configuration
    const WIDTH = 800;
    const HEIGHT = 600;
    const CELL_SIZE = 20;
    const GRID_SIZE = {
      rows: Math.floor(HEIGHT / CELL_SIZE),
      cols: Math.floor(WIDTH / CELL_SIZE)
    };
    const COLORS = {
      low: '#1a9641',   // Green (low price)
      mid: '#f7f7f7',   // White (mid price)
      high: '#d7191c'   // Red (high price)
    };

    // Initialize SVG and scales
    const svg = d3.select("#heatmap")
      .attr("width", WIDTH)
      .attr("height", HEIGHT);

    const xScale = d3.scaleLinear()
      .domain([0, GRID_SIZE.cols])
      .range([0, WIDTH]);

    const yScale = d3.scaleLinear()
      .domain([0, GRID_SIZE.rows])
      .range([0, HEIGHT]);

    // Color scale for heatmap
    const colorScale = d3.scaleLinear()
      .domain([0, 0.5, 1])
      .range([COLORS.low, COLORS.mid, COLORS.high]);

    // Create axes (optional, for context)
    const xAxis = svg.append("g")
      .attr("class", "axis")
      .attr("transform", `translate(0, ${HEIGHT})`)
      .call(d3.axisBottom(xScale).ticks(5));

    const yAxis = svg.append("g")
      .attr("class", "axis")
      .call(d3.axisLeft(yScale).ticks(5));

    // Generate initial random data
    let data = Array.from({ length: GRID_SIZE.rows }, () =>
      Array.from({ length: GRID_SIZE.cols }, () => Math.random())
    );

    // Create heatmap cells
    const cells = svg.selectAll(".cell")
      .data(data.flat())
      .enter()
      .append("rect")
      .attr("class", "cell")
      .attr("x", (_, i) => (i % GRID_SIZE.cols) * CELL_SIZE)
      .attr("y", (_, i) => Math.floor(i / GRID_SIZE.cols) * CELL_SIZE)
      .attr("width", CELL_SIZE)
      .attr("height", CELL_SIZE)
      .attr("fill", (d) => colorScale(d));

    // Zoom and pan behavior
    const zoom = d3.zoom()
      .scaleExtent([0.5, 8])
      .on("zoom", (event) => {
        cells.attr("transform", event.transform);
        xAxis.call(d3.axisBottom(xScale).scale(event.transform.rescaleX(xScale)));
        yAxis.call(d3.axisLeft(yScale).scale(event.transform.rescaleY(yScale)));
      });

    svg.call(zoom);

    // Simulate real-time updates
    function updateHeatmap() {
      // Shift data (simulate new stock prices)
      data.forEach(row => {
        row.unshift(Math.random());
        row.pop();
      });

      // Update cell colors
      cells
        .data(data.flat())
        .transition()
        .duration(500)
        .attr("fill", (d) => colorScale(d));
    }

    // Initial update + periodic refresh
    updateHeatmap();
    setInterval(updateHeatmap, 1000);
  </script>
</body>
</html>
