            xScale.domain(timePeriods);
            yScale.domain(stocks);

            // Update axes
            g.select(".x-axis").call(xAxis);
            g.select(".y-axis").call(yAxis);

            // Create cells
            const cells = g.selectAll(".cell")
                .data(data.flatMap(d =>
                    d.values.map((value, i) => ({
                        stock: d.stock,
                        time: `T${i + 1}`,
                        value: value
                    }))
                ));

            // Enter new cells
            cells.enter()
                .append("rect")
                .attr("class", "cell")
                .merge(cells)
                .attr("x", d => xScale(d.time))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.value))
                .on("mouseover", function(event, d) {
                    d3.select(this).attr("stroke", "black").attr("stroke-width", 2);
                    // Show tooltip
                    tooltip.style("visibility", "visible")
                        .text(`${d.stock} at ${d.time}: $${d.value}`);
                })
                .on("mouseout", function() {
                    d3.select(this).attr("stroke", "none");
                    tooltip.style("visibility", "hidden");
                });

            // Exit old cells
            cells.exit().remove();

            // Update color scale domain based on current data
            const minValue = d3.min(data.flatMap(d => d.values));
            const maxValue = d3.max(data.flatMap(d => d.values));
            colorScale.domain([minValue, maxValue]);
        }

        // Tooltip
        const tooltip = d3.select("body")
            .append("div")
            .style("position", "absolute")
            .style("background-color", "white")
            .style("border", "1px solid black")
            .style("padding", "5px")
            .style("visibility", "hidden")
            .style("pointer-events", "none");

        // Initial render
        updateHeatmap(stockData);

        // Simulate real-time updates
        setInterval(() => {
            // Update stock data with random changes
            stockData = stockData.map(stock => ({
                stock: stock.stock,
                values: stock.values.map(value => value + (Math.random() * 10 - 5)) // Random change between -5 and +5
            }));

            updateHeatmap(stockData);
        }, 2000);
    </script>
</body>
</html>
```

This code creates a minimal interactive stock price heatmap with:
1. A heatmap showing stock prices for 5 stocks over 10 time periods
2. Real-time updates every 2 seconds with simulated price changes
3. Zoom/pan interactions using D3.js's built-in zoom behavior
4. Tooltips showing detailed information on hover
5. Color scale that adjusts based on the current data range

