### 4. Backend Routes (`routes/boards.js`)

```javascript
const express = require('express');
const router = express.Router();
const Board = require('../models/Board');
const Column = require('../models/Column');
const Task = require('../models/Task');

// Get all boards
router.get('/', async (req, res) => {
  try {
    const boards = await Board.find().populate('columns');
    res.json(boards);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

// Create a new board
router.post('/', async (req, res) => {
  const board = new Board({
    name: req.body.name || 'New Board'
  });

  try {
    const newBoard = await board.save();
    res.status(201).json(newBoard);
  } catch (err) {
    res.status(400).json({ message: err.message });
  }
});

// Get a single board
router.get('/:id', async (req, res) => {
  try {
    const board = await Board.findById(req.params.id).populate({
      path: 'columns',
      populate: {
        path: 'tasks'
      }
    });
    if (!board) return res.status(404).json({ message: 'Board not found' });
    res.json(board);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

// Create a new column in a board
router.post('/:id/columns', async (req, res) => {
  const column = new Column({
    title: req.body.title || 'New Column',
    board: req.params.id
  });

  try {
    const newColumn = await column.save();
    await Board.findByIdAndUpdate(req.params.id, {
      $push: { columns: newColumn._id }
    });
    res.status(201).json(newColumn);
  } catch (err) {
    res.status(400).json({ message: err.message });
  }
});

// Create a new task in a column
router.post('/columns/:id/tasks', async (req, res) => {
  const task = new Task({
    title: req.body.title || 'New Task',
    description: req.body.description || '',
    column: req.params.id
  });

  try {
    const newTask = await task.save();
    await Column.findByIdAndUpdate(req.params.id, {
      $push: { tasks: newTask._id }
    });
    res.status(201).json(newTask);
  } catch (err) {
    res.status(400).json({ message: err.message });
  }
});

module.exports = router;
```

