import React from 'react';
import { useDrag } from 'react-dnd';
import { Task as TaskType } from '../types';

interface TaskProps {
  task: TaskType;
  columnId: string;
  onDrop: (taskId: string, newColumnId: string) => void;
}

const Task: React.FC<TaskProps> = ({ task, columnId, onDrop }) => {
  const [{ isDragging }, drag] = useDrag(() => ({
    type: 'TASK',
    item: { taskId: task._id, currentColumnId: columnId },
    end: (item, monitor) => {
      if (!monitor.didDrop()) {
        return;
      }
      const dropResult = monitor.getDropResult();
      if (dropResult && dropResult.columnId !== columnId) {
        onDrop(task._id, dropResult.columnId);
      }
    },
    collect: (monitor) => ({
      isDragging: !!monitor.isDragging(),
    }),
  }));

  return (
    <div
      ref={drag}
      className={`task ${isDragging ? 'dragging' : ''}`}
      style={{
        opacity: isDragging ? 0.5 : 1,
        cursor: 'move',
      }}
    >
      <h4>{task.title}</h4>
      <p>{task.description}</p>
      <small>{new Date(task.createdAt).toLocaleString()}</small>
    </div>
  );
};

export default Task;
```

