import React, { useState } from 'react';
import { useDrop } from 'react-dnd';
import Task from './Task';
import { Column as ColumnType, Task as TaskType } from '../types';

interface ColumnProps {
  column: ColumnType;
  onTaskDrop: (taskId: string, newColumnId: string) => void;
  onAddTask: (columnId: string, title: string, description: string) => void;
}

const Column: React.FC<ColumnProps> = ({ column, onTaskDrop, onAddTask }) => {
  const [showAddForm, setShowAddForm] = useState(false);
  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [newTaskDescription, setNewTaskDescription] = useState('');

  const [{ isOver }, drop] = useDrop(() => ({
    accept: 'TASK',
    drop: () => ({ columnId: column._id }),
    collect: (monitor) => ({
      isOver: !!monitor.isOver(),
    }),
  }));

  const handleAddTask = () => {
    if (newTaskTitle.trim()) {
      onAddTask(column._id, newTaskTitle, newTaskDescription);
      setNewTaskTitle('');
      setNewTaskDescription('');
      setShowAddForm(false);
    }
  };

  return (
    <div className="column" ref={drop}>
      <h3>{column.title}</h3>
      <div className="tasks">
        {column.tasks.map((task) => (
          <Task
            key={task._id}
            task={task}
            columnId={column._id}
            onDrop={onTaskDrop}
          />
        ))}
      </div>
      {showAddForm ? (
        <div className="add-task-form">
          <input
            type="text"
            placeholder="Task title"
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
          />
          <textarea
            placeholder="Description"
            value={newTaskDescription}
            onChange={(e) => setNewTaskDescription(e.target.value)}
          />
          <button onClick={handleAddTask}>Add Task</button>
          <button onClick={() => setShowAddForm(false)}>Cancel</button>
        </div>
      ) : (
        <button onClick={() => setShowAddForm(true)}>Add Task</button>
      )}
    </div>
  );
};

export default Column;
```

