```typescript
import React, { useState, useEffect } from 'react';
import { DndProvider } from 'react-dnd';
import { HTML5Backend } from 'react-dnd-html5-backend';
import Column from './Column';
import { Board as BoardType } from '../types';
import { connectSocket, getSocket } from '../socket';

interface BoardProps {
  board: BoardType;
  onTaskMove: (taskId: string, newColumnId: string) => void;
  onAddTask: (columnId: string, title: string, description: string) => void;
}

const Board: React.FC<BoardProps> = ({ board, onTaskMove, onAddTask }) => {
  const [socket, setSocket] = useState<any>(null);

  useEffect(() => {
    const newSocket = connectSocket(board._id);
    setSocket(newSocket);

    newSocket.on('taskMoved', ({ taskId, newColumnId }) => {
      onTaskMove(taskId, newColumnId);
    });

    return () => {
      newSocket.disconnect();
    };
  }, [board._id, onTaskMove]);

  return (
    <div className="board">
      <h2>{board.name}</h2>
      <div className="columns">
        {board.columns.map((column) => (
          <Column
            key={column._id}
            column={column}
            onTaskDrop={onTaskMove}
            onAddTask={onAddTask}
          />
        ))}
      </div>
    </div>
  );
};

export default Board;
