### 5. Main App Component (`src/App.tsx`)

```typescript
import React, { useState, useEffect } from 'react';
import { DndProvider } from 'react-dnd';
import { HTML5Backend } from 'react-dnd-html5-backend';
import Board from './components/Board';
import { Board as BoardType } from './types';
import './App.css';

const App: React.FC = () => {
  const [board, setBoard] = useState<BoardType | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // In a real app, you would fetch the board from your API
    // For this example, we'll create a mock board
    const mockBoard: BoardType = {
      _id: '1',
      name: 'Project Board',
      columns: [
        {
          _id: 'col1',
          title: 'To Do',
          tasks: [
            {
              _id: 'task1',
              title: 'Task 1',
              description: 'First task',
              column: 'col1',
              createdAt: new Date().toISOString()
            },
            {
              _id: 'task2',
              title: 'Task 2',
              description: 'Second task',
              column: 'col1',
              createdAt: new Date().toISOString()
            }
          ]
        },
        {
          _id: 'col2',
          title: 'In Progress',
          tasks: [
            {
              _id: 'task3',
              title: 'Task 3',
              description: 'In progress task',
              column: 'col2',
              createdAt: new Date().toISOString()
            }
          ]
        },
        {
          _id: 'col3',
          title: 'Done',
          tasks: []
        }
      ]
    };

    setBoard(mockBoard);
    setLoading(false);
  }, []);

  const handleTaskMove = (taskId: string, newColumnId: string) => {
    if (!board) return;

    // Update local state
    setBoard(prevBoard => {
      if (!prevBoard) return prevBoard;

      return {
        ...prevBoard,
        columns: prevBoard.columns.map(column => {
          // Remove task from current column
          const tasks = column.tasks.filter(task => task._id !== taskId);

          // Add task to new column if this is the target column
          if (column._id === newColumnId) {
            const taskToMove = prevBoard.columns
              .flatMap(c => c.tasks)
              .find(task => task._id === taskId);

            if (taskToMove) {
              return {
                ...column,
                tasks: [...tasks, taskToMove]
              };
            }
          }

          return {
            ...column,
            tasks
          };
        })
      };
    });

    // In a real app, you would also update the server
    // For this example, we'll just emit the event via Socket.IO
    const socket = getSocket();
    socket.emit('moveTask', {
      boardId: board._id,
      taskId,
      newColumnId
    });
  };

  const handleAddTask = (columnId: string, title: string, description: string) => {
    if (!board) return;

    // In a real app, you would add the task to the server
    // For this example, we'll just update local state
    setBoard(prevBoard => {
      if (!prevBoard) return prevBoard;

      return {
        ...prevBoard,
        columns: prevBoard.columns.map(column => {
          if (column._id === columnId) {
            const newTask = {
              _id: `task-${Date.now()}`,
              title,
              description,
              column: columnId,
              createdAt: new Date().toISOString()
            };
            return {
              ...column,
              tasks: [...column.tasks, newTask]
            };
          }
          return column;
        })
      };
    });

    // In a real app, you would also send this to the server
    // For this example, we'll just emit the event via Socket.IO
    const socket = getSocket();
    socket.emit('addTask', {
      boardId: board._id,
      columnId,
      title,
      description
    });
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  if (!board) {
    return <div>Board not found</div>;
  }

  return (
    <DndProvider backend={HTML5Backend}>
      <div className="app">
        <h1>Project Management Board</h1>
        <Board
          board={board}
          onTaskMove={handleTaskMove}
          onAddTask={handleAddTask}
        />
      </div>
    </DndProvider>
  );
};

export default App;
```

