### `public/app.js`
```javascript
document.addEventListener('DOMContentLoaded', () => {
    const socket = io();
    const board = document.getElementById('board');

    // Columns data
    const columns = [
        { id: 'todo', title: 'To Do', tasks: [] },
        { id: 'in-progress', title: 'In Progress', tasks: [] },
        { id: 'done', title: 'Done', tasks: [] }
    ];

    // Initialize the board
    function initBoard() {
        board.innerHTML = '';
        columns.forEach(column => {
            const columnElement = document.createElement('div');
            columnElement.className = 'column';
            columnElement.id = column.id;
            columnElement.innerHTML = `
                <div class="column-header">${column.title}</div>
                <div class="tasks"></div>
                <button class="add-task-btn" onclick="addTask('${column.id}')">Add Task</button>
            `;
            board.appendChild(columnElement);
        });

        // Load initial tasks from server
        socket.emit('load-tasks');
    }

    // Add a task to a column
    function addTask(columnId) {
        const taskTitle = prompt('Enter task title:');
        if (taskTitle) {
            socket.emit('add-task', { columnId, title: taskTitle });
        }
    }

    // Render tasks in columns
    function renderTasks() {
        columns.forEach(column => {
            const columnElement = document.getElementById(column.id);
            const tasksContainer = columnElement.querySelector('.tasks');
            tasksContainer.innerHTML = '';
            column.tasks.forEach(task => {
                const taskElement = document.createElement('div');
                taskElement.className = 'task';
                taskElement.draggable = true;
                taskElement.dataset.taskId = task.id;
                taskElement.innerHTML = `
                    <div>${task.title}</div>
                    <button onclick="deleteTask('${task.id}')">Delete</button>
                `;
                tasksContainer.appendChild(taskElement);

                // Drag events
                taskElement.addEventListener('dragstart', () => {
                    taskElement.classList.add('dragging');
                    taskElement.dataset.sourceColumn = column.id;
                    event.dataTransfer.setData('text/plain', task.id);
                });

                taskElement.addEventListener('dragend', () => {
                    taskElement.classList.remove('dragging');
                });
            });
        });
    }

    // Delete a task
    function deleteTask(taskId) {
        if (confirm('Are you sure you want to delete this task?')) {
            socket.emit('delete-task', taskId);
        }
    }

    // Drag and drop events
    board.addEventListener('dragover', (e) => {
        e.preventDefault();
        const draggingTask = document.querySelector('.dragging');
        if (draggingTask) {
            const targetColumn = e.target.closest('.column');
            if (targetColumn) {
                e.dataTransfer.dropEffect = 'move';
            }
        }
    });

    board.addEventListener('drop', (e) => {
        e.preventDefault();
        const taskId = e.dataTransfer.getData('text/plain');
        const sourceColumnId = document.querySelector('.dragging').dataset.sourceColumn;
        const targetColumn = e.target.closest('.column');

        if (targetColumn && targetColumn.id !== sourceColumnId) {
            socket.emit('move-task', {
                taskId,
                fromColumn: sourceColumnId,
                toColumn: targetColumn.id
            });
        }
    });

    // Socket.io event handlers
    socket.on('tasks-loaded', (loadedColumns) => {
        columns.forEach(column => {
            const loadedColumn = loadedColumns.find(c => c.id === column.id);
            if (loadedColumn) {
                column.tasks = loadedColumn.tasks;
            }
        });
        renderTasks();
    });

    socket.on('task-added', (task) => {
        const column = columns.find(c => c.id === task.columnId);
        if (column) {
            column.tasks.push(task);
            renderTasks();
        }
    });

    socket.on('task-moved', ({ taskId, fromColumn, toColumn }) => {
        const fromCol = columns.find(c => c.id === fromColumn);
        const toCol = columns.find(c => c.id === toColumn);
        if (fromCol && toCol) {
            const taskIndex = fromCol.tasks.findIndex(t => t.id === taskId);
            if (taskIndex !== -1) {
                const [task] = fromCol.tasks.splice(taskIndex, 1);
                toCol.tasks.push(task);
                renderTasks();
            }
        }
    });

    socket.on('task-deleted', (taskId) => {
        columns.forEach(column => {
            const taskIndex = column.tasks.findIndex(t => t.id === taskId);
            if (taskIndex !== -1) {
                column.tasks.splice(taskIndex, 1);
                renderTasks();
                return;
            }
        });
    });

    // Initialize the board
    initBoard();
});
