### `database.js`
```javascript
const sqlite3 = require('sqlite3').verbose();
const db = new sqlite3.Database('./tasks.db');

// Initialize the database
function initDb() {
    db.serialize(() => {
        db.run(`
            CREATE TABLE IF NOT EXISTS columns (
                id TEXT PRIMARY KEY,
                title TEXT NOT NULL
            )
        `);

        db.run(`
            CREATE TABLE IF NOT EXISTS tasks (
                id TEXT PRIMARY KEY,
                title TEXT NOT NULL,
                columnId TEXT NOT NULL,
                FOREIGN KEY (columnId) REFERENCES columns(id)
            )
        `);

        // Insert default columns if they don't exist
        const columns = [
            { id: 'todo', title: 'To Do' },
            { id: 'in-progress', title: 'In Progress' },
            { id: 'done', title: 'Done' }
        ];

        columns.forEach(column => {
            db.run(
                `INSERT OR IGNORE INTO columns (id, title) VALUES (?, ?)`,
                [column.id, column.title]
            );
        });
    });
}

// Get all tasks grouped by columns
async function getTasks() {
    return new Promise((resolve, reject) => {
        db.all(`
            SELECT c.id as columnId, c.title as columnTitle, t.id as taskId, t.title as taskTitle
            FROM columns c
            LEFT JOIN tasks t ON c.id = t.columnId
        `, [], (err, rows) => {
            if (err) {
                reject(err);
                return;
            }

            const columnsMap = {};
            rows.forEach(row => {
                if (!columnsMap[row.columnId]) {
                    columnsMap[row.columnId] = {
                        id: row.columnId,
                        title: row.columnTitle,
                        tasks: []
                    };
                }
                if (row.taskId) {
                    columnsMap[row.columnId].tasks.push({
                        id: row.taskId,
                        title: row.taskTitle
                    });
                }
            });

            resolve(Object.values(columnsMap));
        });
    });
}

// Add a new task
async function addTask(columnId, title) {
    return new Promise((resolve, reject) => {
        const taskId = `task-${Date.now()}`;
        db.run(
            `INSERT INTO tasks (id, title, columnId) VALUES (?, ?, ?)`,
            [taskId, title, columnId],
            function(err) {
                if (err) {
                    reject(err);
                    return;
                }
                resolve({ id: taskId, title, columnId });
            }
        );
    });
}

// Move a task between columns
async function moveTask(taskId, fromColumn, toColumn) {
    return new Promise((resolve, reject) => {
        db.run(
            `UPDATE tasks SET columnId = ? WHERE id = ?`,
            [toColumn, taskId],
            function(err) {
                if (err) {
                    reject(err);
                    return;
                }
                resolve();
            }
        );
    });
}

// Delete a task
async function deleteTask(taskId) {
    return new Promise((resolve, reject) => {
        db.run(
            `DELETE FROM tasks WHERE id = ?`,
            [taskId],
            function(err) {
                if (err) {
                    reject(err);
                    return;
                }
                resolve();
            }
        );
    });
}

module.exports = { initDb, getTasks, addTask, moveTask, deleteTask };
```

