# Browser-Based Project Management App with Drag-and-Drop & Real-Time Collaboration

Here's a complete implementation of a project management application with Kanban-style boards, drag-and-drop functionality, and real-time collaboration.

## Backend Implementation (Node.js/Express)

### File: `server.js`
```javascript
const express = require('express');
const mongoose = require('mongoose');
const http = require('http');
const socketIo = require('socket.io');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

// MongoDB connection
mongoose.connect('mongodb://localhost:27017/projectManagement', {
  useNewUrlParser: true,
  useUnifiedTopology: true
});

const db = mongoose.connection;
db.on('error', console.error.bind(console, 'MongoDB connection error:'));
db.once('open', () => {
  console.log('Connected to MongoDB');
});

// Define schemas
const taskSchema = new mongoose.Schema({
  title: { type: String, required: true },
  description: String,
  columnId: String,
  index: Number,
  createdAt: { type: Date, default: Date.now }
});

const columnSchema = new mongoose.Schema({
  id: String,
  title: String,
  taskIds: [String]
});

const boardSchema = new mongoose.Schema({
  title: { type: String, required: true },
  columns: [columnSchema],
  createdAt: { type: Date, default: Date.now }
});

const Task = mongoose.model('Task', taskSchema);
const Board = mongoose.model('Board', boardSchema);

// API Routes
app.get('/api/boards', async (req, res) => {
  try {
    const boards = await Board.find().sort({ createdAt: -1 });
    res.json(boards);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

app.post('/api/boards', async (req, res) => {
  const board = new Board({
    title: req.body.title,
    columns: req.body.columns || [
      { id: 'todo', title: 'To Do', taskIds: [] },
      { id: 'in-progress', title: 'In Progress', taskIds: [] },
      { id: 'done', title: 'Done', taskIds: [] }
    ]
  });

  try {
    const newBoard = await board.save();
    res.status(201).json(newBoard);
  } catch (err) {
    res.status(400).json({ message: err.message });
  }
});

app.get('/api/boards/:id', async (req, res) => {
  try {
    const board = await Board.findById(req.params.id);
    if (!board) return res.status(404).json({ message: 'Board not found' });

    // Populate tasks with their details
    const tasks = await Task.find({ columnId: { $in: board.columns.map(c => c.id) } });
    res.json({ ...board._doc, tasks });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

app.post('/api/boards/:id/tasks', async (req, res) => {
  const task = new Task({
    title: req.body.title,
    description: req.body.description,
    columnId: req.body.columnId,
    index: req.body.index
  });

  try {
    const newTask = await task.save();
    res.status(201).json(newTask);
  } catch (err) {
    res.status(400).json({ message: err.message });
  }
});

// Socket.io connection
io.on('connection', (socket) => {
  console.log('New client connected');

  socket.on('joinBoard', (boardId) => {
    socket.join(boardId);
    console.log(`User joined board ${boardId}`);
  });

  socket.on('moveTask', async ({ boardId, taskId, newColumnId, newIndex }) => {
    try {
      const task = await Task.findById(taskId);
      if (!task) return;

      task.columnId = newColumnId;
      task.index = newIndex;
      await task.save();

      io.to(boardId).emit('taskMoved', { taskId, newColumnId, newIndex });
    } catch (err) {
      console.error('Error moving task:', err);
    }
  });

  socket.on('addTask', async ({ boardId, taskData }) => {
    try {
      const task = new Task(taskData);
      const newTask = await task.save();
      io.to(boardId).emit('taskAdded', newTask);
    } catch (err) {
      console.error('Error adding task:', err);
    }
  });

  socket.on('updateTask', async ({ taskId, updates }) => {
    try {
      await Task.findByIdAndUpdate(taskId, updates);
      io.to(updates.boardId).emit('taskUpdated', { taskId, updates });
    } catch (err) {
      console.error('Error updating task:', err);
    }
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

const PORT = process.env.PORT || 5000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

## Frontend Implementation (React)

### File: `src/App.js`
```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable, Draggable } from 'react-beautiful-dnd';
import io from 'socket.io-client';
import axios from 'axios';
import './App.css';

const socket = io('http://localhost:5000');

function App() {
  const [boards, setBoards] = useState([]);
  const [currentBoard, setCurrentBoard] = useState(null);
  const [newBoardTitle, setNewBoardTitle] = useState('');
  const [newTask, setNewTask] = useState({ title: '', description: '', columnId: 'todo' });

  // Fetch boards on component mount
  useEffect(() => {
    fetchBoards();
  }, []);

  const fetchBoards = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/boards');
      setBoards(response.data);
    } catch (error) {
      console.error('Error fetching boards:', error);
    }
  };

  // Socket.io event listeners
  useEffect(() => {
    if (!currentBoard) return;

    socket.on('taskAdded', (task) => {
      setCurrentBoard(prev => ({
        ...prev,
        tasks: [...prev.tasks, task]
      }));
    });

    socket.on('taskMoved', ({ taskId, newColumnId, newIndex }) => {
      setCurrentBoard(prev => {
        const newTasks = [...prev.tasks];
        const taskIndex = newTasks.findIndex(task => task._id === taskId);
        if (taskIndex !== -1) {
          newTasks[taskIndex].columnId = newColumnId;
          newTasks[taskIndex].index = newIndex;
        }
        return { ...prev, tasks: newTasks };
      });
    });

    socket.on('taskUpdated', ({ taskId, updates }) => {
      setCurrentBoard(prev => ({
        ...prev,
        tasks: prev.tasks.map(task =>
          task._id === taskId ? { ...task, ...updates } : task
        )
      }));
    });

    // Join board room
    socket.emit('joinBoard', currentBoard._id);

    return () => {
      socket.off('taskAdded');
      socket.off('taskMoved');
      socket.off('taskUpdated');
    };
  }, [currentBoard]);

  const createBoard = async () => {
    if (!newBoardTitle.trim()) return;

    try {
      const response = await axios.post('http://localhost:5000/api/boards', {
        title: newBoardTitle
      });
      setBoards([...boards, response.data]);
      setNewBoardTitle('');
    } catch (error) {
      console.error('Error creating board:', error);
    }
  };

  const addTask = async () => {
    if (!newTask.title.trim()) return;

    try {
      await axios.post(`http://localhost:5000/api/boards/${currentBoard._id}/tasks`, {
        ...newTask,
        index: currentBoard.tasks.filter(t => t.columnId === newTask.columnId).length
      });

      // Clear form
      setNewTask({ title: '', description: '', columnId: 'todo' });
    } catch (error) {
      console.error('Error adding task:', error);
    }
  };

  const handleDragEnd = (result) => {
    if (!result.destination) return;

    const { draggableId, source, destination } = result;

    // Optimistically update UI
    setCurrentBoard(prev => {
      const newTasks = [...prev.tasks];
      const [removed] = newTasks.splice(source.index, 1);
      newTasks.splice(destination.index, 0, removed);

      return { ...prev, tasks: newTasks };
    });

    // Send update to server
    socket.emit('moveTask', {
      boardId: currentBoard._id,
      taskId: draggableId,
      newColumnId: destination.droppableId,
      newIndex: destination.index
    });
  };

  const selectBoard = async (board) => {
    try {
      const response = await axios.get(`http://localhost:5000/api/boards/${board._id}`);
      setCurrentBoard(response.data);
    } catch (error) {
      console.error('Error fetching board details:', error);
    }
  };

  const goBackToBoards = () => {
    setCurrentBoard(null);
  };

  if (!currentBoard) {
    return (
      <div className="app-container">
        <h1>Project Management App</h1>

        <div className="board-creation">
          <h2>Create New Board</h2>
          <input
            type="text"
            value={newBoardTitle}
            onChange={(e) => setNewBoardTitle(e.target.value)}
            placeholder="Board title"
          />
          <button onClick={createBoard}>Create Board</button>
        </div>

        <div className="boards-list">
          <h2>Your Boards</h2>
          {boards.length === 0 ? (
            <p>No boards yet. Create one to get started!</p>
          ) : (
            <div className="boards-grid">
              {boards.map(board => (
                <div
                  key={board._id}
                  className="board-card"
                  onClick={() => selectBoard(board)}
                >
                  <h3>{board.title}</h3>
                  <p>{new Date(board.createdAt).toLocaleDateString()}</p>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="app-container">
      <div className="board-header">
        <h1>{currentBoard.title}</h1>
        <button onClick={goBackToBoards} className="back-button">← Back to Boards</button>
      </div>

      <div className="task-creation">
        <h3>Add New Task</h3>
        <input
          type="text"
          value={newTask.title}
          onChange={(e) => setNewTask({...newTask, title: e.target.value})}
          placeholder="Task title"
        />
        <textarea
          value={newTask.description}
          onChange={(e) => setNewTask({...newTask, description: e.target.value})}
          placeholder="Description (optional)"
        />
        <select
          value={newTask.columnId}
          onChange={(e) => setNewTask({...newTask, columnId: e.target.value})}
        >
          {currentBoard.columns.map(column => (
            <option key={column.id} value={column.id}>{column.title}</option>
          ))}
        </select>
        <button onClick={addTask}>Add Task</button>
      </div>

      <DragDropContext onDragEnd={handleDragEnd}>
        <div className="board-columns">
          {currentBoard.columns.map((column, index) => (
            <div key={column.id} className="column">
              <h3>{column.title}</h3>
              <Droppable droppableId={column.id}>
                {(provided) => (
                  <div
                    className="tasks-container"
                    {...provided.droppableProps}
                    ref={provided.innerRef}
                  >
                    {currentBoard.tasks
                      .filter(task => task.columnId === column.id)
                      .sort((a, b) => a.index - b.index)
                      .map((task, index) => (
                        <Draggable key={task._id} draggableId={task._id} index={index}>
                          {(provided) => (
                            <div
                              className="task-card"
                              {...provided.draggableProps}
                              {...provided.dragHandleProps}
                              ref={provided.innerRef}
                            >
                              <h4>{task.title}</h4>
                              {task.description && <p>{task.description}</p>}
                              <small>#{index + 1}</small>
                            </div>
                          )}
                        </Draggable>
                      ))}
                    {provided.placeholder}
                  </div>
                )}
              </Droppable>
            </div>
          ))}
        </div>
      </DragDropContext>
    </div>
  );
}

export default App;
```

