#### Backend (Node.js with Express and Socket.io)
```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const mongoose = require('mongoose');
const cors = require('cors');
require('dotenv').config();

const app = express();
app.use(cors());
const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

// Connect to MongoDB
mongoose.connect(process.env.MONGODB_URI, { useNewUrlParser: true, useUnifiedTopology: true })
  .then(() => console.log('Connected to MongoDB'))
  .catch(err => console.error('Could not connect to MongoDB', err));

// Define schemas
const taskSchema = new mongoose.Schema({
  title: String,
  description: String,
  column: { type: mongoose.Schema.Types.ObjectId, ref: 'Column' },
  assignee: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
});

const columnSchema = new mongoose.Schema({
  name: String,
  tasks: [taskSchema],
});

const boardSchema = new mongoose.Schema({
  name: String,
  columns: [columnSchema],
});

const userSchema = new mongoose.Schema({
  name: String,
});

const Task = mongoose.model('Task', taskSchema);
const Column = mongoose.model('Column', columnSchema);
const Board = mongoose.model('Board', boardSchema);
const User = mongoose.model('User', userSchema);

// Middleware
app.use(express.json());

// Routes
app.get('/boards', async (req, res) => {
  try {
    const boards = await Board.find().populate({
      path: 'columns.tasks',
      populate: { path: 'assignee' }
    });
    res.json(boards);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

// Socket.io connection
io.on('connection', (socket) => {
  console.log('New client connected');

  socket.on('moveTask', async ({ taskId, newColumnId }) => {
    try {
      const task = await Task.findById(taskId);
      if (!task) return;

      task.column = newColumnId;
      await task.save();

      // Broadcast the updated task to all clients
      io.emit('taskMoved', task);
    } catch (err) {
      console.error('Error moving task:', err);
    }
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

