const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const { initDb, getTasks, addTask, moveTask, deleteTask } = require('./database');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Serve static files
app.use(express.static('public'));

// Initialize database
initDb();

// Socket.io connection
io.on('connection', (socket) => {
    console.log('New client connected');

    // Load tasks when a client connects
    socket.on('load-tasks', async () => {
        const tasks = await getTasks();
        io.emit('tasks-loaded', tasks);
    });

    // Add a new task
    socket.on('add-task', async ({ columnId, title }) => {
        const task = await addTask(columnId, title);
        io.emit('task-added', task);
    });

    // Move a task between columns
    socket.on('move-task', async ({ taskId, fromColumn, toColumn }) => {
        await moveTask(taskId, fromColumn, toColumn);
        const tasks = await getTasks();
        io.emit('tasks-loaded', tasks);
    });

    // Delete a task
    socket.on('delete-task', async (taskId) => {
        await deleteTask(taskId);
        io.emit('task-deleted', taskId);
    });

    socket.on('disconnect', () => {
        console.log('Client disconnected');
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
