   const express = require('express');
   const mongoose = require('mongoose');
   const http = require('http');
   const socketIo = require('socket.io');
   const cors = require('cors');

   const app = express();
   app.use(cors());
   app.use(express.json());

   const server = http.createServer(app);
   const io = socketIo(server, {
     cors: {
       origin: "http://localhost:3000",
       methods: ["GET", "POST"]
     }
   });

   // MongoDB connection
   mongoose.connect('mongodb://localhost:27017/projectManagement', {
     useNewUrlParser: true,
     useUnifiedTopology: true
   });

   const db = mongoose.connection;
   db.on('error', console.error.bind(console, 'MongoDB connection error:'));
   db.once('open', () => {
     console.log('Connected to MongoDB');
   });

   // Define Board and Task models
   const taskSchema = new mongoose.Schema({
     title: String,
     description: String,
     columnId: String,
     index: Number
   });

   const columnSchema = new mongoose.Schema({
     id: String,
     title: String,
     taskIds: [String]
   });

   const boardSchema = new mongoose.Schema({
     title: String,
     columns: [columnSchema]
   });

   const Task = mongoose.model('Task', taskSchema);
   const Board = mongoose.model('Board', boardSchema);

   // API Routes
   app.get('/boards', async (req, res) => {
     try {
       const boards = await Board.find();
       res.json(boards);
     } catch (err) {
       res.status(500).json({ message: err.message });
     }
   });

   app.post('/boards', async (req, res) => {
     const board = new Board({
       title: req.body.title,
       columns: req.body.columns
     });
     try {
       const newBoard = await board.save();
       res.status(201).json(newBoard);
     } catch (err) {
       res.status(400).json({ message: err.message });
     }
   });

   app.get('/boards/:id', async (req, res) => {
     try {
       const board = await Board.findById(req.params.id);
       if (!board) return res.status(404).json({ message: 'Board not found' });
       res.json(board);
     } catch (err) {
       res.status(500).json({ message: err.message });
     }
   });

   app.post('/boards/:id/tasks', async (req, res) => {
     const task = new Task({
       title: req.body.title,
       description: req.body.description,
       columnId: req.body.columnId,
       index: req.body.index
     });
     try {
       const newTask = await task.save();
       await Board.findByIdAndUpdate(req.params.id, {
         $push: { tasks: newTask._id }
       });
       io.to(req.params.id).emit('taskAdded', newTask);
       res.status(201).json(newTask);
     } catch (err) {
       res.status(400).json({ message: err.message });
     }
   });

   // Socket.io connection
   io.on('connection', (socket) => {
     console.log('New client connected');

     socket.on('joinBoard', (boardId) => {
       socket.join(boardId);
       console.log(`User joined board ${boardId}`);
     });

     socket.on('moveTask', async ({ boardId, taskId, newColumnId, newIndex }) => {
       try {
         const task = await Task.findById(taskId);
         if (!task) return;

         task.columnId = newColumnId;
         task.index = newIndex;
         await task.save();

         io.to(boardId).emit('taskMoved', { taskId, newColumnId, newIndex });
       } catch (err) {
         console.error('Error moving task:', err);
       }
     });

     socket.on('disconnect', () => {
       console.log('Client disconnected');
     });
   });

   const PORT = process.env.PORT || 5000;
   server.listen(PORT, () => {
     console.log(`Server running on port ${PORT}`);
   });
