```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable, Draggable } from 'react-beautiful-dnd';
import io from 'socket.io-client';
import axios from 'axios';

const socket = io('http://localhost:5000');

function App() {
  const [boards, setBoards] = useState([]);
  const [currentBoard, setCurrentBoard] = useState(null);

  useEffect(() => {
    axios.get('http://localhost:5000/boards')
      .then(response => setBoards(response.data))
      .catch(error => console.error('Error fetching boards:', error));

    socket.on('taskAdded', (task) => {
      setCurrentBoard(prev => ({
        ...prev,
        tasks: [...prev.tasks, task]
      }));
    });

    socket.on('taskMoved', ({ taskId, newColumnId, newIndex }) => {
      setCurrentBoard(prev => {
        const newTasks = [...prev.tasks];
        const taskIndex = newTasks.findIndex(task => task._id === taskId);
        if (taskIndex !== -1) {
          newTasks[taskIndex].columnId = newColumnId;
          newTasks[taskIndex].index = newIndex;
        }
        return { ...prev, tasks: newTasks };
      });
    });

    return () => {
      socket.off('taskAdded');
      socket.off('taskMoved');
    };
  }, []);

  const handleDragEnd = (result) => {
    if (!result.destination) return;

    const { draggableId, source, destination } = result;

    // Optimistically update UI
    setCurrentBoard(prev => {
      const newTasks = [...prev.tasks];
      const [removed] = newTasks.splice(source.index, 1);
      newTasks.splice(destination.index, 0, removed);

      return { ...prev, tasks: newTasks };
    });

    // Send update to server
    socket.emit('moveTask', {
      boardId: currentBoard._id,
      taskId: draggableId,
      newColumnId: destination.droppableId,
      newIndex: destination.index
    });
  };

  const selectBoard = (board) => {
    setCurrentBoard(board);
    socket.emit('joinBoard', board._id);
  };

  if (!currentBoard) {
    return (
      <div>
        <h1>Project Management App</h1>
        <h2>Select a Board</h2>
        <ul>
          {boards.map(board => (
            <li key={board._id} onClick={() => selectBoard(board)}>
              {board.title}
            </li>
          ))}
        </ul>
      </div>
    );
  }

  return (
    <div>
      <h1>{currentBoard.title}</h1>
      <button onClick={() => setCurrentBoard(null)}>Back to Boards</button>

      <DragDropContext onDragEnd={handleDragEnd}>
        <div style={{ display: 'flex' }}>
          {currentBoard.columns.map(column => (
            <Droppable key={column.id} droppableId={column.id}>
              {(provided) => (
                <div
                  {...provided.droppableProps}
                  ref={provided.innerRef}
                  style={{ margin: '10px', padding: '10px', border: '1px solid #ccc', width: '200px' }}
                >
                  <h3>{column.title}</h3>
                  {currentBoard.tasks
                    .filter(task => task.columnId === column.id)
                    .sort((a, b) => a.index - b.index)
                    .map((task, index) => (
                      <Draggable key={task._id} draggableId={task._id} index={index}>
                        {(provided) => (
                          <div
                            {...provided.draggableProps}
                            {...provided.dragHandleProps}
                            ref={provided.innerRef}
                            style={{
                              userSelect: 'none',
                              padding: '16px',
                              margin: '0 0 8px 0',
                              backgroundColor: '#4a6fa5',
                              color: 'white',
                              ...provided.draggableProps.style
                            }}
                          >
                            {task.title}
                          </div>
                        )}
                      </Draggable>
                    ))}
                  {provided.placeholder}
                </div>
              )}
            </Droppable>
          ))}
        </div>
      </DragDropContext>
    </div>
  );
}

export default App;
```

