// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const cors = require('cors');

const app = express();
app.use(cors());
const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory database
let boards = {
  'board-1': {
    id: 'board-1',
    title: 'Main Project',
    lists: {
      'list-1': { id: 'list-1', title: 'To Do', tasks: ['task-1', 'task-2'] },
      'list-2': { id: 'list-2', title: 'In Progress', tasks: [] },
      'list-3': { id: 'list-3', title: 'Done', tasks: [] }
    }
  }
};

let tasks = {
  'task-1': { id: 'task-1', title: 'Design UI', description: 'Design the user interface' },
  'task-2': { id: 'task-2', title: 'Implement API', description: 'Implement backend API' }
};

// Socket.io connection
io.on('connection', (socket) => {
  console.log('New client connected');

  // Send initial data
  socket.emit('init', { boards, tasks });

  // Handle task movement
  socket.on('moveTask', ({ taskId, fromListId, toListId, boardId }) => {
    // Update the board state
    if (boards[boardId] && boards[boardId].lists[fromListId] && boards[boardId].lists[toListId]) {
      // Remove from old list
      const fromList = boards[boardId].lists[fromListId];
      fromList.tasks = fromList.tasks.filter(id => id !== taskId);

      // Add to new list
      const toList = boards[boardId].lists[toListId];
      toList.tasks.push(taskId);

      // Broadcast the change to all clients
      io.emit('boardUpdated', { boards, tasks });
    }
  });

  // Handle task creation
  socket.on('createTask', ({ title, description, listId, boardId }) => {
    const taskId = `task-${Date.now()}`;
    tasks[taskId] = { id: taskId, title, description };

    if (boards[boardId] && boards[boardId].lists[listId]) {
      boards[boardId].lists[listId].tasks.push(taskId);
      io.emit('boardUpdated', { boards, tasks });
    }
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

