Now, the frontend with React and TypeScript:

First, let's set up the React app with TypeScript. We'll need to install dependencies:
- react
- react-dom
- @types/react
- @types/react-dom
- typescript
- react-beautiful-dnd
- socket.io-client
- axios (for HTTP requests, though we'll mostly use WebSockets)

But since we're writing the code directly, let's create the React components.

```tsx
// src/App.tsx
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable, Draggable, DropResult } from 'react-beautiful-dnd';
import { io, Socket } from 'socket.io-client';

interface Task {
  id: string;
  title: string;
  description: string;
}

interface List {
  id: string;
  title: string;
  tasks: string[];
}

interface Board {
  id: string;
  title: string;
  lists: Record<string, List>;
}

const App: React.FC = () => {
  const [boards, setBoards] = useState<Record<string, Board>>({});
  const [tasks, setTasks] = useState<Record<string, Task>>({});
  const [socket, setSocket] = useState<Socket | null>(null);
  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [newTaskDescription, setNewTaskDescription] = useState('');
  const [selectedBoardId, setSelectedBoardId] = useState<string>('board-1');
  const [selectedListId, setSelectedListId] = useState<string>('list-1');

  useEffect(() => {
    // Connect to WebSocket server
    const newSocket = io('http://localhost:4000');
    setSocket(newSocket);

    // Listen for initial data
    newSocket.on('init', (data: { boards: Record<string, Board>; tasks: Record<string, Task> }) => {
      setBoards(data.boards);
      setTasks(data.tasks);
    });

    // Listen for board updates
    newSocket.on('boardUpdated', (data: { boards: Record<string, Board>; tasks: Record<string, Task> }) => {
      setBoards(data.boards);
      setTasks(data.tasks);
    });

    return () => {
      newSocket.close();
    };
  }, []);

  const onDragEnd = (result: DropResult) => {
    if (!result.destination) return;

    const { draggableId, source, destination } = result;

    // Check if the task was moved to a different list
    if (source.droppableId !== destination.droppableId) {
      if (socket) {
        socket.emit('moveTask', {
          taskId: draggableId,
          fromListId: source.droppableId,
          toListId: destination.droppableId,
          boardId: selectedBoardId
        });
      }
    }
  };

  const handleCreateTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (newTaskTitle.trim() && socket) {
      socket.emit('createTask', {
        title: newTaskTitle,
        description: newTaskDescription,
        listId: selectedListId,
        boardId: selectedBoardId
      });
      setNewTaskTitle('');
      setNewTaskDescription('');
    }
  };

  if (!boards[selectedBoardId]) return <div>Loading...</div>;

  const board = boards[selectedBoardId];
  const lists = Object.values(board.lists);

  return (
    <div className="app">
      <h1>{board.title}</h1>

      <div className="board-controls">
        <select
          value={selectedBoardId}
          onChange={(e) => setSelectedBoardId(e.target.value)}
        >
          {Object.keys(boards).map(boardId => (
            <option key={boardId} value={boardId}>{boards[boardId].title}</option>
          ))}
        </select>
      </div>

      <DragDropContext onDragEnd={onDragEnd}>
        <div className="lists-container">
          {lists.map((list, index) => (
            <Droppable key={list.id} droppableId={list.id}>
              {(provided) => (
                <div
                  className="list"
                  ref={provided.innerRef}
                  {...provided.droppableProps}
                >
                  <h3>{list.title}</h3>
                  <div className="tasks">
                    {list.tasks.map((taskId, taskIndex) => {
                      const task = tasks[taskId];
                      if (!task) return null;
                      return (
                        <Draggable key={task.id} draggableId={task.id} index={taskIndex}>
                          {(provided) => (
                            <div
                              className="task"
                              ref={provided.innerRef}
                              {...provided.draggableProps}
                              {...provided.dragHandleProps}
                            >
                              <h4>{task.title}</h4>
                              <p>{task.description}</p>
                            </div>
                          )}
                        </Draggable>
                      );
                    })}
                    {provided.placeholder}
                  </div>
                </div>
              )}
            </Droppable>
          ))}
        </div>
      </DragDropContext>

      <div className="task-form">
        <h3>Create New Task</h3>
        <form onSubmit={handleCreateTask}>
          <input
            type="text"
            placeholder="Task title"
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
            required
          />
          <textarea
            placeholder="Task description"
            value={newTaskDescription}
            onChange={(e) => setNewTaskDescription(e.target.value)}
          />
          <select
            value={selectedListId}
            onChange={(e) => setSelectedListId(e.target.value)}
          >
            {lists.map(list => (
              <option key={list.id} value={list.id}>{list.title}</option>
            ))}
          </select>
          <button type="submit">Add Task</button>
        </form>
      </div>
    </div>
  );
};

export default App;
```

