### 2. Backend Code (`backend/server.ts`)

```typescript
import express from 'express';
import { createServer } from 'http';
import { Server } from 'socket.io';
import cors from 'cors';

const app = express();
app.use(cors());
const httpServer = createServer(app);
const io = new Server(httpServer, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

// In-memory data store (replace with database in production)
let boards = {
  'board-1': {
    id: 'board-1',
    name: 'Main Project',
    columns: [
      { id: 'col-1', title: 'To Do', taskIds: ['task-1', 'task-2'] },
      { id: 'col-2', title: 'In Progress', taskIds: [] },
      { id: 'col-3', title: 'Done', taskIds: [] }
    ]
  }
};

let tasks = {
  'task-1': { id: 'task-1', content: 'Design database schema' },
  'task-2': { id: 'task-2', content: 'Implement API endpoints' }
};

// Socket.io connection
io.on('connection', (socket) => {
  console.log('a user connected');

  // Send initial board data
  socket.emit('init', { boards, tasks });

  // Handle task movement
  socket.on('moveTask', ({ taskId, newColumnId }) => {
    // Find the task's current column
    let oldColumnId = null;
    for (const boardId in boards) {
      const board = boards[boardId];
      for (const column of board.columns) {
        if (column.taskIds.includes(taskId)) {
          oldColumnId = column.id;
          break;
        }
      }
    }

    if (oldColumnId && oldColumnId !== newColumnId) {
      // Remove task from old column
      for (const boardId in boards) {
        const board = boards[boardId];
        for (const column of board.columns) {
          if (column.id === oldColumnId) {
            column.taskIds = column.taskIds.filter(id => id !== taskId);
          }
          if (column.id === newColumnId) {
            column.taskIds.push(taskId);
          }
        }
      }

      // Broadcast the change to all clients
      io.emit('taskMoved', { taskId, newColumnId });
    }
  });

  socket.on('disconnect', () => {
    console.log('user disconnected');
  });
});

const PORT = 4000;
httpServer.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

