# Browser-Based Project Management Application

Here's an initial implementation of a browser-based project management application with drag-and-drop task boards and real-time collaboration.

## Architecture Overview

- **Frontend**: React with TypeScript
- **Backend**: Node.js with Express
- **Database**: MongoDB
- **Real-time**: Socket.io
- **Drag-and-drop**: react-beautiful-dnd

---

## 1. Backend Implementation (Node.js/Express)

### File Structure
```
project-management-backend/
├── server.js          # Main server file
├── models/            # MongoDB models
│   ├── Board.js
│   └── Task.js
├── routes/            # API routes
│   ├── boards.js
│   └── tasks.js
└── package.json
```

### `server.js`
```javascript
require('dotenv').config();
const express = require('express');
const mongoose = require('mongoose');
const cors = require('cors');
const http = require('http');
const socketIo = require('socket.io');
const bodyParser = require('body-parser');
const boardsRouter = require('./routes/boards');
const tasksRouter = require('./routes/tasks');

const app = express();
const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: process.env.FRONTEND_URL || "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

// Middleware
app.use(cors());
app.use(bodyParser.json());

// MongoDB Connection
mongoose.connect(process.env.MONGODB_URI || 'mongodb://localhost:27017/project-management', {
  useNewUrlParser: true,
  useUnifiedTopology: true
})
.then(() => console.log('Connected to MongoDB'))
.catch(err => console.error('MongoDB connection error:', err));

// Routes
app.use('/api/boards', boardsRouter);
app.use('/api/tasks', tasksRouter);

// Socket.io connection
io.on('connection', (socket) => {
  console.log('New client connected:', socket.id);

  socket.on('joinBoard', (boardId) => {
    socket.join(boardId);
    console.log(`User joined board: ${boardId}`);
  });

  socket.on('taskMoved', ({ boardId, taskId, newColumnId }) => {
    socket.to(boardId).emit('taskMoved', { taskId, newColumnId });
  });

  socket.on('taskAdded', ({ boardId, task }) => {
    socket.to(boardId).emit('taskAdded', task);
  });

  socket.on('taskUpdated', ({ boardId, task }) => {
    socket.to(boardId).emit('taskUpdated', task);
  });

  socket.on('taskDeleted', ({ boardId, taskId }) => {
    socket.to(boardId).emit('taskDeleted', taskId);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected:', socket.id);
  });
});

// Start server
const PORT = process.env.PORT || 5000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = io; // For testing purposes
```

### `models/Board.js`
```javascript
const mongoose = require('mongoose');

const boardSchema = new mongoose.Schema({
  name: {
    type: String,
    required: true,
    default: 'Main Board'
  },
  createdAt: {
    type: Date,
    default: Date.now
  },
  columns: [{
    id: String,
    title: String,
    taskIds: [String]
  }]
});

module.exports = mongoose.model('Board', boardSchema);
```

