### `src/context/BoardContext.tsx`
```typescript
import React, { createContext, useState, useEffect, useContext } from 'react';
import { Board, Task, BoardContextType } from '../types/types';
import useSocket from '../hooks/useSocket';
import axios from 'axios';

const BoardContext = createContext<BoardContextType | undefined>(undefined);

export const BoardProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [boards, setBoards] = useState<Board[]>([]);
  const [currentBoard, setCurrentBoard] = useState<Board | null>(null);
  const [tasks, setTasks] = useState<Task[]>([]);
  const socket = useSocket(process.env.REACT_APP_BACKEND_URL || 'http://localhost:5000');

  // Fetch initial data
  useEffect(() => {
    const fetchData = async () => {
      try {
        const [boardsRes, tasksRes] = await Promise.all([
          axios.get(`${process.env.REACT_APP_BACKEND_URL || 'http://localhost:5000'}/api/boards`),
          axios.get(`${process.env.REACT_APP_BACKEND_URL || 'http://localhost:5000'}/api/tasks/board/${currentBoard?._id || ''}`)
        ]);
        setBoards(boardsRes.data);
        setTasks(tasksRes.data);
      } catch (err) {
        console.error('Error fetching data:', err);
      }
    };

    fetchData();
  }, [currentBoard?._id]);

  // Socket.io event handlers
  useEffect(() => {
    if (!socket) return;

    socket.on('taskAdded', (task: Task) => {
      setTasks(prev => [...prev, task]);
    });

    socket.on('taskUpdated', (updatedTask: Task) => {
      setTasks(prev => prev.map(task => task._id === updatedTask._id ? updatedTask : task));
    });

    socket.on('taskMoved', ({ taskId, newColumnId }: { taskId: string; newColumnId: string }) => {
      setTasks(prev => prev.map(task =>
        task._id === taskId ? { ...task, columnId: newColumnId } : task
      ));
    });

    socket.on('taskDeleted', (taskId: string) => {
      setTasks(prev => prev.filter(task => task._id !== taskId));
    });

    return () => {
      socket.off('taskAdded');
      socket.off('taskUpdated');
      socket.off('taskMoved');
      socket.off('taskDeleted');
    };
  }, [socket]);

  const addTask = async (taskData: Omit<Task, '_id' | 'createdAt' | 'updatedAt'>) => {
    try {
      const response = await axios.post(
        `${process.env.REACT_APP_BACKEND_URL || 'http://localhost:5000'}/api/tasks`,
        taskData
      );
      if (currentBoard) {
        socket.emit('joinBoard', currentBoard._id);
      }
      return response.data;
    } catch (err) {
      console.error('Error adding task:', err);
      throw err;
    }
  };

  const updateTask = async (taskId: string, updates: Partial<Task>) => {
    try {
      const response = await axios.put(
        `${process.env.REACT_APP_BACKEND_URL || 'http://localhost:5000'}/api/tasks/${taskId}`,
        updates
      );
      return response.data;
    } catch (err) {
      console.error('Error updating task:', err);
      throw err;
    }
  };

  const moveTask = async (taskId: string, newColumnId: string) => {
    try {
      const response = await axios.post(
        `${process.env.REACT_APP_BACKEND_URL || 'http://localhost:5000'}/api/tasks/${taskId}/move`,
        { newColumnId }
      );
      return response.data;
    } catch (err) {
      console.error('Error moving task:', err);
      throw err;
    }
  };

  const deleteTask = async (taskId: string) => {
    try {
      await axios.delete(
        `${process.env.REACT_APP_BACKEND_URL || 'http://localhost:5000'}/api/tasks/${taskId}`
      );
    } catch (err) {
      console.error('Error deleting task:', err);
      throw err;
    }
  };

  const createBoard = async (name?: string) => {
    try {
      const response = await axios.post(
        `${process.env.REACT_APP_BACKEND_URL || 'http://localhost:5000'}/api/boards`,
        { name }
      );
      setBoards(prev => [...prev, response.data]);
      setCurrentBoard(response.data);
    } catch (err) {
      console.error('Error creating board:', err);
      throw err;
    }
  };

  const selectBoard = (boardId: string) => {
    const board = boards.find(b => b._id === boardId);
    if (board) {
      setCurrentBoard(board);
      socket.emit('joinBoard', boardId);
    }
  };

  return (
    <BoardContext.Provider
      value={{
        boards,
        currentBoard,
        tasks,
        addTask,
        updateTask,
        moveTask,
        deleteTask,
        createBoard,
        selectBoard
      }}
    >
      {children}
    </BoardContext.Provider>
  );
};

export const useBoard = () => {
  const context = useContext(BoardContext);
  if (!context) {
    throw new Error('useBoard must be used within a BoardProvider');
  }
  return context;
};
