import sqlite3 from 'sqlite3';
import { open } from 'sqlite';
import { Board, Column, Task } from './models';

const dbPromise = open({
  filename: './project-management.db',
  driver: sqlite3.Database
});

export async function initializeDB() {
  const db = await dbPromise;

  await db.exec(`
    CREATE TABLE IF NOT EXISTS boards (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS columns (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      boardId TEXT NOT NULL,
      taskIds TEXT NOT NULL,
      FOREIGN KEY (boardId) REFERENCES boards(id)
    );

    CREATE TABLE IF NOT EXISTS tasks (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      description TEXT,
      status TEXT NOT NULL,
      createdAt TEXT NOT NULL,
      boardId TEXT NOT NULL,
      FOREIGN KEY (boardId) REFERENCES boards(id)
    );
  `);

  // Insert default board if none exists
  const boards = await db.all<{ id: string }[]>('SELECT id FROM boards');
  if (boards.length === 0) {
    const boardId = 'board-1';
    await db.run('INSERT INTO boards (id, title) VALUES (?, ?)', [boardId, 'Main Project']);

    const columns: Column[] = [
      { id: 'col-1', title: 'To Do', taskIds: [], boardId: boardId },
      { id: 'col-2', title: 'In Progress', taskIds: [], boardId: boardId },
      { id: 'col-3', title: 'Done', taskIds: [], boardId: boardId }
    ];

    for (const col of columns) {
      await db.run(
        'INSERT INTO columns (id, title, boardId, taskIds) VALUES (?, ?, ?, ?)',
        [col.id, col.title, col.boardId, JSON.stringify(col.taskIds)]
      );
    }
  }
}

export async function getBoard(boardId: string): Promise<Board | null> {
  const db = await dbPromise;
  const board = await db.get<{ id: string; title: string }>(
    'SELECT * FROM boards WHERE id = ?',
    [boardId]
  );

  if (!board) return null;

  const columns = await db.all<Column[]>(
    'SELECT * FROM columns WHERE boardId = ?',
    [boardId]
  );

  const tasks = await db.all<Task[]>(
    'SELECT * FROM tasks WHERE boardId = ?',
    [boardId]
  );

  return {
    id: board.id,
    title: board.title,
    columns: columns.map(col => ({
      ...col,
      taskIds: JSON.parse(col.taskIds)
    }))
  };
}

export async function updateTaskStatus(taskId: string, newStatus: Task['status']) {
  const db = await dbPromise;
  await db.run(
    'UPDATE tasks SET status = ? WHERE id = ?',
    [newStatus, taskId]
  );
}

export async function createTask(task: Omit<Task, 'id' | 'createdAt'>) {
  const db = await dbPromise;
  const taskId = `task-${Date.now()}`;
  const createdAt = new Date().toISOString();

  await db.run(
    'INSERT INTO tasks (id, title, description, status, createdAt, boardId) VALUES (?, ?, ?, ?, ?, ?)',
    [taskId, task.title, task.description, task.status, createdAt, task.boardId]
  );

  return { ...task, id: taskId, createdAt };
}

export async function updateColumnTasks(columnId: string, taskIds: string[]) {
  const db = await dbPromise;
  await db.run(
    'UPDATE columns SET taskIds = ? WHERE id = ?',
    [JSON.stringify(taskIds), columnId]
  );
}
