### 5. `backend/src/socketHandler.ts`

```typescript
import { Server } from 'socket.io';
import {
  getBoard,
  updateTaskStatus,
  createTask,
  updateColumnTasks
} from './db';
import { Task } from './models';

export function setupSocketIO(io: Server) {
  io.on('connection', (socket) => {
    console.log('New client connected:', socket.id);

    socket.on('joinBoard', async (boardId: string) => {
      socket.join(boardId);
      const board = await getBoard(boardId);
      if (board) {
        socket.emit('boardUpdate', board);
      }
    });

    socket.on('moveTask', async ({ taskId, newStatus, boardId }) => {
      await updateTaskStatus(taskId, newStatus);

      // Update column taskIds
      const board = await getBoard(boardId);
      if (board) {
        const newColumns = board.columns.map(col => {
          if (col.id === newStatus) {
            return { ...col, taskIds: [...col.taskIds, taskId] };
          }
          return { ...col, taskIds: col.taskIds.filter(id => id !== taskId) };
        });

        await Promise.all(
          newColumns.map(col => updateColumnTasks(col.id, col.taskIds))
        );

        const updatedBoard = await getBoard(boardId);
        io.to(boardId).emit('boardUpdate', updatedBoard);
      }
    });

    socket.on('createTask', async ({ boardId, title, description }) => {
      const newTask = await createTask({
        title,
        description,
        status: 'todo',
        boardId
      });

      const board = await getBoard(boardId);
      if (board) {
        io.to(boardId).emit('boardUpdate', board);
      }
    });

    socket.on('disconnect', () => {
      console.log('Client disconnected:', socket.id);
    });
  });
}
