export const Task = ({ id, title, description, onClick }: TaskProps) => {
  const [{ isDragging }, drag] = useDrag(() => ({
    type: 'TASK',
    item: { id },
    collect: (monitor) => ({
      isDragging: !!monitor.isDragging(),
    }),
  }));

  return (
    <div
      ref={drag}
      onClick={onClick}
      className={`p-3 mb-2 bg-white rounded-lg shadow-sm cursor-move border-l-4 ${
        isDragging ? 'opacity-50' : 'opacity-100'
