        description
      });
    }
    setShowTaskForm(false);
  };

  const getTasksByStatus = (status: string) => {
    if (!board) return [];
    const column = board.columns.find(col => col.id === status);
    if (!column) return [];

    return column.taskIds
      .map(taskId => board.columns.flatMap(col => col.taskIds).includes(taskId) ?
        board.columns.flatMap(col => col.taskIds).find(id => id === taskId) : null)
      .filter(Boolean) as string[];

    // Actually, we need to get tasks from the board's task list
    // Let's fix this:
    return board.columns
      .flatMap(col => col.taskIds)
      .map(taskId => {
        const task = board.columns
          .flatMap(col => col.taskIds)
          .find(id => id === taskId);
        return task ? board.columns.flatMap(col => col.taskIds).find(id => id === taskId) : null;
      })
      .filter(Boolean) as string[];
  };

  // Better approach: get all tasks and group by status
  const getTasksByStatusFixed = (status: string) => {
    if (!board) return [];
    return board.columns
      .find(col => col.id === status)
      ?.taskIds
      .map(taskId => {
        // Find the task in the board's columns (this is a simplified approach)
        // In a real app, you'd have a proper task store
        return {
          id: taskId,
          title: `Task ${taskId}`,
          description: '',
          status,
          createdAt: new Date().toISOString()
        };
      }) || [];
  };

  // Actually, we need to properly map task IDs to task data
  // Let's refactor this:

  const getTasksForColumn = (column: Column): Task[] => {
    return column.taskIds.map(taskId => {
      // In a real app, you'd have a proper task store
      // For now, we'll create mock tasks
      return {
        id: taskId,
        title: `Task ${taskId.substring(0, 8)}`,
        description: `Description for task ${taskId}`,
        status: column.id as Task['status'],
        createdAt: new Date().toISOString()
      };
    });
  };

  if (!board) {
    return <div className="p-8 text-center">Loading board...</div>;
  }

  return (
    <DndProvider backend={HTML5Backend}>
      <div className="p-6">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-2xl font-bold text-gray-800">{board.title}</h1>
          <button
            onClick={() => setShowTaskForm(true)}
            className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700"
