document.addEventListener('DOMContentLoaded', () => {
  const board = document.getElementById('board');
  const socket = io();

  // Columns (can be dynamic)
  const columns = ['To Do', 'In Progress', 'Done'];

  // Initialize board
  socket.on('init', (initialTasks) => {
    columns.forEach(columnName => {
      const column = document.createElement('div');
      column.className = 'column';
      column.innerHTML = `<h2>${columnName}</h2>`;
      board.appendChild(column);

      // Add tasks to column
      initialTasks[columnName].forEach(task => {
        const taskElement = document.createElement('div');
        taskElement.className = 'task';
        taskElement.draggable = true;
        taskElement.textContent = task;
        taskElement.dataset.task = task;
        taskElement.dataset.column = columnName;
        column.appendChild(taskElement);
      });
    });

    // Set up drag-and-drop
    setupDragAndDrop();
  });

  // Update tasks in real-time
  socket.on('updateTasks', (updatedTasks) => {
    board.innerHTML = ''; // Clear board
    columns.forEach(columnName => {
      const column = document.createElement('div');
      column.className = 'column';
      column.innerHTML = `<h2>${columnName}</h2>`;
      board.appendChild(column);

      updatedTasks[columnName].forEach(task => {
        const taskElement = document.createElement('div');
        taskElement.className = 'task';
        taskElement.draggable = true;
        taskElement.textContent = task;
        taskElement.dataset.task = task;
        taskElement.dataset.column = columnName;
        column.appendChild(taskElement);
      });
    });
    setupDragAndDrop();
  });

  function setupDragAndDrop() {
    const tasks = document.querySelectorAll('.task');
    let draggedTask = null;

    tasks.forEach(task => {
      task.addEventListener('dragstart', (e) => {
        draggedTask = e.target;
        e.target.style.opacity = '0.5';
      });

      task.addEventListener('dragend', (e) => {
        e.target.style.opacity = '1';
        draggedTask = null;
      });

      task.addEventListener('dragover', (e) => {
        e.preventDefault();
      });

      task.addEventListener('drop', (e) => {
        e.preventDefault();
        if (draggedTask !== e.target) {
          const fromColumn = draggedTask.dataset.column;
          const toColumn = e.target.closest('.column').querySelector('h2').textContent;
          const taskName = draggedTask.dataset.task;

          // Update UI immediately (optimistic update)
          e.target.closest('.column').appendChild(draggedTask);
          draggedTask.dataset.column = toColumn;

          // Send update to server
          socket.emit('moveTask', {
            task: taskName,
            from: fromColumn,
            to: toColumn
          });
        }
      });
    });
  }
});
```

