import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable, Draggable } from 'react-beautiful-dnd';
import io from 'socket.io-client';
import axios from 'axios';
import './App.css';

const socket = io('http://localhost:5000');

function App() {
  const [boards, setBoards] = useState([]);
  const [tasks, setTasks] = useState([]);
  const [newTask, setNewTask] = useState('');

  useEffect(() => {
    // Fetch initial data
    axios.get('http://localhost:5000/api/boards')
      .then(response => {
        setBoards(response.data);
      })
      .catch(error => {
        console.error('Error fetching boards:', error);
      });

    // Listen for real-time updates
    socket.on('taskAdded', (task) => {
      setTasks(prevTasks => [...prevTasks, task]);
    });

    socket.on('taskUpdated', (updatedTask) => {
      setTasks(prevTasks =>
        prevTasks.map(task => task._id === updatedTask._id ? updatedTask : task)
      );
    });

    socket.on('taskMoved', ({ taskId, newColumnId }) => {
      setTasks(prevTasks =>
        prevTasks.map(task =>
          task._id === taskId ? { ...task, columnId: newColumnId } : task
        )
      );
    });

    socket.on('taskDeleted', (taskId) => {
      setTasks(prevTasks => prevTasks.filter(task => task._id !== taskId));
    });

    return () => {
      socket.off('taskAdded');
      socket.off('taskUpdated');
      socket.off('taskMoved');
      socket.off('taskDeleted');
    };
  }, []);

  const onDragEnd = (result) => {
    if (!result.destination) return;

    const { draggableId, source, destination } = result;
    const taskId = draggableId;
    const newColumnId = destination.droppableId;
    const oldColumnId = source.droppableId;

    if (oldColumnId === newColumnId) return;

    // Optimistic update
    setTasks(prevTasks =>
      prevTasks.map(task =>
        task._id === taskId ? { ...task, columnId: newColumnId } : task
      )
    );

    // Send update to server
    axios.put(`http://localhost:5000/api/tasks/${taskId}`, { columnId: newColumnId })
      .then(response => {
        socket.emit('taskMoved', { taskId, newColumnId });
      })
      .catch(error => {
        console.error('Error moving task:', error);
        // Revert on error
        setTasks(prevTasks =>
          prevTasks.map(task =>
            task._id === taskId ? { ...task, columnId: oldColumnId } : task
          )
        );
      });
  };

  const addTask = () => {
    if (!newTask.trim()) return;

    const newTaskObj = {
      text: newTask,
      columnId: 'todo', // Default column
    };

    axios.post('http://localhost:5000/api/boards/1/tasks', newTaskObj)
      .then(response => {
        socket.emit('taskAdded', response.data);
        setNewTask('');
      })
      .catch(error => {
        console.error('Error adding task:', error);
      });
  };

  return (
    <div className="App">
      <h1>Project Management App</h1>
      <div className="task-form">
        <input
          type="text"
          value={newTask}
          onChange={(e) => setNewTask(e.target.value)}
          placeholder="Enter task description"
        />
        <button onClick={addTask}>Add Task</button>
      </div>
      <DragDropContext onDragEnd={onDragEnd}>
        <div className="board">
          {boards.map(board => (
            <div key={board._id} className="board-column">
              <h2>{board.name}</h2>
              <Droppable droppableId={board._id}>
                {(provided) => (
                  <div
                    className="tasks"
                    {...provided.droppableProps}
                    ref={provided.innerRef}
