**App.tsx:**
```tsx
import React, { useState, useEffect } from 'react';
import Board from './Board';
import io from 'socket.io-client';

const socket = io('http://localhost:3001');

const App: React.FC = () => {
  const [boards, setBoards] = useState([
    { id: 'board-1', title: 'Project Board', columns: [
      { id: 'column-1', title: 'To Do', tasks: [
        { id: 'task-1', title: 'Task 1' },
        { id: 'task-2', title: 'Task 2' }
      ]},
      { id: 'column-2', title: 'In Progress', tasks: [] },
      { id: 'column-3', title: 'Done', tasks: [] }
    ]}
  ]);

  useEffect(() => {
    socket.on('taskMoved', (data) => {
      setBoards(prevBoards => {
        return prevBoards.map(board => {
          if (board.id === data.boardId) {
            return {
              ...board,
              columns: board.columns.map(column => {
                if (column.id === data.fromColumnId) {
                  return {
                    ...column,
                    tasks: column.tasks.filter(task => task.id !== data.taskId)
                  };
                }
                if (column.id === data.toColumnId) {
                  const task = board.columns
                    .find(c => c.id === data.fromColumnId)?.tasks
                    .find(t => t.id === data.taskId);
                  if (task) {
                    return {
                      ...column,
                      tasks: [...column.tasks, task]
                    };
                  }
                }
                return column;
              })
            };
          }
          return board;
        });
      });
    });

    return () => {
      socket.off('taskMoved');
    };
  }, []);

  const handleDragEnd = (result: any) => {
    if (!result.destination) return;

    const { source, destination } = result;
    const boardId = 'board-1'; // For simplicity, we're only handling one board

    const taskId = source.droppableId.split('-')[1]; // Assuming task IDs are like 'task-1'
    const fromColumnId = source.droppableId;
    const toColumnId = destination.droppableId;

    // Optimistically update the UI
    setBoards(prevBoards => {
      return prevBoards.map(board => {
        if (board.id === boardId) {
          return {
            ...board,
            columns: board.columns.map(column => {
              if (column.id === fromColumnId) {
                return {
                  ...column,
                  tasks: column.tasks.filter(task => task.id !== taskId)
                };
              }
              if (column.id === toColumnId) {
                const task = board.columns
                  .find(c => c.id === fromColumnId)?.tasks
                  .find(t => t.id === taskId);
                if (task) {
                  return {
                    ...column,
                    tasks: [...column.tasks, task]
                  };
                }
              }
              return column;
            })
          };
        }
        return board;
      });
    });

    // Send the move to the server
    socket.emit('taskMoved', {
      boardId,
      taskId,
      fromColumnId,
      toColumnId
    });
  };

  return (
    <div className="App">
      <h1>Project Management App</h1>
      <Board boards={boards} onDragEnd={handleDragEnd} />
    </div>
  );
};

export default App;
```

