```javascript
const express = require("express");
const http = require("http");
const socketIo = require("socket.io");
const tasks = require("./tasks");

const app = express();
const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "http://localhost:3000", // Allow frontend to connect
    methods: ["GET", "POST"]
  }
});

// Serve static files (if needed)
app.use(express.static("public"));

// Socket.io connection handler
io.on("connection", (socket) => {
  console.log("A user connected:", socket.id);

  // Send initial tasks to the new client
  socket.emit("init-tasks", tasks);

  // Handle task movement
  socket.on("move-task", ({ taskId, fromColumn, toColumn }) => {
    // Remove task from source column
    const taskIndex = tasks[fromColumn].findIndex(t => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = tasks[fromColumn].splice(taskIndex, 1);

    // Add task to destination column
    tasks[toColumn].push(task);

    // Broadcast the change to all clients
    io.emit("tasks-updated", tasks);
  });

  socket.on("disconnect", () => {
    console.log("A user disconnected:", socket.id);
  });
});

const PORT = 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

