```tsx
import React, { useState, useEffect } from "react";
import { io, Socket } from "socket.io-client";
import { Task, Columns, Column } from "../types";
import { ColumnComponent } from "./Column";

export const Board: React.FC = () => {
  const [tasks, setTasks] = useState<Columns>({
    "to-do": [],
    "in-progress": [],
    done: [],
  });
  const [socket, setSocket] = useState<Socket | null>(null);

  useEffect(() => {
    // Connect to Socket.io server
    const newSocket = io("http://localhost:4000");
    setSocket(newSocket);

    // Listen for initial tasks
    newSocket.on("init-tasks", (initialTasks: Columns) => {
      setTasks(initialTasks);
    });

    // Listen for real-time updates
    newSocket.on("tasks-updated", (updatedTasks: Columns) => {
      setTasks(updatedTasks);
    });

    return () => {
      newSocket.disconnect();
    };
  }, []);

  const handleDragStart = (e: React.DragEvent<HTMLDivElement>, taskId: string) => {
    e.dataTransfer.setData("taskId", taskId);
  };

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>, toColumn: string) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData("taskId");
    if (socket) {
      socket.emit("move-task", {
        taskId,
        fromColumn: Object.keys(tasks).find((col) =>
          tasks[col].some((task) => task.id === taskId)
        ),
        toColumn,
      });
    }
  };

  return (
    <div style={{ display: "flex", justifyContent: "space-around" }}>
      {Object.entries(tasks).map(([columnName, columnTasks]) => (
        <ColumnComponent
          key={columnName}
          title={columnName}
          tasks={columnTasks}
          onDrop={handleDrop}
          onDragOver={handleDragOver}
          onDragStart={handleDragStart}
        />
      ))}
    </div>
  );
};
```

