### **1. `server.js` (Backend)**
Handles WebSocket connections and serves static files.
```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Serve static files (HTML, CSS, JS)
app.use(express.static(__dirname));

// In-memory task storage (replace with a database in production)
let tasks = [
    { id: 1, text: 'Design UI', status: 'todo' },
    { id: 2, text: 'Implement drag-and-drop', status: 'in-progress' },
    { id: 3, text: 'Add real-time sync', status: 'done' }
];

// Socket.io connection handler
io.on('connection', (socket) => {
    console.log('New client connected');
    socket.emit('init', tasks); // Send current tasks to the new client

    // Handle task updates from clients
    socket.on('updateTasks', (updatedTasks) => {
        tasks = updatedTasks;
        socket.broadcast.emit('updateTasks', tasks); // Broadcast to all clients except sender
    });

    socket.on('disconnect', () => {
        console.log('Client disconnected');
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on http://localhost:${PORT}`);
});
```

