    '1': { id: '1', status: 'todo', content: 'Task 1' },
    '2': { id: '2', status: 'todo', content: 'Task 2' },
    '3': { id: '3', status: 'in-progress', content: 'Task 3' },
    '4': { id: '4', status: 'done', content: 'Task 4' }
};

// Socket.io connection
