        const task = tasks[data.taskId];
        if (task) {
            task.status = data.newStatus;
            io.emit('updateTask', {
                taskId: data.taskId,
                newStatus: data.newStatus
            });
        }
    });

    socket.on('disconnect', () => {
        console.log('Client disconnected');
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
