### 5. `public/app.js`
```javascript
document.addEventListener('DOMContentLoaded', () => {
    const socket = io();
    const boards = {
        'todo': document.getElementById('todo-tasks'),
        'in-progress': document.getElementById('in-progress-tasks'),
        'done': document.getElementById('done-tasks')
    };

    // Initialize tasks from server
    socket.on('initialTasks', (tasks) => {
        Object.values(tasks).forEach(task => {
            const taskElement = createTaskElement(task);
            boards[task.status].appendChild(taskElement);
        });
    });

    // Handle real-time updates
    socket.on('updateTask', (data) => {
        const taskElement = document.querySelector(`[data-id="${data.taskId}"]`);
        if (taskElement) {
            const oldBoard = taskElement.parentElement;
            const newBoard = boards[data.newStatus];

            // Remove from old board
            oldBoard.removeChild(taskElement);

            // Add to new board
            newBoard.appendChild(taskElement);
        }
    });

    // Drag and drop functionality
    document.querySelectorAll('.tasks').forEach(tasksContainer => {
        tasksContainer.addEventListener('dragover', (e) => {
            e.preventDefault();
        });

        tasksContainer.addEventListener('dragenter', (e) => {
            e.preventDefault();
            e.target.classList.add('drag-over');
        });

        tasksContainer.addEventListener('dragleave', (e) => {
            e.target.classList.remove('drag-over');
        });

        tasksContainer.addEventListener('drop', (e) => {
            e.preventDefault();
            e.target.classList.remove('drag-over');

            const taskId = e.dataTransfer.getData('text/plain');
            const taskElement = document.querySelector(`[data-id="${taskId}"]`);
            if (taskElement) {
                const newStatus = e.target.parentElement.id;
                socket.emit('taskMoved', { taskId, newStatus });
            }
        });
    });

    function createTaskElement(task) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task';
        taskElement.draggable = true;
        taskElement.dataset.id = task.id;
        taskElement.textContent = task.content;
        return taskElement;
    }
});
```

