const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// In-memory data store (replace with a real DB in production)
let boards = {
  'board1': {
    name: 'Project Board',
    columns: [
      { id: 'todo', name: 'To Do', tasks: ['Task 1', 'Task 2'] },
      { id: 'inprogress', name: 'In Progress', tasks: [] },
      { id: 'done', name: 'Done', tasks: [] }
    ]
  }
};

// Serve static files (frontend)
app.use(express.static('public'));

// Socket.io: Handle real-time updates
io.on('connection', (socket) => {
  console.log('New client connected');
  socket.emit('boardState', boards); // Send initial state

  // Handle task movement
  socket.on('moveTask', (data) => {
    const { boardId, fromColumnId, toColumnId, taskIndex } = data;
    const task = boards[boardId].columns
      .find(col => col.id === fromColumnId)
      .tasks.splice(taskIndex, 1)[0];

    boards[boardId].columns
      .find(col => col.id === toColumnId)
      .tasks.push(task);

    io.emit('boardState', boards); // Broadcast to all clients
  });

  socket.on('disconnect', () => console.log('Client disconnected'));
});

const PORT = 3000;
server.listen(PORT, () => console.log(`Server running on http://localhost:${PORT}`));
