```javascript
document.addEventListener('DOMContentLoaded', () => {
    const socket = io();
    const taskForm = document.getElementById('newTaskInput');
    const addTaskBtn = document.getElementById('addTaskBtn');
    const todoTasks = document.getElementById('todo-tasks');
    const inProgressTasks = document.getElementById('in-progress-tasks');
    const doneTasks = document.getElementById('done-tasks');

    let tasks = [];

    // Initialize drag-and-drop for each column
    new Sortable(todoTasks, {
        group: 'tasks',
        animation: 150,
        onEnd: () => updateTasks()
    });

    new Sortable(inProgressTasks, {
        group: 'tasks',
        animation: 150,
        onEnd: () => updateTasks()
    });

    new Sortable(doneTasks, {
        group: 'tasks',
        animation: 150,
        onEnd: () => updateTasks()
    });

    // Add new task
    addTaskBtn.addEventListener('click', () => {
        const taskText = taskForm.value.trim();
        if (taskText) {
            const newTask = {
                id: Date.now(),
                text: taskText,
                status: 'todo'
            };
            tasks.push(newTask);
            socket.emit('updateTasks', tasks);
            taskForm.value = '';
        }
    });

    // Update tasks UI
    function updateTasksUI() {
        todoTasks.innerHTML = '';
        inProgressTasks.innerHTML = '';
        doneTasks.innerHTML = '';

        tasks.forEach(task => {
            const taskElement = document.createElement('div');
            taskElement.className = 'task';
            taskElement.textContent = task.text;
            taskElement.dataset.id = task.id;
            taskElement.dataset.status = task.status;

            if (task.status === 'todo') {
                todoTasks.appendChild(taskElement);
            } else if (task.status === 'in-progress') {
                inProgressTasks.appendChild(taskElement);
            } else if (task.status === 'done') {
                doneTasks.appendChild(taskElement);
            }
        });
    }

    // Update tasks and sync with server
    function updateTasks() {
        // Update status based on column
        document.querySelectorAll('.task').forEach(taskElement => {
            const taskId = parseInt(taskElement.dataset.id);
            const task = tasks.find(t => t.id === taskId);
            if (task) {
                task.status = taskElement.parentElement.id.replace('-tasks', '');
            }
        });

        socket.emit('updateTasks', tasks);
    }

    // Socket.io event handlers
    socket.on('init', (initialTasks) => {
        tasks = initialTasks;
        updateTasksUI();
    });

    socket.on('updateTasks', (updatedTasks) => {
        tasks = updatedTasks;
        updateTasksUI();
    });
});
```

