```javascript
// Connect to the Socket.IO server
const socket = io();

// Function to allow drop
function allowDrop(ev) {
    ev.preventDefault();
}

// Function to handle drop
function drop(ev) {
    ev.preventDefault();
    const data = ev.dataTransfer.getData("text");
    const taskId = data.split('-')[1]; // Extract task ID from data
    const newStatus = ev.target.id.split('-')[0]; // Extract column ID

    // Emit the task movement to the server
    socket.emit('moveTask', { taskId, newStatus });
}

// Function to add a new task
function addTask() {
    const taskInput = document.getElementById('task-input');
    const taskName = taskInput.value.trim();
    if (taskName) {
        socket.emit('addTask', { name: taskName });
        taskInput.value = '';
    }
}

// Function to create a task element
function createTaskElement(task) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.id = `task-${task.id}`;
    taskElement.draggable = true;
    taskElement.innerHTML = `
        <div>${task.name}</div>
    `;

    // Set up drag start event
    taskElement.addEventListener('dragstart', (ev) => {
        ev.dataTransfer.setData("text", `task-${task.id}`);
    });

    return taskElement;
}

// Update the board with tasks
function updateBoard(tasks) {
    // Clear all columns
    document.getElementById('todo-tasks').innerHTML = '';
    document.getElementById('in-progress-tasks').innerHTML = '';
    document.getElementById('done-tasks').innerHTML = '';

    // Add tasks to the appropriate columns
    tasks.forEach(task => {
        const taskElement = createTaskElement(task);
        const column = document.getElementById(`${task.status}-tasks`);
        column.appendChild(taskElement);
    });
}

// Socket.IO event listeners
socket.on('initialData', (tasks) => {
    updateBoard(tasks);
});

socket.on('taskAdded', (task) => {
    const taskElement = createTaskElement(task);
    const column = document.getElementById(`${task.status}-tasks`);
    column.appendChild(taskElement);
});

socket.on('taskMoved', (tasks) => {
    updateBoard(tasks);
});
