```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// In-memory storage for tasks
let tasks = [
    { id: 1, name: 'Task 1', status: 'todo' },
    { id: 2, name: 'Task 2', status: 'in-progress' },
    { id: 3, name: 'Task 3', status: 'done' }
];

// Serve static files
app.use(express.static('public'));

// Socket.IO connection
io.on('connection', (socket) => {
    console.log('New client connected');

    // Send initial tasks to the new client
    socket.emit('initialData', tasks);

    // Handle task addition
    socket.on('addTask', (task) => {
        const newTask = {
            id: tasks.length + 1,
            name: task.name,
            status: 'todo'
        };
        tasks.push(newTask);
        io.emit('taskAdded', newTask); // Broadcast to all clients
    });

    // Handle task movement
    socket.on('moveTask', ({ taskId, newStatus }) => {
        tasks = tasks.map(task => {
            if (task.id == taskId) {
                return { ...task, status: newStatus };
            }
            return task;
        });
        io.emit('taskMoved', tasks); // Broadcast to all clients
    });

    // Handle disconnection
    socket.on('disconnect', () => {
        console.log('Client disconnected');
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

