```javascript
document.addEventListener('DOMContentLoaded', () => {
    const socket = io();

    // Initialize drag-and-drop
    const tasks = document.querySelectorAll('.task');
    const boards = document.querySelectorAll('.board');

    tasks.forEach(task => {
        task.addEventListener('dragstart', dragStart);
        task.addEventListener('dragend', dragEnd);
    });

    boards.forEach(board => {
        board.addEventListener('dragover', dragOver);
        board.addEventListener('dragenter', dragEnter);
        board.addEventListener('dragleave', dragLeave);
        board.addEventListener('drop', drop);
    });

    function dragStart() {
        this.classList.add('dragging');
        // Set the drag data (required for Firefox)
        event.dataTransfer.setData('text/plain', this.dataset.id);
    }

    function dragEnd() {
        this.classList.remove('dragging');
    }

    function dragOver(e) {
        e.preventDefault();
    }

    function dragEnter(e) {
        e.preventDefault();
        this.classList.add('drag-over');
    }

    function dragLeave() {
        this.classList.remove('drag-over');
    }

    function drop(e) {
        e.preventDefault();
        this.classList.remove('drag-over');

        const taskId = event.dataTransfer.getData('text/plain');
        const taskElement = document.querySelector(`[data-id="${taskId}"]`);
        const newBoardId = this.id;
        const newBoard = document.getElementById(newBoardId);

        // Remove task from old board (if it was moved within the same board, this won't do anything)
        const oldBoard = taskElement.parentElement.parentElement;
        oldBoard.querySelector('.tasks').removeChild(taskElement);

        // Add task to new board
        newBoard.querySelector('.tasks').appendChild(taskElement);

        // Send update to server
        socket.emit('taskMoved', {
            taskId: taskId,
            newStatus: newBoardId
        });
    }

    // Listen for real-time updates from the server
    socket.on('updateTask', (data) => {
        const taskElement = document.querySelector(`[data-id="${data.taskId}"]`);
        if (taskElement) {
            const oldBoard = taskElement.parentElement.parentElement;
            const newBoard = document.getElementById(data.newStatus);

            // Remove task from old board
            oldBoard.querySelector('.tasks').removeChild(taskElement);

            // Add task to new board
            newBoard.querySelector('.tasks').appendChild(taskElement);
        }
    });
});
