```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// In-memory data store
let boards = {
  'board1': {
    name: 'Project Board',
    columns: [
      { id: 'todo', name: 'To Do', tasks: ['Task 1', 'Task 2'] },
      { id: 'inprogress', name: 'In Progress', tasks: [] },
      { id: 'done', name: 'Done', tasks: [] }
    ]
  }
};

// Serve static files from the 'public' directory
app.use(express.static('public'));

// Socket.io connection handler
io.on('connection', (socket) => {
  console.log('New client connected');

  // Send the current board state to the new client
  socket.emit('boardState', boards);

  // Handle task movement
  socket.on('moveTask', (data) => {
    const { boardId, fromColumnId, toColumnId, taskIndex } = data;

    // Remove task from the source column
    const task = boards[boardId].columns.find(col => col.id === fromColumnId).tasks.splice(taskIndex, 1)[0];

    // Add task to the target column
    boards[boardId].columns.find(col => col.id === toColumnId).tasks.push(task);

    // Broadcast the updated board state to all clients
    io.emit('boardState', boards);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

