  <script>
    const socket = io();
    const boardElement = document.getElementById('board');

    // Handle board state updates from the server
    socket.on('boardState', (boards) => {
      boardElement.innerHTML = '';
      const board = boards['board1'];

      board.columns.forEach(column => {
        const columnElement = document.createElement('div');
        columnElement.className = 'column';
        columnElement.innerHTML = `
          <div class="column-header">${column.name}</div>
          ${column.tasks.map((task, index) => `
            <div class="task" draggable="true" data-column-id="${column.id}" data-task-index="${index}">
              ${task}
            </div>
          `).join('')}
        `;
        boardElement.appendChild(columnElement);
      });

      // Add drag-and-drop event listeners
      setupDragAndDrop();
    });

    function setupDragAndDrop() {
      let draggedTask = null;

      document.querySelectorAll('.task').forEach(task => {
        task.addEventListener('dragstart', (e) => {
          draggedTask = {
            element: e.target,
            columnId: e.target.dataset.columnId,
            taskIndex: e.target.dataset.taskIndex
          };
          e.target.classList.add('dragging');
          e.dataTransfer.setData('text/plain', ''); // Required for Firefox
        });

        task.addEventListener('dragend', (e) => {
          e.target.classList.remove('dragging');
          draggedTask = null;
        });
      });

      document.querySelectorAll('.column').forEach(column => {
        column.addEventListener('dragover', (e) => {
          e.preventDefault();
        });

        column.addEventListener('drop', (e) => {
          e.preventDefault();
          if (!draggedTask) return;

          const columnId = column.querySelector('.column-header').parentElement.dataset.columnId || column.id;
          if (columnId === draggedTask.columnId) return; // No change

          // Find the task index in the source column
          const taskIndex = draggedTask.taskIndex;

          // Send the move task event to the server
          socket.emit('moveTask', {
            boardId: 'board1',
            fromColumnId: draggedTask.columnId,
            toColumnId: columnId,
            taskIndex: parseInt(taskIndex)
          });
        });
      });
    }
  </script>
</body>
