            processMarketOrder(order);
        } else {
            processLimitOrder(order);
        }

        // If order wasn't fully filled, add to the book
        if (!order->isFilled()) {
            orderBook_.addOrder(order);
        }
    }

    // Process a limit order
    void processLimitOrder(std::shared_ptr<Order> order) {
        while (!order->isFilled()) {
            auto [bestPrice, bestLevel] = orderBook_.getBestLevel(order->getSide());

            // Check if we can match at this price
            if ((order->getSide() == OrderSide::BUY && order->getPrice() >= bestPrice) ||
                (order->getSide() == OrderSide::SELL && order->getPrice() <= bestPrice)) {

                if (!bestLevel || bestLevel->orders.empty()) {
                    break; // No more orders to match against
                }

                auto& existingOrder = bestLevel->orders.front();

                int matchQuantity = std::min(order->getQuantity(), existingOrder->getQuantity());

                // Execute the trade
                Trade trade(
                    order->getSide() == OrderSide::BUY ? order->getId() : existingOrder->getId(),
                    order->getSide() == OrderSide::SELL ? order->getId() : existingOrder->getId(),
                    bestPrice, matchQuantity
                );

                std::cout << "[TRADE] " << trade.getBuyOrderId() << " <-> " << trade.getSellOrderId()
                          << " | Price: " << trade.getPrice() << " | Quantity: " << trade.getQuantity()
                          << " | Time: " << std::chrono::system_clock::to_time_t(trade.getTimestamp()) << "\n";

                // Update quantities
                order->updateQuantity(matchQuantity);
                existingOrder->updateQuantity(matchQuantity);

                // If the existing order is fully filled, remove it
                if (existingOrder->isFilled()) {
                    orderBook_.removeOrder(existingOrder->getId());
                }
            } else {
                break; // Price condition not met
            }
        }
    }

    // Process a market order (matches immediately at best available prices)
    void processMarketOrder(std::shared_ptr<Order> order) {
        while (!order->isFilled()) {
            auto [bestPrice, bestLevel] = orderBook_.getBestLevel(order->getSide());

            if (!bestLevel || bestLevel->orders.empty()) {
                break; // No more orders to match against
            }

            auto& existingOrder = bestLevel->orders.front();

            int matchQuantity = std::min(order->getQuantity(), existingOrder->getQuantity());

            // Execute the trade
            Trade trade(
                order->getSide() == OrderSide::BUY ? order->getId() : existingOrder->getId(),
                order->getSide() == OrderSide::SELL ? order->getId() : existingOrder->getId(),
                bestPrice, matchQuantity
            );

            std::cout << "[TRADE] " << trade.getBuyOrderId() << " <-> " << trade.getSellOrderId()
                      << " | Price: " << trade.getPrice() << " | Quantity: " << trade.getQuantity()
                      << " | Time: " << std::chrono::system_clock::to_time_t(trade.getTimestamp()) << "\n";

            // Update quantities
            order->updateQuantity(matchQuantity);
            existingOrder->updateQuantity(matchQuantity);

            // If the existing order is fully filled, remove it
            if (existingOrder->isFilled()) {
                orderBook_.removeOrder(existingOrder->getId());
            }
        }
    }
};

