    uint64_t client_id;
    double price;
    uint64_t quantity;
    OrderSide side;
    OrderType type;
    uint64_t timestamp;

    // For lock-free queue
    std::atomic<Order*> next{nullptr};
};

struct OrderBookLevel {
    double price;
    uint64_t quantity;
};

// ======================
// Matching Engine
// ======================

class OrderBook {
private:
    std::mutex mutex_;
    std::vector<OrderBookLevel> bids_;
    std::vector<OrderBookLevel> asks_;
    std::unordered_map<uint64_t, Order*> active_orders_;

    // For fast price lookup (sorted by price)
    void update_levels(std::vector<OrderBookLevel>& levels, double price, int64_t delta) {
        auto it = std::lower_bound(levels.begin(), levels.end(), price,
            [](const OrderBookLevel& l, double p) { return l.price < p; });

        if (it != levels.end() && it->price == price) {
            it->quantity += delta;
            if (it->quantity <= 0) {
                levels.erase(it);
            }
        } else if (delta > 0) {
            levels.insert(it, {price, static_cast<uint64_t>(delta)});
        }
    }

public:
    bool add_order(Order* order) {
        std::lock_guard<std::mutex> lock(mutex_);

        if (order->type == OrderType::MARKET) {
            // Market orders match immediately
            return match_order(order);
        }

        // Limit order - add to book
        active_orders_[order->order_id] = order;
        update_levels(order->side == OrderSide::BUY ? bids_ : asks_,
                     order->price, order->quantity);
        return true;
    }

    bool cancel_order(uint64_t order_id) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = active_orders_.find(order_id);
        if (it != active_orders_.end()) {
            active_orders_.erase(it);
            return true;
        }
        return false;
    }

    bool match_order(Order* order) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto& opposite_book = (order->side == OrderSide::BUY) ? asks_ : bids_;
        auto& opposite_orders = (order->side == OrderSide::BUY) ? active_orders_ : active_orders_;

        uint64_t remaining = order->quantity;

        while (remaining > 0 && !opposite_book.empty()) {
            OrderBookLevel& best_level = opposite_book.front();
            if ((order->side == OrderSide::BUY && order->price >= best_level.price) ||
                (order->side == OrderSide::SELL && order->price <= best_level.price)) {

                // Execute trade
                uint64_t trade_quantity = std::min(remaining, best_level.quantity);
                remaining -= trade_quantity;
                best_level.quantity -= trade_quantity;

                // In a real system, we'd record the trade here

                if (best_level.quantity == 0) {
                    opposite_book.erase(opposite_book.begin());
                }
            } else {
                break;
            }
        }

        if (remaining > 0) {
            // Order wasn't fully filled - add remaining to book
            if (order->type == OrderType::LIMIT) {
                order->quantity = remaining;
                active_orders_[order->order_id] = order;
                update_levels(order->side == OrderSide::BUY ? bids_ : asks_,
                            order->price, remaining);
            }
            return false; // Not fully filled
        }
        return true; // Fully filled
    }

    std::vector<OrderBookLevel> get_bids() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return bids_;
    }

    std::vector<OrderBookLevel> get_asks() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return asks_;
    }
};

// ======================
// Lock-Free Order Queue
// ======================

class LockFreeQueue {
private:
    std::atomic<Order*> head_;
    std::atomic<Order*> tail_;

public:
    LockFreeQueue() : head_(nullptr), tail_(nullptr) {}

    void enqueue(Order* order) {
        order->next.store(nullptr, std::memory_order_relaxed);
        Order* expected_tail = tail_.load(std::memory_order_acquire);

        while (true) {
            if (tail_.compare_exchange_weak(expected_tail, order,
                std::memory_order_release, std::memory_order_relaxed)) {
                if (expected_tail) {
                    expected_tail->next.store(order, std::memory_order_release);
                } else {
                    head_.store(order, std::memory_order_release);
                }
                break;
            }
        }
    }

    Order* dequeue() {
        Order* expected_head = head_.load(std::memory_order_acquire);

        while (expected_head) {
            Order* next = expected_head->next.load(std::memory_order_acquire);
            if (head_.compare_exchange_weak(expected_head, next,
                std::memory_order_release, std::memory_order_relaxed)) {
                expected_head->next.store(nullptr, std::memory_order_relaxed);
                return expected_head;
            }
        }
        return nullptr;
    }
};

// ======================
// Order Processor
// ======================

class OrderProcessor {
private:
    OrderBook& order_book_;
    LockFreeQueue& order_queue_;
    std::atomic<bool> running_{true};
    std::thread worker_thread_;

    void process_orders() {
        while (running_) {
            Order* order = order_queue_.dequeue();
            if (order) {
                order_book_.add_order(order);
                // In a real system, we'd send acknowledgment to client
                delete order; // Simplified - would use object pool
            } else {
                // Sleep briefly to prevent busy waiting
                std::this_thread::sleep_for(std::chrono::microseconds(100));
            }
        }
    }

public:
    OrderProcessor(OrderBook& order_book, LockFreeQueue& order_queue)
        : order_book_(order_book), order_queue_(order_queue) {
        worker_thread_ = std::thread(&OrderProcessor::process_orders, this);
    }

    ~OrderProcessor() {
        running_ = false;
        if (worker_thread_.joinable()) {
            worker_thread_.join();
        }
    }

    void submit_order(Order* order) {
        order_queue_.enqueue(order);
    }
};

// ======================
// Network Interface
// ======================

class NetworkInterface {
private:
    int sock_fd_;
    OrderProcessor& order_processor_;
    std::thread listener_thread_;
    std::atomic<bool> running_{true};

    void handle_connection(int client_fd) {
        char buffer[1024];
        while (running_) {
            ssize_t bytes_read = read(client_fd, buffer, sizeof(buffer));
            if (bytes_read <= 0) break;

            // Parse order (simplified - real system would use proper protocol)
            Order* order = new Order;
            memcpy(&order->order_id, buffer, sizeof(order->order_id));
            memcpy(&order->client_id, buffer + sizeof(order->order_id), sizeof(order->client_id));
            memcpy(&order->price, buffer + sizeof(order->order_id) + sizeof(order->client_id), sizeof(order->price));
            memcpy(&order->quantity, buffer + sizeof(order->order_id) + sizeof(order->client_id) + sizeof(order->price), sizeof(order->quantity));
            order->side = static_cast<OrderSide>(buffer[sizeof(order->order_id) + sizeof(order->client_id) + sizeof(order->price) + sizeof(order->quantity)]);
            order->type = static_cast<OrderType>(buffer[sizeof(order->order_id) + sizeof(order->client_id) + sizeof(order->price) + sizeof(order->quantity) + 1]);
            order->timestamp = std::chrono::duration_cast<std::chrono::milliseconds>(
                std::chrono::system_clock::now().time_since_epoch()).count();

            order_processor_.submit_order(order);
        }
        close(client_fd);
    }

    void listen_for_connections() {
        int client_fd;
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);

        while (running_) {
            client_fd = accept(sock_fd_, (struct sockaddr*)&client_addr, &client_len);
            if (client_fd < 0) continue;

            // In a real system, we'd spawn a new thread or use async I/O
            handle_connection(client_fd);
        }
    }

public:
    NetworkInterface(OrderProcessor& order_processor, int port = 8080)
        : order_processor_(order_processor) {
        sock_fd_ = socket(AF_INET, SOCK_STREAM, 0);
        if (sock_fd_ < 0) {
            throw std::runtime_error("Failed to create socket");
        }

        sockaddr_in addr;
        addr.sin_family = AF_INET;
        addr.sin_addr.s_addr = INADDR_ANY;
        addr.sin_port = htons(port);

        if (bind(sock_fd_, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
            throw std::runtime_error("Failed to bind socket");
        }

        if (listen(sock_fd_, 10) < 0) {
            throw std::runtime_error("Failed to listen on socket");
        }

        listener_thread_ = std::thread(&NetworkInterface::listen_for_connections, this);
    }

    ~NetworkInterface() {
        running_ = false;
        if (listener_thread_.joinable()) {
            listener_thread_.join();
        }
        close(sock_fd_);
    }
};

