Below is a simplified but functional implementation of a low-latency trading platform in C++ that demonstrates the core architecture while allowing for future scaling. This example focuses on the critical path (order matching) with lock-free communication between components.

```cpp
#include <atomic>
#include <chrono>
#include <iostream>
#include <map>
#include <memory>
#include <optional>
#include <string>
#include <thread>
#include <unordered_map>
#include <vector>

// ======================
// Core Data Structures
// ======================

enum class OrderSide { Buy, Sell };
enum class OrderType { Market, Limit, Stop };

struct Order {
    uint64_t order_id;
    std::string symbol;
    OrderSide side;
    OrderType type;
    uint64_t price;    // In smallest currency unit (e.g., cents)
    uint64_t quantity;
    uint64_t timestamp; // Nanoseconds since epoch
};

struct Trade {
    uint64_t trade_id;
    std::string symbol;
    uint64_t price;
    uint64_t quantity;
    uint64_t buy_order_id;
    uint64_t sell_order_id;
    uint64_t timestamp;
};

// ======================
// Lock-Free Ring Buffer
// ======================

template <typename T>
class RingBuffer {
public:
    explicit RingBuffer(size_t capacity)
        : buffer(capacity), capacity(capacity) {}

    bool push(const T& item) {
        size_t current_tail = tail.load(std::memory_order_relaxed);
        size_t next_tail = (current_tail + 1) % capacity;
        if (next_tail == head.load(std::memory_order_acquire)) {
            return false; // Full
        }
        buffer[current_tail] = item;
        tail.store(next_tail, std::memory_order_release);
        return true;
    }

    std::optional<T> pop() {
        size_t current_head = head.load(std::memory_order_relaxed);
        if (current_head == tail.load(std::memory_order_acquire)) {
            return std::nullopt; // Empty
        }
        T item = std::move(buffer[current_head]);
        head.store((current_head + 1) % capacity, std::memory_order_release);
        return item;
    }

private:
    std::vector<T> buffer;
    const size_t capacity;
    alignas(64) std::atomic<size_t> head{0};
    alignas(64) std::atomic<size_t> tail{0};
};

// ======================
// Order Book Implementation
// ======================

class OrderBook {
public:
    struct Level {
        uint64_t price;
        uint64_t quantity;
    };

    void addOrder(const Order& order) {
        if (order.side == OrderSide::Buy) {
            bids[order.price] += order.quantity;
        } else {
            asks[order.price] += order.quantity;
        }
    }

    void cancelOrder(uint64_t order_id) {
        // In a real system, we'd track orders by ID
        // This simplified version cancels all orders at a price level
        // (Not realistic but sufficient for demonstration)
        for (auto it = bids.begin(); it != bids.end(); ) {
            if (it->second == order_id) {
                it = bids.erase(it);
            } else {
                ++it;
            }
        }
        for (auto it = asks.begin(); it != asks.end(); ) {
            if (it->second == order_id) {
                it = asks.erase(it);
            } else {
                ++it;
            }
        }
    }

    std::vector<Level> getTopOfBook(size_t depth = 5) const {
        std::vector<Level> result;
        size_t count = 0;

        for (const auto& [price, qty] : bids) {
            if (count++ >= depth) break;
            result.push_back({price, qty});
        }

        count = 0;
        for (const auto& [price, qty] : asks) {
            if (count++ >= depth) break;
            result.push_back({price, qty});
        }

        return result;
    }

    const std::map<uint64_t, uint64_t, std::greater<>>& getBids() const { return bids; }
    const std::map<uint64_t, uint64_t>& getAsks() const { return asks; }

private:
    std::map<uint64_t, uint64_t, std::greater<>> bids; // Descending order
    std::map<uint64_t, uint64_t> asks; // Ascending order
};

// ======================
// Matching Engine
// ======================

class MatchingEngine {
public:
    MatchingEngine() : next_order_id(1), next_trade_id(1) {}

    Trade matchOrder(Order order) {
        Trade trade{};
        trade.timestamp = getCurrentTimestamp();

        if (order.type == OrderType::Market) {
            trade = matchMarketOrder(std::move(order));
        } else if (order.type == OrderType::Limit) {
            trade = matchLimitOrder(std::move(order));
        }

        return trade;
    }

private:
    OrderBook order_book;
    uint64_t next_order_id;
    uint64_t next_trade_id;

    Trade matchMarketOrder(Order order) {
        Trade trade{};
        trade.trade_id = next_trade_id++;
        trade.timestamp = getCurrentTimestamp();

        if (order.side == OrderSide::Buy) {
            // Buy market order: match against best asks
            while (order.quantity > 0 && !order_book.getAsks().empty()) {
                auto best_ask = order_book.getAsks().begin();
                uint64_t match_qty = std::min(order.quantity, best_ask->second);
                trade.price = best_ask->first;
                trade.quantity = match_qty;
                trade.buy_order_id = order.order_id;
                trade.sell_order_id = 0; // Would be set to actual sell order ID in real system

                order.quantity -= match_qty;
                order_book.cancelOrder(best_ask->second); // Simplified cancellation
            }
        } else {
            // Sell market order: match against best bids
            while (order.quantity > 0 && !order_book.getBids().empty()) {
                auto best_bid = order_book.getBids().begin();
                uint64_t match_qty = std::min(order.quantity, best_bid->second);
                trade.price = best_bid->first;
                trade.quantity = match_qty;
                trade.sell_order_id = order.order_id;
                trade.buy_order_id = 0; // Would be set to actual buy order ID in real system

                order.quantity -= match_qty;
                order_book.cancelOrder(best_bid->second); // Simplified cancellation
            }
        }

        if (order.quantity > 0) {
            // If there's remaining quantity, add to order book
            order.order_id = next_order_id++;
            order_book.addOrder(order);
        }

        return trade;
    }

    Trade matchLimitOrder(Order order) {
        Trade trade{};
        trade.trade_id = next_trade_id++;
        trade.timestamp = getCurrentTimestamp();

        if (order.side == OrderSide::Buy) {
            // Buy limit order: match against asks <= limit price
            while (order.quantity > 0 && !order_book.getAsks().empty()) {
                auto best_ask = order_book.getAsks().begin();
                if (best_ask->first > order.price) break; // No more matches

                uint64_t match_qty = std::min(order.quantity, best_ask->second);
                trade.price = best_ask->first;
                trade.quantity = match_qty;
                trade.buy_order_id = order.order_id;
                trade.sell_order_id = 0;

                order.quantity -= match_qty;
                order_book.cancelOrder(best_ask->second);
            }
        } else {
            // Sell limit order: match against bids >= limit price
            while (order.quantity > 0 && !order_book.getBids().empty()) {
                auto best_bid = order_book.getBids().begin();
                if (best_bid->first < order.price) break; // No more matches

                uint64_t match_qty = std::min(order.quantity, best_bid->second);
                trade.price = best_bid->first;
                trade.quantity = match_qty;
                trade.sell_order_id = order.order_id;
                trade.buy_order_id = 0;

                order.quantity -= match_qty;
                order_book.cancelOrder(best_bid->second);
            }
        }

        if (order.quantity > 0) {
            order.order_id = next_order_id++;
            order_book.addOrder(order);
        }

        return trade;
    }

    uint64_t getCurrentTimestamp() {
        auto now = std::chrono::system_clock::now();
        auto duration = now.time_since_epoch();
        return static_cast<uint64_t>(
            std::chrono::duration_cast<std::chrono::nanoseconds>(duration).count()
        );
    }
};

