            auto order_opt = order_buffer.pop();
            if (!order_opt) {
                std::this_thread::sleep_for(std::chrono::microseconds(10));
                continue;
            }

            const Order& order = *order_opt;

            // Validate order (simplified)
            if (order.quantity == 0) {
                std::cerr << "Invalid order quantity: " << order.order_id << std::endl;
                continue;
            }

            // Pass to matching engine
