            if (trade.quantity > 0) {
                // Handle trade (e.g., send to risk management, log trade)
                std::cout << "Trade executed: " << trade.quantity
                          << " @ " << trade.price / 100.0 << " ("
                          << (trade.buy_order_id ? "Buy" : "Sell")
                          << " order " << (trade.buy_order_id ? trade.buy_order_id : trade.sell_order_id)
                          << ")" << std::endl;
            }
        }
    }

    void stop() {
        running = false;
    }

private:
