// ======================
// Order Book Implementation
// ======================

class OrderBook {
private:
    struct PriceLevel {
        double price;
        uint64_t total_quantity;
        std::vector<Order*> orders;

        PriceLevel(double p) : price(p), total_quantity(0) {}
    };

    std::string symbol_;
    std::unordered_map<double, std::unique_ptr<PriceLevel>> bids_;
    std::unordered_map<double, std::unique_ptr<PriceLevel>> asks_;

    // For price-time priority
    std::vector<std::unique_ptr<PriceLevel>> bid_levels_;
    std::vector<std::unique_ptr<PriceLevel>> ask_levels_;

    std::mutex mutex_;

public:
    explicit OrderBook(std::string symbol) : symbol_(std::move(symbol)) {}

    bool addOrder(Order* order) {
        std::lock_guard<std::mutex> lock(mutex_);

        if (order->side == OrderSide::BUY) {
            return addBid(order);
        } else {
            return addAsk(order);
        }
    }

    bool cancelOrder(uint64_t order_id) {
        std::lock_guard<std::mutex> lock(mutex_);
        // Implementation would search through bids and asks
        // For simplicity, we'll just mark as cancelled
        return false;
    }

    std::vector<Order*> matchOrder(Order* incoming_order) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<Order*> matched_orders;

        if (incoming_order->side == OrderSide::BUY) {
            matched_orders = matchBuyOrder(incoming_order);
        } else {
            matched_orders = matchSellOrder(incoming_order);
        }

        return matched_orders;
    }

private:
    bool addBid(Order* order) {
        if (order->type == OrderType::MARKET) {
            // Market buy orders take all available asks
            return matchMarketOrder(order);
        }

        // For limit orders
        auto& level = bids_[order->price];
        if (!level) {
            level = std::make_unique<PriceLevel>(order->price);
            bid_levels_.emplace_back(level.get());
        }

        level->orders.push_back(order);
        level->total_quantity += order->quantity;
        return true;
    }

    bool addAsk(Order* order) {
        if (order->type == OrderType::MARKET) {
            // Market sell orders take all available bids
            return matchMarketOrder(order);
        }

        auto& level = asks_[order->price];
        if (!level) {
            level = std::make_unique<PriceLevel>(order->price);
            ask_levels_.emplace_back(level.get());
        }

        level->orders.push_back(order);
        level->total_quantity += order->quantity;
        return true;
    }

    std::vector<Order*> matchBuyOrder(Order* buy_order) {
        std::vector<Order*> matched;

        // Sort asks by price (ascending) and time (FIFO within same price)
        auto compare = [](const std::unique_ptr<PriceLevel>& a,
                          const std::unique_ptr<PriceLevel>& b) {
            if (a->price != b->price) return a->price < b->price;
            return a->orders.front()->timestamp < b->orders.front()->timestamp;
        };
        std::sort(ask_levels_.begin(), ask_levels_.end(), compare);

        uint64_t remaining = buy_order->quantity;

        for (auto& level : ask_levels_) {
            if (remaining <= 0) break;
            if (level->price > buy_order->price && buy_order->type == OrderType::LIMIT) {
                break;  // Can't match at worse price
            }

            for (auto& order : level->orders) {
                if (remaining <= 0) break;
                if (order->is_cancelled) continue;

                uint64_t match_qty = std::min(remaining, order->quantity);
                matched.push_back(order);

                // Update quantities
                remaining -= match_qty;
                order->quantity -= match_qty;
                level->total_quantity -= match_qty;

                if (order->quantity == 0) {
                    // Order fully matched
                }
            }
        }

        return matched;
    }

    std::vector<Order*> matchSellOrder(Order* sell_order) {
        std::vector<Order*> matched;

        // Sort bids by price (descending) and time (FIFO within same price)
        auto compare = [](const std::unique_ptr<PriceLevel>& a,
                          const std::unique_ptr<PriceLevel>& b) {
            if (a->price != b->price) return a->price > b->price;
            return a->orders.front()->timestamp < b->orders.front()->timestamp;
        };
        std::sort(bid_levels_.begin(), bid_levels_.end(), compare);

        uint64_t remaining = sell_order->quantity;

        for (auto& level : bid_levels_) {
            if (remaining <= 0) break;
            if (level->price < sell_order->price && sell_order->type == OrderType::LIMIT) {
                break;  // Can't match at worse price
            }

            for (auto& order : level->orders) {
                if (remaining <= 0) break;
                if (order->is_cancelled) continue;

                uint64_t match_qty = std::min(remaining, order->quantity);
                matched.push_back(order);

                // Update quantities
                remaining -= match_qty;
                order->quantity -= match_qty;
                level->total_quantity -= match_qty;

                if (order->quantity == 0) {
                    // Order fully matched
                }
            }
        }

        return matched;
    }

    bool matchMarketOrder(Order* order) {
        if (order->side == OrderSide::BUY) {
            // Market buy takes all asks
            for (auto& level : ask_levels_) {
                for (auto& o : level->orders) {
                    if (o->is_cancelled) continue;
                    // Process match
                }
            }
        } else {
            // Market sell takes all bids
            for (auto& level : bid_levels_) {
                for (auto& o : level->orders) {
                    if (o->is_cancelled) continue;
                    // Process match
                }
            }
        }
        return true;
    }
};

