class OrderManagementSystem {
private:
    std::unordered_map<std::string, std::unique_ptr<OrderBook>> order_books_;
    std::mutex mutex_;

public:
    void addSymbol(const std::string& symbol) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (order_books_.find(symbol) == order_books_.end()) {
            order_books_[symbol] = std::make_unique<OrderBook>(symbol);
        }
    }

    bool submitOrder(Order* order) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = order_books_.find(order->symbol);
        if (it == order_books_.end()) {
            std::cerr << "Symbol not found: " << order->symbol << std::endl;
            return false;
        }

        // First try to match with existing orders
        auto matched = it->second->matchOrder(order);

        // If not fully matched, add to order book
        if (order->quantity > 0) {
            it->second->addOrder(order);
        }

        return true;
    }

    bool cancelOrder(const std::string& symbol, uint64_t order_id) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = order_books_.find(symbol);
        if (it == order_books_.end()) return false;

        // In a real system, we'd need to track orders by ID
        return it->second->cancelOrder(order_id);
    }
};

