class TradingServer {
private:
    tcp::acceptor acceptor_;
    OrderManagementSystem& oms_;
    std::atomic<bool> running_{true};

    void handleOrder(const std::string& request, tcp::socket& socket) {
        // Parse simple order format: "BUY|SELL SYMBOL PRICE QUANTITY"
        std::istringstream iss(request);
        std::string side_str, symbol;
        double price;
        uint64_t quantity;

        iss >> side_str >> symbol >> price >> quantity;

        OrderSide side = (side_str == "BUY") ? OrderSide::BUY : OrderSide::SELL;
        OrderType type = (price == 0.0) ? OrderType::MARKET : OrderType::LIMIT;

        static std::atomic<uint64_t> order_id{1};
        uint64_t id = order_id.fetch_add(1);

        Order order(id, symbol, side, type, price, quantity, 0);

        if (oms_.submitOrder(&order)) {
            std::string response = "Order accepted: " + std::to_string(id) + "\n";
            boost::asio::write(socket, boost::asio::buffer(response));
        } else {
            std::string response = "Order rejected\n";
            boost::asio::write(socket, boost::asio::buffer(response));
        }
    }

public:
    TradingServer(boost::asio::io_context& io_context, short port,
                 OrderManagementSystem& oms)
        : acceptor_(io_context, tcp::endpoint(tcp::v4(), port)), oms_(oms) {
        startAccept();
    }

    void stop() {
        running_ = false;
        acceptor_.close();
    }

private:
    void startAccept() {
        auto socket = std::make_shared<tcp::socket>(acceptor_.get_executor());

        acceptor_.async_accept(*socket, [this, socket](boost::system::error_code ec) {
            if (!ec) {
                std::thread([this, socket]() {
                    try {
                        boost::asio::streambuf buf;
                        boost::asio::read_until(*socket, buf, '\n');

                        std::istream is(&buf);
                        std::string request;
                        std::getline(is, request);

                        handleOrder(request, *socket);
                    } catch (std::exception& e) {
                        std::cerr << "Error handling order: " << e.what() << std::endl;
                    }
                    socket->close();
                }).detach();
            }
            if (running_) {
                startAccept();
            }
        });
    }
};

