};

// Thread-safe order book
class OrderBook {
private:
    std::string symbol;
    std::unordered_map<uint64_t, Order> orders;
    std::vector<OrderBookLevel> bids;
    std::vector<OrderBookLevel> asks;
    std::mutex book_mutex;
    std::atomic<uint64_t> next_order_id{1};

    // For price-time priority
    struct OrderTimeComparator {
        bool operator()(const Order& a, const Order& b) const {
            return a.timestamp > b.timestamp; // Earlier timestamp has higher priority
        }
    };

    std::priority_queue<Order, std::vector<Order>, OrderTimeComparator> bid_queue;
    std::priority_queue<Order, std::vector<Order>, OrderTimeComparator> ask_queue;

public:
    OrderBook(const std::string& sym) : symbol(sym) {}

    uint64_t add_order(const Order& order) {
        std::lock_guard<std::mutex> lock(book_mutex);

        if (order.side == OrderSide::BUY) {
            bids.emplace_back(order.price, order.quantity);
            bid_queue.push(order);
        } else {
            asks.emplace_back(order.price, order.quantity);
            ask_queue.push(order);
        }

        orders[order.order_id] = order;
        return order.order_id;
    }

    bool cancel_order(uint64_t order_id) {
        std::lock_guard<std::mutex> lock(book_mutex);
        auto it = orders.find(order_id);
        if (it != orders.end()) {
            it->second.is_cancelled = true;
            return true;
        }
        return false;
    }

    bool modify_order(uint64_t order_id, uint64_t new_quantity) {
        std::lock_guard<std::mutex> lock(book_mutex);
        auto it = orders.find(order_id);
        if (it != orders.end()) {
            it->second.quantity = new_quantity;
            return true;
        }
        return false;
    }

    void update_order_book(const std::vector<Order>& market_updates) {
        std::lock_guard<std::mutex> lock(book_mutex);

        for (const auto& update : market_updates) {
            if (update.side == OrderSide::BUY) {
                // Process bid updates
                auto it = std::find_if(bids.begin(), bids.end(),
                    [&update](const OrderBookLevel& level) { return level.price == update.price; });

                if (it != bids.end()) {
                    if (update.quantity == 0) {
                        bids.erase(it);
                    } else {
                        it->quantity = update.quantity;
                    }
                } else if (update.quantity > 0) {
                    bids.emplace_back(update.price, update.quantity);
                    // Maintain sorted order (descending for bids)
                    std::sort(bids.begin(), bids.end(),
                        [](const OrderBookLevel& a, const OrderBookLevel& b) {
                            return a.price > b.price;
                        });
                }
            } else {
                // Process ask updates
                auto it = std::find_if(asks.begin(), asks.end(),
                    [&update](const OrderBookLevel& level) { return level.price == update.price; });

                if (it != asks.end()) {
                    if (update.quantity == 0) {
                        asks.erase(it);
                    } else {
                        it->quantity = update.quantity;
                    }
                } else if (update.quantity > 0) {
                    asks.emplace_back(update.price, update.quantity);
                    // Maintain sorted order (ascending for asks)
                    std::sort(asks.begin(), asks.end(),
                        [](const OrderBookLevel& a, const OrderBookLevel& b) {
                            return a.price < b.price;
                        });
                }
            }
        }
    }

    // Get best bid/ask
    struct BestPrice {
        double bid;
        double ask;
        bool valid;
    };

    BestPrice get_best_price() const {
        std::lock_guard<std::mutex> lock(book_mutex);
        BestPrice result{0.0, 0.0, false};

        if (!bids.empty()) {
