            const Order& best_bid = bid_queue.top();
            const Order& best_ask = ask_queue.top();

            if (best_bid.price >= best_ask.price) {
                uint64_t match_qty = std::min(best_bid.quantity, best_ask.quantity);
                matched_quantity += match_qty;

                // Update quantities
