    void connect_to_exchange() {
        sockfd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockfd < 0) {
            Logger::log(Logger::ERROR, "Error creating socket");
            return;
        }

        struct sockaddr_in serv_addr;
        serv_addr.sin_family = AF_INET;
        serv_addr.sin_port = htons(port);

        if (inet_pton(AF_INET, host.c_str(), &serv_addr.sin_addr) <= 0) {
            Logger::log(Logger::ERROR, "Invalid address/ Address not supported");
            close(sockfd);
            return;
        }

        if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
            Logger::log(Logger::ERROR, "Connection Failed");
            close(sockfd);
            return;
        }

        connected = true;
        Logger::log(Logger::INFO, "Connected to market data feed");
    }

    void process_market_data() {
        char buffer[NETWORK_BUFFER_SIZE];
        std::string partial_message;

        while (connected) {
            ssize_t bytes_received = recv(sockfd, buffer, NETWORK_BUFFER_SIZE - 1, 0);
            if (bytes_received <= 0) {
                if (bytes_received == 0) {
                    Logger::log(Logger::WARNING, "Connection closed by server");
                } else {
                    Logger::log(Logger::ERROR, "Error receiving data");
                }
                break;
            }

            buffer[bytes_received] = '\0';
            partial_message += buffer;

            // Simple message parsing (in real system, use proper protocol)
            size_t pos = 0;
            while ((pos = partial_message.find('\n')) != std::string::npos) {
                std::string message = partial_message.substr(0, pos);
                partial_message.erase(0, pos + 1);

                // Parse market data update (simplified)
                // Format: SYMBOL,BID,BID_SIZE,ASK,ASK_SIZE
                size_t comma1 = message.find(',');
                size_t comma2 = message.find(',', comma1 + 1);
                size_t comma3 = message.find(',', comma2 + 1);

                if (comma1 != std::string::npos && comma2 != std::string::npos && comma3 != std::string::npos) {
                    std::string symbol = message.substr(0, comma1);
                    double bid = std::stod(message.substr(comma1 + 1, comma2 - comma1 - 1));
                    uint64_t bid_size = std::stoull(message.substr(comma2 + 1, comma3 - comma2 - 1));
                    double ask = std::stod(message.substr(comma3 + 1));

                    // Create order book update
                    std::vector<Order> updates;
                    updates.emplace_back(0, symbol, OrderSide::BUY, bid, bid_size, OrderType::LIMIT);
                    updates.emplace_back(0, symbol, OrderSide::SELL, ask, 0, OrderType::LIMIT); // Simplified

                    // Update order book
                    if (order_books.find(symbol) == order_books.end()) {
                        order_books[symbol] = std::make_unique<OrderBook>(symbol);
                    }

                    order_books[symbol]->update_order_book(updates);

                    // Notify strategies
                    for (auto& strategy : strategies) {
                        strategy->on_market_update(symbol, *order_books[symbol]);
                    }
                }
            }
        }

        connected = false;
    }

public:
    MarketDataFeed(const std::string& h, int p,
                  std::unordered_map<std::string, std::unique_ptr<OrderBook>>& books,
                  std::vector<std::unique_ptr<TradingStrategy>>& s)
        : host(h), port(p), order_books(books), strategies(s) {}

    ~MarketDataFeed() {
        if (connected) {
            connected = false;
            if (feed_thread.joinable()) {
                feed_thread.join();
            }
            close(sockfd);
        }
    }

    void start() {
        connect_to_exchange();
        if (connected) {
            feed_thread = std::thread([this]() { process_market_data(); });
        }
    }
};

// Thread pool for parallel processing
class ThreadPool {
private:
    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;
    std::mutex queue_mutex;
    std::condition_variable condition;
    std::atomic<bool> stop{false};

public:
    ThreadPool(size_t threads) {
        for (size_t i = 0; i < threads; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(queue_mutex);
                        condition.wait(lock, [this] { return stop || !tasks.empty(); });
                        if (stop && tasks.empty()) return;
                        task = std::move(tasks.front());
                        tasks.pop();
                    }
                    task();
                }
            });
        }
    }

    template<class F>
    void enqueue(F&& f) {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            if (stop) return;
            tasks.emplace(std::forward<F>(f));
        }
        condition.notify_one();
    }

    ~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread &worker : workers) {
            worker.join();
        }
    }
};

