        trade.timestamp = getCurrentTimestamp();

        if (order.side == OrderSide::Buy) {
            // Buy market order: match against best asks
            while (order.quantity > 0 && !order_book.getAsks().empty()) {
                auto [price, qty] = order_book.getAsks().begin()->second;
                uint64_t match_qty = std::min(order.quantity, qty);
                trade.price = price;
                trade.quantity = match_qty;
                trade.buy_order_id = order.order_id;
                // In a real system, we'd need to track the sell order ID
                order.quantity -= match_qty;
                order_book.reduceAsk(price, match_qty);
            }
        } else {
            // Sell market order: match against best bids
            while (order.quantity > 0 && !order_book.getBids().empty()) {
                auto [price, qty] = order_book.getBids().begin()->second;
                uint64_t match_qty = std::min(order.quantity, qty);
