#include <algorithm>
#include <boost/asio.hpp>

using boost::asio::ip::tcp;

// ====================== Data Structures ======================

struct Order {
    std::string order_id;
    std::string symbol;
    double price;
    int quantity;
    char side; // 'B' for buy, 'S' for sell
    std::string client_id;
    uint64_t timestamp;
    std::string order_type; // "MARKET", "LIMIT", etc.
};

struct Trade {
    std::string buy_order_id;
    std::string sell_order_id;
    std::string symbol;
    double price;
    int quantity;
    uint64_t timestamp;
};

// ====================== Core Components ======================

class OrderBook {
public:
    void add_order(const Order& order) {
        if (order.side == 'B') {
            bids_[order.price].push_back(order);
        } else if (order.side == 'S') {
            asks_[order.price].push_back(order);
        }
        orders_[order.order_id] = order;
    }

    void cancel_order(const std::string& order_id) {
        auto it = orders_.find(order_id);
        if (it != orders_.end()) {
            const Order& order = it->second;
            if (order.side == 'B') {
                auto price_it = bids_.find(order.price);
                if (price_it != bids_.end()) {
                    auto& price_level = price_it->second;
                    price_level.erase(std::remove_if(price_level.begin(), price_level.end(),
                        [&order_id](const Order& o) { return o.order_id == order_id; }), price_level.end());
                    if (price_level.empty()) {
                        bids_.erase(price_it);
                    }
                }
            } else if (order.side == 'S') {
                auto price_it = asks_.find(order.price);
                if (price_it != asks_.end()) {
                    auto& price_level = price_it->second;
                    price_level.erase(std::remove_if(price_level.begin(), price_level.end(),
                        [&order_id](const Order& o) { return o.order_id == order_id; }), price_level.end());
                    if (price_level.empty()) {
                        asks_.erase(price_it);
                    }
                }
            }
            orders_.erase(it);
        }
    }

    std::vector<Trade> match_order(const Order& incoming_order) {
        std::vector<Trade> trades;
        if (incoming_order.side == 'B') {
            // Match against asks (sell orders)
            while (incoming_order.quantity > 0 && !asks_.empty()) {
                auto best_ask_it = asks_.begin();
                if (best_ask_it == asks_.end()) break;

                auto& price_level = best_ask_it->second;
                if (price_level.empty()) {
                    asks_.erase(best_ask_it);
                    continue;
                }

                Order& ask = price_level.front();
                if (ask.price > incoming_order.price) break; // Price condition not met

                int match_qty = std::min(incoming_order.quantity, ask.quantity);
                trades.push_back({
                    incoming_order.order_id,
                    ask.order_id,
                    incoming_order.symbol,
                    ask.price,
                    match_qty,
                    get_current_timestamp()
                });

                incoming_order.quantity -= match_qty;
                ask.quantity -= match_qty;

                if (ask.quantity == 0) {
                    price_level.erase(price_level.begin());
                    if (price_level.empty()) {
                        asks_.erase(best_ask_it);
                    }
                }
            }
        } else if (incoming_order.side == 'S') {
            // Match against bids (buy orders)
            while (incoming_order.quantity > 0 && !bids_.empty()) {
                auto best_bid_it = bids_.begin();
                if (best_bid_it == bids_.end()) break;

                auto& price_level = best_bid_it->second;
                if (price_level.empty()) {
                    bids_.erase(best_bid_it);
                    continue;
                }

                Order& bid = price_level.front();
                if (bid.price < incoming_order.price) break; // Price condition not met

                int match_qty = std::min(incoming_order.quantity, bid.quantity);
                trades.push_back({
                    bid.order_id,
                    incoming_order.order_id,
                    incoming_order.symbol,
                    bid.price,
                    match_qty,
                    get_current_timestamp()
                });

                incoming_order.quantity -= match_qty;
                bid.quantity -= match_qty;

                if (bid.quantity == 0) {
                    price_level.erase(price_level.begin());
                    if (price_level.empty()) {
                        bids_.erase(best_bid_it);
                    }
                }
            }
        }

        // Add remaining quantity to order book if any
        if (incoming_order.quantity > 0) {
            add_order(incoming_order);
        }

        return trades;
    }

    double get_best_bid() const {
        return bids_.empty() ? 0.0 : bids_.begin()->first;
    }

    double get_best_ask() const {
        return asks_.empty() ? 0.0 : asks_.begin()->first;
    }

    size_t get_order_count() const {
        return orders_.size();
    }

private:
    uint64_t get_current_timestamp() {
        auto now = std::chrono::system_clock::now();
        return std::chrono::duration_cast<std::chrono::nanoseconds>(
            now.time_since_epoch()).count();
    }

    // Price levels (sorted by price)
    std::map<double, std::vector<Order>, std::greater<double>> bids_; // descending order
    std::map<double, std::vector<Order>> asks_; // ascending order

    // All active orders by ID
    std::unordered_map<std::string, Order> orders_;
};

