#include <unordered_map>
#include <queue>
#include <mutex>
#include <memory>
#include <thread>
#include <chrono>
#include <atomic>
#include <cassert>
#include <vector>
#include <algorithm>
#include <shared_mutex>

// ======================
// Core Data Structures
// ======================

enum class OrderSide { BUY, SELL };
enum class OrderType { MARKET, LIMIT };

struct Order {
    uint64_t order_id;
    std::string symbol;
    OrderSide side;
    OrderType type;
    double price;
    uint64_t quantity;
    uint64_t timestamp;
    std::string client_id;

    // For priority queue comparison
    bool operator<(const Order& other) const {
        if (price != other.price) return price < other.price;
        return timestamp > other.timestamp; // Earlier orders first for same price
    }
};

struct Trade {
    uint64_t trade_id;
    std::string symbol;
    uint64_t buy_order_id;
    uint64_t sell_order_id;
    double price;
    uint64_t quantity;
    uint64_t timestamp;
};

// ======================
// Order Book Implementation
// ======================

class OrderBook {
private:
    std::string symbol_;
    std::priority_queue<Order> bids_; // Max-heap for buy orders
    std::priority_queue<Order> asks_; // Min-heap for sell orders (using operator<)
    std::shared_mutex mutex_;

public:
    explicit OrderBook(const std::string& symbol) : symbol_(symbol) {}

    const std::string& getSymbol() const { return symbol_; }

    void addOrder(const Order& order) {
        std::unique_lock lock(mutex_);
        if (order.side == OrderSide::BUY) {
            bids_.push(order);
        } else {
            asks_.push(order);
        }
    }

    bool matchOrder(Order& incoming_order, Trade& trade) {
        std::unique_lock lock(mutex_);

        if (incoming_order.side == OrderSide::BUY) {
            return matchBuyOrder(incoming_order, trade);
        } else {
            return matchSellOrder(incoming_order, trade);
        }
    }

    void cancelOrder(uint64_t order_id) {
        std::unique_lock lock(mutex_);
        // In a real system, we'd maintain order lookup structures
        // For simplicity, we'll just clear the book (not realistic)
        while (!bids_.empty()) bids_.pop();
        while (!asks_.empty()) asks_.pop();
    }

private:
    bool matchBuyOrder(Order& buy_order, Trade& trade) {
        while (!asks_.empty() && buy_order.quantity > 0) {
            Order ask = asks_.top();
            asks_.pop();

            if (buy_order.price >= ask.price) {
                uint64_t matched_qty = std::min(buy_order.quantity, ask.quantity);

                trade.trade_id = generateTradeId();
                trade.symbol = symbol_;
                trade.buy_order_id = buy_order.order_id;
                trade.sell_order_id = ask.order_id;
                trade.price = ask.price; // Trade at ask price
                trade.quantity = matched_qty;
                trade.timestamp = getCurrentTimestamp();

                buy_order.quantity -= matched_qty;
                // In a real system, we'd update the ask order's remaining quantity
                // For simplicity, we're just removing it

                if (ask.quantity > matched_qty) {
                    // Partial fill - put back remaining quantity
                    Order remaining_ask = ask;
                    remaining_ask.quantity -= matched_qty;
                    asks_.push(remaining_ask);
                }

                return true;
            } else {
                // Price doesn't match - put back in book
                asks_.push(ask);
                break;
            }
        }
        return false;
    }

    bool matchSellOrder(Order& sell_order, Trade& trade) {
        while (!bids_.empty() && sell_order.quantity > 0) {
            Order bid = bids_.top();
            bids_.pop();

            if (sell_order.price <= bid.price) {
                uint64_t matched_qty = std::min(sell_order.quantity, bid.quantity);

                trade.trade_id = generateTradeId();
                trade.symbol = symbol_;
                trade.buy_order_id = bid.order_id;
                trade.sell_order_id = sell_order.order_id;
                trade.price = bid.price; // Trade at bid price
                trade.quantity = matched_qty;
                trade.timestamp = getCurrentTimestamp();

                sell_order.quantity -= matched_qty;
                // In a real system, we'd update the bid order's remaining quantity

                if (bid.quantity > matched_qty) {
                    Order remaining_bid = bid;
                    remaining_bid.quantity -= matched_qty;
                    bids_.push(remaining_bid);
                }

                return true;
            } else {
                bids_.push(bid);
                break;
            }
        }
        return false;
    }

    uint64_t generateTradeId() {
        static std::atomic<uint64_t> trade_counter{0};
        return trade_counter.fetch_add(1, std::memory_order_relaxed);
    }

    uint64_t getCurrentTimestamp() {
        return std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
    }
};

// ======================
// Matching Engine
// ======================

class MatchingEngine {
private:
    std::unordered_map<std::string, std::unique_ptr<OrderBook>> order_books_;
    std::shared_mutex books_mutex_;

public:
    void addOrder(const Order& order) {
        std::shared_lock lock(books_mutex_);
        auto& book = order_books_[order.symbol];
        if (!book) {
            book = std::make_unique<OrderBook>(order.symbol);
        }
        lock.unlock();

        Trade trade;
        if (book->matchOrder(const_cast<Order&>(order), trade)) {
            // Trade occurred - in a real system we'd publish this to market data feed
            std::cout << "Trade executed: " << trade.quantity << " @ " << trade.price
                      << " (Symbol: " << trade.symbol << ")\n";
        }

        if (order.quantity > 0) {
            // No match - add to order book
            book->addOrder(order);
        }
    }

    void cancelOrder(const std::string& symbol, uint64_t order_id) {
        std::shared_lock lock(books_mutex_);
        auto it = order_books_.find(symbol);
        if (it != order_books_.end()) {
            it->second->cancelOrder(order_id);
        }
    }

    // For future scaling: This could be sharded by symbol
    void processOrders() {
        // In a real system, this would be driven by incoming orders
        // For demo, we'll just process a test order
        Order test_order{
            .order_id = 1,
            .symbol = "AAPL",
            .side = OrderSide::BUY,
            .type = OrderType::LIMIT,
            .price = 150.0,
            .quantity = 100,
            .timestamp = getCurrentTimestamp(),
            .client_id = "CLIENT1"
        };

        addOrder(test_order);
    }

private:
    uint64_t getCurrentTimestamp() {
        return std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
    }
};

// ======================
// Risk Management
// ======================

class RiskManager {
public:
    bool checkOrder(const Order& order) {
        // Basic risk checks
        if (order.quantity == 0) {
            std::cerr << "Risk check failed: Zero quantity order\n";
            return false;
        }

        if (order.price <= 0) {
            std::cerr << "Risk check failed: Invalid price\n";
            return false;
        }

        // In a real system, we'd check against client limits, position limits, etc.
        return true;
    }
};

// ======================
// Order Management System
// ======================

class OrderManager {
private:
    MatchingEngine& matching_engine_;
    RiskManager& risk_manager_;
    std::queue<Order> order_queue_;
    std::mutex queue_mutex_;
    std::condition_variable cv_;
    bool running_ = true;

public:
    OrderManager(MatchingEngine& engine, RiskManager& risk_manager)
        : matching_engine_(engine), risk_manager_(risk_manager) {}

    void submitOrder(const Order& order) {
        {
            std::lock_guard lock(queue_mutex_);
            order_queue_.push(order);
        }
        cv_.notify_one();
    }

    void start() {
        std::thread([this]() {
            while (running_) {
                std::unique_lock lock(queue_mutex_);
                cv_.wait(lock, [this]() { return !order_queue_.empty() || !running_; });

                if (!running_) break;

                Order order = order_queue_.front();
                order_queue_.pop();
                lock.unlock();

                if (risk_manager_.checkOrder(order)) {
                    matching_engine_.addOrder(order);
                }
            }
        }).detach();
    }

    void stop() {
        running_ = false;
        cv_.notify_all();
    }
};

