Below is a foundational implementation of a low-latency trading platform in C++ (the top-ranked language for this use case). This implementation focuses on core components while being designed for future scalability and performance optimization.

```cpp
#include <iostream>
#include <memory>
#include <map>
#include <queue>
#include <vector>
#include <mutex>
#include <atomic>
#include <boost/asio.hpp>
#include <boost/lockfree/queue.hpp>

// ======================
// Core Data Structures
// ======================

enum class OrderSide { BUY, SELL };

struct Order {
    uint64_t order_id;
    uint64_t client_id;
    uint64_t quantity;
    uint64_t price; // Price in smallest units (e.g., cents for USD)
    OrderSide side;
    uint64_t timestamp;
};

struct Trade {
    uint64_t price;
    uint64_t quantity;
    uint64_t buy_order_id;
    uint64_t sell_order_id;
};

// ======================
// Order Book Implementation
// ======================

class OrderBook {
private:
    // Price level: key is price, value is a queue of orders at that price
    std::map<uint64_t, std::queue<std::shared_ptr<Order>>, std::greater<uint64_t>> bids;
    std::map<uint64_t, std::queue<std::shared_ptr<Order>>, std::less<uint64_t>> asks;
    std::mutex book_mutex;

public:
    void addOrder(std::shared_ptr<Order> order) {
        std::lock_guard<std::mutex> lock(book_mutex);
        if (order->side == OrderSide::BUY) {
            bids[order->price].push(order);
        } else {
            asks[order->price].push(order);
        }
    }

    std::vector<std::shared_ptr<Trade>> matchOrder(std::shared_ptr<Order> incomingOrder) {
        std::vector<std::shared_ptr<Trade>> trades;
        std::lock_guard<std::mutex> lock(book_mutex);

        if (incomingOrder->side == OrderSide::BUY) {
            // Match against asks (sorted ascending - best ask is first)
            while (incomingOrder->quantity > 0 && !asks.empty()) {
                auto& [price, orders] = *asks.begin();
                if (price > incomingOrder->price) break; // No more matches possible

                auto& order = orders.front();
                uint64_t matchQuantity = std::min(incomingOrder->quantity, order->quantity);

                // Create trade
                auto trade = std::make_shared<Trade>();
                trade->price = price;
                trade->quantity = matchQuantity;
                trade->buy_order_id = incomingOrder->order_id;
                trade->sell_order_id = order->order_id;
                trades.push_back(trade);

                // Update quantities
                incomingOrder->quantity -= matchQuantity;
                order->quantity -= matchQuantity;

                // Remove if fully filled
                if (order->quantity == 0) {
                    orders.pop();
                    if (orders.empty()) asks.erase(price);
                }
            }

            // Add remaining quantity to book if any
            if (incomingOrder->quantity > 0) {
                incomingOrder->side = OrderSide::BUY;
                addOrder(incomingOrder);
            }
        } else {
            // Match against bids (sorted descending - best bid is first)
            while (incomingOrder->quantity > 0 && !bids.empty()) {
                auto& [price, orders] = *bids.begin();
                if (price < incomingOrder->price) break; // No more matches possible

                auto& order = orders.front();
                uint64_t matchQuantity = std::min(incomingOrder->quantity, order->quantity);

                // Create trade
                auto trade = std::make_shared<Trade>();
                trade->price = price;
                trade->quantity = matchQuantity;
                trade->buy_order_id = order->order_id;
                trade->sell_order_id = incomingOrder->order_id;
                trades.push_back(trade);

                // Update quantities
                incomingOrder->quantity -= matchQuantity;
                order->quantity -= matchQuantity;

                // Remove if fully filled
                if (order->quantity == 0) {
                    orders.pop();
                    if (orders.empty()) bids.erase(price);
                }
            }

            // Add remaining quantity to book if any
            if (incomingOrder->quantity > 0) {
                incomingOrder->side = OrderSide::SELL;
                addOrder(incomingOrder);
            }
        }
        return trades;
    }

    // For demonstration: print current order book state
    void printBook() {
        std::lock_guard<std::mutex> lock(book_mutex);
        std::cout << "\n=== ORDER BOOK ===\n";
        std::cout << "BIDS:\n";
        for (const auto& [price, orders] : bids) {
            std::cout << "  $" << price/100.0 << ": " << orders.front()->quantity << "\n";
        }
        std::cout << "ASKS:\n";
        for (const auto& [price, orders] : asks) {
            std::cout << "  $" << price/100.0 << ": " << orders.front()->quantity << "\n";
        }
        std::cout << "==================\n";
    }
};

