                    MarketDataFeedHandler& handler)
        : acceptor_(io_context, boost::asio::ip::tcp::endpoint(boost::asio::ip::tcp::v4(), port)),
          handler_(handler) {
        start_accept();
    }

private:
    void start_accept() {
        auto socket = std::make_shared<boost::asio::ip::tcp::socket>(acceptor_.get_executor());
        acceptor_.async_accept(*socket, [this, socket](boost::system::error_code ec) {
            if (!ec) {
                std::cout << "New connection from " << socket->remote_endpoint() << std::endl;
                start_read(socket);
            }
            start_accept();
        });
    }

    void start_read(std::shared_ptr<boost::asio::ip::tcp::socket> socket) {
        auto buffer = std::make_shared<boost::asio::streambuf>();
        boost::asio::async_read_until(*socket, *buffer, '\n',
            [this, socket, buffer](boost::system::error_code ec, std::size_t bytes_transferred) {
                if (!ec) {
                    std::istream is(buffer.get());
                    std::string message;
                    std::getline(is, message);
                    handler_.handleMarketData(message);
                    start_read(socket);
                }
            });
    }

    boost::asio::ip::tcp::acceptor acceptor_;
    MarketDataFeedHandler& handler_;
};

