#pragma once

#include <memory>
#include <deque>
#include "core/market_data.h"
#include "core/signal.h"
#include "utils/lock_free_queue.h"

class StrategyEngine {
public:
    explicit StrategyEngine(std::shared_ptr<LockFreeQueue<Signal>> signal_queue)
        : signal_queue_(signal_queue) {}

    void onMarketData(const MarketData& market_data) {
        if (market_data.type == MarketData::Type::ORDER_BOOK_UPDATE) {
            processOrderBook(market_data.data.order_book);
        }
    }

private:
    void processOrderBook(const OrderBook& order_book) {
        // Simple moving average crossover strategy
        static std::deque<uint64_t> bid_prices;
        static std::deque<uint64_t> ask_prices;
        const size_t window_size = 5; // Simple moving average window

        // Add current best bid/ask to the window
        if (!order_book.bids.empty()) {
            bid_prices.push_back(order_book.bids[0].price);
            if (bid_prices.size() > window_size) bid_prices.pop_front();
        }

        if (!order_book.asks.empty()) {
            ask_prices.push_back(order_book.asks[0].price);
            if (ask_prices.size() > window_size) ask_prices.pop_front();
        }

        // Generate signal if we have enough data
        if (bid_prices.size() == window_size && ask_prices.size() == window_size) {
            uint64_t bid_ma = 0, ask_ma = 0;
            for (auto p : bid_prices) bid_ma += p;
            for (auto p : ask_prices) ask_ma += p;
            bid_ma /= window_size;
            ask_ma /= window_size;

            // Simple strategy: buy if bid MA > ask MA, sell otherwise
            Signal signal;
            signal.symbol = order_book.symbol;
            signal.quantity = 100; // Fixed quantity
            signal.timestamp = std::chrono::duration_cast<std::chrono::nanoseconds>(
                std::chrono::system_clock::now().time_since_epoch());

            if (bid_ma > ask_ma) {
                signal.type = SignalType::BUY;
                signal.price = order_book.asks.empty() ? 0 : order_book.asks[0].price;
            } else {
                signal.type = SignalType::SELL;
                signal.price = order_book.bids.empty() ? 0 : order_book.bids[0].price;
            }

            if (!signal_queue_->push(signal)) {
                Logger::log(Logger::Level::ERROR, "Failed to push signal to queue");
            }
        }
    }

    std::shared_ptr<LockFreeQueue<Signal>> signal_queue_;
};
