    ) : order_queue(order_q), risk_check_queue(risk_q) {}

    void process() {
        OrderEvent order;
        while (order_queue.try_pop(order)) {
            RiskCheckEvent risk_event;
            risk_event.order = order;

            // Simple risk check: Limit position size
            if (current_position + order.quantity > max_position) {
                risk_event.is_valid = false;
                std::cerr << "[RISK] Rejected order " << order.order_id
                          << " - Position limit exceeded" << std::endl;
            } else {
                risk_event.is_valid = true;
                current_position += order.quantity;
                std::cout << "[RISK] Approved order " << order.order_id
                          << " | Position: " << current_position << std::endl;
            }

            risk_check_queue.push(risk_event);
