    void cancel_order(const std::string& order_id) {
        auto it = orders_.find(order_id);
        if (it != orders_.end()) {
            const Order& order = it->second;
            if (order.side == 'B') {
                auto& price_level = bids_[order.price];
                price_level.erase(std::remove_if(price_level.begin(), price_level.end(),
                    [&order_id](const Order& o) { return o.order_id == order_id; }), price_level.end());
                if (price_level.empty()) {
