        if (order.side == 'B') {
            // Match against asks
            while (order.quantity > 0 && !asks_.empty()) {
                auto& best_ask = asks_.begin()->second;
                if (best_ask.empty()) {
                    asks_.erase(asks_.begin());
                    continue;
                }
                Order& ask = best_ask.front();
                if (ask.price > order.price) {
                    break; // No more matches
                }
                int match_qty = std::min(order.quantity, ask.quantity);
                trades.push_back({order.order_id, ask.order_id, order.symbol, ask.price, match_qty});
                order.quantity -= match_qty;
                ask.quantity -= match_qty;
                if (ask.quantity == 0) {
                    best_ask.erase(best_ask.begin());
                    if (best_ask.empty()) {
                        asks_.erase(asks_.begin());
                    }
                }
            }
        } else if (order.side == 'S') {
            // Match against bids
            while (order.quantity > 0 && !bids_.empty()) {
                auto& best_bid = bids_.begin()->second;
                if (best_bid.empty()) {
                    bids_.erase(bids_.begin());
                    continue;
                }
                Order& bid = best_bid.front();
                if (bid.price < order.price) {
                    break; // No more matches
                }
                int match_qty = std::min(order.quantity, bid.quantity);
                trades.push_back({bid.order_id, order.order_id, order.symbol, bid.price, match_qty});
                order.quantity -= match_qty;
                bid.quantity -= match_qty;
                if (bid.quantity == 0) {
                    best_bid.erase(best_bid.begin());
                    if (best_bid.empty()) {
                        bids_.erase(bids_.begin());
                    }
                }
            }
        }
        if (order.quantity > 0) {
            add_order(order); // Add remaining quantity to order book
        }
        return trades;
    }

