private:
    // Price level: key is price, value is a queue of orders at that price
    std::map<uint64_t, std::queue<std::shared_ptr<Order>>, std::greater<uint64_t>> bids; // descending for bids
    std::map<uint64_t, std::queue<std::shared_ptr<Order>>, std::less<uint64_t>> asks;    // ascending for asks

public:
    // Add an order to the book
    void addOrder(std::shared_ptr<Order> order) {
        if (order->side == OrderSide::BUY) {
            bids[order->price].push(order);
        } else {
            asks[order->price].push(order);
        }
    }

    // Match an incoming order against the book
    std::vector<std::shared_ptr<Trade>> matchOrder(std::shared_ptr<Order> incomingOrder) {
        std::vector<std::shared_ptr<Trade>> trades;
        if (incomingOrder->side == OrderSide::BUY) {
            // Match against asks
            while (incomingOrder->quantity > 0 && !asks.empty()) {
                auto& [price, orders] = *asks.begin();
                if (price > incomingOrder->price) {
                    break; // No more matches possible
                }

                auto& order = orders.front();
                uint64_t matchQuantity = std::min(incomingOrder->quantity, order->quantity);

                // Create a trade
                auto trade = std::make_shared<Trade>();
                trade->price = price;
                trade->quantity = matchQuantity;
                trade->buy_order_id = incomingOrder->order_id;
                trade->sell_order_id = order->order_id;
                trades.push_back(trade);

                // Update quantities
                incomingOrder->quantity -= matchQuantity;
                order->quantity -= matchQuantity;

                // Remove order if fully filled
                if (order->quantity == 0) {
                    orders.pop();
                    if (orders.empty()) {
                        asks.erase(price);
                    }
                }
            }

            // If there's remaining quantity, add to bids
            if (incomingOrder->quantity > 0) {
                incomingOrder->side = OrderSide::BUY;
                addOrder(incomingOrder);
            }
        } else {
            // Match against bids (similar logic for sell orders)
            while (incomingOrder->quantity > 0 && !bids.empty()) {
                auto& [price, orders] = *bids.begin();
                if (price < incomingOrder->price) {
                    break; // No more matches possible
                }

                auto& order = orders.front();
                uint64_t matchQuantity = std::min(incomingOrder->quantity, order->quantity);

                // Create a trade
                auto trade = std::make_shared<Trade>();
                trade->price = price;
                trade->quantity = matchQuantity;
                trade->buy_order_id = order->order_id;
                trade->sell_order_id = incomingOrder->order_id;
                trades.push_back(trade);

                // Update quantities
                incomingOrder->quantity -= matchQuantity;
                order->quantity -= matchQuantity;

                // Remove order if fully filled
                if (order->quantity == 0) {
                    orders.pop();
                    if (orders.empty()) {
                        bids.erase(price);
                    }
                }
            }

            // If there's remaining quantity, add to asks
            if (incomingOrder->quantity > 0) {
                incomingOrder->side = OrderSide::SELL;
                addOrder(incomingOrder);
            }
        }
        return trades;
    }
};
```

Wait, there's a bug in the above code. When matching a buy order, we should match against asks (which are sorted in ascending order), and for a sell order, match against bids (sorted in descending order). But in the code above, for a buy order, we're checking if `price > incomingOrder->price`, which is correct because asks are sorted ascending, so the best ask is the smallest price. But in the loop, we're iterating from the beginning of the asks map, which is the smallest price (best ask). Similarly, for bids, the best bid is the highest price, so we iterate from the beginning of the bids map (which is sorted descending).

But in the code for matching a buy order, the condition `if (price > incomingOrder->price)` is correct because we want to stop matching if the ask price is higher than the incoming buy order's price (since buy orders want to match with the cheapest asks first).

Similarly, for matching a sell order, we iterate through bids (sorted descending), and stop when the bid price is lower than the incoming sell order's price (since sell orders want to match with the highest bids first).

So the logic seems correct.

