```cpp
template <typename T>
class LockFreeQueue {
private:
    struct Node {
        T data;
        std::atomic<Node*> next;
        Node() : next(nullptr) {}
    };

    alignas(64) std::atomic<Node*> head;
    alignas(64) std::atomic<Node*> tail;

public:
    LockFreeQueue() {
        Node* dummy = new Node();
        head.store(dummy, std::memory_order_relaxed);
        tail.store(dummy, std::memory_order_relaxed);
    }

    ~LockFreeQueue() {
        T data;
        while (try_pop(data)) {}
        Node* node = head.load(std::memory_order_relaxed);
        delete node;
    }

    void push(const T& value) {
        Node* node = new Node();
        node->data = value;
        node->next.store(nullptr, std::memory_order_relaxed);

        Node* old_tail = tail.load(std::memory_order_acquire);
        Node* next;
        do {
            next = old_tail->next.load(std::memory_order_acquire);
            if (next == nullptr) {
                if (tail.compare_exchange_weak(old_tail, node, std::memory_order_release)) {
                    break;
                }
            } else {
                tail.compare_exchange_weak(old_tail, next, std::memory_order_release);
            }
        } while (true);

        old_tail->next.store(node, std::memory_order_release);
    }

    bool try_pop(T& value) {
        Node* old_head = head.load(std::memory_order_acquire);
        Node* next = old_head->next.load(std::memory_order_acquire);
        if (next == nullptr) {
            return false;
        }

        if (head.compare_exchange_weak(old_head, next, std::memory_order_release)) {
            value = std::move(next->data);
            delete old_head;
            return true;
        }
        return false;
    }
};
```

