MarketDataFeed::MarketDataFeed(const std::string& endpoint)
    : context_(1), publisher_(context_, ZMQ_PUB) {
    publisher_.bind(endpoint);
    running_ = true;
}

MarketDataFeed::~MarketDataFeed() {
    stop();
}

void MarketDataFeed::start() {
    feed_thread_ = std::thread(&MarketDataFeed::simulateMarketData, this);
    feed_thread_.detach();
}

void MarketDataFeed::stop() {
    running_ = false;
    if (feed_thread_.joinable()) {
        feed_thread_.join();
    }
}

void MarketDataFeed::simulateMarketData() {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<> price_dist(100.0, 200.0);
    std::uniform_int_distribution<> qty_dist(1, 1000);
    std::vector<std::string> symbols = {"AAPL", "MSFT", "GOOGL", "AMZN", "TSLA"};

    while (running_) {
        auto symbol = symbols[gen() % symbols.size()];
        auto price = price_dist(gen);
        auto quantity = qty_dist(gen);

        // Serialize market data
        zmq::message_t message(sizeof(double) + sizeof(uint64_t) + symbol.size() + 1);
        char* data = static_cast<char*>(message.data());
        memcpy(data, symbol.c_str(), symbol.size() + 1);
        memcpy(data + symbol.size() + 1, &price, sizeof(price));
        memcpy(data + symbol.size() + 1 + sizeof(price), &quantity, sizeof(quantity));

        publisher_.send(message);
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }
}
