#include "order_book.h"
#include <iostream>
#include <iomanip>
#include <sstream>

void OrderBook::add_order(const Order& order) {
    std::lock_guard<std::mutex> lock(mutex_);

    if (order.is_market_order()) {
        // For market orders, we'll match immediately against best available
        match_order(order);
        return;
    }

    // Add to order book
    auto order_id = order.order_id;
    orders_[order_id] = {order, {}};
    symbol_orders_[order.symbol].push_back(order_id);
    price_levels_[std::to_string(order.price)].push_back(order_id);

    // Update market data
    auto& md = market_data_[order.symbol];
    if (order.side == OrderSide::BUY) {
        if (order.price > md.bid_price || md.bid_price == 0) {
            md.bid_price = order.price;
            md.bid_size += order.quantity;
        } else {
            md.bid_size += order.quantity;
        }
    } else {
        if (order.price < md.ask_price || md.ask_price == 0) {
            md.ask_price = order.price;
            md.ask_size += order.quantity;
        } else {
            md.ask_size += order.quantity;
        }
    }

    std::cout << "Added order: " << order_id << " " << order.symbol << " "
              << (order.side == OrderSide::BUY ? "BUY" : "SELL")
              << " " << (order.is_market_order() ? "MARKET" : "LIMIT")
              << " " << order.price << " " << order.quantity << std::endl;
}

void OrderBook::cancel_order(const std::string& order_id) {
    std::lock_guard<std::mutex> lock(mutex_);
    remove_order(order_id);
    std::cout << "Cancelled order: " << order_id << std::endl;
}

void OrderBook::modify_order(const std::string& order_id, int64_t new_quantity) {
    std::lock_guard<std::mutex> lock(mutex_);
    auto it = orders_.find(order_id);
    if (it != orders_.end()) {
        it->second.order.quantity = new_quantity;
        std::cout << "Modified order: " << order_id << " new quantity: " << new_quantity << std::endl;
    }
}

void OrderBook::match_order(const Order& incoming_order) {
    auto& symbol = incoming_order.symbol;
    auto& md = market_data_[symbol];

    if (incoming_order.side == OrderSide::BUY) {
        // Buy order matches against asks
        while (incoming_order.quantity > 0 && md.ask_size > 0) {
            auto best_ask = md.ask_price;
            auto match_quantity = std::min(incoming_order.quantity, md.ask_size);

            std::cout << "Match: " << incoming_order.order_id << " buys "
                      << match_quantity << " @ " << best_ask << " from "
                      << md.ask_size << " available" << std::endl;

            incoming_order.quantity -= match_quantity;
            md.ask_size -= match_quantity;

            if (md.ask_size == 0) {
                // Remove all orders at this price level
                price_levels_.erase(std::to_string(best_ask));
                md.ask_price = 0;
            }
        }
    } else {
        // Sell order matches against bids
        while (incoming_order.quantity > 0 && md.bid_size > 0) {
            auto best_bid = md.bid_price;
            auto match_quantity = std::min(incoming_order.quantity, md.bid_size);

            std::cout << "Match: " << incoming_order.order_id << " sells "
                      << match_quantity << " @ " << best_bid << " from "
                      << md.bid_size << " available" << std::endl;

            incoming_order.quantity -= match_quantity;
            md.bid_size -= match_quantity;

            if (md.bid_size == 0) {
                // Remove all orders at this price level
                price_levels_.erase(std::to_string(best_bid));
                md.bid_price = 0;
            }
        }
    }

    // If any quantity remains, add to order book
    if (incoming_order.quantity > 0) {
        add_to_order_book(incoming_order);
    }
}

void OrderBook::add_to_order_book(const Order& order) {
    auto order_id = order.order_id;
    orders_[order_id] = {order, {}};
    symbol_orders_[order.symbol].push_back(order_id);
    price_levels_[std::to_string(order.price)].push_back(order_id);

    // Update market data
    auto& md = market_data_[order.symbol];
    if (order.side == OrderSide::BUY) {
        if (order.price > md.bid_price || md.bid_price == 0) {
            md.bid_price = order.price;
            md.bid_size += order.quantity;
        } else {
            md.bid_size += order.quantity;
        }
    } else {
        if (order.price < md.ask_price || md.ask_price == 0) {
            md.ask_price = order.price;
            md.ask_size += order.quantity;
        } else {
            md.ask_size += order.quantity;
        }
    }
}

void OrderBook::remove_order(const std::string& order_id) {
    auto it = orders_.find(order_id);
    if (it != orders_.end()) {
        auto& order = it->second.order;
        symbol_orders_[order.symbol].remove(order_id);
        price_levels_[std::to_string(order.price)].remove(order_id);

        // Update market data
        auto& md = market_data_[order.symbol];
        if (order.side == OrderSide::BUY) {
            md.bid_size -= order.quantity;
            if (md.bid_size <= 0) {
                md.bid_price = 0;
                md.bid_size = 0;
            }
        } else {
            md.ask_size -= order.quantity;
            if (md.ask_size <= 0) {
                md.ask_price = 0;
                md.ask_size = 0;
            }
        }

        orders_.erase(it);
    }
}

MarketData OrderBook::get_market_data(const std::string& symbol) const {
    std::lock_guard<std::mutex> lock(mutex_);
    auto it = market_data_.find(symbol);
    if (it != market_data_.end()) {
        return it->second;
    }
    return {};
}

void OrderBook::print() const {
    std::lock_guard<std::mutex> lock(mutex_);
    std::cout << "\n=== Order Book ===" << std::endl;
    for (const auto& [symbol, orders] : symbol_orders_) {
        std::cout << "\nSymbol: " << symbol << std::endl;
        std::cout << "Bid: " << market_data_.at(symbol).bid_price
                  << " (" << market_data_.at(symbol).bid_size << ")"
                  << " | Ask: " << market_data_.at(symbol).ask_price
                  << " (" << market_data_.at(symbol).ask_size << ")" << std::endl;

        // Print bids (sorted descending)
        std::cout << "\nBids:" << std::endl;
        std::map<double, std::vector<std::string>, std::greater<double>> bids;
        for (const auto& order_id : orders) {
            const auto& order = orders_.at(order_id).order;
            if (order.side == OrderSide::BUY) {
                bids[order.price].push_back(order_id);
            }
        }
        for (const auto& [price, order_ids] : bids) {
            for (const auto& order_id : order_ids) {
                const auto& order = orders_.at(order_id).order;
                std::cout << "  BUY  " << std::setw(10) << order.price
                          << " @ " << std::setw(5) << order.quantity
                          << " [ID: " << order_id << "]" << std::endl;
            }
        }

        // Print asks (sorted ascending)
        std::cout << "\nAsks:" << std::endl;
        std::map<double, std::vector<std::string>> asks;
        for (const auto& order_id : orders) {
            const auto& order = orders_.at(order_id).order;
            if (order.side == OrderSide::SELL) {
                asks[order.price].push_back(order_id);
            }
        }
        for (const auto& [price, order_ids] : asks) {
            for (const auto& order_id : order_ids) {
                const auto& order = orders_.at(order_id).order;
                std::cout << "  SELL " << std::setw(10) << order.price
                          << " @ " << std::setw(5) << order.quantity
                          << " [ID: " << order_id << "]" << std::endl;
            }
        }
    }
    std::cout << "==================\n" << std::endl;
}
