    market_data_[symbol] = {
        symbol,
        150.0 + (generator_() % 100),  // Initial bid
        100 + (generator_() % 500),     // Initial bid size
        150.1 + (generator_() % 100),  // Initial ask
        100 + (generator_() % 500),     // Initial ask size
        150.05 + (generator_() % 100), // Last trade price
        200 + (generator_() % 800),     // Last trade size
        std::chrono::system_clock::now()
    };
}

MarketData MarketDataSimulator::get_market_data(const std::string& symbol) const {
    auto it = market_data_.find(symbol);
    if (it != market_data_.end()) {
        return it->second;
    }
    return {};
}

void MarketDataSimulator::update_market_data(const std::string& symbol, double price_change) {
    auto it = market_data_.find(symbol);
    if (it != market_data_.end()) {
        auto& md = it->second;

        // Randomly decide direction
        if (generator_() % 2 == 0) {
            md.bid_price += price_change;
            md.ask_price += price_change;
        } else {
            md.bid_price -= price_change;
            md.ask_price -= price_change;
        }

        // Ensure bid < ask
        if (md.bid_price >= md.ask_price) {
            md.ask_price = md.bid_price + 0.1;
        }

        // Update last trade price to mid
        md.last_trade_price = (md.bid_price + md.ask_price) / 2;
        md.last_trade_size = size_dist_(generator_);
        md.timestamp = std::chrono::system_clock::now();

        std::cout << "Market update: " << symbol
                  << " Bid=" << md.bid_price << "(" << md.bid_size << ")"
                  << " Ask=" << md.ask_price << "(" << md.ask_size << ")"
                  << " Last=" << md.last_trade_price << "(" << md.last_trade_size << ")"
                  << std::endl;
    }
}
