std::string OrderManagementSystem::process_order(const Order& order) {
    if (!validate_order(order)) {
        return "";
    }

    std::ostringstream oss;
    oss << "order_" << std::setw(6) << std::setfill('0') << (rand() % 1000000);
    auto order_id = oss.str();

    Order processed_order = order;
    processed_order.order_id = order_id;
    processed_order.timestamp = std::chrono::system_clock::now();

    order_book_->add_order(processed_order);
    return order_id;
}

bool OrderManagementSystem::cancel_order(const std::string& order_id) {
    return order_book_->cancel_order(order_id);
}

bool OrderManagementSystem::modify_order(const std::string& order_id, int64_t new_quantity) {
    if (new_quantity <= 0) {
        std::cerr << "Error: Order quantity must be positive" << std::endl;
        return false;
    }
    order_book_->modify_order(order_id, new_quantity);
    return true;
}

bool OrderManagementSystem::validate_order(const Order& order) const {
    if (order.quantity <= 0) {
        std::cerr << "Order rejected: invalid quantity (" << order.quantity << ") for order" << std::endl;
        return false;
    }

    if (order.symbol.empty()) {
        std::cerr << "Order rejected: empty symbol" << std::endl;
        return false;
    }

    auto md = market_data_sim_->get_market_data(order.symbol);
    if (md.bid_price == 0 && md.ask_price == 0) {
        std::cerr << "Order rejected: unknown symbol " << order.symbol << std::endl;
        return false;
    }

    if (order.type == OrderType::LIMIT && order.price <= 0) {
        std::cerr << "Order rejected: invalid price (" << order.price << ") for limit order" << std::endl;
        return false;
    }

    return true;
}

void OrderManagementSystem::print_order_book() const {
    order_book_->print();
}
