private:
    struct CompareOrders {
        bool operator()(const Order& a, const Order& b) const {
            if (a.side == OrderSide::BUY) {
                return a.price < b.price; // Highest bid first
            } else {
                return a.price > b.price; // Lowest ask first
            }
        }
    };

    std::priority_queue<Order, std::vector<Order>, CompareOrders> buy_orders_;
    std::priority_queue<Order, std::vector<Order>, CompareOrders> sell_orders_;
    std::unordered_map<uint64_t, Order> active_orders_;
    std::mutex mutex_;
};
