### **`order_book.cpp` – Matching Logic**
```cpp
#include "order_book.h"
#include <algorithm>

void OrderBook::add_order(const Order& order) {
    std::lock_guard<std::mutex> lock(mutex_);
    active_orders_[order.order_id] = order;

    if (order.side == OrderSide::BUY) {
        buy_orders_.push(order);
    } else {
        sell_orders_.push(order);
    }
}

void OrderBook::cancel_order(uint64_t order_id) {
    std::lock_guard<std::mutex> lock(mutex_);
    active_orders_.erase(order_id);
}

std::vector<Order> OrderBook::match_orders() {
    std::vector<Order> matched_orders;
    std::lock_guard<std::mutex> lock(mutex_);

    while (!buy_orders_.empty() && !sell_orders_.empty()) {
        const Order& best_buy = buy_orders_.top();
        const Order& best_sell = sell_orders_.top();

        if (best_buy.price >= best_sell.price) {
            uint64_t matched_qty = std::min(best_buy.quantity, best_sell.quantity);
            matched_orders.push_back({best_buy.order_id, best_buy.instrument_id, best_buy.side, best_buy.type, best_buy.price, matched_qty, 0, 0});
            matched_orders.push_back({best_sell.order_id, best_sell.instrument_id, best_sell.side, best_sell.type, best_sell.price, matched_qty, 0, 0});

            // Update remaining quantities
            buy_orders_.pop();
            sell_orders_.pop();
        } else {
            break;
        }
    }
    return matched_orders;
}
