```cpp
#include "market_data_handler.h"
#include "logger.h"
#include <iostream>

MarketDataHandler::MarketDataHandler(boost::asio::io_context& io_context, OrderBook& order_book)
    : socket_(io_context), order_book_(order_book) {}

void MarketDataHandler::start(const std::string& host, uint16_t port) {
    boost::asio::ip::tcp::resolver resolver(socket_.get_executor());
    auto endpoints = resolver.resolve(host, std::to_string(port));
    boost::asio::connect(socket_, endpoints);

    boost::asio::async_read_until(
        socket_,
        buffer_,
        '\n',
        [this](const boost::system::error_code& error, size_t bytes_read) {
            handle_market_data(error, bytes_read);
        });
}

void MarketDataHandler::handle_market_data(const boost::system::error_code& error, size_t bytes_read) {
    if (!error) {
        std::istream is(&buffer_);
        std::string data;
        std::getline(is, data);
        process_market_data(data);
        start("127.0.0.1", 5000); // Re-arm the async read
    } else {
        Logger::get()->error("Market data handler error: {}", error.message());
    }
}

void MarketDataHandler::process_market_data(const std::string& data) {
    // Parse market data (simplified)
    Order order;
    order.instrument_id = 1; // AAPL
    order.side = (data.find("BID") != std::string::npos) ? OrderSide::BUY : OrderSide::SELL;
    order.price = std::stod(data.substr(4, 6));
    order.quantity = std::stoull(data.substr(11));

    order_book_.add_order(order);
    Logger::get()->info("Processed order: {} {} @ {}", order.side, order.quantity, order.price);
}
