    Logger::init("trading_platform.log");

    // Set up async I/O context
    boost::asio::io_context io_context;
    boost::asio::executor_work_guard<boost::asio::io_context::executor_type> work_guard(io_context.get_executor());

    // Core components
    OrderBook order_book;
    RiskManager risk_manager;
    risk_manager.set_max_position(1, 1000000); // Max position for instrument 1

    // Start market data handler
    MarketDataHandler market_data_handler(io_context, order_book);
    market_data_handler.start("127.0.0.1", 5000);

    // Start matching engine thread
    std::thread matching_thread([&]() {
        while (true) {
            auto matched_orders = order_book.match_orders();
            for (const auto& order : matched_orders) {
                Logger::get()->info("Matched order: {} {} @ {}", order.side, order.quantity, order.price);
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
    });

    // Run I/O context in a separate thread
    std::thread io_thread([&]() { io_context.run(); });

    // Keep main thread alive
    while (true) {
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    io_thread.join();
    matching_thread.join();
    return 0;
}
