use std::collections::BTreeMap;
use crate::order::{Order, OrderSide};

#[derive(Debug)]
pub struct OrderBook {
    bids: BTreeMap<f64, Vec<Order>>, // Price -> List of orders (sorted by time)
    asks: BTreeMap<f64, Vec<Order>>, // Price -> List of orders (sorted by time)
}

impl OrderBook {
    pub fn new() -> Self {
        OrderBook {
            bids: BTreeMap::new(),
            asks: BTreeMap::new(),
        }
    }

    pub fn add_order(&mut self, order: Order) {
        match order.side {
            OrderSide::Buy => {
                self.bids.entry(order.price).or_default().push(order);
            }
            OrderSide::Sell => {
                self.asks.entry(order.price).or_default().push(order);
            }
        }
    }

    pub fn remove_order(&mut self, order_id: &str) -> Option<Order> {
        for (_, orders) in self.bids.iter_mut() {
            if let Some(pos) = orders.iter().position(|o| o.id == order_id) {
                return Some(orders.remove(pos));
            }
        }
        for (_, orders) in self.asks.iter_mut() {
            if let Some(pos) = orders.iter().position(|o| o.id == order_id) {
                return Some(orders.remove(pos));
            }
        }
        None
    }

    pub fn get_best_bid(&self) -> Option<f64> {
        self.bids.keys().next_back().copied()
    }

    pub fn get_best_ask(&self) -> Option<f64> {
        self.asks.keys().next().copied()
    }

    pub fn get_orders_at_price(&self, price: f64, side: &OrderSide) -> Vec<Order> {
        match side {
            OrderSide::Buy => self.bids.get(&price).cloned().unwrap_or_default(),
            OrderSide::Sell => self.asks.get(&price).cloned().unwrap_or_default(),
        }
    }
}
