```rust
use std::sync::Arc;
use tokio::sync::Mutex;
use tokio::sync::mpsc::Receiver;
use warp::Filter;
use crate::order::{Order, Trade};
use crate::order_book::OrderBook;

pub async fn start(
    order_book: Arc<Mutex<OrderBook>>,
    mut market_data_rx: Receiver<Vec<Trade>>,
) {
    tokio::spawn(async move {
        while let Some(trades) = market_data_rx.recv().await {
            println!("Market data update: {:?}", trades);
        }
    });

    let order_book_route = warp::path!("order_book" / String)
        .and(warp::get())
        .and(with_order_book(order_book.clone()))
        .and_then(handle_order_book_request);

    let submit_order_route = warp::path!("submit_order")
        .and(warp::post())
        .and(warp::body::json())
        .and(with_order_book(order_book.clone()))
        .and_then(handle_submit_order);

    let routes = order_book_route.or(submit_order_route);
    warp::serve(routes)
        .run(([127, 0, 0, 1], 3030))
        .await;
}

fn with_order_book(
    order_book: Arc<Mutex<OrderBook>>,
) -> impl Filter<Extract = (Arc<Mutex<OrderBook>>,), Error = std::convert::Infallible> + Clone {
    warp::any().map(move || order_book.clone())
}

async fn handle_order_book_request(
    symbol: String,
    order_book: Arc<Mutex<OrderBook>>,
) -> Result<impl warp::Reply, warp::Rejection> {
    let order_book = order_book.lock().await;
    let best_bid = order_book.get_best_bid();
    let best_ask = order_book.get_best_ask();
    Ok(warp::reply::json(&serde_json::json!({
        "symbol": symbol,
        "best_bid": best_bid,
        "best_ask": best_ask,
    })))
}

async fn handle_submit_order(
    order: Order,
    order_book: Arc<Mutex<OrderBook>>,
) -> Result<impl warp::Reply, warp::Rejection> {
    let mut order_book = order_book.lock().await;
    order_book.add_order(order);
    Ok(warp::reply::json(&serde_json::json!({ "status": "success" })))
}
