use std::collections::BTreeMap;
use crate::order::{Order, OrderSide};

#[derive(Debug, Default)]
pub struct OrderBook {
    bids: BTreeMap<f64, Vec<Order>>, // Price -> List of orders (buy orders)
    asks: BTreeMap<f64, Vec<Order>>, // Price -> List of orders (sell orders)
}

impl OrderBook {
    pub fn new() -> Self {
        Self {
            bids: BTreeMap::new(),
            asks: BTreeMap::new(),
        }
    }

    pub fn add_order(&mut self, order: Order) {
        match order.side {
            OrderSide::Buy => self.bids.entry(order.price).or_default().push(order),
            OrderSide::Sell => self.asks.entry(order.price).or_default().push(order),
        }
    }

    pub fn remove_order(&mut self, order_id: u64) -> Option<Order> {
        // Search through bids
        if let Some(orders) = self.bids.values_mut().find(|v| v.iter().any(|o| o.order_id == order_id)) {
            if let Some(pos) = orders.iter().position(|o| o.order_id == order_id) {
                return Some(orders.remove(pos));
            }
        }

        // Search through asks
        if let Some(orders) = self.asks.values_mut().find(|v| v.iter().any(|o| o.order_id == order_id)) {
            if let Some(pos) = orders.iter().position(|o| o.order_id == order_id) {
                return Some(orders.remove(pos));
            }
        }

        None
    }

    pub fn best_bid(&self) -> Option<f64> {
        self.bids.keys().next().copied()
    }

    pub fn best_ask(&self) -> Option<f64> {
        self.asks.keys().next().copied()
    }

    pub fn get_bids(&self) -> &BTreeMap<f64, Vec<Order>> {
        &self.bids
    }

    pub fn get_asks(&self) -> &BTreeMap<f64, Vec<Order>> {
        &self.asks
    }
}
