```rust
use crate::order::{Order, OrderSide};
use crate::orderbook::OrderBook;
use std::sync::Arc;
use tokio::sync::Mutex;

#[derive(Debug, Default)]
pub struct MatchingEngine {
    order_book: Arc<Mutex<OrderBook>>,
}

impl MatchingEngine {
    pub fn new() -> Self {
        Self {
            order_book: Arc::new(Mutex::new(OrderBook::new())),
        }
    }

    pub async fn add_order(&self, order: Order) -> Vec<Order> {
        let mut trades = Vec::new();
        let mut order_book = self.order_book.lock().await;

        match order.side {
            OrderSide::Buy => {
                // Match against existing asks
                while order.quantity > 0 && !order_book.asks.is_empty() {
                    let best_ask = match order_book.best_ask() {
                        Some(price) => price,
                        None => break,
                    };

                    if best_ask > order.price {
                        break; // No more matches possible
                    }

                    let ask_orders = order_book.asks.get_mut(&best_ask).unwrap();
                    if let Some(ask_order) = ask_orders.first_mut() {
                        let matched_quantity = order.quantity.min(ask_order.quantity);
                        trades.push(Order {
                            order_id: ask_order.order_id,
                            symbol: ask_order.symbol.clone(),
                            price: best_ask,
                            quantity: matched_quantity,
                            side: OrderSide::Sell,
                            timestamp: order.timestamp,
                        });

                        order.quantity -= matched_quantity;
                        ask_order.quantity -= matched_quantity;

                        if ask_order.quantity == 0.0 {
                            ask_orders.remove(0);
                        }
                    } else {
                        break;
                    }
                }

                if order.quantity > 0 {
                    // No more matches; add to order book
                    order_book.add_order(order);
                }
            }
            OrderSide::Sell => {
                // Match against existing bids
                while order.quantity > 0 && !order_book.bids.is_empty() {
                    let best_bid = match order_book.best_bid() {
                        Some(price) => price,
                        None => break,
                    };

                    if best_bid < order.price {
                        break; // No more matches possible
                    }

                    let bid_orders = order_book.bids.get_mut(&best_bid).unwrap();
                    if let Some(bid_order) = bid_orders.first_mut() {
                        let matched_quantity = order.quantity.min(bid_order.quantity);
                        trades.push(Order {
                            order_id: bid_order.order_id,
                            symbol: bid_order.symbol.clone(),
                            price: best_bid,
                            quantity: matched_quantity,
                            side: OrderSide::Buy,
                            timestamp: order.timestamp,
                        });

                        order.quantity -= matched_quantity;
                        bid_order.quantity -= matched_quantity;

                        if bid_order.quantity == 0.0 {
                            bid_orders.remove(0);
                        }
                    } else {
                        break;
                    }
                }

                if order.quantity > 0 {
                    // No more matches; add to order book
                    order_book.add_order(order);
                }
            }
        }

        trades
    }

    pub async fn get_order_book(&self) -> OrderBook {
        let order_book = self.order_book.lock().await;
        order_book.clone()
    }
}
