            ));
        }
        if order.price < self.min_order_price {
            return Err(format!(
                "Order price {} is below minimum allowed {}",
                order.price, self.min_order_price
            ));
        }
        if order.price > self.max_order_price {
            return Err(format!(
                "Order price {} exceeds maximum allowed {}",
                order.price, self.max_order_price
            ));
        }
        Ok(())
    }
