### 6. src/server.rs

```rust
use std::net::SocketAddr;
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::mpsc;
use crate::order::Order;
use crate::matching_engine::MatchingEngine;
use crate::risk_manager::RiskManager;

pub async fn start_server(
    matching_engine: MatchingEngine,
    risk_manager: RiskManager,
    addr: SocketAddr,
) -> tokio::io::Result<()> {
    let listener = TcpListener::bind(addr).await?;
    println!("Server listening on {}", addr);

    loop {
        let (stream, _) = listener.accept().await?;
        let matching_engine = matching_engine.clone();
        let risk_manager = risk_manager.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_connection(stream, matching_engine, risk_manager).await {
                eprintln!("Error handling connection: {}", e);
            }
        });
    }
}

async fn handle_connection(
    mut stream: TcpStream,
    matching_engine: MatchingEngine,
    risk_manager: RiskManager,
) -> tokio::io::Result<()> {
    let mut buffer = [0; 1024];

    loop {
        let n = stream.read(&mut buffer).await?;
        if n == 0 {
            return Ok(()); // Connection closed
        }

        let order_str = String::from_utf8_lossy(&buffer[..n]);
        match parse_order(&order_str) {
            Ok(order) => {
                if let Err(e) = risk_manager.validate_order(&order) {
                    eprintln!("Risk check failed: {}", e);
                    let response = format!("ERROR: {}\n", e);
                    stream.write_all(response.as_bytes()).await?;
                    continue;
                }

                let trades = matching_engine.add_order(order).await;
                if !trades.is_empty() {
                    for trade in trades {
                        let trade_json = serde_json::to_string(&trade)?;
                        let response = format!("TRADE: {}\n", trade_json);
                        stream.write_all(response.as_bytes()).await?;
                    }
                } else {
                    let response = "ORDER_ACCEPTED\n".to_string();
                    stream.write_all(response.as_bytes()).await?;
                }
            }
            Err(e) => {
                let response = format!("ERROR: {}\n", e);
                stream.write_all(response.as_bytes()).await?;
            }
        }
    }
}

fn parse_order(order_str: &str) -> Result<Order, String> {
    let parts: Vec<&str> = order_str.trim().split(',').collect();
    if parts.len() != 4 {
        return Err("Invalid order format. Expected: symbol,price,quantity,side".to_string());
    }

    let symbol = parts[0].to_string();
    let price = parts[1].parse::<f64>().map_err(|_| "Invalid price")?;
    let quantity = parts[2].parse::<f64>().map_err(|_| "Invalid quantity")?;
    let side = match parts[3].to_lowercase().as_str() {
        "buy" => crate::order::OrderSide::Buy,
        "sell" => crate::order::OrderSide::Sell,
        _ => return Err("Invalid side. Use 'buy' or 'sell'".to_string()),
    };

    Ok(Order::new(&symbol, price, quantity, side))
}
