```cpp
// src/market_data_feed.cpp
#include "market_data_feed.h"
#include <iostream>
#include <random>

MarketDataFeed::MarketDataFeed(const std::string& endpoint)
    : context_(1), publisher_(context_, ZMQ_PUB) {
    publisher_.bind(endpoint);
    running_ = true;
    feed_thread_ = std::thread(&MarketDataFeed::simulateMarketData, this);
}

void MarketDataFeed::start() {
    feed_thread_.join();
}

void MarketDataFeed::simulateMarketData() {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<> price_dist(100.0, 200.0);
    std::uniform_int_distribution<> qty_dist(1, 1000);

    while (running_) {
        auto price = price_dist(gen);
        auto quantity = qty_dist(gen);
        publishMarketData("AAPL", price, quantity);
        std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Simulate market data feed
    }
}

void MarketDataFeed::publishMarketData(const std::string& symbol, double price, uint64_t quantity) {
    zmq::message_t message(sizeof(double) + sizeof(uint64_t) + symbol.size());
    memcpy(message.data(), symbol.c_str(), symbol.size());
    memcpy(static_cast<char*>(message.data()) + symbol.size(), &price, sizeof(price));
    memcpy(static_cast<char*>(message.data()) + symbol.size() + sizeof(price), &quantity, sizeof(quantity));
    publisher_.send(message);
}
```

