#### 4. Matching Engine:
```cpp
// include/matching_engine.h
#pragma once

#include "utils.h"
#include <zmq.hpp>
#include <thread>
#include <map>
#include <queue>

class MatchingEngine {
public:
    MatchingEngine(const std::string& sub_endpoint, const std::string& pub_endpoint);
    void start();

private:
    zmq::context_t context_;
    zmq::socket_t subscriber_;
    zmq::socket_t publisher_;
    std::thread engine_thread_;
    bool running_ = false;

    // Order book: symbol -> (buy_orders, sell_orders)
    std::map<std::string, std::priority_queue<Order, std::vector<Order>, CompareOrders>> order_books_;

    void processOrders();
    void matchOrder(const Order& order);
    void publishTrade(const Trade& trade);
};
```

```cpp
// src/matching_engine.cpp
#include "matching_engine.h"
#include <iostream>

struct CompareOrders {
    bool operator()(const Order& a, const Order& b) {
        if (a.type == OrderType::LIMIT && b.type == OrderType::LIMIT) {
            if (a.side == OrderSide::BUY) {
                return a.price < b.price; // Highest bid first
            } else {
                return a.price > b.price; // Lowest ask first
            }
        }
        return false; // Simplified
    }
};

MatchingEngine::MatchingEngine(const std::string& sub_endpoint, const std::string& pub_endpoint)
    : context_(1), subscriber_(context_, ZMQ_SUB), publisher_(context_, ZMQ_PUB) {
    subscriber_.connect(sub_endpoint);
    subscriber_.setsockopt(ZMQ_SUBSCRIBE, "", 0);
    publisher_.bind(pub_endpoint);
    running_ = true;
    engine_thread_ = std::thread(&MatchingEngine::processOrders, this);
}

void MatchingEngine::start() {
    engine_thread_.join();
}

void MatchingEngine::processOrders() {
    while (running_) {
        zmq::message_t message;
        subscriber_.recv(message);

        // Deserialize order (simplified)
        Order order;
        memcpy(&order, message.data(), sizeof(Order));
        matchOrder(order);
    }
}

void MatchingEngine::matchOrder(const Order& order) {
    auto& order_book = order_books_[order.symbol];

    if (order.side == OrderSide::BUY) {
        while (!order_book.empty() && order_book.top().side == OrderSide::SELL &&
               order_book.top().price <= order.price && order.quantity > 0) {
            Order ask = order_book.top();
            order_book.pop();

            uint64_t matched_qty = std::min(order.quantity, ask.quantity);
            order.quantity -= matched_qty;
            ask.quantity -= matched_qty;

            Trade trade;
            trade.trade_id = "trade_" + std::to_string(rand());
            trade.order_id = order.order_id;
            trade.symbol = order.symbol;
            trade.side = order.side;
            trade.price = ask.price; // Trade at ask price
            trade.quantity = matched_qty;
            trade.timestamp = std::chrono::system_clock::now();

            publishTrade(trade);

            if (ask.quantity > 0) {
                order_book.push(ask); // Reinsert remaining quantity
            }
        }

        if (order.quantity > 0) {
            order_book.push(order); // Add to order book if not fully matched
        }
    } else { // SELL
        while (!order_book.empty() && order_book.top().side == OrderSide::BUY &&
               order_book.top().price >= order.price && order.quantity > 0) {
            Order bid = order_book.top();
            order_book.pop();

            uint64_t matched_qty = std::min(order.quantity, bid.quantity);
            order.quantity -= matched_qty;
            bid.quantity -= matched_qty;

            Trade trade;
            trade.trade_id = "trade_" + std::to_string(rand());
            trade.order_id = order.order_id;
            trade.symbol = order.symbol;
            trade.side = order.side;
            trade.price = bid.price; // Trade at bid price
            trade.quantity = matched_qty;
            trade.timestamp = std::chrono::system_clock::now();

            publishTrade(trade);

            if (bid.quantity > 0) {
                order_book.push(bid); // Reinsert remaining quantity
            }
        }

        if (order.quantity > 0) {
            order_book.push(order); // Add to order book if not fully matched
        }
    }
}

void MatchingEngine::publishTrade(const Trade& trade) {
    zmq::message_t message(sizeof(Trade));
    memcpy(message.data(), &trade, sizeof(Trade));
    publisher_.send(message);
}
```

