    MarketDataFeed md_feed(md_feed_endpoint);
    OrderManagementSystem oms(oms_pub_endpoint, oms_rep_endpoint);
    MatchingEngine matching_engine(matching_sub_endpoint, matching_pub_endpoint);

    std::cout << "Starting trading platform..." << std::endl;

    // Start components in separate threads
    std::thread md_thread([&md_feed]() { md_feed.start(); });
    std::thread oms_thread([&oms]() { oms.start(); });
    std::thread matching_thread([&matching_engine]() { matching_engine.start(); });

    while (!stop) {
        std::this_thread::sleep_for(std::chrono::seconds(1));
