class OrderBook {
public:
    void addOrder(const Order& order);
    void cancelOrder(const std::string& order_id);
    void modifyOrder(const std::string& order_id, int new_quantity);

    void print() const;

private:
    struct OrderEntry {
        Order order;
        std::list<std::string>::iterator position;
    };

    std::map<std::string, OrderEntry> orders;
    std::map<std::string, std::list<std::string>> price_levels; // price -> list of order_ids
    std::map<std::string, std::list<std::string>> symbol_orders; // symbol -> list of order_ids
