```cpp
// order_book.cpp
#include "order_book.h"
#include <iostream>

void OrderBook::addOrder(const Order& order) {
    auto order_id = order.order_id;
    orders[order_id] = {order, {}};
    symbol_orders[order.symbol].push_back(order_id);
    price_levels[std::to_string(order.price)].push_back(order_id);
    std::cout << "Added order: " << order_id << " " << order.symbol << " "
              << (order.side == OrderSide::BUY ? "BUY" : "SELL")
              << " " << order.price << " " << order.quantity << std::endl;
}

void OrderBook::cancelOrder(const std::string& order_id) {
    auto it = orders.find(order_id);
    if (it != orders.end()) {
        auto& order = it->second.order;
        symbol_orders[order.symbol].remove(order_id);
        price_levels[std::to_string(order.price)].remove(order_id);
        orders.erase(it);
        std::cout << "Cancelled order: " << order_id << std::endl;
    }
}

void OrderBook::modifyOrder(const std::string& order_id, int new_quantity) {
    auto it = orders.find(order_id);
    if (it != orders.end()) {
        it->second.order.quantity = new_quantity;
        std::cout << "Modified order: " << order_id << " new quantity: " << new_quantity << std::endl;
    }
}

void OrderBook::print() const {
    std::cout << "Order Book:" << std::endl;
    for (const auto& [symbol, orders] : symbol_orders) {
        std::cout << "Symbol: " << symbol << std::endl;
        for (const auto& order_id : orders) {
            const auto& order = orders.at(order_id).order;
            std::cout << "  Order ID: " << order_id
                      << " Side: " << (order.side == OrderSide::BUY ? "BUY" : "SELL")
                      << " Price: " << order.price
                      << " Quantity: " << order.quantity << std::endl;
        }
    }
}
