```cpp
// market_data.cpp
#include "market_data.h"
#include <cstdlib>
#include <ctime>

MarketDataSimulator::MarketDataSimulator() {
    // Initialize with some dummy data
    market_data["AAPL"] = {"AAPL", 150.0, 100, 150.1, 150, 150.05, 200};
    market_data["MSFT"] = {"MSFT", 300.0, 200, 300.1, 250, 300.05, 300};
    std::srand(std::time(0));
}

MarketData MarketDataSimulator::getMarketData(const std::string& symbol) const {
    auto it = market_data.find(symbol);
    if (it != market_data.end()) {
        return it->second;
    }
    return {};
}

void MarketDataSimulator::updateMarketData(const std::string& symbol, double price_change) {
    auto it = market_data.find(symbol);
    if (it != market_data.end()) {
        auto& md = it->second;
        if (std::rand() % 2 == 0) {
            md.bid_price += price_change;
            md.ask_price += price_change;
        } else {
            md.bid_price -= price_change;
            md.ask_price -= price_change;
        }
        md.last_trade_price = (md.bid_price + md.ask_price) / 2;
        std::cout << "Updated market data for " << symbol
                  << ": Bid=" << md.bid_price << ", Ask=" << md.ask_price
                  << ", Last=" << md.last_trade_price << std::endl;
    }
}
