```cpp
// oms.cpp
#include "oms.h"
#include <iostream>

void OrderManagementSystem::processOrder(const Order& order) {
    // Basic risk check: order size must be positive
    if (order.quantity <= 0) {
        std::cerr << "Order rejected: invalid quantity for order " << order.order_id << std::endl;
        return;
    }

    // For market orders, set price to 0 (or use best bid/ask)
    if (order.price == 0.0) {
        auto md = market_data_sim_.getMarketData(order.symbol);
        if (order.side == OrderSide::BUY) {
            order_book_.addOrder({order.order_id, order.symbol, order.side, md.ask_price, order.quantity, order.timestamp});
        } else {
            order_book_.addOrder({order.order_id, order.symbol, order.side, md.bid_price, order.quantity, order.timestamp});
        }
    } else {
        order_book_.addOrder(order);
    }
    std::cout << "Processed order: " << order.order_id << std::endl;
}

void OrderManagementSystem::cancelOrder(const std::string& order_id) {
    order_book_.cancelOrder(order_id);
}

void OrderManagementSystem::modifyOrder(const std::string& order_id, int new_quantity) {
    order_book_.modifyOrder(order_id, new_quantity);
}
