    OrderManagementSystem oms(order_book, market_data_sim);

    // Simulate market data updates
    std::thread market_data_thread([&market_data_sim]() {
        while (true) {
            market_data_sim.updateMarketData("AAPL", 0.1);
            market_data_sim.updateMarketData("MSFT", 0.2);
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    });

    // Simulate order entry
    std::thread order_entry_thread([&oms]() {
        int order_id_counter = 0;
        while (true) {
            Order order;
            order.order_id = "order_" + std::to_string(++order_id_counter);
            order.symbol = (order_id_counter % 2 == 0) ? "AAPL" : "MSFT";
            order.side = (order_id_counter % 2 == 0) ? OrderSide::BUY : OrderSide::SELL;
            order.price = 0.0; // Market order
            order.quantity = 100 + (order_id_counter % 50);
            order.timestamp = std::chrono::system_clock::now();

            oms.processOrder(order);
            std::this_thread::sleep_for(std::chrono::milliseconds(500));
        }
    });

    // Print order book periodically
    while (true) {
        order_book.print();
        std::this_thread::sleep_for(std::chrono::seconds(2));
    }

    market_data_thread.join();
    order_entry_thread.join();
    return 0;
}
