use tokio::sync::mpsc;
use std::sync::Arc;
use tokio::sync::Mutex;

#[tokio::main]
async fn main() {
    // Initialize shared state
    let order_book = Arc::new(Mutex::new(order_book::OrderBook::new()));
    let risk_manager = Arc::new(risk_manager::RiskManager::new());
    let persistence = Arc::new(Mutex::new(persistence::Persistence::new()));

    // Create channels for communication between components
    let (order_tx, order_rx) = mpsc::channel(100);
    let (market_data_tx, market_data_rx) = mpsc::channel(100);

    // Spawn the matching engine
    let matching_engine_order_book = Arc::clone(&order_book);
    let matching_engine_risk_manager = Arc::clone(&risk_manager);
    let matching_engine_persistence = Arc::clone(&persistence);
    tokio::spawn(async move {
        let mut engine = matching_engine::MatchingEngine::new(
            matching_engine_order_book,
            matching_engine_risk_manager,
            matching_engine_persistence,
        );
        engine.run(order_rx, market_data_tx).await;
    });

    // Spawn the API server
    let api_order_book = Arc::clone(&order_book);
    let api_market_data_rx = market_data_rx;
    tokio::spawn(async move {
        api_server::start(api_order_book, api_market_data_rx).await;
    });

    // Keep the main thread alive
    tokio::signal::ctrl_c().await.expect("Failed to listen for ctrl-c");
}
