#### src/matching_engine.rs
```rust
use std::sync::Arc;
use tokio::sync::Mutex;
use tokio::sync::mpsc::{Receiver, Sender};
use crate::order::{Order, OrderSide, Trade};
use crate::order_book::OrderBook;
use crate::risk_manager::RiskManager;
use crate::persistence::Persistence;

pub struct MatchingEngine {
    order_book: Arc<Mutex<OrderBook>>,
    risk_manager: Arc<RiskManager>,
    persistence: Arc<Mutex<Persistence>>,
}

impl MatchingEngine {
    pub fn new(
        order_book: Arc<Mutex<OrderBook>>,
        risk_manager: Arc<RiskManager>,
        persistence: Arc<Mutex<Persistence>>,
    ) -> Self {
        MatchingEngine {
            order_book,
            risk_manager,
            persistence,
        }
    }

    pub async fn run(&mut self, mut order_rx: Receiver<Order>, market_data_tx: Sender<Vec<Trade>>) {
        while let Some(order) = order_rx.recv().await {
            // Validate order with risk manager
            if !self.risk_manager.validate_order(&order).await {
                println!("Order validation failed: {:?}", order);
                continue;
            }

            // Match the order against the order book
            let trades = self.match_order(order).await;

            // Persist trades
            if !trades.is_empty() {
                let mut persistence = self.persistence.lock().await;
                for trade in &trades {
                    persistence.add_trade(trade.clone()).await;
                }
            }

            // Send market data updates
            if !trades.is_empty() {
                market_data_tx.send(trades).await.expect("Failed to send market data");
            }
        }
    }

    async fn match_order(&mut self, order: Order) -> Vec<Trade> {
        let mut trades = Vec::new();
        let mut order_book = self.order_book.lock().await;

        match order.side {
            OrderSide::Buy => {
                // Match against asks (sell orders)
                while let Some((&ask_price, asks)) = order_book.asks.iter().next() {
                    if ask_price > order.price && order.order_type == crate::order::OrderType::Limit {
                        break; // No more matches possible for limit buy order
                    }

                    // Match against all orders at this price level
                    while let Some(ask_order) = asks.first() {
                        let trade_quantity = order.quantity.min(ask_order.quantity);
                        let trade = Trade {
                            id: format!("trade_{}", uuid::Uuid::new_v4()),
                            symbol: order.symbol.clone(),
                            buy_order_id: order.id.clone(),
                            sell_order_id: ask_order.id.clone(),
                            price: ask_price,
                            quantity: trade_quantity,
                            timestamp: chrono::Utc::now().timestamp() as u64,
                        };
                        trades.push(trade);

                        // Update quantities
                        order.quantity -= trade_quantity;
                        // In a real system, you'd update the order quantities in the order book
                        // For simplicity, we'll just remove the order if fully filled
                        if ask_order.quantity <= trade_quantity {
                            order_book.asks.get_mut(&ask_price).unwrap().remove(0);
                        } else {
                            // Update the order quantity
                            // This is simplified; in a real system, you'd have a more robust way to update orders
                            if let Some(first) = order_book.asks.get_mut(&ask_price).unwrap().first_mut() {
                                first.quantity -= trade_quantity;
                            }
                        }

                        if order.quantity <= 0.0 {
                            break;
                        }
                    }

                    if order.quantity <= 0.0 {
                        break;
                    }

                    // Remove the price level if no more orders
                    if asks.is_empty() {
                        order_book.asks.remove(&ask_price);
                    }
                }

                // If the order is not fully filled, add it to the order book
                if order.quantity > 0.0 {
                    order_book.add_order(order);
                }
            }
            OrderSide::Sell => {
                // Similar logic for sell orders
                while let Some((&bid_price, bids)) = order_book.bids.iter().next_back() {
                    if bid_price < order.price && order.order_type == crate::order::OrderType::Limit {
                        break; // No more matches possible for limit sell order
                    }

                    while let Some(bid_order) = bids.first() {
                        let trade_quantity = order.quantity.min(bid_order.quantity);
                        let trade = Trade {
                            id: format!("trade_{}", uuid::Uuid::new_v4()),
                            symbol: order.symbol.clone(),
                            buy_order_id: bid_order.id.clone(),
                            sell_order_id: order.id.clone(),
                            price: bid_price,
                            quantity: trade_quantity,
                            timestamp: chrono::Utc::now().timestamp() as u64,
                        };
                        trades.push(trade);

                        order.quantity -= trade_quantity;
                        if bid_order.quantity <= trade_quantity {
                            order_book.bids.get_mut(&bid_price).unwrap().remove(0);
                        } else {
                            if let Some(first) = order_book.bids.get_mut(&bid_price).unwrap().first_mut() {
                                first.quantity -= trade_quantity;
                            }
                        }

                        if order.quantity <= 0.0 {
                            break;
                        }
                    }

                    if order.quantity <= 0.0 {
                        break;
                    }

                    if bids.is_empty() {
                        order_book.bids.remove(&bid_price);
                    }
                }

                if order.quantity > 0.0 {
                    order_book.add_order(order);
                }
            }
        }

        trades
    }
}
```

