use crate::order::Order;

#[derive(Debug, Default)]
pub struct RiskManager {
    max_order_size: f64,
    min_order_price: f64,
    max_order_price: f64,
}

impl RiskManager {
    pub fn new(max_order_size: f64, min_order_price: f64, max_order_price: f64) -> Self {
        Self {
            max_order_size,
            min_order_price,
            max_order_price,
        }
    }

    pub fn validate_order(&self, order: &Order) -> Result<(), String> {
        if order.quantity > self.max_order_size {
            return Err(format!("Order size {} exceeds maximum allowed {}", order.quantity, self.max_order_size));
        }
        if order.price < self.min_order_price {
            return Err(format!("Order price {} is below minimum allowed {}", order.price, self.min_order_price));
        }
        if order.price > self.max_order_price {
            return Err(format!("Order price {} exceeds maximum allowed {}", order.price, self.max_order_price));
        }
        Ok(())
    }
}
