#### 6. TCP Server (`server.rs`):
```rust
use std::net::{TcpListener, TcpStream};
use std::io::{Read, Write};
use std::sync::mpsc::{channel, Sender};
use std::thread;
use crate::order::{Order, OrderSide};
use crate::matching_engine::MatchingEngine;
use crate::risk_manager::RiskManager;

pub fn start_server(matching_engine: MatchingEngine, risk_manager: RiskManager) {
    let listener = TcpListener::bind("127.0.0.1:8080").unwrap();
    println!("Server listening on 127.0.0.1:8080");

    for stream in listener.incoming() {
        match stream {
            Ok(stream) => {
                let matching_engine = matching_engine.clone();
                let risk_manager = risk_manager.clone();
                thread::spawn(move || handle_client(stream, matching_engine, risk_manager));
            }
            Err(e) => {
                eprintln!("Failed to accept connection: {}", e);
            }
        }
    }
}

fn handle_client(mut stream: TcpStream, mut matching_engine: MatchingEngine, risk_manager: RiskManager) {
    let mut buffer = [0; 1024];
    loop {
        match stream.read(&mut buffer) {
            Ok(size) if size > 0 => {
                let order_str = String::from_utf8_lossy(&buffer[..size]);
                if let Ok(order) = parse_order(&order_str) {
                    if let Err(e) = risk_manager.validate_order(&order) {
                        eprintln!("Risk check failed: {}", e);
                        continue;
                    }
                    let trades = matching_engine.add_order(order);
                    if !trades.is_empty() {
                        for trade in trades {
                            let trade_str = format!("TRADE: {:?}\n", trade);
                            stream.write_all(trade_str.as_bytes()).unwrap();
                        }
                    }
                }
            }
            Ok(_) => break, // Connection closed
            Err(e) => {
                eprintln!("Failed to read from stream: {}", e);
                break;
            }
        }
    }
}

fn parse_order(order_str: &str) -> Result<Order, String> {
    let parts: Vec<&str> = order_str.trim().split(',').collect();
    if parts.len() != 4 {
        return Err("Invalid order format".to_string());
    }
    let symbol = parts[0].to_string();
    let price = parts[1].parse::<f64>().map_err(|_| "Invalid price")?;
    let quantity = parts[2].parse::<f64>().map_err(|_| "Invalid quantity")?;
    let side = match parts[3].to_lowercase().as_str() {
        "buy" => OrderSide::Buy,
        "sell" => OrderSide::Sell,
        _ => return Err("Invalid side".to_string()),
    };
    Ok(Order::new(&symbol, price, quantity, side))
}
```

