Here's a complete implementation of a real-time market data processor in C++ that computes price aggregates and streams results to subscribers:

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <mutex>
#include <memory>
#include <thread>
#include <chrono>
#include <atomic>
#include <functional>
#include <nlohmann/json.hpp> // For JSON serialization (header-only)

using json = nlohmann::json;

// Market data event types
enum class EventType {
    TRADE,
    ORDER_BOOK_UPDATE
};

struct MarketDataEvent {
    EventType type;
    std::string symbol;
    double price;
    double quantity;
    std::chrono::system_clock::time_point timestamp;
    std::map<double, double> bids; // price -> quantity
    std::map<double, double> asks; // price -> quantity
};

// Aggregated market data to send to subscribers
struct MarketAggregates {
    std::string symbol;
    double best_bid;
    double best_ask;
    double mid_price;
    double vwap; // Volume Weighted Average Price
    double total_volume;
    std::chrono::system_clock::time_point timestamp;
};

// Subscriber interface
class Subscriber {
public:
    virtual ~Subscriber() = default;
    virtual void send(const MarketAggregates& data) = 0;
};

// Order book implementation
class OrderBook {
public:
    void update(const MarketDataEvent& event) {
        std::lock_guard<std::mutex> lock(mutex_);

        if (event.type == EventType::TRADE) {
            // Update VWAP and total volume
            vwap_volume_ += event.price * event.quantity;
            total_volume_ += event.quantity;
            if (total_volume_ > 0) {
                vwap_ = vwap_volume_ / total_volume_;
            }
        } else if (event.type == EventType::ORDER_BOOK_UPDATE) {
            // Update order book state
            bids_ = event.bids;
            asks_ = event.asks;

            // Update best bid/ask
            if (!bids_.empty()) {
                best_bid_ = bids_.rbegin()->first; // Highest bid
            }
            if (!asks_.empty()) {
                best_ask_ = asks_.begin()->first; // Lowest ask
            }
            mid_price_ = (best_bid_ + best_ask_) / 2.0;
        }

        last_update_ = event.timestamp;
    }

    MarketAggregates getAggregates() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return {
            symbol_,
            best_bid_,
            best_ask_,
            mid_price_,
            vwap_,
            total_volume_,
            last_update_
        };
    }

    void setSymbol(const std::string& symbol) {
        symbol_ = symbol;
    }

private:
    mutable std::mutex mutex_;
    std::string symbol_;
    std::map<double, double> bids_;
    std::map<double, double> asks_;
    double best_bid_ = 0.0;
    double best_ask_ = 0.0;
    double mid_price_ = 0.0;
    double vwap_ = 0.0;
    double vwap_volume_ = 0.0;
    double total_volume_ = 0.0;
    std::chrono::system_clock::time_point last_update_;
};

// Market data processor
class MarketDataProcessor {
public:
    MarketDataProcessor() : running_(true) {
        // Start processing thread
        processor_thread_ = std::thread(&MarketDataProcessor::processLoop, this);
    }

    ~MarketDataProcessor() {
        running_ = false;
        if (processor_thread_.joinable()) {
            processor_thread_.join();
        }
    }

    void addSubscriber(std::shared_ptr<Subscriber> subscriber) {
        std::lock_guard<std::mutex> lock(subscribers_mutex_);
        subscribers_.push_back(subscriber);
    }

    void removeSubscriber(std::shared_ptr<Subscriber> subscriber) {
        std::lock_guard<std::mutex> lock(subscribers_mutex_);
        subscribers_.erase(
            std::remove(subscribers_.begin(), subscribers_.end(), subscriber),
            subscribers_.end()
        );
    }

    void processMarketData(const MarketDataEvent& event) {
        {
            std::lock_guard<std::mutex> lock(order_book_mutex_);
            if (order_book_.empty()) {
                order_book_.emplace(event.symbol, OrderBook());
                order_book_.at(event.symbol).setSymbol(event.symbol);
            }
            order_book_.at(event.symbol).update(event);
        }

        // Notify subscribers
        auto aggregates = getAggregates(event.symbol);
        if (aggregates) {
            std::lock_guard<std::mutex> lock(subscribers_mutex_);
            for (auto& subscriber : subscribers_) {
                subscriber->send(*aggregates);
            }
        }
    }

    std::shared_ptr<MarketAggregates> getAggregates(const std::string& symbol) {
        std::lock_guard<std::mutex> lock(order_book_mutex_);
        if (order_book_.find(symbol) != order_book_.end()) {
            auto aggregates = std::make_shared<MarketAggregates>(
                order_book_.at(symbol).getAggregates()
            );
            return aggregates;
        }
        return nullptr;
    }

private:
    void processLoop() {
        while (running_) {
            // In a real system, this would process incoming market data
            // For this example, we'll simulate processing
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }

    std::map<std::string, OrderBook> order_book_;
    mutable std::mutex order_book_mutex_;
    std::vector<std::shared_ptr<Subscriber>> subscribers_;
    mutable std::mutex subscribers_mutex_;
    std::thread processor_thread_;
    std::atomic<bool> running_;
};

