struct MarketData {
    std::string instrument;
    double price;
    double volume;
    std::chrono::system_clock::time_point timestamp;

    MarketData(const std::string& inst, double p, double v)
        : instrument(inst), price(p), volume(v),
          timestamp(std::chrono::system_clock::now()) {}
};

struct PriceAggregate {
    std::string instrument;
    double last_price = 0.0;
    double total_volume = 0.0;
    double vwap = 0.0;
    int count = 0;
    std::mutex mtx;

    PriceAggregate(const std::string& inst) : instrument(inst) {}

    void update(const MarketData& data) {
        std::lock_guard<std::mutex> lock(mtx);
        last_price = data.price;
        total_volume += data.volume;
        count++;

        // Cumulative VWAP calculation
        vwap = (vwap * (total_volume - data.volume) + data.price * data.volume) / total_volume;
    }

    std::string toString() const {
        std::lock_guard<std::mutex> lock(mtx);
        return "Instrument: " + instrument +
               ", Last: " + std::to_string(last_price) +
               ", Volume: " + std::to_string(total_volume) +
               ", VWAP: " + std::to_string(vwap) +
               ", Count: " + std::to_string(count);
    }
};

// ======================
// Core Components
// ======================

class Aggregator {
private:
    std::unordered_map<std::string, std::shared_ptr<PriceAggregate>> aggregates;
    mutable std::mutex mtx;

public:
    void onMarketData(const MarketData& data) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = aggregates.find(data.instrument);
        if (it == aggregates.end()) {
            auto agg = std::make_shared<PriceAggregate>(data.instrument);
            agg->update(data);
            aggregates[data.instrument] = agg;
        } else {
            it->second->update(data);
        }
    }

    std::vector<std::shared_ptr<PriceAggregate>> getAllAggregates() const {
        std::lock_guard<std::mutex> lock(mtx);
        std::vector<std::shared_ptr<PriceAggregate>> result;
        for (const auto& pair : aggregates) {
            result.push_back(pair.second);
        }
        return result;
    }

    std::shared_ptr<PriceAggregate> getAggregate(const std::string& instrument) const {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = aggregates.find(instrument);
        if (it != aggregates.end()) {
            return it->second;
        }
        return nullptr;
    }
};

class Publisher {
private:
    std::vector<int> clients;
    std::mutex clients_mtx;
    std::atomic<bool> running{true};

public:
    void addClient(int client_socket) {
        std::lock_guard<std::mutex> lock(clients_mtx);
        clients.push_back(client_socket);
    }

    void removeClient(int client_socket) {
        std::lock_guard<std::mutex> lock(clients_mtx);
        clients.erase(std::remove(clients.begin(), clients.end(), client_socket), clients.end());
        close(client_socket);
    }

    void broadcast(const std::string& message) {
        std::lock_guard<std::mutex> lock(clients_mtx);
        for (auto it = clients.begin(); it != clients.end(); ) {
            int client = *it;
            if (send(client, message.c_str(), message.size(), 0) <= 0) {
                close(client);
                it = clients.erase(it);
            } else {
                ++it;
            }
        }
    }

    void startBroadcastThread(Aggregator& aggregator, int interval_ms = 100) {
        std::thread([this, &aggregator, interval_ms]() {
            while (running) {
                auto aggregates = aggregator.getAllAggregates();
                for (const auto& agg : aggregates) {
                    std::string msg = agg->toString() + "\n";
                    broadcast(msg);
                }
                std::this_thread::sleep_for(std::chrono::milliseconds(interval_ms));
            }
        }).detach();
    }

    void stop() {
        running = false;
    }
};

