// Network Server
// ======================

class MarketDataServer {
private:
    int server_fd;
    Aggregator aggregator;
    Publisher publisher;
    std::atomic<bool> running{true};
    std::thread server_thread;
    std::thread data_feed_thread;

    void handleClient(int client_socket) {
        publisher.addClient(client_socket);
        char buffer[1024] = {0};
        while (running) {
            int valread = read(client_socket, buffer, 1024);
            if (valread <= 0) break;
            // In a real system, you would process client messages here
        }
        publisher.removeClient(client_socket);
    }

    void acceptConnections() {
        sockaddr_in address{};
        address.sin_family = AF_INET;
        address.sin_addr.s_addr = INADDR_ANY;
        address.sin_port = htons(8080);

        if (bind(server_fd, (struct sockaddr*)&address, sizeof(address)) < 0) {
            perror("bind failed");
            exit(EXIT_FAILURE);
        }

        if (listen(server_fd, 3) < 0) {
            perror("listen");
            exit(EXIT_FAILURE);
        }

        std::cout << "Server listening on port 8080..." << std::endl;

        while (running) {
            sockaddr_in client_addr{};
            socklen_t addr_len = sizeof(client_addr);
            int client_socket = accept(server_fd, (struct sockaddr*)&client_addr, &addr_len);
            if (client_socket < 0) {
                if (running) perror("accept");
                continue;
            }

            char client_ip[INET_ADDRSTRLEN];
            inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, INET_ADDRSTRLEN);
            std::cout << "New connection from " << client_ip << ":" << ntohs(client_addr.sin_port)
                      << " (socket: " << client_socket << ")" << std::endl;

            std::thread(&MarketDataServer::handleClient, this, client_socket).detach();
        }
    }

    void mockMarketDataFeed() {
        std::vector<std::string> instruments = {"AAPL", "MSFT", "GOOGL", "AMZN", "TSLA", "NVDA"};
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> price_dist(100.0, 500.0);
        std::uniform_real_distribution<> volume_dist(10.0, 1000.0);

        while (running) {
            for (const auto& inst : instruments) {
                double price = price_dist(gen);
                double volume = volume_dist(gen);
                aggregator.onMarketData(MarketData(inst, price, volume));
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(50)); // Simulate market data rate
        }
    }

public:
    MarketDataServer() : server_fd(socket(AF_INET, SOCK_STREAM, 0)) {
        if (server_fd == 0) {
            perror("socket failed");
            exit(EXIT_FAILURE);
        }

        int opt = 1;
        if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt))) {
            perror("setsockopt");
            exit(EXIT_FAILURE);
        }
    }

    ~MarketDataServer() {
        stop();
    }

    void start() {
        publisher.startBroadcastThread(aggregator);
        server_thread = std::thread(&MarketDataServer::acceptConnections, this);
        data_feed_thread = std::thread(&MarketDataServer::mockMarketDataFeed, this);
    }

    void stop() {
        running = false;
        if (server_fd != -1) {
            close(server_fd);
            server_fd = -1;
        }
        publisher.stop();
        if (server_thread.joinable()) server_thread.join();
        if (data_feed_thread.joinable()) data_feed_thread.join();
    }
