```rust
use std::collections::VecDeque;
use std::sync::Arc;
use tokio::sync::Mutex;
use warp::Filter;
use serde::{Serialize, Deserialize};
use rand::Rng;
use tokio::time::{interval, Duration};

// Market data struct
#[derive(Debug, Clone, Serialize, Deserialize)]
struct MarketData {
    symbol: String,
    price: f64,
    volume: f64,
    timestamp: u64,
}

// Aggregate struct
#[derive(Debug, Clone, Serialize, Deserialize)]
struct Aggregate {
    symbol: String,
    sma: f64,      // Simple Moving Average
    ema: Option<f64>,  // Exponential Moving Average
    vwap: Option<f64>, // Volume-Weighted Average Price
    high: f64,     // High price in window
    low: f64,      // Low price in window
    volume: f64,   // Total volume in window
    timestamp: u64,
}

// Aggregator state
struct Aggregator {
    window_size: usize,
    data: VecDeque<MarketData>,
    ema_alpha: f64, // Smoothing factor for EMA
    last_ema: Option<f64>,
}

impl Aggregator {
    fn new(window_size: usize, ema_alpha: f64) -> Self {
        Aggregator {
            window_size,
            data: VecDeque::with_capacity(window_size),
            ema_alpha,
            last_ema: None,
        }
    }

    fn add_data(&mut self, data: MarketData) {
        self.data.push_back(data);
        if self.data.len() > self.window_size {
            self.data.pop_front();
        }
    }

    fn compute_aggregates(&mut self) -> Option<Aggregate> {
        if self.data.is_empty() {
            return None;
        }

        let window = &self.data;
        let symbol = &window[0].symbol;

        // Compute SMA
        let sma = window.iter().map(|d| d.price).sum::<f64>() / window.len() as f64;

        // Compute EMA (only when window is full)
        let ema = if window.len() >= self.window_size {
            match self.last_ema {
                Some(last) => self.ema_alpha * window.back().unwrap().price + (1.0 - self.ema_alpha) * last,
                None => sma, // Initialize EMA with SMA if not set
            }
        } else {
            None
        };
        if let Some(e) = ema {
            self.last_ema = Some(e);
        }

        // Compute VWAP (only when we have volume)
        let vwap = if window.iter().any(|d| d.volume > 0.0) {
            let (total_volume, total_price_volume) = window.iter().fold((0.0, 0.0), |acc, d| {
                (acc.0 + d.volume, acc.1 + d.price * d.volume)
            });
            Some(total_price_volume / total_volume)
        } else {
            None
        };

        // Compute high/low
        let high = window.iter().map(|d| d.price).fold(f64::MIN, |a, b| a.max(b));
        let low = window.iter().map(|d| d.price).fold(f64::MAX, |a, b| a.min(b));
        let volume = window.iter().map(|d| d.volume).sum();

        Some(Aggregate {
            symbol: symbol.clone(),
            sma,
            ema,
            vwap,
            high,
            low,
            volume,
            timestamp: window.back().unwrap().timestamp,
        })
    }
}

// WebSocket handler
async fn websocket_handler(
    ws: warp::ws::Ws,
    aggregator: Arc<Mutex<Aggregator>>,
) -> Result<impl warp::Reply, warp::Rejection> {
    Ok(ws.on_upgrade(move |socket| {
        handle_connection(socket, aggregator)
    }))
}

async fn handle_connection(ws: warp::ws::WebSocket, aggregator: Arc<Mutex<Aggregator>>) {
    let (mut tx, mut rx) = ws.split();

    // Spawn a task to send aggregates to the client
    let aggregator_clone = aggregator.clone();
    tokio::spawn(async move {
        let mut interval = interval(Duration::from_millis(100));
        loop {
            interval.tick().await;
            let mut agg = aggregator_clone.lock().await;
            if let Some(aggregate) = agg.compute_aggregates() {
                let msg = warp::ws::Message::text(serde_json::to_string(&aggregate).unwrap());
                if tx.send(msg).await.is_err() {
                    break;
                }
            }
        }
    });

    // Spawn a task to receive messages from the client (if needed)
    while let Some(result) = rx.next().await {
        match result {
            Ok(_) => continue,
            Err(_) => break,
        }
    }
}

