// marketDataFeed simulates a real-time market data feed
func marketDataFeed(ch chan<- MarketData) {
	symbols := []string{"AAPL", "MSFT", "GOOGL", "AMZN", "TSLA", "NVDA", "META", "INTC"}

	for {
		time.Sleep(time.Duration(rand.Intn(100)) * time.Millisecond)

		symbol := symbols[rand.Intn(len(symbols))]
		price := 100.0 + rand.Float64()*100.0
		volume := 1 + rand.Intn(1000)

		ch <- MarketData{
			Symbol: symbol,
			Price:  price,
			Volume: volume,
			Time:   time.Now().UnixNano(),
		}
	}
}

// run processes market data and updates aggregates
func (a *Aggregator) run(ch <-chan MarketData) {
	for marketData := range ch {
		startTime := time.Now()

		a.mu.Lock()
		symbolData, exists := a.symbolData[marketData.Symbol]
		if !exists {
			symbolData = &SymbolData{
				priceHistory: list.New(),
				sma5:         list.New(),
				sma20:        list.New(),
			}
			a.symbolData[marketData.Symbol] = symbolData
		}
		a.mu.Unlock()

		// Update price history and volume
		symbolData.priceHistory.PushBack(marketData)
		symbolData.volumeSum += marketData.Volume

		// Update SMA5 and SMA20
		symbolData.sma5.PushBack(marketData.Price)
		symbolData.sma20.PushBack(marketData.Price)

		// Remove old entries for SMA5 (keep last 5)
		for symbolData.sma5.Len() > 5 {
			symbolData.sma5.Remove(symbolData.sma5.Front())
		}

		// Remove old entries for SMA20 (keep last 20)
		for symbolData.sma20.Len() > 20 {
			symbolData.sma20.Remove(symbolData.sma20.Front())
		}

		// Calculate VWAP (simplified as cumulative volume-weighted price)
		// In a real system, you'd need tick data for proper VWAP calculation
		vwap := symbolData.priceSum / float64(symbolData.volumeSum)
		if symbolData.volumeSum > 0 {
			vwap = symbolData.priceSum / float64(symbolData.volumeSum)
		} else {
			vwap = marketData.Price
		}

		// Calculate SMA5 and SMA20
		sma5 := calculateSMA(symbolData.sma5)
		sma20 := calculateSMA(symbolData.sma20)

		// Create aggregate
		aggregate := Aggregate{
			Symbol:         marketData.Symbol,
			VWAP:           vwap,
			SMA5:           sma5,
			SMA20:          sma20,
			LastPrice:      marketData.Price,
			TotalVolume:    symbolData.volumeSum,
			LastUpdateTime: marketData.Time,
			ProcessingTime: time.Since(startTime).Milliseconds(),
		}

		// Broadcast to subscribers
		broadcastAggregate(aggregate)

		// Update symbol data with new values
		symbolData.priceSum += marketData.Price * float64(marketData.Volume)
	}
}

func calculateSMA(l *list.List) float64 {
	if l.Len() == 0 {
		return 0
	}

	sum := 0.0
	for e := l.Front(); e != nil; e = e.Next() {
		sum += e.Value.(float64)
	}
	return sum / float64(l.Len())
}

// handleWebSocket handles WebSocket connections
func handleWebSocket(w http.ResponseWriter, r *http.Request, aggregator *Aggregator) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Println("Upgrade error:", err)
		return
	}
	defer conn.Close()

	// Create subscriber
	subscriber := &Subscriber{
		conn:    conn,
		symbols: make(map[string]bool),
		send:    make(chan []byte, 256),
	}

	subscribersMutex.Lock()
	subscribers[subscriber] = true
	subscribersMutex.Unlock()

	// Read subscription requests
	go func() {
		defer close(subscriber.send)
		for {
			_, message, err := conn.ReadMessage()
			if err != nil {
				break
			}

			// Parse subscription request
			var req struct {
				Subscribe []string `json:"subscribe"`
				Unsubscribe []string `json:"unsubscribe"`
			}
			if err := json.Unmarshal(message, &req); err != nil {
				continue
			}

			// Update subscriptions
			for _, symbol := range req.Subscribe {
				subscriber.symbols[symbol] = true
			}
			for _, symbol := range req.Unsubscribe {
				delete(subscriber.symbols, symbol)
			}
		}
	}()

	// Send aggregates to subscriber
	for {
		select {
		case msg, ok := <-subscriber.send:
			if !ok {
				return
			}
			if err := conn.WriteMessage(websocket.TextMessage, msg); err != nil {
				return
			}
		}
	}
}

// broadcastAggregate sends aggregates to all subscribers interested in the symbol
func broadcastAggregate(agg Aggregate) {
	subscribersMutex.Lock()
	defer subscribersMutex.Unlock()

	// Convert to JSON
	data, err := json.Marshal(agg)
	if err != nil {
		log.Println("Error marshaling aggregate:", err)
		return
	}

	// Send to all subscribers who are interested in this symbol
	for sub := range subscribers {
		sub.mu.Lock()
		if sub.closed {
			sub.mu.Unlock()
			continue
		}

		if _, ok := sub.symbols[agg.Symbol]; ok || len(sub.symbols) == 0 {
			select {
			case sub.send <- data:
			default:
				// Channel full, close connection
				sub.closed = true
				go func(s *Subscriber) {
					s.conn.Close()
				}(sub)
			}
		}
		sub.mu.Unlock()
	}
}
