# Real-Time Market Data Processor in Rust

```rust
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::Instant;
use tokio::sync::broadcast;
use tokio::time::{interval, Duration};
use rand::seq::SliceRandom;
use rand::Rng;

#[derive(Debug, Clone)]
struct MarketData {
    symbol: String,
    price: f64,
    quantity: f64,
    timestamp: Instant,
}

#[derive(Debug, Clone)]
struct AggregatedData {
    symbol: String,
    vwap: f64,
    sma: f64,
    volume: f64,
    timestamp: Instant,
}

struct SymbolState {
    total_price_quantity: f64,
    total_quantity: f64,
    prices: Vec<f64>,
    window_size: usize,
}

struct MarketDataProcessor {
    sender: broadcast::Sender<AggregatedData>,
    state: Arc<Mutex<HashMap<String, SymbolState>>>,
}

impl MarketDataProcessor {
    fn new(window_size: usize) -> Self {
        let (sender, _) = broadcast::channel(100);
        let state = Arc::new(Mutex::new(HashMap::new()));
        MarketDataProcessor { sender, state }
    }

    fn process(&self, data: MarketData) {
        let mut state = self.state.lock().unwrap();
        let symbol = data.symbol.clone();

        let entry = state.entry(symbol.clone()).or_insert_with(|| {
            SymbolState {
                total_price_quantity: 0.0,
                total_quantity: 0.0,
                prices: Vec::with_capacity(window_size),
                window_size,
            }
        });

        // Update VWAP components
        entry.total_price_quantity += data.price * data.quantity;
        entry.total_quantity += data.quantity;

        // Update SMA
        entry.prices.push(data.price);
        if entry.prices.len() > entry.window_size {
            entry.prices.remove(0);
        }

        // Compute aggregates
        let vwap = if entry.total_quantity > 0.0 {
            entry.total_price_quantity / entry.total_quantity
        } else {
            0.0
        };

        let sma = if !entry.prices.is_empty() {
            entry.prices.iter().sum::<f64>() / entry.prices.len() as f64
        } else {
            0.0
        };

        let aggregated = AggregatedData {
            symbol: symbol.clone(),
            vwap,
            sma,
            volume: entry.total_quantity,
            timestamp: data.timestamp,
        };

        // Broadcast to all subscribers
        let _ = self.sender.send(aggregated);
    }
}

async fn generate_market_data(processor: Arc<MarketDataProcessor>, symbols: Vec<String>) {
    let mut rng = rand::thread_rng();
    let mut interval = interval(Duration::from_millis(50)); // 50ms between ticks

    loop {
        interval.tick().await;
        let symbol = symbols.choose(&mut rng).unwrap().clone();
        let price = 100.0 + rng.gen_range(-5.0..5.0);
        let quantity = 1.0 + rng.gen_range(0.0..10.0);

        let data = MarketData {
            symbol,
            price,
            quantity,
            timestamp: Instant::now(),
        };

        processor.process(data);
    }
}

async fn subscribe(processor: Arc<MarketDataProcessor>, symbol: String) {
    let mut receiver = processor.sender.subscribe();
    println!("[{}] Subscribed to {}", Instant::now().elapsed().as_secs(), symbol);

    while let Ok(data) = receiver.recv().await {
        if data.symbol == symbol {
            println!("[{}] {}: VWAP={:.2}, SMA={:.2}, Volume={:.2}",
                     Instant::now().elapsed().as_secs(),
                     data.symbol,
                     data.vwap,
                     data.sma,
                     data.volume);
        }
    }
}

#[tokio::main]
async fn main() {
    let symbols = vec![
        "AAPL".to_string(),
        "GOOGL".to_string(),
        "MSFT".to_string(),
        "AMZN".to_string(),
        "TSLA".to_string(),
    ];
    let window_size = 10; // SMA window size in ticks

    println!("Starting market data processor...");
    println!("Subscribers will receive updates for all symbols");

    let processor = Arc::new(MarketDataProcessor::new(window_size));

    // Start market data generator
    let data_gen = generate_market_data(Arc::clone(&processor), symbols.clone());

    // Start subscribers for each symbol
    let mut subscriber_handles = vec![];
    for symbol in symbols {
        let processor_clone = Arc::clone(&processor);
        let handle = tokio::spawn(async move {
            subscribe(processor_clone, symbol).await;
        });
        subscriber_handles.push(handle);
    }

    // Run both the data generator and subscribers
    tokio::select! {
        _ = data_gen => {},
        _ = tokio::signal::ctrl_c() => {
            println!("\nShutting down...");
        }
    }

    // Wait for subscribers to finish
    for handle in subscriber_handles {
        handle.abort();
    }
}
