    Ok(ws.on_upgrade(move |socket| {
        handle_connection(socket, aggregator)
    }))
}

async fn handle_connection(ws: warp::ws::WebSocket, aggregator: Arc<Mutex<Aggregator>>) {
    let (mut tx, mut rx) = ws.split();

    // Spawn a task to send aggregates to the client
    let aggregator_clone = aggregator.clone();
    tokio::spawn(async move {
        let mut interval = tokio::time::interval(std::time::Duration::from_millis(100));
        loop {
            interval.tick().await;
            let mut agg = aggregator_clone.lock().await;
            if let Some(aggregate) = agg.compute_aggregates() {
                if tx.send(warp::ws::Message::text(serde_json::to_string(&aggregate).unwrap())).await.is_err() {
                    break;
                }
            }
        }
    });

    // Spawn a task to receive messages from the client (if needed)
    // For now, we'll just ignore incoming messages
    while let Some(result) = rx.next().await {
        match result {
            Ok(_) => continue,
            Err(_) => break,
        }
    }
}

