impl MarketDataProcessor {
    fn new(window_size: usize) -> Self {
        let (sender, _) = broadcast::channel(100);
        let state = Arc::new(Mutex::new(HashMap::new()));
        MarketDataProcessor { sender, state }
    }

    fn process(&self, data: MarketData) {
        let mut state = self.state.lock().unwrap();
        let symbol = data.symbol.clone();

        // Initialize state if not present
        let entry = state.entry(symbol.clone()).or_insert_with(|| {
            SymbolState {
                total_price_quantity: 0.0,
                total_quantity: 0.0,
                prices: Vec::with_capacity(window_size),
                window_size,
            }
        });

        // Update VWAP
        entry.total_price_quantity += data.price * data.quantity;
        entry.total_quantity += data.quantity;

        // Update SMA
        entry.prices.push(data.price);
        if entry.prices.len() > entry.window_size {
            entry.prices.remove(0);
        }

        // Compute aggregates
        let vwap = if entry.total_quantity > 0.0 {
            entry.total_price_quantity / entry.total_quantity
        } else {
            0.0
        };
        let sma = if !entry.prices.is_empty() {
            entry.prices.iter().sum::<f64>() / entry.prices.len() as f64
        } else {
            0.0
        };

        let aggregated = AggregatedData {
            symbol,
            vwap,
            sma,
            volume: entry.total_quantity,
            timestamp: data.timestamp,
        };

        // Send to subscribers
        let _ = self.sender.send(aggregated);
    }
}
