    // For VWAP calculation
    std::queue<std::pair<double, int>> vwap_window; // (price, size)
    double vwap_sum = 0.0;
    int vwap_volume = 0;
    size_t vwap_window_size = 100; // Number of trades to consider for VWAP

public:
    OrderBook(const std::string& sym) : symbol(sym) {}

    void update(const MarketDataMessage& msg) {
        std::unique_lock lock(mutex);

        if (msg.type == 'Q') { // Quote update
            // For simplicity, we'll treat quotes as order book updates
            // In a real system, you'd have bid/ask updates separately
            if (msg.price > 0 && msg.size > 0) {
                // This is a simplified approach - real order book would have separate bid/ask updates
                // Here we'll just add to both sides for demonstration
                bids[msg.price] = OrderBookLevel(msg.price, msg.size);
                asks[msg.price] = OrderBookLevel(msg.price, msg.size);
            }
        } else if (msg.type == 'T') { // Trade update
            // Update VWAP
            vwap_sum += msg.price * msg.size;
            vwap_volume += msg.size;
            vwap_window.push({msg.price, msg.size});

            if (vwap_window.size() > vwap_window_size) {
                auto oldest = vwap_window.front();
                vwap_window.pop();
                vwap_sum -= oldest.first * oldest.second;
                vwap_volume -= oldest.second;
            }
        }

        // Clean up old levels (optional)
        auto now = std::chrono::system_clock::now();
        auto bid_it = bids.begin();
        while (bid_it != bids.end()) {
            if (std::chrono::duration_cast<std::chrono::seconds>(now - bid_it->second.timestamp).count() > 30) {
                bid_it = bids.erase(bid_it);
            } else {
                ++bid_it;
            }
        }

        auto ask_it = asks.begin();
        while (ask_it != asks.end()) {
            if (std::chrono::duration_cast<std::chrono::seconds>(now - ask_it->second.timestamp).count() > 30) {
                ask_it = asks.erase(ask_it);
            } else {
                ++ask_it;
            }
        }
    }

    json get_aggregates() const {
        std::shared_lock lock(mutex);

        json aggregates;
        aggregates["symbol"] = symbol;
        aggregates["timestamp"] = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());

        // Best bid/ask
        if (!bids.empty()) {
            aggregates["best_bid"] = bids.begin()->second.price;
            aggregates["best_bid_size"] = bids.begin()->second.size;
        } else {
            aggregates["best_bid"] = nullptr;
            aggregates["best_bid_size"] = nullptr;
        }

        if (!asks.empty()) {
            aggregates["best_ask"] = asks.begin()->first;
            aggregates["best_ask_size"] = asks.begin()->second.size;
        } else {
            aggregates["best_ask"] = nullptr;
            aggregates["best_ask_size"] = nullptr;
        }

        // Spread
        if (!bids.empty() && !asks.empty()) {
            aggregates["spread"] = asks.begin()->first - bids.begin()->second.price;
        } else {
            aggregates["spread"] = nullptr;
        }

        // VWAP
        if (vwap_volume > 0) {
            aggregates["vwap"] = vwap_sum / vwap_volume;
        } else {
            aggregates["vwap"] = nullptr;
        }

        // Order book depth (top 5 levels)
        json bids_array = json::array();
        int count = 0;
        for (const auto& [price, level] : bids) {
            if (count++ >= 5) break;
            bids_array.push_back({{"price", price}, {"size", level.size}});
        }
        aggregates["bids"] = bids_array;

        json asks_array = json::array();
        count = 0;
        for (const auto& [price, level] : asks) {
            if (count++ >= 5) break;
            asks_array.push_back({{"price", price}, {"size", level.size}});
        }
        aggregates["asks"] = asks_array;

        return aggregates;
    }
};

// WebSocket Session for a single subscriber
class WebSocketSession : public std::enable_shared_from_this<WebSocketSession> {
    websocket::stream<tcp::socket> ws_;
    std::shared_ptr<OrderBook> order_book_;
    beast::flat_buffer buffer_;

public:
    WebSocketSession(tcp::socket socket, std::shared_ptr<OrderBook> ob)
        : ws_(std::move(socket)), order_book_(ob) {}

    void run() {
        ws_.async_accept(
            beast::bind_front_handler(&WebSocketSession::on_accept, shared_from_this()));
    }

    void on_accept(beast::error_code ec) {
        if (ec) {
            std::cerr << "WebSocket accept error: " << ec.message() << std::endl;
            return;
        }
        do_read();
    }

    void do_read() {
        ws_.async_read(
            buffer_,
            beast::bind_front_handler(&WebSocketSession::on_read, shared_from_this()));
    }

    void on_read(beast::error_code ec, std::size_t bytes_transferred) {
        boost::ignore_unused(bytes_transferred);

        if (ec == websocket::error::closed) {
            return;
        }

        if (ec) {
            std::cerr << "WebSocket read error: " << ec.message() << std::endl;
            return;
        }

        // In a real system, you might process incoming messages here
        // For this example, we just echo back the aggregates periodically

        do_read();
    }

    void send_aggregates(const json& aggregates) {
        std::string message = aggregates.dump();
        ws_.async_write(
            net::buffer(message),
            beast::bind_front_handler(&WebSocketSession::on_write, shared_from_this()));
    }

    void on_write(beast::error_code ec, std::size_t bytes_transferred) {
        boost::ignore_unused(bytes_transferred);

        if (ec) {
            std::cerr << "WebSocket write error: " << ec.message() << std::endl;
            return;
        }
    }
};

// WebSocket Server to handle multiple subscribers
class WebSocketServer {
    net::io_context& ioc_;
    tcp::acceptor acceptor_;
    std::shared_ptr<OrderBook> order_book_;
    std::vector<std::shared_ptr<WebSocketSession>> sessions_;

public:
    WebSocketServer(net::io_context& ioc, short port, std::shared_ptr<OrderBook> ob)
        : ioc_(ioc), acceptor_(ioc, {tcp::v4(), port}), order_book_(ob) {
        do_accept();
    }

    void do_accept() {
        acceptor_.async_accept(
            net::make_strand(ioc_),
            beast::bind_front_handler(&WebSocketServer::on_accept, this));
    }

    void on_accept(beast::error_code ec, tcp::socket socket) {
        if (ec) {
            std::cerr << "Accept error: " << ec.message() << std::endl;
            return;
        }

        auto session = std::make_shared<WebSocketSession>(std::move(socket), order_book_);
        sessions_.push_back(session);
        session->run();

        do_accept();
    }

    void broadcast(const json& message) {
        for (auto& session : sessions_) {
            session->send_aggregates(message);
        }
    }
};

// Market Data Simulator
class MarketDataSimulator {
    std::shared_ptr<OrderBook> order_book_;
    std::atomic<bool> running_{true};
    std::thread thread_;
    std::vector<std::string> symbols_ = {"AAPL", "MSFT", "GOOG", "AMZN", "TSLA"};
    std::random_device rd_;
    std::mt19937 gen_;
    std::uniform_real_distribution<> price_dist_;
    std::uniform_int_distribution<> size_dist_;
    std::uniform_int_distribution<> symbol_dist_;

public:
    MarketDataSimulator(std::shared_ptr<OrderBook> ob)
        : order_book_(ob), gen_(rd_()),
          price_dist_(90.0, 200.0), size_dist_(1, 1000), symbol_dist_(0, symbols_.size() - 1) {
        thread_ = std::thread(&MarketDataSimulator::run, this);
    }

    ~MarketDataSimulator() {
        running_ = false;
        if (thread_.joinable()) {
            thread_.join();
        }
    }

    void run() {
        while (running_) {
            // Simulate market data updates
            std::string symbol = symbols_[symbol_dist_(gen_)];
            char type = (std::uniform_int_distribution<>(0, 1)(gen_) == 0) ? 'Q' : 'T';
            double price = price_dist_(gen_);
            int size = size_dist_(gen_);

            MarketDataMessage msg(symbol, type, price, size);
            order_book_->update(msg);

            // Sleep for a random interval (simulate real-time data)
            std::this_thread::sleep_for(std::chrono::milliseconds(10 + std::uniform_int_distribution<>(0, 50)(gen_)));
        }
    }
};

int main() {
    try {
        // Create order book for a symbol
        auto order_book = std::make_shared<OrderBook>("AAPL");

        // Set up WebSocket server on port 8080
        net::io_context ioc;
        WebSocketServer server(ioc, 8080, order_book);

        // Start market data simulator
        MarketDataSimulator simulator(order_book);

        // Main loop - periodically broadcast aggregates
        while (true) {
            std::this_thread::sleep_for(std::chrono::milliseconds(500));
            json aggregates = order_book->get_aggregates();
            server.broadcast(aggregates);

            std::cout << "Broadcasting aggregates: " << aggregates.dump(2) << std::endl;
        }

        // Note: In a real application, you'd have proper shutdown handling
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
