Here's a complete initial implementation in **Go** (chosen for its balance of performance and simplicity for prototyping). This demonstrates a real-time market data processor with price aggregation and WebSocket streaming:

```go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"math/rand"
	"net/http"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

// MarketData represents a single market data tick
type MarketData struct {
	Symbol    string  `json:"symbol"`
	Price     float64 `json:"price"`
	Size      int     `json:"size"`
	Timestamp int64   `json:"timestamp"`
}

// Aggregate represents computed statistics for a symbol
type Aggregate struct {
	Symbol      string  `json:"symbol"`
	LastPrice   float64 `json:"last_price"`
	Volume      int     `json:"volume"`
	VWAP        float64 `json:"vwap"`
	BidPrice    float64 `json:"bid_price"`
	AskPrice    float64 `json:"ask_price"`
	Timestamp   int64   `json:"timestamp"`
}

// Subscriber represents a client subscribed to updates
type Subscriber struct {
	conn *websocket.Conn
	send chan []byte
}

// MarketDataProcessor handles the core processing
type MarketDataProcessor struct {
	aggregates map[string]*Aggregate
	subscribers map[*Subscriber]bool
	mu         sync.RWMutex
	newSubs    chan *Subscriber
	delSubs    chan *Subscriber
	dataChan   chan MarketData
	stopChan   chan struct{}
}

// NewMarketDataProcessor creates a new processor instance
func NewMarketDataProcessor() *MarketDataProcessor {
	return &MarketDataProcessor{
		aggregates:  make(map[string]*Aggregate),
		subscribers: make(map[*Subscriber]bool),
		newSubs:     make(chan *Subscriber),
		delSubs:     make(chan *Subscriber),
		dataChan:    make(chan MarketData, 1000),
		stopChan:    make(chan struct{}),
	}
}

// Start begins processing market data
func (mdp *MarketDataProcessor) Start() {
	go mdp.run()
}

// Stop shuts down the processor
func (mdp *MarketDataProcessor) Stop() {
	close(mdp.stopChan)
}

// run is the main processing loop
func (mdp *MarketDataProcessor) run() {
	ticker := time.NewTicker(5 * time.Second)
	defer ticker.Stop()

	for {
		select {
		case <-mdp.stopChan:
			mdp.broadcastAggregates()
			return

		case sub := <-mdp.newSubs:
			mdp.mu.Lock()
			mdp.subscribers[sub] = true
			mdp.mu.Unlock()
			// Send current aggregates to new subscriber
			mdp.sendCurrentAggregates(sub)

		case sub := <-mdp.delSubs:
			mdp.mu.Lock()
			if _, ok := mdp.subscribers[sub]; ok {
				close(sub.send)
				delete(mdp.subscribers, sub)
			}
			mdp.mu.Unlock()

		case data := <-mdp.dataChan:
			mdp.processMarketData(data)
			mdp.broadcastAggregates()

		case <-ticker.C:
			// Periodic update even without new data
			mdp.broadcastAggregates()
		}
	}
}

// processMarketData updates aggregates with new tick
func (mdp *MarketDataProcessor) processMarketData(data MarketData) {
	mdp.mu.Lock()
	defer mdp.mu.Unlock()

	agg, exists := mdp.aggregates[data.Symbol]
	if !exists {
		agg = &Aggregate{
			Symbol:    data.Symbol,
			Timestamp: time.Now().Unix(),
		}
		mdp.aggregates[data.Symbol] = agg
	}

	// Update aggregate statistics
	agg.LastPrice = data.Price
	agg.Volume += data.Size
	agg.VWAP = (agg.VWAP*float64(agg.Volume-data.Size) + data.Price*float64(data.Size)) / float64(agg.Volume)
	agg.Timestamp = time.Now().Unix()

	// Simulate bid/ask updates (in real system these would come from order book)
	agg.BidPrice = data.Price * 0.999
	agg.AskPrice = data.Price * 1.001
}

// broadcastAggregates sends current aggregates to all subscribers
func (mdp *MarketDataProcessor) broadcastAggregates() {
	mdp.mu.RLock()
	aggregates := make([]*Aggregate, 0, len(mdp.aggregates))
	for _, agg := range mdp.aggregates {
		aggregates = append(aggregates, agg)
	}
	mdp.mu.RUnlock()

	data, err := json.Marshal(aggregates)
	if err != nil {
		log.Printf("Error marshaling aggregates: %v", err)
		return
	}

	mdp.mu.RLock()
	for sub := range mdp.subscribers {
		select {
		case sub.send <- data:
		default:
			// Subscriber is slow, mark for removal
			go func(s *Subscriber) {
				mdp.delSubs <- s
			}(sub)
		}
	}
	mdp.mu.RUnlock()
}

// sendCurrentAggregates sends all current aggregates to a new subscriber
func (mdp *MarketDataProcessor) sendCurrentAggregates(sub *Subscriber) {
	mdp.mu.RLock()
	aggregates := make([]*Aggregate, 0, len(mdp.aggregates))
	for _, agg := range mdp.aggregates {
		aggregates = append(aggregates, agg)
	}
	mdp.mu.RUnlock()

	data, err := json.Marshal(aggregates)
	if err != nil {
		log.Printf("Error marshaling aggregates: %v", err)
		return
	}

	sub.send <- data
}

// handleWebSocket handles WebSocket connections
func (mdp *MarketDataProcessor) handleWebSocket(w http.ResponseWriter, r *http.Request) {
	upgrader := websocket.Upgrader{
		CheckOrigin: func(r *http.Request) bool {
			return true // Allow all origins for demo
		},
	}

	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("WebSocket upgrade failed: %v", err)
		return
	}

	sub := &Subscriber{
		conn: conn,
		send: make(chan []byte, 256),
	}

	mdp.newSubs <- sub
	defer func() {
		mdp.delSubs <- sub
	}()

	go mdp.writePump(sub)
	mdp.readPump(sub)
}

// readPump handles incoming messages from subscriber
func (mdp *MarketDataProcessor) readPump(sub *Subscriber) {
	defer func() {
		mdp.delSubs <- sub
	}()

	for {
		_, _, err := sub.conn.ReadMessage()
		if err != nil {
			if websocket.IsUnexpectedCloseError(err, websocket.CloseGoingAway, websocket.CloseAbnormalClosure) {
				log.Printf("WebSocket read error: %v", err)
			}
			break
		}
	}
}

// writePump handles outgoing messages to subscriber
func (mdp *MarketDataProcessor) writePump(sub *Subscriber) {
	defer func() {
		sub.conn.Close()
	}()

	for {
		select {
		case message, ok := <-sub.send:
			if !ok {
				// Channel closed
				sub.conn.WriteMessage(websocket.CloseMessage, []byte{})
				return
			}

			w, err := sub.conn.NextWriter(websocket.TextMessage)
			if err != nil {
				return
			}
			w.Write(message)

			if err := w.Close(); err != nil {
				return
			}
		}
	}
}

// SimulateMarketData generates random market data for testing
func SimulateMarketData(mdp *MarketDataProcessor, symbol string) {
	rand.Seed(time.Now().UnixNano())
	price := 100.0
	direction := 1.0

	for {
		select {
		case <-mdp.stopChan:
			return
		default:
			// Simulate price movement
			priceChange := rand.Float64() * 0.5 * direction
			price += priceChange
			if price < 90 {
				direction = 1.0
			} else if price > 110 {
				direction = -1.0
			}

			// Create market data tick
			tick := MarketData{
				Symbol:    symbol,
				Price:     price,
				Size:      rand.Intn(100) + 1,
				Timestamp: time.Now().UnixNano(),
			}

			mdp.dataChan <- tick
			time.Sleep(100 * time.Millisecond) // Simulate market data rate
		}
	}
}

func main() {
	processor := NewMarketDataProcessor()
	processor.Start()
	defer processor.Stop()

	// Start market data simulator
