# Real-Time Market Data Processor in Go

Here's a complete implementation of a real-time market data processor that computes price aggregates (VWAP and moving averages) and streams results to subscribers via WebSocket:

```go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"math/rand"
	"net/http"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

// MarketData represents a single market data update
type MarketData struct {
	Symbol    string    `json:"symbol"`
	Price     float64   `json:"price"`
	Volume    int64     `json:"volume"`
	Timestamp time.Time `json:"timestamp"`
}

// Aggregate represents computed aggregates for a symbol
type Aggregate struct {
	Symbol       string    `json:"symbol"`
	VWAP         float64   `json:"vwap"`
	MovingAvg20  float64   `json:"moving_avg_20"`
	LastUpdate   time.Time `json:"last_update"`
	TradeCount   int64     `json:"trade_count"`
	TotalVolume  int64     `json:"total_volume"`
	LastPrice    float64   `json:"last_price"`
}

// Aggregator maintains state and computes aggregates
type Aggregator struct {
	mu          sync.RWMutex
	aggregates  map[string]*Aggregate
	windowSize  int
	priceWindow map[string][]float64
}

// NewAggregator creates a new aggregator
func NewAggregator(windowSize int) *Aggregator {
	return &Aggregator{
		aggregates:  make(map[string]*Aggregate),
		windowSize:  windowSize,
		priceWindow: make(map[string][]float64),
	}
}

// ProcessMarketData updates aggregates with new market data
func (a *Aggregator) ProcessMarketData(data MarketData) {
	a.mu.Lock()
	defer a.mu.Unlock()

	// Initialize if new symbol
	if _, exists := a.aggregates[data.Symbol]; !exists {
		a.aggregates[data.Symbol] = &Aggregate{
			Symbol:      data.Symbol,
			VWAP:        0,
			MovingAvg20: 0,
			LastUpdate:  data.Timestamp,
			TradeCount:  0,
			TotalVolume: 0,
			LastPrice:   0,
		}
	}

	agg := a.aggregates[data.Symbol]

	// Update basic aggregates
	agg.LastUpdate = data.Timestamp
	agg.TradeCount++
	agg.TotalVolume += data.Volume
	agg.LastPrice = data.Price

	// Calculate VWAP (Volume Weighted Average Price)
	// VWAP = (Σ(Price * Volume)) / ΣVolume
	agg.VWAP = ((agg.VWAP * float64(agg.TotalVolume-data.Volume)) + (data.Price * float64(data.Volume))) / float64(agg.TotalVolume)

	// Update moving average window
	window := a.priceWindow[data.Symbol]
	window = append(window, data.Price)
	if len(window) > a.windowSize {
		window = window[1:]
	}
	a.priceWindow[data.Symbol] = window

	// Calculate moving average (simple moving average)
	if len(window) > 0 {
		sum := 0.0
		for _, p := range window {
			sum += p
		}
		agg.MovingAvg20 = sum / float64(len(window))
	}

	// Update in map
	a.aggregates[data.Symbol] = agg
}

// GetAggregate returns the current aggregate for a symbol
func (a *Aggregator) GetAggregate(symbol string) *Aggregate {
	a.mu.RLock()
	defer a.mu.RUnlock()
	if agg, exists := a.aggregates[symbol]; exists {
		return agg
	}
	return nil
}

// GetAllAggregates returns all current aggregates
func (a *Aggregator) GetAllAggregates() map[string]*Aggregate {
	a.mu.RLock()
	defer a.mu.RUnlock()
	copy := make(map[string]*Aggregate)
	for k, v := range a.aggregates {
		copy[k] = v
	}
	return copy
}

// WebSocketServer handles client subscriptions
type WebSocketServer struct {
	aggregator *Aggregator
	upgrader   websocket.Upgrader
	clients    map[*websocket.Conn]bool
	broadcast  chan *Aggregate
	mu         sync.Mutex
}

// NewWebSocketServer creates a new WebSocket server
func NewWebSocketServer(aggregator *Aggregator) *WebSocketServer {
	return &WebSocketServer{
		aggregator: aggregator,
		upgrader: websocket.Upgrader{
			CheckOrigin: func(r *http.Request) bool {
				return true // Allow all origins (for development only)
			},
		},
		clients:   make(map[*websocket.Conn]bool),
		broadcast: make(chan *Aggregate, 100),
	}
}

// handleWebSocket handles WebSocket connections
func (s *WebSocketServer) handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := s.upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Println("WebSocket upgrade failed:", err)
		return
	}
	defer conn.Close()

	// Register new client
	s.mu.Lock()
	s.clients[conn] = true
	s.mu.Unlock()

	// Send current aggregates to new client
	aggregates := s.aggregator.GetAllAggregates()
	for _, agg := range aggregates {
		if err := conn.WriteJSON(agg); err != nil {
			log.Println("Error sending initial data:", err)
			return
		}
	}

	// Start a goroutine to send updates to this client
	go func() {
		for {
			select {
			case agg := <-s.broadcast:
				if err := conn.WriteJSON(agg); err != nil {
					log.Println("Error sending update:", err)
					return
				}
			}
		}
	}()

	// Keep connection alive
	for {
		_, _, err := conn.ReadMessage()
		if err != nil {
			log.Println("WebSocket read error:", err)
			break
		}
	}
}

// broadcastUpdates sends updates to all clients
func (s *WebSocketServer) broadcastUpdates() {
	ticker := time.NewTicker(100 * time.Millisecond) // Adjust based on performance needs
	defer ticker.Stop()

	for range ticker.C {
		aggregates := s.aggregator.GetAllAggregates()
		for _, agg := range aggregates {
			s.broadcast <- agg
		}
	}
}

// MarketDataGenerator simulates a market data feed
type MarketDataGenerator struct {
	aggregator *Aggregator
	symbols    []string
	stop       chan struct{}
}

// NewMarketDataGenerator creates a new market data generator
func NewMarketDataGenerator(aggregator *Aggregator, symbols []string) *MarketDataGenerator {
	return &MarketDataGenerator{
		aggregator: aggregator,
		symbols:    symbols,
		stop:       make(chan struct{}),
	}
}

// Start begins generating market data
func (g *MarketDataGenerator) Start() {
	go func() {
