struct MarketData {
    std::string instrument_id;
    double price;
    double volume;
    std::chrono::system_clock::time_point timestamp;

    MarketData(const std::string& id, double p, double v)
        : instrument_id(id), price(p), volume(v),
          timestamp(std::chrono::system_clock::now()) {}
};

// ======================
// Aggregator Component
// ======================

class Aggregator {
public:
    void add_market_data(const MarketData& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto& state = vwap_states_[data.instrument_id];
        state.sum_price_volume += data.price * data.volume;
        state.total_volume += data.volume;
    }

    double get_vwap(const std::string& instrument_id) const {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = vwap_states_.find(instrument_id);
        if (it == vwap_states_.end() || it->second.total_volume == 0) {
            return 0.0;
        }
        return it->second.sum_price_volume / it->second.total_volume;
    }

private:
    struct VwapState {
        double sum_price_volume = 0.0;
        double total_volume = 0.0;
    };

    std::unordered_map<std::string, VwapState> vwap_states_;
    mutable std::mutex mutex_;
};

