public:
    void add_subscriber(std::shared_ptr<Subscriber> subscriber) {
        std::lock_guard<std::mutex> lock(subscribers_mutex_);
        subscribers_.push_back(subscriber);
    }

    void ingest_market_data(const MarketData& data) {
        aggregator_.add_market_data(data);
        double vwap = aggregator_.get_vwap(data.instrument_id);
        notify_subscribers(data.instrument_id, vwap);
    }

private:
    void notify_subscribers(const std::string& instrument_id, double vwap) {
        std::vector<std::shared_ptr<Subscriber>> subscribers_copy;
        {
            std::lock_guard<std::mutex> lock(subscribers_mutex_);
            subscribers_copy = subscribers_;
        }
        for (auto& sub : subscribers_copy) {
            sub->on_aggregate_update(instrument_id, vwap);
        }
    }

    Aggregator aggregator_;
    std::vector<std::shared_ptr<Subscriber>> subscribers_;
    std::mutex subscribers_mutex_;
};

