// Trade data structure
struct Trade {
    std::string symbol;
    double price;
    int size;
    std::chrono::system_clock::time_point timestamp;
};

// Aggregate data structure
struct Aggregate {
    std::string symbol;
    double latest_price = 0.0;
    double vwap = 0.0;
    int total_volume = 0;
    double total_value = 0.0;
    std::chrono::system_clock::time_point last_update;
};

// Subscriber class to handle client connections
class Subscriber : public std::enable_shared_from_this<Subscriber> {
public:
    Subscriber(tcp::socket socket) : socket_(std::move(socket)) {}

    void start() {
        // Start by sending a welcome message
        std::string welcome = "Welcome to Market Data Processor!\n";
        send(welcome);
    }

    void send(const std::string& message) {
        auto self(shared_from_this());
        boost::asio::async_write(socket_, boost::asio::buffer(message),
            [this, self](boost::system::error_code ec, std::size_t /*length*/) {
                if (ec) {
                    std::cerr << "Error sending to subscriber: " << ec.message() << std::endl;
                }
            });
    }

private:
    tcp::socket socket_;
};

// Market Data Processor core
class MarketDataProcessor {
public:
    void add_trade(const Trade& trade) {
        std::lock_guard<std::mutex> lock(mutex_);

        auto& agg = aggregates_[trade.symbol];
        agg.symbol = trade.symbol;
        agg.latest_price = trade.price;
        agg.total_volume += trade.size;
        agg.total_value += trade.price * trade.size;
        agg.vwap = agg.total_volume > 0 ? agg.total_value / agg.total_volume : 0.0;
        agg.last_update = trade.timestamp;

        // Broadcast the updated aggregate
        broadcast_aggregates_locked();
    }

    void add_subscriber(std::shared_ptr<Subscriber> subscriber) {
        std::lock_guard<std::mutex> lock(mutex_);
        subscribers_.push_back(subscriber);
    }

    void remove_subscriber(std::shared_ptr<Subscriber> subscriber) {
        std::lock_guard<std::mutex> lock(mutex_);
        subscribers_.erase(
            std::remove(subscribers_.begin(), subscribers_.end(), subscriber),
            subscribers_.end()
        );
    }

private:
    void broadcast_aggregates_locked() {
        for (auto& agg_pair : aggregates_) {
            const Aggregate& agg = agg_pair.second;
            std::string message = serialize_aggregate(agg) + "\n";
            for (auto& sub : subscribers_) {
                sub->send(message);
            }
        }
    }

    std::string serialize_aggregate(const Aggregate& agg) {
        // Simple JSON serialization for demonstration
        auto now = std::chrono::system_clock::now();
        auto duration = now.time_since_epoch();
        auto millis = std::chrono::duration_cast<std::chrono::milliseconds>(duration).count();

        std::ostringstream oss;
        oss << "{"
            << "\"type\":\"aggregate\","
            << "\"symbol\":\"" << agg.symbol << "\","
            << "\"latest_price\":" << std::fixed << std::setprecision(2) << agg.latest_price << ","
            << "\"vwap\":" << std::fixed << std::setprecision(2) << agg.vwap << ","
            << "\"total_volume\":" << agg.total_volume << ","
            << "\"timestamp\":" << millis
            << "}";
        return oss.str();
    }

    std::unordered_map<std::string, Aggregate> aggregates_;
    std::vector<std::shared_ptr<Subscriber>> subscribers_;
    std::mutex mutex_;
};

