// Server to handle client connections
class Server {
public:
    Server(boost::asio::io_context& io_context, short port, MarketDataProcessor& processor)
        : io_context_(io_context),
          acceptor_(io_context, tcp::endpoint(tcp::v4(), port)),
          processor_(processor) {
        do_accept();
    }

private:
    void do_accept() {
        acceptor_.async_accept(
            [this](boost::system::error_code ec, tcp::socket socket) {
                if (!ec) {
                    auto subscriber = std::make_shared<Subscriber>(std::move(socket));
                    subscriber->start();
                    processor_.add_subscriber(subscriber);
                }
                do_accept();
            });
    }

    boost::asio::io_context& io_context_;
    tcp::acceptor acceptor_;
    MarketDataProcessor& processor_;
};

