### **Market Data Processor (Go)**
```go
package main

import (
	"encoding/json"
	"log"
	"math/rand"
	"net/http"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

// MarketData represents a price update from an exchange
type MarketData struct {
	Symbol   string  `json:"symbol"`
	Price    float64 `json:"price"`
	Volume   int64   `json:"volume"`
	Exchange string  `json:"exchange"`
	Timestamp int64  `json:"timestamp"`
}

// Aggregate holds computed statistics for a symbol
type Aggregate struct {
	Symbol      string  `json:"symbol"`
	LastPrice   float64 `json:"lastPrice"`
	VWAP        float64 `json:"vwap"`      // Volume-Weighted Average Price
	TotalVolume int64   `json:"totalVolume"`
	Count       int64   `json:"count"`
}

// MarketDataProcessor maintains state and computes aggregates
type MarketDataProcessor struct {
	mu         sync.RWMutex
	aggregates map[string]*Aggregate
	subscribers map[*websocket.Conn]bool
	updates    chan MarketData
}

// NewMarketDataProcessor initializes the processor
func NewMarketDataProcessor() *MarketDataProcessor {
	return &MarketDataProcessor{
		aggregates:  make(map[string]*Aggregate),
		subscribers: make(map[*websocket.Conn]bool),
		updates:     make(chan MarketData, 1000),
	}
}

// Update processes a new market data update
func (m *MarketDataProcessor) Update(data MarketData) {
	m.updates <- data
}

// Start begins processing updates and broadcasting aggregates
func (m *MarketDataProcessor) Start() {
	go m.processUpdates()
}

// processUpdates handles incoming market data and computes aggregates
func (m *MarketDataProcessor) processUpdates() {
	for data := range m.updates {
		m.mu.Lock()
		agg, exists := m.aggregates[data.Symbol]
		if !exists {
			agg = &Aggregate{Symbol: data.Symbol}
			m.aggregates[data.Symbol] = agg
		}

		// Update aggregate
		agg.LastPrice = data.Price
		agg.TotalVolume += data.Volume
		agg.Count++
		if agg.Count > 0 {
			agg.VWAP = (agg.VWAP*float64(agg.Count-1) + data.Price*float64(data.Volume)) / float64(agg.Count)
		}
		m.mu.Unlock()

		// Broadcast to all subscribers
		m.broadcastAggregate(agg)
	}
}

// broadcastAggregate sends the aggregate to all WebSocket subscribers
func (m *MarketDataProcessor) broadcastAggregate(agg *Aggregate) {
	m.mu.RLock()
	defer m.mu.RUnlock()

	msg, _ := json.Marshal(agg)
	for sub := range m.subscribers {
		err := sub.WriteMessage(websocket.TextMessage, msg)
		if err != nil {
			log.Printf("Error writing to subscriber: %v", err)
			sub.Close()
			delete(m.subscribers, sub)
		}
	}
}

// AddSubscriber registers a new WebSocket subscriber
func (m *MarketDataProcessor) AddSubscriber(conn *websocket.Conn) {
	m.mu.Lock()
	m.subscribers[conn] = true
	m.mu.Unlock()

	// Send current aggregates to new subscriber
	m.mu.RLock()
	for _, agg := range m.aggregates {
		msg, _ := json.Marshal(agg)
		conn.WriteMessage(websocket.TextMessage, msg)
	}
	m.mu.RUnlock()
}

// RemoveSubscriber unregisters a subscriber
func (m *MarketDataProcessor) RemoveSubscriber(conn *websocket.Conn) {
	m.mu.Lock()
	delete(m.subscribers, conn)
	m.mu.Unlock()
}

// WebSocket handler for subscribers
func (m *MarketDataProcessor) wsHandler(w http.ResponseWriter, r *http.Request) {
	upgrader := websocket.Upgrader{
		CheckOrigin: func(r *http.Request) bool { return true },
	}
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("WebSocket upgrade failed: %v", err)
		return
	}
	defer conn.Close()

	m.AddSubscriber(conn)
	defer m.RemoveSubscriber(conn)

	// Keep connection alive
	for {
		if _, _, err := conn.NextReader(); err != nil {
			break
		}
	}
}

// SimulateMarketData generates fake market data for testing
func SimulateMarketData(processor *MarketDataProcessor, symbols []string) {
	for {
		time.Sleep(100 * time.Millisecond) // Simulate real-time updates
		symbol := symbols[rand.Intn(len(symbols))]
		price := 100.0 + rand.Float64()*10.0
		volume := int64(rand.Intn(1000))
		processor.Update(MarketData{
			Symbol:    symbol,
			Price:     price,
			Volume:    volume,
			Exchange:  "EXCH_" + symbol,
			Timestamp: time.Now().UnixNano(),
		})
	}
}

func main() {
	processor := NewMarketDataProcessor()
	processor.Start()

	// Start market data simulator
	symbols := []string{"AAPL", "MSFT", "GOOGL", "AMZN", "TSLA"}
	go SimulateMarketData(processor, symbols)

	// Set up HTTP server with WebSocket endpoint
	http.HandleFunc("/ws", processor.wsHandler)
	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		http.ServeFile(w, r, "index.html")
	})

	log.Println("Server starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
