### **3. `src/aggregator.rs`**
```rust
use crate::market_data::OrderBook;
use serde::Serialize;

#[derive(Debug, Serialize)]
pub struct PriceAggregate {
    pub best_bid: Option<f64>,
    pub best_ask: Option<f64>,
    pub mid_price: Option<f64>,
    pub last_price: Option<f64>,
    pub vwap: f64,
    pub total_volume: f64,
}

pub struct Aggregator {
    order_book: OrderBook,
}

impl Aggregator {
    pub fn new() -> Self {
        Aggregator {
            order_book: OrderBook::new(),
        }
    }

    pub fn update_order_book(&mut self, order_book: OrderBook) {
        self.order_book = order_book;
    }

    pub fn compute_aggregates(&self) -> PriceAggregate {
        let best_bid = self.order_book.bids.keys().next().copied();
        let best_ask = self.order_book.asks.keys().next().copied();

        let mid_price = match (best_bid, best_ask) {
            (Some(bid), Some(ask)) => Some((bid + ask) / 2.0),
            _ => None,
        };

        PriceAggregate {
            best_bid,
            best_ask,
            mid_price,
            last_price: self.order_book.last_price,
            vwap: if self.order_book.total_volume > 0.0 {
                self.order_book.total_volume / self.order_book.total_volume
            } else {
                0.0
            },
            total_volume: self.order_book.total_volume,
        }
    }
}
