```rust
mod market_data;
mod aggregator;
mod streaming;

use aggregator::Aggregator;
use market_data::OrderBook;
use rand::Rng;
use std::time::Duration;
use tokio::sync::broadcast;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Create a broadcast channel for updates
    let (tx, _) = broadcast::channel(100);

    // Create aggregator
    let aggregator = Aggregator::new();

    // Start WebSocket server
    let ws_tx = tx.clone();
    tokio::spawn(async move {
        streaming::start_websocket_server("127.0.0.1:8080", ws_tx)
            .await
            .unwrap();
    });

    // Start market data simulator
    simulate_market_data(tx, aggregator).await;

    Ok(())
}

async fn simulate_market_data(
    tx: broadcast::Sender<String>,
    mut aggregator: Aggregator,
) {
    let mut rng = rand::thread_rng();
    let mut interval = tokio::time::interval(Duration::from_millis(100));

    loop {
        interval.tick().await;

        // Generate random market data
        let price = 100.0 + rng.gen_range(-5.0..5.0);
        let quantity = rng.gen_range(1.0..100.0);

        // Update order book
        let mut order_book = OrderBook::new();
        order_book.update_bid(price - 0.5, quantity);
        order_book.update_ask(price + 0.5, quantity);
        order_book.update_trade(price, quantity);

        // Update aggregator
        aggregator.update_order_book(order_book);

        // Compute aggregates
        let aggregates = aggregator.compute_aggregates();

        // Serialize and broadcast
        let json = serde_json::to_string(&aggregates).unwrap();
        tx.send(json).unwrap();
    }
}
```

