Here's a minimal working C++ implementation of a real-time market data processor that computes price aggregates and streams results to subscribers:

```cpp
#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>
#include <functional>
#include <mutex>
#include <thread>
#include <chrono>
#include <random>
#include <memory>
#include <atomic>

// ======================
// Market Data Structures
// ======================

struct Order {
    double price;
    int size;
    char side; // 'B' for bid, 'A' for ask
};

struct PriceAggregate {
    double best_bid;
    double best_ask;
    double vwap; // Volume Weighted Average Price
    int total_volume;
    std::string symbol;
};

// ======================
// Subscriber Interface
// ======================

class Subscriber {
public:
    virtual ~Subscriber() = default;
    virtual void onAggregateUpdate(const PriceAggregate& agg) = 0;
};

// ======================
// Order Book
// ======================

class OrderBook {
private:
    std::string symbol_;
    std::vector<Order> bids_;
    std::vector<Order> asks_;
    std::mutex mtx_;

public:
    explicit OrderBook(const std::string& symbol) : symbol_(symbol) {}

    void addOrder(const Order& order) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (order.side == 'B') {
            bids_.push_back(order);
        } else if (order.side == 'A') {
            asks_.push_back(order);
        }
    }

    PriceAggregate getAggregate() const {
        std::lock_guard<std::mutex> lock(mtx_);

        PriceAggregate agg;
        agg.symbol = symbol_;
        agg.total_volume = 0;

        // Find best bid (highest price)
        agg.best_bid = 0.0;
        for (const auto& order : bids_) {
            agg.total_volume += order.size;
            if (order.price > agg.best_bid) {
                agg.best_bid = order.price;
            }
        }

        // Find best ask (lowest price)
        agg.best_ask = 0.0;
        for (const auto& order : asks_) {
            agg.total_volume += order.size;
            if (agg.best_ask == 0.0 || order.price < agg.best_ask) {
                agg.best_ask = order.price;
            }
        }

        // Calculate VWAP (simplified: average of best bid/ask weighted by volume)
        if (agg.total_volume > 0 && agg.best_bid > 0 && agg.best_ask > 0) {
            agg.vwap = (agg.best_bid + agg.best_ask) / 2.0;
        } else {
            agg.vwap = 0.0;
        }

        return agg;
    }
};

// ======================
// Market Data Processor
// ======================

class MarketDataProcessor {
private:
    std::unordered_map<std::string, std::unique_ptr<OrderBook>> order_books_;
    std::vector<std::weak_ptr<Subscriber>> subscribers_;
    std::mutex subscribers_mtx_;
    std::atomic<bool> running_{true};

public:
    void addSymbol(const std::string& symbol) {
        std::lock_guard<std::mutex> lock(order_books_mtx_);
        if (order_books_.find(symbol) == order_books_.end()) {
            order_books_[symbol] = std::make_unique<OrderBook>(symbol);
        }
    }

    void addOrder(const std::string& symbol, const Order& order) {
        std::lock_guard<std::mutex> lock(order_books_mtx_);
        auto it = order_books_.find(symbol);
        if (it != order_books_.end()) {
            it->second->addOrder(order);
            notifySubscribers(symbol);
        }
    }

    void subscribe(const std::shared_ptr<Subscriber>& subscriber) {
        std::lock_guard<std::mutex> lock(subscribers_mtx_);
        subscribers_.emplace_back(subscriber);
    }

    void stop() {
        running_ = false;
    }

    void process() {
        while (running_) {
            // In a real system, this would process actual market data
            // Here we just simulate periodic updates
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }

private:
    std::mutex order_books_mtx_;

    void notifySubscribers(const std::string& symbol) {
        std::lock_guard<std::mutex> lock(order_books_mtx_);
        auto it = order_books_.find(symbol);
        if (it == order_books_.end()) return;

        PriceAggregate agg = it->second->getAggregate();

        std::lock_guard<std::mutex> sub_lock(subscribers_mtx_);
        for (auto it = subscribers_.begin(); it != subscribers_.end(); ) {
            if (auto subscriber = it->lock()) {
                subscriber->onAggregateUpdate(agg);
                ++it;
            } else {
                it = subscribers_.erase(it);
            }
        }
    }
};

// ======================
// Console Subscriber
// ======================

class ConsoleSubscriber : public Subscriber {
public:
    void onAggregateUpdate(const PriceAggregate& agg) override {
        std::cout << "[" << agg.symbol << "] "
                  << "Bid: " << agg.best_bid << " | "
                  << "Ask: " << agg.best_ask << " | "
                  << "VWAP: " << agg.vwap << " | "
                  << "Volume: " << agg.total_volume << std::endl;
    }
};

// ======================
// Simulated Market Data
// ======================

class MarketDataSimulator {
private:
    MarketDataProcessor& processor_;
    std::atomic<bool> running_{true};
    std::vector<std::string> symbols_ = {"AAPL", "MSFT", "GOOGL"};
    std::random_device rd_;
    std::mt19937 gen_{rd_()};
    std::uniform_real_distribution<> price_dist_{90.0, 200.0};
    std::uniform_int_distribution<> size_dist_{10, 1000};
    std::uniform_int_distribution<> side_dist_{0, 1};

public:
    explicit MarketDataSimulator(MarketDataProcessor& processor) : processor_(processor) {
        for (const auto& symbol : symbols_) {
            processor_.addSymbol(symbol);
        }
    }

    void start() {
        std::thread([this]() {
            while (running_) {
                for (const auto& symbol : symbols_) {
                    // Simulate random order
                    Order order;
                    order.price = price_dist_(gen_);
                    order.size = size_dist_(gen_);
                    order.side = (side_dist_(gen_) == 0) ? 'B' : 'A';

                    processor_.addOrder(symbol, order);
                }
                std::this_thread::sleep_for(std::chrono::milliseconds(50));
            }
        }).detach();
    }

    void stop() {
        running_ = false;
    }
};

// ======================
// Main Application
// ======================

int main() {
    MarketDataProcessor processor;
    ConsoleSubscriber subscriber;
    auto shared_subscriber = std::make_shared<ConsoleSubscriber>(subscriber);

    processor.subscribe(shared_subscriber);

    MarketDataSimulator simulator(processor);
    simulator.start();

    std::cout << "Market Data Processor Running. Press ENTER to stop..." << std::endl;
    std::cin.get();

    processor.stop();
    simulator.stop();

    return 0;
}
```

