#[derive(Debug, Clone, serde::Serialize)]
pub struct PriceAggregate {
    pub best_bid: Option<f64>,
    pub best_ask: Option<f64>,
    pub last_price: Option<f64>,
}

pub struct Aggregator {
    rx: mpsc::Receiver<MarketEvent>,
    tx: mpsc::Sender<PriceAggregate>,
    state: PriceAggregate,
}

impl Aggregator {
    pub fn new(rx: mpsc::Receiver<MarketEvent>, tx: mpsc::Sender<PriceAggregate>) -> Self {
        Self {
            rx,
            tx,
            state: PriceAggregate {
                best_bid: None,
                best_ask: None,
                last_price: None,
            },
        }
    }

    pub async fn run(mut self) {
        while let Some(event) = self.rx.recv().await {
            match event {
                MarketEvent::Trade { price, .. } => {
                    self.state.last_price = Some(price);
                }
                MarketEvent::OrderBookUpdate { bid, ask, .. } => {
                    self.state.best_bid = Some(bid);
                    self.state.best_ask = Some(ask);
                }
            }

            // Send the updated aggregate to subscribers
            if self.tx.send(self.state.clone()).await.is_err() {
                eprintln!("Failed to send aggregate");
                break;
            }
        }
    }
}
