use tokio::sync::mpsc;
use tokio_tungstenite::tungstenite::protocol::Message;
use futures::{SinkExt, StreamExt};
use crate::aggregator::PriceAggregate;
use serde_json;

pub async fn start_server(rx: mpsc::Receiver<PriceAggregate>) {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:8080").await.unwrap();
    println!("Server listening on ws://127.0.0.1:8080");

    while let Ok((stream, _)) = listener.accept().await {
        let mut rx = rx.clone();
        tokio::spawn(async move {
            let ws_stream = tokio_tungstenite::accept_async(stream).await.unwrap();
            let (mut write, _) = ws_stream.split();

            // Spawn a task to send aggregates to the client
            let send_task = tokio::spawn(async move {
                while let Some(agg) = rx.recv().await {
                    let json = serde_json::to_string(&agg).unwrap();
                    if write.send(Message::Text(json)).await.is_err() {
                        break;
                    }
                }
            });

            // Wait for the send task to finish (or client disconnect)
            send_task.await.unwrap();
        });
    }
}
