```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <vector>
#include <map>
#include <sstream>
#include <cstring>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <atomic>
#include <chrono>

class MarketDataProcessor {
private:
    std::map<double, double> bids;  // price -> size
    std::map<double, double> asks;  // price -> size
    double best_bid = 0.0;
    double best_ask = 0.0;
    double vwap_bid = 0.0;
    double vwap_ask = 0.0;
    long total_bid_size = 0;
    long total_ask_size = 0;
    mutable std::mutex mtx;
    std::atomic<bool> running{true};

    void update_aggregates() {
        std::lock_guard<std::mutex> lock(mtx);

        // Update best bid/ask
        if (!bids.empty()) {
            best_bid = bids.rbegin()->first;  // Highest bid
        } else {
            best_bid = 0.0;
        }

        if (!asks.empty()) {
            best_ask = asks.begin()->first;   // Lowest ask
        } else {
            best_ask = 0.0;
        }

        // Update VWAP
        vwap_bid = 0.0;
        vwap_ask = 0.0;
        total_bid_size = 0;
        total_ask_size = 0;

        for (const auto& [price, size] : bids) {
            vwap_bid += price * size;
            total_bid_size += size;
        }
        if (total_bid_size > 0) {
            vwap_bid /= total_bid_size;
        }

        for (const auto& [price, size] : asks) {
            vwap_ask += price * size;
            total_ask_size += size;
        }
        if (total_ask_size > 0) {
            vwap_ask /= total_ask_size;
        }
    }

public:
    void process_market_data(const std::string& data) {
        std::istringstream iss(data);
        std::string type;
        double price, size;

        if (iss >> type >> price >> size) {
            std::lock_guard<std::mutex> lock(mtx);
            if (type == "BID") {
                bids[price] += size;
            } else if (type == "ASK") {
                asks[price] += size;
            }
            update_aggregates();
        }
    }

    std::string get_aggregates() const {
        std::lock_guard<std::mutex> lock(mtx);
        std::ostringstream oss;
        oss << "BEST_BID " << best_bid << " " << (bids.empty() ? 0 : bids.rbegin()->second)
            << "\nBEST_ASK " << best_ask << " " << (asks.empty() ? 0 : asks.begin()->second)
            << "\nVWAP_BID " << vwap_bid << " " << total_bid_size
            << "\nVWAP_ASK " << vwap_ask << " " << total_ask_size;
        return oss.str();
    }

    void stop() {
        running = false;
    }
};

class TCPServer {
private:
    MarketDataProcessor& processor;
    int market_data_port;
    int subscriber_port;
    std::vector<int> subscribers;
    std::mutex subscribers_mtx;

    void handle_subscriber(int client_socket) {
        char buffer[1024];
        while (processor.running) {
            std::string aggregates = processor.get_aggregates();
            send(client_socket, aggregates.c_str(), aggregates.size(), 0);
            std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Send every 100ms
        }
        close(client_socket);
    }

    void accept_connections(int port, bool is_market_data) {
        int server_fd, new_socket;
        struct sockaddr_in address;
        int opt = 1;
        int addrlen = sizeof(address);

        if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
            perror("socket failed");
            exit(EXIT_FAILURE);
        }

        if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
            perror("setsockopt");
            exit(EXIT_FAILURE);
        }

        address.sin_family = AF_INET;
        address.sin_addr.s_addr = INADDR_ANY;
        address.sin_port = htons(port);

        if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
            perror("bind failed");
            exit(EXIT_FAILURE);
        }

        if (listen(server_fd, 3) < 0) {
            perror("listen");
            exit(EXIT_FAILURE);
        }

        std::cout << "Server listening on port " << port << std::endl;

        while (processor.running) {
            if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
                perror("accept");
                continue;
            }

            if (is_market_data) {
                // Handle market data feed (simulated)
                char buffer[1024] = {0};
                read(new_socket, buffer, 1024);
                processor.process_market_data(buffer);
                close(new_socket);
            } else {
                // Add new subscriber
                std::lock_guard<std::mutex> lock(subscribers_mtx);
                subscribers.push_back(new_socket);
                std::thread(&TCPServer::handle_subscriber, this, new_socket).detach();
            }
        }
        close(server_fd);
    }

public:
    TCPServer(MarketDataProcessor& proc, int md_port = 8080, int sub_port = 8081)
        : processor(proc), market_data_port(md_port), subscriber_port(sub_port) {}

    void start() {
        // Start market data feed handler
        std::thread market_data_thread(&TCPServer::accept_connections, this, market_data_port, true);
        market_data_thread.detach();

        // Start subscriber handler
        std::thread subscriber_thread(&TCPServer::accept_connections, this, subscriber_port, false);
        subscriber_thread.detach();
    }

    void broadcast_to_subscribers() {
        while (processor.running) {
            std::string aggregates = processor.get_aggregates();
            std::lock_guard<std::mutex> lock(subscribers_mtx);
            for (auto it = subscribers.begin(); it != subscribers.end(); ) {
                if (send(*it, aggregates.c_str(), aggregates.size(), 0) < 0) {
                    close(*it);
                    it = subscribers.erase(it);
                } else {
                    ++it;
                }
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }
};

int main() {
    MarketDataProcessor processor;
    TCPServer server(processor);

    // Start the server
    server.start();

    // Simulate market data feed (for testing)
    std::thread market_data_simulator([&processor]() {
        const char* data[] = {
            "BID 100.5 100",
            "ASK 101.0 50",
            "BID 100.6 150",
            "ASK 101.1 75",
            "BID 100.4 200",
            "ASK 100.9 100"
        };

        for (int i = 0; processor.running && i < 6; ++i) {
            processor.process_market_data(data[i]);
            std::this_thread::sleep_for(std::chrono::milliseconds(500));
        }
    });

    // Start broadcasting to subscribers
    std::thread broadcaster(&TCPServer::broadcast_to_subscribers, &server);

    std::cout << "Market data processor running. Press Enter to stop..." << std::endl;
    std::cin.get();

    processor.stop();
    market_data_simulator.join();
    broadcaster.join();

    return 0;
}
