use serde::{Serialize, Deserialize};
use std::collections::BTreeMap;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OrderBook {
    pub bids: BTreeMap<f64, f64>, // price -> quantity
    pub asks: BTreeMap<f64, f64>, // price -> quantity
    pub last_price: Option<f64>,
    pub total_volume: f64,
}

impl OrderBook {
    pub fn new() -> Self {
        OrderBook {
            bids: BTreeMap::new(),
            asks: BTreeMap::new(),
            last_price: None,
            total_volume: 0.0,
        }
    }

    pub fn update_bid(&mut self, price: f64, quantity: f64) {
        if quantity <= 0.0 {
            self.bids.remove(&price);
        } else {
            *self.bids.entry(price).or_insert(0.0) += quantity;
        }
    }

    pub fn update_ask(&mut self, price: f64, quantity: f64) {
        if quantity <= 0.0 {
            self.asks.remove(&price);
        } else {
            *self.asks.entry(price).or_insert(0.0) += quantity;
        }
    }

    pub fn update_trade(&mut self, price: f64, quantity: f64) {
        self.last_price = Some(price);
        self.total_volume += quantity;
    }
}
