pub async fn start_websocket_server(
    addr: &str,
    mut rx: broadcast::Receiver<String>,
) -> Result<(), Box<dyn std::error::Error>> {
    let listener = tokio::net::TcpListener::bind(addr).await?;
    println!("WebSocket server listening on {}", addr);

