// Message represents a single message in the system
type Message struct {
	ID        string
	Payload   []byte
	Timestamp time.Time
	Headers   map[string]string
	RouteKey  string // For consistent routing
}

// LatencyMetrics tracks performance metrics
type LatencyMetrics struct {
	TotalMessages int64
	TotalLatency  time.Duration
	MinLatency    time.Duration
	MaxLatency    time.Duration
	mu            sync.Mutex
}

// NewLatencyMetrics creates a new metrics tracker
func NewLatencyMetrics() *LatencyMetrics {
	return &LatencyMetrics{
		MinLatency: time.Hour, // Initialize with large value
	}
}

// RecordLatency updates metrics with a new measurement
func (lm *LatencyMetrics) RecordLatency(latency time.Duration) {
	lm.mu.Lock()
	defer lm.mu.Unlock()

	lm.TotalMessages++
	lm.TotalLatency += latency

	if latency < lm.MinLatency {
		lm.MinLatency = latency
	}
	if latency > lm.MaxLatency {
		lm.MaxLatency = latency
	}
}

// GetMetrics returns a copy of current metrics
func (lm *LatencyMetrics) GetMetrics() (int64, time.Duration, time.Duration, time.Duration) {
	lm.mu.Lock()
	defer lm.mu.Unlock()

	return lm.TotalMessages,
		lm.TotalLatency,
		lm.MinLatency,
		lm.MaxLatency
}

// MessageRouter handles the core routing logic
type MessageRouter struct {
	metrics      *LatencyMetrics
	outputChans  map[string]chan *Message
	routingRules map[string]string // Simplified routing rules
	mu           sync.RWMutex
}

// NewMessageRouter creates a new router instance
func NewMessageRouter() *MessageRouter {
	return &MessageRouter{
		metrics:      NewLatencyMetrics(),
		outputChans:  make(map[string]chan *Message),
		routingRules: make(map[string]string),
	}
}

// AddRoute adds a new routing destination
func (r *MessageRouter) AddRoute(routeKey, destination string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.routingRules[routeKey] = destination
	if _, exists := r.outputChans[destination]; !exists {
		r.outputChans[destination] = make(chan *Message, 10000) // Buffered channel
	}
}

// RouteMessage processes and routes a single message
func (r *MessageRouter) RouteMessage(ctx context.Context, msg *Message) {
	startTime := time.Now()

	// Simulate processing delay (in real system this would be actual work)
	time.Sleep(time.Duration(rand.Intn(50)) * time.Microsecond)

	// Apply routing logic
	r.mu.RLock()
	destination, exists := r.routingRules[msg.RouteKey]
	if !exists {
		destination = "default" // Fallback route
	}
	outputChan, exists := r.outputChans[destination]
	r.mu.RUnlock()

	if !exists {
		log.Printf("No route found for message %s", msg.ID)
		return
	}

	// Route the message
	select {
	case <-ctx.Done():
		return
	case outputChan <- msg:
	}

	// Record latency
	latency := time.Since(startTime)
	r.metrics.RecordLatency(latency)
}

// StartMetricsReporter periodically logs performance metrics
func (r *MessageRouter) StartMetricsReporter(interval time.Duration) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	for range ticker.C {
		total, totalLatency, min, max := r.metrics.GetMetrics()
		avg := time.Duration(0)
		if total > 0 {
			avg = totalLatency / time.Duration(total)
		}

		log.Printf("Metrics - Messages: %d, Avg Latency: %v, Min: %v, Max: %v",
			total, avg, min, max)
	}
}

// HighFrequencyMessagingSystem is the main system controller
type HighFrequencyMessagingSystem struct {
	router      *MessageRouter
	inputChan   chan *Message
	workers     int
	shutdown    chan struct{}
	shutdownWg  sync.WaitGroup
}

