func (hfms *HighFrequencyMessagingSystem) Stop() {
	close(hfms.shutdown)
	hfms.shutdownWg.Wait()
	close(hfms.inputChan)
}

// worker processes messages from the input channel
func (hfms *HighFrequencyMessagingSystem) worker(id int) {
	defer hfms.shutdownWg.Done()

