class LatencyStats {
    struct Stats {
        uint64_t count = 0;
        uint64_t min = UINT64_MAX;
        uint64_t max = 0;
        double sum = 0.0;
        double sum_sq = 0.0;
        std::vector<uint64_t> samples;
