public:
    void record_queue_latency(uint64_t latency) {
        std::lock_guard<std::mutex> lock(mutex);
        queue_latency.count++;
        queue_latency.min = std::min(queue_latency.min, latency);
        queue_latency.max = std::max(queue_latency.max, latency);
        queue_latency.sum += latency;
        queue_latency.sum_sq += static_cast<double>(latency) * latency;
        if (queue_latency.samples.size() < 1000) {
            queue_latency.samples.push_back(latency);
        }
    }

    void record_processing_latency(uint64_t latency) {
        std::lock_guard<std::mutex> lock(mutex);
        processing_latency.count++;
        processing_latency.min = std::min(processing_latency.min, latency);
        processing_latency.max = std::max(processing_latency.max, latency);
        processing_latency.sum += latency;
        processing_latency.sum_sq += static_cast<double>(latency) * latency;
        if (processing_latency.samples.size() < 1000) {
            processing_latency.samples.push_back(latency);
        }
    }

    void record_total_latency(uint64_t latency) {
        std::lock_guard<std::mutex> lock(mutex);
        total_latency.count++;
        total_latency.min = std::min(total_latency.min, latency);
        total_latency.max = std::max(total_latency.max, latency);
        total_latency.sum += latency;
        total_latency.sum_sq += static_cast<double>(latency) * latency;
        if (total_latency.samples.size() < 1000) {
            total_latency.samples.push_back(latency);
        }
    }

    void print_stats() {
        std::lock_guard<std::mutex> lock(mutex);

        auto print_percentile = [](const std::string& name, const Stats& stats) {
            if (stats.count == 0) return;

            std::vector<uint64_t> sorted = stats.samples;
            std::sort(sorted.begin(), sorted.end());

            auto percentile = [&](double p) {
                size_t index = static_cast<size_t>(p * sorted.size());
                if (index >= sorted.size()) index = sorted.size() - 1;
                return sorted[index];
