                      << " min=" << stats.min << "ns"
                      << " max=" << stats.max << "ns"
                      << " avg=" << (stats.sum / stats.count) << "ns"
                      << " p50=" << percentile(0.50) << "ns"
                      << " p90=" << percentile(0.90) << "ns"
                      << " p99=" << percentile(0.99) << "ns"
                      << " stddev=" << std::sqrt((stats.sum_sq / stats.count) - std::pow(stats.sum / stats.count, 2)) << "ns"
                      << std::endl;
