class Worker {
    LockFreeQueue<Message>& queue;
    LatencyStats& stats;
    std::atomic<bool>& running;
    std::thread thread;
    uint64_t processed = 0;

    // Simulate message processing
    void process_message(Message& msg) {
        // Simulate some processing work (100-500ns)
        auto start = std::chrono::high_resolution_clock::now();

        // Simulate CPU-intensive work
        volatile uint64_t dummy = 0;
        for (int i = 0; i < 100; i++) {
            dummy += i * i;
        }

        auto end = std::chrono::high_resolution_clock::now();
        uint64_t processing_time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();

        // Record latency statistics
        uint64_t queue_latency = msg.timestamp_queue - msg.timestamp_in;
        uint64_t total_latency = msg.timestamp_out - msg.timestamp_in;

        stats.record_queue_latency(queue_latency);
        stats.record_processing_latency(processing_time);
        stats.record_total_latency(total_latency);

        processed++;
    }

public:
    Worker(LockFreeQueue<Message>& q, LatencyStats& s, std::atomic<bool>& r)
        : queue(q), stats(s), running(r) {}

    void start() {
        thread = std::thread([this] {
            Message msg;
            while (running.load(std::memory_order_acquire)) {
                if (queue.dequeue(msg)) {
                    process_message(msg);
                } else {
                    // Busy wait with pause to reduce CPU usage
                    std::this_thread::yield();
                }
            }

            // Process remaining messages
            while (queue.dequeue(msg)) {
                process_message(msg);
            }
        });
    }

    void join() {
        if (thread.joinable()) {
            thread.join();
        }
    }

    uint64_t get_processed() const { return processed; }
};

