    }

    // Monitor and report statistics
    void monitor() {
        size_t last_total = 0;
        auto start_time = std::chrono::high_resolution_clock::now();

        while (running.load(std::memory_order_acquire)) {
            std::this_thread::sleep_for(std::chrono::seconds(1));

            auto now = std::chrono::high_resolution_clock::now();
            auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(now - start_time).count();

            uint64_t total_processed = 0;
            for (auto& worker : workers) {
                total_processed += worker.get_processed();
            }

            uint64_t msg_per_sec = (total_processed - last_total) / std::max(elapsed, static_cast<int64_t>(1));
            last_total = total_processed;
            start_time = now;

            std::cout << "\n[System Status] Messages/sec: " << msg_per_sec << std::endl;
            stats.print_stats();
        }
    }

public:
    MessagingSystem() {
        // Initialize workers
        for (size_t i = 0; i < NUM_WORKERS; i++) {
            workers.emplace_back(message_queue, stats, running);
        }

        // Start workers
        for (auto& worker : workers) {
            worker.start();
        }
    }

    ~MessagingSystem() {
        running.store(false, std::memory_order_release);

        // Join workers
        for (auto& worker : workers) {
            worker.join();
        }

        // Join monitor thread
        if (monitor_thread.joinable()) {
            monitor_thread.join();
        }
    }

    void start_producers(size_t num_messages) {
        producer_threads.emplace_back([this, num_messages] {
            generate_messages(num_messages);
        });

        monitor_thread = std::thread([this] {
            monitor();
        });
    }

    void wait_for_completion() {
        if (producer_threads[0].joinable()) {
            producer_threads[0].join();
        }
    }
};

// ==================== Main Function ====================
int main() {
    std::cout << "Starting high-frequency messaging system..." << std::endl;
    std::cout << "Workers: " << NUM_WORKERS << std::endl;
    std::cout << "Target messages: " << MAX_MESSAGES << std::endl;

    MessagingSystem system;
    system.start_producers(MAX_MESSAGES);
    system.wait_for_completion();

    std::cout << "\nSystem shutdown complete." << std::endl;
    return 0;
}
```

