	metrics     *Metrics
	handlers    map[string]func(*Message)
}

// NewRouter creates a new Router instance
func NewRouter(bufferSize int) *Router {
	return &Router{
		messageChan: make(chan Message, bufferSize),
		metrics: &Metrics{
			MinLatency: time.Hour, // Initialize to large value
		},
		handlers: make(map[string]func(*Message)),
	}
}

// RegisterHandler adds a processing function for a destination
func (r *Router) RegisterHandler(destination string, handler func(*Message)) {
	r.handlers[destination] = handler
}

// Start begins processing messages
func (r *Router) Start(workers int) {
	for i := 0; i < workers; i++ {
		go r.worker()
	}
}

func (r *Router) worker() {
	for msg := range r.messageChan {
		startTime := time.Now()

		// Apply processing logic based on destination
		if handler, exists := r.handlers[msg.Destination]; exists {
			handler(&msg)
		} else {
			// Default processing if no handler registered
			msg.Destination = "default_" + msg.Destination
		}

		// Calculate and record latency
		msg.Latency = time.Since(startTime)
		r.updateMetrics(msg.Latency)

		// Forward to next hop (in a real system, this would be another service)
		// For simulation, we'll just log
		// fmt.Printf("Forwarded message to %s with latency %v\n", msg.Destination, msg.Latency)
	}
}

func (r *Router) updateMetrics(latency time.Duration) {
	r.metrics.mu.Lock()
	defer r.metrics.mu.Unlock()

	r.metrics.TotalMessages++
	r.metrics.LatencySum += latency

	if latency > r.metrics.MaxLatency {
		r.metrics.MaxLatency = latency
	}
	if latency < r.metrics.MinLatency {
		r.metrics.MinLatency = latency
	}
	r.metrics.AvgLatency = r.metrics.LatencySum / time.Duration(r.metrics.TotalMessages)
}

// GetMetrics returns a copy of current metrics
func (r *Router) GetMetrics() Metrics {
	r.metrics.mu.Lock()
	defer r.metrics.mu.Unlock()
	return *r.metrics
}

// SimulateMessageSource generates messages at high frequency
func SimulateMessageSource(router *Router, messagesPerSecond int, duration time.Duration) {
