use std::collections::HashMap;
use std::sync::Arc;
use std::time::{Instant, Duration};
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::Mutex;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use bytes::BytesMut;
use tokio::time;

// Message structure with routing information
#[derive(Debug, Clone)]
struct Message {
    id: u64,
    received_at: Instant,
    processed_at: Instant,
    content: Vec<u8>,
    route_to: String,
}

// Shared application state
struct AppState {
    routes: HashMap<String, String>,
    latency_stats: Mutex<LatencyStatistics>,
}

struct LatencyStatistics {
    total_messages: u64,
    total_latency: Duration,
    min_latency: Duration,
    max_latency: Duration,
    last_report: Instant,
}

impl AppState {
    fn new() -> Self {
        let mut routes = HashMap::new();
        routes.insert("analytics".to_string(), "127.0.0.1:8081".to_string());
        routes.insert("notifications".to_string(), "127.0.0.1:8082".to_string());
        routes.insert("default".to_string(), "127.0.0.1:8083".to_string());

        AppState {
            routes,
            latency_stats: Mutex::new(LatencyStatistics {
                total_messages: 0,
                total_latency: Duration::from_secs(0),
                min_latency: Duration::from_secs(10),
                max_latency: Duration::from_secs(0),
                last_report: Instant::now(),
            }),
        }
    }

    async fn record_latency(&self, latency: Duration) {
        let mut stats = self.latency_stats.lock().await;
        stats.total_messages += 1;
        stats.total_latency += latency;

        if latency < stats.min_latency {
            stats.min_latency = latency;
        }
        if latency > stats.max_latency {
            stats.max_latency = latency;
        }
    }

    async fn get_stats(&self) -> (u64, Duration, Duration, Duration) {
        let stats = self.latency_stats.lock().await;
        (
            stats.total_messages,
            stats.total_latency,
            stats.min_latency,
            stats.max_latency,
        )
    }

    async fn report_stats(&self) {
        let stats = self.latency_stats.lock().await;
        let duration = stats.last_report.elapsed();
        if duration >= Duration::from_secs(5) {
            let avg_latency = if stats.total_messages > 0 {
                stats.total_latency / stats.total_messages
            } else {
                Duration::from_secs(0)
            };

            println!(
                "[{}] Performance Report - Messages: {}, Avg Latency: {:?}μs, Min: {:?}μs, Max: {:?}μs",
                chrono::Local::now().format("%Y-%m-%d %H:%M:%S"),
                stats.total_messages,
                avg_latency.as_micros(),
                stats.min_latency.as_micros(),
                stats.max_latency.as_micros()
            );

            stats.last_report = Instant::now();
        }
    }
}

// Handle incoming client connections
async fn handle_connection(mut socket: TcpStream, state: Arc<AppState>) {
    let mut buf = BytesMut::with_capacity(4096); // Buffer for incoming data
    let mut message_id = 0;

    loop {
        // Read data from the socket
        match socket.read_buf(&mut buf).await {
            Ok(0) => {
                // Connection closed
                break;
            }
            Ok(n) => {
                message_id += 1;
                let received_at = Instant::now();

                // Parse the message (simple binary protocol: [route_len:u8][route][data])
                let route_len = buf[0] as usize;
                let route = String::from_utf8_lossy(&buf[1..1+route_len]).to_string();
                let content = buf[1+route_len..n].to_vec();

                // Create message
                let message = Message {
                    id: message_id,
                    received_at,
                    processed_at: Instant::now(),
                    content,
                    route_to: route,
                };

                // Process and route the message
                let processing_start = Instant::now();
                process_message(&message, state.clone()).await;
                let latency = processing_start.elapsed();

                // Record latency
                state.record_latency(latency).await;

                // Clear buffer for next message
                buf.clear();
            }
            Err(e) => {
                eprintln!("Read error: {}", e);
                break;
            }
        }
    }
}

// Process and route a single message
async fn process_message(message: &Message, state: Arc<AppState>) {
    // Simulate message processing time
    time::sleep(Duration::from_micros(10)).await;

    // Route the message based on its destination
    if let Some(destination) = state.routes.get(&message.route_to) {
        // In a real system, this would establish a connection to the destination
        // and send the message. For this example, we'll just simulate it.
        time::sleep(Duration::from_micros(50)).await;

        println!(
            "Message {} routed to {} in {:?}μs",
            message.id,
            destination,
            message.processed_at.elapsed().as_micros()
        );
    } else {
        println!("No route found for message {}", message.id);
    }
}

#[tokio::main(flavor = "multi_thread", worker_threads = 8)]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("Starting high-frequency messaging system...");

    // Initialize shared state
    let state = Arc::new(AppState::new());

    // Spawn stats reporter
    let stats_state = state.clone();
    tokio::spawn(async move {
        loop {
            time::sleep(Duration::from_secs(1)).await;
            stats_state.report_stats().await;
        }
    });

    // Create TCP listener
    let listener = TcpListener::bind("0.0.0.0:8080").await?;
    println!("Listening on {}", listener.local_addr()?);

    // Accept incoming connections
    loop {
        let (socket, addr) = listener.accept().await?;
        let state = state.clone();

        println!("New connection from {}", addr);

        tokio::spawn(async move {
            if let Err(e) = handle_connection(socket, state).await {
                eprintln!("Connection error: {}", e);
            }
        });
    }
}
