class LatencyTracker {
public:
    void record_latency(const chrono::steady_clock::duration& latency) {
        auto usec = chrono::duration_cast<chrono::microseconds>(latency).count();

        std::lock_guard<std::mutex> lock(mutex_);
        latencies_.push_back(usec);

        if (usec < min_latency_ || min_latency_ == 0) min_latency_ = usec;
        if (usec > max_latency_) max_latency_ = usec;

        total_latency_ += usec;
        count_++;

        if (count_ % 10000 == 0) {
            print_stats();
        }
    }

    void print_stats() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (count_ == 0) return;

        double avg = static_cast<double>(total_latency_) / count_;
        std::cout << "Latency Stats - Count: " << count_
                  << " | Min: " << min_latency_ << "μs"
                  << " | Max: " << max_latency_ << "μs"
                  << " | Avg: " << avg << "μs" << std::endl;
    }

private:
    std::vector<long> latencies_;
    long min_latency_ = 0;
    long max_latency_ = 0;
    long total_latency_ = 0;
    size_t count_ = 0;
    std::mutex mutex_;
};

// Message router
class MessageRouter {
public:
    void add_route(const std::string& destination, const std::string& pattern) {
        routes_[pattern] = destination;
    }

    std::string route_message(const Message& msg) {
        // Simple routing logic - in production you'd want something more sophisticated
        for (const auto& [pattern, dest] : routes_) {
            if (msg.data.find(pattern) != std::string::npos) {
                return dest;
            }
        }
        return "default";
    }

private:
    std::unordered_map<std::string, std::string> routes_;
};

// Connection handler
class Session : public std::enable_shared_from_this<Session> {
public:
    Session(tcp::socket socket, MessageRouter& router, LatencyTracker& tracker)
        : socket_(std::move(socket)), router_(router), tracker_(tracker) {}

    void start() {
        do_read();
    }

private:
    void do_read() {
        auto self(shared_from_this());
        socket_.async_read_some(boost::asio::buffer(data_, max_length),
            [this, self](boost::system::error_code ec, std::size_t length) {
                if (!ec) {
                    // Record receive time
                    auto receive_time = chrono::steady_clock::now();

                    // Process message
                    Message msg;
                    msg.data.assign(data_, length);
                    msg.received_time = receive_time;

                    // Route the message
                    msg.route_destination = router_.route_message(msg);

                    // Simulate processing time (in real system this would be actual processing)
                    auto processing_start = chrono::steady_clock::now();
                    // ... actual message processing would happen here ...
                    auto processing_end = chrono::steady_clock::now();

                    // Calculate total latency
                    auto total_latency = processing_end - receive_time;
                    tracker_.record_latency(total_latency);

                    // Echo back for demonstration (in real system would forward to destination)
                    do_write("Processed: " + msg.data);
                }
            });
    }

    void do_write(const std::string& message) {
        auto self(shared_from_this());
        boost::asio::async_write(socket_, boost::asio::buffer(message),
            [this, self](boost::system::error_code ec, std::size_t /*length*/) {
                if (!ec) {
                    do_read();
                }
            });
    }

    tcp::socket socket_;
    MessageRouter& router_;
    LatencyTracker& tracker_;
    enum { max_length = 1024 };
    char data_[max_length];
};

// Server class
class Server {
public:
    Server(boost::asio::io_context& io_context, short port)
        : acceptor_(io_context, tcp::endpoint(tcp::v4(), port)) {
        do_accept();
    }

private:
    void do_accept() {
        acceptor_.async_accept(
            [this](boost::system::error_code ec, tcp::socket socket) {
                if (!ec) {
                    std::make_shared<Session>(std::move(socket), router_, tracker_)->start();
                }
                do_accept();
            });
    }

    tcp::acceptor acceptor_;
    MessageRouter router_;
    LatencyTracker tracker_;
};

