// LatencyMetrics tracks the latency of message processing.
type LatencyMetrics struct {
	TotalMessages int
	TotalLatency  time.Duration
	MinLatency    time.Duration
	MaxLatency    time.Duration
	mu            sync.Mutex
}

// NewLatencyMetrics initializes a new LatencyMetrics instance.
func NewLatencyMetrics() *LatencyMetrics {
	return &LatencyMetrics{
		MinLatency: time.Hour, // Initialize with a large value
	}
}

// RecordLatency records the latency of a single message.
func (lm *LatencyMetrics) RecordLatency(latency time.Duration) {
	lm.mu.Lock()
	defer lm.mu.Unlock()

	lm.TotalMessages++
	lm.TotalLatency += latency

	if latency < lm.MinLatency {
		lm.MinLatency = latency
	}

	if latency > lm.MaxLatency {
		lm.MaxLatency = latency
	}
}

// AvgLatency calculates the average latency.
func (lm *LatencyMetrics) AvgLatency() time.Duration {
	lm.mu.Lock()
	defer lm.mu.Unlock()

	if lm.TotalMessages == 0 {
		return 0
	}
	return lm.TotalLatency / time.Duration(lm.TotalMessages)
}

// MessageRouter handles the routing of messages.
type MessageRouter struct {
	metrics *LatencyMetrics
}

// NewMessageRouter initializes a new MessageRouter.
func NewMessageRouter() *MessageRouter {
	return &MessageRouter{
		metrics: NewLatencyMetrics(),
	}
}

// RouteMessage processes a single message and routes it to the appropriate destination.
func (mr *MessageRouter) RouteMessage(ctx context.Context, msg *Message) {
