		_ = msg.Payload
	}

	latency := time.Since(startTime)
	mr.metrics.RecordLatency(latency)

	// Log metrics periodically
	if msg.ID == "1" { // Just for demonstration; in a real system, you'd log periodically
		log.Printf("Latency Metrics - Total: %d, Avg: %v, Min: %v, Max: %v",
			mr.metrics.TotalMessages,
			mr.metrics.AvgLatency(),
			mr.metrics.MinLatency,
			mr.metrics.MaxLatency)
	}
}

