type HighFrequencyMessagingSystem struct {
	router *MessageRouter
}

// NewHighFrequencyMessagingSystem initializes a new HighFrequencyMessagingSystem.
func NewHighFrequencyMessagingSystem() *HighFrequencyMessagingSystem {
