// Start starts the messaging system and begins processing messages.
func (hfms *HighFrequencyMessagingSystem) Start(numWorkers int) {
	var wg sync.WaitGroup
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Start workers
	for i := 0; i < numWorkers; i++ {
		wg.Add(1)
		go func(workerID int) {
			defer wg.Done()
			for {
				select {
				case <-ctx.Done():
					return
				default:
					// Simulate receiving a message
					msg := &Message{
						ID:        fmt.Sprintf("%d-%d", workerID, time.Now().UnixNano()),
						Payload:   []byte("sample payload"),
						Timestamp: time.Now(),
						Headers:   map[string]string{"type": "test"},
					}

					hfms.router.RouteMessage(ctx, msg)
				}
			}
		}(i)
	}

	// Wait for all workers to finish (in a real system, you'd have a way to stop them gracefully)
	wg.Wait()
}

func main() {
	hfms := NewHighFrequencyMessagingSystem()
	hfms.Start(10) // Start with 10 workers
}
