use std::collections::HashMap;
use std::sync::Arc;
use std::time::{Instant, Duration};
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::Mutex;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use bytes::BytesMut;

// Define a simple message structure
#[derive(Debug)]
struct Message {
    id: u64,
    timestamp: Instant,
    content: String,
    route_to: String,
}

// Shared state for the application
struct AppState {
    // Map of route destinations to their addresses
    routes: HashMap<String, String>,
    // Latency statistics
    latency_stats: Mutex<LatencyStats>,
}

// Latency statistics
struct LatencyStats {
    total_messages: u64,
    total_latency: Duration,
    min_latency: Duration,
    max_latency: Duration,
    // You could add more detailed stats here
}

impl AppState {
    fn new() -> Self {
        let mut routes = HashMap::new();
        routes.insert("route1".to_string(), "127.0.0.1:8081".to_string());
        routes.insert("route2".to_string(), "127.0.0.1:8082".to_string());

        AppState {
            routes,
            latency_stats: Mutex::new(LatencyStats {
                total_messages: 0,
                total_latency: Duration::from_secs(0),
                min_latency: Duration::from_secs(10),
                max_latency: Duration::from_secs(0),
            }),
        }
    }

    async fn record_latency(&self, latency: Duration) {
        let mut stats = self.latency_stats.lock().await;
        stats.total_messages += 1;
        stats.total_latency += latency;
        if latency < stats.min_latency {
            stats.min_latency = latency;
        }
        if latency > stats.max_latency {
            stats.max_latency = latency;
        }
    }

    async fn get_stats(&self) -> (u64, Duration, Duration, Duration) {
        let stats = self.latency_stats.lock().await;
        (
            stats.total_messages,
            stats.total_latency,
            stats.min_latency,
            stats.max_latency,
        )
    }
}

// Function to handle a single client connection
async fn handle_connection(mut socket: TcpStream, state: Arc<AppState>) {
    let mut buf = BytesMut::with_capacity(1024);
    let mut message_id = 0;

    loop {
        // Read data from the socket
        match socket.read_buf(&mut buf).await {
            Ok(0) => {
                // Connection was closed
                break;
            }
            Ok(n) => {
                // Process the received data
                let received_at = Instant::now();
                let content = String::from_utf8_lossy(&buf[..n]).to_string();
                message_id += 1;

                // Parse the message to determine routing
                let route_to = if content.starts_with("route1") {
                    "route1".to_string()
                } else if content.starts_with("route2") {
                    "route2".to_string()
                } else {
                    "default".to_string()
                };

                // Create a message
                let message = Message {
                    id: message_id,
                    timestamp: Instant::now(),
                    content,
                    route_to,
                };

                // Route the message
                let latency_start = Instant::now();
                route_message(&message, state.clone()).await;
                let latency = latency_start.elapsed();

                // Record latency
                state.record_latency(latency).await;

                // Log some info
                println!(
                    "Processed message {} in {:?}ms, routed to {}",
                    message.id,
                    latency.as_millis(),
                    message.route_to
                );

                // Clear the buffer for the next message
                buf.clear();
            }
            Err(e) => {
                eprintln!("Failed to read from socket: {}", e);
                break;
            }
        }
    }
}

// Function to route a message to its destination
async fn route_message(message: &Message, state: Arc<AppState>) {
    let route_to = message.route_to.clone();
    if let Some(destination) = state.routes.get(&route_to) {
        // In a real system, you'd connect to the destination and send the message
        // For simplicity, we'll just simulate the routing delay
        tokio::time::sleep(Duration::from_millis(1)).await;
        println!("Routed message {} to {}", message.id, destination);
    } else {
        println!("No route found for message {}", message.id);
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialize the application state
    let state = Arc::new(AppState::new());

    // Create a TCP listener
    let listener = TcpListener::bind("127.0.0.1:8080").await?;
    println!("Listening on {}", listener.local_addr()?);

    // Periodically print latency statistics
    let stats_state = state.clone();
    tokio::spawn(async move {
        loop {
            tokio::time::sleep(Duration::from_secs(5)).await;
            let (total, total_latency, min, max) = stats_state.get_stats().await;
            let avg_latency = if total > 0 {
                total_latency / total
            } else {
                Duration::from_secs(0)
            };
            println!(
                "Stats - Total messages: {}, Avg latency: {:?}ms, Min: {:?}ms, Max: {:?}ms",
                total,
                avg_latency.as_millis(),
                min.as_millis(),
                max.as_millis()
            );
        }
    });

    // Accept incoming connections
    loop {
        let (socket, _) = listener.accept().await?;
        let state = state.clone();

        // Spawn a new task to handle the connection
        tokio::spawn(async move {
            if let Err(e) = handle_connection(socket, state).await {
                eprintln!("Error handling connection: {}", e);
