#include "Monitor.h"
#include <algorithm>

void Monitor::recordEntry(uint64_t timestamp) {
    // Entry timestamp is recorded when message is received
}

void Monitor::recordProcessed(uint64_t entryTimestamp, uint64_t processedTimestamp) {
    uint64_t latency = processedTimestamp - entryTimestamp;

    std::lock_guard<std::mutex> lock(mutex_);
    auto& stats = entryToProcessed_;
    stats.count++;
    stats.totalLatency += latency;
    stats.samples.push_back(latency);

    if (latency > stats.maxLatency) stats.maxLatency = latency;
    if (latency < stats.minLatency) stats.minLatency = latency;
}

void Monitor::recordSent(uint64_t entryTimestamp, uint64_t sentTimestamp) {
    uint64_t latency = sentTimestamp - entryTimestamp;

    std::lock_guard<std::mutex> lock(mutex_);
    auto& stats = entryToSent_;
    stats.count++;
    stats.totalLatency += latency;
    stats.samples.push_back(latency);

    if (latency > stats.maxLatency) stats.maxLatency = latency;
    if (latency < stats.minLatency) stats.minLatency = latency;
}

void Monitor::printStats() {
    std::lock_guard<std::mutex> lock(mutex_);

    auto printStats = [](const std::string& name, LatencyStats& stats) {
        if (stats.count == 0) return;

        // Sort samples for percentile calculation
        std::sort(stats.samples.begin(), stats.samples.end());

        // Calculate 99th percentile
        size_t idx99 = static_cast<size_t>(stats.samples.size() * 0.99);
        if (idx99 >= stats.samples.size()) idx99 = stats.samples.size() - 1;
        uint64_t p99 = stats.samples[idx99];

        double avg = static_cast<double>(stats.totalLatency) / stats.count;
        double throughput = static_cast<double>(stats.count) / 1.0; // per second

        std::cout << "\n" << name << " Latency Report (last 1s):\n"
                  << "  Messages processed: " << stats.count << "\n"
                  << "  Throughput: " << throughput << " msg/s\n"
                  << "  Average latency: " << avg << " ns\n"
                  << "  Min latency: " << stats.minLatency << " ns\n"
                  << "  Max latency: " << stats.maxLatency << " ns\n"
                  << "  99th percentile: " << p99 << " ns\n"
                  << "----------------------------------------\n";
    };

    printStats("Entry→Processed", entryToProcessed_);
    printStats("Entry→Sent", entryToSent_);

    // Reset counters for next interval
    entryToProcessed_.count = 0;
    entryToProcessed_.totalLatency = 0;
    entryToProcessed_.maxLatency = 0;
    entryToProcessed_.minLatency = UINT64_MAX;
    entryToProcessed_.samples.clear();

    entryToSent_.count = 0;
    entryToSent_.totalLatency = 0;
    entryToSent_.maxLatency = 0;
    entryToSent_.minLatency = UINT64_MAX;
    entryToSent_.samples.clear();
}
