    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        std::cerr << "Error opening socket" << std::endl;
        return;
    }

    // Set socket to non-blocking
    int flags = fcntl(sockfd, F_GETFL, 0);
    fcntl(sockfd, F_SETFL, flags | O_NONBLOCK);

    sockaddr_in serv_addr{};
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(port_);

    if (bind(sockfd, (sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
        std::cerr << "Error binding socket" << std::endl;
        close(sockfd);
        return;
    }

    std::cout << "Dispatcher listening on port " << port_ << std::endl;

    while (running_) {
        Message msg;
        sockaddr_in client_addr{};
        socklen_t client_len = sizeof(client_addr);

        auto start = std::chrono::high_resolution_clock::now();
        ssize_t n = recvfrom(sockfd, &msg, sizeof(msg), 0,
                            (sockaddr*)&client_addr, &client_len);
        auto end = std::chrono::high_resolution_clock::now();

        if (n < 0) {
            if (errno == EWOULDBLOCK || errno == EAGAIN) {
                // No data available, sleep briefly
                std::this_thread::sleep_for(std::chrono::microseconds(100));
                continue;
            }
            std::cerr << "Error receiving message: " << strerror(errno) << std::endl;
            continue;
        }

        // Only process complete messages
        if (n != sizeof(Message)) {
            std::cerr << "Received incomplete message (" << n << " bytes)" << std::endl;
            continue;
        }

        // Timestamp entry
        msg.timestamp = std::chrono::duration_cast<std::chrono::nanoseconds>(
            end.time_since_epoch()).count();

        // Push to worker queue
        workerQueue_.push(msg);

        // Update monitor
        monitor_.recordEntry(msg.timestamp);
    }

    close(sockfd);
}
