// Message structure with latency tracking
struct Message {
    uint64_t id;
    std::string payload;
    std::chrono::high_resolution_clock::time_point enqueue_time;
    std::chrono::high_resolution_clock::time_point dequeue_time;
    std::chrono::high_resolution_clock::time_point process_start;
    std::chrono::high_resolution_clock::time_point process_end;
};

// High-performance lock-free queue (MPMC - Multiple Producer Multiple Consumer)
class LockFreeQueue {
private:
    struct Node {
        Message msg;
        std::atomic<Node*> next;
        Node() : next(nullptr) {}
    };

    alignas(64) std::atomic<Node*> head;
    alignas(64) std::atomic<Node*> tail;

public:
    LockFreeQueue() : head(new Node()), tail(head.load()) {}

    ~LockFreeQueue() {
        while (Node* old_head = head.load()) {
            head.store(old_head->next.load());
            delete old_head;
        }
    }

    void enqueue(Message msg) {
        Node* new_node = new Node();
        new_node->msg = std::move(msg);
        new_node->next.store(nullptr, std::memory_order_relaxed);

        Node* current_tail = tail.load(std::memory_order_acquire);
        Node* next;

        do {
            next = current_tail->next.load(std::memory_order_acquire);
            if (current_tail == tail.load(std::memory_order_acquire)) {
                if (next == nullptr) {
                    if (current_tail->next.compare_exchange_weak(next, new_node,
                        std::memory_order_release, std::memory_order_relaxed)) {
                        break;
                    }
                } else {
                    tail.compare_exchange_weak(current_tail, next,
                        std::memory_order_release, std::memory_order_relaxed);
                }
            }
        } while (true);

        tail.compare_exchange_strong(current_tail, new_node,
            std::memory_order_release, std::memory_order_relaxed);
    }

    bool dequeue(Message& msg) {
        Node* current_head = head.load(std::memory_order_acquire);
        Node* next_head = current_head->next.load(std::memory_order_acquire);

        if (next_head == nullptr) {
            return false; // Queue is empty
        }

        if (head.compare_exchange_strong(current_head, next_head,
            std::memory_order_release, std::memory_order_relaxed)) {
            msg = std::move(next_head->msg);
            delete current_head;
            return true;
        }
        return false;
    }
};

