# High-Frequency Messaging System Implementation

Below is a complete C++ implementation of a high-frequency messaging system that routes millions of messages per second with latency monitoring. This implementation uses Boost.Asio for asynchronous networking and includes all core components: message routing, latency tracking, and metrics reporting.

```cpp
#include <iostream>
#include <vector>
#include <string>
#include <chrono>
#include <thread>
#include <atomic>
#include <mutex>
#include <algorithm>
#include <numeric>
#include <memory>
#include <boost/asio.hpp>
#include <boost/bind/bind.hpp>

using namespace std::chrono_literals;

// Message structure
struct Message {
    uint64_t id;
    std::chrono::steady_clock::time_point received_time;
    std::string payload;
    std::string destination;
};

// Latency tracking system
class LatencyTracker {
public:
    void record_latency(std::chrono::nanoseconds latency) {
        std::lock_guard<std::mutex> lock(mutex_);
        latencies_.push_back(latency.count());
        if (latencies_.size() > 1000000) { // Keep last million samples
            latencies_.erase(latencies_.begin());
        }
    }

    struct Stats {
        double min;
        double avg;
        double p99;
        double max;
    };

    Stats get_stats() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (latencies_.empty()) {
            return {0, 0, 0, 0};
        }

        auto minmax = std::minmax_element(latencies_.begin(), latencies_.end());
        double min = *minmax.first;
        double max = *minmax.second;
        double sum = std::accumulate(latencies_.begin(), latencies_.end(), 0.0);
        double avg = sum / latencies_.size();

        // Calculate p99
        size_t n = latencies_.size();
        std::nth_element(latencies_.begin(), latencies_.begin() + n * 0.99, latencies_.end());
        double p99 = latencies_[n * 0.99];

        return {min, avg, p99, max};
    }

private:
    std::vector<int64_t> latencies_;
    std::mutex mutex_;
};

// Thread-safe message queue (lock-free implementation)
template <typename T>
class LockFreeQueue {
public:
    bool push(const T& item) {
        auto new_tail = tail_.load(std::memory_order_relaxed);
        auto next_tail = new_tail + 1;

        if (next_tail == head_.load(std::memory_order_acquire)) {
            return false; // Queue full
        }

        buffer_[new_tail % capacity_] = item;
        tail_.store(next_tail, std::memory_order_release);
        return true;
    }

    bool pop(T& item) {
        auto new_head = head_.load(std::memory_order_relaxed);
        if (new_head == tail_.load(std::memory_order_acquire)) {
            return false; // Queue empty
        }

        item = buffer_[new_head % capacity_];
        head_.store(new_head + 1, std::memory_order_release);
        return true;
    }

private:
    static const size_t capacity_ = 1024 * 1024; // 1M messages
    T buffer_[capacity_];
    alignas(64) std::atomic<size_t> head_{0};
    alignas(64) std::atomic<size_t> tail_{0};
};

// Message router (round-robin)
class Router {
public:
    Router(size_t num_destinations) : destinations_(num_destinations) {
        for (size_t i = 0; i < num_destinations; ++i) {
            destinations_[i] = "destination_" + std::to_string(i);
        }
    }

    std::string route(const Message& msg) {
        std::lock_guard<std::mutex> lock(mutex_);
        return destinations_[current_destination_++ % destinations_.size()];
    }

private:
    std::vector<std::string> destinations_;
    size_t current_destination_ = 0;
    std::mutex mutex_;
};

// Network server (handles incoming connections)
class NetworkServer {
public:
    NetworkServer(boost::asio::io_context& io_context,
                 short port,
                 LockFreeQueue<Message>& incoming_queue,
                 LatencyTracker& latency_tracker)
        : acceptor_(io_context, boost::asio::ip::tcp::endpoint(boost::asio::ip::tcp::v4(), port)),
          socket_(io_context),
          incoming_queue_(incoming_queue),
          latency_tracker_(latency_tracker) {
        do_accept();
    }

private:
    void do_accept() {
        acceptor_.async_accept(socket_, [this](boost::system::error_code ec) {
            if (!ec) {
                std::make_shared<Session>(std::move(socket_), incoming_queue_, latency_tracker_)->start();
            }
            do_accept();
        });
    }

    boost::asio::ip::tcp::acceptor acceptor_;
    boost::asio::ip::tcp::socket socket_;
    LockFreeQueue<Message>& incoming_queue_;
    LatencyTracker& latency_tracker_;

    class Session : public std::enable_shared_from_this<Session> {
    public:
        Session(boost::asio::ip::tcp::socket socket,
               LockFreeQueue<Message>& incoming_queue,
               LatencyTracker& latency_tracker)
            : socket_(std::move(socket)),
              incoming_queue_(incoming_queue),
              latency_tracker_(latency_tracker) {}

        void start() {
            do_read_header();
        }

    private:
        void do_read_header() {
            auto self(shared_from_this());
            boost::asio::async_read(socket_, boost::asio::buffer(&header_, sizeof(header_)),
                [this, self](boost::system::error_code ec, std::size_t /*length*/) {
                    if (!ec && header_.size > 0) {
                        payload_.resize(header_.size);
                        do_read_payload();
                    }
                });
        }

        void do_read_payload() {
            auto self(shared_from_this());
            boost::asio::async_read(socket_, boost::asio::buffer(payload_),
                [this, self](boost::system::error_code ec, std::size_t /*length*/) {
                    if (!ec) {
                        Message msg;
                        msg.id = ++message_counter_;
                        msg.received_time = std::chrono::steady_clock::now();
                        msg.payload = std::move(payload_);

                        // In a real system, we'd parse the message to get destination, etc.
                        msg.destination = "default"; // Simplified for example

                        // Record receive latency
                        auto latency = std::chrono::steady_clock::now() - msg.received_time;
                        latency_tracker_.record_latency(latency);

                        // Add to incoming queue
                        while (!incoming_queue_.push(msg)) {
                            // Queue full, wait a bit
                            std::this_thread::yield();
                        }
                        do_read_header();
                    }
                });
        }

        struct Header {
            uint32_t size;
        } header_;

        boost::asio::ip::tcp::socket socket_;
        LockFreeQueue<Message>& incoming_queue_;
        LatencyTracker& latency_tracker_;
        std::string payload_;
        static inline std::atomic<uint64_t> message_counter_{0};
    };
};

// Message processor (handles routing logic)
class MessageProcessor {
public:
    MessageProcessor(LockFreeQueue<Message>& incoming_queue,
                    LockFreeQueue<Message>& outgoing_queue,
                    Router& router,
                    LatencyTracker& latency_tracker)
        : incoming_queue_(incoming_queue),
          outgoing_queue_(outgoing_queue),
          router_(router),
          latency_tracker_(latency_tracker) {}

    void run() {
        while (running_) {
            Message msg;
            if (incoming_queue_.pop(msg)) {
                // Process message (in this case, just route it)
                msg.destination = router_.route(msg);

                // Calculate processing latency
                auto processing_end = std::chrono::steady_clock::now();
                auto latency = processing_end - msg.received_time;
                latency_tracker_.record_latency(latency);

                // Add to outgoing queue
                while (!outgoing_queue_.push(msg)) {
                    std::this_thread::yield();
                }
            } else {
                // Queue empty, yield to avoid busy waiting
                std::this_thread::yield();
            }
        }
    }

    void stop() {
        running_ = false;
    }

private:
    LockFreeQueue<Message>& incoming_queue_;
    LockFreeQueue<Message>& outgoing_queue_;
    Router& router_;
    LatencyTracker& latency_tracker_;
    std::atomic<bool> running_{true};
};

// Metrics server (HTTP endpoint for latency stats)
class MetricsServer {
public:
    MetricsServer(boost::asio::io_context& io_context, short port, LatencyTracker& tracker)
        : acceptor_(io_context, boost::asio::ip::tcp::endpoint(boost::asio::ip::tcp::v4(), port)),
          socket_(io_context),
          latency_tracker_(tracker) {
        do_accept();
    }

private:
    void do_accept() {
        acceptor_.async_accept(socket_, [this](boost::system::error_code ec) {
            if (!ec) {
                std::make_shared<Connection>(std::move(socket_), latency_tracker_)->start();
            }
            do_accept();
        });
    }

    boost::asio::ip::tcp::acceptor acceptor_;
    boost::asio::ip::tcp::socket socket_;
    LatencyTracker& latency_tracker_;

    class Connection : public std::enable_shared_from_this<Connection> {
    public:
        Connection(boost::asio::ip::tcp::socket socket, LatencyTracker& tracker)
            : socket_(std::move(socket)), latency_tracker_(tracker) {}

        void start() {
            do_read();
        }

    private:
        void do_read() {
            auto self(shared_from_this());
            socket_.async_read_some(boost::asio::buffer(data_, max_length),
                [this, self](boost::system::error_code ec, std::size_t length) {
                    if (!ec) {
                        if (std::string(data_, length).find("GET /metrics") != std::string::npos) {
                            send_metrics();
                        } else {
                            do_read();
                        }
                    }
                });
        }

        void send_metrics() {
            auto stats = latency_tracker_.get_stats();
            std::string response =
                "HTTP/1.1 200 OK\r\n"
                "Content-Type: application/json\r\n"
                "Connection: close\r\n"
                "\r\n"
                "{\"min_latency_ns\":" + std::to_string(static_cast<int64_t>(stats.min)) +
                ",\"avg_latency_ns\":" + std::to_string(static_cast<int64_t>(stats.avg)) +
                ",\"p99_latency_ns\":" + std::to_string(static_cast<int64_t>(stats.p99)) +
                ",\"max_latency_ns\":" + std::to_string(static_cast<int64_t>(stats.max)) +
                ",\"samples\":" + std::to_string(latency_tracker_.get_sample_count()) + "}";

            auto self(shared_from_this());
            boost::asio::async_write(socket_, boost::asio::buffer(response),
                [this, self](boost::system::error_code ec, std::size_t /*length*/) {
                    if (!ec) {
                        socket_.close();
                    }
                });
        }

        boost::asio::ip::tcp::socket socket_;
        LatencyTracker& latency_tracker_;
        enum { max_length = 1024 };
        char data_[max_length];
    };
};

// Helper to get sample count from LatencyTracker
size_t LatencyTracker::get_sample_count() {
    std::lock_guard<std::mutex> lock(mutex_);
    return latencies_.size();
}

int main() {
    try {
        // Configuration
        const int num_workers = std::thread::hardware_concurrency();
        const short listen_port = 12345;
        const short metrics_port = 8080;

        // Create components
        boost::asio::io_context io_context;
        LockFreeQueue<Message> incoming_queue;
        LockFreeQueue<Message> outgoing_queue;
        LatencyTracker latency_tracker;
        Router router(10); // 10 destinations

        // Create network server
        NetworkServer server(io_context, listen_port, incoming_queue, latency_tracker);

        // Create metrics server
        MetricsServer metrics_server(io_context, metrics_port, latency_tracker);

        // Create and start worker threads
        std::vector<std::thread> workers;
        std::vector<MessageProcessor> processors;
        for (int i = 0; i < num_workers; ++i) {
            processors.emplace_back(incoming_queue, outgoing_queue, router, latency_tracker);
            workers.emplace_back([&processor = processors.back()]() { processor.run(); });
        }

        // Run the I/O context in a separate thread
        std::thread io_thread([&io_context]() { io_context.run(); });

        std::cout << "High-frequency messaging system started\n";
        std::cout << "  - Send messages to port " << listen_port << "\n";
        std::cout << "  - Get metrics at http://localhost:" << metrics_port << "/metrics\n";
        std::cout << "  - Using " << num_workers << " worker threads\n";
        std::cout << "Press Ctrl+C to stop...\n";

