use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::time::{Duration, Instant};

pub struct LatencyMonitor {
    total_latency: AtomicU64,
    message_count: AtomicU64,
    max_latency: AtomicU64,
    min_latency: AtomicU64,
    last_reset: Instant,
}

impl LatencyMonitor {
    pub fn new() -> Self {
        Self {
            total_latency: AtomicU64::new(0),
            message_count: AtomicU64::new(0),
            max_latency: AtomicU64::new(0),
            min_latency: AtomicU64::new(u64::MAX),
            last_reset: Instant::now(),
        }
    }

    pub fn record_latency(&self, latency: u64) {
        self.total_latency.fetch_add(latency, Ordering::Relaxed);
        self.message_count.fetch_add(1, Ordering::Relaxed);

        let current_max = self.max_latency.load(Ordering::Relaxed);
        if latency > current_max {
            self.max_latency.store(latency, Ordering::Relaxed);
        }

        let current_min = self.min_latency.load(Ordering::Relaxed);
        if latency < current_min {
            self.min_latency.store(latency, Ordering::Relaxed);
        }
    }

    pub fn get_stats(&self) -> (f64, u64, u64, u64) {
        let count = self.message_count.load(Ordering::Relaxed);
        if count == 0 {
            return (0.0, 0, 0, 0);
        }

        let total = self.total_latency.load(Ordering::Relaxed);
        let avg = total as f64 / count as f64;

        let max = self.max_latency.load(Ordering::Relaxed);
        let min = self.min_latency.load(Ordering::Relaxed);

        (avg, max, min, count)
    }

    pub fn reset(&self) {
        self.total_latency.store(0, Ordering::Relaxed);
        self.message_count.store(0, Ordering::Relaxed);
        self.max_latency.store(0, Ordering::Relaxed);
        self.min_latency.store(u64::MAX, Ordering::Relaxed);
        self.last_reset = Instant::now();
    }

    pub fn uptime(&self) -> Duration {
        self.last_reset.elapsed()
    }
}
