                let latency = start_time.elapsed().as_micros() as u64;
                latency_monitor.record_latency(latency);
                metrics::MESSAGES_PROCESSED.inc();

                // Simulate some processing time
                tokio::time::sleep(std::time::Duration::from_micros(1)).await;
            }
