#[instrument(skip_all)]
async fn handle_connection(
    mut socket: TcpStream,
    tx: mpsc::Sender<message::Message>,
    queue: Arc<queue::MessageQueue>,
) -> Result<(), Box<dyn Error>> {
    let mut buf = [0; 8192];
    let mut message_id = 0u64;

    loop {
        let n = match socket.read(&mut buf).await {
            Ok(n) if n == 0 => break, // Connection closed
            Ok(n) => n,
            Err(e) => {
                error!("Failed to read from socket: {}", e);
                break;
            }
        };

        // Create message with unique ID and current timestamp
        let message = message::Message::new(
            message_id,
            Bytes::copy_from_slice(&buf[..n]),
            format!("{}:{}", socket.peer_addr()?, message_id),
        );

        // Try to enqueue the message
        if queue.enqueue(message.clone()).is_ok() {
            if tx.send(message).await.is_err() {
                error!("Failed to send message to worker");
                break;
            }
            metrics::MESSAGES_RECEIVED.inc();
            metrics::QUEUE_SIZE.set(queue.queue.len() as i64);
        } else {
            error!("Message queue is full");
            break;
        }

        message_id = message_id.wrapping_add(1);
    }

    Ok(())
}
```

