// Lock-free queue implementation (simplified for demonstration)
template <typename T>
class LockFreeQueue {
private:
    struct Node {
        T data;
        std::atomic<Node*> next;
        Node() : next(nullptr) {}
    };

    std::atomic<Node*> head;
    std::atomic<Node*> tail;

public:
    LockFreeQueue() : head(new Node()), tail(head.load()) {}

    ~LockFreeQueue() {
        while (Node* old_head = head.load()) {
            head.store(old_head->next.load());
            delete old_head;
        }
    }

    void enqueue(const T& item) {
        Node* new_node = new Node();
        new_node->data = item;
        new_node->next.store(nullptr);

        Node* current_tail = tail.load();
        while (!tail.compare_exchange_weak(current_tail, new_node)) {
            // Retry until successful
        }
        current_tail->next.store(new_node);
    }

    bool dequeue(T& item) {
        Node* current_head = head.load();
        Node* next_head = current_head->next.load();

        if (!next_head) {
            return false; // Queue is empty
        }

        if (head.compare_exchange_strong(current_head, next_head)) {
            item = next_head->data;
            delete current_head;
            return true;
        }
        return false;
    }
};

