    // Random number generator for message types
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 99);

    // Warmup phase (fill the pipeline)
    std::cout << "Starting warmup phase..." << std::endl;
    for (int i = 0; i < warmup_messages; ++i) {
        Message msg;
        msg.payload = "Warmup Message " + std::to_string(i);
        msg.timestamp = std::chrono::high_resolution_clock::now();
        msg.message_type = dis(gen);
        queue.enqueue(msg);
    }

    // Main message generation phase
    std::cout << "Starting main message generation..." << std::endl;
    auto start_time = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < num_messages; ++i) {
        Message msg;
        msg.payload = "Message " + std::to_string(i);
        msg.timestamp = std::chrono::high_resolution_clock::now();
        msg.message_type = dis(gen);
        queue.enqueue(msg);
    }

    // Wait for all messages to be processed
    std::cout << "Waiting for messages to be processed..." << std::endl;
    auto last_message_time = std::chrono::high_resolution_clock::now();
    while (true) {
        bool all_processed = true;
        for (const auto& latencies : all_latencies) {
            if (latencies.size() < (num_messages / num_threads)) {
                all_processed = false;
                break;
            }
        }

        if (all_processed) break;

        // Check if we've waited too long (timeout)
        auto now = std::chrono::high_resolution_clock::now();
        if (std::chrono::duration_cast<std::chrono::seconds>(now - last_message_time).count() > 5) {
            std::cerr << "Warning: Timeout waiting for messages to process" << std::endl;
            break;
        }

        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }

    auto end_time = std::chrono::high_resolution_clock::now();
    running.store(false);

    // Join all threads
    for (auto& thread : threads) {
        thread.join();
    }

    // Combine all latency measurements
    std::vector<std::chrono::nanoseconds> all_latencies_combined;
    for (const auto& latencies : all_latencies) {
        all_latencies_combined.insert(all_latencies_combined.end(),
                                    latencies.begin(),
                                    latencies.end());
    }

    // Calculate statistics
    if (!all_latencies_combined.empty()) {
        auto min_latency = *std::min_element(all_latencies_combined.begin(), all_latencies_combined.end());
        auto max_latency = *std::max_element(all_latencies_combined.begin(), all_latencies_combined.end());
        auto avg_latency = std::accumulate(all_latencies_combined.begin(),
                                         all_latencies_combined.end(),
                                         std::chrono::nanoseconds(0)) / all_latencies_combined.size();

        auto total_time = std::chrono::duration_cast<std::chrono::milliseconds>(end_time - start_time);
        double throughput = (num_messages * 1000.0) / total_time.count(); // messages per second

        // Print results
        std::cout << "\nSystem Performance Report:" << std::endl;
        std::cout << "=========================" << std::endl;
        std::cout << "Total messages processed: " << num_messages << std::endl;
        std::cout << "Total processing time: " << total_time.count() << " ms" << std::endl;
        std::cout << "Throughput: " << throughput << " messages/second" << std::endl;
        std::cout << "\nLatency Statistics (nanoseconds):" << std::endl;
        std::cout << "Min: " << min_latency.count() << std::endl;
        std::cout << "Max: " << max_latency.count() << std::endl;
        std::cout << "Avg: " << avg_latency.count() << std::endl;

        // Calculate 99th percentile latency
        std::sort(all_latencies_combined.begin(), all_latencies_combined.end());
        auto p99_latency = all_latencies_combined[(all_latencies_combined.size() * 99) / 100];
        std::cout << "99th percentile: " << p99_latency.count() << std::endl;
    } else {
        std::cerr << "No latency measurements collected!" << std::endl;
    }

    return 0;
}
