// Message structure
struct Message {
    uint64_t id;
    std::string payload;
    std::chrono::high_resolution_clock::time_point enqueue_time;
    std::chrono::high_resolution_clock::time_point dequeue_time;
};

// Lock-free queue implementation
class LockFreeQueue {
private:
    struct Node {
        Message msg;
        std::atomic<Node*> next;
        Node() : next(nullptr) {}
    };

    std::atomic<Node*> head;
    std::atomic<Node*> tail;

public:
    LockFreeQueue() : head(new Node()), tail(head.load()) {}

    ~LockFreeQueue() {
        while (Node* old_head = head.load()) {
            head.store(old_head->next.load());
            delete old_head;
        }
    }

    void enqueue(Message msg) {
        Node* new_node = new Node();
        new_node->msg = msg;
        new_node->next.store(nullptr);

        Node* current_tail = tail.load();
        while (!tail.compare_exchange_weak(current_tail, new_node)) {
            // Tail was changed by another thread, retry
        }
        current_tail->next.store(new_node);
    }

    bool dequeue(Message& msg) {
        Node* current_head = head.load();
        Node* next_head = current_head->next.load();

        if (next_head == nullptr) {
            return false; // Queue is empty
        }

        if (head.compare_exchange_weak(current_head, next_head)) {
            msg = next_head->msg;
            delete current_head;
            return true;
        }
        return false;
    }
};

// Worker thread function
void worker_thread(LockFreeQueue& queue, std::atomic<bool>& running, std::vector<std::chrono::nanoseconds>& latencies) {
    Message msg;
    while (running.load()) {
        if (queue.dequeue(msg)) {
            // Simulate processing time
            std::this_thread::sleep_for(std::chrono::nanoseconds(100));

            // Record dequeue time and calculate latency
            msg.dequeue_time = std::chrono::high_resolution_clock::now();
            auto latency = std::chrono::duration_cast<std::chrono::nanoseconds>(msg.dequeue_time - msg.enqueue_time);
            latencies.push_back(latency);
        } else {
            // Queue is empty, yield to avoid busy waiting
            std::this_thread::yield();
        }
    }
}

// Latency statistics
void print_latency_stats(const std::vector<std::chrono::nanoseconds>& latencies) {
    if (latencies.empty()) {
        std::cout << "No latency data available." << std::endl;
        return;
    }

    std::vector<long> latencies_ns;
    for (const auto& latency : latencies) {
        latencies_ns.push_back(latency.count());
    }

    auto min_it = std::min_element(latencies_ns.begin(), latencies_ns.end());
    auto max_it = std::max_element(latencies_ns.begin(), latencies_ns.end());
    double avg = std::accumulate(latencies_ns.begin(), latencies_ns.end(), 0.0) / latencies_ns.size();

    std::cout << "Latency Statistics:" << std::endl;
    std::cout << "  Min: " << *min_it << " ns" << std::endl;
    std::cout << "  Max: " << *max_it << " ns" << std::endl;
    std::cout << "  Avg: " << avg << " ns" << std::endl;
}

