// monitor.rs
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;

pub struct LatencyMonitor {
    total_latency: AtomicU64,
    message_count: AtomicU64,
    max_latency: AtomicU64,
}

impl LatencyMonitor {
    pub fn new() -> Self {
        Self {
            total_latency: AtomicU64::new(0),
            message_count: AtomicU64::new(0),
            max_latency: AtomicU64::new(0),
        }
    }

    pub fn record_latency(&self, latency: u64) {
        self.total_latency.fetch_add(latency, Ordering::Relaxed);
        self.message_count.fetch_add(1, Ordering::Relaxed);
        let current_max = self.max_latency.load(Ordering::Relaxed);
        if latency > current_max {
            self.max_latency.store(latency, Ordering::Relaxed);
        }
    }

    pub fn get_average_latency(&self) -> f64 {
        let count = self.message_count.load(Ordering::Relaxed);
        if count == 0 {
            0.0
        } else {
            let total = self.total_latency.load(Ordering::Relaxed);
            total as f64 / count as f64
        }
    }

    pub fn get_max_latency(&self) -> u64 {
        self.max_latency.load(Ordering::Relaxed)
    }
}
