// Lock-free queue (simplified for demonstration)
template <typename T>
class LockFreeQueue {
private:
    struct Node {
        T data;
        std::atomic<Node*> next;
        Node() : next(nullptr) {}
    };

    std::atomic<Node*> head;
    std::atomic<Node*> tail;

public:
    LockFreeQueue() : head(new Node()), tail(head.load()) {}

    ~LockFreeQueue() {
        while (Node* old_head = head.load()) {
            head.store(old_head->next.load());
            delete old_head;
        }
    }

    void enqueue(const T& item) {
        Node* new_node = new Node();
        new_node->data = item;
        new_node->next.store(nullptr);

        Node* current_tail = tail.load();
        while (!tail.compare_exchange_weak(current_tail, new_node)) {
            // Retry until successful
        }
        current_tail->next.store(new_node);
    }

    bool dequeue(T& item) {
        Node* current_head = head.load();
        Node* next_head = current_head->next.load();

        if (!next_head) {
            return false; // Queue is empty
        }

        if (head.compare_exchange_strong(current_head, next_head)) {
            item = next_head->data;
            delete current_head;
            return true;
        }
        return false;
    }
};

// Worker thread function
void worker_thread(LockFreeQueue<Message>& queue, std::atomic<bool>& running, std::vector<std::chrono::nanoseconds>& latencies) {
    Message msg;
    while (running.load() || queue.dequeue(msg)) {
        auto start = std::chrono::high_resolution_clock::now();
        // Simulate processing time
        std::this_thread::sleep_for(std::chrono::nanoseconds(100)); // Simulate work
        auto end = std::chrono::high_resolution_clock::now();

        // Calculate latency
        auto latency = std::chrono::duration_cast<std::chrono::nanoseconds>(end - msg.timestamp);
        latencies.push_back(latency);
    }
}

int main() {
    const int num_threads = 4; // Number of worker threads
    const int num_messages = 1000000; // Number of messages to process

    LockFreeQueue<Message> queue;
    std::atomic<bool> running(true);
    std::vector<std::thread> threads;
    std::vector<std::vector<std::chrono::nanoseconds>> all_latencies(num_threads);

    // Start worker threads
    for (int i = 0; i < num_threads; ++i) {
        threads.emplace_back(worker_thread, std::ref(queue), std::ref(running), std::ref(all_latencies[i]));
    }

    // Generate and enqueue messages
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 9);

    for (int i = 0; i < num_messages; ++i) {
        Message msg;
        msg.payload = "Message " + std::to_string(i);
        msg.timestamp = std::chrono::high_resolution_clock::now();
        msg.message_type = dis(gen); // Random message type for routing
        queue.enqueue(msg);
    }

    // Wait for all messages to be processed
    while (true) {
        bool all_empty = true;
        for (int i = 0; i < num_threads; ++i) {
            if (all_latencies[i].size() < num_messages / num_threads) {
                all_empty = false;
                break;
            }
        }
        if (all_empty) break;
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }

    running.store(false);

    // Join threads
    for (auto& thread : threads) {
        thread.join();
    }

    // Calculate and print latency statistics
    std::vector<std::chrono::nanoseconds> all_latencies_combined;
    for (const auto& latencies : all_latencies) {
        all_latencies_combined.insert(all_latencies_combined.end(), latencies.begin(), latencies.end());
    }

    if (!all_latencies_combined.empty()) {
        auto min_latency = *std::min_element(all_latencies_combined.begin(), all_latencies_combined.end());
        auto max_latency = *std::max_element(all_latencies_combined.begin(), all_latencies_combined.end());
        auto avg_latency = std::accumulate(all_latencies_combined.begin(), all_latencies_combined.end(), std::chrono::nanoseconds(0)) / all_latencies_combined.size();

        std::cout << "Latency Statistics:" << std::endl;
