        for (i, &count) in self.histogram.iter().enumerate() {
            let range = match i {
                0 => "0-99", 1 => "100-499", 2 => "500-999", 3 => "1-2ms",
                4 => "2-5ms", 5 => "5-10ms", 6 => "10-20ms", 7 => "20-50ms",
                8 => "50-100ms", 9 => ">100ms", _ => unreachable!()
            };
            println!("  {}: {}", range, count);
        }
    }
}

