use std::sync::Arc;
use tokio::{
    net::{TcpListener, TcpStream},
    sync::mpsc,
    io::{AsyncReadExt, AsyncWriteExt},
};
use crate::message::Message;
use prometheus::{IntCounter, IntGauge, register_int_counter, register_int_gauge};

pub struct Router {
    pub metrics: Arc<RouterMetrics>,
    pub tx: mpsc::Sender<Message>,  // Forward messages to monitor
}

pub struct RouterMetrics {
    pub messages_received: IntCounter,
    pub messages_forwarded: IntCounter,
    pub current_connections: IntGauge,
    pub avg_latency_ns: IntGauge,
}

impl Router {
    pub fn new() -> (Self, Arc<RouterMetrics>) {
        let metrics = Arc::new(RouterMetrics {
            messages_received: register_int_counter!("router_messages_received", "Total messages received").unwrap(),
            messages_forwarded: register_int_counter!("router_messages_forwarded", "Total messages forwarded").unwrap(),
            current_connections: register_int_gauge!("router_connections", "Current active connections").unwrap(),
            avg_latency_ns: register_int_gauge!("router_avg_latency_ns", "Average processing latency (ns)").unwrap(),
        });

        let (tx, mut rx) = mpsc::channel::<Message>(100_000);
        let router = Self { metrics: metrics.clone(), tx };

        // Spawn a task to forward messages to the monitor
        tokio::spawn(async move {
            while let Some(msg) = rx.recv().await {
                // In a real system, forward to subscribers here
                metrics.messages_forwarded.inc();
            }
        });

        (router, metrics)
    }

    pub async fn run(&self, addr: &str) -> std::io::Result<()> {
        let listener = TcpListener::bind(addr).await?;
        println!("Router listening on {}", addr);

        loop {
            let (socket, _) = listener.accept().await?;
            self.metrics.current_connections.inc();
            let router = self.clone();
            tokio::spawn(async move {
                if let Err(e) = router.handle_connection(socket).await {
                    eprintln!("Connection error: {}", e);
                }
                router.metrics.current_connections.dec();
            });
        }
    }

    async fn handle_connection(&self, mut socket: TcpStream) -> std::io::Result<()> {
        let mut buf = [0u8; 1024];
        loop {
            let n = socket.read(&mut buf).await?;
            if n == 0 { break; }  // Connection closed

            if let Some(msg) = Message::deserialize(&buf[..n]) {
                self.metrics.messages_received.inc();

                // Simulate processing delay (remove in production)
                tokio::time::sleep(std::time::Duration::from_nanos(100)).await;

                // Forward to monitor (in a real system, route to subscribers)
                let _ = self.tx.send(msg).await;
            }
        }
        Ok(())
    }
}

impl Clone for Router {
    fn clone(&self) -> Self {
        Self {
            metrics: self.metrics.clone(),
            tx: self.tx.clone(),
        }
    }
}
