```rust
use std::sync::Arc;
use tokio::sync::mpsc;
use crate::message::Message;
use prometheus::{IntCounter, Histogram, register_int_counter, register_histogram};
use hyper::{Body, Request, Response, Server};
use hyper::service::{make_service_fn, service_fn};

pub struct Monitor {
    pub metrics: Arc<MonitorMetrics>,
    pub rx: mpsc::Receiver<Message>,
}

pub struct MonitorMetrics {
    pub messages_processed: IntCounter,
    pub latency_histogram: Histogram,
}

impl Monitor {
    pub fn new(rx: mpsc::Receiver<Message>) -> (Self, Arc<MonitorMetrics>) {
        let metrics = Arc::new(MonitorMetrics {
            messages_processed: register_int_counter!("monitor_messages_processed", "Total messages processed").unwrap(),
            latency_histogram: register_histogram!(
                "monitor_message_latency_ns",
                "Latency of message processing (ns)",
                vec![100.0, 1_000.0, 10_000.0, 100_000.0, 1_000_000.0]
            ).unwrap(),
        });

        let monitor = Self { metrics: metrics.clone(), rx };
        (monitor, metrics)
    }

    pub async fn run(&self, http_addr: &str) -> std::io::Result<()> {
        let addr = http_addr.parse().unwrap();
        let make_svc = make_service_fn(|_conn| {
            let metrics = self.metrics.clone();
            async move {
                Ok::<_, hyper::Error>(service_fn(move |req: Request<Body>| {
                    metrics.messages_processed.inc();
                    async move {
                        // Expose Prometheus metrics
                        let body = prometheus::default_handler().call(req).await?;
                        Ok::<_, hyper::Error>(body)
                    }
                }))
            }
        });

        let server = Server::bind(&addr).serve(make_svc);
        println!("Monitor running on http://{}", http_addr);
        server.await
    }

    pub async fn process_messages(&self) {
        while let Some(msg) = self.rx.recv().await {
            let now = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos() as u64;
            let latency_ns = now - msg.timestamp_ns;
            self.metrics.latency_histogram.observe(latency_ns as f64);
        }
    }
}
