    pub router_addr: String,
    #[clap(short, long, default_value = "1000")]
    pub messages: usize,
    #[clap(short, long, default_value = "100")]
    pub payload_size: usize,
}

pub async fn run_client(args: ClientArgs) -> std::io::Result<()> {
    let mut stream = TcpStream::connect(&args.router_addr).await?;
    println!("Connected to router at {}", args.router_addr);

    let mut total_latency = 0u128;
    let mut min_latency = u128::MAX;
    let mut max_latency = 0u128;

    for i in 0..args.messages {
        let payload = vec![b'A' + (i % 26) as u8; args.payload_size];
        let msg = Message::new(payload);
        let start = Instant::now();

        // Send message
        stream.write_all(&msg.serialize()).await?;

        // Wait for echo (in a real system, this would be a response from a subscriber)
        let mut buf = vec![0u8; 1024];
        let n = stream.read(&mut buf).await?;
        if n == 0 { break; }

        let latency = start.elapsed().as_nanos();
        total_latency += latency;
        min_latency = min_latency.min(latency);
        max_latency = max_latency.max(latency);

        if i % 100 == 0 {
            println!("Sent {} messages...", i);
        }
    }

    let avg_latency = total_latency / args.messages as u128;
    println!("Benchmark results:");
    println!("- Messages sent: {}", args.messages);
    println!("- Avg latency: {} ns", avg_latency);
    println!("- Min latency: {} ns", min_latency);
    println!("- Max latency: {} ns", max_latency);
    println!("- Throughput: {:.2} msg/sec",
        args.messages as f64 / (total_latency as f64 / 1_000_000_000.0));

    Ok(())
}
