### **Minimal High-Frequency Messaging System**
```cpp
#include <boost/asio.hpp>
#include <chrono>
#include <deque>
#include <iostream>
#include <mutex>
#include <thread>

namespace asio = boost::asio;
using asio::ip::tcp;
using namespace std::chrono;

// Fixed-size message buffer (64-byte aligned for cache efficiency)
constexpr size_t MAX_MESSAGE_SIZE = 1024;
struct alignas(64) MessageBuffer {
    char data[MAX_MESSAGE_SIZE];
    size_t size;
    time_point<system_clock> receive_time;
    time_point<system_clock> send_time;
};

// Thread-safe latency statistics
class LatencyBuffer {
public:
    void add_latency(double latency_ms) {
        std::lock_guard<std::mutex> lock(mutex_);
        latencies_.push_back(latency_ms);
        if (latencies_.size() > 1'000'000) latencies_.pop_front(); // Keep last 1M samples
    }

    void print_stats() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (latencies_.empty()) return;

        double sum = 0, max_latency = 0;
        for (auto lat : latencies_) {
            sum += lat;
            if (lat > max_latency) max_latency = lat;
        }
        size_t count = latencies_.size();
        std::cout << "Messages/sec: " << count << " | "
                  << "Avg latency: " << (sum / count) << " ms | "
                  << "Max latency: " << max_latency << " ms\n";
        latencies_.clear(); // Reset for next period
    }

private:
    std::deque<double> latencies_;
    std::mutex mutex_;
};

LatencyBuffer latency_buffer;

// TCP Server (handles incoming connections and messages)
class TcpServer {
public:
    TcpServer(asio::io_context& io_context, short port)
        : io_context_(io_context),
          acceptor_(io_context, tcp::endpoint(tcp::v4(), port)) {
        start_accept();
    }

private:
    void start_accept() {
        auto socket = std::make_shared<tcp::socket>(io_context_);
        acceptor_.async_accept(*socket, [this, socket](const asio::error_code& error) {
            if (!error) {
                std::cout << "New connection from " << socket->remote_endpoint() << "\n";
                start_read(socket);
            }
            start_accept(); // Accept next connection
        });
    }

    void start_read(std::shared_ptr<tcp::socket> socket) {
        auto buffer = std::make_shared<MessageBuffer>();
        socket->async_read_some(
            asio::buffer(buffer->data, MAX_MESSAGE_SIZE),
            [this, socket, buffer](const asio::error_code& error, size_t bytes_transferred) {
                if (!error && bytes_transferred > 0) {
                    buffer->size = bytes_transferred;
                    buffer->receive_time = system_clock::now();

                    // Simulate message processing (e.g., routing logic)
                    buffer->send_time = system_clock::now();
                    auto latency = duration_cast<microseconds>(
                        buffer->send_time - buffer->receive_time
                    ).count() / 1000.0; // Convert to milliseconds
                    latency_buffer.add_latency(latency);

                    // Echo back the message (simulate forwarding)
                    asio::async_write(
                        *socket,
                        asio::buffer(buffer->data, buffer->size),
                        [socket](const asio::error_code&, size_t) {
                            // Connection stays open for pipelining
                        }
                    );
                }
                start_read(socket); // Read next message
            }
        );
    }

    asio::io_context& io_context_;
    tcp::acceptor acceptor_;
};

// Statistics printer (runs in a separate thread)
void print_stats() {
    while (true) {
        std::this_thread::sleep_for(seconds(1));
        latency_buffer.print_stats();
    }
}

int main() {
    try {
        asio::io_context io_context;
        TcpServer server(io_context, 12345);

        // Start stats thread
        std::thread stats_thread(print_stats);

        std::cout << "Server running on port 12345...\n";
        io_context.run(); // Blocks until stopped
        stats_thread.join();
    } catch (std::exception& e) {
        std::cerr << "Exception: " << e.what() << "\n";
        return 1;
    }
    return 0;
}
```

