use std::time::{Instant, Duration};
use tokio::sync::mpsc;
use tokio::time;
use metrics_exporter_prometheus::PrometheusBuilder;
use metrics::{Counter, Histogram};

// Message structure with timestamp for latency tracking
#[derive(Debug, Clone)]
struct Message {
    id: u64,
    payload: String,
    timestamp: Instant,
}

// High-throughput message producer
struct Producer {
    tx: mpsc::Sender<Message>,
    message_count: u64,
}

impl Producer {
    fn new(tx: mpsc::Sender<Message>) -> Self {
        Producer {
            tx,
            message_count: 0,
        }
    }

    async fn produce(&mut self) {
        loop {
            self.message_count += 1;
            let message = Message {
                id: self.message_count,
                payload: format!("Message {}", self.message_count),
                timestamp: Instant::now(),
            };

            if self.tx.send(message).await.is_err() {
                eprintln!("Producer channel closed");
                break;
            }

            // Simulate ~1M messages/sec (1μs between messages)
            time::sleep(Duration::from_micros(1)).await;
        }
    }
}

// Message router with simple routing logic
struct Router {
    rx: mpsc::Receiver<Message>,
    tx1: mpsc::Sender<Message>,
    tx2: mpsc::Sender<Message>,
}

impl Router {
    fn new(
        rx: mpsc::Receiver<Message>,
        tx1: mpsc::Sender<Message>,
        tx2: mpsc::Sender<Message>,
    ) -> Self {
        Router { rx, tx1, tx2 }
    }

    async fn route(&mut self) {
        while let Some(message) = self.rx.recv().await {
            // Simple routing: even IDs to consumer1, odd to consumer2
            if message.id % 2 == 0 {
                let _ = self.tx1.send(message).await;
            } else {
                let _ = self.tx2.send(message).await;
            }
        }
    }
}

// Message consumer with latency monitoring
struct Consumer {
    rx: mpsc::Receiver<Message>,
    latency_histogram: Histogram,
    messages_processed: Counter,
}

impl Consumer {
    fn new(
        rx: mpsc::Receiver<Message>,
        latency_histogram: Histogram,
        messages_processed: Counter,
    ) -> Self {
        Consumer {
            rx,
            latency_histogram,
            messages_processed,
        }
    }

    async fn consume(&mut self) {
        while let Some(message) = self.rx.recv().await {
            let latency = message.timestamp.elapsed();
            self.latency_histogram.record(latency.as_secs_f64());
            self.messages_processed.increment(1);

            // Simulate message processing (1μs)
            time::sleep(Duration::from_micros(1)).await;
        }
    }
}

