#pragma once
#include <queue>
#include <mutex>
#include <condition_variable>
#include <boost/lockfree/queue.hpp>
#include "message.hpp"

class MessageRouter {
public:
    void routeMessage(const Message& msg) {
        // In a real system, this would route to different queues based on some criteria
        // For simplicity, we'll just push to a single queue
        message_queue.push(msg);
        cv.notify_one();
    }

    bool tryGetMessage(Message& msg) {
        return message_queue.pop(msg);
    }

    void waitForMessage(Message& msg) {
        while (!message_queue.pop(msg)) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock);
        }
    }

private:
    boost::lockfree::queue<Message, boost::lockfree::fixed_sized<false>> message_queue{1024};
    std::mutex mutex;
    std::condition_variable cv;
};
