class Session : public std::enable_shared_from_this<Session> {
public:
    Session(tcp::socket socket, MessageRouter& router, LatencyMonitor& monitor)
        : socket_(std::move(socket)), router_(router), monitor_(monitor) {}

    void start() {
        do_read();
    }

private:
    void do_read() {
        auto self(shared_from_this());
        socket_.async_read_some(boost::asio::buffer(data_, max_length),
            [this, self](boost::system::error_code ec, std::size_t length) {
                if (!ec) {
                    // Parse message (simplified - in real system would use proper protocol)
                    Message msg;
                    msg.payload = std::string(data_, length);
                    msg.id = next_id_++;
                    msg.received_time = std::chrono::high_resolution_clock::now();

                    // Record reception
                    monitor_.recordReceived(msg.id);
                    monitor_.incrementMessageCount();

                    // Route the message
                    router_.routeMessage(msg);

                    // Continue reading
                    do_read();
                }
            });
    }

    tcp::socket socket_;
    MessageRouter& router_;
    LatencyMonitor& monitor_;
    enum { max_length = 1024 };
    char data_[max_length];
    static std::atomic<uint64_t> next_id_;
};

std::atomic<uint64_t> Session::next_id_{0};

class Server {
public:
    Server(boost::asio::io_context& io_context, short port, MessageRouter& router, LatencyMonitor& monitor)
        : io_context_(io_context),
          acceptor_(io_context, tcp::endpoint(tcp::v4(), port)),
          router_(router),
          monitor_(monitor) {
        do_accept();
    }

private:
    void do_accept() {
        acceptor_.async_accept(
            [this](boost::system::error_code ec, tcp::socket socket) {
                if (!ec) {
                    std::make_shared<Session>(std::move(socket), router_, monitor_)->start();
                }
                do_accept();
            });
    }

    boost::asio::io_context& io_context_;
    tcp::acceptor acceptor_;
    MessageRouter& router_;
    LatencyMonitor& monitor_;
};

void workerThread(MessageRouter& router, LatencyMonitor& monitor) {
    Message msg;
    while (true) {
        router.waitForMessage(msg);
        msg.processed_time = std::chrono::high_resolution_clock::now();

        // Simulate processing (in real system would do actual processing)
        // std::this_thread::sleep_for(std::chrono::microseconds(1));

        // Route to output (simplified - in real system would have multiple outputs)
        monitor.recordProcessed(msg.id);
        monitor.recordSent(msg.id);
    }
}

int main() {
    try {
        boost::asio::io_context io_context;
        short port = 12345;

        MessageRouter router;
        LatencyMonitor monitor;

        // Start server
        Server server(io_context, port, router, monitor);

        // Start worker threads (one per CPU core)
        const int num_workers = std::thread::hardware_concurrency();
        std::vector<std::thread> workers;
        for (int i = 0; i < num_workers; ++i) {
            workers.emplace_back(workerThread, std::ref(router), std::ref(monitor));
        }

        // Start monitoring thread
        std::thread monitor_thread([&monitor]() {
            while (true) {
                std::this_thread::sleep_for(std::chrono::seconds(1));
                monitor.printStats();
            }
        });

        std::cout << "High-frequency messaging server started on port " << port << "\n";
        std::cout << "Using " << num_workers << " worker threads\n";
        std::cout << "Ready to accept connections...\n";

        io_context.run();

        monitor_thread.join();
        for (auto& t : workers) {
            t.join();
        }
    } catch (std::exception& e) {
        std::cerr << "Exception: " << e.what() << "\n";
        return 1;
    }

    return 0;
}
