    total_messages: usize,
    total_latency: usize, // Total latency in microseconds
}

impl LatencyMonitor {
    fn new() -> Self {
        LatencyMonitor {
            histogram: vec![0; 10], // 10 buckets for latency ranges
            total_messages: 0,
            total_latency: 0,
        }
    }

    fn record_latency(&mut self, latency: Duration) {
        let micros = latency.as_micros() as usize;
        let bucket = if micros < 100 {
            0
        } else if micros < 500 {
            1
        } else if micros < 1000 {
            2
        } else if micros < 2000 {
            3
        } else if micros < 5000 {
            4
        } else if micros < 10000 {
            5
        } else if micros < 20000 {
            6
        } else if micros < 50000 {
            7
        } else if micros < 100000 {
            8
        } else {
            9
        };
        self.histogram[bucket] += 1;
        self.total_messages += 1;
        self.total_latency += micros;
    }

    fn print_stats(&self) {
        println!("Total messages processed: {}", self.total_messages);
        if self.total_messages > 0 {
            println!("Average latency: {} microseconds", self.total_latency / self.total_messages);
        } else {
            println!("Average latency: N/A");
        }
        println!("Latency histogram (microseconds):");
        for (i, count) in self.histogram.iter().enumerate() {
            let lower = match i {
                0 => "0-100",
                1 => "100-500",
                2 => "500-1000",
                3 => "1000-2000",
                4 => "2000-5000",
                5 => "5000-10000",
                6 => "10000-20000",
                7 => "20000-50000",
                8 => "50000-100000",
                9 => ">100000",
                _ => unreachable!(),
            };
            println!("  {}: {}", lower, count);
        }
    }
}

// Router that distributes messages to workers
struct Router {
    sender: mpsc::Sender<Message>,
    monitor: Arc<tokio::sync::Mutex<LatencyMonitor>>,
}

impl Router {
    fn new(monitor: Arc<tokio::sync::Mutex<LatencyMonitor>>, num_workers: usize) -> Self {
        let (sender, mut receiver) = mpsc::channel(num_workers * 2); // Buffered channel
        for _ in 0..num_workers {
            let mut receiver = receiver.clone();
            let monitor = monitor.clone();
            tokio::spawn(async move {
                while let Some(message) = receiver.recv().await {
                    let start = Instant::now();
                    // Simulate processing by sleeping for a short duration
                    // In a real system, this would be actual message processing
                    tokio::time::sleep(Duration::from_micros(10)).await; // Simulate 10 microseconds of work
                    let latency = start.elapsed();
                    let mut monitor = monitor.lock().await;
                    monitor.record_latency(latency);
                }
            });
        }
        Router { sender, monitor }
    }

    async fn send(&self, message: Message) {
        self.sender.send(message).await.unwrap();
    }
}

