```cpp
#pragma once
#include <chrono>
#include <vector>
#include <cstdint>

class LatencyMonitor {
public:
    void recordReceived(uint64_t id) {
        received_times[id] = std::chrono::high_resolution_clock::now();
    }

    void recordProcessed(uint64_t id) {
        processed_times[id] = std::chrono::high_resolution_clock::now();
    }

    void recordSent(uint64_t id) {
        auto now = std::chrono::high_resolution_clock::now();
        sent_times[id] = now;

        // Calculate latencies
        auto received = received_times[id];
        auto processed = processed_times[id];

        auto end_to_end = std::chrono::duration_cast<std::chrono::nanoseconds>(now - received).count();
        auto processing = std::chrono::duration_cast<std::chrono::nanoseconds>(processed - received).count();
        auto queueing = std::chrono::duration_cast<std::chrono::nanoseconds>(now - processed).count();

        // Update statistics
        total_messages++;
        total_latency += end_to_end;
        total_processing += processing;
        total_queueing += queueing;

        if (end_to_end < min_latency || total_messages == 1) min_latency = end_to_end;
        if (end_to_end > max_latency) max_latency = end_to_end;
    }

    void printStats() {
        if (total_messages == 0) return;

        auto avg_latency = total_latency / total_messages;
        auto avg_processing = total_processing / total_messages;
        auto avg_queueing = total_queueing / total_messages;

        std::cout << "Latency Statistics (msgs=" << total_messages << "):\n";
        std::cout << "  Avg end-to-end latency: " << avg_latency / 1000.0 << " μs\n";
        std::cout << "  Min end-to-end latency: " << min_latency / 1000.0 << " μs\n";
        std::cout << "  Max end-to-end latency: " << max_latency / 1000.0 << " μs\n";
        std::cout << "  Avg processing time: " << avg_processing / 1000.0 << " μs\n";
        std::cout << "  Avg queueing time: " << avg_queueing / 1000.0 << " μs\n";
    }

private:
    std::unordered_map<uint64_t, std::chrono::high_resolution_clock::time_point> received_times;
    std::unordered_map<uint64_t, std::chrono::high_resolution_clock::time_point> processed_times;
    std::unordered_map<uint64_t, std::chrono::high_resolution_clock::time_point> sent_times;

    uint64_t total_messages = 0;
    uint64_t total_latency = 0;
    uint64_t total_processing = 0;
    uint64_t total_queueing = 0;
    uint64_t min_latency = UINT64_MAX;
    uint64_t max_latency = 0;
};
