                            sll_family: AF_PACKET as u16,
                            sll_protocol: htons(ETH_P_ALL),
                            sll_ifindex: iface_index,
                            sll_hatype: 0,
                            sll_pkttype: 0,
                            sll_halen: 6,
                            sll_addr: [0; 8],
                        },
                        0,
                    ) {
                        eprintln!("Failed to forward packet: {}", e);
                    }
                }
            }
            Err(Errno::EAGAIN) | Err(Errno::EWOULDBLOCK) => {
                // Timeout occurred, continue loop
                continue;
            }
            Err(e) => {
                eprintln!("Error receiving packet: {}", e);
                break;
            }
        }
    }

    close(socket_fd)?;
    Ok(())
}

fn get_interface_index(iface_name: &str) -> Result<i32, Box<dyn std::error::Error>> {
    use nix::net::if_::if_nametoindex;

    if_nametoindex(iface_name)
        .map(|idx| idx as i32)
        .ok_or_else(|| format!("Interface {} not found", iface_name).into())
}

fn process_packet(packet: &[u8]) -> Option<Vec<u8>> {
    // Minimum Ethernet frame size is 64 bytes
    if packet.len() < 64 {
        return None;
    }

    // Parse Ethernet header
    let eth_header = unsafe { &*(packet.as_ptr() as *const EthHeader) };
    let eth_type = u16::from_be(eth_header.eth_type);

    // Simple filter: only process IPv4 packets (ETH_P_IP = 0x0800)
    if eth_type != ETH_P_IP {
        return None;
    }

    // Parse IP header (comes after Ethernet header)
    let ip_header_offset = mem::size_of::<EthHeader>();
    if packet.len() < ip_header_offset + mem::size_of::<IpHeader>() {
        return None;
    }

    let ip_header = unsafe { &*(packet[ip_header_offset..].as_ptr() as *const IpHeader) };

    // Example filter: forward only TCP packets to port 80
    if ip_header.protocol != 6 { // TCP protocol number
        return None;
    }

    // Check if destination port is 80 (HTTP)
    let tcp_header_offset = ip_header_offset + ((ip_header.version_ihl & 0x0F) as usize * 4);
    if packet.len() < tcp_header_offset + 4 {
        return None;
    }

    let dst_port = u16::from_be_bytes([packet[tcp_header_offset + 2], packet[tcp_header_offset + 3]]);
    if dst_port != 80 {
        return None;
    }

    // For demonstration, we'll just forward the packet as-is
    // In a real implementation, you might modify the packet here
    Some(packet.to_vec())
}
```

