Here's a complete implementation of an ultra-low-latency networking service with packet-level filtering and forwarding in C. This example demonstrates the core concepts while maintaining simplicity for educational purposes.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <net/ethernet.h>
#include <netinet/ether.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <sys/socket.h>
#include <linux/if_packet.h>
#include <linux/filter.h>
#include <linux/if_ether.h>
#include <linux/if.h>
#include <sys/ioctl.h>
#include <net/if.h>
#include <errno.h>
#include <pthread.h>
#include <time.h>
#include <sched.h>
#include <signal.h>

#define MAX_INTERFACES 4
#define BUFFER_SIZE 2048
#define ETH_HDR_SIZE sizeof(struct ether_header)
#define IP_HDR_SIZE sizeof(struct iphdr)
#define MAX_RULES 16
#define MAX_MAC_ENTRIES 4096

// Configuration
#define CORE_AFFINITY 0
#define BATCH_SIZE 32
#define PACKET_BUFFER_SIZE (BATCH_SIZE * BUFFER_SIZE)

// Global control
volatile sig_atomic_t keep_running = 1;

typedef struct {
    int sockfd;
    int ifindex;
    char ifname[IFNAMSIZ];
    struct sockaddr_ll sll;
    struct ether_addr mac_addr;
    unsigned char *rx_buffer;
    unsigned char *tx_buffer;
    int rx_len;
    int tx_len;
} interface_t;

typedef struct {
    interface_t *in;
    interface_t *out;
    struct bpf_program filter;
} forwarding_rule_t;

interface_t interfaces[MAX_INTERFACES];
forwarding_rule_t rules[MAX_RULES];
int rule_count = 0;

// MAC learning table
struct mac_table_entry {
    struct ether_addr mac;
    int ifindex;
    uint64_t last_seen;
};
struct mac_table_entry mac_table[MAX_MAC_ENTRIES];
int mac_table_size = 0;
pthread_mutex_t mac_table_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize CPU affinity
void set_cpu_affinity(int cpu) {
    cpu_set_t mask;
    CPU_ZERO(&mask);
    CPU_SET(cpu, &mask);
    if (sched_setaffinity(0, sizeof(mask), &mask) < 0) {
        perror("sched_setaffinity");
    }
}

// Initialize a raw socket with BPF filter
int init_raw_socket(const char *ifname, struct bpf_program *filter) {
    int sockfd;
    struct sockaddr_ll sll;
    struct ifreq ifr;
    int ret;

    if ((sockfd = socket(PF_PACKET, SOCK_RAW, htons(ETH_P_ALL))) < 0) {
        perror("socket");
        return -1;
    }

    // Set interface to promiscuous mode
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ);
    if (ioctl(sockfd, SIOCGIFFLAGS, &ifr) < 0) {
        perror("ioctl SIOCGIFFLAGS");
        close(sockfd);
        return -1;
    }
    ifr.ifr_flags |= IFF_PROMISC;
    if (ioctl(sockfd, SIOCSIFFLAGS, &ifr) < 0) {
        perror("ioctl SIOCSIFFLAGS");
        close(sockfd);
        return -1;
    }

    // Bind to specific interface
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = if_nametoindex(ifname);
    sll.sll_protocol = htons(ETH_P_ALL);

    if (bind(sockfd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(sockfd);
        return -1;
    }

    // Attach BPF filter if provided
    if (filter && setsockopt(sockfd, SOL_SOCKET, SO_ATTACH_FILTER, filter, sizeof(*filter)) < 0) {
        perror("setsockopt SO_ATTACH_FILTER");
        close(sockfd);
        return -1;
    }

    return sockfd;
}

// Initialize interface structure
int init_interface(const char *ifname, struct bpf_program *filter) {
    if (rule_count >= MAX_INTERFACES) {
        fprintf(stderr, "Too many interfaces\n");
        return -1;
    }

    interface_t *iface = &interfaces[rule_count];
    strncpy(iface->ifname, ifname, IFNAMSIZ);

    iface->sockfd = init_raw_socket(ifname, filter);
    if (iface->sockfd < 0) {
        return -1;
    }

    // Get interface index
    iface->ifindex = if_nametoindex(ifname);
    if (iface->ifindex == 0) {
        perror("if_nametoindex");
        close(iface->sockfd);
        return -1;
    }

    // Get MAC address
    struct ifreq ifr;
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ);
    if (ioctl(iface->sockfd, SIOCGIFHWADDR, &ifr) < 0) {
        perror("ioctl SIOCGIFHWADDR");
        close(iface->sockfd);
        return -1;
    }
    memcpy(&iface->mac_addr, ifr.ifr_hwaddr.sa_data, ETH_ALEN);

    // Allocate packet buffers
    iface->rx_buffer = malloc(PACKET_BUFFER_SIZE);
    iface->tx_buffer = malloc(PACKET_BUFFER_SIZE);
    if (!iface->rx_buffer || !iface->tx_buffer) {
        perror("malloc");
        close(iface->sockfd);
        return -1;
    }

    printf("Initialized interface %s (index %d, MAC: %s)\n",
           iface->ifname, iface->ifindex, ether_ntoa(&iface->mac_addr));

    return 0;
}

// Add a forwarding rule with optional BPF filter
void add_forwarding_rule(const char *in_if, const char *out_if, const char *bpf_filter) {
    if (rule_count >= MAX_RULES) {
        fprintf(stderr, "Too many rules\n");
        return;
    }

    // Compile BPF filter if provided
    struct bpf_program filter = {0};
    if (bpf_filter) {
        struct sock_filter code[] = {
            { 0x28, 0, 0, 0x0000000c },  // ldh [12]
            { 0x15, 0, 8, 0x00008000 },  // jeq #0x800 jt 2 jf 10
            { 0x28, 0, 0, 0x00000010 },  // ldh [16]
            { 0x15, 0, 6, 0x00000045 },  // jeq #0x45 jt 3 jf 9
            { 0x28, 0, 0, 0x00000014 },  // ldh [20]
            { 0x45, 4, 0, 0x00001fff },  // jset #0x1fff jt 4 jf 5
            { 0xb1, 0, 0, 0x0000000e },  // ldxb 4*([14]&0xf)
            { 0x50, 0, 0, 0x00000010 },  // ldb [x + 16]
            { 0x15, 0, 1, 0x00000006 },  // jeq #6 jt 7 jf 8
            { 0x6, 0, 0, 0x00040000 },   // ret #262144
            { 0x6, 0, 0, 0x00000000 },   // ret #0
        };
        filter.len = 10;
        filter.filter = code;
    }

    if (init_interface(in_if, &filter) < 0 || init_interface(out_if, NULL) < 0) {
        fprintf(stderr, "Failed to initialize interfaces for rule\n");
        return;
    }

    rules[rule_count].in = &interfaces[rule_count];
    rules[rule_count].out = &interfaces[rule_count + 1];
    rules[rule_count].filter = filter;
    rule_count += 2; // Each rule uses two interfaces
}

// Simple MAC learning function
void learn_mac(struct ether_addr *mac, int ifindex) {
    pthread_mutex_lock(&mac_table_lock);

    // Check if MAC already exists
    for (int i = 0; i < mac_table_size; i++) {
        if (memcmp(&mac_table[i].mac, mac, sizeof(struct ether_addr)) == 0) {
            mac_table[i].ifindex = ifindex;
            mac_table[i].last_seen = clock_gettime_nsec_np(CLOCK_MONOTONIC);
            pthread_mutex_unlock(&mac_table_lock);
            return;
        }
    }

    // If table is full, replace oldest entry
    if (mac_table_size >= MAX_MAC_ENTRIES) {
        int oldest_idx = 0;
        uint64_t oldest_time = mac_table[0].last_seen;
        for (int i = 1; i < MAX_MAC_ENTRIES; i++) {
            if (mac_table[i].last_seen < oldest_time) {
                oldest_idx = i;
                oldest_time = mac_table[i].last_seen;
            }
        }
        memcpy(&mac_table[oldest_idx].mac, mac, sizeof(struct ether_addr));
        mac_table[oldest_idx].ifindex = ifindex;
        mac_table[oldest_idx].last_seen = clock_gettime_nsec_np(CLOCK_MONOTONIC);
    } else {
        memcpy(&mac_table[mac_table_size].mac, mac, sizeof(struct ether_addr));
        mac_table[mac_table_size].ifindex = ifindex;
        mac_table[mac_table_size].last_seen = clock_gettime_nsec_np(CLOCK_MONOTONIC);
        mac_table_size++;
    }

    pthread_mutex_unlock(&mac_table_lock);
}

// Find outgoing interface for a MAC address
int find_outgoing_interface(struct ether_addr *mac) {
    pthread_mutex_lock(&mac_table_lock);

    for (int i = 0; i < mac_table_size; i++) {
        if (memcmp(&mac_table[i].mac, mac, sizeof(struct ether_addr)) == 0) {
            int ifindex = mac_table[i].ifindex;
            pthread_mutex_unlock(&mac_table_lock);
            return ifindex;
        }
    }

    pthread_mutex_unlock(&mac_table_lock);
    return -1; // Unknown MAC
}

// Process a batch of packets
void process_packets(interface_t *in_iface) {
    int batch_count = 0;
    unsigned char *buffer = in_iface->rx_buffer;

    while (batch_count < BATCH_SIZE) {
        int len = recv(in_iface->sockfd, buffer + (batch_count * BUFFER_SIZE), BUFFER_SIZE, 0);
        if (len < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                break; // No more packets available
            }
            perror("recv");
            continue;
        }

        // Process packet
        struct ether_header *eth = (struct ether_header *)buffer;
        if (ntohs(eth->ether_type) == ETHERTYPE_IP) {
            // Learn source MAC
            learn_mac((struct ether_addr *)eth->ether_shost, in_iface->ifindex);

            // Find destination MAC in our table
            int out_ifindex = find_outgoing_interface((struct ether_addr *)eth->ether_dhost);

            if (out_ifindex > 0) {
                // Forward to the correct interface
                for (int i = 0; i < rule_count; i++) {
                    if (rules[i].out->ifindex == out_ifindex) {
                        memcpy(rules[i].out->tx_buffer + (rules[i].out->tx_len * BUFFER_SIZE),
                               buffer, len);
                        rules[i].out->tx_len++;
                        break;
                    }
                }
            } else {
                // Unknown destination - flood to all interfaces except incoming
                for (int i = 0; i < rule_count; i++) {
                    if (rules[i].in->ifindex != in_iface->ifindex) {
                        memcpy(rules[i].out->tx_buffer + (rules[i].out->tx_len * BUFFER_SIZE),
                               buffer, len);
                        rules[i].out->tx_len++;
                    }
                }
            }
        }

        batch_count++;
    }

    // Send batched packets
    for (int i = 0; i < rule_count; i++) {
        if (rules[i].out->tx_len > 0) {
            int total_len = rules[i].out->tx_len * BUFFER_SIZE;
            if (sendto(rules[i].out->sockfd, rules[i].out->tx_buffer, total_len, 0,
                      (struct sockaddr *)&rules[i].out->sll, sizeof(rules[i].out->sll)) < 0) {
                perror("sendto");
            }
            rules[i].out->tx_len = 0;
        }
    }
}

// Worker thread function
void *packet_capture_loop(void *arg) {
    interface_t *iface = (interface_t *)arg;

    // Set CPU affinity
    set_cpu_affinity(CORE_AFFINITY + (iface->ifindex % 2));

    // Set socket to non-blocking
    int flags = fcntl(iface->sockfd, F_GETFL, 0);
    fcntl(iface->sockfd, F_SETFL, flags | O_NONBLOCK);

    printf("Starting packet capture on %s (core %d)\n",
           iface->ifname, CORE_AFFINITY + (iface->ifindex % 2));

    while (keep_running) {
        process_packets(iface);
    }

    return NULL;
}

// Signal handler
void handle_signal(int sig) {
    keep_running = 0;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <in_interface> <out_interface> [bpf_filter]\n", argv[0]);
        fprintf(stderr, "Example BPF filter: 'tcp and port 80'\n");
        return 1;
    }

    // Set high priority
    struct sched_param param;
    param.sched_priority = 99;
    if (sched_setscheduler(0, SCHED_FIFO, &param) < 0) {
        perror("sched_setscheduler");
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize forwarding rules
    const char *bpf_filter = (argc > 3) ? argv[3] : NULL;
    add_forwarding_rule(argv[1], argv[2], bpf_filter);

    // Create worker threads
    pthread_t threads[MAX_INTERFACES];
    for (int i = 0; i < rule_count; i++) {
        if (pthread_create(&threads[i], NULL, packet_capture_loop, interfaces[i].sockfd) != 0) {
            perror("pthread_create");
            return 1;
        }
    }

    // Wait for threads
    for (int i = 0; i < rule_count; i++) {
        pthread_join(threads[i], NULL);
    }

    // Cleanup
    for (int i = 0; i < rule_count; i++) {
        close(interfaces[i].sockfd);
        free(interfaces[i].rx_buffer);
        free(interfaces[i].tx_buffer);
    }

    return 0;
}
```

