use pnet::datalink::{self, Channel::Ethernet, NetworkInterface};
use pnet::packet::{
    ethernet::{EthernetPacket, EtherTypes},
    ip::IpNextHeaderProtocols,
    ipv4::Ipv4Packet,
    tcp::TcpPacket,
    udp::UdpPacket,
    Packet,
};
use std::{
    net::IpAddr,
