/// Global flag to control shutdown
static RUNNING: AtomicBool = AtomicBool::new(true);

fn main() {
    // Set up signal handler for graceful shutdown
    ctrlc::set_handler(|| {
        RUNNING.store(false, Ordering::SeqCst);
    })
    .expect("Error setting Ctrl-C handler");

    // Initialize configuration
    let config = FilterConfig::default();

    // Select network interface
    let interface = match select_interface() {
        Some(iface) => iface,
        None => {
            eprintln!("No suitable network interface found");
            return;
        }
    };

    println!(
        "Starting packet filter on interface {} (MAC: {})",
        interface.name,
        interface.mac.unwrap()
    );

    // Create packet channel (RX only for filtering, TX for forwarding)
    let (mut tx, mut rx) = match datalink::channel(&interface, Default::default()) {
        Ok(Ethernet(tx, rx)) => (tx, rx),
        Ok(_) => {
            eprintln!("Unsupported channel type");
            return;
        }
        Err(e) => {
            eprintln!("Error creating channel: {}", e);
            return;
        }
    };

    println!("Packet filter initialized. Processing packets...");

    // Main processing loop
    let mut packet_count = 0;
    let mut last_stats = Instant::now();
    let mut allowed_count = 0;
    let mut dropped_count = 0;

    while RUNNING.load(Ordering::SeqCst) {
        match rx.next() {
            Ok(packet) => {
                packet_count += 1;

                // Check if we should print stats periodically
                if last_stats.elapsed() >= Duration::from_secs(1) {
                    println!(
                        "Stats - Total: {} | Allowed: {} | Dropped: {} | Rate: {:.2} pps",
                        packet_count,
                        allowed_count,
                        dropped_count,
                        (packet_count as f64) / last_stats.elapsed().as_secs_f64()
                    );
                    last_stats = Instant::now();
                }

                if let Some(eth_packet) = EthernetPacket::new(packet) {
                    if process_ethernet_packet(&eth_packet, &config) {
                        allowed_count += 1;
                        // In a real implementation, you would forward the packet here
                        // tx.build_and_send(1, eth_packet.packet().len(), &mut |new_packet| {
                        //     new_packet.copy_from_slice(eth_packet.packet());
                        // });
                    } else {
                        dropped_count += 1;
                    }
                }
            }
            Err(e) => {
                eprintln!("Error receiving packet: {}", e);
                dropped_count += 1;
            }
        }
    }

    println!(
        "Shutting down. Final stats - Total: {} | Allowed: {} | Dropped: {}",
        packet_count, allowed_count, dropped_count
    );
}

/// Selects the first non-loopback, up interface
fn select_interface() -> Option<NetworkInterface> {
    datalink::interfaces()
        .into_iter()
        .find(|iface| !iface.is_loopback() && iface.is_up())
}

/// Processes an Ethernet packet according to filter rules
fn process_ethernet_packet(eth_packet: &EthernetPacket, config: &FilterConfig) -> bool {
    // Check packet size
    if eth_packet.packet().len() > config.max_packet_size {
        return false;
    }

    // Filter by Ethernet type
    match eth_packet.get_ethertype() {
        EtherTypes::Ipv4 => process_ipv4_packet(eth_packet.payload(), config),
        EtherTypes::Ipv6 => process_ipv6_packet(eth_packet.payload(), config),
        _ => false, // Drop non-IP packets
    }
}

/// Processes IPv4 packets
fn process_ipv4_packet(packet: &[u8], config: &FilterConfig) -> bool {
    if let Some(ipv4_packet) = Ipv4Packet::new(packet) {
        // Check source/destination IP against allowed list
        if !is_ip_allowed(ipv4_packet.get_source(), config)
            && !is_ip_allowed(ipv4_packet.get_destination(), config)
        {
            return false;
        }

        // Process based on protocol
        match ipv4_packet.get_next_level_protocol() {
            IpNextHeaderProtocols::Tcp => process_tcp_packet(ipv4_packet.payload(), config),
            IpNextHeaderProtocols::Udp => process_udp_packet(ipv4_packet.payload(), config),
            _ => false, // Drop non-TCP/UDP packets
        }
    } else {
        false
    }
}

/// Processes IPv6 packets (simplified)
fn process_ipv6_packet(packet: &[u8], config: &FilterConfig) -> bool {
    // Simplified IPv6 processing - in production you'd implement full checks
    if packet.len() >= 40 {
        let protocol = packet[6]; // Next header field
        match protocol {
            6 => process_tcp_packet(&packet[40..], config), // TCP
            17 => process_udp_packet(&packet[40..], config), // UDP
            _ => false,
        }
    } else {
        false
    }
}

/// Processes TCP packets
fn process_tcp_packet(packet: &[u8], config: &FilterConfig) -> bool {
    if let Some(tcp_packet) = TcpPacket::new(packet) {
        // Check if port is allowed
        if !config.allowed_ports.contains(&tcp_packet.get_source())
            && !config.allowed_ports.contains(&tcp_packet.get_destination())
        {
            return false;
        }
        true
    } else {
        false
    }
}

/// Processes UDP packets
fn process_udp_packet(packet: &[u8], config: &FilterConfig) -> bool {
    if let Some(udp_packet) = UdpPacket::new(packet) {
        // Check if port is allowed
        if !config.allowed_ports.contains(&udp_packet.get_source())
            && !config.allowed_ports.contains(&udp_packet.get_destination())
        {
            return false;
        }
        true
    } else {
        false
    }
}

/// Checks if an IP address is in the allowed list
fn is_ip_allowed(ip: IpAddr, config: &FilterConfig) -> bool {
    config
        .allowed_ips
        .iter()
        .any(|&allowed| ip.is_in(allowed))
}
