Below is a production-grade implementation using **DPDK (Data Plane Development Kit)** in C, which is the gold standard for ultra-low-latency networking. This example demonstrates packet-level filtering and forwarding with minimal overhead.

```c
/*
 * Ultra-Low-Latency Packet Filtering and Forwarding Service
 * Uses DPDK for kernel bypass and direct NIC access
 *
 * Features:
 * - Poll-mode operation (no interrupts)
 * - Batch packet processing
 * - Simple MAC-based filtering
 * - Zero-copy packet forwarding
 * - CPU pinning for performance
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <inttypes.h>
#include <sys/types.h>
#include <sys/queue.h>
#include <setjmp.h>
#include <stdarg.h>
#include <ctype.h>
#include <errno.h>
#include <getopt.h>
#include <signal.h>

#include <rte_common.h>
#include <rte_log.h>
#include <rte_malloc.h>
#include <rte_memory.h>
#include <rte_memcpy.h>
#include <rte_eal.h>
#include <rte_launch.h>
#include <rte_atomic.h>
#include <rte_cycles.h>
#include <rte_prefetch.h>
#include <rte_lcore.h>
#include <rte_per_lcore.h>
#include <rte_branch_prediction.h>
#include <rte_interrupts.h>
#include <rte_random.h>
#include <rte_debug.h>
#include <rte_ether.h>
#include <rte_ethdev.h>
#include <rte_mempool.h>
#include <rte_mbuf.h>
#include <rte_net.h>
#include <rte_flow.h>

#define NUM_MBUFS         8191
#define MBUF_CACHE_SIZE   250
#define BURST_SIZE        32
#define RX_RING_SIZE      1024
#define TX_RING_SIZE      1024

/* Filter configuration */
#define FILTER_MAC_1 "00:11:22:33:44:55"
#define FILTER_MAC_2 "AA:BB:CC:DD:EE:FF"

/* Per-core structures */
struct lcore_params {
    uint16_t port_id;
    struct rte_mempool *mbuf_pool;
    struct rte_eth_dev_tx_buffer *tx_buffer;
};

/* Global configuration */
static volatile bool force_quit = false;

/* Signal handler */
static void
signal_handler(int signum)
{
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nSignal %d received, preparing to exit...\n", signum);
        force_quit = true;
    }
}

/* Convert string MAC to rte_ether_addr */
static int
parse_mac_addr(const char *mac_str, struct rte_ether_addr *mac_addr)
{
    int i;
    unsigned int values[6];
    char *end;

    if (strlen(mac_str) != 17) return -1;

    for (i = 0; i < 6; i++) {
        values[i] = strtoul(mac_str + 3*i, &end, 16);
        if (end != mac_str + 3*i + 2) return -1;
    }

    mac_addr->addr_bytes[0] = (uint8_t)values[0];
    mac_addr->addr_bytes[1] = (uint8_t)values[1];
    mac_addr->addr_bytes[2] = (uint8_t)values[2];
    mac_addr->addr_bytes[3] = (uint8_t)values[3];
    mac_addr->addr_bytes[4] = (uint8_t)values[4];
    mac_addr->addr_bytes[5] = (uint8_t)values[5];

    return 0;
}

/* Simple packet filter function */
static inline int
filter_packet(struct rte_mbuf *m)
{
    struct rte_ether_hdr *eth_hdr;
    struct rte_ether_addr filter_mac1, filter_mac2;

    /* Parse MAC addresses */
    if (parse_mac_addr(FILTER_MAC_1, &filter_mac1) < 0 ||
        parse_mac_addr(FILTER_MAC_2, &filter_mac2) < 0) {
        return 0; /* Drop if MAC parsing fails */
    }

    /* Get Ethernet header */
    eth_hdr = rte_pktmbuf_mtod(m, struct rte_ether_hdr *);

    /* Check if destination matches either filter MAC */
    if (rte_is_same_ether_addr(&eth_hdr->dst_addr, &filter_mac1) ||
        rte_is_same_ether_addr(&eth_hdr->dst_addr, &filter_mac2)) {
        return 1; /* Forward */
    }

    return 0; /* Drop */
}

/* Main packet processing loop */
static int
lcore_main(struct lcore_params *p)
{
    const uint16_t nb_ports = rte_eth_dev_count_avail();
    uint16_t port_id = p->port_id;
    struct rte_mempool *mbuf_pool = p->mbuf_pool;
    struct rte_eth_dev_tx_buffer *tx_buffer = p->tx_buffer;
    struct rte_mbuf *rx_pkts[BURST_SIZE];
    uint16_t nb_rx, nb_tx;
    uint64_t prev_tsc = 0, cur_tsc, diff_tsc;
    const uint64_t drain_tsc = (rte_get_tsc_hz() + US_PER_S - 1) / US_PER_S * 50; /* 50us */

    printf("Core %u handling port %u\n", rte_lcore_id(), port_id);

    /* Main processing loop */
    while (!force_quit) {
        cur_tsc = rte_rdtsc();

        /* TX burst queue drain */
        diff_tsc = cur_tsc - prev_tsc;
        if (unlikely(diff_tsc > drain_tsc)) {
            rte_eth_tx_buffer_flush(port_id, 0, tx_buffer);
            prev_tsc = cur_tsc;
        }

        /* Receive burst of packets */
        nb_rx = rte_eth_rx_burst(port_id, 0, rx_pkts, BURST_SIZE);
        if (unlikely(nb_rx == 0))
            continue;

        /* Process each received packet */
        for (uint16_t i = 0; i < nb_rx; i++) {
            struct rte_mbuf *m = rx_pkts[i];

            /* Apply filter */
            if (filter_packet(m)) {
                /* Forward packet - in a real implementation we'd have more sophisticated forwarding logic */
                rte_prefetch0(rte_pktmbuf_mtod(m, void *));
                rte_eth_tx_buffer(port_id, 0, tx_buffer, m);
            } else {
                /* Drop packet - could recycle buffer instead */
                rte_pktmbuf_free(m);
            }
        }
    }

    return 0;
}

/* Initialize a single port */
static inline int
init_port(uint16_t port_id, struct rte_mempool *mbuf_pool)
{
    struct rte_eth_conf port_conf = {
        .rxmode = {
            .mq_mode = ETH_MQ_RX_RSS,
            .max_rx_pkt_len = RTE_ETHER_MAX_LEN,
            .split_hdr_size = 0,
            .offloads = DEV_RX_OFFLOAD_CHECKSUM,
        },
        .txmode = {
            .mq_mode = ETH_MQ_TX_NONE,
        },
    };
    const uint16_t rx_rings = 1, tx_rings = 1;
    int ret;
    uint16_t q;
    struct rte_eth_dev_info dev_info;
    struct rte_eth_txconf txconf;

    /* Get device info */
    rte_eth_dev_info_get(port_id, &dev_info);
    if (dev_info.tx_offload_capa & DEV_TX_OFFLOAD_MBUF_FAST_FREE)
        port_conf.txmode.offloads |= DEV_TX_OFFLOAD_MBUF_FAST_FREE;

    /* Configure the port */
    ret = rte_eth_dev_configure(port_id, rx_rings, tx_rings, &port_conf);
    if (ret != 0)
        return ret;

    /* Setup RX queue */
    for (q = 0; q < rx_rings; q++) {
        ret = rte_eth_rx_queue_setup(port_id, q, RX_RING_SIZE,
                                     rte_eth_dev_socket_id(port_id),
                                     NULL, mbuf_pool);
        if (ret < 0)
            return ret;
    }

    /* Setup TX queue */
    txconf = dev_info.default_txconf;
    txconf.offloads = port_conf.txmode.offloads;
    for (q = 0; q < tx_rings; q++) {
        ret = rte_eth_tx_queue_setup(port_id, q, TX_RING_SIZE,
                                     rte_eth_dev_socket_id(port_id),
                                     &txconf);
        if (ret < 0)
            return ret;
    }

    /* Start the port */
    ret = rte_eth_dev_start(port_id);
    if (ret < 0)
        return ret;

    /* Enable promiscuous mode if needed */
    rte_eth_promiscuous_enable(port_id);

    printf("Port %u initialized\n", port_id);
    return 0;
}

/* Main function */
int
main(int argc, char **argv)
{
    int ret;
    uint16_t nb_ports;
    uint16_t port_id;
    unsigned int nb_lcores;
    struct rte_mempool *mbuf_pool;
    struct lcore_params *params = NULL;
    unsigned int lcore_id;

    /* Initialize EAL */
    ret = rte_eal_init(argc, argv);
    if (ret < 0)
        rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");

    argc -= ret;
    argv += ret;

    /* Parse application arguments (simplified) */
    if (argc > 1) {
        printf("Usage: %s [EAL options]\n", argv[0]);
        return 1;
    }

    /* Setup signal handler */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Create mbuf pool */
    mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", NUM_MBUFS * nb_ports,
                                        MBUF_CACHE_SIZE, 0,
                                        RTE_MBUF_DEFAULT_BUF_SIZE,
                                        rte_socket_id());
    if (mbuf_pool == NULL)
        rte_exit(EXIT_FAILURE, "Cannot create mbuf pool\n");

    /* Initialize ports */
    nb_ports = rte_eth_dev_count_avail();
    if (nb_ports == 0)
        rte_exit(EXIT_FAILURE, "No Ethernet ports available\n");

    RTE_ETH_FOREACH_DEV(port_id) {
        if (init_port(port_id, mbuf_pool) != 0)
            rte_exit(EXIT_FAILURE, "Cannot init port %"PRIu16 "\n", port_id);
    }

    /* Allocate memory for per-core parameters */
    params = rte_zmalloc("lcore_params", sizeof(struct lcore_params) * nb_ports, 0);
    if (params == NULL)
        rte_exit(EXIT_FAILURE, "Cannot allocate memory for lcore params\n");

    /* Setup per-core parameters */
    RTE_ETH_FOREACH_DEV(port_id) {
        params[port_id].port_id = port_id;
        params[port_id].mbuf_pool = mbuf_pool;

        /* Create TX buffer for this port */
        params[port_id].tx_buffer = rte_zmalloc_socket("tx_buffer",
                                                        RTE_ETH_TX_BUFFER_SIZE(BURST_SIZE),
                                                        0,
                                                        rte_eth_dev_socket_id(port_id));
        if (params[port_id].tx_buffer == NULL)
            rte_exit(EXIT_FAILURE, "Cannot allocate tx buffer memory\n");

        rte_eth_tx_buffer_init(params[port_id].tx_buffer, BURST_SIZE);
    }

    /* Launch per-core main function on each lcore */
    RTE_LCORE_FOREACH_WORKER(lcore_id) {
        if (rte_eal_remote_launch((lcore_function_t *)lcore_main, &params[lcore_id % nb_ports], lcore_id) < 0)
            rte_exit(EXIT_FAILURE, "Cannot launch lcore %u\n", lcore_id);
    }

    /* Launch main function on master lcore */
    lcore_main(&params[rte_lcore_id() % nb_ports]);

    /* Wait for all lcores to finish */
    RTE_LCORE_FOREACH_WORKER(lcore_id) {
        if (rte_eal_wait_lcore(lcore_id) < 0)
            return -1;
    }

    /* Cleanup */
    RTE_ETH_FOREACH_DEV(port_id) {
        rte_eth_dev_stop(port_id);
        rte_eth_dev_close(port_id);
    }

    rte_free(params);
    rte_eal_cleanup();

    printf("Application exited successfully\n");
    return 0;
}
