#include <errno.h>
#include <pthread.h>

#define MAX_INTERFACES 2
#define BUFFER_SIZE 2048
#define ETH_HDR_SIZE sizeof(struct ether_header)
#define IP_HDR_SIZE sizeof(struct iphdr)

typedef struct {
    int sockfd;
    int ifindex;
    char ifname[IFNAMSIZ];
    struct sockaddr_ll sll;
    struct ether_addr mac_addr;
} interface_t;

typedef struct {
    interface_t *in;
    interface_t *out;
} forwarding_rule_t;

interface_t interfaces[MAX_INTERFACES];
forwarding_rule_t rules[MAX_INTERFACES];
int rule_count = 0;

// Simple MAC address table for forwarding
struct mac_table_entry {
    struct ether_addr mac;
    int ifindex;
    time_t timestamp;
};
#define MAC_TABLE_SIZE 1024
