## 1. XDP Program (`xdp_filter.c`)

```c
// SPDX-License-Identifier: GPL-2.0
/* XDP Packet Filter - Drops packets from 192.168.1.100 */
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

// Filter rule: Drop packets from 192.168.1.100 (0xC0A80164 in little-endian)
#define FILTER_IP 0xC0A80164

// Ethernet header
struct ethhdr {
    __u8 h_dest[6];
    __u8 h_source[6];
    __u16 h_proto;
};

// IPv4 header
struct iphdr {
    __u8 ihl : 4;
    __u8 version : 4;
    __u8 tos;
    __u16 tot_len;
    __u16 id;
    __u16 frag_off;
    __u8 ttl;
    __u8 protocol;
    __u16 check;
    __u32 saddr;
    __u32 daddr;
};

// XDP program entry point
SEC("xdp")
int xdp_filter_prog(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    // Parse Ethernet header
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end) {
        return XDP_PASS;
    }

    // Check if it's an IPv4 packet
    if (eth->h_proto != bpf_htons(ETH_P_IP)) {
        return XDP_PASS;
    }

    // Parse IP header
    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end) {
        return XDP_PASS;
    }

    // Filter: Drop packets from FILTER_IP
    if (ip->saddr == FILTER_IP) {
        return XDP_DROP;
    }

    // Forward packet back to the same interface (for testing)
    // In production, use bpf_redirect() to forward to another interface
    return XDP_TX;
}

char _license[] SEC("license") = "GPL";
```

