use libbpf_rs::skel::OpenSkel;
use libbpf_rs::{skel::SkelBuilder, Error, XdpFlags};
use std::env;
use std::sync::mpsc;

fn main() -> Result<(), Error> {
    // Parse command line arguments
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: {} <interface>", args[0]);
        std::process::exit(1);
    }
    let iface = &args[1];

    // Build and load the XDP program
    let mut skel_builder = SkelBuilder::default();
    skel_builder.obj("xdp_filter.o")?;

    let open_skel = skel_builder.open()?;
    let mut skel = open_skel.load()?;

    // Attach the XDP program to the interface
    skel.progs_mut()
        .xdp_filter_prog()
        .attach_xdp(iface, XdpFlags::default())?;

