# Ultra-Low-Latency Packet Filter and Forwarder in C

Below is a minimal implementation of an ultra-low-latency networking service that performs packet-level filtering and forwarding. This example uses raw sockets for simplicity (though for production ultra-low-latency, you'd want to use DPDK or AF_XDP instead).

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <linux/if_packet.h>
#include <net/if.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <errno.h>
#include <pthread.h>

// Configuration
#define INTERFACE_IN  "eth0"      // Input interface
#define INTERFACE_OUT "eth1"      // Output interface
#define FILTER_IP     "192.168.1.100"  // Drop all packets from this IP
#define BUFFER_SIZE   (1 << 16)   // 64KB buffer
#define BATCH_SIZE    32          // Process packets in batches

// Global variables
int sock_in, sock_out;
volatile int running = 1;

// Cleanup function
void cleanup() {
    if (sock_in >= 0) close(sock_in);
    if (sock_out >= 0) close(sock_out);
    running = 0;
}

// Signal handler for clean shutdown
#include <signal.h>
void handle_signal(int sig) {
    cleanup();
    exit(0);
}

// Initialize raw socket
int init_raw_socket(const char *interface, int protocol) {
    int sockfd;
    struct sockaddr_ll sll;
    int ifindex;

    // Create raw socket
    sockfd = socket(AF_PACKET, SOCK_RAW, htons(protocol));
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    // Get interface index
    ifindex = if_nametoindex(interface);
    if (!ifindex) {
        perror("if_nametoindex");
        close(sockfd);
        return -1;
    }

    // Bind to interface
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = ifindex;
    sll.sll_protocol = htons(protocol);

    if (bind(sockfd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(sockfd);
        return -1;
    }

    return sockfd;
}

// Parse IPv4 header and check filter
int should_drop_packet(const unsigned char *packet, size_t len) {
    if (len < sizeof(struct iphdr)) {
        return 0;  // Not an IPv4 packet or too short
    }

    struct iphdr *ip = (struct iphdr *)packet;

    // Check if it's IPv4
    if (ip->version != 4) {
        return 0;
    }

    // Convert source IP to string for comparison
    char src_ip[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &ip->saddr, src_ip, INET_ADDRSTRLEN);

    // Check against filter IP
    if (strcmp(src_ip, FILTER_IP) == 0) {
        printf("Dropping packet from %s\n", src_ip);
        return 1;
    }

    return 0;
}

// Forward packet to output interface
int forward_packet(int sock_out, const unsigned char *packet, size_t len) {
    if (send(sock_out, packet, len, 0) < 0) {
        perror("send");
        return -1;
    }
    return 0;
}

// Worker thread function
void *worker_thread(void *arg) {
    (void)arg;
    unsigned char buffer[BUFFER_SIZE];
    struct sockaddr_ll sll;
    socklen_t sll_len = sizeof(sll);

    while (running) {
        // Receive packet
        ssize_t recv_len = recvfrom(sock_in, buffer, BUFFER_SIZE, 0,
                                   (struct sockaddr *)&sll, &sll_len);
        if (recv_len < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            perror("recvfrom");
            continue;
        }

        // Check if we should drop the packet
        if (should_drop_packet(buffer, recv_len)) {
            continue;
        }

        // Forward the packet
        if (forward_packet(sock_out, buffer, recv_len) < 0) {
            continue;
        }
    }

    return NULL;
}

int main() {
    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize raw sockets
    sock_in = init_raw_socket(INTERFACE_IN, ETH_P_ALL);
    if (sock_in < 0) {
        fprintf(stderr, "Failed to initialize input socket\n");
        return 1;
    }

    sock_out = init_raw_socket(INTERFACE_OUT, ETH_P_ALL);
    if (sock_out < 0) {
        fprintf(stderr, "Failed to initialize output socket\n");
        cleanup();
        return 1;
    }

    // Set socket to non-blocking mode
    int flags_in = fcntl(sock_in, F_GETFL, 0);
    fcntl(sock_in, F_SETFL, flags_in | O_NONBLOCK);

    int flags_out = fcntl(sock_out, F_GETFL, 0);
    fcntl(sock_out, F_SETFL, flags_out | O_NONBLOCK);

    // Create worker thread
    pthread_t thread;
    if (pthread_create(&thread, NULL, worker_thread, NULL) != 0) {
        perror("pthread_create");
        cleanup();
        return 1;
    }

    printf("Packet filter running. Press Ctrl+C to stop.\n");

    // Main loop (can be used for stats or other tasks)
    while (running) {
        sleep(1);
    }

    // Cleanup
    cleanup();
    pthread_join(thread, NULL);

    return 0;
}
```

## Key Features of This Implementation:

1. **Raw Sockets**: Uses Linux raw sockets to receive and send packets at the link layer (ETH_P_ALL) for maximum control.

2. **Packet Filtering**:
   - Parses IPv4 headers to check source IP addresses
   - Drops packets matching a specific filter IP (configurable)
   - Easily extendable to support more complex filtering rules

3. **Non-blocking I/O**: Uses non-blocking sockets to avoid blocking in the receive loop.

4. **Threaded Design**: Uses a separate worker thread for packet processing to allow for future expansion (e.g., multiple cores).

5. **Clean Shutdown**: Proper signal handling for clean termination.

## Important Notes:

1. **Performance Limitations**:
   - Raw sockets are not as performant as DPDK or AF_XDP
   - This implementation is single-threaded (though the structure allows for easy expansion)
   - No batching of packets (would need to be added for maximum throughput)

2. **Security**:
