### **Next-Gen Ultra-Low-Latency Version (XDP)**
For a **production-grade** ultra-low-latency service, consider rewriting this in **XDP** (eXpress Data Path), which runs in the kernel and avoids context switches. Example:
```c
// XDP example (simplified)
SEC("xdp")
int xdp_filter(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    // Parse Ethernet/IP/TCP headers (simplified)
    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end) return XDP_DROP;

    struct iphdr *ip = data + sizeof(*eth);
    if ((void *)(ip + 1) > data_end) return XDP_DROP;

    if (ip->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp = (void *)ip + sizeof(*ip);
        if ((void *)(tcp + 1) > data_end) return XDP_DROP;

        if (ntohs(tcp->dest) == FILTER_PORT) {
            return XDP_PASS;  // Forward
        }
    }
    return XDP_DROP;  // Drop if not matching
}
```
Compile with `clang` and load into the kernel using `ip link set dev eth0 xdp obj filter.o`.

