# Ultra-Low-Latency Networking Service with Packet Filtering

Below is a complete implementation of an ultra-low-latency networking service using DPDK (Data Plane Development Kit) in C. This service performs packet-level filtering (based on destination IP and port) and forwarding with minimal latency.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <inttypes.h>
#include <sys/types.h>
#include <sys/queue.h>
#include <netinet/in.h>
#include <setjmp.h>
#include <stdarg.h>
#include <ctype.h>
#include <errno.h>
#include <getopt.h>
#include <signal.h>

#include <rte_common.h>
#include <rte_log.h>
#include <rte_malloc.h>
#include <rte_memory.h>
#include <rte_memcpy.h>
#include <rte_eal.h>
#include <rte_launch.h>
#include <rte_atomic.h>
#include <rte_cycles.h>
#include <rte_prefetch.h>
#include <rte_lcore.h>
#include <rte_per_lcore.h>
#include <rte_branch_prediction.h>
#include <rte_interrupts.h>
#include <rte_pci.h>
#include <rte_random.h>
#include <rte_debug.h>
#include <rte_ether.h>
#include <rte_ethdev.h>
#include <rte_mempool.h>
#include <rte_mbuf.h>

/* Configuration parameters */
#define NUM_MBUFS          (8191 * 4)  /* Number of mbufs in mempool */
#define MBUF_CACHE_SIZE    250         /* Cache size for mbufs */
#define BURST_SIZE         32          /* Burst size for RX/TX */
#define FILTER_DST_IP      "192.168.1.100"
#define FILTER_DST_PORT    80          /* HTTP port for filtering */

/* Global variables */
static volatile bool force_quit;
static struct rte_mempool *mbuf_pool;
static struct rte_eth_conf port_conf_default;

/**
 * Initialize default port configuration
 */
static void
init_port_conf(void)
{
    memset(&port_conf_default, 0, sizeof(port_conf_default));
    port_conf_default.rxmode.mq_mode = ETH_MQ_RX_RSS;
    port_conf_default.rxmode.max_rx_pkt_len = RTE_ETHER_MAX_LEN;
    port_conf_default.rxmode.split_hdr_size = 0;
    port_conf_default.txmode.mq_mode = ETH_MQ_TX_NONE;
}

/**
 * Initialize a single port
 */
static inline int
port_init(uint16_t port)
{
    struct rte_eth_conf port_conf = port_conf_default;
    const uint16_t rx_rings = 1;
    const uint16_t tx_rings = 1;
    int ret;
    uint16_t q;
    struct rte_eth_dev_info dev_info;
    struct rte_eth_txconf txconf;

    if (!rte_eth_dev_is_valid_port(port))
        return -1;

    /* Get device info */
    rte_eth_dev_info_get(port, &dev_info);

    /* Configure the Ethernet device */
    port_conf.rxmode.offloads = dev_info.rx_offload_capa;
    port_conf.txmode.offloads = dev_info.tx_offload_capa;

    ret = rte_eth_dev_configure(port, rx_rings, tx_rings, &port_conf);
    if (ret != 0)
        return ret;

    /* Setup RX queue */
    for (q = 0; q < rx_rings; q++) {
        ret = rte_eth_rx_queue_setup(port, q, NUM_MBUFS,
                                     rte_eth_dev_socket_id(port),
                                     NULL, mbuf_pool);
        if (ret < 0)
            return ret;
    }

    /* Setup TX queue */
    txconf = dev_info.default_txconf;
    txconf.offloads = port_conf.txmode.offloads;
    for (q = 0; q < tx_rings; q++) {
        ret = rte_eth_tx_queue_setup(port, q, NUM_MBUFS,
                                     rte_eth_dev_socket_id(port),
                                     &txconf);
        if (ret < 0)
            return ret;
    }

    /* Start the Ethernet port */
    ret = rte_eth_dev_start(port);
    if (ret < 0)
        return ret;

    /* Enable promiscuous mode */
    rte_eth_promiscuous_enable(port);

    return 0;
}

/**
 * Packet filtering function
 * Returns 1 if packet should be forwarded, 0 otherwise
 */
static inline int
filter_packet(struct rte_mbuf *m)
{
    struct ether_hdr *eth_hdr;
    struct ipv4_hdr *ipv4_hdr;
    struct tcp_hdr *tcp_hdr;
    uint16_t dst_port;
    uint32_t dst_ip;

    /* Get Ethernet header */
    eth_hdr = rte_pktmbuf_mtod(m, struct ether_hdr *);

    /* Check if it's an IPv4 packet */
    if (eth_hdr->ether_type != rte_cpu_to_be_16(ETHER_TYPE_IPv4))
        return 0;

    /* Get IPv4 header */
    ipv4_hdr = (struct ipv4_hdr *)(eth_hdr + 1);

    /* Check destination IP */
    dst_ip = rte_be_to_cpu_32(ipv4_hdr->dst_addr);
    if (dst_ip != inet_addr(FILTER_DST_IP))
        return 0;

    /* Check protocol (TCP or UDP) */
    if (ipv4_hdr->next_proto_id == IPPROTO_TCP) {
        tcp_hdr = (struct tcp_hdr *)(ipv4_hdr + 1);
        dst_port = rte_be_to_cpu_16(tcp_hdr->dst_port);
    }
    else if (ipv4_hdr->next_proto_id == IPPROTO_UDP) {
        struct udp_hdr *udp_hdr = (struct udp_hdr *)(ipv4_hdr + 1);
        dst_port = rte_be_to_cpu_16(udp_hdr->dst_port);
    }
    else {
        return 0; /* Not TCP or UDP */
    }

    /* Check destination port */
    if (dst_port != FILTER_DST_PORT)
        return 0;

    return 1;
}

/**
 * Main processing loop for each core
 */
static void
lcore_main(void)
{
    struct rte_mbuf *bufs[BURST_SIZE];
    uint16_t nb_rx;
    uint16_t nb_tx;
    uint16_t i;

    printf("\nCore %u forwarding packets. [Ctrl+C to quit]\n",
           rte_lcore_id());

    while (!force_quit) {
        /* Receive burst of packets */
        nb_rx = rte_eth_rx_burst(0, 0, bufs, BURST_SIZE);
        if (unlikely(nb_rx == 0))
            continue;

        /* Process each packet */
        for (i = 0; i < nb_rx; i++) {
            if (filter_packet(bufs[i])) {
                /* Set output port (same as input in this example) */
                bufs[i]->port = 0;
            } else {
                /* Drop the packet by not forwarding it */
                rte_pktmbuf_free(bufs[i]);
                bufs[i] = NULL;
            }
        }

        /* Send burst of packets */
        nb_tx = rte_eth_tx_burst(0, 0, bufs, nb_rx);
        if (unlikely(nb_tx < nb_rx)) {
            /* Free any unsent packets */
            for (i = nb_tx; i < nb_rx; i++)
                if (bufs[i] != NULL)
                    rte_pktmbuf_free(bufs[i]);
        }
    }
}

/**
 * Signal handler for clean shutdown
 */
static void
signal_handler(int signum)
{
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nSignal %d received, preparing to exit...\n", signum);
        force_quit = true;
    }
}

int
main(int argc, char **argv)
{
    int ret;
    uint16_t nb_ports;
    uint16_t portid;

    /* Initialize EAL */
    ret = rte_eal_init(argc, argv);
    if (ret < 0)
        rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");

    argc -= ret;
    argv += ret;

    /* Initialize default port configuration */
    init_port_conf();

    /* Check for port limits */
    nb_ports = rte_eth_dev_count_avail();
    if (nb_ports == 0)
        rte_exit(EXIT_FAILURE, "No Ethernet ports - bye\n");

    /* Creates a new mempool in memory to hold the mbufs */
    mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", NUM_MBUFS,
                                        MBUF_CACHE_SIZE, 0,
                                        RTE_MBUF_DEFAULT_BUF_SIZE,
                                        rte_socket_id());
    if (mbuf_pool == NULL)
        rte_exit(EXIT_FAILURE, "Cannot create mbuf pool\n");

    /* Setup signal handler */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Initialize port 0 */
    portid = 0;
    if (port_init(portid) != 0)
        rte_exit(EXIT_FAILURE, "Cannot init port %"PRIu16 "\n", portid);

    printf("Port %u initialized and ready for packet processing\n", portid);

    /* Launch main loop on each lcore */
    rte_eal_mp_remote_launch(lcore_main, NULL, CALL_MAIN);
    RTE_LCORE_FOREACH_WORKER(lcore_id) {
        if (rte_eal_wait_lcore(lcore_id) < 0)
            return -1;
    }

    /* Cleanup */
    rte_eal_cleanup();
    printf("Bye...\n");
    return 0;
}
```

