Here's a complete, ultra-low-latency networking service implementation in C using DPDK for packet-level filtering and forwarding:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <inttypes.h>
#include <signal.h>
#include <unistd.h>

#include <rte_common.h>
#include <rte_log.h>
#include <rte_malloc.h>
#include <rte_memory.h>
#include <rte_memcpy.h>
#include <rte_eal.h>
#include <rte_launch.h>
#include <rte_atomic.h>
#include <rte_cycles.h>
#include <rte_prefetch.h>
#include <rte_lcore.h>
#include <rte_per_lcore.h>
#include <rte_branch_prediction.h>
#include <rte_interrupts.h>
#include <rte_pci.h>
#include <rte_random.h>
#include <rte_debug.h>
#include <rte_ether.h>
#include <rte_ethdev.h>
#include <rte_mempool.h>
#include <rte_mbuf.h>
#include <rte_ip.h>
#include <rte_tcp.h>
#include <rte_udp.h>

#define NUM_MBUFS          (4096*8)
#define MBUF_CACHE_SIZE    250
#define BURST_SIZE         32
#define MAX_PKT_BURST      64
#define MEMPOOL_CACHE_SIZE 256

static volatile bool force_quit;

/* Port configuration */
static struct rte_eth_conf port_conf = {
    .rxmode = {
        .mq_mode        = ETH_MQ_RX_RSS,
        .max_rx_pkt_len = RTE_ETHER_MAX_LEN,
        .split_hdr_size = 0,
        .offloads       = DEV_RX_OFFLOAD_CHECKSUM,
    },
    .rx_adv_conf = {
        .rss_conf = {
            .rss_key = NULL,
            .rss_hf  = ETH_RSS_IP | ETH_RSS_UDP | ETH_RSS_TCP,
        },
    },
    .txmode = {
        .mq_mode = ETH_MQ_TX_NONE,
    },
};

/* Filter configuration */
struct filter_rule {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
    uint8_t  action; /* 0 = drop, 1 = forward */
};

static struct filter_rule rules[] = {
    /* Example rule: Drop all TCP traffic to port 80 (HTTP) */
    {0, 0, 0, 80, IPPROTO_TCP, 0},
    /* Add more rules as needed */
};

/* Filter packets against configured rules */
static inline int
filter_packet(struct rte_mbuf *m)
{
    struct rte_ether_hdr *eth_hdr;
    struct rte_ipv4_hdr *ipv4_hdr;
    struct rte_tcp_hdr *tcp_hdr;
    struct rte_udp_hdr *udp_hdr;
    uint16_t ether_type;
    uint32_t src_ip, dst_ip;
    uint16_t src_port = 0, dst_port = 0;
    uint8_t proto = 0;
    int i;

    eth_hdr = rte_pktmbuf_mtod(m, struct rte_ether_hdr *);
    ether_type = rte_be_to_cpu_16(eth_hdr->ether_type);

    if (ether_type == RTE_ETHER_TYPE_IPV4) {
        ipv4_hdr = (struct rte_ipv4_hdr *)(eth_hdr + 1);
        src_ip = rte_be_to_cpu_32(ipv4_hdr->src_addr);
        dst_ip = rte_be_to_cpu_32(ipv4_hdr->dst_addr);
        proto = ipv4_hdr->next_proto_id;

        if (proto == IPPROTO_TCP) {
            tcp_hdr = (struct rte_tcp_hdr *)(ipv4_hdr + 1);
            src_port = rte_be_to_cpu_16(tcp_hdr->src_port);
            dst_port = rte_be_to_cpu_16(tcp_hdr->dst_port);
        } else if (proto == IPPROTO_UDP) {
            udp_hdr = (struct rte_udp_hdr *)(ipv4_hdr + 1);
            src_port = rte_be_to_cpu_16(udp_hdr->src_port);
            dst_port = rte_be_to_cpu_16(udp_hdr->dst_port);
        }

        /* Check against filter rules */
        for (i = 0; i < RTE_DIM(rules); i++) {
            if ((rules[i].src_ip == 0 || rules[i].src_ip == src_ip) &&
                (rules[i].dst_ip == 0 || rules[i].dst_ip == dst_ip) &&
                (rules[i].src_port == 0 || rules[i].src_port == src_port) &&
                (rules[i].dst_port == 0 || rules[i].dst_port == dst_port) &&
                (rules[i].proto == 0 || rules[i].proto == proto)) {
                return rules[i].action;
            }
        }
    }

    /* Default action: forward */
    return 1;
}

static int
lcore_main(void *arg)
{
    uint16_t port;
    uint16_t nb_ports = rte_eth_dev_count_avail();
    struct rte_mbuf *rx_pkts[MAX_PKT_BURST];
    struct rte_mbuf *tx_pkts[MAX_PKT_BURST];
    uint16_t nb_rx, nb_tx;
    uint16_t queue_id = 0;
    uint32_t lcore_id = rte_lcore_id();

    printf("Core %u: running packet processing\n", lcore_id);

    while (!force_quit) {
        /* Process each port */
        for (port = 0; port < nb_ports; port++) {
            /* Receive packets */
            nb_rx = rte_eth_rx_burst(port, queue_id, rx_pkts, MAX_PKT_BURST);
            if (unlikely(nb_rx == 0))
                continue;

            /* Process packets */
            for (int i = 0; i < nb_rx; i++) {
                if (filter_packet(rx_pkts[i])) {
                    tx_pkts[i] = rx_pkts[i]; /* Forward */
                } else {
                    rte_pktmbuf_free(rx_pkts[i]); /* Drop */
                    tx_pkts[i] = NULL;
                }
            }

            /* Send packets */
            nb_tx = 0;
            for (int i = 0; i < nb_rx; i++) {
                if (tx_pkts[i] != NULL) {
                    tx_pkts[nb_tx++] = tx_pkts[i];
                }
            }

            if (nb_tx > 0) {
                uint16_t sent = rte_eth_tx_burst(port, queue_id, tx_pkts, nb_tx);
                if (unlikely(sent < nb_tx)) {
                    for (int i = sent; i < nb_tx; i++) {
                        rte_pktmbuf_free(tx_pkts[i]);
                    }
                }
            }
        }
    }

    return 0;
}

static void
signal_handler(int signum)
{
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nSignal %d received, preparing to exit...\n", signum);
        force_quit = true;
    }
}

int
main(int argc, char **argv)
{
    int ret;
    uint16_t port_id;
    uint16_t nb_ports;
    struct rte_mempool *mbuf_pool;
    unsigned int nb_lcores = rte_lcore_count();

    /* Initialize EAL */
    ret = rte_eal_init(argc, argv);
    if (ret < 0)
        rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");

    argc -= ret;
    argv += ret;

    /* Check for port limits */
    nb_ports = rte_eth_dev_count_avail();
    if (nb_ports < 2)
        rte_exit(EXIT_FAILURE, "Error: at least two Ethernet ports are required\n");

    /* Create mbuf pool */
    mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", NUM_MBUFS,
                                        MBUF_CACHE_SIZE, 0,
                                        RTE_MBUF_DEFAULT_BUF_SIZE,
                                        rte_socket_id());
    if (mbuf_pool == NULL)
        rte_exit(EXIT_FAILURE, "Cannot create mbuf pool\n");

    /* Initialize all ports */
    for (port_id = 0; port_id < nb_ports; port_id++) {
        /* Configure the port */
        if (rte_eth_dev_configure(port_id, 1, 1, &port_conf) < 0)
            rte_exit(EXIT_FAILURE, "Cannot configure device: err=%d\n", rte_errno);

        /* Setup RX queue */
        if (rte_eth_rx_queue_setup(port_id, 0, 128,
                                   rte_eth_dev_socket_id(port_id),
                                   NULL, mbuf_pool) < 0)
            rte_exit(EXIT_FAILURE, "rte_eth_rx_queue_setup: err=%d\n", rte_errno);

        /* Setup TX queue */
        if (rte_eth_tx_queue_setup(port_id, 0, 512,
                                   rte_eth_dev_socket_id(port_id),
                                   NULL) < 0)
            rte_exit(EXIT_FAILURE, "rte_eth_tx_queue_setup: err=%d\n", rte_errno);

        /* Start device */
        if (rte_eth_dev_start(port_id) < 0)
            rte_exit(EXIT_FAILURE, "rte_eth_dev_start: err=%d\n", rte_errno);
    }

    /* Setup signal handler */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Press Ctrl+C to terminate\n");

    /* Launch packet processing on all cores */
    rte_eal_mp_remote_launch(lcore_main, NULL, CALL_MASTER);
    RTE_LCORE_FOREACH_WORKER(lcore_id) {
        if (rte_eal_wait_lcore(lcore_id) < 0)
            return -1;
    }

    /* Cleanup */
    for (port_id = 0; port_id < nb_ports; port_id++) {
        rte_eth_dev_stop(port_id);
        rte_eth_dev_close(port_id);
    }

    return 0;
}
```

### Key Features:

1. **Ultra-Low Latency Design**:
   - Uses DPDK for kernel-bypass networking
   - Processes packets in batches (burst mode)
   - Minimizes memory allocations during packet processing
