```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <linux/if_packet.h>
#include <linux/if_ether.h>
#include <linux/filter.h>
#include <net/if.h>
#include <sys/ioctl.h>

#define BUFFER_SIZE 65536
#define FILTER_PORT 80

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <input_interface> <output_interface>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *in_iface = argv[1];
    const char *out_iface = argv[2];

    // Create raw socket for receiving
    int recv_sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (recv_sock < 0) {
        perror("socket recv");
        exit(EXIT_FAILURE);
    }

    // Bind to input interface
    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = if_nametoindex(in_iface);
    sll.sll_protocol = htons(ETH_P_ALL);

    if (bind(recv_sock, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind recv");
        close(recv_sock);
        exit(EXIT_FAILURE);
    }

    // Set up BPF filter for TCP port 80
    struct sock_filter bpf_code[] = {
        // Load Ethernet header's type field (2 bytes at offset 12)
        BPF_STMT(BPF_LD | BPF_H | BPF_ABS, 12),
        // If not IPv4, skip (0x0800 is IPv4)
        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, ETH_P_IP, 0, 1),
        BPF_STMT(BPF_RET | BPF_K, 0xFFFFFFFF), // Accept if IPv4

        // Load IP protocol (1 byte at offset 9)
        BPF_STMT(BPF_LD | BPF_B | BPF_ABS, 9),
        // If not TCP, skip (6 is TCP)
        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, IPPROTO_TCP, 0, 1),
        BPF_STMT(BPF_RET | BPF_K, 0xFFFFFFFF), // Accept if TCP

        // Load TCP destination port (2 bytes at offset 20+2)
        BPF_STMT(BPF_LD | BPF_H | BPF_ABS, 22),
        // If not port 80, skip
        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, FILTER_PORT, 0, 1),
        BPF_STMT(BPF_RET | BPF_K, 0xFFFFFFFF), // Accept if port 80

        // Default: drop
        BPF_STMT(BPF_RET | BPF_K, 0),
    };

    struct sock_fprog bpf_prog = {
        .len = sizeof(bpf_code) / sizeof(bpf_code[0]),
        .filter = bpf_code,
    };

    if (setsockopt(recv_sock, SOL_SOCKET, SO_ATTACH_FILTER, &bpf_prog, sizeof(bpf_prog)) < 0) {
        perror("setsockopt filter");
        close(recv_sock);
        exit(EXIT_FAILURE);
    }

    // Create raw socket for sending
    int send_sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (send_sock < 0) {
        perror("socket send");
        close(recv_sock);
        exit(EXIT_FAILURE);
    }

    // Bind to output interface
    sll.sll_ifindex = if_nametoindex(out_iface);
    if (bind(send_sock, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind send");
        close(recv_sock);
        close(send_sock);
        exit(EXIT_FAILURE);
    }

    // Main loop: receive and forward packets
    char buffer[BUFFER_SIZE];
    while (1) {
        ssize_t len = recv(recv_sock, buffer, BUFFER_SIZE, 0);
        if (len < 0) {
            perror("recv");
            continue;
        }

        // Forward the packet
        if (send(send_sock, buffer, len, 0) < 0) {
            perror("send");
        }
    }

    // Cleanup (unreachable in this example)
    close(recv_sock);
    close(send_sock);
    return 0;
}
