#define FILTER_DST_IP "192.168.1.100"
#define FILTER_DST_PORT 80

static volatile bool force_quit;

/* Filter function: checks if packet matches the filter criteria */
static inline int
filter_packet(struct rte_mbuf *m)
{
    struct ether_hdr *eth_hdr;
    struct ipv4_hdr *ipv4_hdr;
    struct tcp_hdr *tcp_hdr;
    uint16_t dst_port;
    uint32_t dst_ip;

    eth_hdr = rte_pktmbuf_mtod(m, struct ether_hdr *);

    /* Check if it's an IPv4 packet */
    if (eth_hdr->ether_type != rte_cpu_to_be_16(ETHER_TYPE_IPv4))
        return 0;

    ipv4_hdr = (struct ipv4_hdr *)(eth_hdr + 1);

    /* Check destination IP */
    dst_ip = rte_be_to_cpu_32(ipv4_hdr->dst_addr);
    if (dst_ip != inet_addr(FILTER_DST_IP))
        return 0;

    /* Check if it's a TCP packet */
    if (ipv4_hdr->next_proto_id != IPPROTO_TCP)
        return 0;

    tcp_hdr = (struct tcp_hdr *)(ipv4_hdr + 1);

    /* Check destination port */
    dst_port = rte_be_to_cpu_16(tcp_hdr->dst_port);
    if (dst_port != FILTER_DST_PORT)
        return 0;

    return 1;
}

/* Main processing loop */
static void
lcore_main(void)
{
    struct rte_mbuf *bufs[BURST_SIZE];
    uint16_t nb_rx;
    uint16_t nb_tx;
    uint16_t i;

    printf("\nCore %u forwarding packets. [Ctrl+C to quit]\n",
           rte_lcore_id());

    while (!force_quit) {
        /* Receive burst of packets */
        nb_rx = rte_eth_rx_burst(0, 0, bufs, BURST_SIZE);
        if (unlikely(nb_rx == 0))
            continue;

        /* Process each packet */
        for (i = 0; i < nb_rx; i++) {
            if (filter_packet(bufs[i])) {
                /* Forward the packet (in this example, we'll just send it back out the same port) */
                bufs[i]->port = 0; /* Set output port */
            } else {
                /* Drop the packet by not forwarding it */
                rte_pktmbuf_free(bufs[i]);
                bufs[i] = NULL;
            }
        }

        /* Send burst of packets */
        nb_tx = rte_eth_tx_burst(0, 0, bufs, nb_rx);
        if (unlikely(nb_tx < nb_rx)) {
            /* Free any unsent packets */
            for (i = nb_tx; i < nb_rx; i++)
                rte_pktmbuf_free(bufs[i]);
        }
    }
}

