            if (unlikely(nb_rx == 0))
                continue;

            /* Filter and forward packets */
            for (int i = 0; i < nb_rx; i++) {
                if (filter_packet(bufs[i])) {
                    /* Forward to port 1 (example) */
                    nb_tx = rte_eth_tx_burst(1, 0, &bufs[i], 1);
                    if (unlikely(nb_tx < 1)) {
                        rte_pktmbuf_free(bufs[i]);
                    }
                } else {
                    rte_pktmbuf_free(bufs[i]);
                }
            }
        }
    }

    return 0;
}

static void
signal_handler(int signum)
{
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nSignal %d received, preparing to exit...\n", signum);
        force_quit = true;
    }
}

int
main(int argc, char **argv)
{
    int ret;
    uint16_t nb_ports;
    uint16_t port_id;
    struct rte_mempool *mbuf_pool;

    /* Initialize EAL */
    ret = rte_eal_init(argc, argv);
    if (ret < 0)
        rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");

    argc -= ret;
    argv += ret;

    /* Check for port limits */
    nb_ports = rte_eth_dev_count_avail();
    if (nb_ports < 2)
        rte_exit(EXIT_FAILURE, "Error: at least two Ethernet ports are required\n");

    /* Create mbuf pool */
    mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", NUM_MBUFS * nb_ports,
                                        MBUF_CACHE_SIZE, 0,
                                        RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id());
    if (mbuf_pool == NULL)
        rte_exit(EXIT_FAILURE, "Cannot create mbuf pool\n");

    /* Initialize all ports */
    for (port_id = 0; port_id < nb_ports; port_id++) {
        /* Configure the port */
        if (rte_eth_dev_configure(port_id, 1, 1, &port_conf) < 0)
            rte_exit(EXIT_FAILURE, "Cannot configure device: err=%d\n", rte_errno);

        /* Setup RX queue */
        if (rte_eth_rx_queue_setup(port_id, 0, 128,
                                   rte_eth_dev_socket_id(port_id),
                                   NULL, mbuf_pool) < 0)
            rte_exit(EXIT_FAILURE, "rte_eth_rx_queue_setup: err=%d\n", rte_errno);

        /* Setup TX queue */
        if (rte_eth_tx_queue_setup(port_id, 0, 512,
                                   rte_eth_dev_socket_id(port_id),
                                   NULL) < 0)
            rte_exit(EXIT_FAILURE, "rte_eth_tx_queue_setup: err=%d\n", rte_errno);

        /* Start device */
        if (rte_eth_dev_start(port_id) < 0)
            rte_exit(EXIT_FAILURE, "rte_eth_dev_start: err=%d\n", rte_errno);
    }

    /* Setup signal handler */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Launch per-lcore init on every lcore */
    rte_eal_mp_remote_launch(lcore_main, NULL, CALL_MASTER);
    RTE_LCORE_FOREACH_WORKER(lcore_id) {
        if (rte_eal_wait_lcore(lcore_id) < 0)
            return -1;
    }

    /* Cleanup */
    for (port_id = 0; port_id < nb_ports; port_id++) {
        rte_eth_dev_stop(port_id);
        rte_eth_dev_close(port_id);
    }

    return 0;
}
```

### Key Features of This Implementation:
1. **DPDK Integration**: Uses DPDK for high-performance packet I/O.
2. **Packet Filtering**: Filters out TCP packets destined for port 80 (HTTP).
3. **Burst Processing**: Processes packets in bursts to reduce overhead.
4. **Signal Handling**: Gracefully exits on SIGINT/SIGTERM.
