#ifndef FILTER_H
#define FILTER_H

#include <rte_mbuf.h>

/**
 * @brief Filters packets based on Ethernet type (IPv4 in this example).
 * @param m DPDK packet buffer.
 * @return 1 if packet should be forwarded, 0 if dropped.
 */
int filter_packet(struct rte_mbuf *m);

