#### **`filter.c`** (Packet filtering implementation)
```c
#include "filter.h"
#include <rte_ether.h>
#include <rte_ip.h>

int filter_packet(struct rte_mbuf *m) {
    struct rte_ether_hdr *eth_hdr;
    uint16_t ether_type;

    // Get Ethernet header from the packet buffer
    eth_hdr = rte_pktmbuf_mtod(m, struct rte_ether_hdr *);
    ether_type = rte_be_to_cpu_16(eth_hdr->ether_type);

    // Accept only IPv4 packets (Ethernet type 0x0800)
    return (ether_type == RTE_ETHER_TYPE_IPV4);
}
```

