```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <inttypes.h>
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_mempool.h>
#include "filter.h"

#define NUM_MBUFS       (8191)  // Number of packet buffers
#define MBUF_CACHE_SIZE (250)   // Cache size for mbuf objects
#define BURST_SIZE      (32)    // Max packets to receive/transmit in one burst

static struct rte_mempool *mbuf_pool = NULL;
static uint16_t port_id = 0;     // Port ID to use

/**
 * @brief Initializes a DPDK port.
 * @param port Port ID.
 * @param mbuf_pool Memory pool for packet buffers.
 * @return 0 on success, -1 on failure.
 */
static inline int port_init(uint16_t port, struct rte_mempool *mbuf_pool) {
    struct rte_eth_conf port_conf = {0};
    const uint16_t rx_rings = 1;  // Number of RX queues
    const uint16_t tx_rings = 1;  // Number of TX queues
    int ret;
    uint16_t q;

    // Validate port
    if (!rte_eth_dev_is_valid_port(port))
        return -1;

    // Configure port (RX offloads for checksum validation)
    port_conf.rxmode.mq_mode = ETH_MQ_RX_RSS;
    port_conf.rxmode.max_rx_pkt_len = RTE_ETHER_MAX_LEN;
    port_conf.rxmode.offloads = DEV_RX_OFFLOAD_CHECKSUM;

    // Configure the Ethernet device
    ret = rte_eth_dev_configure(port, rx_rings, tx_rings, &port_conf);
    if (ret != 0)
        return ret;

    // Setup RX queue
    for (q = 0; q < rx_rings; q++) {
        ret = rte_eth_rx_queue_setup(
            port, q, NUM_MBUFS,
            rte_eth_dev_socket_id(port),
            NULL, mbuf_pool
        );
        if (ret < 0)
            return ret;
    }

    // Setup TX queue
    for (q = 0; q < tx_rings; q++) {
        ret = rte_eth_tx_queue_setup(
            port, q, NUM_MBUFS,
            rte_eth_dev_socket_id(port),
            NULL
        );
        if (ret < 0)
            return ret;
    }

    // Start the Ethernet port
    ret = rte_eth_dev_start(port);
    if (ret < 0)
        return ret;

    return 0;
}

int main(int argc, char **argv) {
    int ret;
    uint16_t nb_ports;
    uint16_t port = 0;  // Use port 0

    // Initialize EAL (Environment Abstraction Layer)
    ret = rte_eal_init(argc, argv);
    if (ret < 0)
        rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");

    argc -= ret;
    argv += ret;

    // Check available ports
    nb_ports = rte_eth_dev_count_avail();
    if (nb_ports == 0)
        rte_exit(EXIT_FAILURE, "No Ethernet ports available\n");

    // Create packet buffer pool
    mbuf_pool = rte_pktmbuf_pool_create(
        "MBUF_POOL", NUM_MBUFS,
        MBUF_CACHE_SIZE, 0,
        RTE_MBUF_DEFAULT_BUF_SIZE,
        rte_socket_id()
    );
    if (mbuf_pool == NULL)
        rte_exit(EXIT_FAILURE, "Cannot create mbuf pool\n");

    // Initialize the port
    if (port_init(port, mbuf_pool) != 0)
        rte_exit(EXIT_FAILURE, "Cannot init port %"PRIu16 "\n", port);

    printf("Port %u initialized and started\n", port);

    // Main packet processing loop
    while (1) {
        struct rte_mbuf *bufs[BURST_SIZE];
        uint16_t nb_rx = rte_eth_rx_burst(port, 0, bufs, BURST_SIZE);

        if (unlikely(nb_rx == 0))
            continue;

        for (uint16_t i = 0; i < nb_rx; i++) {
            struct rte_mbuf *m = bufs[i];

            // Filter and forward packets
            if (filter_packet(m)) {
                uint16_t nb_tx = rte_eth_tx_burst(port, 0, &m, 1);
                if (unlikely(nb_tx < 1)) {
                    rte_pktmbuf_free(m);  // Free if TX fails
                }
            } else {
                rte_pktmbuf_free(m);  // Drop if not matching filter
            }
        }
    }

    return 0;
}
