```rust
use pnet::datalink::{self, Channel::Ethernet, NetworkInterface};
use pnet::packet::ethernet::{EthernetPacket, EtherTypes};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::env;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: {} <input_interface> <output_interface>", args[0]);
        std::process::exit(1);
    }
    let input_interface_name = &args[1];
    let output_interface_name = &args[2];

    // Find the input interface
    let input_interface = datalink::interfaces()
        .into_iter()
        .find(|iface| iface.name == *input_interface_name)
        .expect("Input interface not found");

    // Find the output interface
    let output_interface = datalink::interfaces()
        .into_iter()
        .find(|iface| iface.name == *output_interface_name)
        .expect("Output interface not found");

    // Create a channel to receive packets (promiscuous mode)
    let (_, mut rx) = match datalink::channel(&input_interface, Default::default()) {
        Ok(Ethernet(tx, rx)) => (tx, rx),
        Ok(_) => panic!("Unsupported channel type (not Ethernet)"),
        Err(e) => panic!("Error creating receive channel: {}", e),
    };

    // Create a channel to send packets
    let (mut tx, _) = match datalink::channel(&output_interface, Default::default()) {
        Ok(Ethernet(tx, rx)) => (tx, rx),
        Ok(_) => panic!("Unsupported channel type (not Ethernet)"),
        Err(e) => panic!("Error creating send channel: {}", e),
    };

    println!(
        "🚀 Forwarding UDP port 1234 from {} → {}",
        input_interface_name, output_interface_name
    );

    loop {
        match rx.next() {
            Ok(packet) => {
                if let Some(ethernet) = EthernetPacket::new(packet) {
                    // Filter IPv4 packets
                    if ethernet.get_ethertype() == EtherTypes::Ipv4 {
                        if let Some(ipv4) = Ipv4Packet::new(ethernet.payload()) {
                            // Filter UDP packets
                            if ipv4.get_next_level_protocol() == IpNextHeaderProtocols::Udp {
                                if let Some(udp) = UdpPacket::new(ipv4.payload()) {
                                    // Forward only UDP packets with destination port 1234
                                    if udp.get_destination() == 1234 {
                                        if let Err(e) = tx.send_to(ethernet.packet(), None) {
                                            eprintln!("⚠️ Failed to forward packet: {}", e);
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            Err(e) => eprintln!("❌ Error receiving packet: {}", e),
        }
    }
}
```

