### 📦 Minimal Ultra-Low-Latency Packet Filter & Forwarder

```c
#include <linux/if_packet.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <netinet/ether.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <net/if.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <stdint.h>
#include <poll.h>
#include <sys/mman.h>

#define IN_INTERFACE  "eth0"
#define OUT_INTERFACE "eth1"
#define BUFFER_SIZE   (1 << 22)  // 4MB ring buffer
#define FRAME_SIZE    2048       // Max frame size

// Simple BPF filter: only IPv4 packets (ether type 0x0800)
static struct sock_filter bpf_code[] = {
    { 0x28, 0, 0, 0x0000000c },  // Load ethhdr->h_proto
    { 0x15, 0, 1, 0x00000800 },  // Jump if == ETH_P_IP (0x0800)
    { 0x06, 0, 0, 0x0000ffff },  // Return 0 (drop)
    { 0x06, 0, 0, 0xffffffff },  // Return -1 (accept)
};

static struct sock_fprog bpf_prog = {
    .len = sizeof(bpf_code) / sizeof(bpf_code[0]),
    .filter = bpf_code,
};

int main() {
    int sock_fd = -1;
    struct sockaddr_ll sll = {0};
    struct ifreq ifr = {0};
    void *ring = NULL;
    struct tpacket_req3 req;
    int out_sock = -1;
    struct sockaddr_ll out_sll = {0};
    struct ifreq out_ifr = {0};

    // === Step 1: Open AF_PACKET socket ===
    sock_fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sock_fd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // === Step 2: Bind to input interface ===
    strncpy(ifr.ifr_name, IN_INTERFACE, IFNAMSIZ);
    if (ioctl(sock_fd, SIOCGIFINDEX, &ifr) < 0) {
        perror("ioctl SIOCGIFINDEX");
        close(sock_fd);
        exit(EXIT_FAILURE);
    }

    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = ifr.ifr_ifindex;
    sll.sll_protocol = htons(ETH_P_ALL);

    if (bind(sock_fd, (struct sockaddr*)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(sock_fd);
        exit(EXIT_FAILURE);
    }

    // === Step 3: Set up TPACKET_V3 ring buffer ===
    memset(&req, 0, sizeof(req));
    req.tp_block_size = BUFFER_SIZE;
    req.tp_frame_size = FRAME_SIZE;
    req.tp_block_nr = 1;
    req.tp_frame_nr = BUFFER_SIZE / FRAME_SIZE;

    if (setsockopt(sock_fd, SOL_PACKET, PACKET_RX_RING, &req, sizeof(req)) < 0) {
        perror("setsockopt PACKET_RX_RING");
        close(sock_fd);
        exit(EXIT_FAILURE);
    }

    ring = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, sock_fd, 0);
    if (ring == MAP_FAILED) {
        perror("mmap");
        close(sock_fd);
        exit(EXIT_FAILURE);
    }

    // === Step 4: Attach BPF filter ===
    if (setsockopt(sock_fd, SOL_SOCKET, SO_ATTACH_FILTER, &bpf_prog, sizeof(bpf_prog)) < 0) {
        perror("setsockopt SO_ATTACH_FILTER");
        munmap(ring, BUFFER_SIZE);
        close(sock_fd);
        exit(EXIT_FAILURE);
    }

    // === Step 5: Open output socket ===
    out_sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (out_sock < 0) {
        perror("output socket");
        munmap(ring, BUFFER_SIZE);
        close(sock_fd);
        exit(EXIT_FAILURE);
    }

    strncpy(out_ifr.ifr_name, OUT_INTERFACE, IFNAMSIZ);
    if (ioctl(out_sock, SIOCGIFINDEX, &out_ifr) < 0) {
        perror("ioctl output SIOCGIFINDEX");
        close(out_sock);
        munmap(ring, BUFFER_SIZE);
        close(sock_fd);
        exit(EXIT_FAILURE);
    }

    out_sll.sll_family = AF_PACKET;
    out_sll.sll_ifindex = out_ifr.ifr_ifindex;
    out_sll.sll_protocol = htons(ETH_P_ALL);
    out_sll.sll_halen = ETH_ALEN;

    // === Step 6: Main loop: receive and forward ===
    struct pollfd pfd = { .fd = sock_fd, .events = POLLIN };
    while (1) {
        int ret = poll(&pfd, 1, -1);
        if (ret <= 0) {
            if (errno == EINTR) continue;
            perror("poll");
            break;
        }

        // Process all available packets
        while (1) {
            struct tpacket3_hdr *hdr = (struct tpacket3_hdr*)ring;
            if ((hdr->tp_status & TP_STATUS_USER) == 0) break;  // No more packets

            // Extract packet data
            unsigned char *packet = (unsigned char*)hdr + hdr->tp_mac;
            size_t len = hdr->tp_len;

            // Forward packet to output interface
            if (sendto(out_sock, packet, len, 0,
                       (struct sockaddr*)&out_sll, sizeof(out_sll)) < 0) {
                perror("sendto");
            }

            // Mark buffer as free
            hdr->tp_status = TP_STATUS_KERNEL;
        }
    }

    // Cleanup
    munmap(ring, BUFFER_SIZE);
    close(out_sock);
    close(sock_fd);
    return 0;
}
```

