### **Minimal Ultra-Low-Latency Packet Filter/Forwarder in Zig**
```zig
const std = @import("std");
const os = std.os;
const mem = std.mem;
const debug = std.debug;

// Ethernet header (simplified)
const EthHdr = extern struct {
    dst_mac: [6]u8,
    src_mac: [6]u8,
    ethertype: u16,
};

// IPv4 header (simplified)
const IpHdr = extern struct {
    version_ihl: u8,
    dscp_ecn: u8,
    total_len: u16,
    id: u16,
    flags_frag_offset: u16,
    ttl: u8,
    proto: u8,
    checksum: u16,
    src_ip: u32,
    dst_ip: u32,
};

// UDP header (simplified)
const UdpHdr = extern struct {
    src_port: u16,
    dst_port: u16,
    len: u16,
    checksum: u16,
};

// TCP header (simplified)
const TcpHdr = extern struct {
    src_port: u16,
    dst_port: u16,
    seq: u32,
    ack: u32,
    flags: u16,
    window_size: u16,
    checksum: u16,
    urgent_ptr: u16,
};

// --- Packet Parsing ---
fn parseEthHdr(packet: []const u8) ?EthHdr {
    if (packet.len < @sizeOf(EthHdr)) return null;
    return @ptrCast([*]const EthHdr, packet.ptr)[0];
}

fn parseIpHdr(packet: []const u8) ?IpHdr {
    const eth_hdr = parseEthHdr(packet) orelse return null;
    if (mem.readInt(u16, &eth_hdr.ethertype, .big) != 0x0800) return null; // IPv4
    const ip_offset = @sizeOf(EthHdr);
    if (packet.len < ip_offset + @sizeOf(IpHdr)) return null;
    return @ptrCast([*]const IpHdr, packet.ptr + ip_offset)[0];
}

fn parseTransportHdr(packet: []const u8, ip_hdr: *const IpHdr) ?[]const u8 {
    const ip_offset = @sizeOf(EthHdr);
    const ip_hdr_len = (@intCast(u5, ip_hdr.version_ihl & 0x0F) * 4);
    const transport_offset = ip_offset + ip_hdr_len;
    if (packet.len < transport_offset) return null;
    return packet[transport_offset..];
}

// --- Filtering Logic ---
fn shouldForward(packet: []const u8) bool {
    const ip_hdr = parseIpHdr(packet) orelse return false;
    const transport_hdr = parseTransportHdr(packet, &ip_hdr) orelse return false;
    const proto = ip_hdr.proto;

    if (proto == 17) { // UDP
        if (transport_hdr.len < @sizeOf(UdpHdr)) return false;
        const udp_hdr = @ptrCast([*]const UdpHdr, transport_hdr.ptr)[0];
        return mem.readInt(u16, &udp_hdr.dst_port, .big) == 80;
    } else if (proto == 6) { // TCP
        if (transport_hdr.len < @sizeOf(TcpHdr)) return false;
        const tcp_hdr = @ptrCast([*]const TcpHdr, transport_hdr.ptr)[0];
        return mem.readInt(u16, &tcp_hdr.dst_port, .big) == 80;
    }
    return false;
}

// --- Packet Forwarding ---
fn forwardPacket(packet: []const u8, out_fd: os.fd_t) !void {
    try os.write(out_fd, packet);
}

// --- Main Service ---
pub fn main() !void {
    // Open raw sockets for RX (ingress) and TX (egress)
    const rx_fd = try os.socket(os.AF_PACKET, os.SOCK_RAW, os.htons(0x0800)); // IPv4
    const tx_fd = try os.socket(os.AF_PACKET, os.SOCK_RAW, os.htons(0x0800)); // IPv4
    defer {
        os.close(rx_fd) catch {};
        os.close(tx_fd) catch {};
    }

    // Bind RX socket to an interface (e.g., "eth0")
    // Note: Linux-specific. Replace "eth0" with your interface.
    const iface = "eth0";
    try os.setsockopt(
        rx_fd,
        os.SOL_SOCKET,
        os.SO_BINDTODEVICE,
        iface,
    );

    // Bind TX socket to the same interface
    try os.setsockopt(
        tx_fd,
        os.SOL_SOCKET,
        os.SO_BINDTODEVICE,
        iface,
    );

    // Allocate a packet buffer (max Ethernet frame size)
    var buf: [1514]u8 = undefined;

    debug.print("Ultra-low-latency packet filter/forwarder running...\n", .{});
    debug.print("Forwarding TCP/UDP port 80 packets from {s}...\n", .{iface});

    while (true) {
        const bytes_received = try os.recv(rx_fd, &buf, .{});
        if (bytes_received <= 0) continue;

        const packet = buf[0..bytes_received];
        if (shouldForward(packet)) {
            try forwardPacket(packet, tx_fd);
        }
    }
}
```

