### **Minimal Ultra-Low-Latency Packet Filter & Forwarder**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <inttypes.h>
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_ip.h>

#define NUM_MBUFS       (4096-1)  // Number of mbufs in mempool
#define MBUF_CACHE_SIZE  250       // Cache size for mbuf allocation
#define BURST_SIZE       32        // Max burst size for RX/TX

// Filtering criteria: Forward packets with this destination IP
#define FILTER_IP "192.168.1.100"

// Convert IP string to uint32_t (e.g., "192.168.1.1" → 0xC0A80101)
static uint32_t ip_to_uint(const char *ip) {
    unsigned a, b, c, d;
    if (sscanf(ip, "%u.%u.%u.%u", &a, &b, &c, &d) != 4)
        rte_exit(EXIT_FAILURE, "Invalid IP address: %s\n", ip);
    return (a << 24) | (b << 16) | (c << 8) | d;
}

// Initialize a single DPDK port
static inline int port_init(uint16_t port, struct rte_mempool *mbuf_pool) {
    struct rte_eth_conf port_conf = {0};
    const uint16_t rx_rings = 1, tx_rings = 1;
    int ret;
    uint16_t q;

    // Validate port
    if (!rte_eth_dev_is_valid_port(port))
        return -1;

    // Configure port
    port_conf.rxmode.mq_mode = ETH_MQ_RX_RSS;
    port_conf.rxmode.max_rx_pkt_len = RTE_ETHER_MAX_LEN;
    port_conf.rxmode.offloads = DEV_RX_OFFLOAD_CHECKSUM;

    // Configure and start the port
    ret = rte_eth_dev_configure(port, rx_rings, tx_rings, &port_conf);
    if (ret < 0) return ret;

    // Setup RX queue
    for (q = 0; q < rx_rings; q++) {
        ret = rte_eth_rx_queue_setup(
            port, q, MBUF_CACHE_SIZE,
            rte_eth_dev_socket_id(port), NULL, mbuf_pool
        );
        if (ret < 0) return ret;
    }

    // Setup TX queue
    for (q = 0; q < tx_rings; q++) {
        ret = rte_eth_tx_queue_setup(
            port, q, MBUF_CACHE_SIZE,
            rte_eth_dev_socket_id(port), NULL
        );
        if (ret < 0) return ret;
    }

    // Start the port and enable promiscuous mode
    ret = rte_eth_dev_start(port);
    if (ret < 0) return ret;
    rte_eth_promiscuous_enable(port);

    return 0;
}

// Filter and forward packets (IPv4 only)
static void filter_and_forward(struct rte_mbuf *m, uint16_t port) {
    struct rte_ether_hdr *eth_hdr;
    struct rte_ipv4_hdr *ip_hdr;
    uint32_t dst_ip = ip_to_uint(FILTER_IP);

    // Parse Ethernet header
    eth_hdr = rte_pktmbuf_mtod(m, struct rte_ether_hdr *);
    if (eth_hdr->ether_type != rte_cpu_to_be_16(RTE_ETHER_TYPE_IPV4)) {
        rte_pktmbuf_free(m);  // Drop non-IPv4 packets
        return;
    }

    // Parse IPv4 header
    ip_hdr = rte_pktmbuf_mtod_offset(
        m, struct rte_ipv4_hdr *, sizeof(struct rte_ether_hdr)
    );
    if (rte_be_to_cpu_32(ip_hdr->dst_addr) == dst_ip) {
        // Forward matching packets (same port for simplicity)
        if (rte_eth_tx_burst(port, 0, &m, 1) < 1)
            rte_pktmbuf_free(m);  // Free if TX fails
    } else {
        rte_pktmbuf_free(m);  // Drop non-matching packets
    }
}

int main(int argc, char **argv) {
    int ret;
    uint16_t port;
    struct rte_mempool *mbuf_pool;
    struct rte_mbuf *bufs[BURST_SIZE];
    uint32_t filter_ip = ip_to_uint(FILTER_IP);

    // Initialize EAL (Environment Abstraction Layer)
    ret = rte_eal_init(argc, argv);
    if (ret < 0) rte_exit(EXIT_FAILURE, "EAL init failed\n");
    argc -= ret; argv += ret;

    // Validate ports
    if (rte_eth_dev_count_avail() < 1)
        rte_exit(EXIT_FAILURE, "No DPDK ports available\n");

    // Create mbuf pool
    mbuf_pool = rte_pktmbuf_pool_create(
        "MBUF_POOL", NUM_MBUFS, MBUF_CACHE_SIZE, 0,
        RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id()
    );
    if (!mbuf_pool) rte_exit(EXIT_FAILURE, "MBUF pool creation failed\n");

    // Initialize all ports
    RTE_ETH_FOREACH_DEV(port) {
        if (port_init(port, mbuf_pool) != 0)
            rte_exit(EXIT_FAILURE, "Port %u init failed\n", port);
    }

    printf("Filtering packets for IP: %s (0x%08X)\n", FILTER_IP, filter_ip);
    printf("Press Ctrl+C to exit...\n");

    // Main processing loop
    while (1) {
        RTE_ETH_FOREACH_DEV(port) {
            // Receive burst of packets
            uint16_t nb_rx = rte_eth_rx_burst(port, 0, bufs, BURST_SIZE);
            if (unlikely(nb_rx == 0)) continue;

            // Process each packet
            for (int i = 0; i < nb_rx; i++) {
                filter_and_forward(bufs[i], port);
            }
        }
    }

    // Cleanup (unreachable in this minimal example)
    RTE_ETH_FOREACH_DEV(port) {
        rte_eth_dev_stop(port);
        rte_eth_dev_close(port);
    }
    return 0;
}
```

