// Function to calculate IPv4 checksum
fn ipChecksum(header: []const u8) u16 {
    var sum: u32 = 0;
    var i: usize = 0;
    while (i < header.len) : (i += 2) {
        if (i + 1 < header.len) {
            sum += mem.readInt(u16, header[i..][0..2], .little);
        } else {
            sum += header[i] << 8;
        }
    }
    sum = (sum >> 16) + (sum & 0xFFFF);
    sum += sum >> 16;
    return @as(u16, @truncate(sum ^ 0xFFFF));
}

