    if (packet.len < @sizeOf(EthHdr) + @sizeOf(IpHdr)) return;

    const eth_hdr = @ptrCast([*]const EthHdr, packet.ptr);
    const ethertype = mem.readInt(u16, &eth_hdr.ethertype, .big);

