#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>
#include <rte_ip.h>
#include <rte_udp.h>

#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250
#define BURST_SIZE 32

// Filtering criteria: forward packets with this destination IP
#define FILTER_IP "192.168.1.100"

// MAC addresses for the ports (example, replace with actual MACs)
static struct rte_ether_addr port_eth_addr;

// Function to initialize a single port
static inline int
port_init(uint16_t port, struct rte_mempool *mbuf_pool)
{
    struct rte_eth_conf port_conf = {0};
    const uint16_t rx_rings = 1;
    const uint16_t tx_rings = 1;
    int ret;
    uint16_t q;

    if (!rte_eth_dev_is_valid_port(port))
        return -1;

    // Configure the Ethernet device
    port_conf.rxmode.mq_mode = ETH_MQ_RX_RSS;
    port_conf.rxmode.max_rx_pkt_len = RTE_ETHER_MAX_LEN;
    port_conf.rxmode.offloads = DEV_RX_OFFLOAD_CHECKSUM;

    ret = rte_eth_dev_configure(port, rx_rings, tx_rings, &port_conf);
    if (ret != 0)
        return ret;

    // Setup RX queue
    for (q = 0; q < rx_rings; q++) {
        ret = rte_eth_rx_queue_setup(port, q, MBUF_CACHE_SIZE,
                                     rte_eth_dev_socket_id(port),
                                     NULL, mbuf_pool);
        if (ret < 0)
            return ret;
    }

    // Setup TX queue
    for (q = 0; q < tx_rings; q++) {
        ret = rte_eth_tx_queue_setup(port, q, MBUF_CACHE_SIZE,
                                     rte_eth_dev_socket_id(port),
                                     NULL);
        if (ret < 0)
            return ret;
    }

    // Start the Ethernet port
    ret = rte_eth_dev_start(port);
    if (ret < 0)
        return ret;

    // Enable promiscuous mode to receive all packets
    rte_eth_promiscuous_enable(port);

    return 0;
}

// Function to filter and forward packets
static void
filter_and_forward(struct rte_mbuf *m, uint16_t port)
{
    struct rte_ether_hdr *eth_hdr;
    struct rte_ipv4_hdr *ip_hdr;
    uint32_t dst_ip;

    eth_hdr = rte_pktmbuf_mtod(m, struct rte_ether_hdr *);
    if (eth_hdr->ether_type != rte_cpu_to_be_16(RTE_ETHER_TYPE_IPV4))
        return; // Not an IPv4 packet

    ip_hdr = rte_pktmbuf_mtod_offset(m, struct rte_ipv4_hdr *,
                                     sizeof(struct rte_ether_hdr));
    dst_ip = rte_be_to_cpu_32(ip_hdr->dst_addr);

    // Convert FILTER_IP to uint32_t for comparison
    uint32_t filter_ip = 0;
    sscanf(FILTER_IP, "%" SCNu8 ".%" SCNu8 ".%" SCNu8 ".%" SCNu8,
           (uint8_t*)&filter_ip,
           (uint8_t*)&filter_ip + 1,
           (uint8_t*)&filter_ip + 2,
           (uint8_t*)&filter_ip + 3);

    if (dst_ip == filter_ip) {
        // Forward the packet out the specified port
        if (rte_eth_tx_burst(port, 0, &m, 1) < 1) {
            rte_pktmbuf_free(m); // Free if TX fails
        }
    } else {
        rte_pktmbuf_free(m); // Free if not matching filter
    }
}

int main(int argc, char **argv)
{
    int ret;
    uint16_t nb_ports;
    uint16_t port;
    struct rte_mempool *mbuf_pool;
    struct rte_mbuf *bufs[BURST_SIZE];

    // Initialize EAL
    ret = rte_eal_init(argc, argv);
    if (ret < 0)
        rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");

    argc -= ret;
    argv += ret;

    // Check for port limits
    nb_ports = rte_eth_dev_count_avail();
    if (nb_ports < 1)
        rte_exit(EXIT_FAILURE, "Error: no ports available\n");

    // Create mbuf pool
    mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", NUM_MBUFS,
                                        MBUF_CACHE_SIZE, 0,
                                        RTE_MBUF_DEFAULT_BUF_SIZE,
                                        rte_socket_id());
    if (mbuf_pool == NULL)
        rte_exit(EXIT_FAILURE, "Cannot create mbuf pool\n");

    // Initialize all ports
    RTE_ETH_FOREACH_DEV(port) {
        if (port_init(port, mbuf_pool) != 0)
            rte_exit(EXIT_FAILURE, "Cannot init port %"PRIu16 "\n", port);
    }

    // Main processing loop
    while (1) {
        RTE_ETH_FOREACH_DEV(port) {
            // Receive burst of packets
            uint16_t nb_rx = rte_eth_rx_burst(port, 0, bufs, BURST_SIZE);
            if (unlikely(nb_rx == 0))
                continue;

            // Process each received packet
            for (int i = 0; i < nb_rx; i++) {
                filter_and_forward(bufs[i], port);
            }
        }
    }

    // Cleanup (unreachable in this minimal example)
    RTE_ETH_FOREACH_DEV(port) {
        rte_eth_dev_stop(port);
        rte_eth_dev_close(port);
    }
    return 0;
}
