    port_conf.rxmode.max_rx_pkt_len = RTE_ETHER_MAX_LEN;
    port_conf.rxmode.offloads = DEV_RX_OFFLOAD_CHECKSUM;

    ret = rte_eth_dev_configure(port, rx_rings, tx_rings, &port_conf);
    if (ret != 0)
        return ret;

    // Setup RX queue
    for (q = 0; q < rx_rings; q++) {
