                                     rte_eth_dev_socket_id(port),
                                     NULL);
        if (ret < 0)
            return ret;
    }

    // Start the Ethernet port
    ret = rte_eth_dev_start(port);
    if (ret < 0)
        return ret;

    // Enable promiscuous mode to receive all packets
    rte_eth_promiscuous_enable(port);

    return 0;
}

// Function to filter and forward packets
static void
filter_and_forward(struct rte_mbuf *m, uint16_t port)
{
    struct rte_ether_hdr *eth_hdr;
    struct rte_ipv4_hdr *ip_hdr;
    uint32_t dst_ip;
    uint32_t filter_ip = ip_to_uint(FILTER_IP);

    eth_hdr = rte_pktmbuf_mtod(m, struct rte_ether_hdr *);
    if (eth_hdr->ether_type != rte_cpu_to_be_16(RTE_ETHER_TYPE_IPV4))
        goto free_packet; // Not an IPv4 packet

    ip_hdr = rte_pktmbuf_mtod_offset(m, struct rte_ipv4_hdr *,
                                     sizeof(struct rte_ether_hdr));
    dst_ip = rte_be_to_cpu_32(ip_hdr->dst_addr);

    if (dst_ip == filter_ip) {
        // Forward the packet out the same port (or another port in real use)
        if (rte_eth_tx_burst(port, 0, &m, 1) < 1) {
            goto free_packet; // Free if TX fails
        }
        return;
    }

free_packet:
    rte_pktmbuf_free(m); // Free if not matching filter or TX fails
}

int main(int argc, char **argv)
{
    int ret;
    uint16_t nb_ports;
    uint16_t port;
    struct rte_mempool *mbuf_pool;
    struct rte_mbuf *bufs[BURST_SIZE];
    uint32_t filter_ip = ip_to_uint(FILTER_IP);

    if (filter_ip == 0) {
        rte_exit(EXIT_FAILURE, "Invalid filter IP address\n");
    }

    // Initialize EAL
    ret = rte_eal_init(argc, argv);
    if (ret < 0)
        rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");

    argc -= ret;
    argv += ret;

    // Check for port limits
    nb_ports = rte_eth_dev_count_avail();
    if (nb_ports < 1)
        rte_exit(EXIT_FAILURE, "Error: no ports available\n");

    // Create mbuf pool
    mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", NUM_MBUFS,
                                        MBUF_CACHE_SIZE, 0,
                                        RTE_MBUF_DEFAULT_BUF_SIZE,
                                        rte_socket_id());
    if (mbuf_pool == NULL)
        rte_exit(EXIT_FAILURE, "Cannot create mbuf pool\n");

    // Initialize all ports
    RTE_ETH_FOREACH_DEV(port) {
        if (port_init(port, mbuf_pool) != 0)
            rte_exit(EXIT_FAILURE, "Cannot init port %"PRIu16 "\n", port);
    }

    printf("Filtering packets with destination IP: %s\n", FILTER_IP);
    printf("Press Ctrl+C to exit\n");

    // Main processing loop
    while (1) {
        RTE_ETH_FOREACH_DEV(port) {
            // Receive burst of packets
            uint16_t nb_rx = rte_eth_rx_burst(port, 0, bufs, BURST_SIZE);
            if (unlikely(nb_rx == 0))
                continue;

            // Process each received packet
            for (int i = 0; i < nb_rx; i++) {
                filter_and_forward(bufs[i], port);
            }
        }
    }

    // Cleanup (unreachable in this minimal example)
    RTE_ETH_FOREACH_DEV(port) {
        rte_eth_dev_stop(port);
        rte_eth_dev_close(port);
    }
    return 0;
}
