use memmap2::Mmap;
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;
use std::sync::Arc;

// Custom error type for parsing
#[derive(Debug)]
pub enum ParseError {
    IoError(io::Error),
    ParseError(String),
}

impl From<io::Error> for ParseError {
    fn from(err: io::Error) -> Self {
        ParseError::IoError(err)
    }
}

// Streaming CSV parser that processes records one at a time
pub struct StreamingCsvParser {
    reader: BufReader<File>,
    buffer: String,
    delimiter: u8,
    record_count: usize,
}

impl StreamingCsvParser {
    pub fn new<P: AsRef<Path>>(path: P, delimiter: u8) -> Result<Self, ParseError> {
        let file = File::open(path)?;
        let reader = BufReader::new(file);
        Ok(Self {
            reader,
            buffer: String::with_capacity(8192), // 8KB buffer
            delimiter,
            record_count: 0,
        })
    }

    // Memory-mapped alternative for even better performance with large files
    pub fn from_mmap<P: AsRef<Path>>(path: P, delimiter: u8) -> Result<Self, ParseError> {
        let file = File::open(path)?;
        let mmap = unsafe { Mmap::map(&file)? };
        let reader = BufReader::new(io::Cursor::new(mmap));
        Ok(Self {
            reader,
            buffer: String::with_capacity(8192),
            delimiter,
            record_count: 0,
        })
    }

    // Process records one at a time without loading entire file into memory
    pub fn process_records<F>(&mut self, mut processor: F) -> Result<usize, ParseError>
    where
        F: FnMut(&[&str]) -> Result<(), String>,
    {
        self.record_count = 0;
        self.buffer.clear();

        loop {
            // Read line by line to avoid loading entire file
            let bytes_read = self.reader.read_until(b'\n', &mut self.buffer)?;

            if bytes_read == 0 {
                break; // EOF
            }

            // Skip empty lines
            if self.buffer.trim().is_empty() {
                self.buffer.clear();
                continue;
            }

            // Split line into fields
            let fields: Vec<&str> = self.buffer
                .split(|c| c == self.delimiter as char)
                .map(|s| s.trim())
                .collect();

            if !fields.is_empty() {
                processor(&fields)?;
                self.record_count += 1;
            }

            self.buffer.clear();
        }

        Ok(self.record_count)
    }
}

// Alternative: Zero-copy parser using byte slices (most memory efficient)
pub struct ZeroCopyCsvParser<'a> {
    data: &'a [u8],
    pos: usize,
    delimiter: u8,
    record_count: usize,
}

impl<'a> ZeroCopyCsvParser<'a> {
    pub fn new(data: &'a [u8], delimiter: u8) -> Self {
        Self {
            data,
            pos: 0,
            delimiter,
            record_count: 0,
        }
    }

    pub fn process_records<F>(&mut self, mut processor: F) -> Result<usize, ParseError>
    where
        F: FnMut(&[&str]) -> Result<(), String>,
    {
        self.record_count = 0;

        while self.pos < self.data.len() {
            // Find next line
            let line_end = self.data[self.pos..]
                .iter()
                .position(|&b| b == b'\n')
                .map(|p| p + self.pos)
                .unwrap_or(self.data.len());

            // Process line
            let line = &self.data[self.pos..line_end];
            self.pos = line_end + 1; // Skip newline

            // Skip empty lines
            if line.is_empty() || line.iter().all(|&b| b == b'\r') {
                continue;
            }

            // Split fields without allocation
            let mut fields = Vec::new();
            let mut start = 0;

            for (i, &byte) in line.iter().enumerate() {
                if byte == self.delimiter {
                    fields.push(&line[start..i]);
                    start = i + 1;
                }
            }
            fields.push(&line[start..]); // Last field

            // Process fields
            processor(&fields)?;
            self.record_count += 1;
        }

        Ok(self.record_count)
    }
}

// Example usage
fn main() -> Result<(), ParseError> {
