/// Processes a single line of CSV data, invoking the field_processor for each field
fn process_csv_line<F>(line: &str, delimiter: char, mut field_processor: F) -> usize
where
    F: FnMut(&str),
{
    let mut field_count = 0;
    let mut start = 0;
    let mut in_quotes = false;
    let mut end = 0;
    let bytes = line.as_bytes();
    let len = bytes.len();

    while end < len {
        let c = bytes[end] as char;

        match c {
            '"' => {
                if in_quotes {
                    // Check for escaped quote ("")
                    if end + 1 < len && bytes[end + 1] as char == '"' {
                        end += 2; // Skip both quotes
                        continue;
                    }
                    in_quotes = false;
                } else {
                    in_quotes = true;
                }
                end += 1;
            }
            c if c == delimiter && !in_quotes => {
                let field = &line[start..end];
                field_processor(field.trim());
                field_count += 1;
                start = end + 1;
                end = start;
            }
            _ => {
                end += 1;
            }
        }
    }

    // Process the last field
    if start < end {
        let field = &line[start..end];
        field_processor(field.trim());
        field_count += 1;
    }

    field_count
}

