### **C++ Implementation (Buffered Chunked Reading)**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <stdexcept>

class StreamingParser {
public:
    explicit StreamingParser(size_t buffer_size = 1 << 20)  // Default: 1MB chunks
        : buffer_size_(buffer_size), buffer_(buffer_size) {}

    void parse(const std::string& filename) {
        std::ifstream file(filename, std::ios::binary);
        if (!file) {
            throw std::runtime_error("Failed to open file: " + filename);
        }

        size_t total_lines = 0;
        std::string leftover;  // Handles partial lines at chunk boundaries

        while (file) {
            file.read(buffer_.data(), buffer_size_);
            size_t bytes_read = file.gcount();
            if (bytes_read == 0) break;

            // Combine leftover from previous chunk with current chunk
            std::string chunk(buffer_.data(), bytes_read);
            if (!leftover.empty()) {
                chunk = leftover + chunk;
                leftover.clear();
            }

            // Split into lines, keeping the last partial line as leftover
            size_t last_newline = chunk.find_last_of('\n');
            if (last_newline == std::string::npos) {
                leftover = chunk;  // No newline found; keep for next chunk
                continue;
            }

            // Process all complete lines
            std::string complete_lines = chunk.substr(0, last_newline);
            total_lines += process_lines(complete_lines);

            // Save the leftover (partial line after last newline)
            leftover = chunk.substr(last_newline + 1);
        }

        // Process any remaining leftover data (last line without newline)
        if (!leftover.empty()) {
            total_lines += process_lines(leftover);
        }

        std::cout << "Total lines processed: " << total_lines << std::endl;
    }

private:
    size_t process_lines(const std::string& data) {
        size_t lines = 0;
        size_t start = 0;
        size_t end = data.find('\n');

        while (end != std::string::npos) {
            // Extract line (e.g., parse CSV/JSON here)
            std::string line = data.substr(start, end - start);
            // Example: Parse CSV fields (replace with your logic)
            // std::vector<std::string> fields = split_csv_line(line);

            lines++;
            start = end + 1;
            end = data.find('\n', start);
        }
        return lines;
    }

    size_t buffer_size_;
    std::vector<char> buffer_;
};

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <input_file>\n";
        return 1;
    }

    try {
        StreamingParser parser;
        parser.parse(argv[1]);
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
```

