class StreamingParser {
public:
    StreamingParser(size_t buffer_size = 1 << 20) : buffer_size_(buffer_size) {
        buffer_.resize(buffer_size_);
    }

    void parse(const std::string& filename) {
        std::ifstream file(filename, std::ios::binary);
        if (!file) {
            throw std::runtime_error("Failed to open file: " + filename);
        }

        size_t lines = 0;
        size_t bytes_processed = 0;
        std::string leftover;

        while (file) {
            file.read(&buffer_[0], buffer_size_);
            size_t bytes_read = file.gcount();

            if (bytes_read == 0) break;

            bytes_processed += bytes_read;
            std::string chunk(&buffer_[0], bytes_read);

            // Combine leftover from previous chunk with current chunk
            if (!leftover.empty()) {
                chunk = leftover + chunk;
                leftover.clear();
            }

            // Find the last newline to avoid splitting a line
            size_t last_newline = chunk.find_last_of('\n');
            if (last_newline == std::string::npos) {
                // No newline found, keep the entire chunk as leftover
                leftover = chunk;
                continue;
            }

            // Process all complete lines
            std::string complete_lines = chunk.substr(0, last_newline);
            process_lines(complete_lines, lines);

            // Keep the leftover part (after the last newline)
            leftover = chunk.substr(last_newline + 1);
        }

        // Process any remaining leftover data (last line without newline)
        if (!leftover.empty()) {
            process_lines(leftover, lines);
        }

        std::cout << "Total lines: " << lines << std::endl;
        std::cout << "Total bytes processed: " << bytes_processed << std::endl;
    }

private:
    void process_lines(const std::string& data, size_t& line_count) {
        size_t start = 0;
        size_t end = data.find('\n');
        while (end != std::string::npos) {
            // Process line from start to end
            std::string line = data.substr(start, end - start);
            // Here you would parse the line as needed
            // For this example, we just count lines
            line_count++;

            start = end + 1;
            end = data.find('\n', start);
        }
    }

    std::vector<char> buffer_;
    size_t buffer_size_;
};

