    MmapParser() : data_(nullptr), size_(0) {}

    ~MmapParser() {
        if (data_ != nullptr) {
            munmap(data_, size_);
        }
        if (fd_ != -1) {
            close(fd_);
        }
    }

    void parse(const std::string& filename) {
