        }
        size_ = sb.st_size;

        data_ = static_cast<char*>(mmap(nullptr, size_, PROT_READ, MAP_PRIVATE, fd_, 0));
        if (data_ == MAP_FAILED) {
            throw std::runtime_error("Failed to mmap file");
        }

        size_t lines = 0;
        size_t start = 0;
        for (size_t i = 0; i < size_; ++i) {
            if (data_[i] == '\n') {
                // Process line from start to i
                lines++;
                start = i + 1;
            }
        }
        // Process last line if no trailing newline
        if (start < size_) {
            lines++;
        }

        std::cout << "Total lines: " << lines << std::endl;
    }

private:
    char* data_;
    size_t size_;
    int fd_ = -1;
};

