```rust
use std::io::{self, BufRead, BufReader, Read, Write};
use std::fs::File;
use std::env;

/// Supported parsing modes.
#[derive(Debug, Clone, Copy)]
enum ParseMode {
    /// Line-delimited text (e.g., JSONL, CSV).
    Text,
    /// Fixed-size binary records (e.g., 8-byte records: u32 + f32).
    Binary,
}

/// Parse a CSV-like line (comma-separated, no quoting/escaping).
fn parse_csv_line(line: &[u8]) -> Vec<&[u8]> {
    let mut fields = Vec::new();
    let mut start = 0;
    for (i, &byte) in line.iter().enumerate() {
        if byte == b',' {
            fields.push(&line[start..i]);
            start = i + 1;
        }
    }
    fields.push(&line[start..]);
    fields
}

/// Parse a fixed-size binary record (8 bytes: u32 + f32).
fn parse_binary_record(buffer: &[u8; 8]) -> (u32, f32) {
    let id = u32::from_le_bytes([buffer[0], buffer[1], buffer[2], buffer[3]]);
    let value = f32::from_le_bytes([buffer[4], buffer[5], buffer[6], buffer[7]]);
    (id, value)
}

fn main() -> io::Result<()> {
    // Parse command-line arguments.
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <input_file> --format <text|binary>", args[0]);
        std::process::exit(1);
    }

    let input_path = &args[1];
    let mode = if args.contains(&"--format".to_string()) {
        if args.contains(&"binary".to_string()) {
            ParseMode::Binary
        } else {
            ParseMode::Text
        }
    } else {
        ParseMode::Text // Default to text mode.
    };

    // Open input file or stdin.
    let input: Box<dyn Read> = if input_path == "-" {
        Box::new(io::stdin())
    } else {
        Box::new(File::open(input_path)?)
    };

    let reader = BufReader::new(input);
    let stdout = io::stdout();
    let mut out = stdout.lock();

    match mode {
        ParseMode::Text => {
            let mut line = Vec::with_capacity(1024); // Reusable buffer.
            for result in reader.split(b'\n') {
                line.clear();
                line.extend_from_slice(&result?);
                // Remove trailing \r (Windows line endings).
                if line.last() == Some(&b'\r') {
                    line.pop();
                }
                // Parse CSV (or other text format) here.
                let fields = parse_csv_line(&line);
                writeln!(out, "Parsed {} fields: {:?}", fields.len(), fields)?;
            }
        }
        ParseMode::Binary => {
            let mut buffer = [0u8; 8]; // Fixed-size record buffer.
            let mut reader = reader.take(8); // Ensure we read full records.
            loop {
                match reader.read_exact(&mut buffer) {
                    Ok(_) => {
                        let (id, value) = parse_binary_record(&buffer);
                        writeln!(out, "Record: id={}, value={}", id, value)?;
                    }
                    Err(ref e) if e.kind() == io::ErrorKind::UnexpectedEof => break,
                    Err(e) => return Err(e),
                }
            }
        }
    }

    Ok(())
}
