```rust
use std::io::{self, Read};
use std::error::Error;

/// Parses a single line of data (e.g., "id=123 name=John Doe")
fn process_line(line: &[u8]) {
    // Convert to string slice (assumes UTF-8 input)
    if let Ok(line_str) = std::str::from_utf8(line) {
        let mut id = 0;
        let mut name = "";

        // Parse key=value pairs
        for part in line_str.split_whitespace() {
            if let Some((k, v)) = part.split_once('=') {
                match k {
                    "id" => {
                        if let Ok(num) = v.parse() {
                            id = num;
                        }
                    }
                    "name" => name = v,
                    _ => {} // Ignore unknown fields
                }
            }
        }

        // Process the record (example: print to stdout)
        println!("Parsed record: id={}, name={}", id, name);
    }
}

/// High-throughput streaming parser with minimal memory overhead
fn parse_stream<R: Read>(mut reader: R) -> io::Result<()> {
    // 64KB buffer (adjust based on your system's cache size)
    let mut buf = [0u8; 65536];
    let mut pos = 0; // Current end of valid data in buffer

    loop {
        // Read more data into the buffer (appending after current pos)
        let n = reader.read(&mut buf[pos..])?;
        if n == 0 {
            // EOF: process any remaining data
            if pos > 0 {
                process_line(&buf[..pos]);
            }
            break;
        }
        pos += n;

        // Process complete lines (up to last newline)
        let mut start = 0;
        while let Some(i) = buf[start..pos].iter().position(|&b| b == b'\n') {
            let end = start + i;
            process_line(&buf[start..end]);
            start = end + 1;
        }

        // Move any remaining partial line to buffer start
        let remaining = pos - start;
        if remaining > 0 {
            buf.copy_within(start..pos, 0);
        }
        pos = remaining;
    }
    Ok(())
}

fn main() -> Result<(), Box<dyn Error>> {
    // Read from stdin (pipe large files here)
    parse_stream(io::stdin())?;
    Ok(())
}
```

### Key Optimizations:
1. **Fixed-size buffer**: Uses a 64KB stack-allocated buffer to minimize allocations
2. **Zero-copy parsing**: Processes data in-place without intermediate allocations
3. **Incremental processing**: Handles partial lines at buffer boundaries
4. **Efficient I/O**: Uses buffered reading with minimal system calls
5. **Minimal data retention**: Only keeps the current buffer in memory

