Here's a high-throughput streaming data parser in Rust, designed for gigabyte-scale input with minimal memory overhead. This implementation uses a callback-based approach to process records as they're read, avoiding unnecessary memory allocations.

```rust
use std::io::{self, BufRead, BufReader, Read};
use std::mem;

/// A high-throughput streaming data parser that processes records incrementally
/// with minimal memory overhead. Records are assumed to be newline-delimited.
///
/// # Examples
///
/// Basic usage:
/// ```
/// use std::fs::File;
///
/// let file = File::open("data.txt").unwrap();
/// let mut parser = StreamParser::new(file);
///
/// parser.parse(|record| {
///     println!("Processing record: {:?}", record);
///     Ok(())
/// }).unwrap();
/// ```
pub struct StreamParser<R: Read> {
    reader: BufReader<R>,
    buffer: Vec<u8>,
}

impl<R: Read> StreamParser<R> {
    /// Creates a new StreamParser with a default 64KB buffer
    pub fn new(reader: R) -> Self {
        Self {
            reader: BufReader::new(reader),
            buffer: vec![0; 64 * 1024], // 64KB buffer (adjust based on your needs)
        }
    }

    /// Creates a new StreamParser with a custom buffer size
    pub fn with_capacity(reader: R, capacity: usize) -> Self {
        Self {
            reader: BufReader::new(reader),
            buffer: vec![0; capacity],
        }
    }

    /// Processes records incrementally using a callback function.
    /// The callback receives each complete record as a byte slice.
    ///
    /// # Returns
    /// `Ok(())` on successful completion, or an IO error if one occurs.
    pub fn parse<F>(&mut self, mut record_handler: F) -> io::Result<()>
    where
        F: FnMut(&[u8]) -> io::Result<()>,
    {
        // Reusable buffer for accumulating partial records
        let mut current_record = Vec::with_capacity(1024);

        loop {
            // Read a chunk of data
            let bytes_read = self.reader.read(&mut self.buffer)?;

            if bytes_read == 0 {
                // EOF reached - process any remaining partial record
                if !current_record.is_empty() {
                    record_handler(&current_record)?;
                }
                break;
            }

            // Process each byte in the chunk
            for &byte in &self.buffer[..bytes_read] {
                match byte {
                    b'\n' => {
                        // Complete record found - process it
                        record_handler(&current_record)?;
                        current_record.clear();
                    }
                    _ => {
                        // Accumulate bytes for the current record
                        current_record.push(byte);
                    }
                }
            }
        }

        Ok(())
    }
}

