use std::io::{self, Read};

fn parse_stream<R: Read, F>(mut reader: R, mut handler: F) -> io::Result<()>
where
    F: FnMut(&[u8]),
{
    let mut buf = [0u8; 8192]; // 8KB buffer
    loop {
        let n = reader.read(&mut buf)?;
        if n == 0 {
            break;
        }
        // Process the buffer up to n bytes
        let mut start = 0;
        for i in 0..n {
            if buf[i] == b'\n' {
                handler(&buf[start..i]);
                start = i + 1;
            }
        }
        // Handle the last line if no trailing newline
        if start < n {
            handler(&buf[start..n]);
        }
    }
    Ok(())
}
```

