use std::io::{self, BufRead, BufReader, Read};
use std::mem;

pub struct StreamParser<R: Read> {
    reader: BufReader<R>,
    buffer: Vec<u8>,
    pos: usize,
    end: usize,
}

impl<R: Read> StreamParser<R> {
    pub fn new(reader: R) -> Self {
        Self {
            reader: BufReader::new(reader),
            buffer: vec![0; 64 * 1024], // 64KB buffer
            pos: 0,
            end: 0,
        }
    }

    pub fn next_record(&mut self) -> io::Result<Option<&[u8]>> {
        // If we have data in buffer, try to find a newline
        while self.pos < self.end {
            // Find next newline
            if let Some(pos) = self.buffer[self.pos..self.end]
                .iter()
                .position(|&b| b == b'\n')
            {
                let start = self.pos;
                self.pos += pos + 1; // Skip past the newline
                return Ok(Some(&self.buffer[start..self.pos - 1]));
            } else {
                // No newline found in current buffer, need to refill
                self.refill_buffer()?;
            }
        }

        // No more data
        Ok(None)
    }

    fn refill_buffer(&mut self) -> io::Result<()> {
        // Move remaining data to front of buffer
        if self.pos > 0 {
            let remaining = self.end - self.pos;
            self.buffer.copy_within(self.pos..self.end, 0);
            self.end = remaining;
            self.pos = 0;
        } else {
            self.end = 0;
        }

        // Read more data
        let bytes_read = self.reader.read(&mut self.buffer[self.end..])?;
        self.end += bytes_read;

        if bytes_read == 0 {
            // EOF
            Ok(())
        } else {
            Ok(())
        }
    }
}
