    let mut buffer = [0u8; 65536];
    let mut record_count = 0;
    let mut field_count = 0;

    // Reusable buffer for current field (pre-allocated to avoid allocations)
    let mut current_field = Vec::with_capacity(128);

    loop {
        let bytes_read = input.read(&mut buffer)?;
        if bytes_read == 0 {
