        }

        for &byte in &buffer[..bytes_read] {
            match byte {
                b',' => {
                    // End of field - in a real parser you'd process the field here
                    field_count += 1;
                    current_field.clear();
                }
                b'\n' => {
                    // End of record
                    field_count += 1; // Count the last field
                    record_count += 1;
                    field_count = 0;
                    current_field.clear();
                }
                _ => {
                    current_field.push(byte);
                }
            }
        }
    }

    // Handle final record if file doesn't end with newline
    if !current_field.is_empty() || field_count > 0 {
        record_count += 1;
    }

