fn parse_args() -> Option<(PathBuf, u64, usize)> {
    let mut args = env::args().skip(1); // Skip program name
    let mut log_path = None;
    let mut max_size = None;
    let mut max_rotations = None;

    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--file" => {
                log_path = args.next().map(PathBuf::from);
            }
            "--max-size" => {
                max_size = args.next().and_then(|s| s.parse().ok());
            }
            "--max-rotations" => {
                max_rotations = args.next().and_then(|s| s.parse().ok());
            }
            _ => continue,
        }
    }

    match (log_path, max_size, max_rotations) {
        (Some(path), Some(size), Some(rotations)) if size > 0 && rotations > 0 => {
            Some((path, size, rotations))
        }
        _ => None,
    }
}

fn rotate_log(log_path: &Path, max_rotations: usize) -> io::Result<()> {
    // Delete the oldest rotation if it exists
    let oldest_path = log_path.with_extension(format!("{}", max_rotations + 1));
    if oldest_path.exists() {
        fs::remove_file(&oldest_path)?;
    }

    // Shift existing rotations from highest to lowest
    for i in (1..=max_rotations).rev() {
        let old_path = log_path.with_extension(i.to_string());
        let new_path = log_path.with_extension((i + 1).to_string());

        if old_path.exists() {
            fs::rename(&old_path, &new_path)?;
        }
    }

    // Rotate current log to .1
    let rotated_path = log_path.with_extension("1");
    fs::rename(log_path, &rotated_path)?;

    // Truncate current log
    fs::File::create(log_path)?;

    Ok(())
}

fn main() {
    let (log_path, max_size, max_rotations) = match parse_args() {
        Some(args) => args,
        None => {
            eprintln!("Usage: logrotated --file <path> --max-size <bytes> --max-rotations <n>");
            process::exit(1);
        }
    };

    // Verify log file exists before starting
    if !log_path.exists() {
        eprintln!("Error: Log file does not exist");
        process::exit(1);
