//! Memory-constrained log rotation daemon
//! Designed to stay within single-digit MB memory usage
//! Uses minimal heap allocations and fixed-size buffers

use std::fs::{self, File, OpenOptions};
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, Ordering};
use std::thread;
use std::time::{Duration, SystemTime};

// Configuration - all fixed size, no dynamic allocation
const LOG_FILE_PATH: &str = "/var/log/myapp.log";
const MAX_LOG_SIZE: u64 = 10 * 1024 * 1024; // 10MB
const MAX_ARCHIVE_FILES: usize = 5;
const CHECK_INTERVAL_SECS: u64 = 60;
const BUFFER_SIZE: usize = 4096; // Fixed buffer size

// Global shutdown flag - very small memory footprint (just 1 byte)
static SHOULD_EXIT: AtomicBool = AtomicBool::new(false);

fn main() {
    // Validate configuration fits memory constraints
    assert!(MAX_LOG_SIZE <= 100 * 1024 * 1024, "Log size too large");
    assert!(MAX_ARCHIVE_FILES <= 100, "Too many archives configured");
    assert!(BUFFER_SIZE <= 8192, "Buffer too large");

    // Set up signal handling
    setup_signal_handlers();

    println!("Starting memory-constrained log rotation daemon");
    println!("Config: size={}MB, archives={}, interval={}s",
             MAX_LOG_SIZE / (1024*1024),
             MAX_ARCHIVE_FILES,
             CHECK_INTERVAL_SECS);

    // Main monitoring loop - uses minimal stack space
    while !SHOULD_EXIT.load(Ordering::Relaxed) {
        if let Err(e) = check_and_rotate() {
            // In production, we'd log this to syslog without allocation
            let _ = e;
        }

        // Sleep using fixed interval
        thread::sleep(Duration::from_secs(CHECK_INTERVAL_SECS));
    }

    println!("Daemon exiting");
}

#[cfg(unix)]
fn setup_signal_handlers() {
    use libc;

    extern "C" fn handle_signal(_: i32) {
        SHOULD_EXIT.store(true, Ordering::Relaxed);
    }

    unsafe {
        libc::signal(libc::SIGTERM, handle_signal as libc::sighandler_t);
        libc::signal(libc::SIGHUP, handle_signal as libc::sighandler_t);
    }
}

#[cfg(not(unix))]
fn setup_signal_handlers() {
    // Platform-specific signal handling not implemented
}

fn check_and_rotate() -> io::Result<()> {
    let log_path = Path::new(LOG_FILE_PATH);

    // Check file metadata - minimal allocation
    let metadata = match fs::metadata(log_path) {
        Ok(m) => m,
        Err(_) => return Ok(()), // File doesn't exist yet
    };

    // Check size - direct comparison, no allocation
    if metadata.len() >= MAX_LOG_SIZE {
        rotate_log()?;
    }

    Ok(())
}

fn rotate_log() -> io::Result<()> {
    let log_path = Path::new(LOG_FILE_PATH);
    let timestamp = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap()
        .as_secs();

    // Build archive path
    let mut archive_path = PathBuf::with_capacity(
        LOG_FILE_PATH.len() + 1 + 20 // timestamp fits in 20 chars
    );
    archive_path.push(LOG_FILE_PATH);
    archive_path.push(format!(".{}", timestamp));

    // Open files with minimal options
    let mut log_file = OpenOptions::new()
        .read(true)
        .open(log_path)?;

    // Create new empty log file
    let _new_log_file = OpenOptions::new()
        .create(true)
        .write(true)
        .truncate(true)
        .open(log_path)?;

    // Create archive file
    let mut archive_file = OpenOptions::new()
        .create(true)
        .write(true)
        .open(&archive_path)?;

    // Copy contents using fixed buffer - no heap allocation in hot path
    let mut buffer = [0u8; BUFFER_SIZE];
    loop {
        let bytes_read = log_file.read(&mut buffer)?;
        if bytes_read == 0 {
            break;
        }
        archive_file.write_all(&buffer[..bytes_read])?;
    }

    // Clean up old archives with minimal memory usage
    cleanup_old_archives()?;

    println!("Rotated log to {}", archive_path.display());
    Ok(())
}

fn cleanup_old_archives() -> io::Result<()> {
    let log_dir = Path::new(LOG_FILE_PATH).parent().unwrap();
    let prefix = Path::new(LOG_FILE_PATH).file_name().unwrap();

    // Process directory entries one by one to avoid large allocations
    let mut dir = fs::read_dir(log_dir)?;
    let mut archive_count = 0;
    let mut oldest_path: Option<(std::time::SystemTime, std::path::PathBuf)> = None;

    // Single pass through directory - O(1) memory usage
    while let Some(entry) = dir.next() {
        let entry = entry?;
        let path = entry.path();

        if let Some(filename) = path.file_name() {
            if filename.starts_with(prefix) && filename.len() > prefix.len() {
                archive_count += 1;

                let modified = entry.metadata()?.modified()?;
                match &oldest_path {
                    Some((oldest_time, _)) if modified < *oldest_time => {
                        oldest_path = Some((modified, path));
                    }
                    None => oldest_path = Some((modified, path)),
                    _ => {}
                }
            }
        }
    }

    // Remove oldest if we exceed limit
    if archive_count > MAX_ARCHIVE_FILES {
        if let Some((_, path)) = oldest_path {
            fs::remove_file(path)?;
        }
    }

    Ok(())
}
