fn rotate_log_file(log_path: &Path, max_files: usize, compress: bool) -> io::Result<()> {
    let parent = log_path.parent().ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "No parent directory"))?;
    let stem = log_path.file_stem().ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "No file stem"))?;
    let extension = log_path.extension().map(|e| format!(".{}", e.to_string_lossy())).unwrap_or_default();

    // Find highest existing rotation number
    let mut highest = 0;
    for entry in fs::read_dir(parent)? {
        let entry = entry?;
        let path = entry.path();
        if path.starts_with(log_path) {
            if let Some(file_name) = path.file_name() {
                let file_name = file_name.to_string_lossy();
                if file_name.starts_with(&format!("{}.", stem.to_string_lossy())) {
                    if let Some(num_str) = file_name.strip_prefix(&format!("{}.", stem.to_string_lossy()))
                        .and_then(|s| s.strip_suffix(&extension.as_str())) {
                        if let Ok(num) = num_str.parse::<usize>() {
                            if num > highest { highest = num; }
                        }
                    }
                }
            }
        }
    }

    // Rotate existing files
    for i in (0..=highest).rev() {
        let old_path = parent.join(format!("{}.{}{}", stem.to_string_lossy(), i, extension));
        let new_path = parent.join(format!("{}.{}{}", stem.to_string_lossy(), i + 1, extension));
        if old_path.exists() {
            fs::rename(&old_path, &new_path)?;
        }
    }

    // Rotate current log
    let rotated_path = parent.join(format!("{}.1{}", stem.to_string_lossy(), extension));
    fs::rename(log_path, &rotated_path)?;
    fs::File::create(log_path)?;

    // Compress if enabled
    if compress {
        let compressed_path = parent.join(format!("{}.1{}.gz", stem.to_string_lossy(), extension));
        let mut encoder = GzEncoder::new(Vec::with_capacity(1024), Compression::default());
        let data = fs::read(&rotated_path)?;
        encoder.write_all(&data)?;
        let compressed_data = encoder.finish()?;
        fs::write(&compressed_path, compressed_data)?;
        fs::remove_file(rotated_path)?;
    }

    // Clean up old rotations
    cleanup_old_rotations(parent, stem, extension, max_files)
}

fn cleanup_old_rotations(parent: &Path, stem: &std::ffi::OsStr, extension: String, max_files: usize) -> io::Result<()> {
