Here's a complete implementation of a log rotation daemon designed for strict memory constraints. The code prioritizes minimal memory usage through:
- Stack allocation where possible
- Efficient file handling without large buffers
- Line-by-line config parsing
- Minimal data structures
- Direct system calls for file operations

```rust
use std::{
    fs::{self, File},
    io::{self, BufRead, BufReader, Write},
    path::{Path, PathBuf},
    time::{Duration, SystemTime},
};
use nix::unistd::{daemon, ForkResult};

#[derive(Debug)]
enum RotationFrequency {
    SizeBased(u64),
    Daily,
    Weekly,
}

#[derive(Debug)]
struct RotationRule {
    path: PathBuf,
    frequency: RotationFrequency,
    backups: usize,
    compress: bool,
}

fn parse_config(config_path: &Path) -> io::Result<Vec<RotationRule>> {
    let file = File::open(config_path)?;
    let reader = BufReader::new(file);
    let mut rules = Vec::new();
    let mut current_path = None;
    let mut current_freq = None;
    let mut current_backups = 5; // default
    let mut current_compress = false;

    for line in reader.lines() {
        let line = line?;
        let line = line.trim();

        // Skip empty lines and comments
        if line.is_empty() || line.starts_with('#') {
            continue;
        }

        // Check for block start
        if line.ends_with('{') {
            current_path = Some(line.trim_end_matches('{').trim().to_string());
            continue;
        }

        // Check for block end
        if line == "}" {
            if let Some(path) = current_path.take() {
                if let Some(freq) = current_freq.take() {
                    rules.push(RotationRule {
                        path: PathBuf::from(path),
                        frequency: freq,
                        backups: current_backups,
                        compress: current_compress,
                    });
                }
            }
            continue;
        }

        // Parse directives
        if let Some(path) = &current_path {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.is_empty() {
                continue;
            }

            match parts[0].to_lowercase().as_str() {
                "size" | "maxsize" => {
                    if parts.len() > 1 {
                        if let Ok(size) = parse_size(parts[1]) {
                            current_freq = Some(RotationFrequency::SizeBased(size));
                        }
                    }
                }
                "daily" => {
                    current_freq = Some(RotationFrequency::Daily);
                }
                "weekly" => {
                    current_freq = Some(RotationFrequency::Weekly);
                }
                "rotate" => {
                    if parts.len() > 1 {
                        if let Ok(num) = parts[1].parse() {
                            current_backups = num;
                        }
                    }
                }
                "compress" => {
                    current_compress = true;
                }
                _ => {} // ignore unknown directives
            }
        }
    }

    Ok(rules)
}

fn parse_size(s: &str) -> io::Result<u64> {
    let s = s.to_uppercase();
    if let Ok(num) = s.parse::<u64>() {
        return Ok(num);
    }

    let (num_str, unit) = if s.ends_with('K') {
        (&s[..s.len()-1], 1024)
    } else if s.ends_with('M') {
        (&s[..s.len()-1], 1024 * 1024)
    } else if s.ends_with('G') {
        (&s[..s.len()-1], 1024 * 1024 * 1024)
    } else {
        (s.as_str(), 1)
    };

    if let Ok(num) = num_str.parse::<u64>() {
        Ok(num * unit)
    } else {
        Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "Invalid size format",
        ))
    }
}

fn needs_rotation(rule: &RotationRule, now: SystemTime) -> io::Result<bool> {
    let metadata = fs::metadata(&rule.path)?;

    match &rule.frequency {
        RotationFrequency::SizeBased(max_size) => {
            Ok(metadata.len() >= *max_size)
        }
        RotationFrequency::Daily => {
            let today = now.duration_since(std::time::UNIX_EPOCH)?.as_secs() / 86400;
            let file_day = metadata.modified()?.duration_since(std::time::UNIX_EPOCH)?.as_secs() / 86400;
            Ok(today > file_day)
        }
        RotationFrequency::Weekly => {
            let today = now.duration_since(std::time::UNIX_EPOCH)?.as_secs() / 604800;
            let file_week = metadata.modified()?.duration_since(std::time::UNIX_EPOCH)?.as_secs() / 604800;
            Ok(today > file_week)
        }
    }
}

fn rotate_log(rule: &RotationRule) -> io::Result<()> {
    let path = &rule.path;
    let ext = if rule.compress { ".gz" } else { "" };
    let backups = rule.backups;

    // Shift existing backups
    for i in (1..=backups).rev() {
        let src = if i == 1 {
            format!("{}.{}", path.display(), i)
        } else {
            format!("{}.{}{}", path.display(), i, ext)
        };
        let dest = format!("{}.{}{}", path.display(), i + 1, ext);

        if Path::new(&src).exists() {
            fs::rename(&src, &dest)?;
        }
    }

    // Rename current log to .1
    let new_name = format!("{}.1{}", path.display(), ext);
    fs::rename(path, &new_name)?;

    // Create new log file
    File::create(path)?;

    // Compress the rotated file if needed
    if rule.compress {
        compress_file(&new_name)?;
    }

    // Remove oldest backup if it exists
    let oldest = format!("{}.{}{}", path.display(), backups + 1, ext);
    if Path::new(&oldest).exists() {
        fs::remove_file(oldest)?;
    }

    Ok(())
}

fn compress_file(path: &str) -> io::Result<()> {
    use std::process::Command;

    // Use system gzip for minimal memory overhead
    let output = Command::new("gzip")
        .arg("-f")
        .arg(path)
        .output()?;

    if !output.status.success() {
        return Err(io::Error::new(
            io::ErrorKind::Other,
            format!("Compression failed: {}", String::from_utf8_lossy(&output.stderr)),
        ));
    }

    Ok(())
}

fn daemonize() -> io::Result<()> {
    match unsafe { nix::unistd::fork() }? {
        ForkResult::Parent { .. } => std::process::exit(0),
        ForkResult::Child => {
            nix::unistd::setsid()?;
            match unsafe { nix::unistd::fork() }? {
                ForkResult::Parent { .. } => std::process::exit(0),
                ForkResult::Child => {
                    std::env::set_current_dir("/")?;
                    nix::unistd::umask(nix::sys::stat::Mode::empty());
                    Ok(())
                }
            }
        }
    }
}

fn main() -> io::Result<()> {
    // Parse command line arguments
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: {} <config_file>", args[0]);
        std::process::exit(1);
    }
    let config_path = Path::new(&args[1]);

    // Parse configuration
    let rules = parse_config(config_path)?;
    if rules.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "No rotation rules found in config",
        ));
    }

    // Daemonize the process
    daemonize()?;

    // Main loop
    loop {
        let now = SystemTime::now();

        for rule in &rules {
            if let Ok(true) = needs_rotation(rule, now) {
                if let Err(e) = rotate_log(rule) {
                    eprintln!("Failed to rotate {}: {}", rule.path.display(), e);
                }
            }
        }

        // Sleep for 1 hour (adjust as needed)
        std::thread::sleep(Duration::from_secs(3600));
    }
}
