/// Memory-constrained log rotation daemon
/// Tracks log file size and rotates when threshold is reached

// Configuration constants - all fixed size, no heap allocation
const LOG_FILE_PATH: &str = "/var/log/myapp.log";
const MAX_LOG_SIZE: u64 = 10 * 1024 * 1024; // 10MB
const MAX_ARCHIVE_FILES: usize = 5;
const CHECK_INTERVAL_SECS: u64 = 60;
const BUFFER_SIZE: usize = 4096; // Fixed buffer size

// Global flag for graceful shutdown
static SHOULD_EXIT: AtomicBool = AtomicBool::new(false);

fn main() {
    // Set up signal handlers for graceful shutdown
    setup_signal_handlers();

    println!("Starting memory-constrained log rotation daemon");
    println!("Monitoring: {}", LOG_FILE_PATH);
    println!("Max size: {} bytes", MAX_LOG_SIZE);
    println!("Max archives: {}", MAX_ARCHIVE_FILES);

    // Main monitoring loop
    while !SHOULD_EXIT.load(Ordering::Relaxed) {
        if let Err(e) = check_and_rotate() {
            eprintln!("Error during rotation check: {}", e);
        }

        // Sleep for the check interval
        thread::sleep(Duration::from_secs(CHECK_INTERVAL_SECS));
    }

    println!("Daemon shutting down gracefully");
}

fn setup_signal_handlers() {
