fn check_and_rotate() -> io::Result<()> {
    let log_path = Path::new(LOG_FILE_PATH);

    // Check if log file exists and get its size
    let metadata = match fs::metadata(log_path) {
        Ok(m) => m,
        Err(_) => {
            // Log file doesn't exist yet, nothing to do
            return Ok(());
        }
    };

    let file_size = metadata.len();

    // If log file is too large, rotate it
    if file_size >= MAX_LOG_SIZE {
        rotate_log()?;
    }

    Ok(())
}

fn rotate_log() -> io::Result<()> {
    let log_path = Path::new(LOG_FILE_PATH);
    let timestamp = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap()
        .as_secs();

    // Create archive filename: myapp.log.20231225123045
    let mut archive_path = PathBuf::with_capacity(64);
    archive_path.push(LOG_FILE_PATH);
    archive_path.push(format!(".{}", timestamp));

    // Open current log file for reading
    let mut log_file = OpenOptions::new()
        .read(true)
        .open(log_path)?;

    // Create new empty log file
    let mut new_log_file = OpenOptions::new()
        .create(true)
        .write(true)
        .truncate(true)
        .open(log_path)?;

    // Create archive file
    let mut archive_file = OpenOptions::new()
        .create(true)
        .write(true)
        .open(&archive_path)?;

    // Copy contents to archive (memory efficient - uses fixed buffer)
    let mut buffer = [0u8; BUFFER_SIZE];
    loop {
        let bytes_read = log_file.read(&mut buffer)?;
        if bytes_read == 0 {
            break;
        }
        archive_file.write_all(&buffer[..bytes_read])?;
    }

    // Truncate the original log file
    new_log_file.set_len(0)?;

    // Clean up old archives if we have too many
    cleanup_old_archives()?;

    println!("Rotated log to {}", archive_path.display());
    Ok(())
}

fn cleanup_old_archives() -> io::Result<()> {
    let log_dir = Path::new(LOG_FILE_PATH).parent().unwrap();
    let prefix = Path::new(LOG_FILE_PATH).file_name().unwrap().to_str().unwrap();

    // List all files matching the pattern
    let mut archives = Vec::with_capacity(MAX_ARCHIVE_FILES + 1);

    for entry in fs::read_dir(log_dir)? {
        let entry = entry?;
        let path = entry.path();

        if let Some(filename) = path.file_name() {
            if let Some(name) = filename.to_str() {
                if name.starts_with(prefix) && name.len() > prefix.len() {
                    archives.push(path);
                }
            }
        }
    }

    // Sort by modification time (oldest first)
    archives.sort_by(|a, b| {
        a.metadata().unwrap().modified().unwrap()
            .cmp(&b.metadata().unwrap().modified().unwrap())
    });

    // Remove oldest files beyond MAX_ARCHIVE_FILES
    while archives.len() > MAX_ARCHIVE_FILES {
        let oldest = archives.remove(0);
        fs::remove_file(oldest)?;
    }

    Ok(())
}
