use std::path::PathBuf;
use std::fs;
use std::io::{self, BufRead};
use std::time::Duration;

#[derive(Debug)]
pub struct Config {
    pub log_dir: PathBuf,
    pub max_size: u64,
    pub max_files: usize,
    pub rotate_every: Option<Duration>,
    pub compress: bool,
}

impl Config {
    pub fn from_file(path: &str) -> io::Result<Self> {
        let file = fs::File::open(path)?;
        let reader = io::BufReader::new(file);

        let mut log_dir = None;
        let mut max_size = None;
        let mut max_files = None;
        let mut rotate_every = None;
        let mut compress = false;

        for line in reader.lines() {
            let line = line?;
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }

            let parts: Vec<&str> = line.splitn(2, '=').map(|s| s.trim()).collect();
            if parts.len() != 2 {
                continue;
            }

            match parts[0] {
                "log_dir" => log_dir = Some(PathBuf::from(parts[1])),
                "max_size" => max_size = Some(parts[1].parse::<u64>().map_err(|_| io::Error::new(io::ErrorKind::InvalidData, "Invalid max_size"))?),
                "max_files" => max_files = Some(parts[1].parse::<usize>().map_err(|_| io::Error::new(io::ErrorKind::InvalidData, "Invalid max_files"))?),
                "rotate_every" => {
                    let secs = parts[1].parse::<u64>().map_err(|_| io::Error::new(io::ErrorKind::InvalidData, "Invalid rotate_every"))?;
                    rotate_every = Some(Duration::from_secs(secs));
                }
                "compress" => compress = parts[1].eq_ignore_ascii_case("true"),
                _ => {}
            }
        }

        Ok(Config {
            log_dir: log_dir.ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "log_dir not specified"))?,
            max_size: max_size.ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "max_size not specified"))?,
            max_files: max_files.ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "max_files not specified"))?,
            rotate_every,
            compress,
        })
    }
}
