use std::path::{Path, PathBuf};
use std::fs;
use std::io;
use std::time::{SystemTime, UNIX_EPOCH};
use std::process::Command;

pub fn rotate_log_file(log_path: &Path, max_files: usize, compress: bool) -> io::Result<()> {
    let parent = log_path.parent().ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "No parent directory"))?;
    let stem = log_path.file_stem().ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "No file stem"))?;
    let extension = log_path.extension().map(|e| format!(".{}", e.to_string_lossy())).unwrap_or_default();

    // Find the highest existing rotation number
    let mut highest = 0;
    for entry in fs::read_dir(parent)? {
        let entry = entry?;
        let path = entry.path();
        if path.starts_with(log_path) {
            let file_name = path.file_name().unwrap().to_string_lossy();
            if file_name.starts_with(&format!("{}.", stem.to_string_lossy())) {
                if let Some(num_str) = file_name.strip_prefix(&format!("{}.", stem.to_string_lossy())).and_then(|s| s.strip_suffix(&extension)) {
                    if let Ok(num) = num_str.parse::<usize>() {
                        if num > highest {
                            highest = num;
                        }
                    }
                }
            }
        }
    }

    // Rotate existing files
    for i in (0..=highest).rev() {
        let old_path = parent.join(format!("{}.{}{}", stem.to_string_lossy(), i, extension));
        let new_path = parent.join(format!("{}.{}{}", stem.to_string_lossy(), i + 1, extension));
        if old_path.exists() {
            fs::rename(&old_path, &new_path)?;
        }
    }

    // Rename current log to .1
    let rotated_path = parent.join(format!("{}.1{}", stem.to_string_lossy(), extension));
    fs::rename(log_path, &rotated_path)?;

    // Create new log file
    fs::File::create(log_path)?;

    // Compress if enabled
    if compress {
        let compressed_path = parent.join(format!("{}.1{}.gz", stem.to_string_lossy(), extension));
        let status = Command::new("gzip")
            .arg("-f")
            .arg(&rotated_path)
            .arg("-c")
            .output()?;
        if !status.status.success() {
            return Err(io::Error::new(io::ErrorKind::Other, "Failed to compress log"));
        }
        fs::rename(&rotated_path.with_extension("gz"), compressed_path)?;
    }

    // Clean up old rotations
    cleanup_old_rotations(parent, stem, extension, max_files)
}

fn cleanup_old_rotations(parent: &Path, stem: &std::ffi::OsStr, extension: String, max_files: usize) -> io::Result<()> {
    let mut rotations = Vec::new();
    for entry in fs::read_dir(parent)? {
        let entry = entry?;
        let path = entry.path();
        let file_name = path.file_name().unwrap().to_string_lossy();
        if file_name.starts_with(&format!("{}.", stem.to_string_lossy())) {
            if let Some(num_str) = file_name.strip_prefix(&format!("{}.", stem.to_string_lossy())).and_then(|s| s.strip_suffix(&extension.as_str())) {
                if let Ok(num) = num_str.parse::<usize>() {
                    rotations.push((num, path));
                }
            }
        }
    }

    rotations.sort_by_key(|(num, _)| *num);
    for (num, path) in rotations.iter().rev().skip(max_files) {
        fs::remove_file(path)?;
    }

    Ok(())
}

pub fn should_rotate(log_path: &Path, max_size: u64, last_rotation_time: Option<SystemTime>) -> io::Result<bool> {
    let metadata = fs::metadata(log_path)?;
    let size = metadata.len();
    let now = SystemTime::now();

    let time_trigger = last_rotation_time.map_or(true, |t| {
        now.duration_since(t).unwrap_or_default() >= std::time::Duration::from_secs(86400) // 1 day
    });

    Ok(size >= max_size || time_trigger)
}
