static SHOULD_EXIT: AtomicBool = AtomicBool::new(false);
static SHOULD_RELOAD: AtomicBool = AtomicBool::new(false);

extern "C" fn handle_sigterm(_: libc::c_int) {
    SHOULD_EXIT.store(true, Ordering::SeqCst);
}

extern "C" fn handle_sighup(_: libc::c_int) {
    SHOULD_RELOAD.store(true, Ordering::SeqCst);
}

fn daemonize() -> nix::Result<()> {
    // Fork the process
    match unsafe { fork() }? {
        ForkResult::Parent { .. } => std::process::exit(0),
        ForkResult::Child => {}
    }

    // Create a new session
    setsid()?;

    // Fork again to ensure we are not a session leader
    match unsafe { fork() }? {
        ForkResult::Parent { .. } => std::process::exit(0),
        ForkResult::Child => {}
    }

    // Change working directory
    chdir("/")?;

    // Reset file mode creation mask
    umask(0);

    Ok(())
}

fn set_memory_limit() -> nix::Result<()> {
    // Set memory limit to 16MB (adjust as needed)
    let limit = libc::rlimit {
        rlim_cur: 16 * 1024 * 1024, // 16MB soft limit
        rlim_max: 16 * 1024 * 1024, // 16MB hard limit
    };
    setrlimit(Resource::RLIMIT_AS, &limit)?;
    Ok(())
}

fn main() -> nix::Result<()> {
    // Parse command line arguments
    let config_path = std::env::args().nth(1).expect("Usage: logrotate-daemon <config_file>");

    // Daemonize
    daemonize()?;

    // Set memory limit
    set_memory_limit()?;

    // Set up signal handlers
    let sig_action = SigAction::new(
        SigHandler::Handler(handle_sigterm),
        SaFlags::empty(),
        SigSet::empty(),
    );
    unsafe { sigaction(Signal::SIGTERM, &sig_action)? };
    unsafe { sigaction(Signal::SIGINT, &sig_action)? };

    let sig_action_hup = SigAction::new(
        SigHandler::Handler(handle_sighup),
        SaFlags::empty(),
        SigSet::empty(),
    );
    unsafe { sigaction(Signal::SIGHUP, &sig_action_hup)? };

    // Load config
    let config = Config::from_file(&config_path).expect("Failed to load config");

    // Main loop
    let mut last_rotation_time = SystemTime::now();
    let rotation_interval = config.rotate_every.unwrap_or(Duration::from_secs(86400)); // Default to 1 day

    while !SHOULD_EXIT.load(Ordering::SeqCst) {
        if SHOULD_RELOAD.load(Ordering::SeqCst) {
            // Reload config
            let new_config = Config::from_file(&config_path).expect("Failed to reload config");
            // Update config variables (simplified; in real code, you'd need to handle this properly)
            SHOULD_RELOAD.store(false, Ordering::SeqCst);
