```c
/*
 * Memory-Constrained Log Rotation Daemon
 *
 * Features:
 * - Fixed-size memory usage (no dynamic allocation in main loop)
 * - Size-based rotation with configurable threshold
 * - Configurable backup count
 * - Daemon mode with foreground option
 * - Signal handling for clean shutdown
 * - Syslog logging for daemon activity
 *
 * Memory footprint: ~20KB (stack + static data)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <limits.h>
#include <getopt.h>

/* Memory configuration */
#define MAX_LOG_PATH_LEN 256      /* PATH_MAX is typically 4096, but we constrain this */
#define MAX_BACKUP_COUNT 10       /* Maximum number of rotated logs to keep */
#define DEFAULT_ROTATION_SIZE (5 * 1024 * 1024)  /* 5MB default rotation size */
#define DEFAULT_SLEEP_INTERVAL 30 /* Check every 30 seconds */

/* Fixed-size configuration structure */
typedef struct {
    char log_path[MAX_LOG_PATH_LEN];  /* Fixed-size path buffer */
    size_t rotation_size;             /* Rotation threshold in bytes */
    int backup_count;                 /* Number of backups to retain */
    int daemonize;                    /* Run as daemon flag */
    int sleep_interval;               /* Check interval in seconds */
} Config;

/* Global configuration with fixed-size initialization */
Config config = {
    .log_path = "/var/log/app.log",
    .rotation_size = DEFAULT_ROTATION_SIZE,
    .backup_count = MAX_BACKUP_COUNT,
    .daemonize = 1,
    .sleep_interval = DEFAULT_SLEEP_INTERVAL
};

/* Global flag for signal handling */
volatile sig_atomic_t keep_running = 1;

/**
 * Signal handler for clean shutdown
 */
void handle_signal(int sig) {
    keep_running = 0;
    syslog(LOG_NOTICE, "Received signal %d, shutting down gracefully", sig);
}

/**
 * Rotate the log file with timestamp naming
 * Returns new file descriptor or -1 on error
 */
int rotate_log(const char *log_path, int backup_count) {
    char timestamp[20];  /* Fixed-size timestamp buffer (YYYYMMDD-HHMMSS) */
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d-%H%M%S", tm_info);

    char old_path[MAX_LOG_PATH_LEN * 2];  /* Fixed-size buffer for old path */
    char new_path[MAX_LOG_PATH_LEN];      /* Fixed-size buffer for new path */

    /* Construct old path: log_path.timestamp */
    snprintf(old_path, sizeof(old_path), "%s.%s", log_path, timestamp);

    /* Construct new path (just the original path) */
    strncpy(new_path, log_path, sizeof(new_path));

    /* Rename current log to timestamped version */
    if (rename(new_path, old_path) != 0) {
        syslog(LOG_ERR, "Failed to rename %s to %s: %s",
               new_path, old_path, strerror(errno));
        return -1;
    }

    /* Create new empty log file */
    int fd = open(new_path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        syslog(LOG_ERR, "Failed to open %s: %s", new_path, strerror(errno));
        return -1;
    }

    /* Manage backup rotation (shift existing backups) */
    for (int i = backup_count - 1; i >= 0; i--) {
        char backup_path[MAX_LOG_PATH_LEN * 2];

        if (i == 0) {
            /* Current rotation becomes .0 */
            snprintf(backup_path, sizeof(backup_path), "%s", old_path);
        } else {
            /* Existing backup.N becomes backup.N+1 */
            snprintf(backup_path, sizeof(backup_path), "%s.%d", log_path, i);
        }

        if (access(backup_path, F_OK) == 0) {
            if (i == backup_count - 1) {
                /* Delete oldest backup */
                if (unlink(backup_path) != 0) {
                    syslog(LOG_ERR, "Failed to delete %s: %s",
                           backup_path, strerror(errno));
                }
            } else {
                /* Shift backup to next position */
                char next_path[MAX_LOG_PATH_LEN * 2];
                snprintf(next_path, sizeof(next_path), "%s.%d", log_path, i + 1);
                if (rename(backup_path, next_path) != 0) {
                    syslog(LOG_ERR, "Failed to rename %s to %s: %s",
                           backup_path, next_path, strerror(errno));
                }
            }
        }
    }

    syslog(LOG_INFO, "Rotated log: %s -> %s", new_path, old_path);
    return fd;
}

/**
 * Main monitoring loop
 */
void main_loop() {
    int log_fd = open(config.log_path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        syslog(LOG_ERR, "Failed to open log file %s: %s",
               config.log_path, strerror(errno));
        exit(EXIT_FAILURE);
    }

    syslog(LOG_NOTICE, "Log rotation daemon started (pid=%d)", getpid());

    while (keep_running) {
        struct stat st;

        /* Check log file size */
        if (fstat(log_fd, &st) == 0) {
            if (st.st_size >= (off_t)config.rotation_size) {
                syslog(LOG_INFO, "Log size %lld >= %zu bytes, rotating",
                       (long long)st.st_size, config.rotation_size);
                int new_fd = rotate_log(config.log_path, config.backup_count);
                if (new_fd != -1) {
                    close(log_fd);
                    log_fd = new_fd;
                }
            }
        } else {
            syslog(LOG_ERR, "Failed to stat log file: %s", strerror(errno));
        }

        /* Sleep for configured interval */
        sleep(config.sleep_interval);
    }

    close(log_fd);
    syslog(LOG_NOTICE, "Log rotation daemon stopped");
}

/**
 * Daemonize the process
 */
void daemonize() {
    pid_t pid = fork();
    if (pid < 0) {
        exit(EXIT_FAILURE);
    }
    if (pid > 0) {
        exit(EXIT_SUCCESS);  /* Parent exits */
    }

    /* Create new session */
    if (setsid() < 0) {
        exit(EXIT_FAILURE);
    }

    /* Set file mode mask */
    umask(0);

    /* Redirect standard file descriptors */
    int fd = open("/dev/null", O_RDWR);
    if (fd == -1) {
        exit(EXIT_FAILURE);
    }
    dup2(fd, STDIN_FILENO);
    dup2(fd, STDOUT_FILENO);
    dup2(fd, STDERR_FILENO);
    if (fd > STDERR_FILENO) {
        close(fd);
    }
}

/**
 * Print usage information
 */
void print_usage(const char *progname) {
    fprintf(stderr, "Memory-Constrained Log Rotation Daemon\n");
    fprintf(stderr, "Usage: %s [OPTIONS]\n", progname);
    fprintf(stderr, "\nOptions:\n");
    fprintf(stderr, "  -f <path>      Log file path (default: %s)\n", config.log_path);
    fprintf(stderr, "  -s <size>      Rotation size in bytes (default: %zu)\n", config.rotation_size);
    fprintf(stderr, "  -b <count>     Number of backups to keep (default: %d)\n", config.backup_count);
    fprintf(stderr, "  -i <seconds>   Check interval in seconds (default: %d)\n", config.sleep_interval);
    fprintf(stderr, "  -n             Run in foreground (don't daemonize)\n");
    fprintf(stderr, "  -h             Show this help message\n");
}

/**
 * Parse command line arguments
 */
int parse_args(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "f:s:b:i:nh")) != -1) {
        switch (opt) {
            case 'f':
                strncpy(config.log_path, optarg, sizeof(config.log_path) - 1);
                config.log_path[sizeof(config.log_path) - 1] = '\0';
                break;
            case 's': {
                char *endptr;
                long size = strtol(optarg, &endptr, 10);
                if (*endptr != '\0' || size <= 0) {
                    fprintf(stderr, "Error: Invalid rotation size '%s'\n", optarg);
                    return -1;
                }
                config.rotation_size = (size_t)size;
                break;
            }
            case 'b': {
                char *endptr;
                long count = strtol(optarg, &endptr, 10);
                if (*endptr != '\0' || count <= 0 || count > MAX_BACKUP_COUNT) {
                    fprintf(stderr, "Error: Invalid backup count '%s' (must be 1-%d)\n",
                            optarg, MAX_BACKUP_COUNT);
                    return -1;
                }
                config.backup_count = (int)count;
                break;
            }
            case 'i': {
                char *endptr;
                long interval = strtol(optarg, &endptr, 10);
                if (*endptr != '\0' || interval <= 0) {
                    fprintf(stderr, "Error: Invalid interval '%s'\n", optarg);
                    return -1;
                }
                config.sleep_interval = (int)interval;
                break;
            }
            case 'n':
                config.daemonize = 0;
                break;
            case 'h':
                print_usage(argv[0]);
                exit(EXIT_SUCCESS);
            default:
                print_usage(argv[0]);
                return -1;
        }
    }
    return 0;
}

/**
 * Main entry point
 */
int main(int argc, char *argv[]) {
    /* Parse command line arguments */
    if (parse_args(argc, argv) != 0) {
        return EXIT_FAILURE;
    }

    /* Initialize logging */
    openlog("logrotated", LOG_PID | LOG_CONS, LOG_DAEMON);

    /* Set up signal handlers */
    signal(SIGTERM, handle_signal);
    signal(SIGINT, handle_signal);

    /* Daemonize if configured */
    if (config.daemonize) {
        daemonize();
    }

    /* Enter main monitoring loop */
    main_loop();

    /* Cleanup */
    closelog();
    return EXIT_SUCCESS;
}
