                    // Compress the rotated log (path.YYYYMMDD-HHMMSS)
                    char rotated_path[MAX_PATH_LEN];
                    snprintf(rotated_path, sizeof(rotated_path), "%s.", log_file);
                    compress_log(rotated_path);
