    syslog(LOG_INFO, "Starting log rotation daemon for %s (max size: %ld bytes)",
           log_file, (long)max_size);

    // Daemonize (detach from terminal)
    daemonize();

    // Main processing loop
    main_loop();

    syslog(LOG_INFO, "Stopping log rotation daemon");
    closelog();

