impl LogRotationDaemon {
    fn new(configs: Vec<LogFileConfig>) -> Self {
        // Pre-allocate buffer to avoid runtime allocations
        let buffer = vec![0u8; 64 * 1024]; // 64KB buffer

        Self { configs, buffer }
    }

    fn rotate(&mut self, config: &LogFileConfig) -> io::Result<()> {
        let timestamp = SystemTime::now()
            .duration_since(SystemTime::UNIX_EPOCH)
            .unwrap()
            .as_secs();

        // Construct rotated filename
        let rotated_name = format!("{}.{}", config.path.display(), timestamp);
        let rotated_path = Path::new(&rotated_name);

        // Rename current log to rotated name
        fs::rename(&config.path, rotated_path)?;

        // Create a new empty log file
        File::create(&config.path)?;

        // Compress if enabled
        if config.compress {
            self.compress(rotated_path)?;
        }

        // Clean up old versions
        self.cleanup_old_versions(&config.path, config.max_versions)?;

        Ok(())
    }

    fn compress(&self, path: &Path) -> io::Result<()> {
        // Use gzip compression via flate2 crate for minimal memory usage
        use flate2::write::GzEncoder;
        use flate2::Compression;
        use std::fs::OpenOptions;

        let output_path = format!("{}.gz", path.display());
        let input_file = File::open(path)?;
        let output_file = OpenOptions::new()
            .write(true)
            .create(true)
            .open(&output_path)?;

        let mut encoder = GzEncoder::new(output_file, Compression::default());
        io::copy(&mut input_file.take(100 * 1024 * 1024), &mut encoder)?; // Limit to 100MB
        encoder.finish()?;

        // Remove original uncompressed file
        fs::remove_file(path)?;

        Ok(())
    }

    fn cleanup_old_versions(&self, base_path: &Path, max_versions: usize) -> io::Result<()> {
        // Collect all files matching base_path.*
        let mut files: Vec<_> = fs::read_dir(base_path.parent().unwrap())?
            .filter_map(|entry| {
                let entry = entry.ok()?;
                let path = entry.path();
                let file_name = path.file_name()?.to_string_lossy();

                if file_name.starts_with(&format!("{}", base_path.display()))
                    && file_name != base_path.file_name().unwrap().to_string_lossy() {
                    Some((path, entry.metadata().ok()?.modified().ok()?))
                } else {
                    None
                }
            })
            .collect();

        // Sort by modification time (oldest first)
        files.sort_by_key(|(_, modified)| *modified);

        // Delete oldest files until we're under max_versions
        while files.len() > max_versions {
            if let Some((path, _)) = files.pop() {
                if let Err(e) = fs::remove_file(&path) {
                    warn!("Failed to remove old log file {}: {}", path.display(), e);
                }
            }
        }

        Ok(())
    }

    fn run(&mut self) {
