    keep_running = 0;
}

/* Daemonize the process */
void daemonize() {
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        exit(EXIT_FAILURE);
    }
    if (pid > 0) {
        exit(EXIT_SUCCESS);  // Parent exits
    }

    if (setsid() < 0) {
        perror("setsid");
        exit(EXIT_FAILURE);
    }

    umask(0);  // Clear file mode creation mask

    // Redirect standard file descriptors
    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) {
        perror("open /dev/null");
        exit(EXIT_FAILURE);
    }
    dup2(fd, STDIN_FILENO);
    dup2(fd, STDOUT_FILENO);
    dup2(fd, STDERR_FILENO);
    close(fd);
}

/* Check if file exists */
bool file_exists(const char *path) {
    return access(path, F_OK) == 0;
}

/* Get file size safely */
off_t get_file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        return st.st_size;
    }
    return -1;
}

/* Perform log rotation */
void rotate_log(const char *log_path, int rotations) {
    char old_path[MAX_PATH_LEN];
    char new_path[MAX_PATH_LEN];

    // Delete the oldest rotation if it exists
    snprintf(old_path, sizeof(old_path), ROTATION_FORMAT, log_path, rotations);
    if (file_exists(old_path)) {
        unlink(old_path);
    }

    // Shift existing rotations (highest to lowest)
    for (int i = rotations - 1; i > 0; i--) {
        snprintf(old_path, sizeof(old_path), ROTATION_FORMAT, log_path, i);
        snprintf(new_path, sizeof(new_path), ROTATION_FORMAT, log_path, i + 1);
        rename(old_path, new_path);
    }

    // Rotate current log to .001
    snprintf(old_path, sizeof(old_path), ROTATION_FORMAT, log_path, 1);
    if (rename(log_path, old_path) != 0) {
        perror("rename");
        return;
    }

    // Create new empty log file with same permissions
    int fd = open(log_path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("open");
        return;
    }
    close(fd);
}

int main(int argc, char *argv[]) {
    const char *log_path = NULL;
    int max_size = DEFAULT_MAX_SIZE;
    int rotations = DEFAULT_ROTATIONS;
    int sleep_sec = DEFAULT_SLEEP_SEC;

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--log") == 0 && i + 1 < argc) {
            log_path = argv[++i];
        } else if (strcmp(argv[i], "--max-size") == 0 && i + 1 < argc) {
            max_size = atoi(argv[++i]) * 1024 * 1024;  // Convert MB to bytes
        } else if (strcmp(argv[i], "--rotations") == 0 && i + 1 < argc) {
            rotations = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--sleep") == 0 && i + 1 < argc) {
            sleep_sec = atoi(argv[++i]);
        } else {
            fprintf(stderr,
                "Usage: %s --log LOG_PATH [--max-size SIZE_MB] [--rotations N] [--sleep SEC]\n"
                "Defaults: max-size=10, rotations=5, sleep=60\n",
                argv[0]);
            return EXIT_FAILURE;
        }
    }

    if (!log_path) {
        fprintf(stderr, "Error: log path must be specified with --log\n");
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Daemonize
    daemonize();

    // Main monitoring loop
    while (keep_running) {
        off_t size = get_file_size(log_path);

        if (size == -1) {
            if (errno == ENOENT) {
                // Log file doesn't exist - create it
                int fd = open(log_path, O_WRONLY | O_CREAT | O_APPEND, 0644);
                if (fd < 0) {
                    perror("open");
                } else {
                    close(fd);
                }
            } else {
                perror("get_file_size");
            }
        } else if (size >= max_size) {
            rotate_log(log_path, rotations);
        }

        sleep(sleep_sec);
    }

    return EXIT_SUCCESS;
}
