const std = @import("std");
const Allocator = std.mem.Allocator;
const mem = std.mem;
const io = std.io;
const fs = std.fs;
const os = std.os;
const math = std.math;
const time = std.time;

// --- Memory Management ---
// Custom allocator that enforces strict memory limits
const MemoryLimitAllocator = struct {
    allocator: Allocator,
    limit: usize,
    used: usize,
    peak: usize,

    pub fn init(limit: usize) MemoryLimitAllocator {
        return .{
            .allocator = std.heap.page_allocator,
            .limit = limit,
            .used = 0,
            .peak = 0,
        };
    }

    pub fn allocator(self: *MemoryLimitAllocator) Allocator {
        return .{
            .ptr = self,
            .vtable = .{
                .alloc = alloc,
                .resize = resize,
                .free = free,
            },
        };
    }

    fn alloc(ctx: *anyopaque, len: usize, ptr_align: u8, ret_addr: usize) ?[*]u8 {
        const self = @ptrCast(*MemoryLimitAllocator, ctx);
        if (self.used + len > self.limit) {
            std.debug.print("Memory limit exceeded! Used: {d}, Limit: {d}\n", .{ self.used, self.limit });
            return null;
        }
        self.used += len;
        self.peak = math.max(self.peak, self.used);
        return @ptrCast([*]u8, self.allocator.rawAlloc(len, ptr_align));
    }

    fn resize(ctx: *anyopaque, buf: ?[*]u8, buf_len: usize, new_len: usize, ptr_align: u8, ret_addr: usize) bool {
        const self = @ptrCast(*MemoryLimitAllocator, ctx);
        if (buf) |b| {
            self.used -= buf_len;
        }
        if (new_len > 0) {
            if (self.used + new_len > self.limit) {
                return false;
            }
            self.used += new_len;
            self.peak = math.max(self.peak, self.used);
        }
        return self.allocator.rawResize(buf, buf_len, new_len, ptr_align);
    }

    fn free(ctx: *anyopaque, buf: ?[*]u8, buf_len: usize, ptr_align: u8, ret_addr: usize) void {
        const self = @ptrCast(*MemoryLimitAllocator, ctx);
        if (buf) |b| {
            self.used -= buf_len;
        }
        _ = self.allocator.rawFree(buf, buf_len, ptr_align);
    }
};

