    pub fn deinit(self: *LogRotator) void {
        self.pid_file.close();
        _ = fs.cwd().deleteFile(self.config.pid_file) catch {};
    }

    pub fn run(self: *LogRotator) !void {
        std.debug.print("Starting log rotator daemon (PID: {})\n", .{os.getpid()});
        std.debug.print("Monitoring {s} (max size: {d} bytes, interval: {d}ms)\n",
            .{ self.config.log_dir, self.config.max_log_size, self.config.poll_interval_ms });

        // Main monitoring loop
        while (!self.should_stop) {
