#include <stdbool.h>

// Configuration (all static to avoid heap allocation)
#define MAX_PATH_LEN 256
#define MAX_OLD_LOGS 10
#define DEFAULT_CHECK_INTERVAL 60 // seconds
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024) // 10MB

static char log_file[MAX_PATH_LEN] = "/var/log/mylog.log";
static off_t max_size = DEFAULT_MAX_SIZE;
static int check_interval = DEFAULT_CHECK_INTERVAL;
static int max_old_logs = MAX_OLD_LOGS;
static bool do_compress = true;

// Signal handling
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

// Daemonize the process
void daemonize() {
    pid_t pid = fork();
    if (pid < 0) {
        exit(EXIT_FAILURE);
    }
    if (pid > 0) {
        exit(EXIT_SUCCESS);
    }

    if (setsid() < 0) {
        exit(EXIT_FAILURE);
    }

    signal(SIGCHLD, SIG_IGN);
    signal(SIGHUP, SIG_IGN);
    signal(SIGTERM, handle_signal);
    signal(SIGINT, handle_signal);

    umask(0);

    int fd = open("/dev/null", O_RDWR);
    if (fd == -1) {
        exit(EXIT_FAILURE);
    }
    dup2(fd, STDIN_FILENO);
    dup2(fd, STDOUT_FILENO);
    dup2(fd, STDERR_FILENO);
    if (fd > STDERR_FILENO) {
        close(fd);
    }
}

// Check if log file exists and get its size
bool check_log_size(const char *path, off_t *size) {
    struct stat st;
    if (stat(path, &st) == 0) {
        *size = st.st_size;
        return true;
    }
    return false;
}

// Rotate the log file
void rotate_log(const char *path) {
    char new_path[MAX_PATH_LEN];
    char old_path[MAX_PATH_LEN];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y%m%d-%H%M%S", tm_info);

    // Create new rotated filename
    snprintf(new_path, sizeof(new_path), "%s.%s", path, timestamp);

    // Rename current log to new name
    if (rename(path, new_path) == 0) {
        syslog(LOG_INFO, "Rotated log: %s -> %s", path, new_path);

        // Recreate the original log file
        int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0640);
        if (fd == -1) {
            syslog(LOG_ERR, "Failed to recreate log file %s: %s", path, strerror(errno));
        } else {
            close(fd);
        }
    } else {
        syslog(LOG_ERR, "Failed to rotate log %s: %s", path, strerror(errno));
    }
}

// Compress a log file using gzip
void compress_log(const char *path) {
    char cmd[512];
    snprintf(cmd, sizeof(cmd), "gzip -f %s", path);
    int ret = system(cmd);
    if (ret == 0) {
        syslog(LOG_INFO, "Compressed log: %s.gz", path);
    } else {
        syslog(LOG_ERR, "Failed to compress log %s (exit code %d)", path, ret);
    }
}

// Clean up old log files
void cleanup_old_logs(const char *base_path) {
    DIR *dir;
    struct dirent *entry;
    char prefix[MAX_PATH_LEN];
    char suffix[] = ".gz";
    int count = 0;

    // Extract base name without extension
    char *dot = strrchr(base_path, '.');
    size_t base_len = dot ? (dot - base_path) : strlen(base_path);
    snprintf(prefix, sizeof(prefix), "%.*s.", (int)base_len, base_path);

    dir = opendir("/var/log");
    if (!dir) {
        syslog(LOG_ERR, "Failed to open log directory: %s", strerror(errno));
        return;
    }

    // First pass: count how many we have
    while ((entry = readdir(dir)) != NULL) {
        if (strncmp(entry->d_name, prefix, strlen(prefix)) == 0 &&
            strstr(entry->d_name, suffix) != NULL) {
            count++;
        }
    }
    rewinddir(dir);

    // Second pass: delete oldest ones if we exceed max
    while (count >= max_old_logs && (entry = readdir(dir)) != NULL) {
        if (strncmp(entry->d_name, prefix, strlen(prefix)) == 0 &&
            strstr(entry->d_name, suffix) != NULL) {
            char full_path[MAX_PATH_LEN];
            snprintf(full_path, sizeof(full_path), "/var/log/%s", entry->d_name);
            if (unlink(full_path) == 0) {
                syslog(LOG_INFO, "Deleted old log: %s", full_path);
                count--;
            } else {
                syslog(LOG_ERR, "Failed to delete old log %s: %s", full_path, strerror(errno));
            }
        }
    }

    closedir(dir);
}

// Main loop
void main_loop() {
    while (keep_running) {
        off_t size = 0;
        if (check_log_size(log_file, &size)) {
            if (size >= max_size) {
                rotate_log(log_file);
                if (do_compress) {
                    // Compress the rotated log (without .gz extension)
                    char rotated_path[MAX_PATH_LEN];
                    snprintf(rotated_path, sizeof(rotated_path), "%s.", log_file);
                    compress_log(rotated_path);
                }
                cleanup_old_logs(log_file);
            }
        } else {
            syslog(LOG_WARNING, "Log file %s not found", log_file);
        }

        // Sleep for the check interval
        sleep(check_interval);
    }
}

int main(int argc, char *argv[]) {
    // Parse command line arguments (simplified)
    if (argc > 1) {
        strncpy(log_file, argv[1], sizeof(log_file) - 1);
        log_file[sizeof(log_file) - 1] = '\0';
    }

    // Open syslog
    openlog("logrotated", LOG_PID | LOG_CONS, LOG_DAEMON);

    // Daemonize
    daemonize();

    syslog(LOG_INFO, "Starting log rotation daemon for %s", log_file);

    // Main loop
    main_loop();

    syslog(LOG_INFO, "Stopping log rotation daemon");
    closelog();

    return EXIT_SUCCESS;
}
