        fprintf(stderr, "Usage: %s <log_file_path>\n", argv[0]);
        return 1;
    }

    const char *log_path = argv[1];
    openlog("logrotated", LOG_PID | LOG_CONS, LOG_DAEMON);

    // Setup signal handlers
    signal(SIGTERM, handle_signal);
    signal(SIGINT, handle_signal);

    // Daemonize
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "Failed to fork: %s", strerror(errno));
        closelog();
        return 1;
    }
    if (pid > 0) {
        // Parent exits
        return 0;
    }

    // Child continues as daemon
    setsid();
    umask(0);

    // Change working directory to root
    chdir("/");

    // Close standard file descriptors
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    syslog(LOG_INFO, "Started log rotation daemon for %s", log_path);

    // Main loop
    while (keep_running) {
        if (rotate_log(log_path) == 0) {
            // Successfully rotated, sleep briefly to prevent rapid rotation
            sleep(1);
        } else {
            // Sleep for the poll interval
            sleep(POLL_INTERVAL);
        }
    }

    syslog(LOG_INFO, "Stopped log rotation daemon");
    closelog();

    return 0;
}
