### **Code (`main.rs`)**
```rust
use std::fs::{self, File, rename};
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::time::Duration;
use std::process;
use std::sync::atomic::{AtomicBool, Ordering};
use std::ffi::CString;
use std::os::raw::c_int;

// Global flag for graceful shutdown
static SHOULD_EXIT: AtomicBool = AtomicBool::new(false);

// Signal handler (using libc for minimal dependencies)
extern "C" fn handle_signal(sig: c_int) {
    if sig == libc::SIGTERM || sig == libc::SIGINT {
        SHOULD_EXIT.store(true, Ordering::Relaxed);
    }
}

// Configuration for a single log file
struct LogFileConfig {
    path: PathBuf,
    max_size: u64,    // Rotation threshold (bytes)
    max_backups: usize,
    compress: bool,   // Placeholder for compression (not implemented)
}

// Main configuration
struct Config {
    log_files: Vec<LogFileConfig>,
    check_interval: u64, // Seconds between checks
}

fn main() {
    // Set up signal handlers (SIGTERM/SIGINT)
    setup_signal_handler();

    // Load configuration (hardcoded for minimalism)
    let config = Config {
        log_files: vec![
            LogFileConfig {
                path: PathBuf::from("/var/log/app.log"),
                max_size: 10 * 1024 * 1024, // 10 MB
                max_backups: 5,
                compress: false,
            },
            LogFileConfig {
                path: PathBuf::from("/var/log/access.log"),
                max_size: 5 * 1024 * 1024,  // 5 MB
                max_backups: 3,
                compress: true,
            },
        ],
        check_interval: 60, // Check every 60 seconds
    };

    println!(
        "Starting log rotation daemon (PID: {})",
        process::id()
    );
    println!("Monitoring {} log files", config.log_files.len());

    // Main loop: Check and rotate logs periodically
    while !SHOULD_EXIT.load(Ordering::Relaxed) {
        for log_config in &config.log_files {
            if let Err(e) = rotate_log_if_needed(log_config) {
                eprintln!("Error rotating {}: {}", log_config.path.display(), e);
            }
        }
        std::thread::sleep(Duration::from_secs(config.check_interval));
    }

    println!("Shutting down gracefully...");
}

fn setup_signal_handler() {
    unsafe {
        let sig_action = libc::sigaction {
            sa_sigaction: handle_signal as usize,
            sa_mask: std::mem::zeroed(),
            sa_flags: 0,
            sa_restorer: None,
        };
        libc::sigaction(libc::SIGTERM, &sig_action, std::ptr::null_mut());
        libc::sigaction(libc::SIGINT, &sig_action, std::ptr::null_mut());
    }
}

fn rotate_log_if_needed(config: &LogFileConfig) -> io::Result<()> {
    let path = &config.path;

    // Skip if file doesn't exist
    if !path.exists() {
        return Ok(());
    }

    // Check file size
    let metadata = fs::metadata(path)?;
    if metadata.len() < config.max_size {
        return Ok(());
    }

    // Rotate the log
    rotate_log(config)?;
    Ok(())
}

fn rotate_log(config: &LogFileConfig) -> io::Result<()> {
    let path = &config.path;
    let parent = path.parent().unwrap_or_else(|| Path::new("/"));
    let stem = path.file_stem().and_then(|s| s.to_str()).unwrap_or("log");
    let extension = path.extension().and_then(|s| s.to_str()).unwrap_or("");

    // Shift existing backups (e.g., app.log.2 → app.log.3)
    for i in (1..=config.max_backups).rev() {
        let old_path = parent.join(format!("{}.{}.{}", stem, i, extension));
        if old_path.exists() {
            let new_path = parent.join(format!("{}.{}.{}", stem, i + 1, extension));
            rename(&old_path, &new_path)?;
        }
    }

    // Rename current log to .1 (e.g., app.log → app.log.1)
    let new_path = parent.join(format!("{}.1.{}", stem, extension));
    rename(path, &new_path)?;

    // Create a new empty log file
    File::create(path)?;

    // Placeholder for compression (e.g., spawn `gzip`)
    if config.compress {
        println!("[WARN] Compression not implemented (would compress {})", new_path.display());
    }

    println!("Rotated: {}", path.display());
    Ok(())
}
```

