```rust
// log_rotator.rs
// Minimal memory-constrained log rotation daemon
// Compile with: rustc --release -C opt-level=z -C panic=abort log_rotator.rs -o log_rotator

#![no_std]
#![no_main]
#![feature(lang_items, start, libc, core_intrinsics)]
#![allow(static_mut_refs)]

extern crate libc;

use core::intrinsics;
use core::panic::PanicInfo;
use libc::{c_int, c_void, fork, setsid, chdir, umask, dup2, open, O_RDWR, O_CREAT, O_TRUNC, close, exit, getpid, getppid, SIG_IGN, signal, SIGHUP, SIG_DFL};
use core::ptr;

// Memory-safe static configuration (all values are const to avoid runtime heap allocation)
const LOG_FILE_PATH: &str = "/var/log/app.log";
const MAX_SIZE_BYTES: u64 = 10 * 1024 * 1024; // 10MB
const CHECK_INTERVAL_SEC: u64 = 60; // Check every 60 seconds
const MAX_BACKUPS: u32 = 5; // Keep up to 5 rotated logs

// Panic handler (required for no_std)
#[panic_handler]
fn panic(_info: &PanicInfo) -> ! {
    unsafe { intrinsics::abort() }
}

// Entry point for no_std
#[start]
fn main(_argc: isize, _argv: *const *const u8) -> isize {
    unsafe {
        // Daemonize the process (double fork)
        match fork() {
            -1 => exit(1),
            0 => {
                // Child process 1
                if setsid() == -1 {
                    exit(1);
                }
                match fork() {
                    -1 => exit(1),
                    0 => {
                        // Child process 2 (daemon)
                        // Change working directory to root
                        if chdir(b"/\0".as_ptr() as *const i8) == -1 {
                            exit(1);
                        }
                        // Set file mode mask
                        umask(0);

                        // Redirect stdio to /dev/null
                        let null_fd = open(b"/dev/null\0".as_ptr() as *const i8, O_RDWR);
                        if null_fd != -1 {
                            dup2(null_fd, 0); // stdin
                            dup2(null_fd, 1); // stdout
                            dup2(null_fd, 2); // stderr
                            close(null_fd);
                        }

                        // Ignore SIGHUP to survive terminal closure
                        signal(SIGHUP, SIG_IGN);

                        // Main daemon loop
                        daemon_main();
                    },
                    _ => exit(0), // Exit first child
                }
            },
            _ => exit(0), // Exit original parent
        }
    }
    0
}

fn daemon_main() {
    unsafe {
        // Set up signal handler for manual rotation (SIGHUP)
        extern "C" fn handle_sighup(_: c_int) {
            // Signal handler - just sets a flag (no heap allocation)
            ROTATE_FLAG = true;
        }
        signal(SIGHUP, handle_sighup as usize);

        // Main loop
        loop {
            // Check if rotation is needed (either by size or manual request)
            if should_rotate() || ROTATE_FLAG {
                rotate_logs();
                ROTATE_FLAG = false;
            }

            // Sleep for CHECK_INTERVAL_SEC seconds (without heap allocation)
            sleep(CHECK_INTERVAL_SEC);
        }
    }
}

// Global flag for manual rotation (atomic-like, but we use volatile for simplicity)
static mut ROTATE_FLAG: bool = false;

// Check if log rotation is needed
fn should_rotate() -> bool {
    unsafe {
        let path = LOG_FILE_PATH.as_bytes().as_ptr() as *const i8;
        let fd = libc::open(path, libc::O_RDONLY);
        if fd == -1 {
            return false;
        }

        let mut stat_buf: libc::stat = core::mem::zeroed();
        if libc::fstat(fd, &mut stat_buf) == -1 {
            libc::close(fd);
            return false;
        }
        libc::close(fd);

        stat_buf.st_size >= MAX_SIZE_BYTES as i64
    }
}

// Perform log rotation
fn rotate_logs() {
    unsafe {
        // Build rotated filenames (e.g., app.log.1, app.log.2, etc.)
        let mut rotated_paths: [[u8; 256]; MAX_BACKUPS as usize] = [[0; 256]; MAX_BACKUPS as usize];

        // Generate rotated filenames in reverse order (newest first)
        for i in (1..=MAX_BACKUPS).rev() {
            let src = if i == 1 {
                LOG_FILE_PATH.as_bytes()
            } else {
                rotated_paths[(i-2) as usize].as_ptr() as *const u8
            };

            let dest = rotated_paths[(i-1) as usize].as_mut_ptr();
            let len = libc::strcpy(dest, src) as usize;

            // Append .{i} to the filename
            let suffix = b".\0";
            libc::strcat(dest, suffix.as_ptr() as *const i8);
            let suffix_num = format!("{}\0", i).as_bytes();
            libc::strcat(dest, suffix_num.as_ptr() as *const i8);
        }

        // Rename files in reverse order (oldest to newest)
        for i in (1..MAX_BACKUPS).rev() {
            let src = rotated_paths[i as usize].as_ptr() as *const i8;
            let dest = rotated_paths[(i-1) as usize].as_ptr() as *const i8;
            libc::rename(dest, src);
        }

        // Rename current log to .1
        let current_log = LOG_FILE_PATH.as_bytes().as_ptr() as *const i8;
        let rotated_log = rotated_paths[0].as_ptr() as *const i8;
        libc::rename(current_log, rotated_log);

        // Create new empty log file
        let fd = libc::open(current_log, O_RDWR | O_CREAT | O_TRUNC, 0o644);
        if fd != -1 {
            libc::close(fd);
        }
    }
}

// Simple sleep function (no heap allocation)
fn sleep(seconds: u64) {
    unsafe {
        libc::sleep(seconds as u32);
    }
}

// Required for no_std
#[lang = "eh_personality"]
extern "C" fn eh_personality() {}

// Required for no_std
#[no_mangle]
pub extern "C" fn __udivti3() {}
