### **Code (`logrotated.c`):**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/resource.h>
#include <errno.h>
#include <time.h>

#define MAX_PATH_LEN 256
#define MAX_LOG_FILES 5
#define LOG_FILE "app.log"
#define MAX_LOG_SIZE (10 * 1024 * 1024) // 10MB
#define SLEEP_INTERVAL 60 // seconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_memory_usage() {
    struct rusage usage;
    if (getrusage(RUSAGE_SELF, &usage) == 0) {
        fprintf(stderr, "[MEM] RSS: %ld KB\n", usage.ru_maxrss);
    }
}

int rotate_logs() {
    char old_path[MAX_PATH_LEN];
    char new_path[MAX_PATH_LEN];

    // Shift existing logs: app.log.4 -> app.log.5, ..., app.log -> app.log.1
    for (int i = MAX_LOG_FILES; i > 0; i--) {
        snprintf(old_path, MAX_PATH_LEN, "%s.%d", LOG_FILE, i - 1);
        snprintf(new_path, MAX_PATH_LEN, "%s.%d", LOG_FILE, i);

        if (rename(old_path, new_path) == -1 && errno != ENOENT) {
            perror("rename failed");
            return -1;
        }
    }

    // Rename current log to .1
    if (rename(LOG_FILE, LOG_FILE ".1") == -1) {
        perror("rename failed");
        return -1;
    }

    return 0;
}

int check_log_size() {
    struct stat st;
    if (stat(LOG_FILE, &st) == -1) {
        if (errno == ENOENT) return 0; // Log file doesn't exist yet
        perror("stat failed");
        return -1;
    }
    return (st.st_size >= MAX_LOG_SIZE);
}

void daemonize() {
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork failed");
        exit(EXIT_FAILURE);
    }
    if (pid > 0) exit(EXIT_SUCCESS); // Parent exits

    // Create new session
    if (setsid() < 0) {
        perror("setsid failed");
        exit(EXIT_FAILURE);
    }

    // Fork again to avoid terminal association
    pid = fork();
    if (pid < 0) {
        perror("fork failed");
        exit(EXIT_FAILURE);
    }
    if (pid > 0) exit(EXIT_SUCCESS);

    // Redirect stdio to /dev/null
    int fd = open("/dev/null", O_RDWR);
    dup2(fd, STDIN_FILENO);
    dup2(fd, STDOUT_FILENO);
    dup2(fd, STDERR_FILENO);
    close(fd);
}

int main() {
    // Set up signal handler
    signal(SIGTERM, handle_signal);
    signal(SIGINT, handle_signal);

    daemonize();

    while (keep_running) {
        if (check_log_size() == 0) {
            sleep(SLEEP_INTERVAL);
            continue;
        }

        if (rotate_logs() == 0) {
            fprintf(stderr, "[INFO] Rotated logs\n");
        } else {
            fprintf(stderr, "[ERROR] Failed to rotate logs\n");
        }

        log_memory_usage();
    }

    fprintf(stderr, "[INFO] Shutting down gracefully\n");
    return EXIT_SUCCESS;
}
```

