To add compression (e.g., `gzip`), replace the `rotate_logs()` loop with:
```c
#include <zlib.h>

int compress_log(const char *src, const char *dst) {
    FILE *src_fp = fopen(src, "rb");
    gzFile dst_fp = gzopen(dst, "wb");
    if (!src_fp || !dst_fp) {
        perror("open failed");
        return -1;
    }

    char buf[4096];
    size_t bytes;
    while ((bytes = fread(buf, 1, sizeof(buf), src_fp)) > 0) {
        if (gzwrite(dst_fp, buf, bytes) != bytes) {
            perror("gzwrite failed");
            fclose(src_fp);
            gzclose(dst_fp);
            return -1;
        }
    }

    fclose(src_fp);
    gzclose(dst_fp);
    return 0;
}

int rotate_logs() {
    // ... (shift logs as before)
    if (compress_log(LOG_FILE ".1", LOG_FILE ".1.gz") == 0) {
        unlink(LOG_FILE ".1"); // Remove uncompressed old log
    }
    return 0;
}
```
**Trade-off**: Compression adds ~1MB of binary size (for `libz`) and uses more memory during compression. Disable if memory is extremely tight.

