```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <time.h>

#define MAX_LOG_PATH 256
#define MAX_BACKUPS 5
#define DEFAULT_MAX_SIZE (10 * 1024 * 1024) // 10MB

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void daemonize() {
    pid_t pid = fork();
    if (pid < 0) {
        exit(EXIT_FAILURE);
    }
    if (pid > 0) {
        exit(EXIT_SUCCESS);
    }

    if (setsid() < 0) {
        exit(EXIT_FAILURE);
    }

    signal(SIGCHLD, SIG_IGN);
    signal(SIGTERM, handle_signal);
    signal(SIGINT, handle_signal);

    umask(0);
    chdir("/");
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
}

int should_rotate(const char *log_path, size_t max_size) {
    struct stat st;
    if (stat(log_path, &st) != 0) {
        return 0; // File doesn't exist, no rotation needed
    }
    return st.st_size >= max_size;
}

void rotate_log(const char *log_path) {
    char old_path[MAX_LOG_PATH];
    char new_path[MAX_LOG_PATH];

    // Shift existing backups: log.4 -> log.5, log.3 -> log.4, etc.
    for (int i = MAX_BACKUPS; i > 1; i--) {
        snprintf(old_path, MAX_LOG_PATH, "%s.%d", log_path, i - 1);
        snprintf(new_path, MAX_LOG_PATH, "%s.%d", log_path, i);
        rename(old_path, new_path);
    }

    // Rename current log to .1
    snprintf(old_path, MAX_LOG_PATH, "%s", log_path);
    snprintf(new_path, MAX_LOG_PATH, "%s.1", log_path);
    rename(old_path, new_path);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <log_file_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *log_path = argv[1];
    size_t max_size = DEFAULT_MAX_SIZE;
    int sleep_interval = 5; // seconds

    daemonize();

    while (keep_running) {
        if (should_rotate(log_path, max_size)) {
            rotate_log(log_path);
        }
        sleep(sleep_interval);
    }

    return EXIT_SUCCESS;
}
```

