fn rotate_log(config: &LogFileConfig) -> io::Result<()> {
    let path = &config.path;
    let parent = path.parent().unwrap_or_else(|| Path::new("/"));
    let stem = path.file_stem().and_then(|s| s.to_str()).unwrap_or("log");
    let extension = path.extension().and_then(|s| s.to_str()).unwrap_or("");

    // Rename existing log files to make space for the new rotation
    for i in (1..=config.max_backups).rev() {
        let old_path = parent.join(format!("{}.{}.{}", stem, i, extension));
        if old_path.exists() {
            let new_path = parent.join(format!("{}.{}.{}", stem, i + 1, extension));
            rename(&old_path, &new_path)?;
        }
    }

    // Rename current log file to .1
    let new_path = parent.join(format!("{}.1.{}", stem, extension));
