fn parse_args(args: &[String]) -> Result<Config> {
    let mut interval = 5;
    let mut log_file = "/var/log/system-monitor.log".to_string();
    let mut pid_file = "/var/run/system-monitor.pid".to_string();
    let mut cpu_threshold = 90.0;
