                print_usage();
                process::exit(0);
            }
            "--interval" => {
                if i + 1 >= args.len() {
                    return Err(anyhow::anyhow!("Missing value for --interval"));
                }
                interval = args[i + 1].parse()?;
                i += 1;
            }
            "--log-file" => {
                if i + 1 >= args.len() {
                    return Err(anyhow::anyhow!("Missing value for --log-file"));
                }
                log_file = args[i + 1].clone();
                i += 1;
