                }
                memory_threshold = args[i + 1].parse()?;
                i += 1;
            }
            "--disk-threshold" => {
                if i + 1 >= args.len() {
                    return Err(anyhow::anyhow!("Missing value for --disk-threshold"));
                }
                disk_threshold = args[i + 1].parse()?;
                i += 1;
            }
            _ => {
                return Err(anyhow::anyhow!("Unknown argument: {}", args[i]));
            }
        }
        i += 1;
    }

    Ok(Config {
        interval,
        log_file,
        pid_file,
        cpu_threshold,
        memory_threshold,
        disk_threshold,
    })
}

fn print_usage() {
    println!("Usage: system-monitor-daemon [options]");
    println!("Options:");
    println!("  -h, --help              Show this help message");
    println!("  --interval <seconds>    Monitoring interval in seconds (default: 5)");
    println!("  --log-file <path>       Path to log file (default: /var/log/system-monitor.log)");
    println!("  --pid-file <path>       Path to PID file (default: /var/run/system-monitor.pid)");
    println!("  --cpu-threshold <%>     CPU usage threshold for alerts (default: 90)");
    println!("  --memory-threshold <%>  Memory usage threshold for alerts (default: 95)");
    println!("  --disk-threshold <%>    Disk usage threshold for alerts (default: 90)");
}

fn daemonize(config: &Config) -> Result<()> {
    // Fork the process
    match unsafe { fork() } {
        Ok(ForkResult::Parent { child, .. }) => {
            // Parent exits
            info!("Daemon started with PID: {}", child);
            process::exit(0);
        }
        Ok(ForkResult::Child) => {
            // Child continues
        }
        Err(e) => {
            return Err(e).context("Failed to fork");
        }
    }

    // Create a new session
    setsid().context("Failed to become session leader")?;

    // Fork again to ensure we're not a session leader
    match unsafe { fork() } {
        Ok(ForkResult::Parent { child, .. }) => {
            info!("Daemon forked to background with PID: {}", child);
            process::exit(0);
        }
        Ok(ForkResult::Child) => {
            // Grandchild continues as daemon
        }
        Err(e) => {
            return Err(e).context("Failed to fork second time");
        }
    }

    // Change working directory to root
    chdir("/").context("Failed to change working directory")?;

    // Reset file mode creation mask
    unsafe { umask(0) };

    // Redirect standard file descriptors
    redirect_stdout_stderr(&config.log_file)?;

    Ok(())
}

fn redirect_stdout_stderr(log_file: &str) -> Result<()> {
    let log_path = Path::new(log_file);
    if let Some(parent) = log_path.parent() {
        std::fs::create_dir_all(parent)?;
    }

    let log_file = OpenOptions::new()
        .create(true)
        .append(true)
        .open(log_file)
        .context("Failed to open log file")?;

    // Redirect stdout and stderr to log file
    nix::unistd::dup2(
        log_file.as_raw_fd(),
        libc::STDOUT_FILENO
    ).context("Failed to dup2 stdout")?;

    nix::unistd::dup2(
        log_file.as_raw_fd(),
        libc::STDERR_FILENO
    ).context("Failed to dup2 stderr")?;

    Ok(())
}

fn write_pid_file(pid_file: &str) -> Result<()> {
    let pid = process::id();
    let pid_path = Path::new(pid_file);
    if let Some(parent) = pid_path.parent() {
        std::fs::create_dir_all(parent)?;
    }

    std::fs::write(pid_file, pid.to_string())
        .context("Failed to write PID file")?;
    info!("PID file written to {}", pid_file);
    Ok(())
}

fn setup_signal_handlers() -> Result<()> {
    use signal_hook::flag;

    // Handle SIGTERM for graceful shutdown
    flag::register(Signal::SIGTERM as i32, Arc::new(RUNNING), Ordering::SeqCst)
        .context("Failed to register SIGTERM handler")?;

    // Handle SIGHUP for reloading configuration
    flag::register(Signal::SIGHUP as i32, Arc::new(RUNNING), Ordering::SeqCst)
        .context("Failed to register SIGHUP handler")?;

    Ok(())
}

fn run_daemon(config: &Config) -> Result<()> {
    info!("System monitor daemon started with config: {:?}", config);

    let mut monitor = SystemMonitor::new();
    let manager = ResourceManager::new(
        config.cpu_threshold,
        config.memory_threshold,
        config.disk_threshold,
    );

    // Main monitoring loop
    while RUNNING.load(Ordering::SeqCst) {
        let start_time = Instant::now();

        // Collect system metrics
        match monitor.collect_metrics() {
            Ok(metrics) => {
                info!("CPU: {:.1}% | Memory: {:.1}% | Disk: {:.1}%",
                    metrics.cpu_usage,
                    metrics.memory_usage,
                    metrics.disk_usage);

                // Check thresholds and take actions if needed
                if let Err(e) = manager.check_and_manage(&metrics) {
                    error!("Failed to manage resources: {}", e);
                }
            }
            Err(e) => {
                error!("Failed to collect metrics: {}", e);
            }
        }

        // Calculate sleep duration to maintain interval
        let elapsed = start_time.elapsed();
        let interval = Duration::from_secs(config.interval);
        if elapsed < interval {
            std::thread::sleep(interval - elapsed);
        }
    }

    // Clean up PID file on shutdown
    if let Err(e) = std::fs::remove_file(&config.pid_file) {
        warn!("Failed to remove PID file: {}", e);
    }

    info!("System monitor daemon shutting down");
    Ok(())
}
