use anyhow::{Context, Result};
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::collections::HashMap;
use sysinfo::{System, SystemExt, CpuExt, DiskExt, NetworkExt, ProcessExt};

pub struct SystemMetrics {
    pub cpu_usage: f32,
    pub memory_usage: f32,
    pub disk_usage: f32,
    pub top_cpu_processes: Vec<(u32, String, f32)>,
    pub top_memory_processes: Vec<(u32, String, u64)>,
}

pub struct SystemMonitor {
    system: System,
}

impl SystemMonitor {
    pub fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        SystemMonitor { system }
    }

    pub fn collect_metrics(&mut self) -> Result<SystemMetrics> {
        // Refresh system information
        self.system.refresh_all();

        // Get CPU usage
        let cpu_usage = self.get_cpu_usage()?;

        // Get memory usage
        let memory_usage = self.get_memory_usage();

        // Get disk usage
        let disk_usage = self.get_disk_usage()?;

        // Get top processes
        let top_cpu_processes = self.get_top_cpu_processes(10)?;
        let top_memory_processes = self.get_top_memory_processes(10)?;

        Ok(SystemMetrics {
            cpu_usage,
            memory_usage,
            disk_usage,
            top_cpu_processes,
            top_memory_processes,
        })
    }

    fn get_cpu_usage(&mut self) -> Result<f32> {
        // Wait a bit between refreshes to get accurate CPU usage
        std::thread::sleep(std::time::Duration::from_millis(500));
        self.system.refresh_cpu();
        Ok(self.system.global_cpu_info().cpu_usage())
    }

    fn get_memory_usage(&self) -> f32 {
        let total = self.system.total_memory();
        let used = self.system.used_memory();
        if total > 0 {
            (used as f32 / total as f32) * 100.0
        } else {
            0.0
        }
    }

    fn get_disk_usage(&self) -> Result<f32> {
        let disks = self.system.disks();
        if disks.is_empty() {
            return Ok(0.0);
        }

        let mut total_used = 0u64;
        let mut total_total = 0u64;

        for disk in disks {
            total_used += disk.total_space() - disk.available_space();
            total_total += disk.total_space();
        }

        if total_total > 0 {
            Ok((total_used as f32 / total_total as f32) * 100.0)
        } else {
            Ok(0.0)
        }
    }

    fn get_top_cpu_processes(&self, count: usize) -> Result<Vec<(u32, String, f32)>> {
        let mut processes: Vec<_> = self.system.processes()
            .iter()
            .map(|(pid, proc)| (*pid, proc.name().to_string(), proc.cpu_usage()))
            .collect();

        processes.sort_by(|a, b| b.2.partial_cmp(&a.2).unwrap_or(std::cmp::Ordering::Equal));

        Ok(processes.into_iter().take(count).collect())
    }

    fn get_top_memory_processes(&self, count: usize) -> Result<Vec<(u32, String, u64)>> {
        let mut processes: Vec<_> = self.system.processes()
            .iter()
            .map(|(pid, proc)| (*pid, proc.name().to_string(), proc.memory()))
            .collect();

        processes.sort_by(|a, b| b.2.cmp(&a.2));

        Ok(processes.into_iter().take(count).collect())
    }
}
