        for (pid, name, usage) in &metrics.top_cpu_processes {
            if *usage > 50.0 {
                // Kill process if it's using too much CPU
                if let Err(e) = self.kill_process(*pid) {
                    log::error!("Failed to kill process {} ({}): {}", pid, name, e);
                } else {
                    log::warn!("Killed high CPU process {} ({}) using {:.1}%", pid, name, usage);
                }
            }
        }
        Ok(())
