#[command(author, version, about, long_about = None)]
struct Args {
    /// Path to configuration file
    #[arg(short, long, default_value = "/etc/resourcemon/config.toml")]
    config: String,

    /// Run in foreground (don't daemonize)
    #[arg(short, long)]
    foreground: bool,

    /// Print version information
    #[arg(short, long)]
    version: bool,
}

// Global state
struct DaemonState {
    config: Config,
    running: AtomicBool,
    system: System,
}

impl DaemonState {
    fn new(config: Config) -> Self {
        Self {
            config,
            running: AtomicBool::new(true),
            system: System::new_all(),
        }
    }
}

fn main() {
    let args = Args::parse();

    if args.version {
        println!("Resource Monitor Daemon v0.1.0");
        return;
    }

    // Load configuration
    let config = match load_config(&args.config) {
        Ok(cfg) => cfg,
        Err(e) => {
            eprintln!("Failed to load config: {}", e);
            process::exit(1);
        }
    };

    // Initialize logging
    init_logging(&config).expect("Failed to initialize logging");

    info!("Starting Resource Monitor Daemon");

    let state = Arc::new(DaemonState::new(config));

    // Set up signal handlers
    setup_signal_handlers(state.clone());

    if !args.foreground {
        // Daemonize the process
        if let Err(e) = daemonize(&state.config) {
            error!("Failed to daemonize: {}", e);
            process::exit(1);
        }
    }

    // Main monitoring loop
    if let Err(e) = run_monitoring_loop(state) {
        error!("Monitoring loop failed: {}", e);
        process::exit(1);
    }
}

fn load_config(path: &str) -> Result<Config, Box<dyn std::error::Error>> {
    let config_content = fs::read_to_string(path)?;
    let config: Config = toml::from_str(&config_content)?;
    Ok(config)
}

fn init_logging(config: &Config) -> Result<(), Box<dyn std::error::Error>> {
    let log_file = File::create(&config.log_file)?;

    // Simple logger implementation
    fern::Dispatch::new()
        .format(|out, message, record| {
            out.finish(format_args!(
                "{} [{}] {}",
                SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap()
                    .as_secs(),
                record.level(),
                message
            ))
        })
        .level(LevelFilter::Info)
        .chain(log_file)
        .apply()?;

    Ok(())
}

fn daemonize(config: &Config) -> Result<(), Box<dyn std::error::Error>> {
    // First fork
    match unsafe { unistd::fork() }? {
        ForkResult::Parent { .. } => {
            // Exit parent process
            process::exit(0);
        }
        ForkResult::Child => {}
    }

    // Create new session
    unistd::setsid()?;

    // Second fork
    match unsafe { unistd::fork() }? {
        ForkResult::Parent { .. } => {
            process::exit(0);
        }
        ForkResult::Child => {}
    }

    // Set file permissions mask
    nix::sys::stat::umask(nix::sys::stat::Mode::from_bits(0o022).unwrap());

    // Change working directory
    if let Err(e) = std::env::set_current_dir("/") {
        warn!("Failed to change working directory: {}", e);
    }

    // Write PID file
    let pid = unistd::Pid::this();
    fs::write(&config.pid_file, pid.to_string())?;

    Ok(())
}

fn setup_signal_handlers(state: Arc<DaemonState>) {
    // Handle SIGTERM and SIGINT for graceful shutdown
    let term_handler = signal::SigHandler::Handler(|| {
        info!("Received termination signal, shutting down...");
        state.running.store(false, Ordering::SeqCst);
    });

    unsafe {
        signal::signal(signal::Signal::SIGTERM, term_handler).unwrap();
        signal::signal(signal::Signal::SIGINT, term_handler).unwrap();
    }

    // Handle SIGHUP for reloading configuration
    let hup_handler = signal::SigHandler::Handler(|| {
        info!("Received SIGHUP, reloading configuration...");
        // In a real implementation, we would reload the config here
    });

    unsafe {
        signal::signal(signal::Signal::SIGHUP, hup_handler).unwrap();
    }
}

