#include <syslog.h>
#include <stdbool.h>
#include <sys/statvfs.h>

static volatile sig_atomic_t keep_running = 1;
static const char *pid_file = "/var/run/resmon.pid";
static unsigned long long last_total = 0, last_idle = 0;

void handle_signal(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        keep_running = 0;
        syslog(LOG_INFO, "Received signal %d, shutting down...", sig);
    }
}

void daemonize() {
    pid_t pid = fork();
    if (pid < 0) {
        exit(EXIT_FAILURE);
    }
    if (pid > 0) {
        exit(EXIT_SUCCESS); // Parent exits
    }

    // Child continues
    umask(0); // Clear file mode creation mask

    // Create a new session
    if (setsid() < 0) {
        exit(EXIT_FAILURE);
    }

    // Second fork to ensure daemon can't acquire a controlling terminal
    pid = fork();
    if (pid < 0) {
        exit(EXIT_FAILURE);
    }
    if (pid > 0) {
        exit(EXIT_SUCCESS);
    }

    // Change working directory to root
    chdir("/");

    // Close standard file descriptors
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    // Open syslog
    openlog("resmon", LOG_PID, LOG_DAEMON);
    syslog(LOG_INFO, "Daemon started");
}

int write_pid_file() {
    FILE *pidf = fopen(pid_file, "w");
    if (!pidf) {
        syslog(LOG_ERR, "Failed to open PID file: %s", strerror(errno));
        return -1;
    }
    fprintf(pidf, "%d\n", getpid());
    fclose(pidf);
    return 0;
}

void remove_pid_file() {
    if (pid_file) {
        unlink(pid_file);
    }
}

double get_cpu_usage() {
    unsigned long long total = 0, idle = 0;
    FILE *stat = fopen("/proc/stat", "r");
    if (!stat) {
        syslog(LOG_ERR, "Failed to open /proc/stat: %s", strerror(errno));
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), stat)) {
        if (strncmp(line, "cpu ", 4) == 0) {
            unsigned long long user, nice, system, idle_time, iowait, irq, softirq, steal, guest, guest_nice;
            sscanf(line, "cpu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
                   &user, &nice, &system, &idle_time, &iowait, &irq, &softirq, &steal, &guest, &guest_nice);
            total = user + nice + system + idle_time + iowait + irq + softirq + steal;
            idle = idle_time + iowait;
            break;
        }
    }
    fclose(stat);

    if (last_total == 0) {
        last_total = total;
        last_idle = idle;
        return 0.0; // First run, no data
    }

    unsigned long long total_diff = total - last_total;
    unsigned long long idle_diff = idle - last_idle;
    last_total = total;
    last_idle = idle;

    if (total_diff == 0) {
        return 0.0;
    }

    return 100.0 * (1.0 - (double)idle_diff / total_diff);
}

double get_memory_usage() {
    FILE *meminfo = fopen("/proc/meminfo", "r");
    if (!meminfo) {
        syslog(LOG_ERR, "Failed to open /proc/meminfo: %s", strerror(errno));
        return -1;
    }

    unsigned long total = 0, free = 0, buffers = 0, cached = 0;
    char line[256];
    while (fgets(line, sizeof(line), meminfo)) {
        if (strncmp(line, "MemTotal:", 9) == 0) {
            sscanf(line, "MemTotal: %lu kB", &total);
        } else if (strncmp(line, "MemFree:", 8) == 0) {
            sscanf(line, "MemFree: %lu kB", &free);
        } else if (strncmp(line, "Buffers:", 8) == 0) {
            sscanf(line, "Buffers: %lu kB", &buffers);
        } else if (strncmp(line, "Cached:", 7) == 0) {
            sscanf(line, "Cached: %lu kB", &cached);
        }
    }
    fclose(meminfo);

    if (total == 0) {
        return -1;
    }

    unsigned long used = total - free - buffers - cached;
    return (double)used / total * 100.0;
}

double get_disk_usage(const char *path) {
    struct statvfs stat;
    if (statvfs(path, &stat) != 0) {
        syslog(LOG_ERR, "Failed to get disk stats for %s: %s", path, strerror(errno));
        return -1;
    }

    unsigned long total = stat.f_blocks * stat.f_frsize;
    unsigned long free = stat.f_bfree * stat.f_frsize;
    unsigned long used = total - free;

    return (double)used / total * 100.0;
}

void get_network_stats(double *rx_bytes, double *tx_bytes) {
    FILE *netdev = fopen("/proc/net/dev", "r");
    if (!netdev) {
        syslog(LOG_ERR, "Failed to open /proc/net/dev: %s", strerror(errno));
        *rx_bytes = *tx_bytes = -1;
        return;
    }

    char line[256];
    // Skip header lines
    fgets(line, sizeof(line), netdev);
    fgets(line, sizeof(line), netdev);

    *rx_bytes = *tx_bytes = 0;
    while (fgets(line, sizeof(line), netdev)) {
        char iface[16];
        unsigned long rx, tx, dummy;
        if (sscanf(line, "%15s %lu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
                  iface, &rx, &dummy, &dummy, &dummy, &dummy, &dummy, &dummy, &dummy, &tx) >= 2) {
            *rx_bytes += rx;
            *tx_bytes += tx;
        }
    }
    fclose(netdev);
}

void main_loop() {
    time_t last_log = time(NULL);
    double cpu_threshold = 90.0; // 90% CPU usage threshold
    double mem_threshold = 95.0; // 95% memory usage threshold

    while (keep_running) {
        double cpu_usage = get_cpu_usage();
        double mem_usage = get_memory_usage();
        double disk_usage = get_disk_usage("/");
        double rx_bytes = 0, tx_bytes = 0;
        get_network_stats(&rx_bytes, &tx_bytes);

        time_t now = time(NULL);
        if (now - last_log >= 5) { // Log every 5 seconds
            syslog(LOG_INFO, "System Stats - CPU: %.1f%%, Memory: %.1f%%, Disk: %.1f%%, RX: %.2f KB, TX: %.2f KB",
                   cpu_usage, mem_usage, disk_usage, rx_bytes/1024, tx_bytes/1024);
            last_log = now;
        }

        if (cpu_usage > cpu_threshold) {
            syslog(LOG_WARNING, "High CPU usage detected: %.1f%%", cpu_usage);
        }

        if (mem_usage > mem_threshold) {
            syslog(LOG_WARNING, "High memory usage detected: %.1f%%", mem_usage);
        }

        sleep(1); // Check every second
    }
}

int main(int argc, char *argv[]) {
    // Set up signal handlers
    signal(SIGTERM, handle_signal);
    signal(SIGINT, handle_signal);

    // Daemonize
    daemonize();
    if (write_pid_file() != 0) {
        closelog();
        exit(EXIT_FAILURE);
    }

    // Drop privileges if running as root (simplified)
    if (getuid() == 0) {
        syslog(LOG_WARNING, "Running as root; consider dropping privileges");
    }

    // Main loop
    main_loop();

    // Cleanup
    remove_pid_file();
    closelog();
    syslog(LOG_INFO, "Daemon stopped");
    return EXIT_SUCCESS;
}
```

