// system-monitor-daemon.rs
// A high-performance system daemon for monitoring and managing OS resources
// Compile with: rustc --release system-monitor-daemon.rs -o system-monitor-daemon

use std::{
    collections::HashMap,
    env,
    fs::{self, File},
    io::{self, Read, Write},
    os::unix::net::{UnixListener, UnixStream},
    path::Path,
    process,
    sync::{Arc, Mutex},
    thread,
    time::{Duration, SystemTime},
};

use nix::{
    sys::signal::{self, Signal},
    unistd::{self, ForkResult, Pid},
};
use sysinfo::{CpuExt, DiskExt, NetworkExt, ProcessExt, System, SystemExt};

// Configuration
const DAEMON_NAME: &str = "system-monitor-daemon";
const SOCKET_PATH: &str = "/var/run/system-monitor.sock";
const PID_FILE: &str = "/var/run/system-monitor.pid";
const LOG_FILE: &str = "/var/log/system-monitor.log";
const MONITOR_INTERVAL_SEC: u64 = 5;
const MAX_LOG_SIZE: u64 = 10 * 1024 * 1024; // 10MB

// Shared state between threads
#[derive(Debug, Clone)]
struct SystemState {
    cpu_usage: Vec<f32>,
    memory_usage: (u64, u64), // (used, total)
    swap_usage: (u64, u64),
    disk_usage: Vec<(String, u64, u64)>, // (mount_point, used, total)
    network_stats: HashMap<String, (u64, u64)>, // (interface, (rx_bytes, tx_bytes))
    processes: Vec<(u32, String, f32, u64)>, // (pid, name, cpu_usage, memory_usage)
    timestamp: SystemTime,
}

impl SystemState {
    fn new() -> Self {
        Self {
            cpu_usage: vec![0.0; num_cpus::get()],
            memory_usage: (0, 0),
            swap_usage: (0, 0),
            disk_usage: Vec::new(),
            network_stats: HashMap::new(),
            processes: Vec::new(),
            timestamp: SystemTime::now(),
        }
    }
}

// Daemon utilities
fn daemonize() -> io::Result<()> {
    // Fork the process
    match unsafe { unistd::fork() } {
        Ok(ForkResult::Parent { child, .. }) => {
            // Parent process exits
            process::exit(0);
        }
        Ok(ForkResult::Child) => {
            // Child process continues
            // Create a new session
            if unistd::setsid().is_err() {
                return Err(io::Error::new(
                    io::ErrorKind::Other,
                    "Failed to create new session",
                ));
            }

            // Fork again to ensure we're not a session leader
            match unsafe { unistd::fork() } {
                Ok(ForkResult::Parent { child, .. }) => {
                    process::exit(0);
                }
                Ok(ForkResult::Child) => {
                    // Second child continues as daemon
                    // Change working directory
                    if let Err(e) = env::set_current_dir("/") {
                        eprintln!("Failed to change directory: {}", e);
                    }

                    // Set file permissions mask
                    umask::Mode::from(0o022).apply().unwrap();

                    // Redirect standard file descriptors
                    let _ = File::create("/dev/null").and_then(|null| {
                        io::stdout().flush()?;
                        io::stderr().flush()?;
                        unistd::dup2(null.as_raw_fd(), io::stdin().as_raw_fd())?;
                        unistd::dup2(null.as_raw_fd(), io::stdout().as_raw_fd())?;
                        unistd::dup2(null.as_raw_fd(), io::stderr().as_raw_fd())?;
                        Ok(())
                    });

                    Ok(())
                }
                Err(e) => Err(io::Error::new(
                    io::ErrorKind::Other,
                    format!("Second fork failed: {}", e),
                )),
            }
        }
        Err(e) => Err(io::Error::new(
            io::ErrorKind::Other,
            format!("First fork failed: {}", e),
        )),
    }
}

fn write_pid_file(pid: u32) -> io::Result<()> {
    fs::write(PID_FILE, pid.to_string())
}

fn cleanup_pid_file() {
    let _ = fs::remove_file(PID_FILE);
}

fn log_message(message: &str) -> io::Result<()> {
    // Simple logging to file with rotation
    let mut log_file = File::options()
        .create(true)
        .append(true)
        .open(LOG_FILE)?;

    // Check log size and rotate if needed
    if let Ok(metadata) = fs::metadata(LOG_FILE) {
        if metadata.len() > MAX_LOG_SIZE {
            let rotated = format!("{}.old", LOG_FILE);
            let _ = fs::rename(LOG_FILE, rotated);
        }
    }

    writeln!(
        log_file,
        "[{}] {}",
        SystemTime::now()
            .duration_since(SystemTime::UNIX_EPOCH)
            .unwrap()
            .as_secs(),
        message
    )
}

// System monitoring
fn collect_system_state() -> SystemState {
    let mut system = System::new_all();
    system.refresh_all();

    let mut state = SystemState::new();

    // CPU usage
    state.cpu_usage = system.cpus().iter().map(|cpu| cpu.cpu_usage()).collect();

    // Memory usage
    state.memory_usage = (
        system.used_memory(),
        system.total_memory(),
    );

    // Swap usage
    state.swap_usage = (
        system.used_swap(),
        system.total_swap(),
    );

    // Disk usage
    for disk in system.disks() {
        state.disk_usage.push((
            disk.mount_point().to_string_lossy().into_owned(),
            disk.total_space() - disk.available_space(),
            disk.total_space(),
        ));
    }

    // Network stats
    for (interface, data) in system.networks() {
        state.network_stats.insert(
            interface.to_string(),
            (data.received(), data.transmitted()),
        );
    }

    // Process info
    for (pid, process) in system.processes() {
        state.processes.push((
            *pid,
            process.name().to_string_lossy().into_owned(),
            process.cpu_usage(),
            process.memory(),
        ));
    }

    state.timestamp = SystemTime::now();
    state
}

// IPC server
fn handle_client(mut stream: UnixStream, state: Arc<Mutex<SystemState>>) -> io::Result<()> {
    let mut buffer = [0; 1024];

    stream.read(&mut buffer)?;
    let request = String::from_utf8_lossy(&buffer[..]).trim().to_string();

    let response = match request.as_str() {
        "cpu" => {
            let state = state.lock().unwrap();
            format!(
                "CPU Usage: {:.1}% (avg), Per-core: {:?}",
                state.cpu_usage.iter().sum::<f32>() / state.cpu_usage.len() as f32,
                state.cpu_usage
            )
        }
        "memory" => {
            let state = state.lock().unwrap();
            format!(
                "Memory: {}MB used / {}MB total ({:.1}%)",
                state.memory_usage.0 / 1024 / 1024,
                state.memory_usage.1 / 1024 / 1024,
                (state.memory_usage.0 as f64 / state.memory_usage.1 as f64) * 100.0
            )
        }
        "swap" => {
            let state = state.lock().unwrap();
            format!(
                "Swap: {}MB used / {}MB total ({:.1}%)",
                state.swap_usage.0 / 1024 / 1024,
                state.swap_usage.1 / 1024 / 1024,
                (state.swap_usage.0 as f64 / state.swap_usage.1 as f64) * 100.0
            )
        }
        "disks" => {
            let state = state.lock().unwrap();
            let mut disks = String::new();
            for (mount, used, total) in &state.disk_usage {
                disks.push_str(&format!(
                    "{} - {}MB used / {}MB total ({:.1}%)\n",
                    mount,
                    used / 1024 / 1024,
                    total / 1024 / 1024,
                    (used as f64 / *total as f64) * 100.0
                ));
            }
            disks
        }
        "processes" => {
            let state = state.lock().unwrap();
            let mut processes = String::new();
            for (pid, name, cpu, mem) in &state.processes {
                processes.push_str(&format!(
                    "PID {}: {} - CPU: {:.1}% Mem: {}KB\n",
                    pid,
                    name,
                    cpu,
                    mem / 1024
                ));
            }
            processes
        }
        "all" => {
            let state = state.lock().unwrap();
            format!(
                "System Status at {:?}\n\
                 CPU: {:.1}% avg ({:?})\n\
                 Memory: {}MB/{}MB ({:.1}%)\n\
                 Swap: {}MB/{}MB ({:.1}%)\n\
                 Disks:\n{}\
                 Processes:\n{}",
                state.timestamp,
                state.cpu_usage.iter().sum::<f32>() / state.cpu_usage.len() as f32,
                state.cpu_usage,
                state.memory_usage.0 / 1024 / 1024,
                state.memory_usage.1 / 1024 / 1024,
                (state.memory_usage.0 as f64 / state.memory_usage.1 as f64) * 100.0,
                state.swap_usage.0 / 1024 / 1024,
                state.swap_usage.1 / 1024 / 1024,
                (state.swap_usage.0 as f64 / state.swap_usage.1 as f64) * 100.0,
                state.disk_usage.iter().map(|(m, u, t)| format!(
                    "  {}: {}MB/{}MB ({:.1}%)\n",
                    m,
                    u / 1024 / 1024,
                    t / 1024 / 1024,
                    (u as f64 / *t as f64) * 100.0
                )).collect::<String>(),
                state.processes.iter().map(|(p, n, c, m)| format!(
                    "  PID {}: {} - CPU: {:.1}% Mem: {}KB\n",
                    p, n, c, m / 1024
                )).collect::<String>()
            )
        }
        "kill" => {
            // Example management command: kill <pid>
            // In a real implementation, you'd want proper authentication
            if let Some(pid_str) = request.split_whitespace().nth(1) {
                if let Ok(pid) = pid_str.parse::<i32>() {
                    if nix::sys::signal::kill(Pid::from_raw(pid), Signal::SIGTERM).is_ok() {
                        format!("Sent SIGTERM to PID {}", pid)
                    } else {
                        format!("Failed to send signal to PID {}", pid)
                    }
                } else {
                    "Invalid PID".to_string()
                }
            } else {
                "Usage: kill <pid>".to_string()
            }
        }
        _ => "Available commands: cpu, memory, swap, disks, processes, all, kill <pid>".to_string(),
    };

    stream.write_all(response.as_bytes())?;
    stream.flush()?;
    Ok(())
}

fn ipc_server(state: Arc<Mutex<SystemState>>) -> io::Result<()> {
    // Clean up any existing socket
    let _ = fs::remove_file(SOCKET_PATH);

    let listener = UnixListener::bind(SOCKET_PATH)?;
    log_message("IPC server started")?;

    for stream in listener.incoming() {
        match stream {
            Ok(stream) => {
                let state = Arc::clone(&state);
                thread::spawn(move || {
                    if let Err(e) = handle_client(stream, state) {
                        log_message(&format!("IPC error: {}", e)).unwrap();
                    }
                });
            }
            Err(err) => {
                log_message(&format!("IPC connection error: {}", err)).unwrap();
            }
        }
    }

    Ok(())
}

// Main monitoring loop
fn monitoring_loop(state: Arc<Mutex<SystemState>>) {
    log_message("Monitoring loop started").unwrap();

    loop {
        let new_state = collect_system_state();
        {
            let mut state = state.lock().unwrap();
            *state = new_state;
        }

        log_message(&format!("System state updated at {:?}", state.lock().unwrap().timestamp)).unwrap();
        thread::sleep(Duration::from_secs(MONITOR_INTERVAL_SEC));
    }
}

// Signal handler
extern "C" fn handle_signal(sig: i32) {
    match sig {
        libc::SIGTERM | libc::SIGINT => {
            log_message("Received termination signal, shutting down...").unwrap();
            cleanup_pid_file();
            process::exit(0);
        }
        _ => {}
    }
}

fn main() {
    // Set up signal handling
    unsafe {
        libc::signal(libc::SIGTERM, handle_signal as libc::sighandler_t);
        libc::signal(libc::SIGINT, handle_signal as libc::sighandler_t);
    }

    // Daemonize
    if let Err(e) = daemonize() {
        eprintln!("Failed to daemonize: {}", e);
        process::exit(1);
    }

    // Write PID file
    if let Err(e) = write_pid_file(process::id()) {
        eprintln!("Failed to write PID file: {}", e);
        process::exit(1);
    }

    log_message("Daemon started successfully").unwrap();

    // Shared state
    let state = Arc::new(Mutex::new(SystemState::new()));

    // Start monitoring thread
    let monitor_state = Arc::clone(&state);
    thread::spawn(move || monitoring_loop(monitor_state));

    // Start IPC server
    if let Err(e) = ipc_server(state) {
        log_message(&format!("IPC server failed: {}", e)).unwrap();
        process::exit(1);
    }
}
