use anyhow::{Context, Result};
use log::{info, error, LevelFilter};
use nix::sys::signal::{self, Signal};
use nix::unistd::{fork, ForkResult, setsid, chdir, umask};
use nix::fcntl::{open, OFlag};
use nix::sys::stat::Mode;
use nix::unistd::Pid;
use std::fs::{File, OpenOptions};
use std::io::{self, Write};
use std::path::Path;
use std::process;
use std::time::{Duration, Instant};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

mod system_monitor;
mod resource_manager;

use system_monitor::SystemMonitor;
use resource_manager::ResourceManager;

static RUNNING: AtomicBool = AtomicBool::new(true);

fn main() -> Result<()> {
    // Initialize logging
    env_logger::Builder::new()
        .filter_level(LevelFilter::Info)
        .init();

    // Parse command line arguments
    let args: Vec<String> = std::env::args().collect();
    if args.len() > 1 && (args[1] == "-h" || args[1] == "--help") {
        print_usage();
        process::exit(0);
    }

    // Daemonize
    daemonize()?;

    // Set up signal handlers
    setup_signal_handlers()?;

    // Main loop
    run_daemon()?;

    Ok(())
}

fn print_usage() {
    println!("Usage: system-monitor-daemon [options]");
    println!("Options:");
    println!("  -h, --help     Show this help message");
    println!("  --interval     Monitoring interval in seconds (default: 5)");
    println!("  --log-file     Path to log file (default: /var/log/system-monitor.log)");
    println!("  --pid-file     Path to PID file (default: /var/run/system-monitor.pid)");
}

fn daemonize() -> Result<()> {
    // Fork the process
    match unsafe { fork() } {
        Ok(ForkResult::Parent { child, .. }) => {
            // Parent exits
            info!("Daemon started with PID: {}", child);
            process::exit(0);
        }
        Ok(ForkResult::Child) => {
            // Child continues
        }
        Err(e) => {
            return Err(e).context("Failed to fork");
        }
    }

    // Create a new session
    setsid().context("Failed to become session leader")?;

    // Fork again to ensure we're not a session leader
    match unsafe { fork() } {
        Ok(ForkResult::Parent { child, .. }) => {
            info!("Daemon forked to background with PID: {}", child);
            process::exit(0);
        }
        Ok(ForkResult::Child) => {
            // Grandchild continues as daemon
        }
        Err(e) => {
            return Err(e).context("Failed to fork second time");
        }
    }

    // Change working directory to root
    chdir("/").context("Failed to change working directory")?;

    // Reset file mode creation mask
    unsafe { umask(0) };

    // Redirect standard file descriptors
    redirect_stdout_stderr()?;

    Ok(())
}

fn redirect_stdout_stderr() -> Result<()> {
    let log_file = OpenOptions::new()
        .create(true)
        .append(true)
        .open("/var/log/system-monitor.log")
        .context("Failed to open log file")?;

    // Redirect stdout and stderr to log file
    nix::unistd::dup2(
        log_file.as_raw_fd(),
        libc::STDOUT_FILENO
    ).context("Failed to dup2 stdout")?;

    nix::unistd::dup2(
        log_file.as_raw_fd(),
        libc::STDERR_FILENO
    ).context("Failed to dup2 stderr")?;

    Ok(())
}

fn setup_signal_handlers() -> Result<()> {
    use signal_hook::flag;

    // Handle SIGTERM for graceful shutdown
    flag::register(Signal::SIGTERM as i32, Arc::new(RUNNING), Ordering::SeqCst)
        .context("Failed to register SIGTERM handler")?;

    // Handle SIGHUP for reloading configuration
    flag::register(Signal::SIGHUP as i32, Arc::new(RUNNING), Ordering::SeqCst)
        .context("Failed to register SIGHUP handler")?;

    Ok(())
}

fn run_daemon() -> Result<()> {
    info!("System monitor daemon started");

    let mut monitor = SystemMonitor::new();
    let manager = ResourceManager::new();

    // Main monitoring loop
    while RUNNING.load(Ordering::SeqCst) {
        let start_time = Instant::now();

        // Collect system metrics
        if let Err(e) = monitor.collect_metrics() {
            error!("Failed to collect metrics: {}", e);
        }

        // Check thresholds and take actions if needed
        if let Err(e) = manager.check_and_manage(&monitor) {
            error!("Failed to manage resources: {}", e);
        }

        // Calculate sleep duration to maintain interval
        let elapsed = start_time.elapsed();
        let interval = Duration::from_secs(5); // Default interval
        if elapsed < interval {
            std::thread::sleep(interval - elapsed);
        }
    }

    info!("System monitor daemon shutting down");
    Ok(())
}
