use anyhow::{Context, Result};
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::collections::HashMap;

pub struct SystemMetrics {
    pub cpu_usage: f32,
    pub memory_usage: f32,
    pub disk_io: HashMap<String, DiskStats>,
    pub network_io: HashMap<String, NetworkStats>,
    pub process_count: usize,
    pub top_cpu_processes: Vec<(u32, String, f32)>,
    pub top_memory_processes: Vec<(u32, String, u64)>,
}

pub struct DiskStats {
    pub read_ios: u64,
    pub write_ios: u64,
    pub read_sectors: u64,
    pub write_sectors: u64,
}

pub struct NetworkStats {
    pub rx_bytes: u64,
    pub tx_bytes: u64,
}

pub struct SystemMonitor {
    last_cpu_stats: Option<CpuStats>,
    last_disk_stats: HashMap<String, DiskStats>,
    last_network_stats: HashMap<String, NetworkStats>,
}

struct CpuStats {
    user: u64,
    nice: u64,
    system: u64,
    idle: u64,
    iowait: u64,
    irq: u64,
    softirq: u64,
    steal: u64,
    guest: u64,
    guest_nice: u64,
}

impl SystemMonitor {
    pub fn new() -> Self {
        SystemMonitor {
            last_cpu_stats: None,
            last_disk_stats: HashMap::new(),
            last_network_stats: HashMap::new(),
        }
    }

    pub fn collect_metrics(&mut self) -> Result<SystemMetrics> {
        let cpu_usage = self.collect_cpu_usage()?;
        let memory_usage = self.collect_memory_usage()?;
        let disk_io = self.collect_disk_io()?;
        let network_io = self.collect_network_io()?;
        let process_count = self.count_processes()?;
        let top_cpu_processes = self.get_top_cpu_processes(10)?;
        let top_memory_processes = self.get_top_memory_processes(10)?;

        Ok(SystemMetrics {
            cpu_usage,
            memory_usage,
            disk_io,
            network_io,
            process_count,
            top_cpu_processes,
            top_memory_processes,
        })
    }

    fn collect_cpu_usage(&mut self) -> Result<f32> {
        let file = File::open("/proc/stat").context("Failed to open /proc/stat")?;
        let reader = BufReader::new(file);

        let mut total = 0u64;
        let mut idle = 0u64;
        let mut iowait = 0u64;

        for line in reader.lines().take(1) {
            let line = line?;
            if !line.starts_with("cpu ") {
                continue;
            }

            let parts: Vec<&str> = line.split_whitespace().skip(1).collect();
            if parts.len() < 4 {
                continue;
            }

            total = parts.iter().take(10).filter_map(|s| s.parse::<u64>().ok()).sum();
            idle = parts[3].parse::<u64>()?;
            iowait = parts[4].parse::<u64>()?;
        }

        let usage = if let Some(prev) = &self.last_cpu_stats {
            let prev_total = prev.user + prev.nice + prev.system + prev.idle + prev.iowait +
                            prev.irq + prev.softirq + prev.steal + prev.guest + prev.guest_nice;
            let prev_idle = prev.idle + prev.iowait;

            let delta_total = total.saturating_sub(prev_total);
            let delta_idle = idle.saturating_sub(prev_idle);

            if delta_total > 0 {
                100.0 * (delta_total - delta_idle) as f32 / delta_total as f32
            } else {
                0.0
            }
        } else {
            0.0
        };

        // Update last stats
        self.last_cpu_stats = Some(CpuStats {
            user: parts.get(0).and_then(|s| s.parse().ok()).unwrap_or(0),
            nice: parts.get(1).and_then(|s| s.parse().ok()).unwrap_or(0),
            system: parts.get(2).and_then(|s| s.parse().ok()).unwrap_or(0),
            idle: parts.get(3).and_then(|s| s.parse().ok()).unwrap_or(0),
            iowait: parts.get(4).and_then(|s| s.parse().ok()).unwrap_or(0),
            irq: parts.get(5).and_then(|s| s.parse().ok()).unwrap_or(0),
            softirq: parts.get(6).and_then(|s| s.parse().ok()).unwrap_or(0),
            steal: parts.get(7).and_then(|s| s.parse().ok()).unwrap_or(0),
            guest: parts.get(8).and_then(|s| s.parse().ok()).unwrap_or(0),
            guest_nice: parts.get(9).and_then(|s| s.parse().ok()).unwrap_or(0),
        });

        Ok(usage)
    }

    // Implement other collection methods...
}
