use clap::Parser;
use daemonize::Daemonize;
use std::fs::File;
use std::path::PathBuf;
use sysinfo::{System, SystemExt};
use tokio::sync::mpsc;
use tracing::{info, error, Level};
use tracing_subscriber::EnvFilter;

mod metrics;
mod server;
mod alerts;

use metrics::Metrics;
use alerts::Alert;

#[derive(Parser, Debug)]
#[command(author, version, about, long_about = None)]
struct Args {
    /// Run as a daemon
    #[arg(short, long)]
    daemon: bool,

    /// Path to PID file
    #[arg(short, long, default_value = "/var/run/os_resource_daemon.pid")]
    pid_file: PathBuf,

    /// Path to log file
    #[arg(short, long, default_value = "/var/log/os_resource_daemon.log")]
    log_file: PathBuf,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialize logging
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env().add_directive(Level::INFO.into()))
        .init();

    let args = Args::parse();

    if args.daemon {
        info!("Starting as daemon...");
        let stdout = File::create(&args.log_file)?;
        let stderr = stdout.try_clone()?;

        let daemonize = Daemonize::new()
            .pid_file(&args.pid_file)
            .stdout(stdout)
            .stderr(stderr)
            .chown_pid_file(true);

        match daemonize.start() {
            Ok(_) => info!("Successfully daemonized"),
            Err(e) => {
                error!("Failed to daemonize: {}", e);
                return Err(e.into());
            }
        }
    }

    // Create channel for metrics
    let (metrics_tx, mut metrics_rx) = mpsc::channel(32);

    // Spawn metrics collection task
    tokio::spawn(async move {
        let mut system = System::new_all();
        let mut interval = tokio::time::interval(std::time::Duration::from_secs(5));

        loop {
            interval.tick().await;
            system.refresh_all();

            let metrics = Metrics::from_system(&system);
            if metrics_tx.send(metrics).await.is_err() {
                error!("Failed to send metrics");
                break;
            }
        }
    });

    // Spawn alert monitoring task
    tokio::spawn(async move {
        let mut alerts = Vec::new();
        while let Some(metrics) = metrics_rx.recv().await {
            let new_alerts = alerts::check_thresholds(&metrics);
            alerts.extend(new_alerts);
            // In a real system, we might send alerts via email, webhook, etc.
            for alert in &alerts {
                info!("ALERT: {}", alert);
            }
        }
    });

    // Start HTTP server
    let app = server::create_app();
    let listener = tokio::net::TcpListener::bind("0.0.0.0:3000").await?;
    info!("Server running on {}", listener.local_addr()?);
    axum::serve(listener, app).await?;

    Ok(())
}
