use serde::Serialize;
use crate::metrics::Metrics;

#[derive(Debug, Serialize, Clone)]
pub struct Alert {
    pub timestamp: u64,
    pub message: String,
}

pub fn check_thresholds(metrics: &Metrics) -> Vec<Alert> {
    let mut alerts = Vec::new();

    // CPU usage threshold (90%)
    if metrics.cpu_usage > 90.0 {
        alerts.push(Alert {
            timestamp: metrics.timestamp,
            message: format!("High CPU usage: {:.1}%", metrics.cpu_usage),
        });
    }

    // Memory usage threshold (90%)
    let memory_percent = (metrics.memory_used as f32 / metrics.memory_total as f32) * 100.0;
    if memory_percent > 90.0 {
        alerts.push(Alert {
            timestamp: metrics.timestamp,
            message: format!("High memory usage: {:.1}% ({}MB/{}MB)",
                memory_percent,
                metrics.memory_used / 1024 / 1024,
                metrics.memory_total / 1024 / 1024),
        });
    }

    // Swap usage threshold (50%)
    let swap_percent = (metrics.swap_used as f32 / metrics.swap_total as f32) * 100.0;
    if swap_percent > 50.0 {
        alerts.push(Alert {
            timestamp: metrics.timestamp,
            message: format!("High swap usage: {:.1}% ({}MB/{}MB)",
                swap_percent,
                metrics.swap_used / 1024 / 1024,
                metrics.swap_total / 1024 / 1024),
        });
    }

    alerts
}
