void kill_high_cpu_processes(double threshold) {
    DIR *dir = opendir("/proc");
    if (!dir) {
        syslog(LOG_ERR, "Failed to open /proc: %s", strerror(errno));
        return;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type != DT_DIR) continue;
        char *end;
        pid_t pid = strtol(entry->d_name, &end, 10);
        if (*end != '\0') continue; // Not a PID

        char stat_path[256];
        snprintf(stat_path, sizeof(stat_path), "/proc/%d/stat", pid);
        FILE *stat = fopen(stat_path, "r");
        if (!stat) continue;

        char comm[256], state;
        unsigned long utime, stime;
        if (fscanf(stat, "%*d %255s %c %*d %*d %*d %*d %*d %*u %*u %*u %lu %lu",
                   comm, &state, &utime, &stime) == 4) {
            double cpu_usage = (utime + stime) / (double)sysconf(_SC_CLK_TCK);
            // This is a rough estimate; real CPU usage would need time-based sampling
            if (cpu_usage > threshold) {
                syslog(LOG_WARNING, "Killing high CPU process %d (%s) with usage %.2f%%", pid, comm, cpu_usage);
                kill(pid, SIGKILL);
            }
        }
        fclose(stat);
    }
    closedir(dir);
}
