use clap::Parser;
use serde::Serialize;
use std::collections::HashMap;
use std::sync::Arc;
use sysinfo::{CpuExt, DiskExt, NetworkExt, PidExt, ProcessExt, System, SystemExt};
use tokio::sync::Mutex;
use warp::{Filter, Reply};

#[derive(Parser, Debug)]
#[command(author, version, about, long_about = None)]
struct Args {
    /// Port to listen on
    #[arg(short, long, default_value_t = 8080)]
    port: u16,

    /// Update interval in seconds
    #[arg(short, long, default_value_t = 5)]
    interval: u64,
}

#[derive(Debug, Serialize)]
struct SystemMetrics {
    cpu: HashMap<String, f32>,
    memory: MemoryMetrics,
    disks: Vec<DiskMetrics>,
    network: NetworkMetrics,
    processes: Vec<ProcessMetrics>,
}

#[derive(Debug, Serialize)]
struct MemoryMetrics {
    total: u64,
    used: u64,
    free: u64,
    available: u64,
}

#[derive(Debug, Serialize)]
struct DiskMetrics {
    name: String,
    mount_point: String,
    total: u64,
    used: u64,
    free: u64,
}

#[derive(Debug, Serialize)]
struct NetworkMetrics {
    total_received: u64,
    total_transmitted: u64,
}

#[derive(Debug, Serialize)]
struct ProcessMetrics {
    pid: u32,
    name: String,
    cpu_usage: f32,
    memory_usage: u64,
    status: String,
}

struct AppState {
    system: Arc<Mutex<System>>,
    interval: u64,
}

async fn collect_metrics(state: Arc<AppState>) -> SystemMetrics {
    let mut system = state.system.lock().await;
    system.refresh_all();

    let mut cpu_metrics = HashMap::new();
    for (i, cpu) in system.cpus().iter().enumerate() {
        cpu_metrics.insert(format!("cpu{}", i), cpu.cpu_usage());
    }

    let memory = system.used_memory();
    let memory_total = system.total_memory();
    let memory_free = system.free_memory();
    let memory_available = system.available_memory();

    let disks = system.disks()
        .iter()
        .map(|disk| DiskMetrics {
            name: String::from_utf8_lossy(disk.name()).into_owned(),
            mount_point: String::from_utf8_lossy(disk.mount_point()).into_owned(),
            total: disk.total_space(),
            used: disk.total_space() - disk.available_space(),
            free: disk.available_space(),
        })
        .collect();

    let networks = system.networks();
    let network = NetworkMetrics {
        total_received: networks.iter().map(|(_, net)| net.total_received()).sum(),
        total_transmitted: networks.iter().map(|(_, net)| net.total_transmitted()).sum(),
    };

    let processes = system.processes()
        .iter()
        .map(|(pid, process)| ProcessMetrics {
            pid: pid.as_u32(),
            name: process.name().to_string_lossy().into_owned(),
            cpu_usage: process.cpu_usage(),
            memory_usage: process.memory(),
            status: format!("{:?}", process.status()),
        })
        .collect();

    SystemMetrics {
        cpu: cpu_metrics,
        memory: MemoryMetrics {
            total: memory_total,
            used: memory,
            free: memory_free,
            available: memory_available,
        },
        disks,
        network,
        processes,
    }
}

async fn metrics_handler(state: Arc<AppState>) -> Result<impl Reply, warp::Rejection> {
    let metrics = collect_metrics(state).await;
    Ok(warp::reply::json(&metrics))
}

#[tokio::main]
async fn main() {
    // Initialize logging
    tracing_subscriber::fmt()
        .with_env_filter("system_monitor_daemon=info")
        .init();

    // Parse command line arguments
    let args = Args::parse();

    // Initialize system monitor
    let mut system = System::new_all();
    system.refresh_all();

    let state = Arc::new(AppState {
        system: Arc::new(Mutex::new(system)),
        interval: args.interval,
    });

    // Clone state for the metrics handler
    let state_metrics = state.clone();

    // Spawn a background task to refresh system data periodically
    tokio::spawn(async move {
        let mut interval = tokio::time::interval(tokio::time::Duration::from_secs(args.interval));
        loop {
            interval.tick().await;
            let mut system = state.system.lock().await;
            system.refresh_all();
        }
    });

    // Define the metrics endpoint
    let metrics_route = warp::path("metrics")
        .and(warp::get())
        .and(with_state(state_metrics))
        .and_then(metrics_handler);

    // Start the server
    tracing::info!("Starting system monitor daemon on port {}", args.port);
    warp::serve(metrics_route)
        .run(([0, 0, 0, 0], args.port))
        .await;
}

fn with_state(
    state: Arc<AppState>,
) -> impl Filter<Extract = (Arc<AppState>,), Error = std::convert::Infallible> + Clone {
    warp::any().map(move || state.clone())
}
```

