### `src/main.rs`
```rust
use axum::{
    body::Bytes,
    extract::{Path, State},
    http::{Request, StatusCode},
    response::IntoResponse,
    routing::{get, post},
    Json, Router,
};
use clap::Parser;
use daemonize::Daemonize;
use log::{error, info, LevelFilter};
use nix::sys::signal::{self, Signal};
use nix::unistd::{self, Pid};
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    fs::{self, File},
    io::{self, Write},
    path::PathBuf,
    sync::Arc,
    time::{Duration, SystemTime},
};
use sysinfo::{CpuExt, Disks, PidExt, ProcessExt, System, SystemExt};
use tokio::{
    net::UnixListener,
    sync::Mutex,
    time,
};

#[derive(Debug, Parser)]
#[command(name = "sysmon-daemon")]
#[command(about = "High-performance system resource monitoring daemon", long_about = None)]
struct Cli {
    /// Run as a daemon
    #[arg(long)]
    daemonize: bool,

    /// Path to PID file
    #[arg(long, default_value = "/var/run/sysmon.pid")]
    pid_file: PathBuf,

    /// Path to Unix socket
    #[arg(long, default_value = "/var/run/sysmon.sock")]
    socket_path: PathBuf,

    /// Log level (off, error, warn, info, debug, trace)
    #[arg(long, default_value = "info")]
    log_level: LevelFilter,
}

#[derive(Debug, Serialize, Deserialize, Clone)]
struct SystemMetrics {
    timestamp: SystemTime,
    uptime: u64,
    cpu_usage: f32,
    memory_used: u64,
    memory_total: u64,
    swap_used: u64,
    swap_total: u64,
    processes: usize,
    running_processes: usize,
    disk_usage: HashMap<String, (u64, u64)>, // (used, total) for each mount point
    load_average: (f64, f64, f64),
}

#[derive(Debug, Serialize, Deserialize, Clone)]
struct ThresholdConfig {
    cpu_high: f32,
    memory_high: f64,
    disk_high: f64,
}

#[derive(Debug, Serialize, Deserialize)]
struct ActionRequest {
    pid: Option<u32>,
    action: String,
}

struct AppState {
    metrics: Arc<Mutex<SystemMetrics>>,
    thresholds: Arc<Mutex<ThresholdConfig>>,
    system: Arc<Mutex<System>>,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cli = Cli::parse();

    // Initialize logging
    env_logger::Builder::new()
        .filter_level(cli.log_level)
        .init();

    // Create directories if they don't exist
    if let Some(parent) = cli.pid_file.parent() {
        fs::create_dir_all(parent)?;
    }
    if let Some(parent) = cli.socket_path.parent() {
        fs::create_dir_all(parent)?;
    }

    // Daemonize if requested
    if cli.daemonize {
        info!("Starting in daemon mode");

        let stdout = File::create("/var/log/sysmon.out")?;
        let stderr = File::create("/var/log/sysmon.err")?;

        let daemonize = Daemonize::new()
            .pid_file(cli.pid_file)
            .stdout(stdout)
            .stderr(stderr)
            .chown_pid_file(true)
            .working_directory("/tmp");

        match daemonize.start() {
            Ok(_) => info!("Successfully daemonized"),
            Err(e) => {
                error!("Failed to daemonize: {}", e);
                return Err(e.into());
            }
        }
    }

    // Set up signal handling
    let (shutdown_sender, mut shutdown_receiver) = tokio::sync::oneshot::channel();
    tokio::spawn(async move {
        if let Err(e) = tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())
            .expect("Failed to register signal handler")
            .recv()
            .await
        {
            error!("Signal handler error: {}", e);
        }
        info!("Received termination signal");
        let _ = shutdown_sender.send(());
    });

    // Initialize system monitor
    let mut system = System::new_all();
    system.refresh_all();

    let initial_metrics = SystemMetrics {
        timestamp: SystemTime::now(),
        uptime: system.uptime(),
        cpu_usage: system.global_cpu_info().cpu_usage(),
        memory_used: system.used_memory(),
        memory_total: system.total_memory(),
        swap_used: system.used_swap(),
        swap_total: system.total_swap(),
        processes: system.processes().len(),
        running_processes: system.processes().iter().filter(|(_, p)| p.status() == sysinfo::ProcessStatus::Run).count(),
        disk_usage: get_disk_usage(),
        load_average: system.load_average(),
    };

    let initial_thresholds = ThresholdConfig {
        cpu_high: 90.0,
        memory_high: 0.9,
        disk_high: 0.85,
    };

    let state = Arc::new(AppState {
        metrics: Arc::new(Mutex::new(initial_metrics)),
        thresholds: Arc::new(Mutex::new(initial_thresholds)),
        system: Arc::new(Mutex::new(system)),
    });

    // Start monitoring loop
    let metrics_state = state.metrics.clone();
    let thresholds_state = state.thresholds.clone();
    let system_state = state.system.clone();
    tokio::spawn(async move {
        monitor_loop(metrics_state, thresholds_state, system_state).await;
    });

    // Start HTTP server (using Unix socket)
    let app = Router::new()
        .route("/metrics", get(get_metrics))
        .route("/thresholds", get(get_thresholds).post(set_thresholds))
        .route("/processes", get(list_processes))
        .route("/processes/:pid", get(get_process_info).delete(kill_process))
        .route("/actions", post(handle_action))
        .with_state(state);

    // Clean up existing socket if it exists
    let _ = fs::remove_file(&cli.socket_path);

    let listener = UnixListener::bind(&cli.socket_path)?;
    info!("Listening on {}", cli.socket_path.display());

    tokio::select! {
        _ = axum::serve(listener, app.into_make_service()) => {
            info!("Server stopped");
        },
        _ = shutdown_receiver => {
            info!("Shutting down gracefully...");
            // Clean up socket
            let _ = fs::remove_file(&cli.socket_path);
        }
    }

    Ok(())
}

async fn monitor_loop(
    metrics: Arc<Mutex<SystemMetrics>>,
    thresholds: Arc<Mutex<ThresholdConfig>>,
    system: Arc<Mutex<System>>,
) {
    let mut interval = time::interval(Duration::from_secs(5));

    loop {
        interval.tick().await;

        // Refresh system information
        {
            let mut sys = system.lock().await;
            sys.refresh_all();
        }

        // Collect metrics
        let mut sys = system.lock().await;
        let mut metrics_guard = metrics.lock().await;

        metrics_guard.timestamp = SystemTime::now();
        metrics_guard.uptime = sys.uptime();
        metrics_guard.cpu_usage = sys.global_cpu_info().cpu_usage();
        metrics_guard.memory_used = sys.used_memory();
        metrics_guard.memory_total = sys.total_memory();
        metrics_guard.swap_used = sys.used_swap();
        metrics_guard.swap_total = sys.total_swap();
        metrics_guard.processes = sys.processes().len();
        metrics_guard.running_processes = sys
            .processes()
            .iter()
            .filter(|(_, p)| p.status() == sysinfo::ProcessStatus::Run)
            .count();
        metrics_guard.disk_usage = get_disk_usage();
        metrics_guard.load_average = sys.load_average();

        // Check thresholds and take actions if needed
        let thresholds_guard = thresholds.lock().await;
        check_and_act_on_thresholds(&metrics_guard, &thresholds_guard).await;

        info!("Metrics updated - CPU: {:.1}%, Mem: {:.1}%/{:.1}%, Processes: {}",
            metrics_guard.cpu_usage,
            (metrics_guard.memory_used as f64 / metrics_guard.memory_total as f64) * 100.0,
            metrics_guard.memory_total as f64 / 1024.0 / 1024.0,
            metrics_guard.processes);
    }
}

fn get_disk_usage() -> HashMap<String, (u64, u64)> {
    let mut disk_usage = HashMap::new();
    if let Ok(disks) = Disks::new_with_refreshed_list() {
        for disk in disks.list() {
            disk_usage.insert(
                disk.mount_point().to_string_lossy().into_owned(),
                (disk.total_space() - disk.available_space(), disk.total_space()),
            );
        }
    }
    disk_usage
}

async fn check_and_act_on_thresholds(metrics: &SystemMetrics, thresholds: &ThresholdConfig) {
    let memory_usage = metrics.memory_used as f64 / metrics.memory_total as f64;
    let disk_usage = metrics
        .disk_usage
        .values()
        .map(|(used, total)| *used as f64 / *total as f64)
        .fold(0.0, f64::max);

    // Check CPU threshold
    if metrics.cpu_usage > thresholds.cpu_high {
        warn!("High CPU usage detected: {:.1}%", metrics.cpu_usage);
        // In a real implementation, we might want to log this or take action
    }

    // Check memory threshold
    if memory_usage > thresholds.memory_high {
        warn!(
            "High memory usage detected: {:.1}% ({}MB/{}MB)",
            memory_usage * 100.0,
            metrics.memory_used / 1024 / 1024,
            metrics.memory_total / 1024 / 1024
        );
    }

    // Check disk threshold
    if disk_usage > thresholds.disk_high {
        warn!("High disk usage detected: {:.1}%", disk_usage * 100.0);
    }
}

// API Handlers

async fn get_metrics(State(state): State<Arc<AppState>>) -> impl IntoResponse {
    let metrics = state.metrics.lock().await;
    Json(metrics.clone())
}

async fn get_thresholds(State(state): State<Arc<AppState>>) -> impl IntoResponse {
    let thresholds = state.thresholds.lock().await;
    Json(thresholds.clone())
}

async fn set_thresholds(
    State(state): State<Arc<AppState>>,
    Json(thresholds): Json<ThresholdConfig>,
) -> impl IntoResponse {
    let mut current = state.thresholds.lock().await;
    *current = thresholds;
    Json(*current)
}

async fn list_processes(State(state): State<Arc<AppState>>) -> impl IntoResponse {
    let sys = state.system.lock().await;
    let processes: Vec<_> = sys
        .processes()
        .iter()
        .map(|(pid, proc)| {
            (
                *pid,
                proc.name().to_string_lossy().into_owned(),
                proc.status().to_string(),
                proc.cpu_usage(),
                proc.memory() / 1024 / 1024, // Convert to MB
            )
        })
        .collect();

    Json(processes)
}

async fn get_process_info(
    State(state): State<Arc<AppState>>,
    Path(pid): Path<u32>,
) -> impl IntoResponse {
    let sys = state.system.lock().await;
    if let Some(process) = sys.process(Pid::from_raw(pid as i32)) {
        let process_info = serde_json::json!({
            "pid": pid,
            "name": process.name().to_string_lossy(),
            "status": process.status().to_string(),
            "cpu_usage": process.cpu_usage(),
            "memory_usage_mb": process.memory() / 1024 / 1024,
            "command": process.cmd().join(" "),
            "start_time": process.start_time(),
            "user_id": process.user_id().map(|id| id.to_string()),
        });
        Json(process_info)
    } else {
        (StatusCode::NOT_FOUND, "Process not found").into_response()
    }
}

async fn kill_process(
    State(state): State<Arc<AppState>>,
    Path(pid): Path<u32>,
) -> impl IntoResponse {
    match unistd::kill(Pid::from_raw(pid as i32), Signal::SIGTERM) {
        Ok(_) => (StatusCode::OK, "Process terminated").into_response(),
        Err(e) => (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    }
}

async fn handle_action(
    State(state): State<Arc<AppState>>,
    Json(action): Json<ActionRequest>,
) -> impl IntoResponse {
    match action.action.as_str() {
        "clean_memory" => {
            // In a real implementation, this would trigger memory cleanup
            info!("Memory cleanup action triggered");
            (StatusCode::OK, "Memory cleanup initiated").into_response()
        }
        "reboot" => {
            info!("System reboot action triggered");
            // In a real implementation, this would trigger a reboot
            (StatusCode::OK, "Reboot action would be triggered").into_response()
        }
        _ => (StatusCode::BAD_REQUEST, "Unknown action").into_response(),
    }
}
