```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <errno.h>

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void daemonize() {
    pid_t pid = fork();
    if (pid < 0) {
        exit(EXIT_FAILURE);
    }
    if (pid > 0) {
        exit(EXIT_SUCCESS); // Parent exits
    }

    // Child continues
    if (setsid() < 0) { // Create a new session
        exit(EXIT_FAILURE);
    }

    // Fork again to ensure we are not a session leader
    pid = fork();
    if (pid < 0) {
        exit(EXIT_FAILURE);
    }
    if (pid > 0) {
        exit(EXIT_SUCCESS);
    }

    // Set file permissions mask
    umask(0);

    // Change working directory to root
    chdir("/");

    // Close standard file descriptors
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    // Open /dev/null for standard file descriptors
    int fd = open("/dev/null", O_RDWR);
    if (fd != -1) {
        dup2(fd, STDIN_FILENO);
        dup2(fd, STDOUT_FILENO);
        dup2(fd, STDERR_FILENO);
        close(fd);
    }
}

double get_cpu_usage() {
    static long unsigned int prev_idle = 0, prev_non_idle = 0;
    long unsigned int idle, non_idle, total;
    double cpu_usage = 0.0;

    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("Failed to open /proc/stat");
        return -1.0;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return -1.0;
    }
    fclose(fp);

    // Parse the first line which starts with "cpu "
    unsigned long user, nice, system, idle_time, iowait, irq, softirq, steal, guest, guest_nice;
    if (sscanf(line, "cpu %lu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
               &user, &nice, &system, &idle_time, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        return -1.0;
    }

    // Calculate total and idle times
    idle = idle_time + iowait;
    non_idle = user + nice + system + irq + softirq + steal;
    total = idle + non_idle;

    if (prev_idle == 0 && prev_non_idle == 0) {
        // First call, just store values and return 0
        prev_idle = idle;
        prev_non_idle = non_idle;
        return 0.0;
    }

    long unsigned int total_diff = total - (prev_idle + prev_non_idle);
    if (total_diff == 0) {
        return 0.0;
    }

    long unsigned int idle_diff = idle - prev_idle;
    cpu_usage = 100.0 * (total_diff - idle_diff) / total_diff;

    prev_idle = idle;
    prev_non_idle = non_idle;

    return cpu_usage;
}

double get_memory_usage() {
    long total = 0, free = 0, buffers = 0, cached = 0, reclaimable = 0;
    double usage = 0.0;

    FILE *fp = fopen("/proc/meminfo", "r");
    if (!fp) {
        perror("Failed to open /proc/meminfo");
        return -1.0;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "MemTotal:", 9) == 0) {
            sscanf(line, "MemTotal: %ld kB", &total);
        } else if (strncmp(line, "MemFree:", 8) == 0) {
            sscanf(line, "MemFree: %ld kB", &free);
        } else if (strncmp(line, "Buffers:", 8) == 0) {
            sscanf(line, "Buffers: %ld kB", &buffers);
        } else if (strncmp(line, "Cached:", 7) == 0) {
            sscanf(line, "Cached: %ld kB", &cached);
        } else if (strncmp(line, "SReclaimable:", 13) == 0) {
            sscanf(line, "SReclaimable: %ld kB", &reclaimable);
        }
    }
    fclose(fp);

    if (total == 0) {
        return -1.0;
    }

    // Calculate used memory
    long used = total - free - buffers - cached - reclaimable;
    usage = (double)used / total * 100.0;

    return usage;
}

void log_message(const char *message) {
    FILE *log_file = fopen("/var/log/resource_monitor.log", "a");
    if (log_file) {
        time_t now = time(NULL);
        char *time_str = ctime(&now);
        time_str[strlen(time_str) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] %s\n", time_str, message);
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    // Daemonize the process
    daemonize();

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        log_message("Failed to set signal handler for SIGTERM");
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        double cpu_usage = get_cpu_usage();
        double mem_usage = get_memory_usage();

        if (cpu_usage >= 0 && mem_usage >= 0) {
            char log_msg[256];
            snprintf(log_msg, sizeof(log_msg), "CPU Usage: %.2f%%, Memory Usage: %.2f%%", cpu_usage, mem_usage);
            log_message(log_msg);
        } else {
            log_message("Failed to get system resource usage");
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    log_message("Daemon shutting down gracefully");
    return EXIT_SUCCESS;
}
