### **Implementation (`resourced.c`)**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <dirent.h>
#include <sys/sysinfo.h>
#include <sys/resource.h>
#include <sys/time.h>
#include <net/if.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <ifaddrs.h>
#include <errno.h>

#define POLL_INTERVAL_SEC 1
#define LOG_IDENT "resourced"
#define MAX_PROCESSES 1024
#define MAX_IFACE_NAME 16

volatile sig_atomic_t keep_running = 1;

typedef struct {
    unsigned long long user;
    unsigned long long nice;
    unsigned long long system;
    unsigned long long idle;
    unsigned long long iowait;
    unsigned long long irq;
    unsigned long long softirq;
    unsigned long long steal;
    unsigned long long guest;
    unsigned long long total;
} CpuStats;

typedef struct {
    char name[256];
    pid_t pid;
    float cpu_percent;
    unsigned long mem_rss;
    unsigned long mem_vsz;
} ProcessInfo;

typedef struct {
    char iface[MAX_IFACE_NAME];
    unsigned long long rx_bytes;
    unsigned long long tx_bytes;
} NetInterface;

void handle_signal(int sig) {
    keep_running = 0;
    syslog(LOG_INFO, "Received signal %d, shutting down...", sig);
}

void daemonize() {
    pid_t pid, sid;

    // Fork off the parent process
    pid = fork();
    if (pid < 0) {
        exit(EXIT_FAILURE);
    }
    if (pid > 0) {
        exit(EXIT_SUCCESS); // Parent exits
    }

    // Change file mode mask
    umask(0);

    // Create a new SID
    sid = setsid();
    if (sid < 0) {
        exit(EXIT_FAILURE);
    }

    // Change working directory
    if (chdir("/") < 0) {
        exit(EXIT_FAILURE);
    }

    // Close standard file descriptors
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
}

void log_message(const char *msg) {
    syslog(LOG_INFO, "%s", msg);
}

void get_cpu_stats(CpuStats *stats) {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open /proc/stat: %s", strerror(errno));
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "cpu ", 4) == 0) {
            unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest;
            sscanf(line, "cpu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
                   &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest);

            stats->user = user;
            stats->nice = nice;
            stats->system = system;
            stats->idle = idle;
            stats->iowait = iowait;
            stats->irq = irq;
            stats->softirq = softirq;
            stats->steal = steal;
            stats->guest = guest;
            stats->total = user + nice + system + idle + iowait + irq + softirq + steal + guest;
            break;
        }
    }
    fclose(fp);
}

float calculate_cpu_usage(CpuStats *prev, CpuStats *curr) {
    unsigned long long prev_total = prev->total;
    unsigned long long curr_total = curr->total;
    unsigned long long prev_idle = prev->idle + prev->iowait;
    unsigned long long curr_idle = curr->idle + curr->iowait;

    if (curr_total <= prev_total) return 0.0f;

    unsigned long long total_diff = curr_total - prev_total;
    unsigned long long idle_diff = curr_idle - prev_idle;

    return 100.0f * (1.0f - (float)idle_diff / (float)total_diff);
}

void get_memory_stats(unsigned long *total, unsigned long *free, unsigned long *used) {
    struct sysinfo mem_info;
    if (sysinfo(&mem_info) != 0) {
        syslog(LOG_ERR, "sysinfo() failed: %s", strerror(errno));
        return;
    }

    *total = mem_info.totalram * mem_info.mem_unit;
    *free = mem_info.freeram * mem_info.mem_unit;
    *used = *total - (*free + mem_info.bufferram * mem_info.mem_unit);
}

void get_disk_io(unsigned long long *read_bytes, unsigned long long *write_bytes) {
    FILE *fp = fopen("/proc/diskstats", "r");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open /proc/diskstats: %s", strerror(errno));
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strstr(line, "sda") || strstr(line, "nvme")) { // Adjust for your disk
            unsigned int major, minor;
            char device[32];
            unsigned long reads, read_merged, read_sectors, read_time;
            unsigned long writes, write_merged, write_sectors, write_time;

            if (sscanf(line, "%u %u %s %lu %lu %lu %lu %lu %lu %lu %lu",
                       &major, &minor, device,
                       &reads, &read_merged, &read_sectors, &read_time,
                       &writes, &write_merged, &write_sectors, &write_time) == 11) {
                *read_bytes = read_sectors * 512; // Sectors are 512 bytes
                *write_bytes = write_sectors * 512;
                break;
            }
        }
    }
    fclose(fp);
}

void get_network_stats(NetInterface *interfaces, int *count) {
    struct ifaddrs *ifaddr, *ifa;
    if (getifaddrs(&ifaddr) == -1) {
        syslog(LOG_ERR, "getifaddrs() failed: %s", strerror(errno));
        return;
    }

    *count = 0;
    for (ifa = ifaddr; ifa != NULL && *count < MAX_IFACE_NAME; ifa = ifa->ifa_next) {
        if (ifa->ifa_addr == NULL || ifa->ifa_name == NULL) continue;
        if (ifa->ifa_addr->sa_family != AF_PACKET) continue;

        // Skip loopback and non-ethernet interfaces
        if (strncmp(ifa->ifa_name, "lo", 2) == 0) continue;

        strncpy(interfaces[*count].iface, ifa->ifa_name, MAX_IFACE_NAME - 1);
        interfaces[*count].rx_bytes = 0;
        interfaces[*count].tx_bytes = 0;
        (*count)++;
    }

    // Read /proc/net/dev for actual stats
    FILE *fp = fopen("/proc/net/dev", "r");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open /proc/net/dev: %s", strerror(errno));
        freeifaddrs(ifaddr);
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strstr(line, ":") == NULL) continue;

        char iface[16];
        unsigned long long rx_bytes, rx_packets, rx_errs, rx_drop, rx_fifo, rx_frame, rx_compressed, rx_multicast;
        unsigned long long tx_bytes, tx_packets, tx_errs, tx_drop, tx_fifo, tx_colls, tx_carrier, tx_compressed;

        if (sscanf(line, "%15[^:]:%llu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
                   iface, &rx_bytes, &rx_packets, &rx_errs, &rx_drop, &rx_fifo, &rx_frame, &rx_compressed, &rx_multicast,
                   &tx_bytes, &tx_packets, &tx_errs, &tx_drop, &tx_fifo, &tx_colls, &tx_carrier, &tx_compressed) == 17) {

            for (int i = 0; i < *count; i++) {
                if (strcmp(interfaces[i].iface, iface) == 0) {
                    interfaces[i].rx_bytes = rx_bytes;
                    interfaces[i].tx_bytes = tx_bytes;
                    break;
                }
            }
        }
    }
    fclose(fp);
    freeifaddrs(ifaddr);
}

int get_process_list(ProcessInfo *processes, int max_processes) {
    DIR *dir = opendir("/proc");
    if (!dir) {
        syslog(LOG_ERR, "Failed to open /proc: %s", strerror(errno));
        return 0;
    }

    int count = 0;
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL && count < max_processes) {
        if (entry->d_type != DT_DIR) continue;
        if (!isdigit(entry->d_name[0])) continue;

        pid_t pid = atoi(entry->d_name);
        char path[256];
        snprintf(path, sizeof(path), "/proc/%d/stat", pid);
        FILE *fp = fopen(path, "r");
        if (!fp) continue;

        char comm[256], state;
        long utime, stime, cutime, cstime, starttime;
        unsigned long vsize, rss;
        int ppid, pgrp, session, tty_nr, tpgid;
        unsigned flags;
        unsigned long minflt, cminflt, majflt, cmajflt;
        long priority, nice_val, num_threads;
        long itrealvalue;
        unsigned long long starttime_ull;

        if (fscanf(fp, "%*d %255s %c %d %d %d %d %d %lu %lu %ld %ld %ld %ld %llu %lu %ld %ld %ld %ld %lu %lu %ld",
                   comm, &state, &ppid, &pgrp, &session, &tty_nr, &tpgid, &flags, &minflt, &cminflt, &majflt, &cmajflt,
                   &utime, &stime, &cutime, &cstime, &starttime_ull, &vsize, &rss, &priority, &nice_val, &num_threads,
                   &itrealvalue) >= 20) {
            fclose(fp);

            // Get process name (remove parentheses)
            char *name = comm;
            if (name[0] == '(') {
                name = strchr(comm, ')');
                if (name) name++;
                else name = comm;
            }

            // Calculate CPU% (simplified)
            float cpu_percent = (utime + stime) / (float)sysconf(_SC_CLK_TCK) * 100.0f;

            processes[count].pid = pid;
            strncpy(processes[count].name, name, sizeof(processes[count].name) - 1);
            processes[count].cpu_percent = cpu_percent;
            processes[count].mem_rss = rss * sysconf(_SC_PAGESIZE); // Convert pages to bytes
            processes[count].mem_vsz = vsize;
            count++;
        } else {
            fclose(fp);
        }
    }
    closedir(dir);
    return count;
}

int kill_process(pid_t pid) {
    if (kill(pid, SIGTERM) == 0) {
        syslog(LOG_INFO, "Sent SIGTERM to PID %d", pid);
        return 0;
    } else {
        syslog(LOG_ERR, "Failed to kill PID %d: %s", pid, strerror(errno));
        return -1;
    }
}

int set_nice_value(pid_t pid, int nice) {
    if (setpriority(PRIO_PROCESS, pid, nice) == 0) {
        syslog(LOG_INFO, "Set nice value of PID %d to %d", pid, nice);
        return 0;
    } else {
        syslog(LOG_ERR, "Failed to set nice value for PID %d: %s", pid, strerror(errno));
        return -1;
    }
}

void monitor_resources() {
    CpuStats prev_cpu = {0};
    CpuStats curr_cpu = {0};
    get_cpu_stats(&prev_cpu);

    unsigned long mem_total = 0, mem_free = 0, mem_used = 0;
    unsigned long long disk_read = 0, disk_write = 0;
    NetInterface net_interfaces[MAX_IFACE_NAME];
    int net_count = 0;
    get_network_stats(net_interfaces, &net_count);

    char log_msg[1024];
    while (keep_running) {
        sleep(POLL_INTERVAL_SEC);

        // CPU
        get_cpu_stats(&curr_cpu);
        float cpu_usage = calculate_cpu_usage(&prev_cpu, &curr_cpu);
        prev_cpu = curr_cpu;

        // Memory
        get_memory_stats(&mem_total, &mem_free, &mem_used);

        // Disk
        unsigned long long new_disk_read = 0, new_disk_write = 0;
        get_disk_io(&new_disk_read, &new_disk_write);
        unsigned long long disk_read_diff = new_disk_read - disk_read;
        unsigned long long disk_write_diff = new_disk_write - disk_write;
        disk_read = new_disk_read;
        disk_write = new_disk_write;

        // Network
        NetInterface new_net_interfaces[MAX_IFACE_NAME];
        int new_net_count = 0;
        get_network_stats(new_net_interfaces, &new_net_count);

        // Log stats
        snprintf(log_msg, sizeof(log_msg),
                "CPU: %.1f%% | Mem: %lu/%lu KB (used) | Disk: R+%llu W+%llu B/s | Net: ",
                cpu_usage, mem_used / 1024, mem_total / 1024, disk_read_diff, disk_write_diff);

        for (int i = 0; i < new_net_count; i++) {
            for (int j = 0; j < net_count; j++) {
                if (strcmp(net_interfaces[j].iface, new_net_interfaces[i].iface) == 0) {
                    unsigned long long rx_diff = new_net_interfaces[i].rx_bytes - net_interfaces[j].rx_bytes;
                    unsigned long long tx_diff = new_net_interfaces[i].tx_bytes - net_interfaces[j].tx_bytes;
                    char net_buf[64];
                    snprintf(net_buf, sizeof(net_buf), "%s(R+%llu T+%llu) ",
                            new_net_interfaces[i].iface, rx_diff, tx_diff);
                    strncat(log_msg, net_buf, sizeof(log_msg) - strlen(log_msg) - 1);
                    break;
                }
            }
        }

        log_message(log_msg);

        // Optional: Log top processes
        ProcessInfo processes[MAX_PROCESSES];
        int proc_count = get_process_list(processes, MAX_PROCESSES);
        if (proc_count > 0) {
            syslog(LOG_INFO, "Top 5 processes by CPU:");
            for (int i = 0; i < 5 && i < proc_count; i++) {
                syslog(LOG_INFO, "  PID %d (%s): %.1f%% CPU, RSS: %lu KB",
                      processes[i].pid, processes[i].name,
                      processes[i].cpu_percent,
                      processes[i].mem_rss / 1024);
            }
        }
    }
}

int main() {
    // Initialize syslog
    openlog(LOG_IDENT, LOG_PID | LOG_CONS, LOG_DAEMON);
    syslog(LOG_INFO, "Starting resourced daemon...");

    // Set up signal handlers
    signal(SIGTERM, handle_signal);
    signal(SIGINT, handle_signal);

    // Daemonize
    daemonize();
    syslog(LOG_INFO, "Daemonized with PID %d", getpid());

    // Start monitoring
    monitor_resources();

    // Cleanup
    closelog();
    syslog(LOG_INFO, "Daemon stopped.");
    return EXIT_SUCCESS;
}
