#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <errno.h>
#include <stdbool.h>

// Configuration
#define PID_FILE "/var/run/resource_monitor.pid"
#define LOG_FILE "/var/log/resource_monitor.log"
#define MONITOR_INTERVAL 5  // seconds
#define CRITICAL_PROCESSES {"sshd", "cron", NULL}  // NULL-terminated list

// Global variables
volatile sig_atomic_t keep_running = 1;

// Signal handler for graceful shutdown
void handle_signal(int sig) {
    keep_running = 0;
}

// Daemonize the process
void daemonize() {
    pid_t pid, sid;

    // Fork off the parent process
    pid = fork();
    if (pid < 0) {
        exit(EXIT_FAILURE);
    }
    if (pid > 0) {
        exit(EXIT_SUCCESS);  // Parent exits
    }

    // Change the file mode mask
    umask(0);

    // Create a new SID for the child process
    sid = setsid();
    if (sid < 0) {
        exit(EXIT_FAILURE);
    }

    // Change the current working directory
    if ((chdir("/")) < 0) {
        exit(EXIT_FAILURE);
    }

    // Close standard file descriptors
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    // Write PID file
    FILE *pidf = fopen(PID_FILE, "w");
    if (pidf) {
        fprintf(pidf, "%d\n", getpid());
        fclose(pidf);
    }
}

// Log a message with timestamp
void log_message(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE *logf = fopen(LOG_FILE, "a");
    if (logf) {
        fprintf(logf, "[%s] %s\n", timestamp, message);
        fclose(logf);
    }
}

// Get CPU usage (user + system)
float get_cpu_usage() {
    static unsigned long long last_total = 0, last_idle = 0;
    unsigned long long total = 0, idle = 0;
    char line[256];
    FILE *statf = fopen("/proc/stat", "r");
    if (!statf) return 0.0;

    // Read the first line (cpu)
    if (fgets(line, sizeof(line), statf)) {
        unsigned long long user, nice, system, idle_time, iowait, irq, softirq, steal, guest, guest_nice;
        if (sscanf(line, "cpu %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
                   &user, &nice, &system, &idle_time, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) >= 4) {
            total = user + nice + system + idle_time + iowait + irq + softirq + steal;
            idle = idle_time;

            if (last_total != 0) {
                unsigned long long total_diff = total - last_total;
                unsigned long long idle_diff = idle - last_idle;
                if (total_diff > 0) {
                    fclose(statf);
                    last_total = total;
                    last_idle = idle;
                    return 100.0 * (total_diff - idle_diff) / total_diff;
                }
            }
            last_total = total;
            last_idle = idle;
        }
    }
    fclose(statf);
    return 0.0;
}

// Get memory usage (percentage)
float get_memory_usage() {
    char line[256];
    unsigned long total = 0, free = 0, buffers = 0, cached = 0;
    FILE *meminfo = fopen("/proc/meminfo", "r");
    if (!meminfo) return 0.0;

    while (fgets(line, sizeof(line), meminfo)) {
        if (sscanf(line, "MemTotal: %lu kB", &total) == 1) continue;
        if (sscanf(line, "MemFree: %lu kB", &free) == 1) continue;
        if (sscanf(line, "Buffers: %lu kB", &buffers) == 1) continue;
        if (sscanf(line, "Cached: %lu kB", &cached) == 1) break;
    }
    fclose(meminfo);

    if (total > 0) {
        unsigned long used = total - free - buffers - cached;
        return (100.0 * used) / total;
    }
    return 0.0;
}

// Check if a process is running
bool is_process_running(const char *name) {
    char cmd[256];
    snprintf(cmd, sizeof(cmd), "pgrep -x %s > /dev/null", name);
    return system(cmd) == 0;
}

// Start a process (simple version)
void start_process(const char *name) {
    char cmd[256];
    snprintf(cmd, sizeof(cmd), "%s &", name);
    system(cmd);
}

// Monitor critical processes
void monitor_processes() {
    const char *critical_procs[] = CRITICAL_PROCESSES;
    for (int i = 0; critical_procs[i] != NULL; i++) {
        if (!is_process_running(critical_procs[i])) {
            char msg[256];
            snprintf(msg, sizeof(msg), "Critical process '%s' not running. Attempting to restart.", critical_procs[i]);
            log_message(msg);
            start_process(critical_procs[i]);
        }
    }
}

// Main monitoring loop
void monitoring_loop() {
    while (keep_running) {
        float cpu_usage = get_cpu_usage();
        float mem_usage = get_memory_usage();

        char msg[256];
        snprintf(msg, sizeof(msg), "CPU Usage: %.1f%%, Memory Usage: %.1f%%", cpu_usage, mem_usage);
        log_message(msg);

        monitor_processes();

        sleep(MONITOR_INTERVAL);
    }
}

int main() {
    // Set up signal handlers
    signal(SIGTERM, handle_signal);
    signal(SIGHUP, handle_signal);

    // Daemonize
    daemonize();

    log_message("Resource monitor daemon started");

    // Enter monitoring loop
    monitoring_loop();

    log_message("Resource monitor daemon shutting down");
    remove(PID_FILE);
    return EXIT_SUCCESS;
}
