        (metrics.memory_used as f32 / metrics.memory_total as f32) * 100.0,
        metrics.memory_used / 1024 / 1024,
        metrics.memory_total / 1024 / 1024,
        (metrics.disk_used as f32 / metrics.disk_total as f32) * 100.0,
        metrics.disk_used / 1024 / 1024,
        metrics.disk_total / 1024 / 1024,
    );
    axum::response::Response::builder()
        .header("Content-Type", "text/plain")
        .body(body.into())
        .unwrap()
}

async fn update_metrics(state: Arc<Mutex<Metrics>>) {
    let mut system = System::new_all();
    loop {
        tokio::time::sleep(Duration::from_secs(5)).await;
        system.refresh_all();

        let cpu_usage = system.global_cpu_info().cpu_usage();
        let memory_used = system.used_memory();
        let memory_total = system.total_memory();
        let disk = system.disks().first().map(|d| (d.used_space(), d.total_space())).unwrap_or((0, 0));

        let mut metrics = state.lock().unwrap();
        metrics.cpu_usage = cpu_usage;
        metrics.memory_used = memory_used;
        metrics.memory_total = memory_total;
        metrics.disk_used = disk.0;
        metrics.disk_total = disk.1;
    }
}

#[tokio::main]
async fn main() {
    // Initialize logging
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    info!("Starting system resource monitor daemon");

    let state = Arc::new(Mutex::new(Metrics {
        cpu_usage: 0.0,
        memory_used: 0,
        memory_total: 0,
        disk_used: 0,
        disk_total: 0,
    }));

    // Spawn metrics update task
    tokio::spawn(update_metrics(state.clone()));

    // Build HTTP server
    let app = Router::new()
        .route("/metrics", get({
            let state = state.clone();
            move || metrics_handler(state.clone())
        }));

    // Bind to 127.0.0.1:3000
    let listener = tokio::net::TcpListener::bind("127.0.0.1:3000")
        .await
        .expect("Failed to bind to address");
    info!("Listening on {}", listener.local_addr().unwrap());

    // Handle SIGTERM/SIGINT for graceful shutdown
    let signals = Signals::new(&[signal_hook::consts::SIGTERM, signal_hook::consts::SIGINT])
        .expect("Failed to register signals");
    let mut signals_stream = signals.fuse();

    let server = axum::serve(listener, app.into_make_service());

    tokio::select! {
        _ = server => {},
        _ = signals_stream.next() => {
            info!("Received termination signal, shutting down gracefully");
        }
    }
}
