use nix::sys::signal::{self, Signal};
use nix::unistd::{fork, ForkResult, setsid, chdir, umask};
use signal_hook::{iterator::Signals, consts::TERM_SIGNALS};
use std::fs::File;
use std::io::{self, Write};
use std::path::Path;
use std::thread;
use std::time::Duration;
use sysinfo::{System, SystemExt};
use log::{info, error};

/// Daemonize the process (fork, setsid, redirect I/O)
fn daemonize() -> io::Result<()> {
    // Fork the process
    match unsafe { fork() } {
        Ok(ForkResult::Parent { .. }) => std::process::exit(0), // Parent exits
        Ok(ForkResult::Child) => {}                             // Child continues
        Err(e) => return Err(io::Error::new(io::ErrorKind::Other, e)),
    }

    // Create a new session
    setsid().map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;

    // Change working directory to root
    chdir(Path::new("/")).map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;

    // Set file mode creation mask
    umask(0o022);

    // Redirect stdin/stdout/stderr to /dev/null
    File::create("/dev/null")?.into_raw_fd();
    File::create("/dev/null")?.into_raw_fd();
    File::create("/dev/null")?.into_raw_fd();

    Ok(())
}

/// Initialize logging with timestamps
fn setup_logging() -> io::Result<()> {
    env_logger::Builder::from_default_env()
        .format(|buf, record| {
            writeln!(
                buf,
                "{} [{}] - {}",
                chrono::Local::now().format("%Y-%m-%d %H:%M:%S"),
                record.level(),
                record.args()
            )
        })
        .try_init()
        .map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;
    Ok(())
}

/// Monitor system resources (CPU, memory) and log periodically
fn monitor_system(interval_secs: u64) {
    let mut system = System::new_all();
    loop {
        system.refresh_all(); // Update system info

        info!(
            "CPU Usage: {:.2}%, Memory: {:.2}% ({} / {} MB)",
            system.global_cpu_info().cpu_usage(),
            (system.used_memory() as f64 / (1024.0 * 1024.0)),
            system.used_memory() / (1024 * 1024),
            system.total_memory() / (1024 * 1024)
        );

        thread::sleep(Duration::from_secs(interval_secs));
    }
}

fn main() {
    // Initialize logging
    if let Err(e) = setup_logging() {
        eprintln!("Failed to initialize logging: {}", e);
        std::process::exit(1);
    }

    // Daemonize the process
    if let Err(e) = daemonize() {
        error!("Failed to daemonize: {}", e);
        std::process::exit(1);
    }

    info!("System monitor daemon started");

    // Handle termination signals (e.g., SIGTERM)
    let signals = Signals::new(TERM_SIGNALS).expect("Failed to create signal set");
    let signals_handle = signals.handle();

    thread::spawn(move || {
        for signal in signals.forever() {
            info!("Received signal {}, shutting down...", signal);
            signals_handle.close();
            std::process::exit(0);
        }
    });

    // Start monitoring (every 5 seconds)
    monitor_system(5);
}
