use log::{info, error, LevelFilter};
use signal_hook::consts::signal::*;
use signal_hook_tokio::Signals;
use std::time::Duration;
use sysinfo::{System, SystemExt, CpuExt, DiskExt};
use tokio::time;

#[cfg(feature = "http")]
use axum::{
    routing::get,
    Json,
    Router,
    extract::State,
};
#[cfg(feature = "http")]
use serde::Serialize;

#[derive(Debug, Clone)]
struct DaemonState {
    system: System,
}

#[cfg(feature = "http")]
#[derive(Serialize)]
struct SystemMetrics {
    cpu_usage: f32,
    total_memory: u64,
    used_memory: u64,
    disk_usage: Vec<(String, f32)>,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialize logging
    env_logger::builder()
        .filter_level(LevelFilter::Info)
        .init();

    info!("Starting system monitor daemon...");

    // Initialize system monitor
    let mut system = System::new_all();
    system.refresh_all();

    let state = DaemonState { system };

    // Spawn monitoring task
    let monitor_handle = tokio::spawn(monitor_system(state.clone()));

    // Spawn HTTP server (optional)
    #[cfg(feature = "http")]
    let http_handle = tokio::spawn(http_server(state.clone()));

    // Set up signal handling
    let mut signals = Signals::new(&[SIGTERM, SIGINT, SIGQUIT])?;
    let signals_handle = signals.handle();

    tokio::select! {
        _ = signals.recv().fuse() => {
            info!("Received termination signal. Shutting down gracefully...");
        }
        _ = monitor_handle => {
            error!("Monitoring task failed unexpectedly.");
        }
        #[cfg(feature = "http")]
        _ = http_handle => {
            error!("HTTP server failed unexpectedly.");
        }
    }

    // Cleanup
    signals_handle.close();
    info!("Daemon shutdown complete.");
    Ok(())
}

async fn monitor_system(state: DaemonState) {
    let mut interval = time::interval(Duration::from_secs(5));
    loop {
        interval.tick().await;
        let mut system = state.system.clone();
        system.refresh_all();

        // Log system metrics
        log_system_metrics(&system);
    }
}

fn log_system_metrics(system: &System) {
    let cpu_usage = system.global_cpu_info().cpu_usage();
    let total_memory = system.total_memory();
    let used_memory = system.used_memory();

    info!(
        "CPU Usage: {:.1}%, Memory: {}/{} MB ({:.1}% used)",
        cpu_usage,
        used_memory / 1024 / 1024,
        total_memory / 1024 / 1024,
        (used_memory as f64 / total_memory as f64) * 100.0
    );

    // Log disk usage
    for disk in system.disks() {
        info!(
            "Disk {}: {:.1}% used ({} / {} bytes)",
            disk.name().to_string_lossy(),
            disk.usage().total as f64 / disk.total_space() as f64 * 100.0,
            disk.used_space(),
            disk.total_space()
        );
    }
}

#[cfg(feature = "http")]
async fn http_server(state: DaemonState) -> Result<(), Box<dyn std::error::Error>> {
    use axum::http::StatusCode;

    let app = Router::new()
        .route("/metrics", get(get_metrics))
        .with_state(state);

    let listener = tokio::net::TcpListener::bind("127.0.0.1:3000").await?;
    info!("HTTP server listening on http://127.0.0.1:3000");

    axum::serve(listener, app).await?;
    Ok(())
}

#[cfg(feature = "http")]
async fn get_metrics(State(state): State<DaemonState>) -> Result<Json<SystemMetrics>, StatusCode> {
    let mut system = state.system;
    system.refresh_all();

    let cpu_usage = system.global_cpu_info().cpu_usage();
    let total_memory = system.total_memory();
    let used_memory = system.used_memory();

    let disk_usage = system.disks()
        .iter()
        .map(|disk| {
            (
                disk.name().to_string_lossy().into_owned(),
                disk.usage().total as f64 / disk.total_space() as f64 * 100.0,
            )
        })
        .collect();

    Ok(Json(SystemMetrics {
        cpu_usage,
        total_memory,
        used_memory,
        disk_usage,
    }))
}
