use nix::sys::signal::{self, Signal};
use nix::unistd::{fork, ForkResult, setsid, chdir, umask};
use signal_hook::{iterator::Signals, consts::TERM_SIGNALS};
use std::fs::File;
use std::io::{self, Write};
use std::path::Path;
use std::thread;
use std::time::Duration;
use sysinfo::{System, SystemExt};
use log::{info, error};

fn daemonize() -> io::Result<()> {
    // Fork the process
    match unsafe { fork() } {
        Ok(ForkResult::Parent { child, .. }) => {
            // Parent exits, child continues
            std::process::exit(0);
        }
        Ok(ForkResult::Child) => {
            // Child process continues
        }
        Err(e) => {
            return Err(io::Error::new(io::ErrorKind::Other, e));
        }
    }

    // Create a new session
    setsid().map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;

    // Change working directory to root
    chdir(Path::new("/")).map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;

    // Set file mode creation mask
    umask(0o022);

    // Redirect standard I/O to /dev/null
    let _ = File::create("/dev/null")?.into_raw_fd();
    let _ = File::create("/dev/null")?.into_raw_fd();
    let _ = File::create("/dev/null")?.into_raw_fd();

    Ok(())
}

fn setup_logging() -> io::Result<()> {
    // Initialize logger
    env_logger::Builder::from_default_env()
        .format(|buf, record| {
            writeln!(
                buf,
                "{} [{}] - {}",
                chrono::Local::now().format("%Y-%m-%d %H:%M:%S"),
                record.level(),
                record.args()
            )
        })
        .try_init()
        .map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;
    Ok(())
}

fn monitor_system(interval: u64) {
    let mut system = System::new_all();
    loop {
        // Refresh all system information
        system.refresh_all();

        // Log CPU and memory usage
        info!(
            "CPU Usage: {:.2}%, Memory Usage: {:.2}% ({} / {} bytes)",
            system.global_cpu_info().cpu_usage(),
            system.used_memory() as f32 / system.total_memory() as f32 * 100.0,
            system.used_memory(),
            system.total_memory()
        );

        // Sleep for the interval
        thread::sleep(Duration::from_secs(interval));
    }
}

fn main() {
    // Initialize logging
    if let Err(e) = setup_logging() {
        eprintln!("Failed to initialize logging: {}", e);
        std::process::exit(1);
    }

    // Daemonize the process
    if let Err(e) = daemonize() {
        error!("Failed to daemonize: {}", e);
        std::process::exit(1);
    }

    info!("System monitor daemon started");

    // Set up signal handling
    let signals = Signals::new(TERM_SIGNALS).expect("Failed to create signal set");
    let signals_handle = signals.handle();

    // Spawn a thread to handle signals
    thread::spawn(move || {
        for signal in signals.forever() {
            info!("Received signal {}, shutting down...", signal);
            signals_handle.close();
            std::process::exit(0);
        }
    });

    // Start monitoring
    monitor_system(5); // Poll every 5 seconds
}
```

### Explanation:
1. **Daemonization**:
   - The `daemonize` function forks the process, creates a new session, changes the working directory to root, and redirects standard I/O to `/dev/null`.
2. **Logging**:
   - Uses `env_logger` for logging with timestamps and log levels.
3. **Signal Handling**:
   - Uses `signal-hook` to handle termination signals (e.g., SIGTERM) for graceful shutdown.
4. **Monitoring**:
   - Uses the `sysinfo` crate to gather CPU and memory usage metrics.
   - Logs metrics every 5 seconds (configurable).

