# High-Performance Network Flow Analyzer (Gigabit-Scale)

Here's a C++ implementation of a network flow analyzer optimized for gigabit-scale traffic. This code uses libpcap for packet capture and implements efficient flow tracking with periodic expiration.

```cpp
#include <pcap.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <arpa/inet.h>
#include <unordered_map>
#include <ctime>
#include <thread>
#include <mutex>
#include <iostream>
#include <chrono>
#include <atomic>
#include <vector>
#include <algorithm>

// Configuration constants
constexpr uint16_t SNAPSHOT_LENGTH = 65535;  // Maximum packet size to capture
constexpr int PROMISCUOUS_MODE = 1;          // Promiscuous mode
constexpr int TIMEOUT_MS = 1000;             // pcap timeout
constexpr uint32_t FLOW_TIMEOUT_SEC = 60;    // Flow expiration timeout
constexpr uint32_t EXPIRE_CHECK_INTERVAL_SEC = 5; // How often to check for expired flows
constexpr size_t HASH_TABLE_BUCKETS = 1000003; // Prime number for hash table size

// Thread-safe flow key structure
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;

    bool operator==(const FlowKey &other) const {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

// Custom hash function for FlowKey
struct FlowKeyHash {
    size_t operator()(const FlowKey& key) const {
        // FNV-1a hash algorithm
        size_t hash = 2166136261u;
        hash ^= key.src_ip; hash *= 16777619;
        hash ^= key.dst_ip; hash *= 16777619;
        hash ^= key.src_port; hash *= 16777619;
        hash ^= key.dst_port; hash *= 16777619;
        hash ^= key.protocol; hash *= 16777619;
        return hash;
    }
};

// Flow record structure
struct Flow {
    uint64_t bytes;
    uint64_t packets;
    time_t first_seen;
    time_t last_seen;

    Flow() : bytes(0), packets(0), first_seen(0), last_seen(0) {}
    Flow(uint64_t b, uint64_t p, time_t fs, time_t ls)
        : bytes(b), packets(p), first_seen(fs), last_seen(ls) {}
};

// Thread-safe flow table with sharding
class FlowTable {
private:
    struct Shard {
        std::unordered_map<FlowKey, Flow, FlowKeyHash> table;
        std::mutex mutex;
    };

    std::vector<Shard> shards;
    std::atomic<size_t> shard_mask;

public:
    FlowTable(size_t shard_count = 16) : shards(shard_count) {
        shard_mask = shard_count - 1;
    }

    void insert(const FlowKey& key, const Flow& flow) {
        size_t shard_idx = hash_to_shard(key);
        std::lock_guard<std::mutex> lock(shards[shard_idx].mutex);
        shards[shard_idx].table[key] = flow;
    }

    bool update(const FlowKey& key, uint64_t bytes) {
        size_t shard_idx = hash_to_shard(key);
        std::lock_guard<std::mutex> lock(shards[shard_idx].mutex);

        auto& table = shards[shard_idx].table;
        auto it = table.find(key);
        if (it != table.end()) {
            it->second.bytes += bytes;
            it->second.packets++;
            it->second.last_seen = time(nullptr);
            return true;
        }
        return false;
    }

    void remove(const FlowKey& key) {
        size_t shard_idx = hash_to_shard(key);
        std::lock_guard<std::mutex> lock(shards[shard_idx].mutex);
        shards[shard_idx].table.erase(key);
    }

    void export_expired_flows(std::vector<std::pair<FlowKey, Flow>>& expired_flows) {
        time_t now = time(nullptr);
        expired_flows.clear();

        for (auto& shard : shards) {
            std::lock_guard<std::mutex> lock(shard.mutex);
            for (auto it = shard.table.begin(); it != shard.table.end(); ) {
                if (now - it->second.last_seen > FLOW_TIMEOUT_SEC) {
                    expired_flows.emplace_back(it->first, it->second);
                    it = shard.table.erase(it);
                } else {
                    ++it;
                }
            }
        }
    }

private:
    size_t hash_to_shard(const FlowKey& key) const {
        return (FlowKeyHash{}(key)) & shard_mask;
    }
};

// Global flow table
FlowTable flow_table;

// Packet processing function
void process_packet(u_char *user_data, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    // Skip Ethernet header (14 bytes)
    if (pkthdr->len < sizeof(struct ether_header)) return;

    const struct ether_header *eth_header = (const struct ether_header *)packet;
    if (ntohs(eth_header->ether_type) != ETHERTYPE_IP) {
        return; // Not IPv4
    }

    // Skip Ethernet header
    packet += sizeof(struct ether_header);
    const struct ip *ip_header = (const struct ip *)packet;

    // Validate IP header
    if (ip_header->ip_v != 4 || pkthdr->len < sizeof(struct ether_header) + sizeof(struct ip)) {
        return;
    }

    uint16_t ip_total_len = ntohs(ip_header->ip_len);
    uint32_t src_ip = ip_header->ip_src.s_addr;
    uint32_t dst_ip = ip_header->ip_dst.s_addr;
    uint8_t protocol = ip_header->ip_p;

    // Skip IP header (variable length)
    int ip_header_len = ip_header->ip_hl * 4;
    if (ip_header_len < 20 || pkthdr->len < sizeof(struct ether_header) + ip_header_len) {
        return;
    }

    packet += ip_header_len;
    const u_char *transport_header = packet;
    uint16_t src_port = 0, dst_port = 0;

    // Parse transport layer
    if (protocol == IPPROTO_TCP) {
        if (pkthdr->len < sizeof(struct ether_header) + ip_header_len + sizeof(struct tcphdr)) {
            return;
        }
        const struct tcphdr *tcp_header = (const struct tcphdr *)transport_header;
        src_port = ntohs(tcp_header->th_sport);
        dst_port = ntohs(tcp_header->th_dport);
    } else if (protocol == IPPROTO_UDP) {
        if (pkthdr->len < sizeof(struct ether_header) + ip_header_len + sizeof(struct udphdr)) {
            return;
        }
        const struct udphdr *udp_header = (const struct udphdr *)transport_header;
        src_port = ntohs(udp_header->uh_sport);
        dst_port = ntohs(udp_header->uh_dport);
    } else {
        // For other protocols, we'll still track the flow but with ports=0
        src_port = 0;
        dst_port = 0;
    }

    // Create flow key
    FlowKey key;
    key.src_ip = src_ip;
    key.dst_ip = dst_ip;
    key.src_port = src_port;
    key.dst_port = dst_port;
    key.protocol = protocol;

    // Update flow table
    if (!flow_table.update(key, ip_total_len)) {
        time_t now = time(nullptr);
        flow_table.insert(key, Flow(ip_total_len, 1, now, now));
    }
}

// Flow expiration thread
void expire_flows() {
    while (true) {
        std::this_thread::sleep_for(std::chrono::seconds(EXPIRE_CHECK_INTERVAL_SEC));

        std::vector<std::pair<FlowKey, Flow>> expired_flows;
        flow_table.export_expired_flows(expired_flows);

        // Process expired flows (in this example, just print them)
        for (const auto& [key, flow] : expired_flows) {
            char src_ip_str[INET_ADDRSTRLEN], dst_ip_str[INET_ADDRSTRLEN];
            inet_ntop(AF_INET, &key.src_ip, src_ip_str, INET_ADDRSTRLEN);
            inet_ntop(AF_INET, &key.dst_ip, dst_ip_str, INET_ADDRSTRLEN);

            std::cout << "FLOW_EXPORT "
                      << src_ip_str << ":" << key.src_port << " -> "
                      << dst_ip_str << ":" << key.dst_port << " "
                      << "proto=" << (int)key.protocol << " "
                      << "bytes=" << flow.bytes << " "
                      << "packets=" << flow.packets << " "
                      << "duration=" << (flow.last_seen - flow.first_seen) << "s\n";
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <interface>\n";
        std::cerr << "Example: " << argv[0] << " eth0\n";
        return 1;
    }

    char *dev = argv[1];
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle = pcap_open_live(dev, SNAPSHOT_LENGTH, PROMISCUOUS_MODE, TIMEOUT_MS, errbuf);

    if (handle == nullptr) {
        std::cerr << "Couldn't open device " << dev << ": " << errbuf << "\n";
        return 1;
    }

    // Set non-blocking mode for better performance
    if (pcap_setnonblock(handle, 1, errbuf) == -1) {
        std::cerr << "Error setting non-blocking mode: " << errbuf << "\n";
        pcap_close(handle);
        return 1;
    }

    std::cout << "Starting flow analyzer on interface " << dev << "\n";
    std::cout << "Capturing traffic... Press Ctrl+C to stop.\n";

