#define PRINT_INTERVAL 10           // Seconds between flow statistics print

// Flow key structure (5-tuple)
typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;
} flow_key_t;

// Flow entry structure
typedef struct flow_entry {
    flow_key_t key;
    uint64_t bytes;
    uint64_t packets;
    time_t last_seen;
    struct flow_entry *next;  // For hash table chaining
} flow_entry_t;

// Flow table structure
typedef struct {
    flow_entry_t *buckets[FLOW_TABLE_SIZE];
    pthread_mutex_t lock;      // For thread-safe operations
} flow_table_t;

// Global flow table
flow_table_t flow_table;

// Hash function for flow keys
uint32_t hash_flow_key(const flow_key_t *key) {
    uint32_t hash = 5381;
    hash = ((hash << 5) + hash) + key->src_ip;
    hash = ((hash << 5) + hash) + key->dst_ip;
    hash = ((hash << 5) + hash) + key->src_port;
    hash = ((hash << 5) + hash) + key->dst_port;
    hash = ((hash << 5) + hash) + key->protocol;
    return hash;
}

// Initialize flow table
void flow_table_init() {
    memset(&flow_table, 0, sizeof(flow_table));
    pthread_mutex_init(&flow_table.lock, NULL);
}

// Lookup or create a flow entry
flow_entry_t* flow_table_lookup_or_create(const flow_key_t *key) {
    pthread_mutex_lock(&flow_table.lock);

    uint32_t hash = hash_flow_key(key) % FLOW_TABLE_SIZE;
    flow_entry_t *entry = flow_table.buckets[hash];
    flow_entry_t *prev = NULL;

    // Search for existing flow
    while (entry) {
        if (memcmp(&entry->key, key, sizeof(flow_key_t)) == 0) {
            // Check if expired
            if (time(NULL) - entry->last_seen > FLOW_TIMEOUT) {
                // Remove expired entry
                if (prev) {
                    prev->next = entry->next;
                } else {
                    flow_table.buckets[hash] = entry->next;
                }
                free(entry);
                entry = NULL;
            } else {
                // Update last seen time
                entry->last_seen = time(NULL);
                pthread_mutex_unlock(&flow_table.lock);
                return entry;
            }
        }
        prev = entry;
        entry = entry->next;
    }

    // Create new flow entry
    if (entry == NULL) {
        entry = (flow_entry_t*)malloc(sizeof(flow_entry_t));
        if (entry) {
            memcpy(&entry->key, key, sizeof(flow_key_t));
            entry->bytes = 0;
            entry->packets = 0;
            entry->last_seen = time(NULL);
            entry->next = flow_table.buckets[hash];
            flow_table.buckets[hash] = entry;
        }
    }

    pthread_mutex_unlock(&flow_table.lock);
    return entry;
}

