}

// Statistics printer thread
void* stats_printer(void *arg) {
    while (1) {
        sleep(PRINT_INTERVAL);
        print_flow_stats();
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    char *dev = NULL;
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;
    pthread_t stats_thread;

    // Initialize flow table
    flow_table_init();

    // Start statistics printer thread
    pthread_create(&stats_thread, NULL, stats_printer, NULL);

    // Get network device
    dev = pcap_lookupdev(errbuf);
    if (dev == NULL) {
        fprintf(stderr, "Couldn't find default device: %s\n", errbuf);
        return 1;
    }
    printf("Using device: %s\n", dev);

    // Open device for sniffing
    handle = pcap_open_live(dev, BUFSIZ, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Couldn't open device %s: %s\n", dev, errbuf);
        return 1;
    }

    // Set filter to only capture IP traffic
    struct bpf_program fp;
    if (pcap_compile(handle, &fp, "ip", 0, PCAP_NETMASK_UNKNOWN) == -1) {
        fprintf(stderr, "Couldn't parse filter: %s\n", pcap_geterr(handle));
        return 1;
    }
    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "Couldn't install filter: %s\n", pcap_geterr(handle));
        return 1;
    }

    printf("Starting packet capture...\nPress Ctrl+C to stop\n");

    // Start packet capture
    pcap_loop(handle, -1, packet_handler, NULL);

    // Cleanup
    pcap_freecode(&fp);
    pcap_close(handle);
    pthread_cancel(stats_thread);
    pthread_join(stats_thread, NULL);

    return 0;
}
```

## Key Performance Features:

1. **Efficient Flow Tracking**:
   - Uses a hash table with separate chaining for O(1) average case flow lookups
   - Implements lazy flow expiration to avoid periodic scanning overhead

2. **Thread Safety**:
   - Uses mutex locks to protect the shared flow table
   - Includes a separate thread for printing statistics without blocking packet processing

3. **Memory Management**:
   - Dynamically allocates flow entries only when needed
   - Note: For production use, consider a memory pool for even better performance

4. **Packet Processing**:
   - Directly parses packet headers without unnecessary copies
   - Uses network byte order conversions where needed

