# Gigabit-Scale Network Flow Analyzer in C++

```cpp
#include <pcap.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <net/ethernet.h>
#include <arpa/inet.h>
#include <unordered_map>
#include <ctime>
#include <iostream>
#include <iomanip>
#include <signal.h>
#include <atomic>
#include <thread>
#include <mutex>
#include <vector>
#include <algorithm>

// Configuration constants
#define FLOW_TIMEOUT 60          // Seconds before a flow expires
#define SNAPLEN 65535            // Maximum packet size to capture
#define PROMISC 1                // Promiscuous mode
#define TIMEOUT 1000             // Read timeout in ms
#define NUM_SHARDS 16            // Number of flow table shards for concurrency
#define STATS_INTERVAL 10        // Seconds between statistics output

// Flow key structure (5-tuple)
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;

    bool operator==(const FlowKey &other) const {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

// Hash function for FlowKey
struct FlowKeyHash {
    size_t operator()(const FlowKey& key) const {
        // Jenkins one-at-a-time hash
        size_t hash = 0;
        hash += key.src_ip; hash += hash << 10; hash ^= hash >> 6;
        hash += key.dst_ip; hash += hash << 10; hash ^= hash >> 6;
        hash += key.src_port; hash += hash << 10; hash ^= hash >> 6;
        hash += key.dst_port; hash += hash << 10; hash ^= hash >> 6;
        hash += key.protocol; hash += hash << 10; hash ^= hash >> 6;
        return hash;
    }
};

// Flow statistics
struct FlowStats {
    uint64_t bytes;
    uint64_t packets;
    time_t last_seen;
};

// Global state
std::atomic<bool> keep_running(true);
std::vector<std::unordered_map<FlowKey, FlowStats, FlowKeyHash>> flow_table_shards(NUM_SHARDS);
std::vector<std::mutex> flow_table_mutexes(NUM_SHARDS);
pcap_t* global_handle = nullptr;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    keep_running = false;
    if (global_handle) {
        pcap_breakloop(global_handle);
    }
}

// Flow cleanup thread function
void cleanup_flows() {
    while (keep_running) {
        std::this_thread::sleep_for(std::chrono::seconds(STATS_INTERVAL));

        time_t now = time(nullptr);
        uint64_t total_flows = 0;
        uint64_t total_bytes = 0;
        uint64_t total_packets = 0;
        std::vector<std::pair<FlowKey, FlowStats>> top_flows;

        // Collect statistics from all shards
        for (int i = 0; i < NUM_SHARDS; ++i) {
            std::lock_guard<std::mutex> lock(flow_table_mutexes[i]);
            auto& shard = flow_table_shards[i];

            // Clean up expired flows
            for (auto it = shard.begin(); it != shard.end(); ) {
                if (now - it->second.last_seen > FLOW_TIMEOUT) {
                    it = shard.erase(it);
                } else {
                    total_flows++;
                    total_bytes += it->second.bytes;
                    total_packets += it->second.packets;

                    // Track top flows by byte count
                    if (top_flows.size() < 10 || it->second.bytes > top_flows.back().second.bytes) {
                        top_flows.emplace_back(it->first, it->second);
                        std::push_heap(top_flows.begin(), top_flows.end(),
                            [](const auto& a, const auto& b) {
                                return a.second.bytes < b.second.bytes;
                            });
                        if (top_flows.size() > 10) {
                            std::pop_heap(top_flows.begin(), top_flows.end(),
                                [](const auto& a, const auto& b) {
                                    return a.second.bytes < b.second.bytes;
                                });
                            top_flows.pop_back();
                        }
                    }
                    ++it;
                }
            }
        }

        // Print statistics
        std::cout << "\n[" << std::put_time(std::localtime(&now), "%Y-%m-%d %H:%M:%S")
                  << "] Flow Statistics:\n";
        std::cout << "  Active flows: " << total_flows << "\n";
        std::cout << "  Total bytes: " << total_bytes << "\n";
        std::cout << "  Total packets: " << total_packets << "\n";

        if (!top_flows.empty()) {
            std::cout << "\nTop 10 flows by byte count:\n";
            std::cout << "  SRC_IP:PORT -> DST_IP:PORT | BYTES | PACKETS\n";
            for (const auto& flow : top_flows) {
                char src_ip[INET_ADDRSTRLEN], dst_ip[INET_ADDRSTRLEN];
                inet_ntop(AF_INET, &flow.first.src_ip, src_ip, sizeof(src_ip));
                inet_ntop(AF_INET, &flow.first.dst_ip, dst_ip, sizeof(dst_ip));

                std::cout << "  " << src_ip << ":" << ntohs(flow.first.src_port)
                          << " -> " << dst_ip << ":" << ntohs(flow.first.dst_port)
                          << " | " << flow.second.bytes
                          << " | " << flow.second.packets << "\n";
            }
        }
        std::cout << std::endl;
    }
}

// Packet processing function
void process_packet(u_char* user_data, const struct pcap_pkthdr* pkthdr, const u_char* packet) {
    // Skip non-Ethernet packets for simplicity
    if (pkthdr->len < sizeof(struct ether_header) + sizeof(struct ip)) {
        return;
    }

    // Parse Ethernet header
    const struct ether_header* eth_header = (struct ether_header*)packet;
    if (ntohs(eth_header->ether_type) != ETHERTYPE_IP) {
        return; // Not IPv4
    }

    // Parse IP header
    const struct ip* ip_header = (struct ip*)(packet + sizeof(struct ether_header));
    if (ip_header->ip_v != 4) {
        return; // Not IPv4
    }

    int ip_header_len = ip_header->ip_hl * 4;
    if (ip_header_len < 20 || pkthdr->len < sizeof(struct ether_header) + ip_header_len) {
        return; // Invalid IP header
    }

    uint32_t src_ip = ip_header->ip_src.s_addr;
    uint32_t dst_ip = ip_header->ip_dst.s_addr;
    uint8_t protocol = ip_header->ip_p;
    uint16_t src_port = 0, dst_port = 0;

    // Parse transport layer (TCP/UDP)
    if (protocol == IPPROTO_TCP && pkthdr->len >= sizeof(struct ether_header) + ip_header_len + sizeof(struct tcphdr)) {
        const struct tcphdr* tcp_header = (struct tcphdr*)(packet + sizeof(struct ether_header) + ip_header_len);
        src_port = ntohs(tcp_header->th_sport);
        dst_port = ntohs(tcp_header->th_dport);
    } else if (protocol == IPPROTO_UDP && pkthdr->len >= sizeof(struct ether_header) + ip_header_len + sizeof(struct udphdr)) {
        const struct udphdr* udp_header = (struct udphdr*)(packet + sizeof(struct ether_header) + ip_header_len);
        src_port = ntohs(udp_header->uh_sport);
        dst_port = ntohs(udp_header->uh_dport);
    } else {
        return; // Not TCP/UDP
    }

    // Create flow key
    FlowKey key;
    key.src_ip = src_ip;
    key.dst_ip = dst_ip;
    key.src_port = src_port;
    key.dst_port = dst_port;
    key.protocol = protocol;

    // Determine shard and update flow table
    size_t shard_index = FlowKeyHash()(key) % NUM_SHARDS;
    std::lock_guard<std::mutex> lock(flow_table_mutexes[shard_index]);
    auto& shard = flow_table_shards[shard_index];

    auto it = shard.find(key);
    if (it != shard.end()) {
        // Update existing flow
        it->second.bytes += pkthdr->len;
        it->second.packets += 1;
        it->second.last_seen = time(nullptr);
    } else {
        // Create new flow entry
        FlowStats stats;
        stats.bytes = pkthdr->len;
        stats.packets = 1;
        stats.last_seen = time(nullptr);
        shard[key] = stats;
    }
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <interface>\n";
        return 1;
    }

    char errbuf[PCAP_ERRBUF_SIZE];
    const char* dev = argv[1];

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open network device
    global_handle = pcap_open_live(dev, SNAPLEN, PROMISC, TIMEOUT, errbuf);
    if (global_handle == nullptr) {
        std::cerr << "Error opening interface " << dev << ": " << errbuf << "\n";
        return 1;
    }

    // Set BPF filter to capture only IP traffic
    struct bpf_program fp;
    if (pcap_compile(global_handle, &fp, "ip", 0, PCAP_NETMASK_UNKNOWN) == -1) {
        std::cerr << "Couldn't parse filter: " << pcap_geterr(global_handle) << "\n";
        pcap_close(global_handle);
        return 1;
    }
    if (pcap_setfilter(global_handle, &fp) == -1) {
        std::cerr << "Couldn't install filter: " << pcap_geterr(global_handle) << "\n";
        pcap_freecode(&fp);
        pcap_close(global_handle);
        return 1;
    }
    pcap_freecode(&fp);

    std::cout << "Starting flow analyzer on interface " << dev
              << " (Ctrl+C to stop)...\n";

    // Start cleanup thread
    std::thread cleanup_thread(cleanup_flows);

    // Main packet capture loop
    if (pcap_loop(global_handle, 0, process_packet, nullptr) == -1) {
        std::cerr << "Error in pcap_loop: " << pcap_geterr(global_handle) << "\n";
    }

    // Cleanup
    keep_running = false;
    cleanup_thread.join();
    pcap_close(global_handle);

    return 0;
}
```

