# Gigabit-Scale Network Flow Analyzer in C

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <pcap.h>
#include <netinet/if_ether.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <signal.h>
#include <stdatomic.h>

// Configuration
#define MAX_FLOWS 1000000       // Maximum concurrent flows
#define FLOW_TIMEOUT 60         // Seconds before idle flow expires
#define BATCH_SIZE 64           // Packets to process in each batch
#define HASH_TABLE_SIZE 1048576 // Power of 2 for fast modulo
#define SNAPLEN 65535           // Max packet size to capture

// Flow 5-tuple
typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;
} flow_key_t;

// Flow state
typedef struct flow {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    time_t last_seen;
    struct flow *next; // For hash table chaining
} flow_t;

// Global state
typedef struct {
    flow_t *flows[MAX_FLOWS];
    pthread_mutex_t lock;
    atomic_uint_fast64_t total_packets;
    atomic_uint_fast64_t total_bytes;
    atomic_uint_fast64_t active_flows;
    time_t start_time;
} flow_table_t;

flow_table_t flow_table;
volatile sig_atomic_t keep_running = 1;

// Signal handler for clean shutdown
void handle_signal(int sig) {
    keep_running = 0;
}

// Hash function for flow key
uint32_t flow_hash(const flow_key_t *key) {
    uint32_t hash = key->src_ip;
    hash = (hash << 5) + hash + key->dst_ip;
    hash = (hash << 5) + hash + key->src_port;
    hash = (hash << 5) + hash + key->dst_port;
    hash = (hash << 5) + hash + key->protocol;
    return hash % HASH_TABLE_SIZE;
}

// Initialize flow table
void init_flow_table() {
    memset(&flow_table, 0, sizeof(flow_table));
    pthread_mutex_init(&flow_table.lock, NULL);
    flow_table.start_time = time(NULL);
}

// Cleanup expired flows
void cleanup_expired_flows() {
    time_t now = time(NULL);
    uint64_t expired = 0;

    pthread_mutex_lock(&flow_table.lock);

    for (int i = 0; i < MAX_FLOWS; i++) {
        flow_t **prev = &flow_table.flows[i];
        flow_t *curr = flow_table.flows[i];

        while (curr != NULL) {
            if (now - curr->last_seen > FLOW_TIMEOUT) {
                flow_t *to_free = curr;
                *prev = curr->next;
                free(to_free);
                expired++;
                flow_table.active_flows--;
            } else {
                prev = &curr->next;
                curr = curr->next;
            }
        }
    }

    pthread_mutex_unlock(&flow_table.lock);
    atomic_fetch_add(&flow_table.total_packets, expired);
}

// Process a single packet
void process_packet(const u_char *packet, struct pcap_pkthdr *header) {
    struct ether_header *eth = (struct ether_header *)packet;
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) {
        return;
    }

    struct ip *ip = (struct ip *)(packet + sizeof(struct ether_header));
    if (ip->ip_v != 4) {
        return;
    }

    flow_key_t key;
    key.src_ip = ip->ip_src.s_addr;
    key.dst_ip = ip->ip_dst.s_addr;
    key.protocol = ip->ip_p;

    uint16_t payload_len = ntohs(ip->ip_len) - (ip->ip_hl << 2);

    if (ip->ip_p == IPPROTO_TCP) {
        struct tcphdr *tcp = (struct tcphdr *)(packet + sizeof(struct ether_header) + (ip->ip_hl << 2));
        key.src_port = tcp->th_sport;
        key.dst_port = tcp->th_dport;
    } else if (ip->ip_p == IPPROTO_UDP) {
        struct udphdr *udp = (struct udphdr *)(packet + sizeof(struct ether_header) + (ip->ip_hl << 2));
        key.src_port = udp->uh_sport;
        key.dst_port = udp->uh_dport;
    } else {
        // Non-TCP/UDP protocols - use 0 for ports
        key.src_port = 0;
        key.dst_port = 0;
    }

    // Lookup or create flow
    uint32_t hash = flow_hash(&key);
    flow_t *flow = NULL;
    flow_t *prev = NULL;

    pthread_mutex_lock(&flow_table.lock);

    flow = flow_table.flows[hash];
    while (flow != NULL) {
        if (flow->key.src_ip == key.src_ip &&
            flow->key.dst_ip == key.dst_ip &&
            flow->key.src_port == key.src_port &&
            flow->key.dst_port == key.dst_port &&
            flow->key.protocol == key.protocol) {
            break;
        }
        prev = flow;
        flow = flow->next;
    }

    if (flow == NULL) {
        // Create new flow
        flow = malloc(sizeof(flow_t));
        if (flow == NULL) {
            pthread_mutex_unlock(&flow_table.lock);
            return;
        }
        memset(flow, 0, sizeof(flow_t));
        flow->key = key;
        flow->last_seen = time(NULL);
        flow->next = NULL;

        if (prev == NULL) {
            flow_table.flows[hash] = flow;
        } else {
            prev->next = flow;
        }
        flow_table.active_flows++;
    } else {
        // Update existing flow
        flow->last_seen = time(NULL);
    }

    // Update statistics
    flow->packets++;
    flow->bytes += payload_len;
    atomic_fetch_add(&flow_table.total_packets, 1);
    atomic_fetch_add(&flow_table.total_bytes, payload_len);

    pthread_mutex_unlock(&flow_table.lock);
}

// Packet processing callback
void packet_handler(u_char *user_data, const struct pcap_pkthdr *header, const u_char *packet) {
    if (!keep_running) return;

    // Process in batches for better performance
    static u_char *batch[BATCH_SIZE];
    static int batch_count = 0;
    static struct pcap_pkthdr *batch_headers[BATCH_SIZE];

    batch[batch_count] = (u_char *)packet;
    batch_headers[batch_count] = (struct pcap_pkthdr *)header;
    batch_count++;

    if (batch_count >= BATCH_SIZE) {
        for (int i = 0; i < batch_count; i++) {
            process_packet(batch[i], batch_headers[i]);
        }
        batch_count = 0;
    }
}

// Expiration thread
void *expiration_thread(void *arg) {
    while (keep_running) {
        sleep(1); // Check every second
        cleanup_expired_flows();
    }
    return NULL;
}

// Print statistics
void print_stats() {
    time_t now = time(NULL);
    double duration = difftime(now, flow_table.start_time);
    uint64_t total_packets = atomic_load(&flow_table.total_packets);
    uint64_t total_bytes = atomic_load(&flow_table.total_bytes);
    uint64_t active_flows = atomic_load(&flow_table.active_flows);

    printf("\n--- Flow Statistics ---\n");
    printf("Uptime: %.0f seconds\n", duration);
    printf("Total packets: %lu\n", total_packets);
    printf("Total bytes: %lu\n", total_bytes);
    printf("Packet rate: %.2f pps\n", total_packets / duration);
    printf("Byte rate: %.2f Mbps\n", (total_bytes * 8.0) / (duration * 1000000.0));
    printf("Active flows: %lu\n", active_flows);
    printf("Flows/sec: %.2f\n", active_flows / duration);
    printf("------------------------\n");
}

// Main function
int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    char *dev = argv[1];
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;

    // Initialize flow table
    init_flow_table();

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Start expiration thread
    pthread_t exp_thread;
    pthread_create(&exp_thread, NULL, expiration_thread, NULL);

    // Open capture device
    handle = pcap_open_live(dev, SNAPLEN, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Couldn't open device %s: %s\n", dev, errbuf);
        return 1;
    }

    // Set non-blocking mode for better performance
    if (pcap_setnonblock(handle, 1, errbuf) == -1) {
        fprintf(stderr, "Couldn't set non-blocking mode: %s\n", errbuf);
        pcap_close(handle);
        return 1;
    }

    printf("Starting flow analyzer on %s...\n", dev);
    printf("Press Ctrl+C to stop\n");

    // Main capture loop
    while (keep_running) {
        int ret = pcap_dispatch(handle, 0, packet_handler, NULL);
        if (ret < 0) {
            fprintf(stderr, "Error in pcap_dispatch: %s\n", pcap_geterr(handle));
            break;
        }

        // Print stats periodically
        static time_t last_stats = 0;
        time_t now = time(NULL);
        if (now - last_stats >= 5) {
            print_stats();
            last_stats = now;
        }
    }

    // Process remaining packets in batch
    if (batch_count > 0) {
        for (int i = 0; i < batch_count; i++) {
            process_packet(batch[i], batch_headers[i]);
        }
    }

    // Clean up
    pcap_close(handle);
    pthread_join(exp_thread, NULL);
    print_stats();

    // Free all flows
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        flow_t *curr = flow_table.flows[i];
        while (curr != NULL) {
            flow_t *to_free = curr;
            curr = curr->next;
            free(to_free);
        }
    }

    pthread_mutex_destroy(&flow_table.lock);
    return 0;
}
```

## Compilation and Usage

To compile this code (requires libpcap):

```bash
gcc -O3 -pthread -o flow_analyzer flow_analyzer.c -lpcap
```

Run it on your network interface (replace `eth0` with your interface):

```bash
sudo ./flow_analyzer eth0
```

## Key Performance Features

1. **Batch Processing**: Processes packets in batches (64 at a time) to reduce per-packet overhead
2. **Lock-Free Statistics**: Uses atomic operations for counters accessed from multiple threads
3. **Efficient Hash Table**: Custom hash function with power-of-2 size for fast modulo
4. **Flow Expiration**: Separate thread handles flow cleanup to prevent memory bloat
5. **Minimal Memory Allocation**: Only allocates new flow structures when needed
6. **Non-Blocking Capture**: Uses libpcap's non-blocking mode for better throughput

## Limitations

This is a simplified version. A production implementation would need:

1. **DPDK or AF_XDP** for true line-rate capture at 1Gbps+
2. **More sophisticated flow expiration** (TCP FIN/RST detection)
3. **Better memory management** (object pools for flows)
4. **Flow export** (NetFlow/IPFIX/sFlow)
5. **More detailed protocol parsing**
6. **Proper error handling and logging**

For true gigabit performance, you would need to replace libpcap with a DPDK-based solution that bypasses the kernel networking stack entirely.

