#define TX_RING_SIZE 1024
#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250
#define BURST_SIZE 32
#define FLOW_TIMEOUT 60  // seconds
#define HASH_TABLE_SIZE 1 << 20  // 1M entries

// Flow key structure (5-tuple)
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;

    bool operator==(const FlowKey &other) const {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

// Hash function for FlowKey
namespace std {
    template<>
    struct hash<FlowKey> {
        size_t operator()(const FlowKey& key) const {
            size_t h = 0;
            h ^= hash<uint32_t>()(key.src_ip) + 0x9e3779b9 + (h << 6) + (h >> 2);
            h ^= hash<uint32_t>()(key.dst_ip) + 0x9e3779b9 + (h << 6) + (h >> 2);
            h ^= hash<uint16_t>()(key.src_port) + 0x9e3779b9 + (h << 6) + (h >> 2);
            h ^= hash<uint16_t>()(key.dst_port) + 0x9e3779b9 + (h << 6) + (h >> 2);
            h ^= hash<uint8_t>()(key.protocol) + 0x9e3779b9 + (h << 6) + (h >> 2);
            return h;
        }
    };
}

// Flow statistics
struct FlowStats {
    uint64_t bytes;
    uint64_t packets;
    uint64_t first_seen;
    uint64_t last_seen;
};

// Flow table using hash map with custom allocator for performance
class FlowTable {
private:
    std::unordered_map<FlowKey, FlowStats> table;
    std::mutex mutex;  // For thread safety (simplified for example)

public:
    void update(const FlowKey& key, uint32_t pkt_len) {
        auto now = rte_rdtsc();
        std::lock_guard<std::mutex> lock(mutex);

        auto it = table.find(key);
        if (it != table.end()) {
            // Update existing flow
            it->second.bytes += pkt_len;
            it->second.packets++;
            it->second.last_seen = now;
        } else {
            // Create new flow
            FlowStats stats = {pkt_len, 1, now, now};
            table[key] = stats;
        }
    }

    void expire_flows() {
        auto now = rte_rdtsc();
        std::lock_guard<std::mutex> lock(mutex);

        for (auto it = table.begin(); it != table.end(); ) {
            if ((now - it->second.last_seen) > (FLOW_TIMEOUT * rte_get_tsc_hz())) {
                it = table.erase(it);
            } else {
                ++it;
            }
        }
    }

    void print_stats() {
        std::lock_guard<std::mutex> lock(mutex);
        std::cout << "Active flows: " << table.size() << std::endl;
    }
};

// Packet processing function
static inline void process_packet(struct rte_mbuf *m, FlowTable& flow_table) {
    // Parse Ethernet header
    struct rte_ether_hdr *eth = rte_pktmbuf_mtod(m, struct rte_ether_hdr *);
    if (eth->ether_type != rte_cpu_to_be_16(RTE_ETHER_TYPE_IPV4)) {
        return;
    }

    // Parse IP header
    struct rte_ipv4_hdr *ip = (struct rte_ipv4_hdr *)(eth + 1);
    uint32_t ip_len = rte_be_to_cpu_16(ip->total_length);

    // Parse transport header
    struct FlowKey key;
    key.src_ip = ip->src_addr;
    key.dst_ip = ip->dst_addr;
    key.protocol = ip->next_proto_id;

    if (ip->next_proto_id == IPPROTO_TCP) {
        struct rte_tcp_hdr *tcp = (struct rte_tcp_hdr *)(ip + 1);
        key.src_port = tcp->src_port;
        key.dst_port = tcp->dst_port;
    } else if (ip->next_proto_id == IPPROTO_UDP) {
        struct rte_udp_hdr *udp = (struct rte_udp_hdr *)(ip + 1);
        key.src_port = udp->src_port;
        key.dst_port = udp->dst_port;
    } else {
        return;  // Unsupported protocol
    }

    // Update flow statistics
    flow_table.update(key, rte_pktmbuf_pkt_len(m));
}

// Main packet processing loop
void run_flow_analyzer(uint16_t port_id, FlowTable& flow_table) {
    struct rte_mbuf *bufs[BURST_SIZE];
    const uint16_t nb_rx_desc = RX_RING_SIZE;
    const uint16_t nb_tx_desc = TX_RING_SIZE;
    uint64_t prev_tsc = 0, cur_tsc, diff_tsc;
    const uint64_t drain_tsc = (rte_get_tsc_hz() + US_PER_S - 1) / US_PER_S * 1000; // 1ms

    std::cout << "Starting flow analyzer on port " << port_id << std::endl;

    while (true) {
        cur_tsc = rte_rdtsc();

        // Periodically expire old flows (every 100ms)
        diff_tsc = cur_tsc - prev_tsc;
        if (unlikely(diff_tsc > drain_tsc)) {
            flow_table.expire_flows();
            prev_tsc = cur_tsc;
        }

        // Receive burst of packets
        const uint16_t nb_rx = rte_eth_rx_burst(port_id, 0, bufs, BURST_SIZE);
        if (unlikely(nb_rx == 0)) {
            continue;
        }

        // Process each packet in the burst
        for (uint16_t i = 0; i < nb_rx; i++) {
            process_packet(bufs[i], flow_table);
            rte_pktmbuf_free(bufs[i]);
        }
    }
}

