               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

// Hash function for FlowKey
struct FlowKeyHash {
    size_t operator()(const FlowKey &key) const {
        // Jenkins one-at-a-time hash
        size_t hash = 0;
        hash += key.src_ip; hash += hash << 12; hash ^= hash >> 22;
        hash += key.dst_ip; hash += hash << 12; hash ^= hash >> 22;
        hash += key.src_port; hash += hash << 12; hash ^= hash >> 22;
        hash += key.dst_port; hash += hash << 12; hash ^= hash >> 22;
        hash += key.protocol; hash += hash << 12; hash ^= hash >> 22;
        return hash;
    }
};

// Flow record structure
