    PerCoreFlowTable(uint32_t id) : last_cleanup_time(0), core_id(id) {}

    FlowRecord* getOrCreateFlow(const FlowKey& key) {
        std::lock_guard<std::mutex> lock(mutex);

        auto it = flow_map.find(key);
