        FlowRecord* record = new FlowRecord();
        record->first_timestamp = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
        record->last_timestamp = record->first_timestamp;
        record->ref_count = 1;

        flow_map[key] = record;
        return record;
