               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

// High-performance hash function for FlowKey
namespace std {
    template <>
    struct hash<FlowKey> {
        size_t operator()(const FlowKey& key) const {
            // FNV-1a hash for better distribution
            size_t hash = 2166136261u;
            hash ^= key.src_ip; hash *= 16777619;
            hash ^= key.dst_ip; hash *= 16777619;
            hash ^= key.src_port; hash *= 16777619;
            hash ^= key.dst_port; hash *= 16777619;
            hash ^= key.protocol; hash *= 16777619;
            return hash;
        }
    };
