// Process a single packet and update flow table
void process_packet(struct rte_mbuf *m) {
    // Parse Ethernet header
    struct rte_ether_hdr *eth_hdr = rte_pktmbuf_mtod(m, struct rte_ether_hdr *);
    if (rte_be_to_cpu_16(eth_hdr->ether_type) != RTE_ETHER_TYPE_IPV4) {
        return; // Skip non-IPv4 packets
    }

    // Parse IP header
    struct rte_ipv4_hdr *ip_hdr = rte_pktmbuf_mtod_offset(
        m, struct rte_ipv4_hdr *, sizeof(struct rte_ether_hdr));
    uint32_t src_ip = rte_be_to_cpu_32(ip_hdr->src_addr);
    uint32_t dst_ip = rte_be_to_cpu_32(ip_hdr->dst_addr);
    uint8_t protocol = ip_hdr->next_proto_id;

    FlowKey key;
    key.src_ip = src_ip;
    key.dst_ip = dst_ip;
    key.protocol = protocol;

    // Parse transport layer (TCP/UDP only)
    if (protocol == IPPROTO_TCP) {
        struct rte_tcp_hdr *tcp_hdr = rte_pktmbuf_mtod_offset(
            m, struct rte_tcp_hdr *, sizeof(struct rte_ether_hdr) + sizeof(struct rte_ipv4_hdr));
        key.src_port = rte_be_to_cpu_16(tcp_hdr->src_port);
        key.dst_port = rte_be_to_cpu_16(tcp_hdr->dst_port);
    } else if (protocol == IPPROTO_UDP) {
        struct rte_udp_hdr *udp_hdr = rte_pktmbuf_mtod_offset(
            m, struct rte_udp_hdr *, sizeof(struct rte_ether_hdr) + sizeof(struct rte_ipv4_hdr));
        key.src_port = rte_be_to_cpu_16(udp_hdr->src_port);
        key.dst_port = rte_be_to_cpu_16(udp_hdr->dst_port);
    } else {
        return; // Skip non-TCP/UDP packets
    }

    // Update flow table (thread-safe)
    std::lock_guard<std::mutex> lock(flow_table_mutex);
    auto &entry = flow_table[key];
    entry.bytes += m->pkt_len;
    entry.packets++;
    entry.last_seen = rte_rdtsc();
    if (entry.packets == 1) {
        entry.first_seen = entry.last_seen;
    }
