        char src_ip[INET_ADDRSTRLEN], dst_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &key.src_ip, src_ip, INET_ADDRSTRLEN);
        inet_ntop(AF_INET, &key.dst_ip, dst_ip, INET_ADDRSTRLEN);

        uint64_t duration_ms = (entry.last_seen - entry.first_seen) / (hz / 1000);
        std::cout << std::left
                  << std::setw(20) << src_ip
                  << std::setw(20) << dst_ip
                  << std::setw(8) << (int)key.protocol
                  << std::setw(10) << key.src_port
                  << std::setw(10) << key.dst_port
                  << std::setw(15) << entry.bytes
                  << std::setw(15) << entry.packets
                  << duration_ms << "\n";
    }
}

int main(int argc, char **argv) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize EAL (DPDK Environment Abstraction Layer)
    int ret = rte_eal_init(argc, argv);
    if (ret < 0) {
        rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");
    }

    // Parse port number from command line
    if (argc < 2) {
        rte_exit(EXIT_FAILURE, "Usage: %s <port_id>\n", argv[0]);
    }
    uint16_t port_id = std::stoi(argv[1]);

    // Configure the Ethernet port
    struct rte_eth_conf port_conf = {};
    port_conf.rxmode.mq_mode = ETH_MQ_RX_RSS;
    port_conf.rxmode.max_rx_pkt_len = RTE_ETHER_MAX_LEN;
    port_conf.rxmode.offloads = DEV_RX_OFFLOAD_CHECKSUM;

    if (rte_eth_dev_configure(port_id, 1, 1, &port_conf) < 0) {
        rte_exit(EXIT_FAILURE, "Cannot configure port %" PRIu16 "\n", port_id);
    }

    // Create memory pool for packet buffers
    struct rte_mempool *mbuf_pool = rte_pktmbuf_pool_create(
        "MBUF_POOL", 4096, 0, 0,
        RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id());
    if (mbuf_pool == NULL) {
        rte_exit(EXIT_FAILURE, "Cannot create mbuf pool\n");
    }

    // Setup RX queue
    if (rte_eth_rx_queue_setup(port_id, 0, 1024,
        rte_eth_dev_socket_id(port_id), NULL, mbuf_pool) < 0) {
        rte_exit(EXIT_FAILURE, "Cannot setup RX queue\n");
    }

    // Start the port
    if (rte_eth_dev_start(port_id) < 0) {
        rte_exit(EXIT_FAILURE, "Cannot start port %" PRIu16 "\n", port_id);
    }

    std::cout << "Network Flow Analyser started on port " << port_id
              << " (Press Ctrl+C to stop)\n";

    // Main processing loop
    uint64_t prev_tsc = rte_rdtsc();
    uint64_t hz = rte_get_tsc_hz();
    uint64_t stats_interval = hz; // Print stats every 1 second

    while (!force_quit) {
        struct rte_mbuf *bufs[32];
        uint16_t nb_rx = rte_eth_rx_burst(port_id, 0, bufs, 32);

        for (uint16_t i = 0; i < nb_rx; i++) {
            process_packet(bufs[i]);
            rte_pktmbuf_free(bufs[i]);
        }

        // Periodically print statistics
        uint64_t cur_tsc = rte_rdtsc();
        if (cur_tsc - prev_tsc >= stats_interval) {
            print_stats();
            prev_tsc = cur_tsc;
        }
    }

    // Cleanup
    rte_eth_dev_stop(port_id);
    rte_eth_dev_close(port_id);
    return 0;
}
