static inline uint32_t
flow_hash(const flow_key_t *key, uint32_t size)
{
    // Simple hash function - in production consider MurmurHash or similar
    uint32_t hash = 0;
    hash = ((hash << 5) + hash) + key->src_ip;
    hash = ((hash << 5) + hash) + key->dst_ip;
    hash = ((hash << 5) + hash) + key->src_port;
    hash = ((hash << 5) + hash) + key->dst_port;
    hash = ((hash << 5) + hash) + key->protocol;
    return hash % size;
}

flow_table_t*
flow_table_create(uint32_t size)
{
    flow_table_t *table = malloc(sizeof(flow_table_t));
    if (!table) return NULL;

    table->entries = calloc(size, sizeof(flow_entry_t));
    if (!table->entries) {
        free(table);
        return NULL;
    }

    table->size = size;
    table->count = 0;
    table->active_count = 0;

    return table;
}

void
flow_table_destroy(flow_table_t *table)
{
    if (table) {
        free(table->entries);
        free(table);
    }
}

flow_entry_t*
flow_table_lookup(flow_table_t *table, const flow_key_t *key)
{
    uint32_t idx = flow_hash(key, table->size);
    uint32_t start_idx = idx;
    uint32_t i = 0;

    while (i < table->size) {
        flow_entry_t *entry = &table->entries[idx];

        // Check if entry is empty (using first IP as indicator)
        if (entry->key.src_ip == 0 && entry->key.dst_ip == 0) {
            return NULL;
        }

        // Check if this is the flow we're looking for
        if (memcmp(&entry->key, key, sizeof(flow_key_t)) == 0) {
            return entry;
        }

        // Linear probing
        idx = (idx + 1) % table->size;
        i++;

        // Wrap around
        if (idx == start_idx) break;
    }

    return NULL;
}

flow_entry_t*
flow_table_insert(flow_table_t *table, const flow_key_t *key, uint32_t timestamp)
{
    uint32_t idx = flow_hash(key, table->size);
    uint32_t start_idx = idx;
    uint32_t i = 0;

    while (i < table->size) {
        flow_entry_t *entry = &table->entries[idx];

        // Empty slot found
        if (entry->key.src_ip == 0 && entry->key.dst_ip == 0) {
            memcpy(&entry->key, key, sizeof(flow_key_t));
            entry->packets = 1;
            entry->bytes = 0; // Will be set by caller
            entry->first_seen = timestamp;
            entry->last_seen = timestamp;
            entry->is_active = 1;
            table->count++;
            table->active_count++;
            return entry;
        }

        // If flow exists, we shouldn't be inserting
        if (memcmp(&entry->key, key, sizeof(flow_key_t)) == 0) {
            return entry;
        }

        idx = (idx + 1) % table->size;
        i++;
        if (idx == start_idx) break;
    }

    // Table full
    return NULL;
}

void
flow_table_age(flow_table_t *table, uint32_t current_time, uint32_t inactive_timeout)
{
    uint32_t expired = 0;

    for (uint32_t i = 0; i < table->size; i++) {
        flow_entry_t *entry = &table->entries[i];
        if (entry->is_active && (current_time - entry->last_seen) > inactive_timeout) {
            entry->is_active = 0;
            expired++;
            table->active_count--;
        }
    }

    table->count -= expired;
}

