use pcap::{Device, Packet};
use std::collections::HashMap;
use std::time::{SystemTime, UNIX_EPOCH};
use std::net::{IpAddr, Ipv4Addr};
use std::fmt;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

// Flow identifier (5-tuple)
#[derive(Debug, Eq, PartialEq, Hash, Clone)]
struct FlowKey {
    src_ip: IpAddr,
    dst_ip: IpAddr,
    src_port: u16,
    dst_port: u16,
    protocol: u8, // 6=TCP, 17=UDP
}

impl fmt::Display for FlowKey {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(
            f,
            "{} {}:{} → {}:{} (proto {})",
            match self.src_ip {
                IpAddr::V4(ip) => format!("{}", ip),
                IpAddr::V6(ip) => format!("[{}]", ip),
            },
            self.src_port,
            match self.dst_ip {
                IpAddr::V4(ip) => format!("{}", ip),
                IpAddr::V6(ip) => format!("[{}]", ip),
            },
            self.dst_port,
            self.protocol
        )
    }
}

// Flow statistics
#[derive(Debug, Default, Clone)]
struct FlowStats {
    bytes: u64,
    packets: u64,
    first_seen: u64,
    last_seen: u64,
}

fn main() {
    // Shared flow table protected by mutex
    let flow_table = Arc::new(Mutex::new(HashMap::<FlowKey, FlowStats>::new()));

    // Clone for the reporting thread
    let report_table = Arc::clone(&flow_table);

    // Start reporting thread
    thread::spawn(move || {
        report_flow_stats(report_table);
    });

    // Get network device
    let device = Device::lookup()
        .expect("Device lookup failed")
        .unwrap_or_else(|| Device::list().expect("No devices found")[0].clone());

    println!("Monitoring traffic on interface: {}", device.name);

    // Open capture
    let mut cap = pcap::Capture::from_device(device)
        .expect("Failed to open capture")
        .immediate_mode(true)
        .open()
        .expect("Failed to open capture");

    // Optional BPF filter (uncomment to filter TCP/UDP only)
    // cap.filter("tcp or udp", true).expect("Filter error");

    println!("Starting packet capture (Ctrl+C to stop)...");

    // Main capture loop
    while let Ok(packet) = cap.next_packet() {
        if let Some((flow_key, packet_size)) = parse_packet(&packet) {
            let mut table = flow_table.lock().unwrap();
            let stats = table.entry(flow_key.clone()).or_insert_with(|| {
                FlowStats {
                    first_seen: SystemTime::now()
                        .duration_since(UNIX_EPOCH)
                        .unwrap()
                        .as_secs(),
                    ..Default::default()
                }
            });

            stats.bytes += packet_size as u64;
            stats.packets += 1;
            stats.last_seen = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_secs();
        }
    }
}

fn parse_packet(packet: &Packet) -> Option<(FlowKey, usize)> {
    let data = packet.data;

    // Skip Ethernet header (14 bytes)
    if data.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([data[12], data[13]]);
    let ip_data = &data[14..];

    match ethertype {
        0x0800 => parse_ipv4(ip_data), // IPv4
        _ => None,
    }
}

fn parse_ipv4(data: &[u8]) -> Option<(FlowKey, usize)> {
    if data.len() < 20 {
        return None;
    }

    let version_ihl = data[0];
    if version_ihl >> 4 != 4 { // IPv4 version
        return None;
    }

    let ihl = ((version_ihl & 0x0F) * 4) as usize;
    if data.len() < ihl {
        return None;
    }

    let protocol = data[9];
    let src_ip = Ipv4Addr::new(data[12], data[13], data[14], data[15]);
    let dst_ip = Ipv4Addr::new(data[16], data[17], data[18], data[19]);

    let payload = &data[ihl..];
    let packet_size = packet.data.len();

    match protocol {
        6 => parse_tcp(payload).map(|(src_port, dst_port)| {
            let flow_key = FlowKey {
                src_ip: IpAddr::V4(src_ip),
                dst_ip: IpAddr::V4(dst_ip),
                src_port,
                dst_port,
                protocol: 6,
            };
            (flow_key, packet_size)
        }),
        17 => parse_udp(payload).map(|(src_port, dst_port)| {
            let flow_key = FlowKey {
                src_ip: IpAddr::V4(src_ip),
                dst_ip: IpAddr::V4(dst_ip),
                src_port,
                dst_port,
                protocol: 17,
            };
            (flow_key, packet_size)
        }),
        _ => None,
    }
}

fn parse_tcp(data: &[u8]) -> Option<(u16, u16)> {
    if data.len() < 20 {
        return None;
    }
    Some((
        u16::from_be_bytes([data[0], data[1]]),
        u16::from_be_bytes([data[2], data[3]]),
    ))
}

fn parse_udp(data: &[u8]) -> Option<(u16, u16)> {
    if data.len() < 8 {
        return None;
    }
    Some((
        u16::from_be_bytes([data[0], data[1]]),
        u16::from_be_bytes([data[2], data[3]]),
    ))
}

fn report_flow_stats(table: Arc<Mutex<HashMap<FlowKey, FlowStats>>>) {
    loop {
        thread::sleep(Duration::from_secs(10));

        let table = table.lock().unwrap();
        if table.is_empty() {
            continue;
        }

        println!("\n=== Flow Statistics (last 10 seconds) ===");
        println!("{:<60} {:>12} {:>10} {:>15} {:>15}",
                 "Flow", "Bytes", "Packets", "First Seen", "Last Seen");

        let mut flows: Vec<_> = table.iter().collect();
        flows.sort_by(|a, b| b.1.bytes.cmp(&a.1.bytes));

        for (flow_key, stats) in flows {
            println!("{:<60} {:>12} {:>10} {:>15} {:>15}",
                     flow_key,
                     stats.bytes,
                     stats.packets,
                     format_time(stats.first_seen),
                     format_time(stats.last_seen));
        }
        println!("Total flows: {}\n", flows.len());
    }
}

fn format_time(timestamp: u64) -> String {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs();
    let elapsed = now - timestamp;
    if elapsed < 60 {
        format!("{}s ago", elapsed)
    } else if elapsed < 3600 {
        format!("{}m ago", elapsed / 60)
    } else {
        format!("{}h ago", elapsed / 3600)
    }
}
