    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;
};

// --- Flow Statistics ---
struct flow_stats {
    uint64_t packets;
    uint64_t bytes;
    uint64_t last_seen;  // Timestamp (cycles)
};

// --- Flow Table (Hash Map) ---
struct flow_stats flow_table[FLOW_TABLE_SIZE];

// --- Hash Function ---
static uint32_t flow_hash(const struct flow_key *key) {
    uint32_t hash = 0;
    hash = (hash * 31) + key->src_ip;
    hash = (hash * 31) + key->dst_ip;
    hash = (hash * 31) + key->src_port;
    hash = (hash * 31) + key->dst_port;
    hash = (hash * 31) + key->protocol;
    return hash % FLOW_TABLE_SIZE;
}

// --- Initialize Flow Table ---
void init_flow_table() {
    memset(flow_table, 0, sizeof(flow_table));
}

// --- Update Flow Statistics ---
void update_flow_stats(const struct flow_key *key, uint32_t pkt_len) {
    uint32_t index = flow_hash(key);
    flow_table[index].packets++;
    flow_table[index].bytes += pkt_len;
    flow_table[index].last_seen = rte_rdtsc();
}

// --- Age Out Old Flows ---
void age_flows() {
    const uint64_t timeout_cycles = FLOW_TIMEOUT_SEC * rte_get_timer_hz();
    for (uint32_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        if (flow_table[i].packets > 0 &&
            (rte_rdtsc() - flow_table[i].last_seen) > timeout_cycles) {
            flow_table[i].packets = 0;
            flow_table[i].bytes = 0;
        }
    }
}

// --- Process Packets ---
static void lcore_main() {
    struct rte_mbuf *bufs[BURST_SIZE];
    uint16_t nb_rx;
    uint16_t port = 0;  // Use first port

    while (1) {
        // Receive burst of packets
        nb_rx = rte_eth_rx_burst(port, 0, bufs, BURST_SIZE);
        if (unlikely(nb_rx == 0)) {
            continue;
        }

        // Process each packet
        for (uint16_t i = 0; i < nb_rx; i++) {
            struct rte_mbuf *m = bufs[i];
            struct rte_ether_hdr *eth_hdr;
            struct rte_ipv4_hdr *ip_hdr;
            struct rte_tcp_hdr *tcp_hdr;
            struct rte_udp_hdr *udp_hdr;
            uint16_t ether_type;
            uint32_t pkt_len = m->pkt_len;

            // Parse Ethernet header
            eth_hdr = rte_pktmbuf_mtod(m, struct rte_ether_hdr *);
            ether_type = rte_be_to_cpu_16(eth_hdr->ether_type);

            if (ether_type == RTE_ETHER_TYPE_IPV4) {
                // Parse IPv4 header
                ip_hdr = (struct rte_ipv4_hdr *)(eth_hdr + 1);
                struct flow_key key = {
                    .src_ip = ip_hdr->src_addr,
                    .dst_ip = ip_hdr->dst_addr,
                    .protocol = ip_hdr->next_proto_id
                };

                // Parse transport layer (TCP/UDP)
                if (ip_hdr->next_proto_id == IPPROTO_TCP) {
                    tcp_hdr = (struct rte_tcp_hdr *)(ip_hdr + 1);
                    key.src_port = tcp_hdr->src_port;
                    key.dst_port = tcp_hdr->dst_port;
                } else if (ip_hdr->next_proto_id == IPPROTO_UDP) {
                    udp_hdr = (struct rte_udp_hdr *)(ip_hdr + 1);
                    key.src_port = udp_hdr->src_port;
                    key.dst_port = udp_hdr->dst_port;
                } else {
                    rte_pktmbuf_free(m);
                    continue;  // Skip unsupported protocols
                }

                // Update flow statistics
                update_flow_stats(&key, pkt_len);
            }

            // Free the mbuf
            rte_pktmbuf_free(m);
        }
    }
}

// --- Main Function ---
int main(int argc, char **argv) {
    int ret;
    uint16_t nb_ports;

    // Initialize DPDK EAL
    ret = rte_eal_init(argc, argv);
    if (ret < 0) {
        rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");
    }

    argc -= ret;
    argv += ret;

    // Check available ports
    nb_ports = rte_eth_dev_count_avail();
    if (nb_ports == 0) {
        rte_exit(EXIT_FAILURE, "No Ethernet ports available\n");
    }

    // Initialize flow table
