            .rss_conf = {
                .rss_key = NULL,
                .rss_hf = ETH_RSS_IP | ETH_RSS_UDP | ETH_RSS_TCP,
            },
        },
    };

    ret = rte_eth_dev_configure(0, 1, 1, &port_conf);
    if (ret < 0) {
        rte_exit(EXIT_FAILURE, "Cannot configure device: err=%d\n", ret);
    }

    // Setup RX queue
    ret = rte_eth_rx_queue_setup(0, 0, 128,
                                 rte_eth_dev_socket_id(0),
                                 NULL, NULL);
    if (ret < 0) {
