Packet parser:

```c
int
parse_packet(const struct rte_mbuf *m, flow_key_t *key, uint32_t *pkt_len)
{
    // Skip VLAN tag if present (802.1Q)
    uint16_t ether_type = rte_be_to_cpu_16(*(uint16_t *)(rte_pktmbuf_mtod(m, uint8_t *) + 12));
    uint8_t *l2_hdr = rte_pktmbuf_mtod(m, uint8_t *);

    if (ether_type == 0x8100) { // VLAN
        ether_type = rte_be_to_cpu_16(*(uint16_t *)(l2_hdr + 16));
        l2_hdr += 4; // Skip VLAN header
    } else if (ether_type != 0x0800) { // Not IPv4
        return 0;
    }

    // Check IPv4
    if (ether_type != 0x0800) {
        return 0;
    }

    // Minimum IPv4 header length is 20 bytes
    if (m->data_len < (l2_hdr - rte_pktmbuf_mtod(m, uint8_t *) + 20)) {
        return 0;
    }

    struct ipv4_hdr *ip = (struct ipv4_hdr *)l2_hdr;
    uint8_t ip_len = (ip->version_ihl & 0x0F) * 4;
    if (ip_len < 20) return 0;

    // Check protocol
    uint8_t protocol = ip->next_proto_id;
    if (protocol != IPPROTO_TCP && protocol != IPPROTO_UDP) {
        return 0;
    }

    // Check total length
    uint16_t ip_total_len = rte_be_to_cpu_16(ip->total_length);
    if (ip_total_len < ip_len) return 0;

    *pkt_len = ip_total_len;

    // Extract ports based on protocol
    if (protocol == IPPROTO_TCP) {
        struct tcp_hdr *tcp = (struct tcp_hdr *)(l2_hdr + ip_len);
        if ((uint8_t *)tcp + sizeof(struct tcp_hdr) > rte_pktmbuf_mtod(m, uint8_t *) + m->data_len) {
            return 0;
        }
        key->src_port = tcp->src_port;
        key->dst_port = tcp->dst_port;
    } else { // UDP
        struct udp_hdr *udp = (struct udp_hdr *)(l2_hdr + ip_len);
        if ((uint8_t *)udp + sizeof(struct udp_hdr) > rte_pktmbuf_mtod(m, uint8_t *) + m->data_len) {
            return 0;
        }
        key->src_port = udp->src_port;
        key->dst_port = udp->dst_port;
    }

    key->src_ip = ip->src_addr;
    key->dst_ip = ip->dst_addr;
    key->protocol = protocol;

    return 1;
}
