NetFlow export function:

```c
void
export_netflow(flow_table_t *table, int sockfd, uint32_t current_time, uint32_t flow_sequence)
{
    struct netflow_v5_header header;
    struct netflow_v5_record records[30]; // Max 30 records per packet

    header.version = rte_cpu_to_be_16(5);
    header.count = rte_cpu_to_be_16(table->active_count);
    header.sys_uptime = rte_cpu_to_be_32(current_time * 1000); // ms
    header.unix_secs = rte_cpu_to_be_32(current_time);
    header.unix_nsecs = 0;
    header.flow_sequence = rte_cpu_to_be_32(flow_sequence);
    header.engine_type = 0;
    header.engine_id = 0;
    header.sampling_interval = rte_cpu_to_be_16(1); // No sampling

    uint32_t record_count = 0;
    for (uint32_t i = 0; i < table->size && record_count < 30; i++) {
        flow_entry_t *entry = &table->entries[i];
        if (!entry->is_active) continue;

        struct netflow_v5_record *rec = &records[record_count];

        rec->src_addr = entry->key.src_ip;
        rec->dst_addr = entry->key.dst_ip;
        rec->nexthop = 0;
        rec->input = 0;
        rec->output = 0;
        rec->dPkts = rte_cpu_to_be_32(entry->packets);
        rec->dOctets = rte_cpu_to_be_32(entry->bytes);
        rec->first = rte_cpu_to_be_32(entry->first_seen);
        rec->last = rte_cpu_to_be_32(entry->last_seen);
        rec->src_port = entry->key.src_port;
        rec->dst_port = entry->key.dst_port;
        rec->pad1 = 0;
        rec->tcp_flags = 0;
        rec->prot = entry->key.protocol;
        rec->tos = 0;
        rec->src_as = 0;
        rec->dst_as = 0;
        rec->src_mask = 0;
        rec->dst_mask = 0;
        rec->pad2 = 0;

        record_count++;
    }

    // Send header and records
    send(sockfd, &header, sizeof(header), 0);
    if (record_count > 0) {
        send(sockfd, records, record_count * sizeof(struct netflow_v5_record), 0);
    }
}
