Main loop:

```c
int
main(int argc, char **argv)
{
    int ret;
    uint16_t port_id = 0;
    struct rte_mempool *mbuf_pool;
    struct rte_mbuf *rx_pkts[BURST_SIZE];
    flow_table_t *flow_table;
    int sockfd;
    struct sockaddr_in collector_addr;
    uint32_t flow_sequence = 0;
    uint32_t last_export_time = 0;
    uint32_t last_age_time = 0;
    const uint32_t INACTIVE_TIMEOUT = 15; // seconds
    const uint32_t EXPORT_INTERVAL = 5; // seconds

    // Initialize EAL
    ret = rte_eal_init(argc, argv);
    if (ret < 0)
        rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");

    argc -= ret;
    argv += ret;

    // Create mbuf pool
    mbuf_pool = rte_pbuf_pool_create("MBUF_POOL", NUM_MBUFS * 4,
                                    MBUF_CACHE_SIZE, 0,
                                    RTE_MBUF_DEFAULT_BUF_SIZE,
                                    rte_socket_id());
    if (mbuf_pool == NULL)
        rte_exit(EXIT_FAILURE, "Cannot create mbuf pool\n");

    // Initialize port
    if (port_init(port_id, mbuf_pool) != 0)
        rte_exit(EXIT_FAILURE, "Cannot init port %"PRIu16 "\n", port_id);

    // Create flow table
    flow_table = flow_table_create(FLOW_TABLE_SIZE);
    if (!flow_table)
        rte_exit(EXIT_FAILURE, "Cannot create flow table\n");

    // Create UDP socket for NetFlow export
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    memset(&collector_addr, 0, sizeof(collector_addr));
    collector_addr.sin_family = AF_INET;
    collector_addr.sin_port = htons(NETFLOW_COLLECTOR_PORT);
    collector_addr.sin_addr.s_addr = inet_addr(NETFLOW_COLLECTOR_IP);

    printf("Starting flow analyser...\n");

    // Main loop
    while (1) {
        uint32_t current_time = time(NULL);

        // Age flows periodically
        if (current_time - last_age_time >= 1) {
            flow_table_age(flow_table, current_time, INACTIVE_TIMEOUT);
            last_age_time = current_time;
        }

        // Export flows periodically
        if (current_time - last_export_time >= EXPORT_INTERVAL) {
            export_netflow(flow_table, sockfd, current_time, flow_sequence++);
            last_export_time = current_time;
        }

        // Receive packets
        uint16_t nb_rx = rte_eth_rx_burst(port_id, 0, rx_pkts, BURST_SIZE);
        if (unlikely(nb_rx == 0))
            continue;

        // Process each packet
        for (int i = 0; i < nb_rx; i++) {
            struct rte_mbuf *m = rx_pkts[i];
            flow_key_t key;
            uint32_t pkt_len;

            if (parse_packet(m, &key, &pkt_len)) {
                flow_entry_t *entry = flow_table_lookup(flow_table, &key);
                if (entry) {
                    // Update existing flow
                    entry->packets++;
                    entry->bytes += pkt_len;
                    entry->last_seen = current_time;
                } else {
                    // Create new flow
                    entry = flow_table_insert(flow_table, &key, current_time);
                    if (entry) {
                        entry->bytes = pkt_len;
                    }
                }
            }

            // Free the mbuf
            rte_pktmbuf_free(m);
        }
    }

    return 0;
}
