#[derive(Debug, Eq, PartialEq, Hash, Clone)]
struct FlowKey {
    src_ip: IpAddr,
    dst_ip: IpAddr,
    src_port: u16,
    dst_port: u16,
    protocol: u8, // e.g., 6 for TCP, 17 for UDP
}

