// Parse a packet to extract flow key and packet size
fn parse_packet(packet: &Packet) -> Option<(FlowKey, usize)> {
    // The packet data starts after the link-layer header (e.g., Ethernet)
    let data = packet.data;

    // Parse Ethernet header (simplified; assumes Ethernet II framing)
    if data.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([data[12], data[13]]);
    let (ip_header, ip_payload) = match ethertype {
        0x0800 => parse_ipv4(&data[14..]).ok()?, // IPv4
        0x86DD => parse_ipv6(&data[14..]).ok()?, // IPv6
        _ => return None, // Not IPv4 or IPv6
    };

    let (src_ip, dst_ip) = match ip_header {
        IpHeader::V4(ipv4) => (
            IpAddr::V4(ipv4.source),
            IpAddr::V4(ipv4.destination),
        ),
        IpHeader::V6(ipv6) => (
            IpAddr::V6(ipv6.source),
            IpAddr::V6(ipv6.destination),
        ),
    };

    // Parse transport layer header
    let (src_port, dst_port, protocol) = match ip_payload {
        IpPayload::Tcp(tcp) => (tcp.source, tcp.destination, 6), // TCP protocol number
        IpPayload::Udp(udp) => (udp.source, udp.destination, 17), // UDP protocol number
        _ => return None,
    };

    let flow_key = FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        protocol,
    };

    Some((flow_key, packet.data.len()))
}

// Simplified IP header parsing (for IPv4)
struct Ipv4Header {
    source: Ipv4Addr,
    destination: Ipv4Addr,
    protocol: u8,
    payload_offset: usize,
}

enum IpHeader {
    V4(Ipv4Header),
    V6(Ipv6Header),
}

struct Ipv6Header {
    source: Ipv6Addr,
    destination: Ipv6Addr,
    next_header: u8,
    payload_length: u16,
    payload_offset: usize,
}

enum IpPayload {
    Tcp(TcpHeader),
    Udp(UdpHeader),
    Other,
}

struct TcpHeader {
    source: u16,
    destination: u16,
}

struct UdpHeader {
    source: u16,
    destination: u16,
}

fn parse_ipv4(data: &[u8]) -> Result<(IpHeader, IpPayload), &'static str> {
    if data.len() < 20 {
        return Err("IPv4 header too short");
    }

    let version_ihl = data[0];
    let version = version_ihl >> 4;
    if version != 4 {
        return Err("Not IPv4");
    }

    let ihl = (version_ihl & 0x0F) as usize * 4;
    if data.len() < ihl {
        return Err("IPv4 header too short");
    }

    let protocol = data[9];
    let source = Ipv4Addr::new(data[12], data[13], data[14], data[15]);
    let destination = Ipv4Addr::new(data[16], data[17], data[18], data[19]);

    let payload_offset = ihl;
    let payload = &data[payload_offset..];

    let ip_header = Ipv4Header {
        source,
        destination,
        protocol,
        payload_offset,
    };

    // Parse transport layer
    let transport_payload = match protocol {
        6 => parse_tcp(payload).map(IpPayload::Tcp).ok(),
        17 => parse_udp(payload).map(IpPayload::Udp).ok(),
        _ => Some(IpPayload::Other),
    };

    match transport_payload {
        Some(payload) => Ok((IpHeader::V4(ip_header), payload)),
        None => Err("Failed to parse transport header"),
    }
}

fn parse_ipv6(data: &[u8]) -> Result<(IpHeader, IpPayload), &'static str> {
    if data.len() < 40 {
        return Err("IPv6 header too short");
    }

    let version = data[0] >> 4;
    if version != 6 {
        return Err("Not IPv6");
    }

    let payload_length = u16::from_be_bytes([data[4], data[5]]);
    let next_header = data[6];
    let source = Ipv6Addr::from(&data[8..24]);
    let destination = Ipv6Addr::from(&data[24..40]);

    let payload_offset = 40;
    let payload = &data[payload_offset..(payload_offset + payload_length as usize)];

    let ip_header = Ipv6Header {
        source,
        destination,
        next_header,
        payload_length,
        payload_offset,
    };

    // Parse transport layer
    let transport_payload = match next_header {
        6 => parse_tcp(payload).map(IpPayload::Tcp).ok(),
        17 => parse_udp(payload).map(IpPayload::Udp).ok(),
        _ => Some(IpPayload::Other),
    };

    match transport_payload {
        Some(payload) => Ok((IpHeader::V6(ip_header), payload)),
        None => Err("Failed to parse transport header"),
    }
}

fn parse_tcp(data: &[u8]) -> Result<TcpHeader, &'static str> {
    if data.len() < 20 {
        return Err("TCP header too short");
    }

    let source = u16::from_be_bytes([data[0], data[1]]);
    let destination = u16::from_be_bytes([data[2], data[3]]);

    Ok(TcpHeader { source, destination })
}

fn parse_udp(data: &[u8]) -> Result<UdpHeader, &'static str> {
    if data.len() < 8 {
        return Err("UDP header too short");
    }

    let source = u16::from_be_bytes([data[0], data[1]]);
    let destination = u16::from_be_bytes([data[2], data[3]]);

    Ok(UdpHeader { source, destination })
}

