```rust
use pnet::datalink::{self, Channel::Ethernet, NetworkInterface};
use pnet::packet::{
    Packet,
    ethernet::{EthernetPacket, EtherTypes},
    ip::{IpNextHeaderProtocol, IpNextHeaderProtocols},
    ipv4::Ipv4Packet,
    ipv6::Ipv6Packet,
    tcp::TcpPacket,
    udp::UdpPacket,
};
use std::{
    collections::HashMap,
    net::{IpAddr, Ipv4Addr, Ipv6Addr},
    sync::{Arc, Mutex},
    time::{Instant, Duration},
    thread,
};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct FlowKey {
    src_ip: IpAddr,
    dst_ip: IpAddr,
    src_port: u16,
    dst_port: u16,
    protocol: u8,
}

#[derive(Debug)]
struct FlowStats {
    bytes: u64,
    packets: u64,
    start_time: Instant,
    last_seen: Instant,
}

fn main() {
    // Find the default network interface
    let interface = datalink::interfaces()
        .into_iter()
        .find(|iface| iface.is_up() && !iface.is_loopback() && iface.is_running())
        .expect("No suitable network interface found");

    println!("Monitoring traffic on interface: {}", interface.name);

    // Create a channel to receive packets (promiscuous mode)
    let (_, mut rx) = match datalink::channel(&interface, Default::default()) {
        Ok(Ethernet(tx, rx)) => (tx, rx),
        Ok(_) => panic!("Unsupported channel type"),
        Err(e) => panic!("Error creating channel: {}", e),
    };

    // Shared state for flow tracking with thread-safe Mutex
    let flows = Arc::new(Mutex::new(HashMap::<FlowKey, FlowStats>::new()));
    let stats = Arc::new(Mutex::new((0u64, 0u64))); // (total_bytes, total_packets)

    // Spawn a thread to print flow statistics periodically
    let flows_clone = flows.clone();
    let stats_clone = stats.clone();
    thread::spawn(move || {
        let mut last_print = Instant::now();
        loop {
            thread::sleep(Duration::from_secs(1));
            let mut flows = flows_clone.lock().unwrap();
            let (total_bytes, total_packets) = *stats_clone.lock().unwrap();

            if last_print.elapsed() >= Duration::from_secs(1) {
                println!("\n=== Flow Statistics (Last Second) ===");
                println!("Total bytes: {}, Total packets: {}", total_bytes, total_packets);
                println!("Active flows: {}", flows.len());

                for (key, stats) in flows.iter() {
                    println!(
                        "{:?} -> Bytes: {}, Packets: {}, Duration: {:?}",
                        key,
                        stats.bytes,
                        stats.packets,
                        stats.last_seen - stats.start_time
                    );
                }
                println!("====================================\n");

                // Clean up old flows (older than 30 seconds)
                flows.retain(|_, v| v.last_seen.elapsed() < Duration::from_secs(30));
                last_print = Instant::now();
            }
        }
    });

    // Main packet processing loop
    loop {
        match rx.next() {
            Ok(packet) => {
                // Update global statistics
                let mut stats = stats.lock().unwrap();
                stats.0 += packet.len() as u64;
                stats.1 += 1;

                if let Some(eth_packet) = EthernetPacket::new(packet) {
                    match eth_packet.get_ethertype() {
                        EtherTypes::Ipv4 => {
                            if let Some(ipv4_packet) = Ipv4Packet::new(eth_packet.payload()) {
                                process_ip_packet(&ipv4_packet, flows.clone());
                            }
                        }
                        EtherTypes::Ipv6 => {
                            if let Some(ipv6_packet) = Ipv6Packet::new(eth_packet.payload()) {
                                process_ip_packet(&ipv6_packet, flows.clone());
                            }
                        }
                        _ => continue,
                    }
                }
            }
            Err(e) => eprintln!("Error receiving packet: {}", e),
        }
    }
}

fn process_ip_packet<T: Packet>(ip_packet: &T, flows: Arc<Mutex<HashMap<FlowKey, FlowStats>>>) {
    let protocol = ip_packet.get_next_level_protocol();
    let (src_ip, dst_ip) = match ip_packet {
        pnet::packet::ipv4::Ipv4Packet(_) => {
            let ipv4 = pnet::packet::ipv4::Ipv4Packet::new(ip_packet.packet()).unwrap();
            (IpAddr::V4(ipv4.get_source()), IpAddr::V4(ipv4.get_destination()))
        }
        pnet::packet::ipv6::Ipv6Packet(_) => {
            let ipv6 = pnet::packet::ipv6::Ipv6Packet::new(ip_packet.packet()).unwrap();
            (IpAddr::V6(ipv6.get_source()), IpAddr::V6(ipv6.get_destination()))
        }
        _ => return,
    };

    let (src_port, dst_port) = match protocol {
        IpNextHeaderProtocols::Tcp => {
            if let Some(tcp_packet) = TcpPacket::new(ip_packet.payload()) {
                (tcp_packet.get_source(), tcp_packet.get_destination())
            } else {
                return;
            }
        }
        IpNextHeaderProtocols::Udp => {
            if let Some(udp_packet) = UdpPacket::new(ip_packet.payload()) {
                (udp_packet.get_source(), udp_packet.get_destination())
            } else {
                return;
            }
        }
        _ => return,
    };

    let key = FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        protocol: protocol as u8,
    };

    let mut flows = flows.lock().unwrap();
    let stats = flows.entry(key).or_insert_with(|| FlowStats {
        bytes: 0,
        packets: 0,
        start_time: Instant::now(),
        last_seen: Instant::now(),
    });

    stats.bytes += ip_packet.packet().len() as u64;
    stats.packets += 1;
    stats.last_seen = Instant::now();
}
```

### Key Performance Features:

1. **Efficient Packet Capture**:
