#include <iostream>
#include <unordered_map>
#include <chrono>
#include <pcap.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <arpa/inet.h>

// Flow key structure (5-tuple)
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;

    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

// Hash function for FlowKey
namespace std {
    template<>
    struct hash<FlowKey> {
        size_t operator()(const FlowKey& key) const {
            return ((hash<uint32_t>()(key.src_ip) ^ (hash<uint32_t>()(key.dst_ip) << 1)) >> 1) ^
                   ((hash<uint16_t>()(key.src_port) ^ (hash<uint16_t>()(key.dst_port) << 1)) >> 1) ^
                   (hash<uint8_t>()(key.protocol) << 1);
        }
    };
}

// Flow statistics
struct FlowStats {
    uint64_t bytes;
    uint64_t packets;
    uint64_t first_timestamp;
    uint64_t last_timestamp;
};

// Global flow table
std::unordered_map<FlowKey, FlowStats> flow_table;
uint64_t total_packets = 0;
uint64_t total_bytes = 0;

// Packet processing callback
void packet_handler(u_char* user_data, const struct pcap_pkthdr* pkthdr, const u_char* packet) {
    (void)user_data; // Unused

    total_packets++;
    total_bytes += pkthdr->len;

    // Skip Ethernet header (assuming Ethernet)
    const struct ip* ip_header = (struct ip*)(packet + 14); // 14 bytes Ethernet header

    FlowKey key;
    key.src_ip = ip_header->ip_src.s_addr;
    key.dst_ip = ip_header->ip_dst.s_addr;
    key.protocol = ip_header->ip_p;

    // Handle TCP/UDP
    if (ip_header->ip_p == IPPROTO_TCP) {
        const struct tcphdr* tcp_header = (struct tcphdr*)(packet + 14 + (ip_header->ip_hl << 2));
        key.src_port = ntohs(tcp_header->th_sport);
        key.dst_port = ntohs(tcp_header->th_dport);
    } else if (ip_header->ip_p == IPPROTO_UDP) {
        const struct udphdr* udp_header = (struct udphdr*)(packet + 14 + (ip_header->ip_hl << 2));
        key.src_port = ntohs(udp_header->uh_sport);
        key.dst_port = ntohs(udp_header->uh_dport);
    } else {
        // Non-TCP/UDP protocols - use 0 for ports
        key.src_port = 0;
        key.dst_port = 0;
    }

    // Update flow statistics
    auto& stats = flow_table[key];
    stats.bytes += pkthdr->len;
    stats.packets++;
    stats.last_timestamp = pkthdr->ts.tv_sec * 1000000 + pkthdr->ts.tv_usec;

    if (stats.first_timestamp == 0) {
        stats.first_timestamp = stats.last_timestamp;
    }
}

// Print flow statistics every second
void print_stats() {
    static auto last_print = std::chrono::steady_clock::now();

    auto now = std::chrono::steady_clock::now();
    auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(now - last_print).count();

    if (elapsed >= 1) {
        std::cout << "\n--- Flow Statistics (last " << elapsed << " seconds) ---\n";
        std::cout << "Total packets: " << total_packets << "\n";
        std::cout << "Total bytes: " << total_bytes << "\n";
        std::cout << "Active flows: " << flow_table.size() << "\n";

        for (const auto& [key, stats] : flow_table) {
            char src_ip[INET_ADDRSTRLEN], dst_ip[INET_ADDRSTRLEN];
            inet_ntop(AF_INET, &key.src_ip, src_ip, INET_ADDRSTRLEN);
            inet_ntop(AF_INET, &key.dst_ip, dst_ip, INET_ADDRSTRLEN);

            std::cout << "Flow: " << src_ip << ":" << key.src_port << " -> "
                      << dst_ip << ":" << key.dst_port << " (proto "
                      << (int)key.protocol << ")\n";
            std::cout << "  Bytes: " << stats.bytes << ", Packets: " << stats.packets
                      << ", Duration: " << (stats.last_timestamp - stats.first_timestamp) / 1000000.0
                      << "s\n";
        }

        // Clear old flows (older than 60 seconds)
        auto now_usec = std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();

        for (auto it = flow_table.begin(); it != flow_table.end(); ) {
            if ((now_usec - it->second.last_timestamp) > 60000000) { // 60 seconds
                it = flow_table.erase(it);
            } else {
                ++it;
            }
        }

        total_packets = 0;
        total_bytes = 0;
        last_print = now;
    }
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <interface>\n";
        return 1;
    }

    char* dev = argv[1];
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t* handle;

    // Open device for sniffing
    handle = pcap_open_live(dev, BUFSIZ, 1, 1000, errbuf);
    if (handle == nullptr) {
        std::cerr << "Couldn't open device " << dev << ": " << errbuf << "\n";
        return 1;
    }

    // Set buffer size for better performance
    if (pcap_set_buffer_size(handle, 2 * 1024 * 1024) != 0) {
        std::cerr << "Warning: Couldn't set buffer size\n";
    }

    // Set immediate mode (don't wait for buffer to fill)
    if (pcap_set_immediate_mode(handle, 1) != 0) {
        std::cerr << "Warning: Couldn't set immediate mode\n";
    }

    std::cout << "Starting network flow analyser on interface " << dev << "...\n";
    std::cout << "Press Ctrl+C to stop\n";

    // Start packet capture loop
    if (pcap_loop(handle, 0, packet_handler, nullptr) < 0) {
        std::cerr << "Error in pcap_loop: " << pcap_geterr(handle) << "\n";
        pcap_close(handle);
        return 1;
    }

    pcap_close(handle);
    return 0;
}
