Here's a minimal working network flow analyser in **C** that captures packets, tracks flows (5-tuple), and outputs statistics. This version uses **libpcap** for packet capture (with optimizations for performance) and a simple hash table for flow tracking.

---

### **`flow_analyser.c`**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <pcap.h>
#include <netinet/in.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <arpa/inet.h>
#include <pthread.h>

#define HASH_TABLE_SIZE 1000003  // Prime number for better distribution
#define FLOW_TIMEOUT    60       // Seconds before a flow is considered expired
#define BUFFER_SIZE     1024     // Packet buffer size

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;
} FlowKey;

typedef struct Flow {
    FlowKey key;
    uint64_t bytes;
    uint64_t packets;
    time_t last_seen;
    struct Flow *next;
} Flow;

Flow *flow_table[HASH_TABLE_SIZE] = {0};
pthread_mutex_t flow_table_mutex = PTHREAD_MUTEX_INITIALIZER;

// Simple hash function for FlowKey
unsigned int hash_flow_key(const FlowKey *key) {
    unsigned int hash = 0;
    hash = (hash * 31) + key->src_ip;
    hash = (hash * 31) + key->dst_ip;
    hash = (hash * 31) + key->src_port;
    hash = (hash * 31) + key->dst_port;
    hash = (hash * 31) + key->protocol;
    return hash % HASH_TABLE_SIZE;
}

// Insert or update a flow in the hash table
void update_flow(const FlowKey *key, uint32_t pkt_len) {
    unsigned int hash = hash_flow_key(key);
    Flow *flow = flow_table[hash];

    pthread_mutex_lock(&flow_table_mutex);

    // Search for existing flow
    while (flow) {
        if (flow->key.src_ip == key->src_ip &&
            flow->key.dst_ip == key->dst_ip &&
            flow->key.src_port == key->src_port &&
            flow->key.dst_port == key->dst_port &&
            flow->key.protocol == key->protocol) {
            flow->bytes += pkt_len;
            flow->packets++;
            flow->last_seen = time(NULL);
            pthread_mutex_unlock(&flow_table_mutex);
            return;
        }
        flow = flow->next;
    }

    // Create new flow
    flow = malloc(sizeof(Flow));
    if (!flow) {
        perror("malloc failed");
        pthread_mutex_unlock(&flow_table_mutex);
        return;
    }
    flow->key = *key;
    flow->bytes = pkt_len;
    flow->packets = 1;
    flow->last_seen = time(NULL);
    flow->next = flow_table[hash];
    flow_table[hash] = flow;

    pthread_mutex_unlock(&flow_table_mutex);
}

// Print all active flows (for demonstration)
void print_flows() {
    printf("\n=== Active Flows ===\n");
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        Flow *flow = flow_table[i];
        while (flow) {
            char src_ip[INET_ADDRSTRLEN], dst_ip[INET_ADDRSTRLEN];
            inet_ntop(AF_INET, &flow->key.src_ip, src_ip, sizeof(src_ip));
            inet_ntop(AF_INET, &flow->key.dst_ip, dst_ip, sizeof(dst_ip));

            printf("Flow: %s:%d -> %s:%d (Proto: %d) | Bytes: %lu | Packets: %lu\n",
                   src_ip, ntohs(flow->key.src_port),
                   dst_ip, ntohs(flow->key.dst_port),
                   flow->key.protocol,
                   flow->bytes, flow->packets);
            flow = flow->next;
        }
    }
}

// Periodically clean up expired flows
void *cleanup_flows(void *arg) {
    while (1) {
        sleep(10);  // Run cleanup every 10 seconds
        time_t now = time(NULL);

        pthread_mutex_lock(&flow_table_mutex);
        for (int i = 0; i < HASH_TABLE_SIZE; i++) {
            Flow **flow_ptr = &flow_table[i];
            while (*flow_ptr) {
                if (now - (*flow_ptr)->last_seen > FLOW_TIMEOUT) {
                    Flow *expired = *flow_ptr;
                    *flow_ptr = expired->next;
                    free(expired);
                } else {
                    flow_ptr = &((*flow_ptr)->next);
                }
            }
        }
        pthread_mutex_unlock(&flow_table_mutex);
    }
    return NULL;
}

// Packet processing callback
void packet_handler(u_char *user_data, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    const struct ip *ip_header = (struct ip *)(packet + sizeof(struct ether_header));
    if (ip_header->ip_v != 4) return;  // Only IPv4

    FlowKey key;
    key.src_ip = ip_header->ip_src.s_addr;
    key.dst_ip = ip_header->ip_dst.s_addr;
    key.protocol = ip_header->ip_p;

    uint16_t src_port = 0, dst_port = 0;
    if (ip_header->ip_p == IPPROTO_TCP) {
        const struct tcphdr *tcp_header = (struct tcphdr *)(packet + sizeof(struct ether_header) + sizeof(struct ip));
        src_port = tcp_header->th_sport;
        dst_port = tcp_header->th_dport;
    } else if (ip_header->ip_p == IPPROTO_UDP) {
        const struct udphdr *udp_header = (struct udphdr *)(packet + sizeof(struct ether_header) + sizeof(struct ip));
        src_port = udp_header->uh_sport;
        dst_port = udp_header->uh_dport;
    } else {
        return;  // Unsupported protocol
    }

    key.src_port = src_port;
    key.dst_port = dst_port;

    update_flow(&key, pkthdr->len);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    char *dev = argv[1];
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;

    // Open device in promiscuous mode
    handle = pcap_open_live(dev, BUFSIZ, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Couldn't open device %s: %s\n", dev, errbuf);
        return 1;
    }

    // Set buffer size and timeout for better performance
    if (pcap_set_buffer_size(handle, 2 * 1024 * 1024) != 0) {
        fprintf(stderr, "Failed to set buffer size\n");
    }
    if (pcap_set_timeout(handle, 100) != 0) {
        fprintf(stderr, "Failed to set timeout\n");
    }

    // Start flow cleanup thread
    pthread_t cleanup_thread;
    if (pthread_create(&cleanup_thread, NULL, cleanup_flows, NULL) != 0) {
        perror("Failed to create cleanup thread");
        return 1;
    }

    printf("Starting flow analyser on %s...\n", dev);
    pcap_loop(handle, -1, packet_handler, NULL);

    pcap_close(handle);
    return 0;
}
```

