// Function to process packets
void packet_handler(u_char *user_data, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    // Skip Ethernet header (14 bytes)
    const u_char *ip_header = packet + 14;

    // Check IPv4 (version 4, header length 5)
    if ((ip_header[0] & 0xF0) != 0x40 || (ip_header[0] & 0x0F) != 5) {
        return;
    }

    // Get IP header fields
    uint32_t src_ip = *(uint32_t*)(ip_header + 12);
    uint32_t dst_ip = *(uint32_t*)(ip_header + 16);
    uint8_t protocol = ip_header[9];
    uint16_t ip_len = ntohs(*(uint16_t*)(ip_header + 2));

    // Skip IP header to get transport header
    const u_char *transport_header = ip_header + (ip_header[0] & 0x0F) * 4;

    FlowKey key;
    key.src_ip = src_ip;
    key.dst_ip = dst_ip;
    key.protocol = protocol;

    // Process TCP/UDP flows
    if (protocol == 6 || protocol == 17) {  // TCP or UDP
        key.src_port = ntohs(*(uint16_t*)(transport_header));
        key.dst_port = ntohs(*(uint16_t*)(transport_header + 2));

        // Create flow key (network byte order for consistent hashing)
        Flow *flow = g_hash_table_lookup(flow_table, &key);
        if (!flow) {
            flow = g_new(Flow, 1);
            flow->key = key;
            flow->packets = 0;
            flow->bytes = 0;
            flow->first_seen = pkthdr->ts.tv_sec;
            flow->last_seen = pkthdr->ts.tv_sec;
            g_hash_table_insert(flow_table, &flow->key, flow);
        }

        flow->packets++;
        flow->bytes += pkthdr->len;
        flow->last_seen = pkthdr->ts.tv_sec;
    }
}

// Print flow statistics
void print_stats() {
    GHashTableIter iter;
    gpointer key, value;

    printf("\nFlow Statistics (last updated: %ld):\n", time(NULL));
    printf("%-20s %-20s %-10s %-10s %-10s %-10s\n",
           "Source IP", "Dest IP", "Proto", "Src Port", "Dst Port", "Packets");

    g_hash_table_iter_init(&iter, flow_table);
    while (g_hash_table_iter_next(&iter, &key, &value)) {
        Flow *flow = (Flow *)value;
        char src_ip[INET_ADDRSTRLEN], dst_ip[INET_ADDRSTRLEN];

        inet_ntop(AF_INET, &flow->key.src_ip, src_ip, INET_ADDRSTRLEN);
        inet_ntop(AF_INET, &flow->key.dst_ip, dst_ip, INET_ADDRSTRLEN);

        printf("%-20s %-20s %-10d %-10d %-10d %-10lu\n",
               src_ip, dst_ip, flow->key.protocol,
               flow->key.src_port, flow->key.dst_port,
               flow->packets);
    }
    printf("\n");
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    char *dev = argv[1];
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;

    // Open device for sniffing
    handle = pcap_open_live(dev, BUFSIZ, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Couldn't open device %s: %s\n", dev, errbuf);
        return 1;
    }

    // Compile and set filter for IPv4 TCP/UDP traffic
    struct bpf_program fp;
    char filter_exp[] = "ip proto tcp or ip proto udp";
    if (pcap_compile(handle, &fp, filter_exp, 0, PCAP_NETMASK_UNKNOWN) == -1) {
        fprintf(stderr, "Couldn't parse filter %s: %s\n", filter_exp, pcap_geterr(handle));
        return 1;
    }
    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "Couldn't install filter %s: %s\n", filter_exp, pcap_geterr(handle));
        return 1;
    }

    // Initialize flow table
    flow_table = g_hash_table_new_full(
        g_boxed_hash(flow_key_hash),  // Custom hash function for FlowKey
        g_boxed_equal(flow_key_equal), // Custom equal function
        NULL,                          // No key destroy
        g_free                         // Value destroy (free Flow structs)
    );

    // Set up periodic stats printing
    time_t last_print = time(NULL);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = print_stats;
    sigaction(SIGALRM, &sa, NULL);
    alarm(5);  // Print stats every 5 seconds

    printf("Starting packet capture on %s...\n", dev);

    // Start packet capture loop
    pcap_loop(handle, -1, packet_handler, NULL);

    // Cleanup
    pcap_close(handle);
    g_hash_table_destroy(flow_table);
    return 0;
}
