use pnet::datalink::{self, Channel::Ethernet, NetworkInterface};
use pnet::packet::{Packet, ethernet::EthernetPacket, ip::IpNextHeaderProtocols, ipv4::Ipv4Packet, tcp::TcpPacket, udp::UdpPacket};
use std::collections::HashMap;
use std::net::{IpAddr, Ipv4Addr};
use std::time::{Instant, Duration};
use std::sync::{Arc, Mutex};
use std::thread;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct FlowKey {
    src_ip: IpAddr,
    dst_ip: IpAddr,
    src_port: u16,
    dst_port: u16,
    protocol: u8,
}

struct FlowStats {
    bytes: u64,
    packets: u64,
    start_time: Instant,
    last_seen: Instant,
}

fn main() {
    // Find the default network interface
    let interface = datalink::interfaces()
        .into_iter()
        .find(|iface| iface.is_up() && !iface.is_loopback() && iface.is_running())
        .expect("No suitable network interface found");

    // Create a channel to receive packets
    let (_, mut rx) = match datalink::channel(&interface, Default::default()) {
        Ok(Ethernet(tx, rx)) => (tx, rx),
        Ok(_) => panic!("Unsupported channel type"),
        Err(e) => panic!("Error creating channel: {}", e),
    };

    // Shared state for flow tracking
    let flows = Arc::new(Mutex::new(HashMap::<FlowKey, FlowStats>::new()));
    let last_print = Arc::new(Mutex::new(Instant::now()));

    // Spawn a thread to print flow statistics periodically
    let flows_clone = flows.clone();
    let last_print_clone = last_print.clone();
    thread::spawn(move || {
        loop {
            thread::sleep(Duration::from_secs(1));
            let mut flows = flows_clone.lock().unwrap();
            let mut last_print = last_print_clone.lock().unwrap();

            if last_print.elapsed() >= Duration::from_secs(1) {
                println!("Flow statistics:");
                for (key, stats) in flows.iter() {
                    println!("{:?} - Bytes: {}, Packets: {}, Duration: {:?}",
                        key, stats.bytes, stats.packets, stats.last_seen - stats.start_time);
                }
                println!("---");
                *last_print = Instant::now();
            }
        }
    });

    // Main packet processing loop
    loop {
        match rx.next() {
            Ok(packet) => {
                if let Some(eth_packet) = EthernetPacket::new(packet) {
                    if let Some(ipv4_packet) = Ipv4Packet::new(eth_packet.payload()) {
                        let protocol = ipv4_packet.get_next_level_protocol();
                        let src_ip = IpAddr::V4(ipv4_packet.get_source());
                        let dst_ip = IpAddr::V4(ipv4_packet.get_destination());

                        let (src_port, dst_port) = match protocol {
                            IpNextHeaderProtocols::Tcp => {
                                if let Some(tcp_packet) = TcpPacket::new(ipv4_packet.payload()) {
                                    (tcp_packet.get_source(), tcp_packet.get_destination())
                                } else {
                                    continue;
                                }
                            },
                            IpNextHeaderProtocols::Udp => {
                                if let Some(udp_packet) = UdpPacket::new(ipv4_packet.payload()) {
                                    (udp_packet.get_source(), udp_packet.get_destination())
                                } else {
                                    continue;
                                }
                            },
                            _ => continue,
                        };

                        let key = FlowKey {
                            src_ip,
                            dst_ip,
                            src_port,
                            dst_port,
                            protocol: protocol as u8,
                        };

                        let mut flows = flows.lock().unwrap();
                        let stats = flows.entry(key).or_insert_with(|| FlowStats {
                            bytes: 0,
                            packets: 0,
                            start_time: Instant::now(),
                            last_seen: Instant::now(),
                        });

                        stats.bytes += ipv4_packet.packet().len() as u64;
                        stats.packets += 1;
                        stats.last_seen = Instant::now();
                    }
                }
            },
            Err(e) => {
                eprintln!("Error receiving packet: {}", e);
            }
        }
    }
}
```

