            let mut last_print = last_print_clone.lock().unwrap();

            if last_print.elapsed() >= Duration::from_secs(1) {
                println!("Flow statistics (last second):");
                for (key, stats) in flows.iter() {
                    println!("{:?} - Bytes: {}, Packets: {}, Duration: {:?}",
                        key, stats.bytes, stats.packets, stats.last_seen - stats.start_time);
                }
                println!("---");
                *last_print = Instant::now();
                // Clear old flows (older than 30 seconds)
                flows.retain(|_, v| v.last_seen.elapsed() < Duration::from_secs(30));
            }
        }
    });

    // Main packet processing loop
    loop {
        match rx.next() {
            Ok(packet) => {
                if let Some(eth_packet) = EthernetPacket::new(packet) {
                    match eth_packet.get_ethertype() {
                        pnet::packet::ethernet::EtherTypes::Ipv4 => {
                            if let Some(ipv4_packet) = Ipv4Packet::new(eth_packet.payload()) {
                                process_ip_packet(&ipv4_packet, flows.clone());
                            }
                        },
                        pnet::packet::ethernet::EtherTypes::Ipv6 => {
                            if let Some(ipv6_packet) = Ipv6Packet::new(eth_packet.payload()) {
                                process_ip_packet(&ipv6_packet, flows.clone());
                            }
                        },
                        _ => continue,
                    }
                }
            },
            Err(e) => {
                eprintln!("Error receiving packet: {}", e);
            }
        }
    }
}

fn process_ip_packet<T: Packet>(ip_packet: &T, flows: Arc<Mutex<HashMap<FlowKey, FlowStats>>>) {
    let protocol = ip_packet.get_next_level_protocol();
    let (src_ip, dst_ip) = match ip_packet {
        pnet::packet::ipv4::Ipv4Packet(_) => {
            let ipv4 = pnet::packet::ipv4::Ipv4Packet::new(ip_packet.packet()).unwrap();
            (IpAddr::V4(ipv4.get_source()), IpAddr::V4(ipv4.get_destination()))
        },
        pnet::packet::ipv6::Ipv6Packet(_) => {
            let ipv6 = pnet::packet::ipv6::Ipv6Packet::new(ip_packet.packet()).unwrap();
            (IpAddr::V6(ipv6.get_source()), IpAddr::V6(ipv6.get_destination()))
        },
        _ => return,
    };

    let (src_port, dst_port) = match protocol {
        IpNextHeaderProtocols::Tcp => {
            if let Some(tcp_packet) = TcpPacket::new(ip_packet.payload()) {
                (tcp_packet.get_source(), tcp_packet.get_destination())
            } else {
                return;
            }
        },
        IpNextHeaderProtocols::Udp => {
            if let Some(udp_packet) = UdpPacket::new(ip_packet.payload()) {
                (udp_packet.get_source(), udp_packet.get_destination())
            } else {
                return;
            }
        },
        _ => return,
    };

    let key = FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        protocol: protocol as u8,
    };

    let mut flows = flows.lock().unwrap();
    let stats = flows.entry(key).or_insert_with(|| FlowStats {
        bytes: 0,
        packets: 0,
        start_time: Instant::now(),
        last_seen: Instant::now(),
    });

    stats.bytes += ip_packet.packet().len() as u64;
    stats.packets += 1;
    stats.last_seen = Instant::now();
}
