static void bme280_read_raw_data(void)
{
  uint8_t data[8];

  /* Read temperature and pressure (6 bytes) */
  bme280_read_reg(BME280_REGISTER_PRESS_MSB, data, 6);

  raw_press = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
  raw_temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

  /* Read humidity (2 bytes) */
  bme280_read_reg(BME280_REGISTER_HUM_MSB, data, 2);
  raw_hum = (data[0] << 8) | data[1];
