/*
 * Microcontroller Firmware: Sensor Data Reader & Processor
 * Target: Arduino Uno (ATmega328P)
 * Sensor: DHT22 (Temperature & Humidity)
 * Language: C++ (Arduino framework)
 */

#include <DHT.h>  // Official DHT sensor library

// Configuration Constants
#define DHT_PIN     2       // Digital pin connected to DHT22
#define DHT_TYPE    DHT22   // Sensor type
#define SAMPLE_COUNT 5      // Number of samples for moving average
#define DELAY_MS    2000    // Delay between readings (ms)

// Sensor Data Structure
struct SensorData {
    float temperature;  // in °C
    float humidity;     // in %
    bool valid;         // Data validity flag
};

// Global Variables
DHT dht(DHT_PIN, DHT_TYPE);
SensorData processedData;
float tempSamples[SAMPLE_COUNT] = {0};
float humSamples[SAMPLE_COUNT] = {0};
uint8_t sampleIndex = 0;

// Initialize the system
void setup() {
    // Initialize serial communication
    Serial.begin(9600);
    while (!Serial);  // Wait for serial port to connect (for native USB)

    // Initialize DHT sensor
    dht.begin();

    // Print header
    Serial.println("=== Sensor Data Processor ===");
    Serial.println("Type,RawTemp,RawHum,ProcessedTemp,ProcessedHum,Status");
}

// Main processing loop
void loop() {
    // Read raw sensor data
    float rawTemp = dht.readTemperature();
    float rawHum = dht.readHumidity();

    // Check if readings are valid
    bool isValid = !isnan(rawTemp) && !isnan(rawHum);

    // Store samples for moving average
    tempSamples[sampleIndex] = rawTemp;
    humSamples[sampleIndex] = rawHum;
    sampleIndex = (sampleIndex + 1) % SAMPLE_COUNT;

    // Calculate moving average
    float avgTemp = calculateMovingAverage(tempSamples, SAMPLE_COUNT);
    float avgHum = calculateMovingAverage(humSamples, SAMPLE_COUNT);

    // Store processed data
    processedData.temperature = avgTemp;
    processedData.humidity = avgHum;
    processedData.valid = isValid;

    // Output results
    printSensorData(rawTemp, rawHum, processedData);

    // Wait before next reading
    delay(DELAY_MS);
}

// Calculate moving average from samples
float calculateMovingAverage(float samples[], uint8_t count) {
    float sum = 0;
    for (uint8_t i = 0; i < count; i++) {
        sum += samples[i];
    }
    return sum / count;
}

// Format and print sensor data
void printSensorData(float rawTemp, float rawHum, SensorData data) {
    // Format: Type,RawTemp,RawHum,ProcessedTemp,ProcessedHum,Status
    Serial.print("DHT22,");
    Serial.print(rawTemp, 1);
    Serial.print(",");
    Serial.print(rawHum, 1);
    Serial.print(",");
    Serial.print(data.temperature, 1);
    Serial.print(",");
    Serial.print(data.humidity, 1);
    Serial.print(",");
    Serial.println(data.valid ? "VALID" : "ERROR");
}
```

