/**
 * @brief Applies moving average filter to sensor data
 * @param newValue New sensor reading
 * @param samples Array storing previous samples
 * @param index Current position in circular buffer
 * @param windowSize Size of the moving average window
 * @return Filtered value
 */
float movingAverage(float newValue, float samples[], uint8_t &index, uint8_t windowSize) {
    // Store new value
    samples[index] = newValue;
    index = (index + 1) % windowSize;

    // Calculate average
    float sum = 0;
    for (uint8_t i = 0; i < windowSize; i++) {
        sum += samples[i];
    }

    return sum / windowSize;
}

