// Read DHT22 sensor data
uint8_t DHT22_Read(void) {
    uint8_t data[5] = {0};
    uint8_t retries = 0;
    uint32_t timeout = 0;

    // Reset communication
    HAL_GPIO_WritePin(DHT22_PORT, DHT22_PIN, GPIO_PIN_RESET);
    HAL_Delay(1);  // Hold low for at least 1ms
    __HAL_GPIO_EXTI_CLEAR_IT(DHT22_PIN);
    HAL_GPIO_WritePin(DHT22_PORT, DHT22_PIN, GPIO_PIN_SET);

    // Change to input mode to wait for sensor response
    GPIO_InitTypeDef GPIO_InitStruct = {0};
    GPIO_InitStruct.Pin = DHT22_PIN;
    GPIO_InitStruct.Mode = GPIO_MODE_INPUT;
    GPIO_InitStruct.Pull = GPIO_PULLUP;
    GPIO_InitStruct.Speed = GPIO_SPEED_FREQ_HIGH;
    HAL_GPIO_Init(DHT22_PORT, &GPIO_InitStruct);

    // Wait for sensor to pull line low (response)
    timeout = 0;
    while(HAL_GPIO_ReadPin(DHT22_PORT, DHT22_PIN) == GPIO_PIN_SET) {
        if(timeout++ > 1000) return 0;  // Timeout
        HAL_Delay(1);
    }

    // Wait for sensor to pull line high (start of data transmission)
    timeout = 0;
    while(HAL_GPIO_ReadPin(DHT22_PORT, DHT22_PIN) == GPIO_PIN_RESET) {
        if(timeout++ > 1000) return 0;  // Timeout
        HAL_Delay(1);
    }

    // Read 40 bits of data
    for(int i = 0; i < 5; i++) {
        for(int j = 0; j < 8; j++) {
            // Wait for start of bit (low)
            timeout = 0;
            while(HAL_GPIO_ReadPin(DHT22_PORT, DHT22_PIN) == GPIO_PIN_SET) {
                if(timeout++ > 1000) return 0;
                HAL_Delay(1);
            }

            // Measure pulse width (high time)
            uint32_t pulseStart = systemTicks;
            timeout = 0;
            while(HAL_GPIO_ReadPin(DHT22_PORT, DHT22_PIN) == GPIO_PIN_RESET) {
                if(timeout++ > 1000) return 0;
                HAL_Delay(1);
            }
            uint32_t pulseEnd = systemTicks;

            // Calculate bit value (0 or 1)
            uint32_t pulseWidth = pulseEnd - pulseStart;
            data[i] <<= 1;
            if(pulseWidth > 50) {  // Threshold for '1' bit
                data[i] |= 0x01;
            }
        }
    }

    // Verify checksum
    uint8_t checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if(checksum != data[4]) {
        return 0;
    }

    // Store data
    memcpy(dht22Data, data, 5);
    return 1;
}

// Process raw sensor data
void ProcessSensorData(void) {
    // Extract humidity (16-bit integer)
    uint16_t rawHumidity = (dht22Data[0] << 8) | dht22Data[1];
    humidity = (float)rawHumidity / 10.0f;

    // Extract temperature (16-bit integer, negative if MSB is set)
    uint16_t rawTemp = ((dht22Data[2] & 0x7F) << 8) | dht22Data[3];
    temperature = (float)rawTemp / 10.0f;
    if(dht22Data[2] & 0x80) {
        temperature = -temperature;
    }

    // Apply simple moving average filter
    static float tempHistory[FILTER_WINDOW] = {0};
    static float humHistory[FILTER_WINDOW] = {0};
    static uint8_t index = 0;

    tempHistory[index] = temperature;
    humHistory[index] = humidity;
    index = (index + 1) % FILTER_WINDOW;

    float tempSum = 0, humSum = 0;
    for(int i = 0; i < FILTER_WINDOW; i++) {
        tempSum += tempHistory[i];
        humSum += humHistory[i];
    }

    temperature = tempSum / FILTER_WINDOW;
    humidity = humSum / FILTER_WINDOW;
}

