}

bool bme280_init(void) {
    // Check chip ID
    uint8_t chip_id;
    if (!bme280_read_reg(BME280_REGISTER_CHIPID, &chip_id, 1) || chip_id != 0x60) {
        return false;
    }

    // Configure sensor (oversampling x1, normal mode)
    if (!bme280_write_reg(BME280_REGISTER_CTRL_MEAS, 0x25)) {
        return false;
    }

    return true;
}

bool bme280_read(BME280_Data *data) {
    uint8_t raw[8];
    if (!bme280_read_reg(BME280_REGISTER_PRESS_MSB, raw, 8)) {
        return false;
    }

    // Raw data processing (simplified; real implementation requires calibration)
    int32_t adc_T = (raw[3] << 12) | (raw[4] << 4) | (raw[5] >> 4);
    int32_t adc_H = (raw[6] << 8) | raw[7];

    // Simplified conversion (real BME280 requires calibration coefficients)
    data->temperature = (adc_T / 100.0f) - 50.0f;
    data->humidity = adc_H / 1024.0f;
    data->pressure = 1000.0f; // Placeholder

    return true;
}
