### **9. `utils/filter.c` (Moving Average Filter)**
```c
#include "filter.h"
#include <stdlib.h>

void filter_init(MovingAverageFilter *filter, uint8_t window_size) {
    filter->buffer = malloc(window_size * sizeof(float));
    filter->window_size = window_size;
    filter->index = 0;
    filter->sum = 0.0f;
    for (uint8_t i = 0; i < window_size; i++) {
        filter->buffer[i] = 0.0f;
    }
}

float filter_update(MovingAverageFilter *filter, float input) {
    filter->sum -= filter->buffer[filter->index];
    filter->buffer[filter->index] = input;
    filter->sum += input;
    filter->index = (filter->index + 1) % filter->window_size;
    return filter->sum / filter->window_size;
}
