// ======================
#define SENSOR_I2C_ADDRESS       0x48  // Example: TMP102 sensor address
#define SENSOR_DATA_REGISTER     0x00  // Register to read temperature
#define MOVING_AVERAGE_WINDOW    5     // Number of samples for moving average
#define UART_TX_BUFFER_SIZE      64    // Buffer for UART transmission

// ======================
// Global Variables
// ======================
I2C_HandleTypeDef hi2c1;      // I2C handle
UART_HandleTypeDef huart2;    // UART handle
float temperature_readings[MOVING_AVERAGE_WINDOW] = {0};
uint8_t current_index = 0;
float filtered_temperature = 0.0f;

