    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_I2C1_Init();
    MX_USART2_UART_Init();
    Sensor_Init();

    char msg_buffer[UART_TX_BUFFER_SIZE];

    while (1) {
        // 1. Read sensor data
        float raw_temp = Read_Temperature();

        // 2. Process data (apply moving average filter)
        filtered_temperature = Moving_Average_Filter(raw_temp);

        // 3. Format and send output via UART
        snprintf(msg_buffer, UART_TX_BUFFER_SIZE,
                "Raw: %.2f°C | Filtered: %.2f°C\r\n",
                raw_temp, filtered_temperature);
        Print_Message(msg_buffer);

        // 4. Delay between readings (adjust based on sensor requirements)
        HAL_Delay(1000);  // 1 second delay
    }
}

