    // For TMP102, you might configure it for 12-bit resolution here.
}

// ======================
// Read Temperature from Sensor
// ======================
float Read_Temperature(void) {
    uint8_t data[2] = {0};
    uint8_t reg = SENSOR_DATA_REGISTER;

    // Read 2 bytes from the sensor (temperature is 12-bit)
    if (HAL_I2C_Master_Transmit(&hi2c1, SENSOR_I2C_ADDRESS << 1, &reg, 1, HAL_MAX_DELAY) != HAL_OK) {
        return -273.15f;  // Return absolute zero on error
    }
    if (HAL_I2C_Master_Receive(&hi2c1, SENSOR_I2C_ADDRESS << 1, data, 2, HAL_MAX_DELAY) != HAL_OK) {
        return -273.15f;  // Return absolute zero on error
    }

    // Convert raw data to temperature (example for TMP102)
    int16_t raw_temp = ((data[0] << 4) | (data[1] >> 4));
    float temperature = raw_temp * 0.0625f;  // 0.0625°C per LSB (12-bit mode)

    return temperature;
}

// ======================
// Moving Average Filter
// ======================
float Moving_Average_Filter(float new_value) {
    // Shift and add new value
    temperature_readings[current_index] = new_value;
    current_index = (current_index + 1) % MOVING_AVERAGE_WINDOW;

    // Calculate average
    float sum = 0.0f;
    for (uint8_t i = 0; i < MOVING_AVERAGE_WINDOW; i++) {
        sum += temperature_readings[i];
    }
    return sum / MOVING_AVERAGE_WINDOW;
}

