#include "stm32f4xx_hal.h"

// MPU6050 I2C Address
#define MPU6050_ADDR         0x68 << 1  // Shifted for 7-bit address
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H  0x43
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_CONFIG       0x1A
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_ACCEL_CONFIG 0x1C

// Sensor Scaling Factors (adjust based on your configuration)
#define ACCEL_SCALE 16384.0f  // ±2g range
#define GYRO_SCALE  131.0f    // ±250°/s range

// Global Variables
I2C_HandleTypeDef hi2c1;
UART_HandleTypeDef huart2;

// Function Prototypes
void SystemClock_Config(void);
static void MX_GPIO_Init(void);
static void MX_I2C1_Init(void);
static void MX_USART2_UART_Init(void);
void MPU6050_Init(void);
void MPU6050_ReadAccel(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z);
void MPU6050_ReadGyro(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void ProcessSensorData(int16_t accel_x, int16_t accel_y, int16_t accel_z,
                       float *pitch, float *roll);
void SendDataOverUART(float pitch, float roll, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z);

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_I2C1_Init();
    MX_USART2_UART_Init();

    MPU6050_Init();  // Initialize MPU6050

    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;
    float pitch, roll;

    while (1) {
        // Read sensor data
        MPU6050_ReadAccel(&accel_x, &accel_y, &accel_z);
        MPU6050_ReadGyro(&gyro_x, &gyro_y, &gyro_z);

        // Process data (calculate pitch and roll)
        ProcessSensorData(accel_x, accel_y, accel_z, &pitch, &roll);

        // Send data over UART for debugging
        SendDataOverUART(pitch, roll, gyro_x, gyro_y, gyro_z);

        HAL_Delay(100);  // 10Hz sampling rate
    }
}

/**
  * @brief  Initialize MPU6050 sensor
  * @param  None
  * @retval None
  */
void MPU6050_Init(void) {
    uint8_t data[2];

    // Wake up MPU6050 (disable sleep mode)
    data[0] = MPU6050_PWR_MGMT_1;
    data[1] = 0x00;
    HAL_I2C_Master_Transmit(&hi2c1, MPU6050_ADDR, data, 2, HAL_MAX_DELAY);

    // Set sample rate (divider = 7 for 1kHz / (7+1) = 125Hz)
    data[0] = MPU6050_SMPLRT_DIV;
    data[1] = 0x07;
    HAL_I2C_Master_Transmit(&hi2c1, MPU6050_ADDR, data, 2, HAL_MAX_DELAY);

    // Configure DLPF (Digital Low-Pass Filter) for accelerometer and gyro
    data[0] = MPU6050_CONFIG;
    data[1] = 0x00;  // 260Hz bandwidth, 0ms delay
    HAL_I2C_Master_Transmit(&hi2c1, MPU6050_ADDR, data, 2, HAL_MAX_DELAY);

    // Set gyro range to ±250°/s
    data[0] = MPU6050_GYRO_CONFIG;
    data[1] = 0x00;
    HAL_I2C_Master_Transmit(&hi2c1, MPU6050_ADDR, data, 2, HAL_MAX_DELAY);

    // Set accelerometer range to ±2g
    data[0] = MPU6050_ACCEL_CONFIG;
    data[1] = 0x00;
    HAL_I2C_Master_Transmit(&hi2c1, MPU6050_ADDR, data, 2, HAL_MAX_DELAY);
}

/**
  * @brief  Read accelerometer data from MPU6050
  * @param  accel_x, accel_y, accel_z: Pointers to store accelerometer data
  * @retval None
  */
void MPU6050_ReadAccel(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    uint8_t data[6];
    uint8_t reg = MPU6050_ACCEL_XOUT_H;

    // Read 6 bytes starting from ACCEL_XOUT_H
    HAL_I2C_Master_Transmit(&hi2c1, MPU6050_ADDR, &reg, 1, HAL_MAX_DELAY);
    HAL_I2C_Master_Receive(&hi2c1, MPU6050_ADDR, data, 6, HAL_MAX_DELAY);

    // Combine high and low bytes (big-endian)
    *accel_x = (int16_t)(data[0] << 8 | data[1]);
    *accel_y = (int16_t)(data[2] << 8 | data[3]);
    *accel_z = (int16_t)(data[4] << 8 | data[5]);
}

/**
  * @brief  Read gyroscope data from MPU6050
  * @param  gyro_x, gyro_y, gyro_z: Pointers to store gyroscope data
  * @retval None
  */
void MPU6050_ReadGyro(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t data[6];
    uint8_t reg = MPU6050_GYRO_XOUT_H;

    // Read 6 bytes starting from GYRO_XOUT_H
    HAL_I2C_Master_Transmit(&hi2c1, MPU6050_ADDR, &reg, 1, HAL_MAX_DELAY);
    HAL_I2C_Master_Receive(&hi2c1, MPU6050_ADDR, data, 6, HAL_MAX_DELAY);

    // Combine high and low bytes (big-endian)
    *gyro_x = (int16_t)(data[0] << 8 | data[1]);
    *gyro_y = (int16_t)(data[2] << 8 | data[3]);
    *gyro_z = (int16_t)(data[4] << 8 | data[5]);
}

/**
  * @brief  Process accelerometer data to calculate pitch and roll angles
  * @param  accel_x, accel_y, accel_z: Raw accelerometer data
  * @param  pitch, roll: Pointers to store calculated angles (in degrees)
  * @retval None
  */
void ProcessSensorData(int16_t accel_x, int16_t accel_y, int16_t accel_z,
                       float *pitch, float *roll) {
    // Convert raw data to g-force (assuming ±2g range)
    float ax = accel_x / ACCEL_SCALE;
    float ay = accel_y / ACCEL_SCALE;
    float az = accel_z / ACCEL_SCALE;

    // Calculate pitch and roll (in degrees)
    *pitch = atan2(ay, az) * 180.0f / 3.14159f;
    *roll  = atan2(-ax, sqrt(ay * ay + az * az)) * 180.0f / 3.14159f;
}

/**
  * @brief  Send sensor data over UART for debugging
  * @param  pitch, roll: Angles in degrees
  * @param  gyro_x, gyro_y, gyro_z: Raw gyroscope data
  * @retval None
  */
void SendDataOverUART(float pitch, float roll, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    char msg[100];
    sprintf(msg, "Pitch: %.2f° | Roll: %.2f° | Gyro: %d, %d, %d\r\n",
            pitch, roll, gyro_x, gyro_y, gyro_z);
    HAL_UART_Transmit(&huart2, (uint8_t*)msg, strlen(msg), HAL_MAX_DELAY);
}

