#### **`filter.c`**
```c
#include "filter.h"

float filter_apply(float new_value, float *buffer, uint8_t *index, uint8_t window_size) {
    buffer[*index] = new_value;
    *index = (*index + 1) % window_size;

    float sum = 0.0f;
    for (uint8_t i = 0; i < window_size; i++) {
        sum += buffer[i];
    }
    return sum / window_size;
}
