### **Code (`main.c`)**
```c
#include "stm32f4xx_hal.h"

I2C_HandleTypeDef hi2c1;
UART_HandleTypeDef huart2;

// TMP102 I2C address (7-bit)
#define TMP102_ADDR (0x48 << 1)

// Moving average filter
#define WINDOW_SIZE 5
float temp_readings[WINDOW_SIZE];
uint8_t current_index = 0;
float sum = 0.0f;

void SystemClock_Config(void);
static void MX_GPIO_Init(void);
static void MX_I2C1_Init(void);
static void MX_USART2_UART_Init(void);
void Error_Handler(void);

float read_temperature(void);
float moving_average(float new_value);

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_I2C1_Init();
    MX_USART2_UART_Init();

    // Initialize moving average buffer
    for (int i = 0; i < WINDOW_SIZE; i++) {
        temp_readings[i] = 0.0f;
    }

    while (1) {
        float temp = read_temperature();
        float avg_temp = moving_average(temp);

        // Print to UART
        char msg[50];
        sprintf(msg, "Temp: %.2f°C (Avg: %.2f°C)\r\n", temp, avg_temp);
        HAL_UART_Transmit(&huart2, (uint8_t*)msg, strlen(msg), HAL_MAX_DELAY);

        HAL_Delay(1000); // Read every second
    }
}

float read_temperature(void) {
    uint8_t data[2];
    uint8_t reg = 0x00; // Temperature register

    // Read temperature register
    if (HAL_I2C_Master_Transmit(&hi2c1, TMP102_ADDR, &reg, 1, HAL_MAX_DELAY) != HAL_OK) {
        Error_Handler();
    }

    if (HAL_I2C_Master_Receive(&hi2c1, TMP102_ADDR, data, 2, HAL_MAX_DELAY) != HAL_OK) {
        Error_Handler();
    }

    // Convert raw data to temperature (12-bit, 0.0625°C per LSB)
    int16_t raw = (data[0] << 4) | (data[1] >> 4);
    return raw * 0.0625f;
}

float moving_average(float new_value) {
    sum -= temp_readings[current_index];
    sum += new_value;
    temp_readings[current_index] = new_value;
    current_index = (current_index + 1) % WINDOW_SIZE;
    return sum / WINDOW_SIZE;
}

