### **Minimal Firmware Example (Arduino-style)**
```cpp
#include <Wire.h>       // I2C library
#include <SoftwareSerial.h> // For debugging (optional)

// Sensor I2C address (TMP102 default address)
#define SENSOR_ADDR 0x48

void setup() {
    // Initialize serial for debugging (9600 baud)
    Serial.begin(9600);

    // Initialize I2C
    Wire.begin();

    // Optional: Configure sensor (e.g., set resolution)
    Wire.beginTransmission(SENSOR_ADDR);
    Wire.write(0x01); // Pointer register for configuration
    Wire.write(0x60); // 12-bit resolution, shutdown mode disabled
    Wire.endTransmission();
}

void loop() {
    // Request temperature reading from sensor
    Wire.beginTransmission(SENSOR_ADDR);
    Wire.write(0x00); // Pointer register for temperature
    Wire.endTransmission(false); // Send restart (no stop)

    // Read 2 bytes of temperature data
    Wire.requestFrom(SENSOR_ADDR, 2);
    uint8_t msb = Wire.read();
    uint8_t lsb = Wire.read();

    // Combine bytes and convert to temperature (TMP102: 12-bit, 0.0625°C/LSB)
    int16_t rawTemp = ((msb << 8) | lsb) >> 4;
    float temperature = rawTemp * 0.0625;

    // Output temperature via UART
    Serial.print("Temperature: ");
    Serial.print(temperature);
    Serial.println(" °C");

    delay(1000); // Wait 1 second
}
```

