/**
 * Minimal firmware for STM32 reading and processing BME280 sensor data.
 * Target: STM32F401RE (Nucleo board) with BME280 over I2C.
 * Language: C (using STM32 HAL)
 */

#include "stm32f4xx_hal.h"

// --- BME280 Definitions ---
#define BME280_ADDR         (0x76 << 1)  // I2C address (shifted for 7-bit)
#define BME280_REG_ID       0xD0         // Chip ID register
#define BME280_REG_CTRL_MEAS 0xF4        // Control measurement register
#define BME280_REG_DATA     0xF7         // Data register (starts with pressure)

// --- Global Variables ---
I2C_HandleTypeDef hi2c1;  // I2C handle
UART_HandleTypeDef huart2; // UART handle (for debugging)

// --- Helper Functions ---
void SystemClock_Config(void);
static void MX_GPIO_Init(void);
static void MX_I2C1_Init(void);
static void MX_USART2_UART_Init(void);

// --- BME280 Functions ---
uint8_t bme280_read_reg(uint8_t reg) {
    uint8_t data = 0;
    HAL_I2C_Mem_Read(&hi2c1, BME280_ADDR, reg, 1, &data, 1, 100);
    return data;
}

void bme280_write_reg(uint8_t reg, uint8_t value) {
    HAL_I2C_Mem_Write(&hi2c1, BME280_ADDR, reg, 1, &value, 1, 100);
}

void bme280_init(void) {
    // Check chip ID (should be 0x60 for BME280)
    uint8_t chip_id = bme280_read_reg(BME280_REG_ID);
    if (chip_id != 0x60) {
        while(1); // Error: Sensor not detected
    }

    // Configure sensor (oversampling x1, normal mode)
    bme280_write_reg(BME280_REG_CTRL_MEAS, 0x25);
}

float bme280_read_temperature(void) {
    // Read raw temperature data (3 bytes: MSB, LSB, XLSB)
    uint8_t raw[3] = {0};
    HAL_I2C_Mem_Read(&hi2c1, BME280_ADDR, BME280_REG_DATA, 1, raw, 3, 100);

    // Combine bytes (simplified; real BME280 requires compensation)
    int32_t raw_temp = (raw[0] << 16) | (raw[1] << 8) | raw[2];
    raw_temp >>= 4; // Adjust for 20-bit data

    // Simplified conversion (real BME280 requires calibration)
    float temp = (float)raw_temp / 100.0f;
    return temp;
}

// --- Main Application ---
int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_I2C1_Init();
    MX_USART2_UART_Init();

    bme280_init();

    float temp_filtered = 0.0f;
    float temp_samples[5] = {0};
    uint8_t sample_idx = 0;

    while (1) {
        // Read temperature
        float temp = bme280_read_temperature();

        // Moving average filter (5 samples)
        temp_samples[sample_idx] = temp;
        sample_idx = (sample_idx + 1) % 5;

        temp_filtered = 0.0f;
        for (uint8_t i = 0; i < 5; i++) {
            temp_filtered += temp_samples[i];
        }
        temp_filtered /= 5.0f;

        // Print via UART (for debugging)
        char msg[50];
        sprintf(msg, "Temp: %.2f°C (Filtered: %.2f°C)\r\n", temp, temp_filtered);
        HAL_UART_Transmit(&huart2, (uint8_t*)msg, strlen(msg), HAL_MAX_DELAY);

        HAL_Delay(1000); // 1-second interval
    }
}

// --- STM32 HAL Callbacks ---
void SystemClock_Config(void) {
    RCC_OscInitTypeDef RCC_OscInitStruct = {0};
    RCC_ClkInitTypeDef RCC_ClkInitStruct = {0};

    RCC_OscInitStruct.OscillatorType = RCC_OSCILLATORTYPE_HSE;
    RCC_OscInitStruct.HSEState = RCC_HSE_ON;
    RCC_OscInitStruct.PLL.PLLState = RCC_PLL_ON;
    RCC_OscInitStruct.PLL.PLLSource = RCC_PLLSOURCE_HSE;
