class Sensor {
public:
    Sensor(uint32_t windowSize = 5);
    void read();           // Simulate reading from sensor
    void process();        // Apply moving average filter
    float getFilteredValue() const;
    float getRawValue() const;

private:
    float rawValue;
    float filteredValue;
    std::array<float, 10> window; // Circular buffer for moving average
