### 📄 `Core/Src/sensor.cpp`
```cpp
#include "sensor.h"
#include <cstdlib> // for rand()

Sensor::Sensor(uint32_t windowSize) : windowSize(windowSize), index(0) {
    window.fill(0.0f);
    rawValue = 0.0f;
    filteredValue = 0.0f;
}

void Sensor::read() {
    // Simulate sensor reading: random value between 20.0 and 30.0
    rawValue = 20.0f + (static_cast<float>(rand()) / RAND_MAX) * 10.0f;
}

void Sensor::process() {
    // Add new value to window
    window[index] = rawValue;
    index = (index + 1) % windowSize;

    // Compute moving average
    float sum = 0.0f;
    uint32_t count = 0;
    for (uint32_t i = 0; i < windowSize; ++i) {
        if (window[i] != 0.0f) { // Skip uninitialized values
            sum += window[i];
            count++;
        }
    }
    filteredValue = (count > 0) ? sum / count : rawValue;
}

float Sensor::getFilteredValue() const { return filteredValue; }
float Sensor::getRawValue() const { return rawValue; }
