    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_USART3_UART_Init();
    MX_TIM2_Init();

    // Initialize random seed
    srand(HAL_GetTick());

    // Initialize sensor and UART
    Sensor sensor(5); // 5-point moving average
    USART_Init();

    // Start timer for periodic sampling (e.g., every 100ms)
    HAL_TIM_Base_Start_IT(&htim2);

    while (1) {
        // Main loop: nothing to do here since we're using interrupts
        // All processing happens in timer interrupt
    }
}

// Timer interrupt callback (called every 100ms)
extern "C" void HAL_TIM_PeriodElapsedCallback(TIM_HandleTypeDef *htim) {
    if (htim->Instance == TIM2) {
        Sensor sensor(5); // Create instance (in real code, use global or static)

        // Read and process sensor data
        sensor.read();
        sensor.process();

        // Output results
        USART_PrintFloat(sensor.getRawValue());
        USART_Transmit(" -> ");
        USART_PrintFloat(sensor.getFilteredValue());
    }
}

// Weak definitions to avoid linker errors
extern "C" void Error_Handler(void) {
