/**
  ******************************************************************************
  * @file           : main.c
  * @brief          : Minimal firmware to read TMP102 sensor over I2C and output temperature via UART
  ******************************************************************************
  * This code is for STM32F401RE (Nucleo board) using STM32 HAL.
  ******************************************************************************
  */

#include "stm32f4xx_hal.h"

I2C_HandleTypeDef hi2c1;
UART_HandleTypeDef huart2;

void SystemClock_Config(void);
static void MX_GPIO_Init(void);
static void MX_I2C1_Init(void);
static void MX_USART2_UART_Init(void);

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_I2C1_Init();
    MX_USART2_UART_Init();

    uint8_t sensor_addr = 0x48 << 1; // TMP102 I2C address (7-bit), shifted for 8-bit write
    uint8_t reg_addr = 0x00;         // Temperature register
    uint8_t data[2];
    float temperature = 0.0f;

    char msg[50];

    while (1) {
        // Read 2 bytes from TMP102
        if (HAL_I2C_Master_Transmit(&hi2c1, sensor_addr, &reg_addr, 1, HAL_MAX_DELAY) != HAL_OK) {
            sprintf(msg, "I2C Transmit Error\r\n");
            HAL_UART_Transmit(&huart2, (uint8_t*)msg, strlen(msg), HAL_MAX_DELAY);
            continue;
        }

        if (HAL_I2C_Master_Receive(&hi2c1, sensor_addr, data, 2, HAL_MAX_DELAY) != HAL_OK) {
            sprintf(msg, "I2C Receive Error\r\n");
            HAL_UART_Transmit(&huart2, (uint8_t*)msg, strlen(msg), HAL_MAX_DELAY);
            continue;
        }

        // Convert raw data to temperature (12-bit, left-justified)
        int16_t raw_temp = ((data[0] << 8) | data[1]) >> 4;
        temperature = raw_temp * 0.0625f; // Each LSB = 0.0625°C

        // Format and send over UART
        sprintf(msg, "Temperature: %.2f °C\r\n", temperature);
        HAL_UART_Transmit(&huart2, (uint8_t*)msg, strlen(msg), HAL_MAX_DELAY);

        HAL_Delay(1000); // Read every second
    }
}

