    void setPower(double power) {
        // Clamp power to [-1.0, 1.0]
        currentPower = std::clamp(power, -1.0, 1.0);
    }

    double getPosition() const { return position; }
    double getVelocity() const { return velocity; }

    void update(double dt) {
        // Simple motor model: power affects velocity with some inertia
        velocity += (currentPower * 10.0 - velocity * 2.0) * dt;
        position += velocity * dt;
    }

private:
    double currentPower = 0.0;
    double velocity = 0.0;
    double position = 0.0;
};

// PID controller with anti-windup
class PIDController {
public:
    PIDController(double Kp, double Ki, double Kd, double outputMin, double outputMax)
        : Kp(Kp), Ki(Ki), Kd(Kd), outputMin(outputMin), outputMax(outputMax) {}

    double update(double error, double dt) {
        integral += error * dt;

        // Anti-windup: clamp integral term
        if (integral > outputMax) integral = outputMax;
        else if (integral < outputMin) integral = outputMin;

        double derivative = (error - prevError) / dt;
        prevError = error;

        double output = Kp * error + Ki * integral + Kd * derivative;

        // Clamp final output
        return std::clamp(output, outputMin, outputMax);
    }

    void reset() {
        integral = 0.0;
        prevError = 0.0;
    }

private:
    double Kp, Ki, Kd;
    double integral = 0.0;
    double prevError = 0.0;
    double outputMin, outputMax;
};

// Sensor fusion (complementary filter)
class OrientationEstimator {
public:
    void update(double gyroX, double gyroY, double gyroZ,
                double accelX, double accelY, double accelZ,
                double dt) {
        // Calculate accelerometer angles (roll and pitch)
        double accelRoll = atan2(accelY, accelZ);
        double accelPitch = atan2(-accelX, sqrt(accelY*accelY + accelZ*accelZ));

        // Gyro integration (in rad/s)
        rollRate = gyroX;
        pitchRate = gyroY;
        yawRate = gyroZ;

        // Apply complementary filter
        roll = COMPLEMENTARY_FILTER_ALPHA * (roll + rollRate * dt) +
               (1 - COMPLEMENTARY_FILTER_ALPHA) * accelRoll;
        pitch = COMPLEMENTARY_FILTER_ALPHA * (pitch + pitchRate * dt) +
                (1 - COMPLEMENTARY_FILTER_ALPHA) * accelPitch;
        yaw += yawRate * dt; // Yaw is only from gyro (no magnetometer)
    }

    double getRoll() const { return roll; }
    double getPitch() const { return pitch; }
    double getYaw() const { return yaw; }
    double getRollRate() const { return rollRate; }
    double getPitchRate() const { return pitchRate; }

private:
    double roll = 0.0;
    double pitch = 0.0;
    double yaw = 0.0;
    double rollRate = 0.0;
    double pitchRate = 0.0;
    double yawRate = 0.0;
};

int main() {
    IMU imu;
    Motor leftMotor, rightMotor;
    PIDController rollPID(1.5, 0.5, 0.1, -1.0, 1.0);  // Roll controller
    PIDController pitchPID(1.2, 0.3, 0.08, -1.0, 1.0); // Pitch controller
    OrientationEstimator estimator;

    // Initialize timing
    auto lastTime = std::chrono::high_resolution_clock::now();
    auto nextTime = lastTime + std::chrono::milliseconds(10); // 100Hz target

    std::cout << "Starting robotics control loop (100Hz)...\n";
    std::cout << "Press Ctrl+C to exit.\n\n";

    while (true) {
        // Wait until next cycle (busy-wait for better accuracy)
        auto currentTime = std::chrono::high_resolution_clock::now();
        if (currentTime < nextTime) {
            std::this_thread::sleep_until(nextTime);
        }
        nextTime += std::chrono::milliseconds(10);

        // Calculate actual dt
        double dt = std::chrono::duration<double>(nextTime - lastTime).count();
        lastTime = nextTime;

        // Read sensors
        double gyroX, gyroY, gyroZ, accelX, accelY, accelZ;
        imu.read(gyroX, gyroY, gyroZ, accelX, accelY, accelZ);

        // Sensor fusion
        estimator.update(gyroX, gyroY, gyroZ, accelX, accelY, accelZ, dt);

        // Get current orientation
        double roll = estimator.getRoll();
        double pitch = estimator.getPitch();

        // Control: try to maintain level (roll=0, pitch=0)
        double rollError = -roll;    // Negative because we want to correct the error
        double pitchError = -pitch;

        // Update motors based on errors
        double leftPower = rollPID.update(rollError, dt);
        double rightPower = pitchPID.update(pitchError, dt);

        // Apply motor commands
        leftMotor.setPower(leftPower);
        rightMotor.setPower(rightPower);

        // Update motor state
        leftMotor.update(dt);
        rightMotor.update(dt);

        // Print debug info (every 100 cycles to reduce output)
        static int counter = 0;
        if (++counter % 100 == 0) {
            std::cout << "Roll: " << roll << "°  Pitch: " << pitch << "°  "
                      << "Left: " << leftPower << "  Right: " << rightPower << "\r";
            std::cout.flush();
        }
    }

    return 0;
}
