// Sensor Fusion Class (Complementary Filter)
class SensorFusion {
private:
    RobotState state_;
    std::mutex state_mutex_;
    double gyro_bias_x_ = 0.0;
    double gyro_bias_y_ = 0.0;
    double gyro_bias_z_ = 0.0;

public:
    void update(const IMUData& imu, const EncoderData& encoder) {
        std::lock_guard<std::mutex> lock(state_mutex_);

        // Remove gyro bias (simple calibration)
        double gyro_x = imu.gyro_x - gyro_bias_x_;
        double gyro_y = imu.gyro_y - gyro_bias_y_;
        double gyro_z = imu.gyro_z - gyro_bias_z_;

        // Complementary filter for roll and pitch
        // Accelerometer gives absolute angle (low frequency)
        // Gyro gives rate of change (high frequency)
        double accel_roll = atan2(imu.accel_y, imu.accel_z);
        double accel_pitch = atan2(-imu.accel_x, sqrt(imu.accel_y * imu.accel_y + imu.accel_z * imu.accel_z));

        // Update angles using complementary filter
        state_.roll = COMPLEMENTARY_FILTER_ALPHA * (state_.roll + gyro_x * DT) +
                      (1 - COMPLEMENTARY_FILTER_ALPHA) * accel_roll;
        state_.pitch = COMPLEMENTARY_FILTER_ALPHA * (state_.pitch + gyro_y * DT) +
                       (1 - COMPLEMENTARY_FILTER_ALPHA) * accel_pitch;

        // Simple yaw integration (no magnetometer in this example)
        state_.yaw += gyro_z * DT;

        // Update position and velocity from encoders
        state_.position = encoder.position;
        state_.velocity = encoder.velocity;
    }

    RobotState getState() const {
        std::lock_guard<std::mutex> lock(state_mutex_);
        return state_;
    }

    void calibrateGyro(const std::vector<IMUData>& samples, int num_samples) {
        if (num_samples <= 0) return;

        gyro_bias_x_ = 0.0;
        gyro_bias_y_ = 0.0;
        gyro_bias_z_ = 0.0;

        for (int i = 0; i < num_samples; ++i) {
            gyro_bias_x_ += samples[i].gyro_x;
            gyro_bias_y_ += samples[i].gyro_y;
            gyro_bias_z_ += samples[i].gyro_z;
        }

        gyro_bias_x_ /= num_samples;
        gyro_bias_y_ /= num_samples;
        gyro_bias_z_ /= num_samples;
    }
};

// Motor Controller Class
class MotorController {
private:
    PIDParams pid_params_;
    double setpoint_ = 0.0;
    double output_ = 0.0;
    double integral_ = 0.0;
    double prev_error_ = 0.0;

public:
    MotorController(const PIDParams& params) : pid_params_(params) {}

    void setSetpoint(double setpoint) {
        setpoint_ = setpoint;
    }

    double getOutput() const {
        return output_;
    }

    void reset() {
        integral_ = 0.0;
        prev_error_ = 0.0;
        output_ = 0.0;
    }

    MotorCommand update(double measurement) {
        double error = setpoint_ - measurement;

        // Proportional term
        double proportional = pid_params_.Kp * error;

        // Integral term with anti-windup
        integral_ += error * DT;
        if (integral_ > pid_params_.integral_max) {
            integral_ = pid_params_.integral_max;
        } else if (integral_ < -pid_params_.integral_max) {
            integral_ = -pid_params_.integral_max;
        }
        double integral = pid_params_.Ki * integral_;

        // Derivative term
        double derivative = pid_params_.Kd * (error - prev_error_) / DT;
        prev_error_ = error;

        // Calculate output
        output_ = proportional + integral + derivative;

        // Clamp output
        if (output_ > pid_params_.output_max) {
            output_ = pid_params_.output_max;
        } else if (output_ < -pid_params_.output_max) {
            output_ = -pid_params_.output_max;
        }

        return {output_};
    }
};

