// Simple Kalman Filter for 1D angle estimation
class KalmanFilter {
private:
    double angle;       // Estimated angle (rad)
    double angle_rate;  // Estimated angle rate (rad/s)
    double P_angle;     // Estimate error covariance for angle
    double P_angle_rate;// Estimate error covariance for angle rate
    const double Q_angle = 0.01;     // Process noise covariance
    const double Q_angle_rate = 0.01;// Process noise covariance
    const double R_angle = 0.1;     // Measurement noise covariance

public:
    KalmanFilter() : angle(0.0), angle_rate(0.0),
                    P_angle(0.1), P_angle_rate(0.1) {}

    void predict(double dt) {
        // State transition: angle += angle_rate * dt
        angle += angle_rate * dt;

        // Update covariance (simplified model)
        P_angle += dt * (dt * P_angle_rate + Q_angle);
        P_angle_rate += Q_angle_rate;
    }

    void update(double measured_angle) {
        // Kalman gain for angle
        double K_angle = P_angle / (P_angle + R_angle);

        // Update angle estimate
        angle += K_angle * (measured_angle - angle);
        // Update covariance
        P_angle *= (1 - K_angle);
    }

    double getAngle() const { return angle; }
    double getAngleRate() const { return angle_rate; }
};

// PID Controller for motor control
class PIDController {
private:
    double Kp, Ki, Kd;
    double prev_error;
    double integral;
    const double dt;

public:
    PIDController(double kp, double ki, double kd, double dt)
        : Kp(kp), Ki(ki), Kd(kd), dt(dt),
          prev_error(0.0), integral(0.0) {}

    double compute(double setpoint, double measured) {
        double error = setpoint - measured;
        integral += error * dt;
        double derivative = (error - prev_error) / dt;
        prev_error = error;
        return Kp * error + Ki * integral + Kd * derivative;
    }

    void reset() {
        integral = 0.0;
        prev_error = 0.0;
    }
};

