// ======================
// Sensor Fusion (Kalman Filter)
// ======================
class KalmanFilter {
public:
    struct State {
        double position;
        double velocity;
    };

    KalmanFilter() {
        // Initialize state
        state_.position = 0.0;
        state_.velocity = 0.0;

        // Initial state covariance
        P_(0, 0) = 1.0;
        P_(1, 1) = 1.0;

        // Process noise covariance
        Q_(0, 0) = 0.01;  // Position noise
        Q_(1, 1) = 0.1;   // Velocity noise

        // Measurement noise covariance
        R_accel_ = 0.1;
        R_encoder_ = 0.05;
    }

    void predict(double dt) {
        // State transition matrix F
        Eigen::Matrix2d F;
        F << 1, dt,
             0, 1;

        // Process noise matrix
        Eigen::Matrix2d Q = Q_;

        // Predict state
        state_ = F * state_;

        // Predict covariance
        P_ = F * P_ * F.transpose() + Q;
    }

    void updateIMU(const IMU::Data& imu_data, double dt) {
        // Measurement matrix for IMU (acceleration)
        Eigen::Matrix<double, 1, 2> H;
        H << 1, 0;  // We'll use acceleration to estimate position

        // Measurement noise
        double R = R_accel_;

        // Kalman gain
        Eigen::Matrix<double, 2, 1> K = P_ * H.transpose() / (H * P_ * H.transpose() + R);

        // Measurement residual
        double residual = imu_data.accel_x - state_.position;

        // Update state
        state_.position += K(0, 0) * residual;
        state_.velocity += K(1, 0) * residual;

        // Update covariance
        Eigen::Matrix2d I = Eigen::Matrix2d::Identity();
        P_ = (I - K * H) * P_;
    }

    void updateEncoder(const Encoder::Data& encoder_data) {
        // Measurement matrix for encoder
        Eigen::Matrix<double, 1, 2> H;
        H << 1, 0;  // Using position measurement

        // Measurement noise
        double R = R_encoder_;

        // Kalman gain
        Eigen::Matrix<double, 2, 1> K = P_ * H.transpose() / (H * P_ * H.transpose() + R);

        // Measurement residual
        double residual = encoder_data.position - state_.position;

        // Update state
        state_.position += K(0, 0) * residual;
        state_.velocity += K(1, 0) * residual;

        // Update covariance
        Eigen::Matrix2d I = Eigen::Matrix2d::Identity();
        P_ = (I - K * H) * P_;
    }

    State getState() const { return state_; }

private:
    State state_;
    Eigen::Matrix2d P_;  // State covariance
    Eigen::Matrix2d Q_;  // Process noise covariance
    double R_accel_;     // IMU measurement noise
    double R_encoder_;   // Encoder measurement noise
};

// ======================
// Motor Control (PID Controller)
// ======================
class PIDController {
public:
    PIDController(double Kp, double Ki, double Kd, double max_output, double min_output)
        : Kp_(Kp), Ki_(Ki), Kd_(Kd),
          max_output_(max_output), min_output_(min_output),
          integral_(0.0), prev_error_(0.0) {}

    double compute(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;

        // Proportional term
        double P = Kp_ * error;

        // Integral term with anti-windup
        integral_ += error * dt;
        double I = Ki_ * integral_;

        // Derivative term (filtered)
        double derivative = (error - prev_error_) / dt;
        prev_error_ = error;
        double D = Kd_ * derivative;

        // Compute output
        double output = P + I + D;

        // Clamp output
        output = std::clamp(output, min_output_, max_output_);

        return output;
    }

    void reset() {
        integral_ = 0.0;
        prev_error_ = 0.0;
    }

private:
    double Kp_, Ki_, Kd_;
    double max_output_, min_output_;
    double integral_;
    double prev_error_;
};

