        H << 1.0, 0.0;

        // Kalman gain
        Eigen::Matrix<double, 2, 1> K = P * H.transpose() / (H * P * H.transpose() + R);

        // Update state
        state = state + K * (z(0) - H * state);

        // Update covariance
        P = (Eigen::Matrix2d::Identity() - K * H) * P;
    }

    double getAngle() const { return state(0); }
    double getAngleRate() const { return state(1); }
};

