        // Accelerometer measures angle relative to gravity (noisy)
        accel_angle = true_angle_ + noise_ * (rand() / (double)RAND_MAX - 0.5);

        // Gyroscope measures angular velocity (noisy)
        gyro_rate = true_angular_velocity_ + noise_ * (rand() / (double)RAND_MAX - 0.5);
    }

    void update(double motor_torque, double dt) {
        // Simulate system dynamics: inverted pendulum with motor torque
        // torque = I * alpha => alpha = torque / I (simplified with I=1)
        true_angular_velocity_ += (motor_torque - 0.1 * true_angular_velocity_) * dt;
        true_angle_ += true_angular_velocity_ * dt;

        // Add external disturbance (e.g., ground vibration)
        true_angle_ += 0.005 * (rand() / (double)RAND_MAX - 0.5);
    }

    double getTrueAngle() const { return true_angle_; }

private:
    double true_angle_ = 0.1;      // Initial tilt angle (slightly off balance)
    double true_angular_velocity_ = 0.0;
