// Complementary Filter for sensor fusion
class ComplementaryFilter {
public:
    ComplementaryFilter(double alpha = 0.98) : alpha_(alpha) {}

    double update(double accel_angle, double gyro_rate, double dt) {
        // Fuse accelerometer (low-frequency) and gyroscope (high-frequency) data
        angle_ = alpha_ * (angle_ + gyro_rate * dt) + (1 - alpha_) * accel_angle;
        return angle_;
    }

private:
