// Simple 3D vector class
struct Vec3 {
    double x, y, z;
    Vec3(double x = 0, double y = 0, double z = 0) : x(x), y(y), z(z) {}
};

// IMU sensor class (simulated)
class IMU {
public:
    IMU() : accel_(0, 0, 9.81), gyro_(0, 0, 0) {} // Simulated gravity

    void read(Vec3& accel, Vec3& gyro) {
        std::lock_guard<std::mutex> lock(mutex_);
        accel = accel_;
        gyro = gyro_;
    }

    void setAccel(const Vec3& accel) {
        std::lock_guard<std::mutex> lock(mutex_);
        accel_ = accel;
    }

    void setGyro(const Vec3& gyro) {
        std::lock_guard<std::mutex> lock(mutex_);
        gyro_ = gyro;
    }

private:
    Vec3 accel_;
    Vec3 gyro_;
    std::mutex mutex_;
};

// Encoder sensor class (simulated)
class Encoder {
public:
    Encoder() : position_(0), velocity_(0) {}

    void read(double& position, double& velocity) {
        std::lock_guard<std::mutex> lock(mutex_);
        position = position_;
        velocity = velocity_;
    }

    void setPosition(double pos) {
        std::lock_guard<std::mutex> lock(mutex_);
        position_ = pos;
    }

    void setVelocity(double vel) {
        std::lock_guard<std::mutex> lock(mutex_);
        velocity_ = vel;
    }

private:
    double position_;
    double velocity_;
    std::mutex mutex_;
};

// Complementary filter for orientation estimation
class ComplementaryFilter {
public:
    ComplementaryFilter(double alpha = 0.98) : alpha_(alpha) {}

    void update(const Vec3& accel, const Vec3& gyro, double dt, Vec3& orientation) {
        // Roll and pitch from accelerometer
        double roll_acc  = atan2(accel.y, accel.z);
        double pitch_acc = atan2(-accel.x, sqrt(accel.y * accel.y + accel.z * accel.z));

        // Integrate gyro data (simplified)
        roll_  += gyro.x * dt;
        pitch_ += gyro.y * dt;

        // Complementary filter (combines gyro and accel)
        orientation.x = alpha_ * roll_ + (1 - alpha_) * roll_acc;
        orientation.y = alpha_ * pitch_ + (1 - alpha_) * pitch_acc;
        orientation.z = 0; // Yaw not estimated here
    }

private:
    double alpha_;
    double roll_ = 0;
    double pitch_ = 0;
};

// PID controller for motor control
class PIDController {
public:
    PIDController(double kp, double ki, double kd, double dt)
        : kp_(kp), ki_(ki), kd_(kd), dt_(dt), integral_(0), prev_error_(0) {}

    double compute(double setpoint, double measurement) {
        double error = setpoint - measurement;
        integral_ += error * dt_;
        double derivative = (error - prev_error_) / dt_;
        prev_error_ = error;

        return kp_ * error + ki_ * integral_ + kd_ * derivative;
    }

    void reset() {
        integral_ = 0;
        prev_error_ = 0;
    }

private:
    double kp_, ki_, kd_, dt_;
    double integral_;
    double prev_error_;
};

// Main robot control loop
class RobotControlLoop {
public:
    RobotControlLoop(double loop_rate_hz = 100.0)
        : imu_(), encoder_(), filter_(0.98),
          pid_x_(1.0, 0.1, 0.05, 1.0/loop_rate_hz),
          pid_y_(1.0, 0.1, 0.05, 1.0/loop_rate_hz),
          running_(true) {}

    void start() {
        loop_thread_ = std::thread([this]() { run(); });
    }

    void stop() {
        running_ = false;
        if (loop_thread_.joinable()) {
            loop_thread_.join();
        }
    }

    void run() {
        auto last_time = std::chrono::steady_clock::now();
        const double dt = 1.0 / 100.0; // 100Hz loop rate

        while (running_) {
            auto now = std::chrono::steady_clock::now();
            double elapsed = std::chrono::duration<double>(now - last_time).count();
            last_time = now;

            // Read sensors
            Vec3 accel, gyro;
            imu_.read(accel, gyro);

            double position, velocity;
            encoder_.read(position, velocity);

            // Sensor fusion (orientation estimation)
            Vec3 orientation;
            filter_.update(accel, gyro, dt, orientation);

            // Control logic (example: balance on a moving platform)
            double motor_command_x = pid_x_.compute(0, position); // Target: 0 position
            double motor_command_y = pid_y_.compute(0, velocity); // Target: 0 velocity

            // Update motor commands (simulated)
            std::lock_guard<std::mutex> lock(mutex_);
            motor_commands_[0] = motor_command_x;
            motor_commands_[1] = motor_command_y;

            // Print debug info (replace with actual motor commands in real system)
            std::cout << "[Control Loop] dt=" << elapsed << "s, "
                      << "Orientation: [" << orientation.x << ", " << orientation.y << "], "
                      << "Motor: [" << motor_commands_[0] << ", " << motor_commands_[1] << "]\n";

            // Sleep to maintain real-time loop
            std::this_thread::sleep_for(std::chrono::milliseconds(static_cast<int>(dt * 1000)));
        }
    }

    // Get latest motor commands (thread-safe)
    std::vector<double> getMotorCommands() {
        std::lock_guard<std::mutex> lock(mutex_);
        return {motor_commands_[0], motor_commands_[1]};
    }

private:
    IMU imu_;
    Encoder encoder_;
    ComplementaryFilter filter_;
    PIDController pid_x_;
    PIDController pid_y_;
    std::thread loop_thread_;
    std::atomic<bool> running_;
    std::mutex mutex_;
    double motor_commands_[2] = {0, 0};
};

int main() {
    RobotControlLoop robot(100.0); // 100Hz control loop

    // Simulate sensor data (in a real system, this would come from hardware)
