    Vector3D gyro_bias;
    Vector3D angle;  // Estimated orientation (roll, pitch, yaw)

public:
    SensorFusion(double alpha = 0.98, Vector3D gyro_bias = {0, 0, 0})
        : alpha(alpha), gyro_bias(gyro_bias), angle({0, 0, 0}) {}

    // Update with gyroscope data (rad/s)
    void updateGyro(Vector3D gyro) {
        angle.x += gyro.x * 0.01;  // Assuming 100Hz loop (0.01s dt)
        angle.y += gyro.y * 0.01;
        angle.z += gyro.z * 0.01;
    }

    // Update with accelerometer data (m/s²) and apply complementary filter
    void updateAccel(Vector3D accel) {
        // Simple accelerometer-based roll/pitch (yaw is unreliable)
        double roll = atan2(accel.y, accel.z);
        double pitch = atan2(-accel.x, sqrt(accel.y * accel.y + accel.z * accel.z));

        // Apply complementary filter
        angle.x = alpha * angle.x + (1 - alpha) * roll;
        angle.y = alpha * angle.y + (1 - alpha) * pitch;
        // Yaw is not fused here (use magnetometer in a real system)
    }

    // Get estimated orientation
    Vector3D getAngle() const { return angle; }
};

#endif // SENSOR_FUSION_H
