public:
    MotorController(double kp = 1.0, double ki = 0.1, double kd = 0.01)
        : kp(kp), ki(ki), kd(kd), integral(0), prev_error(0), output(0) {}

    // Compute PID output (target vs. actual speed)
    double compute(double target_speed, double actual_speed) {
        double error = target_speed - actual_speed;
        integral += error;
        double derivative = error - prev_error;
        prev_error = error;

        output = kp * error + ki * integral + kd * derivative;
        return output;
    }

    // Reset PID state
    void reset() {
        integral = 0;
        prev_error = 0;
    }
};

#endif // MOTOR_CONTROLLER_H
