// Kalman Filter for IMU Orientation Estimation
class SensorFusion {
public:
    SensorFusion(double dt)
        : dt(dt), gyro_x(0), gyro_y(0), gyro_z(0) {
        // State: [roll, pitch, yaw, roll_rate, pitch_rate, yaw_rate]
        state = Eigen::VectorXd::Zero(6);
        P = Eigen::MatrixXd::Identity(6, 6) * 0.1;
        Q = Eigen::MatrixXd::Identity(6, 6) * 0.01;  // Process noise
        R = Eigen::MatrixXd::Identity(3, 3) * 0.5;   // Measurement noise
        H = Eigen::MatrixXd::Zero(3, 6);
        H(0, 0) = 1; // roll
        H(1, 1) = 1; // pitch
        H(2, 2) = 1; // yaw
    }

    void predict() {
        // Simple state transition: angles evolve via gyro rates
        state(0) += state(3) * dt;  // roll += roll_rate * dt
        state(1) += state(4) * dt;  // pitch += pitch_rate * dt
        state(2) += state(5) * dt;  // yaw += yaw_rate * dt

        // Add process noise
        P += Q;
    }

    void update(double accel_x, double accel_y, double accel_z,
                double gyro_x, double gyro_y, double gyro_z) {
        this->gyro_x = gyro_x;
        this->gyro_y = gyro_y;
        this->gyro_z = gyro_z;

        // Accelerometer-based roll/pitch (yaw not observable from accel)
        double roll_acc = atan2(accel_y, accel_z);
        double pitch_acc = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z));

        Eigen::VectorXd z(3);
        z << roll_acc, pitch_acc, 0;  // Assume yaw=0 for simplicity

        // Kalman Update
        Eigen::MatrixXd S = H * P * H.transpose() + R;
        Eigen::MatrixXd K = P * H.transpose() * S.inverse();
        state += K * (z - H * state);
        P = (Eigen::MatrixXd::Identity(6, 6) - K * H) * P;
    }

    Eigen::Vector3d getOrientation() const {
        return state.head<3>();
    }

private:
    double dt;
    double gyro_x, gyro_y, gyro_z;
    Eigen::VectorXd state;
    Eigen::MatrixXd P, Q, R, H;
};

