            std::vector<int> motor_pwms(4, 1000);  // Base PWM (neutral)
            motor_pwms[0] += roll_command + pitch_command;  // Front-left
            motor_pwms[1] += -roll_command + pitch_command; // Front-right
            motor_pwms[2] += -roll_command - pitch_command; // Rear-right
            motor_pwms[3] += roll_command - pitch_command;  // Rear-left

