// Simple Kalman filter for IMU fusion
class SensorFusion {
public:
    SensorFusion(double dt) : dt(dt) {
        // Initialize state: [roll, pitch, yaw, roll_rate, pitch_rate, yaw_rate]
        state = Eigen::VectorXd::Zero(6);
        // Initialize covariance matrix
        P = Eigen::MatrixXd::Identity(6, 6);
        // Process noise covariance
        Q = Eigen::MatrixXd::Identity(6, 6) * 0.01;
        // Measurement noise covariance
        R = Eigen::MatrixXd::Identity(3, 3) * 0.1;
        // Measurement matrix (we only measure roll, pitch, yaw)
        H = Eigen::MatrixXd::Zero(3, 6);
        H(0, 0) = 1; // roll
        H(1, 1) = 1; // pitch
        H(2, 2) = 1; // yaw
    }

    void predict() {
        // Simple prediction: state transition is identity for angles, and we add gyro rates
        // In a real implementation, we'd have a proper state transition matrix
        Eigen::VectorXd new_state = state;
        new_state(3) = gyro_x; // roll rate
        new_state(4) = gyro_y; // pitch rate
        new_state(5) = gyro_z; // yaw rate
        state = new_state;

        // Update covariance
        P = P + Q;
    }

    void update(double accel_x, double accel_y, double accel_z,
                double gyro_x, double gyro_y, double gyro_z) {
        this->gyro_x = gyro_x;
        this->gyro_y = gyro_y;
        this->gyro_z = gyro_z;

        // Simple accelerometer-based roll/pitch estimation
        double roll_acc = atan2(accel_y, accel_z);
        double pitch_acc = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z));

        // Measurement vector: [roll, pitch, yaw]
        Eigen::VectorXd z(3);
        z << roll_acc, pitch_acc, 0; // yaw is not measured from accelerometer

        // Kalman gain
        Eigen::MatrixXd S = H * P * H.transpose() + R;
        Eigen::MatrixXd K = P * H.transpose() * S.inverse();

        // Update state
        state = state + K * (z - H * state);

        // Update covariance
        P = (Eigen::MatrixXd::Identity(6, 6) - K * H) * P;
    }

    Eigen::Vector3d getOrientation() const {
        return state.head<3>();
    }

