        // Fuse gyro and accelerometer data
        current_theta = ALPHA * theta_gyro + (1 - ALPHA) * theta_accel;

        // --- Position estimation (odometry) ---
        // Convert encoder ticks to wheel displacements
        double left_m = left_ticks * WHEEL_RADIUS;
        double right_m = right_ticks * WHEEL_RADIUS;

        // Calculate linear and angular velocities from wheel displacements
        double linear_vel = (left_m + right_m) / (2 * DT);
        double angular_vel = (right_m - left_m) / (WHEELBASE * DT);

        // Update position (simple dead reckoning)
        current_x += linear_vel * cos(current_theta) * DT;
        current_y += linear_vel * sin(current_theta) * DT;
        theta_gyro = current_theta;  // Reset gyro integration to fused angle
    }

    Pose get_pose() const { return {current_x, current_y, current_theta}; }

    void set_imu_state(double theta, double omega) {
        imu.set_state(theta, omega);
    }

    void set_encoder_velocity(double left, double right) {
        encoder.set_velocity(left, right);
    }

private:
    IMU imu;
    Encoder encoder;
    double current_x = 0.0, current_y = 0.0, current_theta = 0.0;
    double theta_gyro = 0.0;  // Gyro-only integration
};

// Simple motor controller (simulated PWM output)
class MotorController {
public:
    void set_motor_pwm(double left_pwm, double right_pwm) {
        // In a real system, this would send PWM signals to motor drivers
        // For simulation, we just print the commands
        std::cout << "Motor PWM: Left=" << left_pwm << ", Right=" << right_pwm << std::endl;
    }
};

// PID controller for velocity control
class PIDController {
public:
    PIDController(double kp, double ki, double kd)
        : kp(kp), ki(ki), kd(kd), integral(0.0), prev_error(0.0) {}

    double update(double setpoint, double measurement) {
        double error = setpoint - measurement;
        integral += error * DT;
        double derivative = (error - prev_error) / DT;
        prev_error = error;

        return kp * error + ki * integral + kd * derivative;
    }

private:
    double kp, ki, kd;
    double integral;
    double prev_error;
};

int main() {
    SensorFusion fusion;
    MotorController motors;
    PIDController left_pid(1.0, 0.1, 0.05);
    PIDController right_pid(1.0, 0.1, 0.05);

    // Desired motor velocities (m/s)
    const double left_velocity_setpoint = 1.0;
    const double right_velocity_setpoint = 1.2;

    // Run for 10 seconds (1000 iterations at 100Hz)
    const int total_iterations = static_cast<int>(10 * LOOP_RATE_HZ);
    int iteration = 0;

    auto last_time = std::chrono::steady_clock::now();

    while (iteration < total_iterations) {
        auto now = std::chrono::steady_clock::now();
        double elapsed = std::chrono::duration<double>(now - last_time).count();

        // Maintain fixed loop rate
        if (elapsed < DT) {
            continue;
        }
        last_time = now;
        iteration++;

        // Simulate sensor updates (in reality, these would come from hardware)
        fusion.set_imu_state(0.0, 0.0);  // Reset IMU state
        fusion.set_encoder_velocity(left_velocity_setpoint, right_velocity_setpoint);

        // Perform sensor fusion
        fusion.update();

        // Get current pose
        Pose pose = fusion.get_pose();
        std::cout << "[" << iteration << "] Pose: x=" << pose.x
                  << "m, y=" << pose.y << "m, theta=" << pose.theta << "rad\n";

        // Motor control: PID velocity control
        // In reality, we'd read actual encoder values for feedback
        double left_encoder_measurement = left_velocity_setpoint;  // Simplified
        double right_encoder_measurement = right_velocity_setpoint;

        double left_pwm = left_pid.update(left_velocity_setpoint, left_encoder_measurement);
        double right_pwm = right_pid.update(right_velocity_setpoint, right_encoder_measurement);

        motors.set_motor_pwm(left_pwm, right_pwm);
    }

    std::cout << "Control loop completed after " << iteration << " iterations\n";
    return 0;
}
```

