// --- Sensor Fusion: Complementary Filter ---
// Combines gyro (short-term accurate) and accelerometer (long-term accurate) for orientation.
double complementary_filter(double angle, double gyro_rate, double accel_angle, double dt) {
    const double alpha = 0.98;  // Gyro weight (high-pass), accelerometer weight (1-alpha)
    return alpha * (angle + gyro_rate * dt) + (1 - alpha) * accel_angle;
}

// --- Control Law: Proportional Controller ---
// Computes motor PWM based on desired vs. actual wheel velocity.
MotorCommand compute_motor_commands(
    const RobotState& state,
    const RobotState& desired_state,
    double dt
) {
    MotorCommand cmd;
    const double kp = 1.0;  // Proportional gain

    // Simple P-controller for each wheel
    double left_error = desired_state.v_left - state.v_left;
    double right_error = desired_state.v_right - state.v_right;

    cmd.left_pwm = kp * left_error;
    cmd.right_pwm = kp * right_error;

    // Clamp PWM to [-1.0, 1.0] (full reverse to full forward)
    cmd.left_pwm = std::max(-1.0, std::min(1.0, cmd.left_pwm));
    cmd.right_pwm = std::max(-1.0, std::min(1.0, cmd.right_pwm));

    return cmd;
}

