        MotorCommand cmd = compute_motor_commands(state, desired_state, dt);

        // --- Actuation ---
        actuate_motors(cmd);

        // --- Real-Time Loop Control ---
        // Sleep to maintain 100Hz loop rate
        std::this_thread::sleep_for(std::chrono::milliseconds(static_cast<int>(LOOP_PERIOD_MS)));
    }

    return 0;
}
