### **Minimal Robotics Control Loop**
```cpp
#include <iostream>
#include <chrono>
#include <cmath>
#include <vector>

// ======================
// 1. Sensor Simulation
// ======================
struct IMUData {
    double gyro_x;   // Angular velocity (rad/s)
    double gyro_y;   // Angular velocity (rad/s)
    double gyro_z;   // Angular velocity (rad/s)
    double accel_x;  // Acceleration (m/s²)
    double accel_y;  // Acceleration (m/s²)
    double accel_z;  // Acceleration (m/s²)
};

struct WheelEncoderData {
    double left_ticks;   // Encoder ticks (simulated)
    double right_ticks;  // Encoder ticks (simulated)
};

// Simulate IMU (gyro drift + noise)
IMUData simulateIMU(double time, double gyro_drift = 0.01) {
    IMUData imu;
    imu.gyro_x = 0.1 * sin(time) + gyro_drift * time;  // Drifting bias
    imu.gyro_y = 0.05 * cos(time);
    imu.gyro_z = 0.0;
    imu.accel_x = 9.81 * sin(time * 0.5);  // Tilt simulation
    imu.accel_y = 9.81 * cos(time * 0.5);
    imu.accel_z = 9.81;
    return imu;
}

// Simulate wheel encoders (wheel radius = 0.1m, ticks per revolution = 1000)
WheelEncoderData simulateEncoders(double time, double left_vel_cmd, double right_vel_cmd) {
    static double left_ticks = 0, right_ticks = 0;
    const double wheel_radius = 0.1;  // meters
    const double ticks_per_rev = 1000.0;

    // Simulate encoder ticks (convert velocity to ticks)
    left_ticks += left_vel_cmd * ticks_per_rev / (2 * M_PI * wheel_radius) * 0.01;  // dt = 0.01s
    right_ticks += right_vel_cmd * ticks_per_rev / (2 * M_PI * wheel_radius) * 0.01;

    return {left_ticks, right_ticks};
}

// ======================
// 2. Sensor Fusion (Complementary Filter)
// ======================
class ComplementaryFilter {
private:
    double angle;  // Estimated angle (rad)
    double alpha;  // Filter coefficient (0.0 to 1.0)
    double bias;   // Gyro bias estimate

public:
    ComplementaryFilter(double alpha = 0.98) : angle(0.0), alpha(alpha), bias(0.0) {}

    // Update filter with new IMU data
    void update(const IMUData& imu, double dt) {
        // Gyro integration (with bias compensation)
        double gyro_angle = imu.gyro_y * dt;  // Only using Y-axis for simplicity
        bias += 0.01 * (gyro_angle - (angle - angle_prev));  // Simple bias estimation
        angle += (gyro_angle - bias) * dt;

        // Accelerometer correction (tilt from gravity)
        double accel_angle = atan2(imu.accel_x, imu.accel_z);
        angle = alpha * angle + (1 - alpha) * accel_angle;

        angle_prev = angle;
    }

    double getAngle() const { return angle; }

private:
    double angle_prev = 0.0;
};

// ======================
// 3. Motor Control (PID Controller)
// ======================
class PIDController {
private:
    double Kp, Ki, Kd;
    double integral;
    double prev_error;
    double output_min, output_max;

public:
    PIDController(double Kp, double Ki, double Kd, double output_min = -1.0, double output_max = 1.0)
        : Kp(Kp), Ki(Ki), Kd(Kd), integral(0.0), prev_error(0.0),
          output_min(output_min), output_max(output_max) {}

    double compute(double setpoint, double measurement, double dt) {
        double error = setpoint - measurement;
        integral += error * dt;
        double derivative = (error - prev_error) / dt;
        prev_error = error;

        double output = Kp * error + Ki * integral + Kd * derivative;
        return std::clamp(output, output_min, output_max);
    }

    void reset() {
        integral = 0.0;
        prev_error = 0.0;
    }
};

// ======================
// 4. Main Control Loop
// ======================
int main() {
    // Initialize components
    ComplementaryFilter filter;
    PIDController left_pid(1.0, 0.1, 0.05);   // Tuned for left motor
    PIDController right_pid(1.0, 0.1, 0.05);  // Tuned for right motor

    // Desired velocity (m/s)
    double desired_vel = 0.5;

    // Control loop variables
    auto last_time = std::chrono::high_resolution_clock::now();
    const double loop_freq = 100.0;  // Hz
    const double dt = 1.0 / loop_freq;

    std::cout << "Starting control loop (100Hz)...\n";

    while (true) {
        auto now = std::chrono::high_resolution_clock::now();
        double elapsed = std::chrono::duration<double>(now - last_time).count();

        // Run loop at fixed frequency
        if (elapsed >= dt) {
            last_time = now;

            // --- SENSOR READING ---
            IMUData imu = simulateIMU(elapsed);
            WheelEncoderData encoders = simulateEncoders(elapsed, desired_vel, desired_vel);

            // --- SENSOR FUSION ---
            filter.update(imu, dt);
            double estimated_angle = filter.getAngle();

            // --- MOTOR CONTROL ---
            // Convert encoder ticks to velocity (simplified)
            double left_vel_actual = encoders.left_ticks * 0.01;  // Ticks to m/s
            double right_vel_actual = encoders.right_ticks * 0.01;

            // Compute PID outputs
            double left_cmd = left_pid.compute(desired_vel, left_vel_actual, dt);
            double right_cmd = right_pid.compute(desired_vel, right_vel_actual, dt);

            // --- SIMULATE MOTOR RESPONSE ---
            // (In real hardware, send left_cmd/right_cmd to motor drivers)
            std::cout << "Time: " << elapsed << "s | "
                      << "Angle: " << estimated_angle << " rad | "
                      << "Left Vel: " << left_vel_actual << " m/s | "
                      << "Right Vel: " << right_vel_actual << " m/s | "
                      << "Left CMD: " << left_cmd << " | "
                      << "Right CMD: " << right_cmd << "\n";

            // Early exit for demo (press Ctrl+C to stop)
            if (elapsed > 5.0) break;
        }
    }

    std::cout << "Control loop exited.\n";
    return 0;
}
```

