// ======================
// 1. Kalman Filter for Orientation (Roll/Pitch)
// ======================
class KalmanFilter {
private:
    // State: [roll, pitch, roll_rate, pitch_rate]
    std::vector<double> state;
    // Covariance matrix (4x4)
    std::vector<std::vector<double>> covariance;
    // Process noise (tune for your system)
    const double Q_accel = 0.01;
    const double Q_gyro = 0.001;
    // Measurement noise (tune for your IMU)
    const double R_accel = 0.1;

public:
    KalmanFilter() : state(4, 0.0), covariance(4, std::vector<double>(4, 0.0)) {
        // Initialize covariance (high uncertainty)
        covariance[0][0] = 1.0;  // roll
        covariance[1][1] = 1.0;  // pitch
        covariance[2][2] = 1.0;  // roll_rate
        covariance[3][3] = 1.0;  // pitch_rate
    }

    // Predict step (using gyroscope)
    void predict(double gyro_x, double gyro_y) {
        // State transition matrix (simplified)
        state[0] += gyro_x * 0.01;  // roll += roll_rate * dt
        state[1] += gyro_y * 0.01;  // pitch += pitch_rate * dt
        state[2] = gyro_x;          // roll_rate = gyro_x
        state[3] = gyro_y;          // pitch_rate = gyro_y

        // Update covariance (simplified)
        covariance[0][0] += Q_gyro;
        covariance[1][1] += Q_gyro;
        covariance[2][2] += Q_accel;
        covariance[3][3] += Q_accel;
    }

    // Update step (using accelerometer)
    void update(double accel_x, double accel_y, double accel_z) {
        // Convert accelerometer to roll/pitch (simplified)
        double roll_accel = atan2(accel_y, accel_z);
        double pitch_accel = atan2(-accel_x, sqrt(accel_y*accel_y + accel_z*accel_z));

        // Kalman gain (simplified)
        double K_roll = covariance[0][0] / (covariance[0][0] + R_accel);
        double K_pitch = covariance[1][1] / (covariance[1][1] + R_accel);

        // Update state
        state[0] += K_roll * (roll_accel - state[0]);
        state[1] += K_pitch * (pitch_accel - state[1]);

        // Update covariance
        covariance[0][0] *= (1 - K_roll);
        covariance[1][1] *= (1 - K_pitch);
    }

    // Get filtered roll/pitch
    void getOrientation(double& roll, double& pitch) {
        roll = state[0];
        pitch = state[1];
    }
};

