// PID Controller for balancing
struct PidController {
    kp: f64,
    ki: f64,
    kd: f64,
    integral: f64,
    prev_error: f64,
}

impl PidController {
    fn new(kp: f64, ki: f64, kd: f64) -> Self {
        PidController {
            kp,
            ki,
            kd,
            integral: 0.0,
            prev_error: 0.0,
        }
    }

    fn update(&mut self, error: f64, dt: f64) -> f64 {
        self.integral += error * dt;
        let derivative = (error - self.prev_error) / dt;
        self.prev_error = error;

        self.kp * error + self.ki * self.integral + self.kd * derivative
    }
}

// Complementary filter for sensor fusion
struct ComplementaryFilter {
    alpha: f64, // Weight for gyro (1 - alpha for accel)
    angle: f64, // Estimated angle (rad)
}

impl ComplementaryFilter {
    fn new(alpha: f64) -> Self {
        ComplementaryFilter { alpha, angle: 0.0 }
    }

    fn update(&mut self, imu: &ImuData, dt: f64) -> f64 {
        // Gyro integration to get angle change
