#define WINDOW_SIZE 50          // Moving window size for anomaly detection
#define ANOMALY_THRESHOLD 3.0  // Number of standard deviations to trigger anomaly
#define SAMPLE_RATE 100         // Hz (for simulation)
#define GRAVITY 9.81            // m/s²

