// Initialize a data window
void window_init(DataWindow* window, size_t capacity) {
    window->x = (float*)malloc(capacity * sizeof(float));
    window->y = (float*)malloc(capacity * sizeof(float));
    window->z = (float*)malloc(capacity * sizeof(float));
    window->size = 0;
    window->capacity = capacity;
}

// Free window memory
void window_free(DataWindow* window) {
    free(window->x);
    free(window->y);
    free(window->z);
    window->size = 0;
    window->capacity = 0;
}

// Add new data to window (FIFO)
void window_push(DataWindow* window, AccelData data) {
    if (window->size < window->capacity) {
        window->x[window->size] = data.x;
        window->y[window->size] = data.y;
        window->z[window->size] = data.z;
        window->size++;
    } else {
        // Shift data to make room (simple FIFO)
        for (size_t i = 0; i < window->capacity - 1; i++) {
            window->x[i] = window->x[i+1];
            window->y[i] = window->y[i+1];
            window->z[i] = window->z[i+1];
        }
        window->x[window->capacity-1] = data.x;
        window->y[window->capacity-1] = data.y;
        window->z[window->capacity-1] = data.z;
    }
}

// Calculate mean of a window
float window_mean(float* data, size_t size) {
    float sum = 0.0f;
    for (size_t i = 0; i < size; i++) {
        sum += data[i];
    }
    return sum / size;
}

// Calculate standard deviation of a window
float window_std(float* data, size_t size, float mean) {
    float sum_sq = 0.0f;
    for (size_t i = 0; i < size; i++) {
        float diff = data[i] - mean;
        sum_sq += diff * diff;
    }
    return sqrtf(sum_sq / size);
}

// Calculate magnitude of acceleration vector
float calculate_magnitude(AccelData data) {
    return sqrtf(data.x*data.x + data.y*data.y + data.z*data.z);
}

// ======================
// Anomaly Detection
// ======================

typedef struct {
    bool is_anomaly;
    float magnitude;
    float mean;
    float std_dev;
} AnomalyResult;

// Detect anomalies using moving window statistics
AnomalyResult detect_anomaly(DataWindow* window, AccelData current) {
    AnomalyResult result = {false, 0.0f, 0.0f, 0.0f};

    if (window->size < WINDOW_SIZE) {
        // Not enough data yet
        window_push(window, current);
        return result;
    }

    // Calculate magnitude of current reading
    result.magnitude = calculate_magnitude(current);

    // Calculate mean and std dev of the window
    float mean_x = window_mean(window->x, window->size);
    float mean_y = window_mean(window->y, window->size);
    float mean_z = window_mean(window->z, window->size);
    result.mean = sqrtf(mean_x*mean_x + mean_y*mean_y + mean_z*mean_z);

    float std_x = window_std(window->x, window->size, mean_x);
    float std_y = window_std(window->y, window->size, mean_y);
    float std_z = window_std(window->z, window->size, mean_z);
    result.std_dev = sqrtf(std_x*std_x + std_y*std_y + std_z*std_z);

    // Check for anomaly (simple threshold-based)
    if (result.std_dev > 0) {
        float z_score = fabsf(result.magnitude - result.mean) / result.std_dev;
        if (z_score > ANOMALY_THRESHOLD) {
            result.is_anomaly = true;
        }
    }

    // Add current data to window
    window_push(window, current);

    return result;
}

