// Update moving statistics (mean and std) for anomaly detection
class MovingStats {
private:
    std::vector<float> window;
    float sum = 0.0f;
    float sumSq = 0.0f;

public:
    void addValue(float value) {
        if (window.size() == WINDOW_SIZE) {
            float oldValue = window.front();
            window.erase(window.begin());
            sum -= oldValue;
            sumSq -= oldValue * oldValue;
        }
        window.push_back(value);
        sum += value;
        sumSq += value * value;
    }

    float getMean() const {
        return window.empty() ? 0.0f : sum / window.size();
    }

    float getStd() const {
        if (window.empty()) return 0.0f;
        float mean = getMean();
        return std::sqrt((sumSq / window.size()) - (mean * mean));
    }

    bool isAnomaly(float value) const {
        float mean = getMean();
        float std = getStd();
        if (std < 1e-5f) return false;  // Avoid division by zero
        return (value > mean + ANOMALY_THRESHOLD * std) ||
               (value < mean - ANOMALY_THRESHOLD * std);
    }
};

