    uint16_t index;
    float sum;
    float mean;
} MovingAverageFilter;

typedef struct {
    float rms;
    float peak;
    bool is_anomaly;
} AnomalyResult;

// ======================
// Filter Implementation
// ======================
void init_filter(MovingAverageFilter* filter) {
    filter->index = 0;
    filter->sum = 0.0f;
    filter->mean = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        filter->window[i] = 0.0f;
    }
}

float apply_filter(MovingAverageFilter* filter, float new_value) {
    // Subtract the oldest value
    filter->sum -= filter->window[filter->index];

    // Add the new value
    filter->window[filter->index] = new_value;
    filter->sum += new_value;

    // Update mean
    filter->mean = filter->sum / WINDOW_SIZE;

    // Update index (circular buffer)
    filter->index = (filter->index + 1) % WINDOW_SIZE;

    return filter->mean;
}

