    return sqrtf((data->x * data->x + data->y * data->y + data->z * data->z) / 3.0f);
}

float calculate_peak(const AccelData* data) {
    float peak = fmaxf(fabsf(data->x), fmaxf(fabsf(data->y), fabsf(data->z)));
    return peak;
}

// ======================
// Anomaly Detection
// ======================
AnomalyResult detect_anomaly(const AccelData* raw_data, const AccelData* filtered_data) {
    AnomalyResult result = {0};

    // Calculate features
    result.rms = calculate_rms(filtered_data);
    result.peak = calculate_peak(raw_data);

    // Simple threshold-based detection
    bool rms_anomaly = result.rms > RMS_THRESHOLD;
    bool peak_anomaly = result.peak > PEAK_THRESHOLD;

    // Combine conditions (OR logic - anomaly if either condition is met)
    result.is_anomaly = rms_anomaly || peak_anomaly;

