    MovingAverageFilter filter_x, filter_y, filter_z;
    init_filter(&filter_x);
    init_filter(&filter_y);
    init_filter(&filter_z);

    uint16_t anomaly_count = 0;
    bool in_anomaly = false;

    for (uint32_t i = 0; i < num_samples; i++) {
