// Initialize moving average structure
void moving_average_init(MovingAverage* ma) {
    for (int i = 0; i < WINDOW_SIZE; i++) {
        ma->values[i] = 0.0f;
    }
    ma->index = 0;
    ma->sum = 0.0f;
    ma->mean = 0.0f;
    ma->m2 = 0.0f;
}

// Update moving average with new value (Welford's algorithm)
void moving_average_update(MovingAverage* ma, float value) {
    // Circular buffer update
    float old_value = ma->values[ma->index];
    ma->values[ma->index] = value;
    ma->index = (ma->index + 1) % WINDOW_SIZE;

    // Update sum for mean calculation
    ma->sum = ma->sum - old_value + value;

    // Welford's algorithm for variance
    float delta = value - ma->mean;
    ma->mean = ma->sum / WINDOW_SIZE;
    ma->m2 += delta * (value - ma->mean);
}

