#include "mpu6050.h"
#include "i2c_hal.h"
#include "config.h"

#define MPU6050_REG_PWR_MGMT_1  0x6B
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_ACCEL_SCALE      16384.0f  // Sensitivity for ±2g range

bool mpu6050_init(void) {
    uint8_t data = 0;
    if (!i2c_init()) return false;

    // Wake up MPU6050 (disable sleep mode)
    data = 0;
    if (!i2c_write(MPU6050_I2C_ADDR, MPU6050_REG_PWR_MGMT_1, &data, 1)) {
        return false;
    }

    // Configure accelerometer range (±2g)
    data = 0x00;  // 0x00 = ±2g, 0x08 = ±4g, etc.
    return i2c_write(MPU6050_I2C_ADDR, 0x1C, &data, 1);
}

bool mpu6050_read_accel(AccelData *data) {
    uint8_t raw[6];
    if (!i2c_read(MPU6050_I2C_ADDR, MPU6050_REG_ACCEL_XOUT_H, raw, 6)) {
        return false;
    }

    // Combine high/low bytes (little-endian)
    int16_t x_raw = (raw[0] << 8) | raw[1];
    int16_t y_raw = (raw[2] << 8) | raw[3];
    int16_t z_raw = (raw[4] << 8) | raw[5];

    // Convert to g-force (assuming ±2g range)
    data->x = (float)x_raw / MPU6050_ACCEL_SCALE;
    data->y = (float)y_raw / MPU6050_ACCEL_SCALE;
    data->z = (float)z_raw / MPU6050_ACCEL_SCALE;

    return true;
}
