void processing_init(ProcessingContext *ctx, float threshold) {
    ctx->index = 0;
    ctx->rms_threshold = threshold;
    for (uint8_t i = 0; i < WINDOW_SIZE; i++) {
        ctx->samples[i][0] = 0;
        ctx->samples[i][1] = 0;
        ctx->samples[i][2] = 0;
    }
}

void processing_add_sample(ProcessingContext *ctx, const AccelData *data) {
    ctx->samples[ctx->index][0] = data->x;
    ctx->samples[ctx->index][1] = data->y;
    ctx->samples[ctx->index][2] = data->z;
    ctx->index = (ctx->index + 1) % WINDOW_SIZE;
}

float processing_calculate_rms(const ProcessingContext *ctx) {
    float sum_sq = 0.0f;
    for (uint8_t i = 0; i < WINDOW_SIZE; i++) {
        sum_sq += ctx->samples[i][0] * ctx->samples[i][0];  // x-axis only
        sum_sq += ctx->samples[i][1] * ctx->samples[i][1];  // y-axis
        sum_sq += ctx->samples[i][2] * ctx->samples[i][2];  // z-axis
    }
    return sqrtf(sum_sq / (WINDOW_SIZE * 3));
}

bool processing_is_anomaly(const ProcessingContext *ctx) {
    float rms = processing_calculate_rms(ctx);
    return (rms > ctx->rms_threshold);
}
