#include "accelerometer.h"
#include "stm32f4xx_hal.h"
#include <math.h>

extern I2C_HandleTypeDef hi2c1;

bool Accelerometer_Init(void) {
    uint8_t config[2] = {0};

    // Enable accelerometer (50Hz, ±2g, all axes)
    config[0] = LSM303DLHC_REG_CTRL1_A;
    config[1] = 0x57;  // ODR=50Hz (0x50), LPen=0, X/Y/Z-en=111
    if (HAL_I2C_Master_Transmit(&hi2c1, LSM303DLHC_ADDR_ACC, config, 2, HAL_MAX_DELAY) != HAL_OK) {
        return false;
    }

    // Small delay for stabilization
    HAL_Delay(10);
    return true;
}

bool Accelerometer_ReadRaw(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t reg = LSM303DLHC_REG_OUT_X_L_A | 0x80;  // Auto-increment
    uint8_t data[6] = {0};

    if (HAL_I2C_Master_Transmit(&hi2c1, LSM303DLHC_ADDR_ACC, &reg, 1, HAL_MAX_DELAY) != HAL_OK) {
        return false;
    }
    if (HAL_I2C_Master_Receive(&hi2c1, LSM303DLHC_ADDR_ACC, data, 6, HAL_MAX_DELAY) != HAL_OK) {
        return false;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);
    return true;
}

bool Accelerometer_ReadFiltered(float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;
    if (!Accelerometer_ReadRaw(&raw_x, &raw_y, &raw_z)) {
        return false;
    }

    // Convert to g (fixed-point for embedded)
    *x = (float)raw_x * ACCEL_SENSITIVITY / 1000.0f;
    *y = (float)raw_y * ACCEL_SENSITIVITY / 1000.0f;
    *z = (float)raw_z * ACCEL_SENSITIVITY / 1000.0f;
    return true;
}
