typedef struct {
    float alpha;    // Smoothing factor (0 < alpha < 1)
    float prev_x;   // Previous filtered value
    float prev_y;
    float prev_z;
} LowPassFilter;

// Initialize filter
void Filter_Init(LowPassFilter *filter, float alpha);

// Apply low-pass filter to accelerometer data
void Filter_Apply(LowPassFilter *filter, float *x, float *y, float *z);

