#### **`Core/Src/filter.c`**
```c
#include "filter.h"

void Filter_Init(LowPassFilter *filter, float alpha) {
    filter->alpha = alpha;
    filter->prev_x = 0.0f;
    filter->prev_y = 0.0f;
    filter->prev_z = 0.0f;
}

void Filter_Apply(LowPassFilter *filter, float *x, float *y, float *z) {
    filter->prev_x = filter->alpha * (*x) + (1 - filter->alpha) * filter->prev_x;
    filter->prev_y = filter->alpha * (*y) + (1 - filter->alpha) * filter->prev_y;
    filter->prev_z = filter->alpha * (*z) + (1 - filter->alpha) * filter->prev_z;

    *x = filter->prev_x;
    *y = filter->prev_y;
    *z = filter->prev_z;
}
