#include "anomaly_detection.h"
#include <stdlib.h>
#include <math.h>

void AnomalyDetector_Init(AnomalyDetector *detector, float threshold, uint32_t window_size) {
    detector->threshold = threshold;
    detector->window_size = window_size;
    detector->history_capacity = window_size;
    detector->history = (float *)malloc(window_size * sizeof(float));
    detector->history_idx = 0;
    for (uint32_t i = 0; i < window_size; i++) {
        detector->history[i] = 0.0f;
    }
}

bool AnomalyDetector_Check(AnomalyDetector *detector, float x, float y, float z) {
    // Calculate magnitude (Euclidean norm)
    float magnitude = sqrtf(x*x + y*y + z*z);

    // Update history (circular buffer)
    detector->history[detector->history_idx] = magnitude;
    detector->history_idx = (detector->history_idx + 1) % detector->history_capacity;

    // Check if any sample in the window exceeds the threshold
    for (uint32_t i = 0; i < detector->history_capacity; i++) {
        if (detector->history[i] > detector->threshold) {
            return true;
        }
    }
    return false;
}

void AnomalyDetector_Deinit(AnomalyDetector *detector) {
    free(detector->history);
    detector->history = NULL;
}
