    LowPassFilter filter;
    Filter_Init(&filter, 0.2f);

    // Initialize anomaly detector (threshold = 1.5g, window = 10 samples)
    AnomalyDetector detector;
    AnomalyDetector_Init(&detector, 1.5f, 10);

