    int16_t raw_x, raw_y, raw_z;
    float filtered_x, filtered_y, filtered_z;
    uint32_t tick = HAL_GetTick();

    while (1) {
        // Read accelerometer data
        if (Accelerometer_ReadFiltered(&filtered_x, &filtered_y, &filtered_z)) {
            // Apply low-pass filter
            Filter_Apply(&filter, &filtered_x, &filtered_y, &filtered_z);

            // Check for anomaly
            if (AnomalyDetector_Check(&detector, filtered_x, filtered_y, filtered_z)) {
                sprintf(msg, "ANOMALY DETECTED! X=%.2fg Y=%.2fg Z=%.2fg\r\n",
                        filtered_x, filtered_y, filtered_z);
                HAL_UART_Transmit(&huart2, (uint8_t *)msg, strlen(msg), HAL_MAX_DELAY);
