        // Maintain 100Hz sampling rate
        uint32_t elapsed = HAL_GetTick() - tick;
        if (elapsed < 10) {  // 1000ms / 100Hz = 10ms
            HAL_Delay(10 - elapsed);
        }
        tick = HAL_GetTick();
    }
}

