Here's a complete initial implementation of an embedded sensor-processing pipeline for accelerometer anomaly detection in C++. This example targets an STM32 microcontroller (using HAL libraries) with an MPU6050 accelerometer, but can be adapted for other platforms:

```cpp
#include <cstdint>
#include <cmath>
#include "stm32f4xx_hal.h"  // Hardware Abstraction Layer for STM32

// ======================
// Configuration Constants
// ======================
constexpr float ACCEL_SCALE_FACTOR = 16384.0f;  // LSB/g for ±2g range on MPU6050
constexpr float THRESHOLD = 1.5f;               // Anomaly threshold in g (1.5g)
constexpr float ALPHA = 0.2f;                   // Low-pass filter coefficient (0.0-1.0)
constexpr uint32_t SAMPLING_PERIOD_MS = 10;     // 100Hz sampling rate (1000ms/10ms)
constexpr uint8_t MPU6050_ADDR = 0x68 << 1;    // MPU6050 I2C address (shifted for 7-bit)

// ======================
// Data Structures
// ======================
struct AccelData {
    float x;
    float y;
    float z;
};

// ======================
// Accelerometer Interface
// ======================
class Accelerometer {
public:
    /**
     * @brief Initialize the MPU6050 accelerometer
     * @param hi2c Pointer to I2C handle
     */
    void init(I2C_HandleTypeDef* hi2c) {
        i2c_handle = hi2c;

        // Wake up MPU6050 from sleep mode
        uint8_t wakeup_cmd[2] = {0x6B, 0x00};
        HAL_I2C_Master_Transmit(i2c_handle, MPU6050_ADDR, wakeup_cmd, 2, HAL_MAX_DELAY);

        // Configure accelerometer range (±2g)
        uint8_t accel_config[2] = {0x1C, 0x00};
        HAL_I2C_Master_Transmit(i2c_handle, MPU6050_ADDR, accel_config, 2, HAL_MAX_DELAY);
    }

    /**
     * @brief Read raw accelerometer data and convert to g units
     * @return Acceleration data in g
     */
    AccelData read() {
        uint8_t data[6];
        uint8_t reg = 0x3B;  // Start with ACCEL_XOUT_H register

        // Set register pointer and read 6 bytes (X,Y,Z)
        HAL_I2C_Master_Transmit(i2c_handle, MPU6050_ADDR, &reg, 1, HAL_MAX_DELAY);
        HAL_I2C_Master_Receive(i2c_handle, MPU6050_ADDR, data, 6, HAL_MAX_DELAY);

        // Convert raw data to g (16-bit signed integers)
        int16_t x_raw = (static_cast<int16_t>(data[0]) << 8) | data[1];
        int16_t y_raw = (static_cast<int16_t>(data[2]) << 8) | data[3];
        int16_t z_raw = (static_cast<int16_t>(data[4]) << 8) | data[5];

        return {
            .x = static_cast<float>(x_raw) / ACCEL_SCALE_FACTOR,
            .y = static_cast<float>(y_raw) / ACCEL_SCALE_FACTOR,
            .z = static_cast<float>(z_raw) / ACCEL_SCALE_FACTOR
        };
    }

private:
    I2C_HandleTypeDef* i2c_handle;
};

// ======================
// Signal Preprocessing
// ======================
class Preprocessor {
public:
    /**
     * @brief Apply exponential moving average filter
     * @param raw New accelerometer data
     * @return Filtered accelerometer data
     */
    AccelData filter(const AccelData& raw) {
        filtered.x = ALPHA * raw.x + (1 - ALPHA) * prev.x;
        filtered.y = ALPHA * raw.y + (1 - ALPHA) * prev.y;
        filtered.z = ALPHA * raw.z + (1 - ALPHA) * prev.z;

        prev = filtered;
        return filtered;
    }

private:
    AccelData prev = {0.0f, 0.0f, 0.0f};
    AccelData filtered;
};

// ======================
// Anomaly Detection
// ======================
class AnomalyDetector {
public:
    /**
     * @brief Detect anomalies based on acceleration magnitude
     * @param data Filtered accelerometer data
     * @return true if anomaly detected, false otherwise
     */
    bool detect(const AccelData& data) {
        float magnitude = std::sqrt(data.x * data.x +
                                   data.y * data.y +
                                   data.z * data.z);
        return magnitude > THRESHOLD;
    }
};

// ======================
// Main Application
// ======================
int main() {
    // Hardware initialization
    HAL_Init();
    SystemClock_Config();

    // Initialize I2C peripheral (example for STM32F4)
    I2C_HandleTypeDef hi2c1;
    hi2c1.Instance = I2C1;
    hi2c1.Init.ClockSpeed = 400000;  // 400kHz I2C clock
    hi2c1.Init.DutyCycle = I2C_DUTYCYCLE_2;
    hi2c1.Init.OwnAddress1 = 0;
    hi2c1.Init.AddressingMode = I2C_ADDRESSINGMODE_7BIT;
    hi2c1.Init.DualAddressMode = I2C_DUALADDRESS_DISABLE;
    hi2c1.Init.OwnAddress2 = 0;
    hi2c1.Init.GeneralCallMode = I2C_GENERALCALL_DISABLE;
    hi2c1.Init.NoStretchMode = I2C_NOSTRETCH_DISABLE;
    HAL_I2C_Init(&hi2c1);

    // Initialize peripheral components
    Accelerometer accel;
    Preprocessor preprocessor;
    AnomalyDetector detector;

    accel.init(&hi2c1);

    // Main processing loop
    while (1) {
        // 1. Read sensor data
        AccelData raw = accel.read();

        // 2. Preprocess data (filtering)
        AccelData filtered = preprocessor.filter(raw);

        // 3. Detect anomalies
        bool anomaly = detector.detect(filtered);

        // 4. Handle anomaly (example: toggle LED)
        HAL_GPIO_WritePin(GPIOA, GPIO_PIN_5,
                         anomaly ? GPIO_PIN_SET : GPIO_PIN_RESET);

        // 5. Delay for next sample
        HAL_Delay(SAMPLING_PERIOD_MS);
    }
}
```

