        std::cout << "[Accelerometer] Initialized (mock)\n";
    }

    // Read raw accelerometer data (x, y, z axes)
    void readData(float& x, float& y, float& z) {
        // Mock data: Simulate accelerometer readings
        // In a real implementation, this would read from hardware registers
        x = static_cast<float>(rand() % 100) / 10.0f - 5.0f; // Range: -5.0 to 4.9
        y = static_cast<float>(rand() % 100) / 10.0f - 5.0f;
        z = static_cast<float>(rand() % 100) / 10.0f - 5.0f;
    }
};

// ======================
// Preprocessing
// ======================

// Simple exponential moving average (EMA) filter
class EMAFilter {
private:
    float alpha;  // Smoothing factor (0 < alpha < 1)
    float smoothedValue;
    bool firstRun;

public:
    EMAFilter(float alpha = 0.2f) : alpha(alpha), smoothedValue(0.0f), firstRun(true) {}

    // Apply EMA filter to a new value
    float filter(float newValue) {
        if (firstRun) {
            smoothedValue = newValue;
            firstRun = false;
        } else {
            smoothedValue = alpha * newValue + (1 - alpha) * smoothedValue;
        }
        return smoothedValue;
    }

    // Reset the filter
    void reset() {
        firstRun = true;
    }
};

// ======================
// Anomaly Detection
// ======================

class AnomalyDetector {
private:
    float threshold;  // Anomaly threshold (e.g., in g)
    float baseline;   // Baseline value (e.g., moving average)
    EMAFilter emaFilter;

public:
    AnomalyDetector(float threshold = 2.0f, float alpha = 0.2f)
        : threshold(threshold), baseline(0.0f), emaFilter(alpha) {}

    // Process new accelerometer data and detect anomalies
    bool detectAnomaly(float x, float y, float z) {
        // Compute acceleration magnitude (Euclidean norm)
        float magnitude = std::sqrt(x * x + y * y + z * z);

        // Apply EMA filter to smooth the magnitude
        float smoothedMagnitude = emaFilter.filter(magnitude);

        // Update baseline (simple moving average of smoothed magnitude)
        static std::vector<float> magnitudeHistory;
        const size_t historySize = 10;  // Window size for baseline
        magnitudeHistory.push_back(smoothedMagnitude);

        if (magnitudeHistory.size() > historySize) {
            magnitudeHistory.erase(magnitudeHistory.begin());
        }

        if (!magnitudeHistory.empty()) {
            baseline = std::accumulate(magnitudeHistory.begin(), magnitudeHistory.end(), 0.0f) / magnitudeHistory.size();
        }

        // Detect anomaly: if current magnitude exceeds threshold * baseline
        bool isAnomaly = (smoothedMagnitude > threshold * baseline);

        // Optional: Log or output the anomaly
        if (isAnomaly) {
            std::cout << "[Anomaly Detected] Magnitude: " << smoothedMagnitude
                      << " g (Baseline: " << baseline << " g, Threshold: " << threshold * baseline << " g)\n";
        }

        return isAnomaly;
    }

    // Reset the detector (e.g., after a long period of inactivity)
    void reset() {
        emaFilter.reset();
        baseline = 0.0f;
    }
};

// ======================
// Main Pipeline
// ======================

int main() {
    // Initialize hardware
    Accelerometer accelerometer;
    accelerometer.init();

    // Initialize anomaly detector
    AnomalyDetector detector(threshold = 2.0f);  // 2x baseline threshold

    // Simulate sensor data stream
    std::cout << "Starting accelerometer anomaly detection pipeline...\n";
