HAL_StatusTypeDef MPU6050_WriteReg(I2C_HandleTypeDef *hi2c, uint8_t reg, uint8_t value) {
    uint8_t data[2] = {reg, value};
    return HAL_I2C_Master_Transmit(hi2c, MPU6050_ADDR, data, 2, HAL_MAX_DELAY);
}

HAL_StatusTypeDef MPU6050_ReadReg(I2C_HandleTypeDef *hi2c, uint8_t reg, uint8_t *value) {
    return HAL_I2C_Master_Transmit(hi2c, MPU6050_ADDR, &reg, 1, HAL_MAX_DELAY) ||
           HAL_I2C_Master_Receive(hi2c, MPU6050_ADDR, value, 1, HAL_MAX_DELAY);
}

HAL_StatusTypeDef MPU6050_Init(I2C_HandleTypeDef *hi2c) {
    // Wake up MPU6050 (default starts in sleep mode)
    if (MPU6050_WriteReg(hi2c, 0x6B, 0x00) != HAL_OK) return HAL_ERROR;

    // Set accelerometer range to ±2g (default)
    if (MPU6050_WriteReg(hi2c, 0x1C, 0x00) != HAL_OK) return HAL_ERROR;

    // Set sample rate to 100Hz (1kHz / (1 + 9))
    if (MPU6050_WriteReg(hi2c, 0x19, 0x09) != HAL_OK) return HAL_ERROR;

    return HAL_OK;
}

HAL_StatusTypeDef MPU6050_ReadAccel(I2C_HandleTypeDef *hi2c, float *magnitude) {
    uint8_t data[6];
    uint8_t reg = 0x3B; // Start of accelerometer data

    // Read 6 bytes (X, Y, Z accel)
    if (HAL_I2C_Master_Transmit(hi2c, MPU6050_ADDR, &reg, 1, HAL_MAX_DELAY) != HAL_OK) return HAL_ERROR;
    if (HAL_I2C_Master_Receive(hi2c, MPU6050_ADDR, data, 6, HAL_MAX_DELAY) != HAL_OK) return HAL_ERROR;

    // Convert raw data to g's (±2g range → 16384 LSB/g)
    int16_t x = (int16_t)((data[0] << 8) | data[1]);
    int16_t y = (int16_t)((data[2] << 8) | data[3]);
    int16_t z = (int16_t)((data[4] << 8) | data[5]);

    float x_g = x / 16384.0f;
    float y_g = y / 16384.0f;
    float z_g = z / 16384.0f;

    *magnitude = sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);
    return HAL_OK;
}
