#include "main.h"
#include "mpu6050.h"
#include <math.h>
#include <stdio.h>

#define ANOMALY_THRESHOLD_MULTIPLIER 2.0f  // Anomaly if current > 2x moving avg
#define MOVING_AVG_WINDOW 10               // Samples for moving average
#define SAMPLE_DELAY_MS 100                // 10Hz sampling rate

I2C_HandleTypeDef hi2c1;
UART_HandleTypeDef huart2;

void SystemClock_Config(void);
static void MX_GPIO_Init(void);
static void MX_I2C1_Init(void);
static void MX_USART2_UART_Init(void);

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_I2C1_Init();
    MX_USART2_UART_Init();

    // Initialize MPU6050
    if (MPU6050_Init(&hi2c1) != HAL_OK) {
        printf("MPU6050 init failed!\r\n");
        while (1);
    }
    printf("MPU6050 initialized. Starting anomaly detection...\r\n");

    // Moving average buffer
    float accel_history[MOVING_AVG_WINDOW] = {0};
    float sum = 0.0f;
    uint8_t history_index = 0;

    while (1) {
        // Read accelerometer magnitude
        if (MPU6050_ReadAccel(&hi2c1, &accel_history[history_index]) != HAL_OK) {
            printf("Failed to read accelerometer!\r\n");
            HAL_Delay(1000);
            continue;
        }

        // Update moving average
        sum += accel_history[history_index];
        if (history_index == 0) sum -= accel_history[MOVING_AVG_WINDOW - 1];
        else sum -= accel_history[history_index - 1];
        history_index = (history_index + 1) % MOVING_AVG_WINDOW;
        float moving_avg = sum / MOVING_AVG_WINDOW;

        // Anomaly detection: current magnitude > 2x moving average
        float current_magnitude = accel_history[(history_index - 1) % MOVING_AVG_WINDOW];
        if (current_magnitude > ANOMALY_THRESHOLD_MULTIPLIER * moving_avg) {
            printf("ANOMALY! Magnitude: %.2fg (Avg: %.2fg)\r\n", current_magnitude, moving_avg);
            HAL_GPIO_WritePin(GPIOA, GPIO_PIN_5, GPIO_PIN_SET); // Turn on LED
        } else {
            HAL_GPIO_WritePin(GPIOA, GPIO_PIN_5, GPIO_PIN_RESET); // Turn off LED
        }

        HAL_Delay(SAMPLE_DELAY_MS);
    }
