    // In a real system, this would read from I2C/SPI
    static int counter = 0;
    *x = (int16_t)(1000 * sin(counter * 0.1f));  // Simulate sine wave
    *y = (int16_t)(1000 * cos(counter * 0.1f));
    *z = 1000;  // Gravity
    counter++;
    return 0;
}

// --- Signal Processing ---
#define WINDOW_SIZE 10  // Moving average window
#define ANOMALY_THRESHOLD 2.0f  // 2 standard deviations

typedef struct {
    float x_buffer[WINDOW_SIZE];
    float y_buffer[WINDOW_SIZE];
    float z_buffer[WINDOW_SIZE];
    float x_mean, y_mean, z_mean;
    float x_std, y_std, z_std;
    uint8_t buffer_index;
} MovingAverageFilter;

void filter_init(MovingAverageFilter *filter) {
    for (int i = 0; i < WINDOW_SIZE; i++) {
        filter->x_buffer[i] = 0;
        filter->y_buffer[i] = 0;
        filter->z_buffer[i] = 0;
    }
    filter->buffer_index = 0;
    filter->x_mean = filter->y_mean = filter->z_mean = 0;
    filter->x_std = filter->y_std = filter->z_std = 0;
}

void filter_update(MovingAverageFilter *filter, int16_t x, int16_t y, int16_t z) {
    // Update circular buffer
    filter->x_buffer[filter->buffer_index] = (float)x;
    filter->y_buffer[filter->buffer_index] = (float)y;
    filter->z_buffer[filter->buffer_index] = (float)z;
    filter->buffer_index = (filter->buffer_index + 1) % WINDOW_SIZE;

    // Recompute mean
    float sum_x = 0, sum_y = 0, sum_z = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        sum_x += filter->x_buffer[i];
        sum_y += filter->y_buffer[i];
        sum_z += filter->z_buffer[i];
    }
    filter->x_mean = sum_x / WINDOW_SIZE;
    filter->y_mean = sum_y / WINDOW_SIZE;
    filter->z_mean = sum_z / WINDOW_SIZE;

    // Recompute standard deviation
    float var_x = 0, var_y = 0, var_z = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        var_x += powf(filter->x_buffer[i] - filter->x_mean, 2);
        var_y += powf(filter->y_buffer[i] - filter->y_mean, 2);
        var_z += powf(filter->z_buffer[i] - filter->z_mean, 2);
    }
    filter->x_std = sqrtf(var_x / WINDOW_SIZE);
    filter->y_std = sqrtf(var_y / WINDOW_SIZE);
    filter->z_std = sqrtf(var_z / WINDOW_SIZE);
}

// --- Anomaly Detection ---
typedef struct {
    int anomaly_count;
} AnomalyDetector;

void detector_init(AnomalyDetector *detector) {
    detector->anomaly_count = 0;
}

int is_anomaly(AnomalyDetector *detector, MovingAverageFilter *filter) {
    // Check if any axis exceeds the threshold
    int anomaly = 0;
    if (fabsf(filter->x_mean - filter->x_buffer[filter->buffer_index]) > ANOMALY_THRESHOLD * filter->x_std) {
        anomaly = 1;
    }
    if (fabsf(filter->y_mean - filter->y_buffer[filter->buffer_index]) > ANOMALY_THRESHOLD * filter->y_std) {
        anomaly = 1;
    }
    if (fabsf(filter->z_mean - filter->z_buffer[filter->buffer_index]) > ANOMALY_THRESHOLD * filter->z_std) {
        anomaly = 1;
    }

    if (anomaly) {
        detector->anomaly_count++;
        return 1;
    }
    return 0;
}

// --- Main Pipeline ---
int main() {
    uart_init();
    uart_write("Starting anomaly detection pipeline...\r\n");

    if (sensor_init() != 0) {
        uart_write("ERROR: Sensor initialization failed!\r\n");
        return -1;
    }

    MovingAverageFilter filter;
    filter_init(&filter);

    AnomalyDetector detector;
    detector_init(&detector);

    while (1) {
        int16_t x, y, z;
        if (sensor_read(&x, &y, &z) != 0) {
            uart_write("ERROR: Sensor read failed!\r\n");
            continue;
        }

        filter_update(&filter, x, y, z);
        if (is_anomaly(&detector, &filter)) {
            char msg[64];
            snprintf(msg, sizeof(msg),
                     "ANOMALY DETECTED! Count: %d, X: %d, Y: %d, Z: %d\r\n",
                     detector.anomaly_count, x, y, z);
            uart_write(msg);
        }

        // Simulate real-time delay (e.g., 10ms)
        // Replace with your platform's delay function
        for (volatile int i = 0; i < 100000; i++);
    }

    return 0;
}
