## **3. C++ Version (OOP Approach)**
For larger projects, here’s an object-oriented version:
```cpp
#include <cmath>
#include <array>
#include <string>

// Hardware Abstraction (platform-specific)
class Sensor {
public:
    virtual bool init() = 0;
    virtual bool read(int16_t &x, int16_t &y, int16_t &z) = 0;
};

class UART {
public:
    virtual void write(const std::string &msg) = 0;
};

// Signal Processing
class MovingAverageFilter {
private:
    static constexpr size_t WINDOW_SIZE = 10;
    std::array<float, WINDOW_SIZE> x_buffer, y_buffer, z_buffer;
    size_t buffer_index = 0;
    float x_mean, y_mean, z_mean;
    float x_std, y_std, z_std;

public:
    void init() {
        x_buffer.fill(0);
        y_buffer.fill(0);
        z_buffer.fill(0);
    }

    void update(int16_t x, int16_t y, int16_t z) {
        x_buffer[buffer_index] = static_cast<float>(x);
        y_buffer[buffer_index] = static_cast<float>(y);
        z_buffer[buffer_index] = static_cast<float>(z);
        buffer_index = (buffer_index + 1) % WINDOW_SIZE;

        // Recompute mean
        float sum_x = 0, sum_y = 0, sum_z = 0;
        for (float val : x_buffer) sum_x += val;
        for (float val : y_buffer) sum_y += val;
        for (float val : z_buffer) sum_z += val;
        x_mean = sum_x / WINDOW_SIZE;
        y_mean = sum_y / WINDOW_SIZE;
        z_mean = sum_z / WINDOW_SIZE;

        // Recompute std
        float var_x = 0, var_y = 0, var_z = 0;
        for (float val : x_buffer) var_x += powf(val - x_mean, 2);
        for (float val : y_buffer) var_y += powf(val - y_mean, 2);
        for (float val : z_buffer) var_z += powf(val - z_mean, 2);
        x_std = sqrtf(var_x / WINDOW_SIZE);
        y_std = sqrtf(var_y / WINDOW_SIZE);
        z_std = sqrtf(var_z / WINDOW_SIZE);
    }

    bool is_anomaly(float threshold = 2.0f) const {
        return (fabsf(x_buffer[buffer_index] - x_mean) > threshold * x_std) ||
               (fabsf(y_buffer[buffer_index] - y_mean) > threshold * y_std) ||
               (fabsf(z_buffer[buffer_index] - z_mean) > threshold * z_std);
    }
};

// Anomaly Detector
class AnomalyDetector {
private:
    int anomaly_count = 0;

public:
    void reset() { anomaly_count = 0; }
    int get_count() const { return anomaly_count; }
    void increment() { anomaly_count++; }
};

// Main Pipeline
class Pipeline {
private:
    Sensor &sensor;
    UART &uart;
    MovingAverageFilter filter;
    AnomalyDetector detector;

public:
    Pipeline(Sensor &s, UART &u) : sensor(s), uart(u) {}

    void run() {
        if (!sensor.init()) {
            uart.write("ERROR: Sensor init failed!\n");
            return;
        }

        filter.init();
        detector.reset();

        while (true) {
            int16_t x, y, z;
            if (!sensor.read(x, y, z)) {
                uart.write("ERROR: Sensor read failed!\n");
                continue;
            }

            filter.update(x, y, z);
            if (filter.is_anomaly()) {
                detector.increment();
                uart.write("ANOMALY! Count: " + std::to_string(detector.get_count()) +
                           ", X: " + std::to_string(x) +
                           ", Y: " + std::to_string(y) +
                           ", Z: " + std::to_string(z) + "\n");
            }
        }
    }
};
