// Signal Processing
pub struct MovingAverageFilter {
    x_buffer: [f32; 10],
    y_buffer: [f32; 10],
    z_buffer: [f32; 10],
    buffer_index: usize,
    x_mean: f32,
    y_mean: f32,
    z_mean: f32,
    x_std: f32,
    y_std: f32,
    z_std: f32,
}

impl MovingAverageFilter {
    pub fn new() -> Self {
        MovingAverageFilter {
            x_buffer: [0.0; 10],
            y_buffer: [0.0; 10],
            z_buffer: [0.0; 10],
            buffer_index: 0,
            x_mean: 0.0,
            y_mean: 0.0,
            z_mean: 0.0,
            x_std: 0.0,
            y_std: 0.0,
            z_std: 0.0,
        }
    }

    pub fn update(&mut self, x: i16, y: i16, z: i16) {
        self.x_buffer[self.buffer_index] = x as f32;
        self.y_buffer[self.buffer_index] = y as f32;
        self.z_buffer[self.buffer_index] = z as f32;
        self.buffer_index = (self.buffer_index + 1) % 10;

        // Recompute mean
        self.x_mean = self.x_buffer.iter().sum::<f32>() / 10.0;
        self.y_mean = self.y_buffer.iter().sum::<f32>() / 10.0;
        self.z_mean = self.z_buffer.iter().sum::<f32>() / 10.0;

        // Recompute std
        self.x_std = self.x_buffer.iter()
            .map(|v| (v - self.x_mean).powi(2))
            .sum::<f32>()
            .sqrt() / 10.0;
        self.y_std = self.y_buffer.iter()
            .map(|v| (v - self.y_mean).powi(2))
            .sum::<f32>()
            .sqrt() / 10.0;
        self.z_std = self.z_buffer.iter()
            .map(|v| (v - self.z_mean).powi(2))
            .sum::<f32>()
            .sqrt() / 10.0;
    }

    pub fn is_anomaly(&self, threshold: f32) -> bool {
        let idx = (self.buffer_index + 9) % 10;  // Most recent value
        (self.x_buffer[idx] - self.x_mean).abs() > threshold * self.x_std ||
        (self.y_buffer[idx] - self.y_mean).abs() > threshold * self.y_std ||
        (self.z_buffer[idx] - self.z_mean).abs() > threshold * self.z_std
    }
}

