### **2. Minimal Working Code (`main.c`)**
```c
#include "stm32f4xx_hal.h"
#include <math.h>
#include <stdbool.h>

// ADXL345 I2C Address
#define ADXL345_ADDR          (0x53 << 1)  // 7-bit address shifted left by 1
#define ADXL345_REG_DEVID    0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0   0x32

// Anomaly detection threshold (adjust based on your application)
#define RMS_THRESHOLD         1.5f  // g-force threshold (e.g., 1.5g)

// Global variables
I2C_HandleTypeDef hi2c1;
UART_HandleTypeDef huart2;

// Function prototypes
void SystemClock_Config(void);
static void MX_GPIO_Init(void);
static void MX_I2C1_Init(void);
static void MX_USART2_UART_Init(void);
void ADXL345_Init(void);
void ADXL345_ReadAccel(float *x, float *y, float *z);
float CalculateRMS(float x, float y, float z);
void LogAnomaly(float rms);

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_I2C1_Init();
    MX_USART2_UART_Init();

    ADXL345_Init();  // Configure accelerometer

    float x, y, z;
    float rms;
    bool anomaly_detected = false;

    while (1) {
        ADXL345_ReadAccel(&x, &y, &z);
        rms = CalculateRMS(x, y, z);

        // Simple low-pass filter (optional)
        static float filtered_rms = 0.0f;
        filtered_rms = 0.9f * filtered_rms + 0.1f * rms;

        // Check for anomaly
        if (filtered_rms > RMS_THRESHOLD) {
            if (!anomaly_detected) {
                LogAnomaly(filtered_rms);
                HAL_GPIO_TogglePin(GPIOC, GPIO_PIN_13);  // Toggle LED
                anomaly_detected = true;
            }
        } else {
            anomaly_detected = false;
        }

        HAL_Delay(50);  // 20Hz sampling rate
    }
}

// Initialize ADXL345
void ADXL345_Init(void) {
    uint8_t data[2];

    // Check device ID (optional)
    data[0] = ADXL345_REG_DEVID;
    HAL_I2C_Master_Transmit(&hi2c1, ADXL345_ADDR, data, 1, HAL_MAX_DELAY);
    HAL_I2C_Master_Receive(&hi2c1, ADXL345_ADDR, data, 1, HAL_MAX_DELAY);
    if (data[0] != 0xE5) {
        // Error: ADXL345 not detected
        while (1);
    }

    // Enable measurement mode
    data[0] = ADXL345_REG_POWER_CTL;
    data[1] = 0x08;  // Set measure bit
    HAL_I2C_Master_Transmit(&hi2c1, ADXL345_ADDR, data, 2, HAL_MAX_DELAY);
}

// Read accelerometer data (X, Y, Z in g-force)
void ADXL345_ReadAccel(float *x, float *y, float *z) {
    uint8_t data[6];
    int16_t raw_x, raw_y, raw_z;

    // Read 6 bytes starting from DATAX0
    data[0] = ADXL345_REG_DATAX0;
    HAL_I2C_Master_Transmit(&hi2c1, ADXL345_ADDR, data, 1, HAL_MAX_DELAY);
    HAL_I2C_Master_Receive(&hi2c1, ADXL345_ADDR, data, 6, HAL_MAX_DELAY);

    // Combine bytes (little-endian)
    raw_x = (data[1] << 8) | data[0];
    raw_y = (data[3] << 8) | data[2];
    raw_z = (data[5] << 8) | data[4];

    // Convert to g-force (±16g range, 10-bit resolution)
    *x = raw_x * 0.0039f;  // 16g / 4096 = 0.0039 g/LSB
    *y = raw_y * 0.0039f;
    *z = raw_z * 0.0039f;
}

// Calculate RMS of acceleration magnitude
float CalculateRMS(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

// Log anomaly via UART
void LogAnomaly(float rms) {
    char msg[50];
    int len = snprintf(msg, sizeof(msg), "Anomaly detected! RMS: %.2fg\r\n", rms);
    HAL_UART_Transmit(&huart2, (uint8_t *)msg, len, HAL_MAX_DELAY);
}

// STM32 HAL callbacks (minimal implementations)
void SystemClock_Config(void) {
    // Configure system clock (e.g., 168MHz for STM32F4)
    // (Typically generated by CubeMX; omitted for brevity)
}

static void MX_I2C1_Init(void) {
    hi2c1.Instance = I2C1;
    hi2c1.Init.ClockSpeed = 100000;  // 100kHz
    hi2c1.Init.DutyCycle = I2C_DUTYCYCLE_2;
    hi2c1.Init.OwnAddress1 = 0;
    hi2c1.Init.AddressingMode = I2C_ADDRESSINGMODE_7BIT;
    hi2c1.Init.DualAddressMode = I2C_DUALADDRESS_DISABLE;
    hi2c1.Init.OwnAddress2 = 0;
    hi2c1.Init.GeneralCallMode = I2C_GENERALCALL_DISABLE;
    hi2c1.Init.NoStretchMode = I2C_NOSTRETCH_DISABLE;
    HAL_I2C_Init(&hi2c1);
}

static void MX_USART2_UART_Init(void) {
    huart2.Instance = USART2;
    huart2.Init.BaudRate = 115200;
    huart2.Init.WordLength = UART_WORDLENGTH_8B;
    huart2.Init.StopBits = UART_STOPBITS_1;
    huart2.Init.Parity = UART_PARITY_NONE;
    huart2.Init.Mode = UART_MODE_TX_RX;
