```rust
#![no_std]
#![no_main]

use panic_halt as _;
use cortex_m_rt::entry;
use embedded_hal::{
    blocking::delay::DelayMs,
    i2c::{I2c, WriteRead},
};
use fixed::types::I16F16; // Fixed-point arithmetic (no FPU needed)

// --- Constants ---
const ACCEL_ADDR: u8 = 0x68; // MPU6050 default I2C address
const ACCEL_XOUT_H: u8 = 0x3B;
const WINDOW_SIZE: usize = 10; // Moving average window
const ANOMALY_THRESHOLD: i16 = 3000; // ~3x std dev in fixed-point

// --- Data Structures ---
#[derive(Debug, Clone, Copy)]
struct AccelData {
    x: i16,
    y: i16,
    z: i16,
}

impl AccelData {
    // Calculate magnitude (fixed-point, no floating point)
    fn magnitude(&self) -> i16 {
        let x = I16F16::from_num(self.x);
        let y = I16F16::from_num(self.y);
        let z = I16F16::from_num(self.z);
        let mag = (x*x + y*y + z*z).sqrt();
        (mag * I16F16::from_num(16384)).to_num() // Scale to approximate g's * 16384
    }
}

// --- Moving Statistics ---
struct MovingStats {
    window: [i16; WINDOW_SIZE],
    index: usize,
    sum: i32,
}

impl MovingStats {
    fn new() -> Self {
        MovingStats {
            window: [0; WINDOW_SIZE],
            index: 0,
            sum: 0,
        }
    }

    fn add(&mut self, value: i16) {
        self.sum -= self.window[self.index] as i32;
        self.window[self.index] = value;
        self.sum += value as i32;
        self.index = (self.index + 1) % WINDOW_SIZE;
    }

    fn mean(&self) -> i16 {
        if self.window.iter().all(|&v| v == 0) {
            0
        } else {
            (self.sum / WINDOW_SIZE as i32) as i16
        }
    }

    fn std_dev(&self) -> i16 {
        let mean = self.mean() as i32;
        let variance = self.window.iter()
            .map(|&v| {
                let diff = (v as i32 - mean).abs();
                (diff * diff) as i32
            })
            .sum::<i32>() / WINDOW_SIZE as i32;
        (variance.sqrt() as i16).min(1000) // Clamp to prevent overflow
    }

    fn is_anomaly(&self, value: i16) -> bool {
        let mean = self.mean() as i32;
        let std_dev = self.std_dev() as i32;
        if std_dev == 0 {
            false
        } else {
            let diff = (value as i32 - mean).abs();
            diff > (ANOMALY_THRESHOLD as i32 * std_dev / 100) // Scale to avoid floating point
        }
    }
}

