static float simulate_accel_data(int sample_count) {
    const float baseline = 1.0f;  // Baseline acceleration (1g)
    const float spike = 3.0f;     // Anomaly spike (3g)
    const int spike_start = 5 * SAMPLE_RATE_HZ;  // After 5 seconds

    if (sample_count >= spike_start) {
        return spike;
    } else {
        return baseline;
    }
}
#endif

// ===== Moving Average Filter =====
typedef struct {
    float buffer[WINDOW_SIZE];
    uint8_t index;
    float sum;
} MovingAverageFilter;

void ma_init(MovingAverageFilter* filter) {
    for (int i = 0; i < WINDOW_SIZE; i++) {
        filter->buffer[i] = 0.0f;
    }
    filter->index = 0;
    filter->sum = 0.0f;
}

float ma_update(MovingAverageFilter* filter, float new_value) {
    filter->sum -= filter->buffer[filter->index];
    filter->buffer[filter->index] = new_value;
    filter->sum += new_value;
    filter->index = (filter->index + 1) % WINDOW_SIZE;
    return filter->sum / WINDOW_SIZE;
}

// ===== Anomaly Detection =====
bool is_anomaly(float magnitude) {
    return magnitude > ANOMALY_THRESHOLD;
}

// ===== Main Pipeline =====
int main() {
    printf("=== Embedded Anomaly Detection Pipeline ===\n");

    MovingAverageFilter filter;
    ma_init(&filter);

    uint32_t sample_count = 0;
    bool anomaly_detected = false;

    while (1) {
        // --- 1. Read Accelerometer Data ---
#if SIMULATED_DATA
        float accel_x = simulate_accel_data(sample_count);
        float accel_y = 0.0f;
        float accel_z = 0.0f;
