        printf("ERROR: Real accelerometer not implemented. Use SIMULATED_DATA=1.\n");
        return 1;
#endif

        // --- 2. Calculate Magnitude (3-axis) ---
        float magnitude = sqrtf(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z);

        // --- 3. Apply Moving Average Filter ---
        float filtered_magnitude = ma_update(&filter, magnitude);

        // --- 4. Detect Anomaly ---
        if (is_anomaly(filtered_magnitude) && !anomaly_detected) {
            anomaly_detected = true;
            printf("[ALERT] Anomaly detected! Magnitude: %.2fg (Threshold: %.2fg)\n",
                   filtered_magnitude, ANOMALY_THRESHOLD);

