#include "stm32f4xx_hal.h"
#include "mpu6050.h"
#include <math.h>
#include <stdio.h>

#define ANOMALY_THRESHOLD 1.5f // in g's (e.g., 1.5g)
#define MOVING_AVG_WINDOW 10   // Number of samples for moving average

I2C_HandleTypeDef hi2c1;
UART_HandleTypeDef huart2;

void SystemClock_Config(void);
static void MX_GPIO_Init(void);
static void MX_I2C1_Init(void);
static void MX_USART2_UART_Init(void);

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_I2C1_Init();
    MX_USART2_UART_Init();

    // Initialize MPU6050
    if (MPU6050_Init(&hi2c1) != HAL_OK) {
        printf("MPU6050 initialization failed!\r\n");
        while (1);
    }

    printf("MPU6050 initialized. Starting anomaly detection...\r\n");

    float accel_magnitude_history[MOVING_AVG_WINDOW] = {0};
    float sum = 0.0f;
    uint8_t history_index = 0;

    while (1) {
        // Read accelerometer data
        MPU6050_ReadAccel(&hi2c1, &accel_magnitude_history[history_index]);

        // Update moving average
        sum += accel_magnitude_history[history_index];
        if (history_index == 0) {
            sum -= accel_magnitude_history[MOVING_AVG_WINDOW - 1];
        } else {
            sum -= accel_magnitude_history[history_index - 1];
        }
        history_index = (history_index + 1) % MOVING_AVG_WINDOW;
        float moving_avg = sum / MOVING_AVG_WINDOW;

        // Simple anomaly detection: if current magnitude is 2x the moving average, it's an anomaly
        float current_magnitude = accel_magnitude_history[history_index];
        if (current_magnitude > 2.0f * moving_avg) {
            printf("Anomaly detected! Magnitude: %.2fg, Avg: %.2fg\r\n", current_magnitude, moving_avg);
            HAL_GPIO_WritePin(GPIOA, GPIO_PIN_5, GPIO_PIN_SET); // Turn on LED
        } else {
            HAL_GPIO_WritePin(GPIOA, GPIO_PIN_5, GPIO_PIN_RESET); // Turn off LED
        }

        HAL_Delay(100); // 10Hz sampling rate
    }
}
