```rust
#![no_std]
#![no_main]

use panic_halt as _;
use cortex_m_rt::entry;
use embedded_hal::{
    blocking::delay::DelayMs,
    i2c::{I2c, WriteRead},
};
use fixed::types::I16F16;
use fixed_sqrt::FixedSqrt;

// Constants
const WINDOW_SIZE: usize = 10;
const ANOMALY_THRESHOLD: i16 = 3000; // Fixed-point threshold

#[derive(Debug, Clone, Copy)]
struct AccelData {
    x: i16,
    y: i16,
    z: i16,
}

impl AccelData {
    fn magnitude(&self) -> i16 {
        // Fixed-point magnitude calculation
        // sqrt(x² + y² + z²) scaled by 2^16
        let x = I16F16::from_num(self.x);
        let y = I16F16::from_num(self.y);
        let z = I16F16::from_num(self.z);
        let mag = (x*x + y*y + z*z).sqrt();
        (mag * I16F16::from_num(16384)).to_num() // Scale back to approximate g's * 16384
    }
}

struct MovingStats {
    window: [i16; WINDOW_SIZE],
    index: usize,
    sum: i32,
}

impl MovingStats {
    fn new() -> Self {
        MovingStats {
            window: [0; WINDOW_SIZE],
            index: 0,
            sum: 0,
        }
    }

    fn add(&mut self, value: i16) {
        self.sum -= self.window[self.index] as i32;
        self.window[self.index] = value;
        self.sum += value as i32;
        self.index = (self.index + 1) % WINDOW_SIZE;
    }

    fn mean(&self) -> i16 {
        if self.window.iter().all(|&v| v == 0) {
            0
        } else {
            (self.sum / WINDOW_SIZE as i32) as i16
        }
    }

    fn std_dev(&self) -> i16 {
        let mean = self.mean() as i32;
        let variance = self.window.iter()
            .map(|&v| {
                let diff = (v as i32 - mean).abs();
                (diff * diff) as i32
            })
            .sum::<i32>() / WINDOW_SIZE as i32;
        (variance.sqrt() as i16).min(1000) // Clamp to prevent overflow
    }

    fn z_score(&self, value: i16) -> i16 {
        let mean = self.mean() as i32;
        let std_dev = self.std_dev() as i32;
        if std_dev == 0 {
            0
        } else {
            let diff = (value as i32 - mean).abs();
            (diff * 100 / std_dev) as i16 // Scale to avoid floating point
        }
    }
}

#[entry]
fn main() -> ! {
    // Hardware initialization would be here
    // let dp = stm32f4xx_hal::pac::Peripherals::take().unwrap();
    // let mut delay = dp.TIM1.delay_ms(84_000_000);
    // let i2c = dp.I2C1.i2c(...);
    // let mut uart = dp.USART1.usart(...);

    let mut stats = MovingStats::new();
    let mut anomaly_count = 0;

    loop {
        // Simulate reading accelerometer
        let accel_data = AccelData {
            x: 100,
            y: 200,
            z: 300,
        };

        let magnitude = accel_data.magnitude();
        stats.add(magnitude);

        // Detect anomaly using Z-score
        let z_score = stats.z_score(magnitude);
        if z_score > 300 { // 3.0 in fixed-point (300 = 3.0 * 100)
            anomaly_count += 1;
            // In real code: uart.write_str("Anomaly detected!\n").unwrap();
        }

        // Simple threshold check as backup
        if magnitude > 2000 { // ~0.12g threshold
            anomaly_count += 1;
        }

        // Delay
