// Moving average filter implementation
struct MovingAverageFilter {
    buffer: [u16; 5], // 5-point moving average
    index: usize,
    sum: u32,
}

impl MovingAverageFilter {
    fn new() -> Self {
        MovingAverageFilter {
            buffer: [0; 5],
            index: 0,
            sum: 0,
        }
    }

    fn add_value(&mut self, value: u16) -> u16 {
        self.sum -= self.buffer[self.index] as u32;
        self.sum += value as u32;
        self.buffer[self.index] = value;
        self.index = (self.index + 1) % self.buffer.len();
        (self.sum / self.buffer.len() as u32) as u16
    }
}

#[entry]
fn main() -> ! {
    // Get access to device peripherals
    let dp = pac::Peripherals::take().unwrap();
    let cp = cortex_m::Peripherals::take().unwrap();

    // Set up the system clock
    let mut flash = dp.FLASH.constrain();
    let mut rcc = dp.RCC.constrain();
    let clocks = rcc.cfgr.freeze(&mut flash.acr);

    // Set up ADC for temperature sensor (connected to PA0)
    let mut adc = adc::Adc::adc1(dp.ADC1, clocks);
    let mut sensor_pin = dp.GPIOA.pa0.into_analog_input(&mut dp.GPIOA.crl);

    // Set up fan actuator (connected to PA1)
    let mut fan_pin = dp.GPIOA.pa1.into_push_pull_output(&mut dp.GPIOA.crl);
    let mut fan = Fan::new(fan_pin);

    // Initialize filter
    let mut filter = MovingAverageFilter::new();

    // Threshold for turning on the fan (example: 2000 = 2.00V)
    const TEMP_THRESHOLD: u16 = 2000;

    // Set up a timer for delays
    let mut timer = Timer::syst(cp.SYST, &clocks).unwrap();

    loop {
        // Read raw ADC value from temperature sensor
        let raw_temp = adc.read(&mut sensor_pin).unwrap();

        // Apply moving average filter
        let filtered_temp = filter.add_value(raw_temp);

        // Control actuator based on filtered data
        if filtered_temp > TEMP_THRESHOLD {
            fan.turn_on();
        } else {
            fan.turn_off();
        }

        // Delay for 1 second between readings
        timer.delay_ms(1000u32);
    }
}

