#define FILTER_WINDOW_SIZE 5

static float filter_buffer[FILTER_WINDOW_SIZE] = {0};
static uint8_t filter_index = 0;
static float filter_sum = 0.0f;

void filter_init(void) {
    // Initialize the filter buffer and sum
    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++) {
        filter_buffer[i] = 0.0f;
    }
    filter_index = 0;
    filter_sum = 0.0f;
}

float filter_apply(int16_t raw_value) {
    // Subtract the oldest value from the sum
    filter_sum -= filter_buffer[filter_index];

    // Add the new raw value (converted to float) to the buffer and sum
    float new_value = (float)raw_value;
    filter_buffer[filter_index] = new_value;
    filter_sum += new_value;

    // Update the index (with wrap-around)
    filter_index = (filter_index + 1) % FILTER_WINDOW_SIZE;

    // Return the average
    return filter_sum / FILTER_WINDOW_SIZE;
}
