// Define a simple low-pass filter (exponential moving average)
struct LowPassFilter {
    alpha: f32,       // Smoothing factor (0 < alpha < 1)
    value: f32,       // Current filtered value
}

impl LowPassFilter {
    fn new(alpha: f32) -> Self {
        Self { alpha, value: 0.0 }
    }

    fn update(&mut self, new_value: f32) -> f32 {
        self.value = self.alpha * new_value + (1.0 - self.alpha) * self.value;
        self.value
    }
}

// Simulated sensor (e.g., temperature sensor)
