        }

        const Uint8* currentKeyStates = SDL_GetKeyboardState(nullptr);

        // Reset horizontal movement
        float horizontalForce = 0.0f;

        // Handle left/right movement
        if (currentKeyStates[SDL_SCANCODE_LEFT]) {
            horizontalForce -= 10.0f;
            playerState = PlayerState::RUNNING;
            playerDirection = -1;
        } else if (currentKeyStates[SDL_SCANCODE_RIGHT]) {
            horizontalForce += 10.0f;
            playerState = PlayerState::RUNNING;
            playerDirection = 1;
        } else {
            playerState = PlayerState::IDLE;
        }

        // Apply force to player
        playerBody->ApplyForceToCenter(b2Vec2(horizontalForce, 0.0f), true);

        // Handle jumping
        if (currentKeyStates[SDL_SCANCODE_SPACE] && isGrounded) {
            playerBody->ApplyLinearImpulseToCenter(b2Vec2(0.0f, -15.0f), true);
            isGrounded = false;
            playerState = PlayerState::JUMPING;
        }

        // Update player state based on vertical velocity
        float verticalVelocity = playerBody->GetLinearVelocity().y;
        if (verticalVelocity > 0.1f) {
            playerState = PlayerState::FALLING;
        } else if (verticalVelocity < -0.1f) {
            playerState = PlayerState::JUMPING;
        }
    }

    void update(float deltaTime) {
