        // Update Box2D world
        world->Step(TIME_STEP, VELOCITY_ITERATIONS, POSITION_ITERATIONS);

        // Check if player is grounded
        b2Vec2 position = playerBody->GetPosition();
        b2Vec2 bottomCenter(position.x, position.y + 1.0f);
        b2Fixture* fixture = playerBody->GetFixtureList();
        b2AABB aabb;
        fixture->GetShape()->ComputeAABB(&aabb, playerBody->GetTransform(), 0);

        // Simple ground check (in a real game you'd use proper collision detection)
        if (position.y * PIXELS_PER_METER > WINDOW_HEIGHT - playerHeight - 10) {
            isGrounded = true;
            playerState = PlayerState::IDLE;
        } else {
            isGrounded = false;
        }
    }

    void render() {
        SDL_SetRenderDrawColor(renderer, 135, 206, 235, 255); // Sky blue
        SDL_RenderClear(renderer);

        // Draw ground
        SDL_SetRenderDrawColor(renderer, 0, 100, 0, 255); // Dark green
        SDL_Rect groundRect = {0, WINDOW_HEIGHT - 50, WINDOW_WIDTH, 50};
        SDL_RenderFillRect(renderer, &groundRect);

        // Get player position and convert to screen coordinates
        b2Vec2 position = playerBody->GetPosition();
        float angle = playerBody->GetAngle();
        int screenX = static_cast<int>(position.x * PIXELS_PER_METER);
        int screenY = static_cast<int>(position.y * PIXELS_PER_METER);

        // Get current animation frame
        SDL_Texture* currentFrame = currentAnimation->getCurrentFrame(0.016f); // ~60fps

        // Render player
        SDL_Rect renderQuad = {
            screenX - static_cast<int>(playerWidth/2),
            screenY - static_cast<int>(playerHeight/2),
            static_cast<int>(playerWidth),
            static_cast<int>(playerHeight)
        };

        SDL_RendererFlip flip = (playerDirection == 1) ? SDL_FLIP_NONE : SDL_FLIP_HORIZONTAL;
        SDL_RenderCopyEx(renderer, currentFrame, nullptr, &renderQuad, 0, nullptr, flip);

        SDL_RenderPresent(renderer);
    }

    void clean() {
        // Clean up textures
        SDL_DestroyTexture(playerIdle);
        SDL_DestroyTexture(playerRun1);
        SDL_DestroyTexture(playerRun2);
        SDL_DestroyTexture(playerJump);
        SDL_DestroyTexture(playerFall);

        // Clean up Box2D
        delete world;

        // Clean up SDL
        SDL_DestroyRenderer(renderer);
        SDL_DestroyWindow(window);
        SDL_Quit();
    }

    void run() {
        Uint32 lastTime = SDL_GetTicks();
        while (isRunning) {
            Uint32 currentTime = SDL_GetTicks();
            float deltaTime = (currentTime - lastTime) / 1000.0f;
            lastTime = currentTime;

            handleInput();
            update(deltaTime);
            render();
        }
    }

private:
    bool isRunning;
    SDL_Window* window;
    SDL_Renderer* renderer;
    b2World* world;

    // Player
    b2Body* playerBody;
    b2Fixture* playerFixture;
    float playerWidth;
    float playerHeight;
    int playerDirection;
    PlayerState playerState;
