```wgsl
// Vertex shader
struct Camera {
    view_proj: mat4x4<f32>,
};

@group(0) @binding(0)
var<uniform> camera: Camera;

struct VertexInput {
    @location(0) position: vec3<f32>,
    @location(1) normal: vec3<f32>,
};

struct VertexOutput {
    @builtin(position) clip_position: vec4<f32>,
    @location(0) world_position: vec3<f32>,
    @location(1) world_normal: vec3<f32>,
};

@vertex
fn vs_main(
    model: VertexInput,
) -> VertexOutput {
    let world_position = model.position;
    let world_normal = model.normal;

    let clip_position = camera.view_proj * vec4<f32>(world_position, 1.0);

    return VertexOutput(clip_position, world_position, world_normal);
}

// Fragment shader
struct Light {
    position: vec3<f32>,
    color: vec3<f32>,
    intensity: f32,
};

@group(0) @binding(1)
var<uniform> light: Light;

@fragment
fn fs_main(in: VertexOutput) -> @location(0) vec4<f32> {
    let light_dir = normalize(light.position - in.world_position);
    let diffuse = max(dot(in.world_normal, light_dir), 0.0) * light.color * light.intensity;

    let ambient = 0.1;
    let final_color = (diffuse + ambient) * vec3<f32>(1.0, 1.0, 1.0); // Assuming white object color

    return vec4<f32>(final_color, 1.0);
}
