# Custom Physics Plugin for Unity (C#)

Here's a complete implementation of a basic custom physics plugin for Unity. This provides a simplified physics system that can be integrated into your game.

## 1. Core Physics Components

```csharp
// CustomRigidbody.cs - Handles physics properties and motion
using UnityEngine;

[RequireComponent(typeof(SphereCollider))]
public class CustomRigidbody : MonoBehaviour
{
    [Header("Physics Properties")]
    public float mass = 1.0f;
    public Vector3 velocity;
    public Vector3 acceleration;
    public bool useGravity = true;
    public float drag = 0.0f;
    public float angularDrag = 0.05f;

    [Header("State")]
    public bool isKinematic = false;
    public bool detectCollisions = true;

    private SphereCollider col;
    private Transform cachedTransform;

    private void Awake()
    {
        cachedTransform = transform;
        col = GetComponent<SphereCollider>();
    }

    private void Start()
    {
        acceleration = Vector3.zero;
        velocity = Vector3.zero;
    }

    private void FixedUpdate()
    {
        if (isKinematic) return;

        if (useGravity)
        {
            acceleration += Physics.gravity * mass;
        }

        // Apply drag
        velocity *= (1.0f - drag * Time.fixedDeltaTime);
        angularDrag = Mathf.Clamp01(angularDrag);

        // Update position
        Vector3 displacement = velocity * Time.fixedDeltaTime + 0.5f * acceleration * Time.fixedDeltaTime * Time.fixedDeltaTime;
        cachedTransform.position += displacement;

        // Update velocity
        velocity += acceleration * Time.fixedDeltaTime;

        // Reset acceleration for next frame
        acceleration = Vector3.zero;
    }

    public void AddForce(Vector3 force)
    {
        if (isKinematic) return;
        acceleration += force / mass;
    }

    public void AddForceAtPosition(Vector3 force, Vector3 position)
    {
        if (isKinematic) return;

        // Simple implementation - in a real system you'd calculate torque
        AddForce(force);
    }

    public void MovePosition(Vector3 newPosition)
    {
        if (isKinematic)
        {
            cachedTransform.position = newPosition;
        }
    }
}
