    public float radius = 1.0f;
    public bool isTrigger = false;
    public LayerMask collisionMask = ~0; // All layers by default

    public float Radius => radius;

    public bool CheckCollision(SphereCollider other)
    {
        // Check if layers should collide
        if ((collisionMask.value & (1 << other.gameObject.layer)) == 0)
            return false;

        float distance = Vector3.Distance(transform.position, other.transform.position);
        return distance < (radius + other.radius);
    }

    public bool CheckCollision(Vector3 point)
    {
        return Vector3.Distance(transform.position, point) <= radius;
    }

