## 2. Collision System

```csharp
// CollisionManager.cs - Handles all collision detection and response
using System.Collections.Generic;
using UnityEngine;

public class CollisionManager : MonoBehaviour
{
    public static CollisionManager Instance { get; private set; }

    [Header("Collision Settings")]
    public int maxCollisionIterations = 10;
    public float collisionMargin = 0.1f;

    private List<SphereCollider> colliders = new List<SphereCollider>();
    private List<CustomRigidbody> rigidbodies = new List<CustomRigidbody>();

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }

        Instance = this;
    }

    private void Start()
    {
        // Find all colliders and rigidbodies in the scene
        colliders.AddRange(FindObjectsOfType<SphereCollider>());
        rigidbodies.AddRange(FindObjectsOfType<CustomRigidbody>());
    }

    private void FixedUpdate()
    {
        // Update collider lists in case objects were added/removed
        colliders.Clear();
        rigidbodies.Clear();
        colliders.AddRange(FindObjectsOfType<SphereCollider>());
        rigidbodies.AddRange(FindObjectsOfType<CustomRigidbody>());

        // Perform collision detection and resolution
        for (int iteration = 0; iteration < maxCollisionIterations; iteration++)
        {
            bool collisionOccurred = false;

            for (int i = 0; i < colliders.Count; i++)
            {
                for (int j = i + 1; j < colliders.Count; j++)
                {
                    if (colliders[i].CheckCollision(colliders[j]))
                    {
                        HandleCollision(colliders[i], colliders[j]);
                        collisionOccurred = true;
                    }
                }
            }

            if (!collisionOccurred) break;
        }
    }

    private void HandleCollision(SphereCollider a, SphereCollider b)
    {
        CustomRigidbody rbA = a.GetComponent<CustomRigidbody>();
        CustomRigidbody rbB = b.GetComponent<CustomRigidbody>();

        if (rbA == null || rbB == null || !rbA.detectCollisions || !rbB.detectCollisions)
            return;

        if (rbA.isKinematic && rbB.isKinematic)
            return;

        Vector3 normal = (a.transform.position - b.transform.position).normalized;
        float distance = Vector3.Distance(a.transform.position, b.transform.position);
        float overlap = (a.Radius + b.Radius) - distance;

        // Calculate relative velocity
        Vector3 relativeVelocity = rbA.velocity - rbB.velocity;

        // Calculate impulse
        float e = 0.5f; // Coefficient of restitution (bounciness)
        float impulseMagnitude = -(1 + e) * Vector3.Dot(relativeVelocity, normal) /
                                ((1/rbA.mass) + (1/rbB.mass));

        Vector3 impulse = impulseMagnitude * normal;

        // Apply impulse
        if (!rbA.isKinematic)
        {
            rbA.velocity += (impulse / rbA.mass);
        }

        if (!rbB.isKinematic)
        {
            rbB.velocity -= (impulse / rbB.mass);
        }

        // Position correction to prevent sinking
        if (overlap > 0)
        {
            Vector3 correction = normal * (overlap + collisionMargin);
            if (!rbA.isKinematic) a.transform.position += correction * 0.5f;
            if (!rbB.isKinematic) b.transform.position -= correction * 0.5f;
        }

        // Send collision events
        a.SendMessage("OnCollisionEnter", new CollisionInfo(b, normal, overlap), SendMessageOptions.DontRequireReceiver);
        b.SendMessage("OnCollisionEnter", new CollisionInfo(a, -normal, overlap), SendMessageOptions.DontRequireReceiver);
    }
}

// Helper class for collision information
public class CollisionInfo
{
    public SphereCollider collider;
    public Vector3 normal;
    public float penetrationDepth;

    public CollisionInfo(SphereCollider collider, Vector3 normal, float penetrationDepth)
    {
        this.collider = collider;
        this.normal = normal;
        this.penetrationDepth = penetrationDepth;
    }
}
