    PrimaryComponentTick.TickGroup = TG_PostPhysics;

    BuoyancyStrength = 1.0f;
    WaterDensity = 1000.0f; // kg/m³ for water
    WaterPlaneNormal = FVector(0, 0, 1);
    WaterPlaneDistance = 0.0f;
    bDebugVisualization = false;
}

void UBuoyancyForceComponent::BeginPlay()
{
    Super::BeginPlay();
}

void UBuoyancyForceComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    if (AActor* Owner = GetOwner())
    {
        ApplyBuoyancyForce(Owner);
        if (bDebugVisualization)
        {
            DebugVisualization();
        }
    }
}

void UBuoyancyForceComponent::ApplyBuoyancyForce(AActor* OwnerActor)
{
    if (!OwnerActor) return;

    // Get all primitive components with physics
    TArray<UPrimitiveComponent*> PrimitiveComponents;
    OwnerActor->GetComponents(PrimitiveComponents);

    for (UPrimitiveComponent* PrimComp : PrimitiveComponents)
    {
        if (!PrimComp || !PrimComp->IsSimulatingPhysics()) continue;

        // Get the physics body instance
        FBodyInstance* BodyInst = PrimComp->GetBodyInstance();
        if (!BodyInst) continue;

        // Get the physics material
        UPhysicalMaterial* PhysMat = PrimComp->GetPhysicalMaterial();
        UCustomPhysicsMaterial* CustomMat = Cast<UCustomPhysicsMaterial>(PhysMat);
        if (!CustomMat) continue;

        // Calculate submerged volume (simplified)
        FVector ActorLocation = OwnerActor->GetActorLocation();
        FVector PrimitiveLocation = PrimComp->GetComponentLocation();
        FVector LocalWaterPlanePos = WaterPlaneNormal * WaterPlaneDistance;

        // Calculate distance from water plane
        float DistanceToWater = FVector::DotProduct(ActorLocation - LocalWaterPlanePos, WaterPlaneNormal);

        // Simple buoyancy calculation (Archimedes' principle)
        float SubmergedVolume = FMath::Clamp(DistanceToWater / 100.0f, 0.0f, 1.0f); // Simplified
        float BuoyantForce = SubmergedVolume * BodyInst->GetBodyMass() * BuoyancyStrength * CustomMat->BuoyancyFactor * 9.81f * WaterDensity;

        // Apply force at the center of mass
        FVector Force = -FVector::UpVector * BuoyantForce;
        BodyInst->AddForce(Force);
    }
}

