    // Draw water plane
    FVector PlanePoint = WaterPlaneNormal * WaterPlaneDistance;
    DrawDebugPlane(
        GetWorld(),
        PlanePoint,
        WaterPlaneNormal,
        1000.0f,
        FColor::Blue,
        false,
        -1.0f,
        0
    );
}

