Here's a minimal but functional C++ physics plugin for a commercial game engine. This example includes rigid body simulation with basic sphere-sphere collision detection and a clean C-style interface for engine integration:

```cpp
// physics_plugin.h - Core plugin interface
#pragma once

#ifdef _WIN32
#define PHYSICS_API __declspec(dllexport)
#else
#define PHYSICS_API
#endif

// Vector3 structure for physics calculations
struct Vector3 {
    float x, y, z;

    Vector3(float x = 0, float y = 0, float z = 0) : x(x), y(y), z(z) {}
    Vector3 operator+(const Vector3& other) const {
        return Vector3(x + other.x, y + other.y, z + other.z);
    }
    Vector3 operator-(const Vector3& other) const {
        return Vector3(x - other.x, y - other.y, z - other.z);
    }
    Vector3 operator*(float scalar) const {
        return Vector3(x * scalar, y * scalar, z * scalar);
    }
    float length() const {
        return sqrt(x*x + y*y + z*z);
    }
    Vector3 normalized() const {
        float len = length();
        return len > 0 ? Vector3(x/len, y/len, z/len) : Vector3(0, 0, 0);
    }
};

// Physics object handle
typedef unsigned int PhysicsObjectHandle;

// Physics plugin interface
extern "C" {
    // Initialize the physics world
    PHYSICS_API void Physics_Init(float gravity = -9.81f);

    // Create a rigid body
    PHYSICS_API PhysicsObjectHandle Physics_CreateRigidBody(
        const Vector3& position,
        const Vector3& velocity,
        float radius,
        float mass,
        bool isStatic = false
    );

    // Update physics simulation
    PHYSICS_API void Physics_Update(float deltaTime);

    // Get current transform of a physics object
    PHYSICS_API Vector3 Physics_GetPosition(PhysicsObjectHandle handle);
    PHYSICS_API Vector3 Physics_GetVelocity(PhysicsObjectHandle handle);

    // Apply force to a physics object
    PHYSICS_API void Physics_ApplyForce(PhysicsObjectHandle handle, const Vector3& force);

