```cpp
// physics_plugin.cpp - Implementation
#include "physics_plugin.h"
#include <vector>
#include <algorithm>

class RigidBody {
public:
    Vector3 position;
    Vector3 velocity;
    Vector3 forceAccum;
    float radius;
    float mass;
    bool isStatic;

    RigidBody(const Vector3& pos, const Vector3& vel, float r, float m, bool stat)
        : position(pos), velocity(vel), radius(r), mass(m), isStatic(stat) {}

    void integrate(float deltaTime, const Vector3& gravity) {
        if (isStatic) return;

        // Apply gravity
        forceAccum = forceAccum + gravity * mass;

        // Simple Euler integration
        Vector3 acceleration = forceAccum * (1.0f / mass);
        velocity = velocity + acceleration * deltaTime;
        position = position + velocity * deltaTime;

        // Reset forces
        forceAccum = Vector3(0, 0, 0);

        // Simple ground collision
        if (position.y < radius) {
            position.y = radius;
            velocity.y = 0;
        }
    }

    void applyForce(const Vector3& force) {
        if (!isStatic) {
            forceAccum = forceAccum + force;
        }
    }
};

class PhysicsWorld {
private:
    std::vector<RigidBody> bodies;
    Vector3 gravity;

public:
    PhysicsWorld(float g) : gravity(0, g, 0) {}

    PhysicsObjectHandle createRigidBody(const Vector3& pos, const Vector3& vel,
                                      float radius, float mass, bool isStatic) {
        bodies.emplace_back(pos, vel, radius, mass, isStatic);
        return static_cast<PhysicsObjectHandle>(bodies.size() - 1);
    }

    void update(float deltaTime) {
        // Update all bodies
        for (auto& body : bodies) {
            body.integrate(deltaTime, gravity);
        }

        // Simple collision detection (sphere-sphere)
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                RigidBody& a = bodies[i];
                RigidBody& b = bodies[j];

                Vector3 delta = b.position - a.position;
                float distance = delta.length();
                float minDist = a.radius + b.radius;

                if (distance < minDist) {
                    // Simple collision response
                    Vector3 normal = delta * (1.0f / distance);
                    float restitution = 0.8f;

                    Vector3 relativeVel = b.velocity - a.velocity;
                    float velAlongNormal = relativeVel.x * normal.x +
                                          relativeVel.y * normal.y +
                                          relativeVel.z * normal.z;

                    if (velAlongNormal > 0) continue; // Objects moving apart

                    float impulse = -(1 + restitution) * velAlongNormal;
                    impulse /= (1.0f/a.mass + 1.0f/b.mass);

                    Vector3 impulseVec = normal * impulse;

                    if (!a.isStatic) {
                        a.velocity = a.velocity - impulseVec * (1.0f/a.mass);
                    }
                    if (!b.isStatic) {
                        b.velocity = b.velocity + impulseVec * (1.0f/b.mass);
                    }

                    // Position correction to prevent sinking
                    float correction = (minDist - distance) * 0.2f;
                    if (!a.isStatic) a.position = a.position - normal * correction * 0.5f;
                    if (!b.isStatic) b.position = b.position + normal * correction * 0.5f;
                }
            }
        }
    }

    Vector3 getPosition(PhysicsObjectHandle handle) const {
        return bodies[handle].position;
    }

    Vector3 getVelocity(PhysicsObjectHandle handle) const {
        return bodies[handle].velocity;
    }

    void applyForce(PhysicsObjectHandle handle, const Vector3& force) {
        bodies[handle].applyForce(force);
    }
};

// Global physics world instance
static PhysicsWorld* g_physicsWorld = nullptr;

extern "C" {
    PHYSICS_API void Physics_Init(float gravity) {
        if (!g_physicsWorld) {
            g_physicsWorld = new PhysicsWorld(gravity);
        }
    }

    PHYSICS_API PhysicsObjectHandle Physics_CreateRigidBody(
        const Vector3& position,
        const Vector3& velocity,
        float radius,
        float mass,
        bool isStatic
    ) {
        if (!g_physicsWorld) Physics_Init();
        return g_physicsWorld->createRigidBody(position, velocity, radius, mass, isStatic);
    }

    PHYSICS_API void Physics_Update(float deltaTime) {
        if (g_physicsWorld) {
            g_physicsWorld->update(deltaTime);
        }
    }

    PHYSICS_API Vector3 Physics_GetPosition(PhysicsObjectHandle handle) {
        return g_physicsWorld ? g_physicsWorld->getPosition(handle) : Vector3(0, 0, 0);
    }

    PHYSICS_API Vector3 Physics_GetVelocity(PhysicsObjectHandle handle) {
        return g_physicsWorld ? g_physicsWorld->getVelocity(handle) : Vector3(0, 0, 0);
    }

    PHYSICS_API void Physics_ApplyForce(PhysicsObjectHandle handle, const Vector3& force) {
        if (g_physicsWorld) {
            g_physicsWorld->applyForce(handle, force);
        }
    }

    PHYSICS_API void Physics_Shutdown() {
        delete g_physicsWorld;
        g_physicsWorld = nullptr;
    }
}
```

### Key Features:
1. **C-Style Interface**: Ensures compatibility with most game engines (Unreal, Unity, Godot, etc.)
2. **Basic Physics Simulation**:
   - Rigid body dynamics with mass and velocity
   - Simple Euler integration
   - Sphere-sphere collision detection and response
   - Gravity and ground collision
3. **Memory Management**: Proper cleanup with `Physics_Shutdown()`
4. **Performance Considerations**:
   - Uses simple data structures (vector) for bodies
   - Basic collision detection (O(n²) but sufficient for small numbers of objects)

### Integration Notes:
1. **Compilation**: Compile as a shared library (DLL/.so)
2. **Engine Integration**:
   - Call `Physics_Init()` at startup
   - Create physics objects when game objects are spawned
   - Call `Physics_Update()` each frame
   - Use `Physics_GetPosition()` to update game object transforms
3. **Extensibility**:
   - Add more shape types (boxes, capsules)
   - Implement more accurate integration (Verlet, RK4)
   - Add spatial partitioning for better collision performance

