// PhysicsWorld.h - Manages all physics bodies and simulation
// =============================================================================
#pragma once

#include <vector>
#include <memory>
#include "Math/AABB.h"
#include "Physics/RigidBody.h"

class PhysicsWorld {
public:
    PhysicsWorld();
    ~PhysicsWorld();

    void Initialize();
    void Clear();

    void AddBody(RigidBody* body);
    void RemoveBody(RigidBody* body);
    void StepSimulation(float deltaTime);

    void DebugDraw(IRenderSystem* renderer) const;

    // Collision detection helpers
    void BroadPhaseCollision();
    void NarrowPhaseCollision();

private:
    std::vector<RigidBody*> m_bodies;
    std::vector<std::pair<RigidBody*, RigidBody*>> m_collisionPairs;
    bool m_gravityEnabled = true;
    Vector3 m_gravity = Vector3(0.0f, -9.81f, 0.0f);
    float m_sleepThreshold = 0.01f; // Linear velocity threshold for sleeping
};

// =============================================================================
// PhysicsWorld.cpp - Simulation and collision handling
// =============================================================================
#include "PhysicsWorld.h"
#include "Physics/CollisionDetection.h"
#include "Engine/IRenderSystem.h"

PhysicsWorld::PhysicsWorld() = default;
PhysicsWorld::~PhysicsWorld() { Clear(); }

void PhysicsWorld::Initialize() {
    // Could load configuration from engine settings here
}

void PhysicsWorld::Clear() {
    for (auto body : m_bodies) {
        delete body;
    }
    m_bodies.clear();
    m_collisionPairs.clear();
}

void PhysicsWorld::AddBody(RigidBody* body) {
    if (!body) return;
    m_bodies.push_back(body);
}

void PhysicsWorld::RemoveBody(RigidBody* body) {
    auto it = std::find(m_bodies.begin(), m_bodies.end(), body);
    if (it != m_bodies.end()) {
        m_bodies.erase(it);
    }
}

void PhysicsWorld::StepSimulation(float deltaTime) {
    if (deltaTime <= 0.0f) return;

    // 1. Apply forces (gravity, etc.)
    for (auto body : m_bodies) {
        if (body->IsDynamic() && m_gravityEnabled) {
            body->ApplyForce(m_gravity * body->GetMass());
        }
    }

    // 2. Broad phase collision detection
    BroadPhaseCollision();

    // 3. Narrow phase collision detection and resolution
    NarrowPhaseCollision();

    // 4. Integrate velocities and positions
    for (auto body : m_bodies) {
        body->Integrate(deltaTime);

        // Update the body's AABB
        body->UpdateAABB();
    }
}

void PhysicsWorld::BroadPhaseCollision() {
    m_collisionPairs.clear();

    // Simple broad phase: check all pairs (O(n²) - not optimal for many bodies)
    // In a production engine, you'd use spatial partitioning (grid, BVH, etc.)
    const size_t numBodies = m_bodies.size();
    for (size_t i = 0; i < numBodies; ++i) {
        for (size_t j = i + 1; j < numBodies; ++j) {
            RigidBody* bodyA = m_bodies[i];
            RigidBody* bodyB = m_bodies[j];

            // Skip pairs that can't collide (e.g., both static)
            if (!bodyA->CanCollideWith(bodyB)) continue;

            // Check AABB collision
            if (AABB::Intersect(bodyA->GetAABB(), bodyB->GetAABB())) {
                m_collisionPairs.emplace_back(bodyA, bodyB);
            }
        }
    }
}

void PhysicsWorld::NarrowPhaseCollision() {
    for (auto& pair : m_collisionPairs) {
        RigidBody* bodyA = pair.first;
        RigidBody* bodyB = pair.second;

        // Get collision info
        CollisionInfo info;
        if (CheckCollision(bodyA, bodyB, info)) {
            // Resolve collision
            ResolveCollision(bodyA, bodyB, info);

            // Notify engine about collision (could trigger game events)
            if (m_engine) {
                m_engine->OnCollision(bodyA, bodyB, info);
            }
        }
    }
}

void PhysicsWorld::DebugDraw(IRenderSystem* renderer) const {
    if (!renderer) return;

    // Draw all bodies' AABBs
    for (const auto body : m_bodies) {
        renderer->DrawAABB(body->GetAABB(), Color::Green);
    }

    // Draw collision pairs
    for (const auto& pair : m_collisionPairs) {
        renderer->DrawLine(
            pair.first->GetPosition(),
            pair.second->GetPosition(),
            Color::Red
        );
    }
}

