// RigidBody.h - Represents a physics body
// =============================================================================
#pragma once

#include "Math/Vector3.h"
#include "Math/Quaternion.h"
#include "Math/AABB.h"

enum class BodyType {
    Static,
    Kinematic,
    Dynamic
};

class RigidBody {
public:
    RigidBody(BodyType type = BodyType::Dynamic);
    ~RigidBody();

    // Physics properties
    void SetMass(float mass);
    float GetMass() const { return m_mass; }
    void SetInertiaTensor(const Matrix3x3& tensor);
    const Matrix3x3& GetInertiaTensor() const { return m_inertiaTensor; }

    // Position and orientation
    void SetPosition(const Vector3& position);
    Vector3 GetPosition() const { return m_position; }
    void SetOrientation(const Quaternion& orientation);
    Quaternion GetOrientation() const { return m_orientation; }

    // Velocity
    void SetLinearVelocity(const Vector3& velocity);
    Vector3 GetLinearVelocity() const { return m_linearVelocity; }
    void SetAngularVelocity(const Vector3& velocity);
    Vector3 GetAngularVelocity() const { return m_angularVelocity; }

    // Forces and impulses
    void ApplyForce(const Vector3& force);
    void ApplyForceAtPoint(const Vector3& force, const Vector3& point);
    void ApplyImpulse(const Vector3& impulse);
    void ApplyImpulseAtPoint(const Vector3& impulse, const Vector3& point);

    // Integration
    void Integrate(float deltaTime);

    // Collision
    void UpdateAABB();
    const AABB& GetAABB() const { return m_aabb; }
    bool IsDynamic() const { return m_type == BodyType::Dynamic; }
    bool CanCollideWith(const RigidBody* other) const;

    // Game engine integration
    void* GetUserData() const { return m_userData; }
    void SetUserData(void* data) { m_userData = data; }

private:
    BodyType m_type;
    float m_mass;
    float m_inverseMass;
    Matrix3x3 m_inertiaTensor;
    Matrix3x3 m_inverseInertiaTensor;

    Vector3 m_position;
    Quaternion m_orientation;
    Vector3 m_linearVelocity;
    Vector3 m_angularVelocity;

    Vector3 m_forceAccum;
    Vector3 m_torqueAccum;

    AABB m_aabb;

    void* m_userData = nullptr; // For engine-specific data

    // Helper methods
    void UpdateDerivedData();
};

// =============================================================================
// RigidBody.cpp - Physics body implementation
// =============================================================================
#include "RigidBody.h"
#include "Math/MathUtils.h"

RigidBody::RigidBody(BodyType type)
    : m_type(type), m_mass(type == BodyType::Static ? 0.0f : 1.0f),
      m_inverseMass(type == BodyType::Static ? 0.0f : 1.0f),
      m_inertiaTensor(Matrix3x3::Identity),
      m_inverseInertiaTensor(Matrix3x3::Identity),
      m_position(Vector3::Zero),
      m_orientation(Quaternion::Identity),
      m_linearVelocity(Vector3::Zero),
      m_angularVelocity(Vector3::Zero) {
    UpdateDerivedData();
}

RigidBody::~RigidBody() = default;

void RigidBody::SetMass(float mass) {
    if (mass <= 0.0f) {
        m_type = BodyType::Static;
        m_mass = 0.0f;
        m_inverseMass = 0.0f;
    } else {
        m_type = BodyType::Dynamic;
        m_mass = mass;
        m_inverseMass = 1.0f / mass;
    }
    UpdateDerivedData();
}

void RigidBody::SetInertiaTensor(const Matrix3x3& tensor) {
    m_inertiaTensor = tensor;
    if (m_mass > 0.0f) {
        m_inverseInertiaTensor = tensor.Inverse();
    } else {
        m_inverseInertiaTensor = Matrix3x3::Zero;
    }
}

void RigidBody::SetPosition(const Vector3& position) {
    m_position = position;
    UpdateAABB();
}

void RigidBody::SetOrientation(const Quaternion& orientation) {
    m_orientation = orientation;
    UpdateDerivedData();
    UpdateAABB();
}

void RigidBody::SetLinearVelocity(const Vector3& velocity) {
    m_linearVelocity = velocity;
}

void RigidBody::SetAngularVelocity(const Vector3& velocity) {
    m_angularVelocity = velocity;
}

void RigidBody::ApplyForce(const Vector3& force) {
    if (m_type != BodyType::Dynamic) return;
    m_forceAccum += force;
}

void RigidBody::ApplyForceAtPoint(const Vector3& force, const Vector3& point) {
    if (m_type != BodyType::Dynamic) return;

    // Convert point to local space
    Vector3 localPoint = m_orientation.Conjugate().Rotate(point - m_position);

    m_forceAccum += force;
    m_torqueAccum += localPoint.Cross(force);
}

void RigidBody::ApplyImpulse(const Vector3& impulse) {
    if (m_type != BodyType::Dynamic) return;
    m_linearVelocity += impulse * m_inverseMass;
}

void RigidBody::ApplyImpulseAtPoint(const Vector3& impulse, const Vector3& point) {
    if (m_type != BodyType::Dynamic) return;

    // Convert point to local space
    Vector3 localPoint = m_orientation.Conjugate().Rotate(point - m_position);

    m_linearVelocity += impulse * m_inverseMass;
    m_angularVelocity += m_inverseInertiaTensor * localPoint.Cross(impulse);
}

void RigidBody::Integrate(float deltaTime) {
    if (m_type != BodyType::Dynamic || deltaTime <= 0.0f) return;

    // Linear integration
    m_linearVelocity += m_forceAccum * m_inverseMass * deltaTime;
    m_position += m_linearVelocity * deltaTime;

    // Angular integration
    Vector3 angularAcceleration = m_inverseInertiaTensor * m_torqueAccum;
    m_angularVelocity += angularAcceleration * deltaTime;

    // Update orientation
    m_orientation += m_orientation * Quaternion(m_angularVelocity * deltaTime * 0.5f, 0.0f);
    m_orientation.Normalize();

    // Clear accumulators
    m_forceAccum = Vector3::Zero;
    m_torqueAccum = Vector3::Zero;

    // Update derived data
    UpdateDerivedData();
}

void RigidBody::UpdateAABB() {
    // In a real implementation, this would consider the body's shape
    // For simplicity, we'll use a fixed-size AABB centered at the body
    Vector3 halfExtents(1.0f, 1.0f, 1.0f); // Default size
    m_aabb = AABB(m_position - halfExtents, m_position + halfExtents);
}

bool RigidBody::CanCollideWith(const RigidBody* other) const {
    // Don't collide with self
    if (this == other) return false;

    // Static bodies don't collide with other static or kinematic bodies
    if (m_type == BodyType::Static && other->m_type != BodyType::Dynamic) return false;
    if (other->m_type == BodyType::Static && m_type != BodyType::Dynamic) return false;

    // Kinematic bodies only collide with dynamic bodies
    if ((m_type == BodyType::Kinematic || other->m_type == BodyType::Kinematic) &&
        m_type != BodyType::Dynamic && other->m_type != BodyType::Dynamic) {
        return false;
    }

    return true;
}

void RigidBody::UpdateDerivedData() {
    // Update inertia tensor based on orientation
    // In a real implementation, this would consider the body's shape
    if (m_mass > 0.0f) {
        m_inverseInertiaTensor = m_inertiaTensor * m_orientation.ToMatrix3x3();
        m_inverseInertiaTensor = m_inverseInertiaTensor.Inverse();
    }
}

// =============================================================================
// CollisionDetection.h - Collision detection utilities
// =============================================================================
#pragma once

#include "Math/AABB.h"
#include "Physics/RigidBody.h"

struct CollisionInfo {
    Vector3 normal;     // Collision normal (points from A to B)
    float penetration;  // Penetration depth
    Vector3 contactPointA;
    Vector3 contactPointB;
};

bool CheckCollision(RigidBody* bodyA, RigidBody* bodyB, CollisionInfo& outInfo);
bool CheckAABBCollision(const AABB& a, const AABB& b);
void ResolveCollision(RigidBody* bodyA, RigidBody* bodyB, const CollisionInfo& info);

// =============================================================================
// CollisionDetection.cpp - Collision detection implementation
// =============================================================================
#include "CollisionDetection.h"
#include "Math/MathUtils.h"

bool CheckAABBCollision(const AABB& a, const AABB& b) {
    return (a.min.x <= b.max.x && a.max.x >= b.min.x) &&
           (a.min.y <= b.max.y && a.max.y >= b.min.y) &&
           (a.min.z <= b.max.z && a.max.z >= b.min.z);
}

bool CheckCollision(RigidBody* bodyA, RigidBody* bodyB, CollisionInfo& outInfo) {
    // For simplicity, we're just checking AABB collision
    // A real implementation would check the actual shapes

    if (!CheckAABBCollision(bodyA->GetAABB(), bodyB->GetAABB())) {
        return false;
    }

    // Simple collision response - just push bodies apart along the normal
    Vector3 centerA = bodyA->GetAABB().GetCenter();
    Vector3 centerB = bodyB->GetAABB().GetCenter();
    outInfo.normal = (centerB - centerA).Normalized();
    outInfo.penetration = 0.5f * (bodyA->GetAABB().GetSize() + bodyB->GetAABB().GetSize()).Length() -
                          (centerB - centerA).Length();

    // Simple contact points (center of each AABB)
    outInfo.contactPointA = centerA;
    outInfo.contactPointB = centerB;

    return true;
}

void ResolveCollision(RigidBody* bodyA, RigidBody* bodyB, const CollisionInfo& info) {
    if (bodyA->GetMass() <= 0.0f && bodyB->GetMass() <= 0.0f) return;

    // Calculate relative velocity
    Vector3 relativeVelocity = bodyB->GetLinearVelocity() - bodyA->GetLinearVelocity();

    // Calculate velocity along the normal
    float velocityAlongNormal = relativeVelocity.Dot(info.normal);

    // Do not resolve if objects are moving away
    if (velocityAlongNormal > 0) return;

    // Calculate restitution (bounciness)
    float restitution = 0.5f; // Coefficient of restitution

    // Calculate impulse scalar
    float impulseScalar = -(1 + restitution) * velocityAlongNormal;
    impulseScalar /= (bodyA->GetInverseMass() + bodyB->GetInverseMass());

    // Apply impulse
    Vector3 impulse = impulseScalar * info.normal;

    if (bodyA->IsDynamic()) {
        bodyA->ApplyImpulse(-impulse);
    }
    if (bodyB->IsDynamic()) {
        bodyB->ApplyImpulse(impulse);
    }

    // Position correction to prevent sinking
    const float percent = 0.2f; // Usually 20% to 80%
    const float slop = 0.01f;   // Usually 0.01 to 0.1
    Vector3 correction = std::max(info.penetration - slop, 0.0f) / (bodyA->GetInverseMass() + bodyB->GetInverseMass()) * percent * info.normal;

    if (bodyA->IsDynamic()) {
        bodyA->SetPosition(bodyA->GetPosition() - correction * bodyA->GetInverseMass());
    }
    if (bodyB->IsDynamic()) {
        bodyB->SetPosition(bodyB->GetPosition() + correction * bodyB->GetInverseMass());
    }
}

