// Math Library (simplified) - Would normally be in separate files
// =============================================================================
namespace Math {

class Vector3 {
public:
    float x, y, z;

    Vector3(float x = 0, float y = 0, float z = 0) : x(x), y(y), z(z) {}

    Vector3 operator+(const Vector3& other) const {
        return Vector3(x + other.x, y + other.y, z + other.z);
    }

    Vector3 operator-(const Vector3& other) const {
        return Vector3(x - other.x, y - other.y, z - other.z);
    }

    Vector3 operator*(float scalar) const {
        return Vector3(x * scalar, y * scalar, z * scalar);
    }

    float Dot(const Vector3& other) const {
        return x * other.x + y * other.y + z * other.z;
    }

    Vector3 Cross(const Vector3& other) const {
        return Vector3(
            y * other.z - z * other.y,
            z * other.x - x * other.z,
            x * other.y - y * other.x
        );
    }

    float Length() const {
        return std::sqrt(x*x + y*y + z*z);
    }

    Vector3 Normalized() const {
        float len = Length();
        if (len > 0) return *this * (1.0f / len);
        return Vector3::Zero;
    }

    static const Vector3 Zero;
    static const Vector3 One;
};

const Vector3 Vector3::Zero(0.0f, 0.0f, 0.0f);
const Vector3 Vector3::One(1.0f, 1.0f, 1.0f);

class Quaternion {
public:
    float w, x, y, z;

    Quaternion(float w = 1, float x = 0, float y = 0, float z = 0) : w(w), x(x), y(y), z(z) {}

    Quaternion operator+(const Quaternion& other) const {
        return Quaternion(w + other.w, x + other.x, y + other.y, z + other.z);
    }

    Quaternion operator*(const Quaternion& other) const {
        return Quaternion(
            w * other.w - x * other.x - y * other.y - z * other.z,
            w * other.x + x * other.w + y * other.z - z * other.y,
            w * other.y - x * other.z + y * other.w + z * other.x,
            w * other.z + x * other.y - y * other.x + z * other.w
        );
    }

    Quaternion operator*(float scalar) const {
        return Quaternion(w * scalar, x * scalar, y * scalar, z * scalar);
    }

    Quaternion Conjugate() const {
        return Quaternion(w, -x, -y, -z);
    }

    Vector3 Rotate(const Vector3& v) const {
        Quaternion p(0, v.x, v.y, v.z);
        Quaternion rotated = (*this) * p * Conjugate();
        return Vector3(rotated.x, rotated.y, rotated.z);
    }

    Matrix3x3 ToMatrix3x3() const {
        float xx = x * x, yy = y * y, zz = z * z;
        float xy = x * y, xz = x * z, yz = y * z;
        float wx = w * x, wy = w * y, wz = w * z;

        return Matrix3x3(
            1 - 2 * (yy + zz),     2 * (xy - wz),     2 * (xz + wy),
                2 * (xy + wz), 1 - 2 * (xx + zz),     2 * (yz - wx),
                2 * (xz - wy),     2 * (yz + wx), 1 - 2 * (xx + yy)
        );
    }

    void Normalize() {
        float len = std::sqrt(w*w + x*x + y*y + z*z);
        if (len > 0) {
            float invLen = 1.0f / len;
            w *= invLen;
            x *= invLen;
            y *= invLen;
            z *= invLen;
        }
    }

    static const Quaternion Identity;
};

const Quaternion Quaternion::Identity(1, 0, 0, 0);

class Matrix3x3 {
public:
    float m[3][3];

    Matrix3x3() {
        *this = Zero;
    }

    Matrix3x3(float m00, float m01, float m02,
              float m10, float m11, float m12,
              float m20, float m21, float m22) {
        m[0][0] = m00; m[0][1] = m01; m[0][2] = m02;
        m[1][0] = m10; m[1][1] = m11; m[1][2] = m12;
        m[2][0] = m20; m[2][1] = m21; m[2][2] = m22;
    }

    Matrix3x3 operator*(const Matrix3x3& other) const {
        Matrix3x3 result;
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                result.m[i][j] = 0;
                for (int k = 0; k < 3; ++k) {
                    result.m[i][j] += m[i][k] * other.m[k][j];
                }
            }
        }
        return result;
    }

    Matrix3x3 Inverse() const {
        // Simplified inverse calculation for symmetric matrices
        float det = m[0][0] * (m[1][1] * m[2][2] - m[2][1] * m[1][2]) -
                    m[0][1] * (m[1][0] * m[2][2] - m[2][0] * m[1][2]) +
                    m[0][2] * (m[1][0] * m[2][1] - m[2][0] * m[1][1]);

        if (std::abs(det) < 1e-6f) return Zero;

        float invDet = 1.0f / det;

        return Matrix3x3(
            (m[1][1] * m[2][2] - m[2][1] * m[1][2]) * invDet,
            (m[0][2] * m[2][1] - m[0][1] * m[2][2]) * invDet,
            (m[0][1] * m[1][2] - m[0][2] * m[1][1]) * invDet,

            (m[1][2] * m[2][0] - m[1][0] * m[2][2]) * invDet,
            (m[0][0] * m[2][2] - m[0][2] * m[2][0]) * invDet,
            (m[1][0] * m[0][2] - m[0][0] * m[1][2]) * invDet,

            (m[1][0] * m[2][1] - m[2][0] * m[1][1]) * invDet,
            (m[2][0] * m[0][1] - m[0][0] * m[2][1]) * invDet,
            (m[0][0] * m[1][1] - m[1][0] * m[0][1]) * invDet
        );
    }

    static const Matrix3x3 Identity;
    static const Matrix3x3 Zero;
};

