public class CollisionManager : MonoBehaviour
{
    private void FixedUpdate()
    {
        CustomRigidbody[] rigidbodies = FindObjectsOfType<CustomRigidbody>();
        SphereCollider[] colliders = FindObjectsOfType<SphereCollider>();

        // Simple collision detection (O(n^2) for all pairs)
        for (int i = 0; i < colliders.Length; i++)
        {
            for (int j = i + 1; j < colliders.Length; j++)
            {
                if (colliders[i].CheckCollision(colliders[j]))
                {
                    HandleCollision(colliders[i], colliders[j]);
                }
            }
        }
    }

    private void HandleCollision(SphereCollider a, SphereCollider b)
    {
        CustomRigidbody rbA = a.GetComponent<CustomRigidbody>();
        CustomRigidbody rbB = b.GetComponent<CustomRigidbody>();

        if (rbA == null || rbB == null) return;

        // Simple collision response - just reverse velocities
        Vector3 normal = (a.transform.position - b.transform.position).normalized;
        Vector3 relativeVelocity = rbA.velocity - rbB.velocity;

        // Calculate impulse
        float impulse = Vector3.Dot(relativeVelocity, normal) / (1/rbA.mass + 1/rbB.mass);

        // Apply impulse
        rbA.velocity -= (impulse / rbA.mass) * normal;
        rbB.velocity += (impulse / rbB.mass) * normal;

        // Move objects apart to prevent sticking
        float overlap = (a.radius + b.radius) - Vector3.Distance(a.transform.position, b.transform.position);
        Vector3 separation = normal * overlap * 0.5f;
        a.transform.position += separation;
        b.transform.position -= separation;
    }
}
