// Simple 3D Vector
struct Vec3 {
    float x, y, z;
    Vec3(float x = 0, float y = 0, float z = 0) : x(x), y(y), z(z) {}
    Vec3 operator+(const Vec3& other) const { return Vec3(x + other.x, y + other.y, z + other.z); }
    Vec3 operator-(const Vec3& other) const { return Vec3(x - other.x, y - other.y, z - other.z); }
    Vec3 operator*(float scalar) const { return Vec3(x * scalar, y * scalar, z * scalar); }
    float Length() const { return std::sqrt(x*x + y*y + z*z); }
    void Normalize() { float len = Length(); if (len > 0) { x /= len; y /= len; z /= len; } }
};

// Rigid Body
class RigidBody {
public:
    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;
    float mass;
    float inverseMass;
    bool isStatic;

    RigidBody(Vec3 pos, float mass, bool isStatic = false)
        : position(pos), velocity(0, 0, 0), mass(mass), isStatic(isStatic), inverseMass(isStatic ? 0 : 1.0f / mass) {}

    void AddForce(const Vec3& force) {
        if (!isStatic) {
            forceAccum = forceAccum + force;
        }
    }

    void Integrate(float deltaTime) {
        if (isStatic || inverseMass <= 0.0f) return;

        // Apply gravity (simple example)
        AddForce(Vec3(0, -9.81f * mass, 0));

        // Update velocity
        Vec3 acceleration = forceAccum * inverseMass;
        velocity = velocity + acceleration * deltaTime;

        // Update position
        position = position + velocity * deltaTime;

        // Reset force accumulator
        forceAccum = Vec3(0, 0, 0);
    }
};

// Physics World
class PhysicsWorld {
private:
    std::vector<std::shared_ptr<RigidBody>> bodies;
    Vec3 gravity;

public:
    PhysicsWorld(Vec3 gravity = Vec3(0, -9.81f, 0)) : gravity(gravity) {}

    void AddBody(std::shared_ptr<RigidBody> body) {
        bodies.push_back(body);
    }

    void Step(float deltaTime) {
        // Apply gravity to all bodies
        for (auto& body : bodies) {
            if (!body->isStatic) {
                body->AddForce(gravity * body->mass);
            }
        }

        // Integrate all bodies
        for (auto& body : bodies) {
            body->Integrate(deltaTime);
        }

        // Simple collision detection (AABB with ground plane)
        for (auto& body : bodies) {
            if (body->position.y < 0) {
                body->position.y = 0;
                body->velocity.y *= -0.5f; // Bounce with some energy loss
            }
        }
    }

    const std::vector<std::shared_ptr<RigidBody>>& GetBodies() const {
        return bodies;
    }
