## 6. Custom Physics Component Implementation (`CustomPhysicsComponent.cpp`)

```cpp
#include "CustomPhysicsComponent.h"
#include "GameFramework/Actor.h"

UCustomPhysicsComponent::UCustomPhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
    PrimaryComponentTick.TickGroup = TG_PostPhysics;

    Velocity = FVector::ZeroVector;
    AngularVelocity = FVector::ZeroVector;
    Mass = 1.0f;
    LinearDamping = 0.1f;
    AngularDamping = 0.1f;
    GravityScale = 1.0f;
    AccumulatedForce = FVector::ZeroVector;
    AccumulatedTorque = FVector::ZeroVector;
}

void UCustomPhysicsComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    // Apply gravity
    const FVector Gravity = FVector(0.0f, 0.0f, -980.0f) * GravityScale;
    AccumulatedForce += Gravity * Mass;

    // Calculate acceleration from forces (F = ma)
    const FVector Acceleration = AccumulatedForce / Mass;

    // Update velocity (v = v0 + at)
    Velocity += Acceleration * DeltaTime;

    // Apply linear damping
    Velocity *= (1.0f - LinearDamping * DeltaTime);

    // Update position (x = x0 + vt)
    if (AActor* Owner = GetOwner())
    {
        const FVector NewLocation = Owner->GetActorLocation() + Velocity * DeltaTime;
        Owner->SetActorLocation(NewLocation, true);
    }

    // Calculate angular acceleration from torques (τ = Iα)
    // For simplicity, we're using a point mass approximation where I = m
    const FVector AngularAcceleration = AccumulatedTorque / Mass;

    // Update angular velocity (ω = ω0 + αt)
    AngularVelocity += AngularAcceleration * DeltaTime;

    // Apply angular damping
    AngularVelocity *= (1.0f - AngularDamping * DeltaTime);

    // Update rotation
    if (AActor* Owner = GetOwner())
    {
        FRotator NewRotation = Owner->GetActorRotation();
        NewRotation.Pitch += AngularVelocity.X * DeltaTime;
        NewRotation.Yaw += AngularVelocity.Y * DeltaTime;
        NewRotation.Roll += AngularVelocity.Z * DeltaTime;
        Owner->SetActorRotation(NewRotation);
    }

    // Reset accumulated forces and torques
    AccumulatedForce = FVector::ZeroVector;
    AccumulatedTorque = FVector::ZeroVector;
}

void UCustomPhysicsComponent::ApplyForce(FVector Force)
{
    AccumulatedForce += Force;
}

void UCustomPhysicsComponent::ApplyTorque(FVector Torque)
{
    AccumulatedTorque += Torque;
}

void UCustomPhysicsComponent::SetVelocity(FVector NewVelocity)
{
    Velocity = NewVelocity;
}

FVector UCustomPhysicsComponent::GetVelocity() const
{
    return Velocity;
}
