#include "CustomForceFieldComponent.h"
#include "GameFramework/Actor.h"
#include "Components/PrimitiveComponent.h"
#include "PhysicsEngine/BodyInstance.h"

UCustomForceFieldComponent::UCustomForceFieldComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
    ForceStrength = 1000.0f;
    Radius = 500.0f;
    bApplyForceToOverlappingActors = true;
}

void UCustomForceFieldComponent::BeginPlay()
{
    Super::BeginPlay();
}

void UCustomForceFieldComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    if (!bApplyForceToOverlappingActors)
    {
        return;
    }

    TArray<AActor*> OverlappingActors;
    GetOwner()->GetOverlappingActors(OverlappingActors);

    for (AActor* Actor : OverlappingActors)
    {
        UPrimitiveComponent* PrimitiveComponent = Actor->FindComponentByClass<UPrimitiveComponent>();
        if (PrimitiveComponent)
        {
            FVector Direction = GetOwner()->GetActorLocation() - Actor->GetActorLocation();
            float Distance = Direction.Size();
            if (Distance > 0.0f && Distance <= Radius)
            {
                Direction.Normalize();
                FVector Force = Direction * ForceStrength * (1.0f - (Distance / Radius));
                PrimitiveComponent->AddForce(Force, NAME_None, true);
            }
        }
    }
}

void UCustomForceFieldComponent::ApplyForceToActor(AActor* ActorToAffect)
{
    if (ActorToAffect)
    {
        UPrimitiveComponent* PrimitiveComponent = ActorToAffect->FindComponentByClass<UPrimitiveComponent>();
        if (PrimitiveComponent)
        {
            FVector Direction = GetOwner()->GetActorLocation() - ActorToAffect->GetActorLocation();
            float Distance = Direction.Size();
            if (Distance > 0.0f && Distance <= Radius)
            {
                Direction.Normalize();
                FVector Force = Direction * ForceStrength * (1.0f - (Distance / Radius));
                PrimitiveComponent->AddForce(Force, NAME_None, true);
            }
        }
    }
