# Custom Physics Plugin for Unity (C#)

Below is a minimal but functional initial implementation of a custom physics plugin for Unity. This plugin provides a basic rigid body physics system with gravity, collision detection (AABB), and simple collision response.

---

## **Plugin Code (Single C# File)**
Save this as `CustomPhysicsPlugin.cs` in a **C# Class Library** project (targeting .NET Standard 2.1 or .NET Framework 4.x for Unity compatibility). Compile it to a `.dll` and place it in your Unity project's `Assets/Plugins` folder.

```csharp
using UnityEngine;
using System.Collections.Generic;

namespace CustomPhysics
{
    /// <summary>
    /// Simple Axis-Aligned Bounding Box (AABB) collider for collision detection.
    /// </summary>
    public class Collider
    {
        public Vector3 Center { get; set; }
        public Vector3 Size { get; set; }

        public bool Intersects(Collider other)
        {
            return (Mathf.Abs(Center.x - other.Center.x) <= (Size.x + other.Size.x) / 2) &&
                   (Mathf.Abs(Center.y - other.Center.y) <= (Size.y + other.Size.y) / 2) &&
                   (Mathf.Abs(Center.z - other.Center.z) <= (Size.z + other.Size.z) / 2);
        }
    }

    /// <summary>
    /// Custom rigid body for physics simulation.
    /// </summary>
    public class CustomRigidbody
    {
        public Vector3 Position { get; set; }
        public Vector3 Velocity { get; set; }
        public Vector3 Acceleration { get; set; }
        public float Mass { get; set; } = 1.0f;
        public bool IsKinematic { get; set; } = false;
        public Collider Collider { get; set; }

        public void AddForce(Vector3 force)
        {
            Acceleration += force / Mass;
        }
    }

    /// <summary>
    /// Core physics simulation manager.
    /// </summary>
    public class PhysicsManager
    {
        private List<CustomRigidbody> rigidbodies = new List<CustomRigidbody>();
        private List<Collider> colliders = new List<Collider>();
        public Vector3 Gravity { get; set; } = new Vector3(0, -9.81f, 0);

        public void AddRigidbody(CustomRigidbody rb)
        {
            rigidbodies.Add(rb);
            if (rb.Collider != null)
            {
                colliders.Add(rb.Collider);
            }
        }

        public void Update(float deltaTime)
        {
            // Apply forces (e.g., gravity)
            foreach (var rb in rigidbodies)
            {
                if (!rb.IsKinematic)
                {
                    rb.Acceleration += Gravity;
                }
            }

            // Update positions (Euler integration)
            foreach (var rb in rigidbodies)
            {
                if (!rb.IsKinematic)
                {
                    rb.Velocity += rb.Acceleration * deltaTime;
                    rb.Position += rb.Velocity * deltaTime;
                    rb.Acceleration = Vector3.zero; // Reset for next frame
                }
            }

            // Collision detection and response (simplified)
            for (int i = 0; i < colliders.Count; i++)
            {
                for (int j = i + 1; j < colliders.Count; j++)
                {
                    if (colliders[i].Intersects(colliders[j]))
                    {
                        HandleCollision(rigidbodies[i], rigidbodies[j]);
                    }
                }
            }
        }

        private void HandleCollision(CustomRigidbody rb1, CustomRigidbody rb2)
        {
            // Simple collision response: reverse velocities along collision normal
            Vector3 normal = (rb1.Position - rb2.Position).normalized;
            float relativeVelocity = Vector3.Dot(rb1.Velocity - rb2.Velocity, normal);
            if (relativeVelocity > 0)
            {
                Vector3 impulse = normal * relativeVelocity;
                rb1.Velocity -= impulse;
                rb2.Velocity += impulse;
            }
        }
    }
}

/// <summary>
