Then, the PhysicsManager that handles the simulation:

```csharp
public class PhysicsManager
{
    private List<CustomRigidbody> rigidbodies = new List<CustomRigidbody>();
    private List<Collider> colliders = new List<Collider>();
    public Vector3 Gravity { get; set; } = new Vector3(0, -9.81f, 0);

    public void AddRigidbody(CustomRigidbody rb)
    {
        rigidbodies.Add(rb);
        if (rb.Collider != null)
        {
            colliders.Add(rb.Collider);
        }
    }

    public void Update(float deltaTime)
    {
        // Apply forces (gravity)
        foreach (var rb in rigidbodies)
        {
            if (!rb.IsKinematic)
            {
                rb.Acceleration += Gravity;
            }
        }

        // Update positions (Euler integration)
        foreach (var rb in rigidbodies)
        {
            if (!rb.IsKinematic)
            {
                rb.Velocity += rb.Acceleration * deltaTime;
                rb.Position += rb.Velocity * deltaTime;
                rb.Acceleration = Vector3.zero; // Reset acceleration for next frame
            }
        }

        // Collision detection and response (simplified)
        for (int i = 0; i < colliders.Count; i++)
        {
            for (int j = i + 1; j < colliders.Count; j++)
            {
                if (colliders[i].Intersects(colliders[j]))
                {
                    HandleCollision(rigidbodies[i], rigidbodies[j]);
                }
            }
        }
    }

    private void HandleCollision(CustomRigidbody rb1, CustomRigidbody rb2)
    {
        // Simple collision response: reverse velocities along collision normal
        // This is a very basic approach; real physics would use impulse resolution
        Vector3 normal = (rb1.Position - rb2.Position).normalized;
        float relativeVelocity = Vector3.Dot(rb1.Velocity - rb2.Velocity, normal);
        if (relativeVelocity > 0)
        {
            Vector3 impulse = normal * relativeVelocity;
            rb1.Velocity -= impulse;
            rb2.Velocity += impulse;
        }
    }
}
```

