### **2. Physics Manager (`CustomPhysicsManager.cs`)**
This script handles the physics simulation loop and collision detection between objects.

```csharp
using UnityEngine;
using System.Collections.Generic;

public class CustomPhysicsManager : MonoBehaviour
{
    public static CustomPhysicsManager Instance { get; private set; }
    private List<CustomPhysicsObject> physicsObjects = new List<CustomPhysicsObject>();

    void Awake()
    {
        if (Instance == null)
        {
            Instance = this;
        }
        else
        {
            Destroy(gameObject);
        }
    }

    public void RegisterObject(CustomPhysicsObject obj)
    {
        if (!physicsObjects.Contains(obj))
        {
            physicsObjects.Add(obj);
        }
    }

    public void UnregisterObject(CustomPhysicsObject obj)
    {
        if (physicsObjects.Contains(obj))
        {
            physicsObjects.Remove(obj);
        }
    }

    // Simple collision detection (sphere-to-sphere)
    void Update()
    {
        for (int i = 0; i < physicsObjects.Count; i++)
        {
            for (int j = i + 1; j < physicsObjects.Count; j++)
            {
                CheckCollision(physicsObjects[i], physicsObjects[j]);
            }
        }
    }

    void CheckCollision(CustomPhysicsObject obj1, CustomPhysicsObject obj2)
    {
        float distance = Vector3.Distance(obj1.transform.position, obj2.transform.position);
        float combinedRadius = 1.0f; // Assume radius of 1 for simplicity

        if (distance < combinedRadius * 2)
        {
            // Simple collision response (elastic collision)
            Vector3 direction = (obj2.transform.position - obj1.transform.position).normalized;
            float relativeVelocity = Vector3.Dot(obj1.velocity - obj2.velocity, direction);

            if (relativeVelocity < 0)
            {
                // Calculate impulse
                float impulse = -(1 + 1) * relativeVelocity / (1 / obj1.mass + 1 / obj2.mass);
                Vector3 impulseForce = direction * impulse;

                // Apply impulse
                obj1.AddForce(impulseForce / 2);
                obj2.AddForce(-impulseForce / 2);
            }
        }
    }
}
```

