using System.Collections.Generic;
using UnityEngine;

public class PhysicsWorld : MonoBehaviour
{
    public List<PhysicsBody> bodies = new List<PhysicsBody>();
    public Vector3 gravity = new Vector3(0, -9.81f, 0);

    void FixedUpdate()
    {
        // Apply forces (e.g., gravity)
        foreach (var body in bodies)
        {
            body.AddForce(body.mass * gravity);
        }

        // Update positions based on velocity
        foreach (var body in bodies)
        {
            // Update velocity: v = v0 + a * dt
            body.velocity += body.acceleration * Time.fixedDeltaTime;

            // Update position: x = x0 + v * dt
            body.transform.position += body.velocity * Time.fixedDeltaTime;

            // Clear forces for next frame
            body.ClearForces();
        }

        // Simple collision detection (AABB)
        for (int i = 0; i < bodies.Count; i++)
        {
            for (int j = i + 1; j < bodies.Count; j++)
            {
                if (CheckCollision(bodies[i], bodies[j]))
                {
                    HandleCollision(bodies[i], bodies[j]);
                }
            }
        }
    }

    bool CheckCollision(PhysicsBody a, PhysicsBody b)
    {
        // Simple AABB collision detection
        Collider aCollider = a.GetComponent<Collider>();
        Collider bCollider = b.GetComponent<Collider>();

        if (aCollider == null || bCollider == null)
            return false;

        return aCollider.bounds.Intersects(bCollider.bounds);
    }

    void HandleCollision(PhysicsBody a, PhysicsBody b)
    {
        // Simple collision response: reverse velocities
        Vector3 temp = a.velocity;
        a.velocity = b.velocity;
        b.velocity = temp;

        // Optional: apply impulse based on mass
        // This is a very simplified collision response
    }

    public void RegisterBody(PhysicsBody body)
    {
        if (!bodies.Contains(body))
        {
            bodies.Add(body);
        }
    }

    public void UnregisterBody(PhysicsBody body)
    {
        if (bodies.Contains(body))
        {
            bodies.Remove(body);
        }
    }
}
