Here's a complete C++ implementation of a real-time rigid body physics simulation using Bullet Physics and OpenGL/GLUT for visualization. This example includes frame-rate control and demonstrates basic rigid body dynamics:

```cpp
#include <btBulletDynamicsCommon.h>
#include <GL/glut.h>
#include <iostream>

// Physics world variables
btDefaultCollisionConfiguration* collisionConfiguration = nullptr;
btCollisionDispatcher* dispatcher = nullptr;
btBroadphaseInterface* overlappingPairCache = nullptr;
btSequentialImpulseConstraintSolver* solver = nullptr;
btDiscreteDynamicsWorld* dynamicsWorld = nullptr;

// Simulation parameters
const float FIXED_TIMESTEP = 1.0f / 60.0f; // 60Hz simulation
const int MAX_SUBSTEPS = 3;
float lastTime = 0;
int frameCount = 0;
float fps = 0;

// Function prototypes
void initPhysics();
void stepSimulation(float deltaTime);
void renderScene();
void renderText(float x, float y, const char* text);
void keyboardCallback(unsigned char key, int x, int y);
void reshapeCallback(int width, int height);
void mouseCallback(int button, int state, int x, int y);
void motionCallback(int x, int y);

int main(int argc, char** argv) {
    // Initialize GLUT
    glutInit(&argc, argv);
    glutInitDisplayMode(GLUT_DOUBLE | GLUT_RGB | GLUT_DEPTH);
    glutInitWindowSize(800, 600);
    glutCreateWindow("Real-Time Rigid Body Physics Simulation");

    // Initialize Bullet physics
    initPhysics();

    // Set up GLUT callbacks
    glutDisplayFunc(renderScene);
    glutKeyboardFunc(keyboardCallback);
    glutReshapeFunc(reshapeCallback);
    glutMouseFunc(mouseCallback);
    glutMotionFunc(motionCallback);
    glutIdleFunc([]() {
        // Calculate delta time
        float currentTime = glutGet(GLUT_ELAPSED_TIME) / 1000.0f;
        float deltaTime = currentTime - lastTime;
        lastTime = currentTime;

        // Calculate FPS
        frameCount++;
        if (currentTime - lastTime > 1.0f) {
            fps = frameCount / (currentTime - lastTime);
            frameCount = 0;
            lastTime = currentTime;
        }

        // Step simulation with fixed time step
        stepSimulation(deltaTime);

        // Redraw
        glutPostRedisplay();
    });

    std::cout << "Real-Time Rigid Body Physics Simulation\n";
    std::cout << "Controls:\n";
    std::cout << "  ESC - Exit\n";
    std::cout << "  Left Click + Drag - Rotate view\n";
    std::cout << "  Right Click - Add a box at mouse position\n";
    std::cout << "  SPACE - Add 10 random boxes\n";
    std::cout << "----------------------------------------\n";

    glutMainLoop();

    // Cleanup
    if (dynamicsWorld) {
        for (int i = dynamicsWorld->getNumCollisionObjects() - 1; i >= 0; i--) {
            btCollisionObject* obj = dynamicsWorld->getCollisionObjectArray()[i];
            btRigidBody* body = btRigidBody::upcast(obj);
            if (body && body->getMotionState()) {
                delete body->getMotionState();
            }
            dynamicsWorld->removeCollisionObject(obj);
            delete obj;
        }
    }

    delete dynamicsWorld;
    delete solver;
    delete overlappingPairCache;
    delete dispatcher;
    delete collisionConfiguration;

    return 0;
}

void initPhysics() {
    // Build the collision configuration
    collisionConfiguration = new btDefaultCollisionConfiguration();
    dispatcher = new btCollisionDispatcher(collisionConfiguration);
    overlappingPairCache = new btDbvtBroadphase();
    solver = new btSequentialImpulseConstraintSolver();
    dynamicsWorld = new btDiscreteDynamicsWorld(dispatcher, overlappingPairCache, solver, collisionConfiguration);

    if (!dynamicsWorld) {
        std::cerr << "Error: Failed to create dynamics world!" << std::endl;
        exit(1);
    }

    // Set gravity
    dynamicsWorld->setGravity(btVector3(0, -9.81f, 0));

    // Create ground plane
    btStaticPlaneShape* groundShape = new btStaticPlaneShape(btVector3(0, 1, 0), 0);
    if (!groundShape) {
        std::cerr << "Error: Failed to create ground shape!" << std::endl;
        exit(1);
    }

    btDefaultMotionState* groundMotionState = new btDefaultMotionState(
        btTransform(btQuaternion(0, 0, 0, 1), btVector3(0, -1, 0))
    );
    if (!groundMotionState) {
        std::cerr << "Error: Failed to create ground motion state!" << std::endl;
        exit(1);
    }

    btRigidBody::btRigidBodyConstructionInfo groundRigidBodyCI(
        0, groundMotionState, groundShape, btVector3(0, 0, 0)
    );
    btRigidBody* groundRigidBody = new btRigidBody(groundRigidBodyCI);
    if (!groundRigidBody) {
        std::cerr << "Error: Failed to create ground rigid body!" << std::endl;
        exit(1);
    }

    dynamicsWorld->addRigidBody(groundRigidBody);

    // Create some initial dynamic bodies (boxes)
    btBoxShape* boxShape = new btBoxShape(btVector3(1, 1, 1));
    if (!boxShape) {
        std::cerr << "Error: Failed to create box shape!" << std::endl;
        exit(1);
    }

    for (int i = 0; i < 5; i++) {
        btTransform startTransform;
        startTransform.setIdentity();
        startTransform.setOrigin(btVector3(
            (rand() % 10) - 5,
            10 + i * 3,
            (rand() % 10) - 5
        ));

        btDefaultMotionState* motionState = new btDefaultMotionState(startTransform);
        if (!motionState) {
            std::cerr << "Error: Failed to create motion state for box " << i << "!" << std::endl;
            continue;
        }

        btScalar mass = 1.0f;
        btVector3 localInertia(0, 0, 0);
        boxShape->calculateLocalInertia(mass, localInertia);

        btRigidBody::btRigidBodyConstructionInfo rbInfo(mass, motionState, boxShape, localInertia);
        btRigidBody* body = new btRigidBody(rbInfo);
        if (!body) {
            std::cerr << "Error: Failed to create rigid body for box " << i << "!" << std::endl;
            delete motionState;
            continue;
        }

        dynamicsWorld->addRigidBody(body);
    }
}

void stepSimulation(float deltaTime) {
    // Step simulation with fixed time step
    if (deltaTime > FIXED_TIMESTEP * MAX_SUBSTEPS) {
        deltaTime = FIXED_TIMESTEP * MAX_SUBSTEPS;
    }

    int numSubSteps = (int)(deltaTime / FIXED_TIMESTEP);
    if (numSubSteps < 0) numSubSteps = 0;
    dynamicsWorld->stepSimulation(deltaTime, numSubSteps, FIXED_TIMESTEP);
}

void renderScene() {
    // Clear buffers
    glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);

    // Set up camera
    glMatrixMode(GL_PROJECTION);
    glLoadIdentity();
    gluPerspective(60.0, 800.0 / 600.0, 0.1, 100.0);
    glMatrixMode(GL_MODELVIEW);
    glLoadIdentity();

    // Camera controls
    glTranslatef(0, -5, 15);
    glRotatef(30, 1, 0, 0);

    // Draw ground plane
    glBegin(GL_QUADS);
    glColor3f(0.3f, 0.3f, 0.3f);
    glVertex3f(-20, -1, -20);
    glVertex3f(-20, -1, 20);
    glVertex3f(20, -1, 20);
    glVertex3f(20, -1, -20);
    glEnd();

    // Draw rigid bodies
    glColor3f(0.8f, 0.2f, 0.2f);
    for (int i = dynamicsWorld->getNumCollisionObjects() - 1; i >= 0; i--) {
        btCollisionObject* obj = dynamicsWorld->getCollisionObjectArray()[i];
        btRigidBody* body = btRigidBody::upcast(obj);
        if (body && body->getMotionState()) {
            btTransform trans;
            body->getMotionState()->getWorldTransform(trans);

            float mat[16];
            trans.getOpenGLMatrix(mat);

            glPushMatrix();
            glMultMatrixf(mat);
            glutSolidCube(2.0f); // Draw a cube with side length 2
            glPopMatrix();
        }
    }

    // Draw axes
    glBegin(GL_LINES);
    // X axis (red)
    glColor3f(1.0f, 0.0f, 0.0f);
    glVertex3f(0, 0, 0);
    glVertex3f(5, 0, 0);
    // Y axis (green)
    glColor3f(0.0f, 1.0f, 0.0f);
    glVertex3f(0, 0, 0);
    glVertex3f(0, 5, 0);
    // Z axis (blue)
    glColor3f(0.0f, 0.0f, 1.0f);
    glVertex3f(0, 0, 0);
    glVertex3f(0, 0, 5);
    glEnd();

    // Display FPS
    renderText(10, 10, ("FPS: " + std::to_string((int)fps)).c_str());

    glutSwapBuffers();
}

void renderText(float x, float y, const char* text) {
    glMatrixMode(GL_PROJECTION);
    glPushMatrix();
    glLoadIdentity();
    glOrtho(0, 800, 0, 600, -1, 1);
    glMatrixMode(GL_MODELVIEW);
    glPushMatrix();
    glLoadIdentity();

    glRasterPos2f(x, y);
    for (const char* c = text; *c != '\0'; c++) {
        glutBitmapCharacter(GLUT_BITMAP_HELVETICA_12, *c);
    }

    glPopMatrix();
    glMatrixMode(GL_PROJECTION);
    glPopMatrix();
    glMatrixMode(GL_MODELVIEW);
}

void keyboardCallback(unsigned char key, int x, int y) {
    switch (key) {
        case 27: // ESC key
            exit(0);
            break;
        case ' ':
            // Add 10 random boxes
            for (int i = 0; i < 10; i++) {
                btBoxShape* boxShape = new btBoxShape(btVector3(1, 1, 1));
                btTransform startTransform;
                startTransform.setIdentity();
                startTransform.setOrigin(btVector3(
                    (rand() % 10) - 5,
                    15 + i * 2,
                    (rand() % 10) - 5
                ));

                btDefaultMotionState* motionState = new btDefaultMotionState(startTransform);
                btScalar mass = 1.0f;
                btVector3 localInertia(0, 0, 0);
                boxShape->calculateLocalInertia(mass, localInertia);

                btRigidBody::btRigidBodyConstructionInfo rbInfo(mass, motionState, boxShape, localInertia);
                btRigidBody* body = new btRigidBody(rbInfo);
                dynamicsWorld->addRigidBody(body);
            }
            break;
    }
}

void reshapeCallback(int width, int height) {
    glViewport(0, 0, width, height);
    glMatrixMode(GL_PROJECTION);
    glLoadIdentity();
    gluPerspective(60.0, (float)width / (float)height, 0.1, 100.0);
    glMatrixMode(GL_MODELVIEW);
}

void mouseCallback(int button, int state, int x, int y) {
    // Simple camera rotation control
    static int lastX = 0, lastY = 0;
    static bool rotating = false;

    if (button == GLUT_LEFT_BUTTON) {
        if (state == GLUT_DOWN) {
            rotating = true;
            lastX = x;
            lastY = y;
        } else if (state == GLUT_UP) {
            rotating = false;
        }
    }
}

void motionCallback(int x, int y) {
    static int lastX = 0, lastY = 0;
    static bool rotating = false;

    if (rotating) {
        // Simple camera rotation
        glRotatef((y - lastY) * 0.5f, 1, 0, 0);
        glRotatef((x - lastX) * 0.5f, 0, 1, 0);
        lastX = x;
        lastY = y;
    }
}
