Here's a complete real-time rigid body physics simulation in C++ using SFML for visualization. This implements a simplified physics engine with frame-rate control, gravity, and collision response:

```cpp
#include <SFML/Graphics.hpp>
#include <vector>
#include <cmath>
#include <iostream>

// Physics constants
const float GRAVITY = 9.8f;
const float RESTITUTION = 0.8f; // Bounciness
const float TIMESTEP = 1.0f / 60.0f; // Fixed timestep (60 FPS)
const float MAX_FRAME_TIME = 0.25f; // Prevent spiral of death

// Physics vector class
struct Vec2 {
    float x, y;

    Vec2(float x = 0, float y = 0) : x(x), y(y) {}

    Vec2 operator+(const Vec2& other) const { return Vec2(x + other.x, y + other.y); }
    Vec2 operator-(const Vec2& other) const { return Vec2(x - other.x, y - other.y); }
    Vec2 operator*(float scalar) const { return Vec2(x * scalar, y * scalar); }
    Vec2 operator/(float scalar) const { return Vec2(x / scalar, y / scalar); }

    float length() const { return std::sqrt(x*x + y*y); }
    Vec2 normalized() const { return *this / length(); }
    float dot(const Vec2& other) const { return x * other.x + y * other.y; }
};

// Rigid body class
class RigidBody {
public:
    Vec2 position;
    Vec2 velocity;
    Vec2 forceAccum;
    float mass;
    float radius;
    sf::Color color;

    RigidBody(Vec2 pos, float mass, float radius, sf::Color color = sf::Color::White)
        : position(pos), mass(mass), radius(radius), color(color) {
        velocity = Vec2(0, 0);
        forceAccum = Vec2(0, 0);
    }

    void addForce(Vec2 force) {
        forceAccum = forceAccum + force;
    }

    void update(float dt) {
        // Apply gravity
        addForce(Vec2(0, mass * GRAVITY));

        // Update velocity (F = ma => a = F/m)
        Vec2 acceleration = forceAccum * (1.0f / mass);
        velocity = velocity + acceleration * dt;

        // Update position
        position = position + velocity * dt;

        // Reset forces
        forceAccum = Vec2(0, 0);
    }

    void resolveCollision(const RigidBody& other) {
        // Simple circle-circle collision response
        Vec2 delta = position - other.position;
        float distance = delta.length();

        if (distance < radius + other.radius) {
            // Collision normal
            Vec2 normal = delta.normalized();

            // Relative velocity
            Vec2 relativeVel = velocity - other.velocity;

            // Collision impulse
            float velocityAlongNormal = relativeVel.dot(normal);

            // Do not resolve if objects are moving away
            if (velocityAlongNormal > 0) return;

            // Calculate impulse scalar
            float j = -(1 + RESTITUTION) * velocityAlongNormal;
            j /= (1/mass + 1/other.mass);

            // Apply impulse
            Vec2 impulse = normal * j;
            velocity = velocity + impulse * (1.0f/mass);
            // other.velocity = other.velocity - impulse * (1.0f/other.mass);

            // Positional correction to prevent sinking
            const float percent = 0.2f; // usually 20% to 80%
            const float slop = 0.01f; // usually 0.01 to 0.1
            Vec2 correction = normal * (std::max(distance - radius - other.radius - slop, 0.0f) / (1/mass + 1/other.mass)) * percent;
            position = position + correction * (1.0f/mass);
            // other.position = other.position - correction * (1.0f/other.mass);
        }
    }
};

// Physics world
class PhysicsWorld {
private:
    std::vector<RigidBody> bodies;
    Vec2 gravity;

public:
    PhysicsWorld() : gravity(0, GRAVITY) {}

    void addBody(const RigidBody& body) {
        bodies.push_back(body);
    }

    void step(float dt) {
        // Apply gravity
        for (auto& body : bodies) {
            body.addForce(gravity * body.mass);
        }

        // Update all bodies
        for (auto& body : bodies) {
            body.update(dt);
        }

        // Check collisions (simple O(n^2) for demo)
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                bodies[i].resolveCollision(bodies[j]);
            }
        }

        // Ground collision
        for (auto& body : bodies) {
            if (body.position.y + body.radius > 500) { // Ground at y=500
                body.position.y = 500 - body.radius;
                body.velocity.y *= -RESTITUTION;

                // Add some friction
                body.velocity.x *= 0.9f;
            }
        }
    }

    const std::vector<RigidBody>& getBodies() const { return bodies; }
};

// Frame rate control
class FrameRateController {
private:
    sf::Clock clock;
    float accumulator = 0.0f;
    float frameTime = 0.0f;
    float fps = 0.0f;

public:
    void startFrame() {
        float currentTime = clock.getElapsedTime().asSeconds();
        frameTime = currentTime - accumulator;
        accumulator = currentTime;

        if (frameTime > MAX_FRAME_TIME) {
            frameTime = MAX_FRAME_TIME;
        }
    }

    bool shouldStep() {
        return frameTime >= TIMESTEP;
    }

    void stepPhysics(PhysicsWorld& world) {
        while (frameTime >= TIMESTEP) {
            world.step(TIMESTEP);
            frameTime -= TIMESTEP;
        }
    }

    void endFrame() {
        // Calculate FPS
        static sf::Clock fpsClock;
        static int frameCount = 0;

        frameCount++;
        if (fpsClock.getElapsedTime().asSeconds() >= 1.0f) {
            fps = frameCount / fpsClock.restart().asSeconds();
            frameCount = 0;
        }
    }

    float getFPS() const { return fps; }
    float getFrameTime() const { return frameTime; }
};

int main() {
    // Create window
    sf::RenderWindow window(sf::VideoMode(800, 600), "Physics Simulation");
    window.setFramerateLimit(60);

    // Create physics world
    PhysicsWorld world;

    // Add some bodies
    world.addBody(RigidBody(Vec2(400, 100), 1.0f, 20.0f, sf::Color::Red));
    world.addBody(RigidBody(Vec2(350, 100), 1.0f, 20.0f, sf::Color::Green));
    world.addBody(RigidBody(Vec2(450, 100), 1.0f, 20.0f, sf::Color::Blue));
    world.addBody(RigidBody(Vec2(400, 50), 2.0f, 30.0f, sf::Color::Yellow));

    // Frame rate controller
    FrameRateController frc;

    // Main loop
    while (window.isOpen()) {
        // Event handling
        sf::Event event;
        while (window.pollEvent(event)) {
            if (event.type == sf::Event::Closed) {
                window.close();
            }

            // Add new body on click
            if (event.type == sf::Event::MouseButtonPressed && event.mouseButton.button == sf::Mouse::Left) {
                sf::Vector2i mousePos = sf::Mouse::getPosition(window);
                float mass = 1.0f + static_cast<float>(rand() % 3);
                float radius = 10.0f + static_cast<float>(rand() % 20);
                world.addBody(RigidBody(Vec2(mousePos.x, mousePos.y), mass, radius,
                    sf::Color(rand() % 255, rand() % 255, rand() % 255)));
            }
        }

        // Frame rate control
        frc.startFrame();

        if (frc.shouldStep()) {
            frc.stepPhysics(world);
        }

        frc.endFrame();

        // Rendering
        window.clear(sf::Color::Black);

        // Draw ground
        sf::RectangleShape ground(sf::Vector2f(800, 10));
        ground.setPosition(0, 590);
        ground.setFillColor(sf::Color(100, 100, 100));
        window.draw(ground);

        // Draw bodies
        for (const auto& body : world.getBodies()) {
            sf::CircleShape shape(body.radius);
            shape.setPosition(body.position.x - body.radius, body.position.y - body.radius);
            shape.setFillColor(body.color);
            window.draw(shape);
        }

        // Display FPS
