#include <vector>
#include <chrono>
#include <thread>
#include <iostream>
#include <cmath>

// Vector math utilities
struct Vec2 {
    float x, y;

    Vec2 operator+(const Vec2& other) const { return {x + other.x, y + other.y}; }
    Vec2 operator-(const Vec2& other) const { return {x - other.x, y - other.y}; }
    Vec2 operator*(float s) const { return {x * s, y * s}; }
    Vec2 operator/(float s) const { return {x / s, y / s}; }
    float length() const { return std::sqrt(x*x + y*y); }
    Vec2 normalized() const { return *this / length(); }
    float dot(const Vec2& other) const { return x*other.x + y*other.y; }
};

// Rigid body representation
class RigidBody {
public:
    Vec2 position;
    Vec2 velocity;
    float rotation;       // in radians
    float angularVelocity;
    float mass;
    float invMass;        // 0 for static objects
    Vec2 forceAccum;
    float torqueAccum;

    RigidBody(Vec2 pos, float m) : position(pos), mass(m), invMass(m > 0 ? 1.0f/m : 0) {
        velocity = {0, 0};
        rotation = 0;
        angularVelocity = 0;
        forceAccum = {0, 0};
        torqueAccum = 0;
    }

    void applyForce(Vec2 force) {
        forceAccum = forceAccum + force;
    }

    void applyTorque(float torque) {
        torqueAccum += torque;
    }

    void integrate(float dt) {
        if (invMass == 0) return; // Skip static objects

        // Linear motion
        Vec2 acceleration = forceAccum * invMass;
        velocity = velocity + acceleration * dt;
        position = position + velocity * dt;

        // Angular motion (simplified inertia)
        float angularAcceleration = torqueAccum * invMass;
        angularVelocity += angularAcceleration * dt;
        rotation += angularVelocity * dt;

        // Clear accumulators
        forceAccum = {0, 0};
        torqueAccum = 0;
    }
};

// Physics world that manages all bodies and simulation
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec2 gravity = {0, -9.8f};
    float restitution = 0.5f; // bounciness

    void step(float dt) {
        // Apply forces (gravity)
        for (auto& body : bodies) {
            if (body.invMass > 0) { // Only dynamic bodies
                body.applyForce(gravity * body.mass);
            }
        }

        // Integrate motion
        for (auto& body : bodies) {
            body.integrate(dt);
        }

        // Collision detection and resolution
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                resolveCollision(bodies[i], bodies[j]);
            }
        }
    }

private:
    void resolveCollision(RigidBody& a, RigidBody& b) {
        // Simple AABB collision detection (for demonstration)
        Vec2 halfSize = {0.5f, 0.5f};
        Vec2 minA = a.position - halfSize;
        Vec2 maxA = a.position + halfSize;
        Vec2 minB = b.position - halfSize;
        Vec2 maxB = b.position + halfSize;

        // Check for separation
        if (maxA.x < minB.x || minA.x > maxB.x ||
            maxA.y < minB.y || minA.y > maxB.y) {
            return; // No collision
        }

        // Calculate collision normal and penetration
        Vec2 normal;
        float penetration;

        // Find the axis of least penetration
        float xOverlap = std::min(maxA.x, maxB.x) - std::max(minA.x, minB.x);
        float yOverlap = std::min(maxA.y, maxB.y) - std::max(minA.y, minB.y);

        if (xOverlap < yOverlap) {
            penetration = xOverlap;
            normal = (a.position.x < b.position.x) ? Vec2{1, 0} : Vec2{-1, 0};
        } else {
            penetration = yOverlap;
            normal = (a.position.y < b.position.y) ? Vec2{0, 1} : Vec2{0, -1};
        }

        // Position correction (simple)
        float correction = std::max(penetration - 0.01f, 0.0f) / (a.invMass + b.invMass);
        a.position = a.position - normal * correction * a.invMass;
        b.position = b.position + normal * correction * b.invMass;

        // Calculate relative velocity
        Vec2 relativeVelocity = b.velocity - a.velocity;
        float velocityAlongNormal = relativeVelocity.dot(normal);

        // Do not resolve if objects are moving away
        if (velocityAlongNormal > 0) return;

        // Calculate impulse scalar
        float e = restitution; // Coefficient of restitution
        float j = -(1 + e) * velocityAlongNormal;
        j /= (a.invMass + b.invMass);

        // Apply impulse
        Vec2 impulse = normal * j;
        a.velocity = a.velocity - impulse * a.invMass;
        b.velocity = b.velocity + impulse * b.invMass;
    }
};

// Simple console-based visualization
void render(const PhysicsWorld& world) {
    const int width = 50;
