        int screenY = static_cast<int>((body.position.y) * height/10.0f);

        if (screenX >= 0 && screenX < width && screenY >= 0 && screenY < height) {
            grid[height - 1 - screenY][screenX] = 'O';
        }
    }

    // Print grid
    for (const auto& row : grid) {
        for (char c : row) {
            std::cout << c;
        }
        std::cout << '\n';
    }
    std::cout << "==============================\n";
}

