    // Create some bodies
    world.bodies.emplace_back(Vec2{0, -1}, 0.0f); // Static ground
    world.bodies.emplace_back(Vec2{0, 5}, 1.0f);  // Dynamic box
    world.bodies.emplace_back(Vec2{-2, 3}, 1.0f); // Another dynamic box
    world.bodies.emplace_back(Vec2{2, 4}, 1.0f);  // Another dynamic box

    // Simulation parameters
    const float physicsStep = 1.0f / 60.0f; // 60Hz physics simulation
    const float maxFrameTime = 0.25f;       // Prevent spiral of death
    const int targetFPS = 60;

    auto lastTime = std::chrono::high_resolution_clock::now();
    float accumulator = 0.0f;

    while (true) {
        // Calculate frame time
        auto currentTime = std::chrono::high_resolution_clock::now();
        float frameTime = std::chrono::duration<float>(currentTime - lastTime).count();
        lastTime = currentTime;

        // Clamp frame time to prevent large jumps
        if (frameTime > maxFrameTime) frameTime = maxFrameTime;

        // Accumulate time for fixed timestep
        accumulator += frameTime;

        // Fixed timestep physics simulation
        while (accumulator >= physicsStep) {
            world.step(physicsStep);
            accumulator -= physicsStep;
        }

        // Render at target FPS
        static auto nextRenderTime = std::chrono::high_resolution_clock::now();
        if (currentTime >= nextRenderTime) {
            // Simple console clear (works on most terminals)
            std::cout << "\033[2J\033[1;1H";

            render(world);
            nextRenderTime += std::chrono::milliseconds(1000 / targetFPS);
        }

        // Cap frame rate
        auto frameDuration = std::chrono::high_resolution_clock::now() - currentTime;
        auto targetFrameTime = std::chrono::milliseconds(1000 / targetFPS);
        if (frameDuration < targetFrameTime) {
            std::this_thread::sleep_for(targetFrameTime - frameDuration);
        }
    }

    return 0;
}
