```cpp
#include <SFML/Graphics.hpp>
#include <Box2D/Box2D.h>
#include <vector>
#include <iostream>

// Constants
const float WORLD_SCALE = 30.0f; // Scale between Box2D and SFML coordinates
const float TIME_STEP = 1.0f / 60.0f; // Fixed physics timestep (60Hz)
const int VELOCITY_ITERATIONS = 6;
const int POSITION_ITERATIONS = 2;
const int MAX_FRAME_TIME = 250; // ms (to prevent spiral of death)

// Physics simulation class
class PhysicsWorld {
private:
    b2World world;
    std::vector<b2Body*> bodies;

public:
    PhysicsWorld() : world(b2Vec2(0.0f, 9.8f)) {} // Gravity (9.8 m/s² downward)

    void Step(float deltaTime) {
        // Clamp delta time to prevent large jumps
        deltaTime = std::min(deltaTime, MAX_FRAME_TIME / 1000.0f);

        // Accumulate time for fixed timestep
        static float accumulator = 0.0f;
        accumulator += deltaTime;

        // Update physics at fixed timestep
        while (accumulator >= TIME_STEP) {
            world.Step(TIME_STEP, VELOCITY_ITERATIONS, POSITION_ITERATIONS);
            accumulator -= TIME_STEP;
        }
    }

    b2Body* CreateBox(float x, float y, float width, float height, bool isStatic = false) {
        b2BodyDef bodyDef;
        bodyDef.position.Set(x / WORLD_SCALE, y / WORLD_SCALE);
        bodyDef.type = isStatic ? b2_staticBody : b2_dynamicBody;

        b2Body* body = world.CreateBody(&bodyDef);

        b2PolygonShape dynamicBox;
        dynamicBox.SetAsBox(width / 2 / WORLD_SCALE, height / 2 / WORLD_SCALE);

        b2FixtureDef fixtureDef;
        fixtureDef.shape = &dynamicBox;
        fixtureDef.density = 1.0f;
        fixtureDef.friction = 0.3f;
        body->CreateFixture(&fixtureDef);

        bodies.push_back(body);
        return body;
    }

    void Render(sf::RenderWindow& window) {
        for (b2Body* body : bodies) {
            if (body->GetType() == b2_staticBody) continue;

            // Get the body's transform
            b2Transform transform = body->GetTransform();
            float angle = transform.q.GetAngle();

            // Create SFML rectangle
            sf::RectangleShape shape(sf::Vector2f(
                body->GetFixtureList()->GetShape()->m_radius * 2 * WORLD_SCALE,
                body->GetFixtureList()->GetShape()->m_radius * 2 * WORLD_SCALE
            ));

            // Convert Box2D coordinates to SFML coordinates
            shape.setPosition(
                transform.p.x * WORLD_SCALE - shape.getSize().x / 2,
                transform.p.y * WORLD_SCALE - shape.getSize().y / 2
            );
            shape.setRotation(angle * 180.0f / b2_pi);
            shape.setFillColor(sf::Color::Green);
            window.draw(shape);
        }
    }

    b2World& GetWorld() { return world; }
};

// Main function
int main() {
    // Create window
    sf::RenderWindow window(sf::VideoMode(800, 600), "Real-time Physics Simulation");
    window.setFramerateLimit(60); // Limit rendering to 60 FPS

    // Create physics world
    PhysicsWorld physicsWorld;

    // Create ground
    physicsWorld.CreateBox(400, 580, 800, 20, true);

    // Create some dynamic boxes
    for (int i = 0; i < 5; ++i) {
        physicsWorld.CreateBox(200 + i * 60, 100, 40, 40);
    }

    // Main loop
    sf::Clock clock;
    float lastTime = 0.0f;

    while (window.isOpen()) {
        // Calculate delta time
        float currentTime = clock.getElapsedTime().asSeconds();
        float deltaTime = currentTime - lastTime;
        lastTime = currentTime;

        // Handle events
        sf::Event event;
        while (window.pollEvent(event)) {
            if (event.type == sf::Event::Closed) {
                window.close();
            }

            // Create new box on mouse click
            if (event.type == sf::Event::MouseButtonPressed && event.mouseButton.button == sf::Mouse::Left) {
                sf::Vector2i mousePos = sf::Mouse::getPosition(window);
                physicsWorld.CreateBox(mousePos.x, mousePos.y, 30, 30);
            }
        }

        // Update physics
        physicsWorld.Step(deltaTime);

        // Render
        window.clear(sf::Color::Black);
        physicsWorld.Render(window);
        window.display();
    }

    return 0;
}
