    Vector2 operator+(const Vector2& other) const {
        return Vector2(x + other.x, y + other.y);
    }

    Vector2 operator-(const Vector2& other) const {
        return Vector2(x - other.x, y - other.y);
    }

    Vector2 operator*(float scalar) const {
        return Vector2(x * scalar, y * scalar);
    }

    Vector2 operator/(float scalar) const {
        return Vector2(x / scalar, y / scalar);
    }

    float length() const {
        return std::sqrt(x * x + y * y);
    }

    Vector2 normalized() const {
        float len = length();
        if (len > 0) return Vector2(x / len, y / len);
        return *this;
    }

    void operator+=(const Vector2& other) {
        x += other.x;
        y += other.y;
    }

    void operator*=(float scalar) {
        x *= scalar;
        y *= scalar;
    }
};

// Rigid Body class
class RigidBody {
public:
    Vector2 position;
    Vector2 velocity;
    Vector2 acceleration;
    float mass;
    float radius;
    bool isStatic;
    sf::Color color;

    RigidBody(Vector2 pos, float r, float m, bool stat = false, sf::Color col = sf::Color::Green)
        : position(pos), radius(r), mass(m), isStatic(stat), color(col) {
        velocity = Vector2(0, 0);
        acceleration = Vector2(0, GRAVITY);
    }

    void applyForce(Vector2 force) {
        if (!isStatic) {
            acceleration += force * (1.0f / mass);
        }
    }

    void update(float deltaTime) {
        if (!isStatic) {
            // Semi-implicit Euler integration
            velocity += acceleration * deltaTime;
            position += velocity * deltaTime;

            // Apply damping
            velocity *= 0.99f;
        }

        // Reset acceleration for next frame
        acceleration = Vector2(0, isStatic ? 0 : GRAVITY);
    }
};

// Physics World class
class PhysicsWorld {
public:
    std::vector<std::unique_ptr<RigidBody>> bodies;
    float gravity;

    PhysicsWorld(float g = GRAVITY) : gravity(g) {}

    void addBody(std::unique_ptr<RigidBody> body) {
        bodies.push_back(std::move(body));
    }

    void update(float deltaTime) {
        // Apply gravity to all dynamic bodies
        for (auto& body : bodies) {
            if (!body->isStatic) {
                body->applyForce(Vector2(0, body->mass * gravity));
            }
        }

        // Update all bodies
        for (auto& body : bodies) {
            body->update(deltaTime);
        }

        // Check for collisions
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                resolveCollision(bodies[i].get(), bodies[j].get());
            }
        }
    }

    void resolveCollision(RigidBody* a, RigidBody* b) {
        if (a->isStatic && b->isStatic) return;

        // Simple circle-circle collision detection
        Vector2 delta = b->position - a->position;
        float distance = delta.length();
        float minDistance = a->radius + b->radius;

        if (distance < minDistance) {
            // Collision detected
            Vector2 normal = delta.normalized();
            Vector2 relativeVelocity = b->velocity - a->velocity;

            // Calculate impulse scalar
            float impulse = -(1 + RESTITUTION) * (relativeVelocity.x * normal.x + relativeVelocity.y * normal.y);
            impulse /= (1/a->mass + 1/b->mass);

            Vector2 impulseVec = normal * impulse;

            // Apply impulse
            if (!a->isStatic) {
                a->velocity -= impulseVec * (1.0f / a->mass);
            }
            if (!b->isStatic) {
                b->velocity += impulseVec * (1.0f / b->mass);
            }

            // Position correction to prevent sinking
            float correction = (minDistance - distance) * 0.2f;
            if (!a->isStatic) {
                a->position -= normal * correction * 0.5f;
            }
            if (!b->isStatic) {
                b->position += normal * correction * 0.5f;
            }
        }
    }
};

