#include <vector>
#include <chrono>
#include <iostream>

// Vector math
struct Vec2 {
    float x, y;
    Vec2 operator+(const Vec2& other) const { return {x + other.x, y + other.y}; }
    Vec2 operator-(const Vec2& other) const { return {x - other.x, y - other.y}; }
    Vec2 operator*(float s) const { return {x * s, y * s}; }
    float length() const { return sqrt(x*x + y*y); }
    Vec2 normalized() const { return *this * (1.0f / length()); }
};

// RigidBody
class RigidBody {
public:
    Vec2 position;
    Vec2 velocity;
    float rotation; // angle in radians
    float angularVelocity;
    float mass;
    float invMass; // 1/mass, 0 for static objects
    Vec2 forceAccum;
    float torqueAccum;

    RigidBody(Vec2 pos, float m) : position(pos), mass(m), invMass(m > 0 ? 1.0f/m : 0) {
        velocity = {0, 0};
        rotation = 0;
        angularVelocity = 0;
        forceAccum = {0, 0};
        torqueAccum = 0;
    }

    void applyForce(Vec2 force) {
        forceAccum = forceAccum + force;
    }

    void applyTorque(float torque) {
        torqueAccum += torque;
    }

    void integrate(float dt) {
        if (invMass == 0) return; // static object

        // Linear motion
        Vec2 acceleration = forceAccum * invMass;
        velocity = velocity + acceleration * dt;
        position = position + velocity * dt;

        // Angular motion
        float angularAcceleration = torqueAccum * invMass; // simplified inertia
        angularVelocity += angularAcceleration * dt;
        rotation += angularVelocity * dt;

        // Clear accumulators
        forceAccum = {0, 0};
        torqueAccum = 0;
    }
};

// PhysicsWorld
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec2 gravity = {0, -9.8f};

    void step(float dt) {
        // Apply gravity
        for (auto& body : bodies) {
            if (body.invMass > 0) { // not static
                body.applyForce(gravity * body.mass);
            }
        }

        // Integrate
        for (auto& body : bodies) {
            body.integrate(dt);
        }

        // Simple collision detection/resolution (AABB vs AABB)
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                RigidBody& a = bodies[i];
                RigidBody& b = bodies[j];

                // Simple AABB collision detection (for demo)
                // In a real engine, you'd use more sophisticated methods
                Vec2 minA = a.position - Vec2{0.5f, 0.5f};
                Vec2 maxA = a.position + Vec2{0.5f, 0.5f};
                Vec2 minB = b.position - Vec2{0.5f, 0.5f};
                Vec2 maxB = b.position + Vec2{0.5f, 0.5f};

                if (maxA.x < minB.x || minA.x > maxB.x ||
                    maxA.y < minB.y || minA.y > maxB.y) {
                    continue; // no collision
                }

                // Simple collision resolution (just push apart)
                Vec2 normal = (b.position - a.position).normalized();
                float overlap = 0.5f - (b.position - a.position).length();
                a.position = a.position - normal * overlap * 0.5f;
                b.position = b.position + normal * overlap * 0.5f;

                // Simple impulse response
                Vec2 relativeVelocity = b.velocity - a.velocity;
                float velocityAlongNormal = relativeVelocity.x * normal.x + relativeVelocity.y * normal.y;

                if (velocityAlongNormal > 0) continue; // separating

                float e = 0.5f; // coefficient of restitution
                float j = -(1 + e) * velocityAlongNormal;
                j /= (a.invMass + b.invMass);

                Vec2 impulse = normal * j;
                a.velocity = a.velocity - impulse * a.invMass;
                b.velocity = b.velocity + impulse * b.invMass;
            }
        }
    }
};

// Main loop with frame rate control
int main() {
    PhysicsWorld world;
    world.bodies.emplace_back(Vec2{0, 0}, 1.0f); // static ground
    world.bodies.emplace_back(Vec2{0, 5}, 1.0f); // dynamic box

    const float physicsStep = 1.0f / 60.0f; // 60Hz physics
    const float maxFrameTime = 0.25f; // prevent spiral of death

    auto lastTime = std::chrono::high_resolution_clock::now();
    float accumulator = 0.0f;

    while (true) {
        auto currentTime = std::chrono::high_resolution_clock::now();
        float frameTime = std::chrono::duration<float>(currentTime - lastTime).count();
        lastTime = currentTime;

        if (frameTime > maxFrameTime) frameTime = maxFrameTime;

        accumulator += frameTime;

        // Fixed timestep physics
        while (accumulator >= physicsStep) {
            world.step(physicsStep);
            accumulator -= physicsStep;
        }

        // Rendering would go here
        // For demo, we'll just print positions
        for (const auto& body : world.bodies) {
            std::cout << "Body at (" << body.position.x << ", " << body.position.y << ")\n";
        }
        std::cout << "-----\n";

        // Simple frame rate control (sleep to maintain ~60fps)
        std::this_thread::sleep_for(std::chrono::milliseconds(16));
    }

    return 0;
}
