        if (len > 0) {
            return Vector2(x / len, y / len);
        }
        return *this;
    }

    void operator+=(const Vector2& other) {
        x += other.x;
        y += other.y;
    }

    void operator*=(float scalar) {
        x *= scalar;
        y *= scalar;
    }
};

