// 3D Vector class
class Vec3 {
public:
    float x, y, z;
    Vec3(float x = 0, float y = 0, float z = 0) : x(x), y(y), z(z) {}

    Vec3 operator+(const Vec3& v) const { return Vec3(x + v.x, y + v.y, z + v.z); }
    Vec3 operator-(const Vec3& v) const { return Vec3(x - v.x, y - v.y, z - v.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3& operator+=(const Vec3& v) { x += v.x; y += v.y; z += v.z; return *this; }
    float dot(const Vec3& v) const { return x * v.x + y * v.y + z * v.z; }
    float length() const { float l = sqrt(x * x + y * y + z * z); return l > 0 ? l : 1.0f; }
    Vec3 normalized() const { float l = length(); return Vec3(x / l, y / l, z / l); }
};

// Rigid Body with position, velocity, and collision response
class RigidBody {
public:
    Vec3 position;
    Vec3 velocity;
    Vec3 acceleration;
    float mass;
    float restitution; // Bounciness (0 = inelastic, 1 = elastic)

    RigidBody(Vec3 pos, float mass, float restitution = 0.5f)
        : position(pos), velocity(0, 0, 0), acceleration(0, 0, 0),
          mass(mass), restitution(restitution) {}

    void applyForce(const Vec3& force) {
        acceleration += force * (1.0f / mass);
    }

    void step(float dt) {
        velocity += acceleration * dt;
        position += velocity * dt;
        acceleration = Vec3(0, 0, 0); // Reset for next frame
    }

    void handleCollision(const Vec3& planeNormal, float planeDist) {
        float distance = position.dot(planeNormal) - planeDist;
        if (distance < 0) {
            // Move out of collision
            position -= planeNormal * distance;
            // Compute velocity component along the normal
            float velocityAlongNormal = velocity.dot(planeNormal);
            if (velocityAlongNormal < 0) { // Moving toward the plane
                velocity -= planeNormal * (velocityAlongNormal * (1 + restitution));
            }
        }
    }
};

// Physics World with gravity and collision handling
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec3 gravity;
    Vec3 groundNormal;
    float groundDist;

    PhysicsWorld(Vec3 gravity = Vec3(0, -9.81f, 0),
                 Vec3 groundNormal = Vec3(0, 1, 0),
                 float groundDist = 0)
        : gravity(gravity), groundNormal(groundNormal), groundDist(groundDist) {}

    void addBody(const RigidBody& body) {
        bodies.push_back(body);
    }

    void step(float dt) {
        // Apply gravity (F = m * g)
        for (auto& body : bodies) {
            body.applyForce(gravity * body.mass);
        }

        // Update all bodies and handle collisions
        for (auto& body : bodies) {
            body.step(dt);
            body.handleCollision(groundNormal, groundDist);
        }
    }
};

