    float restitution = 0.8f; // Bounciness (0 = no bounce, 1 = perfect bounce)
    float width = 1.0f, height = 1.0f; // AABB dimensions

    void applyForce(const Vec2& force) {
        acceleration = acceleration + force * (1.0f / mass);
    }

    void update(float dt) {
        // Semi-implicit Euler integration
        velocity = velocity + acceleration * dt;
        position = position + velocity * dt;

        // Apply damping (air resistance)
        velocity = velocity * 0.99f;

        // Reset acceleration for next frame
        acceleration = Vec2(0, 0);
    }
};

// --- Collision Detection ---
struct AABB {
    Vec2 min, max;
};

AABB getAABB(const RigidBody& body) {
    return AABB{
        Vec2(body.position.x - body.width / 2, body.position.y - body.height / 2),
        Vec2(body.position.x + body.width / 2, body.position.y + body.height / 2)
    };
}

bool checkAABBCollision(const AABB& a, const AABB& b) {
    return (a.min.x < b.max.x && a.max.x > b.min.x) &&
           (a.min.y < b.max.y && a.max.y > b.min.y);
}

void resolveCollision(RigidBody& a, RigidBody& b) {
    AABB aAABB = getAABB(a);
    AABB bAABB = getAABB(b);

    // Simple collision response: push bodies apart and apply impulse
    Vec2 overlap = Vec2(
        std::min(aAABB.max.x - bAABB.min.x, bAABB.max.x - aAABB.min.x),
        std::min(aAABB.max.y - bAABB.min.y, bAABB.max.y - aAABB.min.y)
    );

    if (overlap.x < overlap.y) {
        // Resolve along X-axis
        if (aAABB.min.x < bAABB.min.x) {
            a.position.x -= overlap.x / 2;
            b.position.x += overlap.x / 2;
        } else {
            a.position.x += overlap.x / 2;
            b.position.x -= overlap.x / 2;
        }
        // Apply impulse (simplified)
        Vec2 normal = Vec2(1, 0);
        Vec2 relativeVelocity = b.velocity - a.velocity;
        float velocityAlongNormal = relativeVelocity.x;
        if (velocityAlongNormal > 0) return; // Separating

        float j = -(1 + a.restitution) * velocityAlongNormal;
        float impulse = j / (1.0f / a.mass + 1.0f / b.mass);
        Vec2 impulseVec = Vec2(impulse, 0);

        a.velocity = a.velocity - impulseVec * (1.0f / a.mass);
        b.velocity = b.velocity + impulseVec * (1.0f / b.mass);
    } else {
        // Resolve along Y-axis
        if (aAABB.min.y < bAABB.min.y) {
            a.position.y -= overlap.y / 2;
            b.position.y += overlap.y / 2;
        } else {
            a.position.y += overlap.y / 2;
            b.position.y -= overlap.y / 2;
        }
        // Apply impulse (simplified)
        Vec2 normal = Vec2(0, 1);
        Vec2 relativeVelocity = b.velocity - a.velocity;
        float velocityAlongNormal = relativeVelocity.y;
        if (velocityAlongNormal > 0) return; // Separating

        float j = -(1 + a.restitution) * velocityAlongNormal;
        float impulse = j / (1.0f / a.mass + 1.0f / b.mass);
        Vec2 impulseVec = Vec2(0, impulse);

        a.velocity = a.velocity - impulseVec * (1.0f / a.mass);
        b.velocity = b.velocity + impulseVec * (1.0f / b.mass);
    }
}

// --- Physics World ---
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec2 gravity = Vec2(0, -9.81f); // Earth gravity

    void addBody(const RigidBody& body) {
        bodies.push_back(body);
    }

    void update(float dt) {
        // Apply forces (e.g., gravity)
        for (auto& body : bodies) {
            body.applyForce(gravity * body.mass);
        }

        // Update positions
        for (auto& body : bodies) {
            body.update(dt);
        }

        // Check for collisions
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                AABB aabbA = getAABB(bodies[i]);
                AABB aabbB = getAABB(bodies[j]);
                if (checkAABBCollision(aabbA, aabbB)) {
                    resolveCollision(bodies[i], bodies[j]);
                }
            }
        }
    }
};

// --- Main Simulation ---
int main() {
    const float targetFPS = 60.0f;
    const float targetFrameTime = 1.0f / targetFPS;
    const int numSteps = 10; // Substeps for stability

    PhysicsWorld world;
    world.addBody({Vec2(0, 10), Vec2(0, 0), Vec2(0, 0), 1.0f}); // Falling box
    world.addBody({Vec2(0, 0), Vec2(0, 0), Vec2(0, 0), 1.0f, 0.8f, 10.0f, 0.5f}); // Ground (static)

    auto lastTime = std::chrono::high_resolution_clock::now();
    while (true) {
        auto currentTime = std::chrono::high_resolution_clock::now();
        float deltaTime = std::chrono::duration<float>(currentTime - lastTime).count();
        lastTime = currentTime;

        // Fixed timestep loop (substepping for stability)
        static float accumulator = 0.0f;
        accumulator += deltaTime;
        while (accumulator >= targetFrameTime) {
            world.update(targetFrameTime / numSteps); // Substeps
            accumulator -= targetFrameTime;
        }

        // Print simulation state (every 10 frames for brevity)
        static int frameCount = 0;
        if (frameCount++ % 10 == 0) {
            std::cout << "Frame " << frameCount << ":\n";
            for (size_t i = 0; i < world.bodies.size(); ++i) {
                const auto& body = world.bodies[i];
                std::cout << "  Body " << i << ": Pos(" << body.position.x << ", " << body.position.y
                          << "), Vel(" << body.velocity.x << ", " << body.velocity.y << ")\n";
            }
            std::cout << "--------------------\n";
        }

        // Simple way to exit (press Ctrl+C in terminal)
        if (frameCount > 100) break;
    }

    return 0;
}
