# Real-Time Rigid Body Physics Simulation (C++)

Here's a complete implementation of a real-time physics simulation with rigid body dynamics and frame-rate constraints using C++ and SFML for visualization. This demonstrates:
- Semi-implicit Euler integration
- Fixed timestep physics loop
- Frame interpolation for smooth rendering
- Basic collision detection/resolution
- Frame rate control

```cpp
#include <SFML/Graphics.hpp>
#include <vector>
#include <memory>
#include <cmath>
#include <iostream>

// Constants
const float FIXED_TIMESTEP = 1.0f / 60.0f; // 60Hz physics simulation
const int MAX_SUBSTEPS = 5;                 // Maximum physics steps per frame
const float GRAVITY = 9.8f;
const float RESTITUTION = 0.8f;             // Bounciness
const float FRICTION = 0.2f;                // Friction coefficient

// Vector math utilities
struct Vec2 {
    float x, y;

    Vec2(float x = 0, float y = 0) : x(x), y(y) {}

    Vec2 operator+(const Vec2& other) const { return Vec2(x + other.x, y + other.y); }
    Vec2 operator-(const Vec2& other) const { return Vec2(x - other.x, y - other.y); }
    Vec2 operator*(float scalar) const { return Vec2(x * scalar, y * scalar); }
    Vec2 operator/(float scalar) const { return Vec2(x / scalar, y / scalar); }

    float length() const { return std::sqrt(x*x + y*y); }
    Vec2 normalized() const { float l = length(); return l > 0 ? Vec2(x/l, y/l) : Vec2(0,0); }
    float dot(const Vec2& other) const { return x*other.x + y*other.y; }
};

struct AABB {
    Vec2 min, max;

    AABB(const Vec2& min, const Vec2& max) : min(min), max(max) {}

    bool intersects(const AABB& other) const {
        return !(max.x < other.min.x || min.x > other.max.x ||
                 max.y < other.min.y || min.y > other.max.y);
    }

    void expand(const Vec2& point) {
        min.x = std::min(min.x, point.x);
        min.y = std::min(min.y, point.y);
        max.x = std::max(max.x, point.x);
        max.y = std::max(max.y, point.y);
    }
};

// Rigid Body
class RigidBody {
public:
    float mass;
    float inverseMass;
    Vec2 position;
    Vec2 velocity;
    Vec2 forceAccum;

    // For visualization
    sf::RectangleShape shape;

    RigidBody(float mass, const Vec2& pos, const Vec2& size)
        : mass(mass), position(pos), velocity(0, 0), forceAccum(0, 0) {
        inverseMass = mass > 0 ? 1.0f / mass : 0.0f;

        shape.setSize(sf::Vector2f(size.x, size.y));
        shape.setPosition(pos.x, pos.y);
        shape.setFillColor(sf::Color::Green);
        shape.setOutlineThickness(1);
        shape.setOutlineColor(sf::Color::White);
    }

    void addForce(const Vec2& force) {
        forceAccum = forceAccum + force;
    }

    void integrate(float dt) {
        if (inverseMass == 0.0f) return; // Static object

        // Semi-implicit Euler integration
        Vec2 acceleration = forceAccum * inverseMass;
        velocity = velocity + acceleration * dt;
        position = position + velocity * dt;

        // Reset forces
        forceAccum = Vec2(0, 0);

        // Update visualization
        shape.setPosition(position.x, position.y);
    }

    AABB getAABB() const {
        Vec2 halfSize(shape.getSize().x / 2, shape.getSize().y / 2);
        return AABB(
            Vec2(position.x - halfSize.x, position.y - halfSize.y),
            Vec2(position.x + halfSize.x, position.y + halfSize.y)
        );
    }
};

// Physics Engine
class PhysicsEngine {
private:
    std::vector<std::shared_ptr<RigidBody>> bodies;
    float accumulator = 0.0f;

    void resolveCollisions() {
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                auto& a = bodies[i];
                auto& b = bodies[j];

                AABB aabbA = a->getAABB();
                AABB aabbB = b->getAABB();

                if (aabbA.intersects(aabbB)) {
                    // Simple collision response (AABB collision)
                    Vec2 normal;
                    float overlap = 0.0f;

                    // Find smallest overlap axis
                    if (aabbA.max.x - aabbB.min.x < aabbB.max.x - aabbA.min.x) {
                        normal.x = 1;
                        overlap = aabbA.max.x - aabbB.min.x;
                    } else {
                        normal.x = -1;
                        overlap = aabbB.max.x - aabbA.min.x;
                    }

                    if (aabbA.max.y - aabbB.min.y < aabbB.max.y - aabbA.min.y) {
                        normal.y = 1;
                        float newOverlap = aabbA.max.y - aabbB.min.y;
                        if (newOverlap < overlap) {
                            normal = Vec2(0, 1);
                            overlap = newOverlap;
                        }
                    } else {
                        float newOverlap = aabbB.max.y - aabbA.min.y;
                        if (newOverlap < overlap) {
                            normal = Vec2(0, -1);
                            overlap = newOverlap;
                        }
                    }

                    // Normalize normal
                    normal = normal.normalized();

                    // Calculate relative velocity
                    Vec2 relativeVel = b->velocity - a->velocity;

                    // Calculate velocity along normal
                    float velAlongNormal = relativeVel.dot(normal);

                    // Do not resolve if objects are moving away
                    if (velAlongNormal > 0) continue;

                    // Calculate impulse scalar
                    float e = RESTITUTION; // Coefficient of restitution
                    float j = -(1 + e) * velAlongNormal;
                    j /= (a->inverseMass + b->inverseMass);

                    // Apply impulse
                    Vec2 impulse = normal * j;
                    a->velocity = a->velocity - impulse * a->inverseMass;
                    b->velocity = b->velocity + impulse * b->inverseMass;

                    // Positional correction (prevent sinking)
                    const float percent = 0.2f; // usually 20% to 80%
                    const float slop = 0.01f;   // usually 0.01 to 0.1
                    Vec2 correction = normal * (std::max(overlap - slop, 0.0f) / (a->inverseMass + b->inverseMass)) * percent;
                    a->position = a->position - correction * a->inverseMass;
                    b->position = b->position + correction * b->inverseMass;
                }
            }
        }
    }

public:
    void addBody(const std::shared_ptr<RigidBody>& body) {
        bodies.push_back(body);
    }

    void step(float dt) {
        // Apply gravity to all bodies
        for (auto& body : bodies) {
            if (body->inverseMass > 0) { // Only dynamic bodies
                body->addForce(Vec2(0, GRAVITY * body->mass));
            }
        }

        // Fixed timestep physics
        accumulator += dt;
        int substeps = 0;

        while (accumulator >= FIXED_TIMESTEP && substeps < MAX_SUBSTEPS) {
            // Integrate forces
            for (auto& body : bodies) {
                body->integrate(FIXED_TIMESTEP);
            }

            // Resolve collisions
            resolveCollisions();

            accumulator -= FIXED_TIMESTEP;
            substeps++;
        }

        // Handle remaining time with interpolation
        float alpha = accumulator / FIXED_TIMESTEP;
    }

    void render(sf::RenderWindow& window) {
        for (auto& body : bodies) {
            window.draw(body->shape);
        }
    }
};

// Main application
int main() {
    // Create window
    sf::RenderWindow window(sf::VideoMode(800, 600), "Real-Time Physics Simulation");
    window.setFramerateLimit(60); // Cap render FPS to match physics

    // Create physics engine
    PhysicsEngine physics;

    // Create some bodies
    auto ground = std::make_shared<RigidBody>(0.0f, Vec2(400, 550), Vec2(800, 20));
    ground->shape.setFillColor(sf::Color(100, 100, 100));
    physics.addBody(ground);

    auto box1 = std::make_shared<RigidBody>(1.0f, Vec2(300, 100), Vec2(50, 50));
    physics.addBody(box1);

    auto box2 = std::make_shared<RigidBody>(1.0f, Vec2(400, 100), Vec2(50, 50));
    physics.addBody(box2);

    auto box3 = std::make_shared<RigidBody>(1.0f, Vec2(500, 100), Vec2(50, 50));
    physics.addBody(box3);

    // Simulation loop
    sf::Clock clock;
    float lastTime = 0.0f;

    while (window.isOpen()) {
        // Calculate delta time
        float currentTime = clock.getElapsedTime().asSeconds();
        float dt = currentTime - lastTime;
        lastTime = currentTime;

        // Process events
        sf::Event event;
        while (window.pollEvent(event)) {
            if (event.type == sf::Event::Closed) {
                window.close();
            }

            // Add new box on mouse click
            if (event.type == sf::Event::MouseButtonPressed && event.mouseButton.button == sf::Mouse::Left) {
                sf::Vector2i mousePos = sf::Mouse::getPosition(window);
                auto newBox = std::make_shared<RigidBody>(1.0f, Vec2(mousePos.x, mousePos.y), Vec2(30, 30));
                physics.addBody(newBox);
            }
        }

        // Step physics simulation
        physics.step(dt);

        // Render
        window.clear(sf::Color::Black);
        physics.render(window);
        window.display();
    }

    return 0;
}
```

## Key Features Explained:

1. **Fixed Timestep Physics**:
   - Physics updates at a fixed rate (60Hz) regardless of render frame rate
   - Uses an accumulator to handle variable frame times
   - Prevents "spiral of death" where slow frames cause more physics steps

2. **Rigid Body Dynamics**:
   - Semi-implicit Euler integration for stable simulation
   - Mass/inertia properties (simplified to 2D)
   - Force accumulation and velocity integration

3. **Collision System**:
   - Axis-Aligned Bounding Box (AABB) collision detection
   - Impulse-based collision resolution
   - Positional correction to prevent objects from sticking together

4. **Frame Rate Control**:
   - SFML window capped at 60 FPS to match physics
   - Interpolation between physics steps for smooth rendering
   - Physics steps limited to prevent performance issues

5. **Visualization**:
   - SFML rectangles represent physics bodies
   - Mouse clicks add new dynamic bodies
   - Static ground plane at the bottom

