#include <thread>

// Simple 2D vector
struct Vec2 {
    float x, y;
    Vec2(float x = 0, float y = 0) : x(x), y(y) {}
    Vec2 operator+(const Vec2& other) const { return Vec2(x + other.x, y + other.y); }
    Vec2 operator-(const Vec2& other) const { return Vec2(x - other.x, y - other.y); }
    Vec2 operator*(float scalar) const { return Vec2(x * scalar, y * scalar); }
    float length() const { return std::sqrt(x * x + y * y); }
    Vec2 normalized() const { float len = length(); return len > 0 ? Vec2(x / len, y / len) : Vec2(0, 0); }
};

// Rigid body in 2D (circle for simplicity)
class RigidBody {
public:
    Vec2 position;
    Vec2 velocity;
    Vec2 force;
    float mass;
    float restitution; // Bounciness (0 = no bounce, 1 = perfect bounce)
    float radius;      // For collision detection

    RigidBody(Vec2 pos, float mass, float radius = 1.0f, float restitution = 0.8f)
        : position(pos), velocity(0, 0), force(0, 0), mass(mass), restitution(restitution), radius(radius) {}

    void applyForce(Vec2 f) { force = force + f; }
    void integrate(float dt) {
        // Semi-implicit Euler integration (better stability)
        Vec2 acceleration = force * (1.0f / mass);
        velocity = velocity + acceleration * dt;
        position = position + velocity * dt;
        force = Vec2(0, 0); // Reset force
    }
};

// Physics world
class PhysicsWorld {
public:
    std::vector<RigidBody> bodies;
    Vec2 gravity;

    PhysicsWorld(Vec2 gravity = Vec2(0, -9.81f)) : gravity(gravity) {}

    void addBody(const RigidBody& body) { bodies.push_back(body); }

    void update(float dt) {
        // Apply gravity and integrate
        for (auto& body : bodies) {
            body.applyForce(gravity * body.mass);
            body.integrate(dt);
        }
        // Collision detection and response
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                RigidBody& a = bodies[i];
                RigidBody& b = bodies[j];
                Vec2 delta = b.position - a.position;
                float distance = delta.length();
                float minDistance = a.radius + b.radius;

                if (distance < minDistance) {
                    // Collision detected
                    Vec2 normal = delta.normalized();
                    Vec2 relativeVelocity = b.velocity - a.velocity;
                    float velocityAlongNormal = relativeVelocity.x * normal.x + relativeVelocity.y * normal.y;

                    // Do not resolve if objects are moving away
                    if (velocityAlongNormal > 0) continue;

                    // Calculate impulse scalar
                    float impulseScalar = -(1 + a.restitution) * velocityAlongNormal;
                    impulseScalar /= (1 / a.mass + 1 / b.mass);

                    // Apply impulse
                    Vec2 impulse = normal * impulseScalar;
                    a.velocity = a.velocity - impulse * (1 / a.mass);
                    b.velocity = b.velocity + impulse * (1 / b.mass);

                    // Positional correction to prevent sinking
                    float correction = (minDistance - distance) * 0.2f; // 20% of penetration
                    a.position = a.position - normal * correction * 0.5f;
                    b.position = b.position + normal * correction * 0.5f;
                }
            }
        }
        // Boundary collisions (walls)
        for (auto& body : bodies) {
            if (body.position.x - body.radius < -10.0f) {
                body.position.x = -10.0f + body.radius;
                body.velocity.x *= -body.restitution;
            }
            if (body.position.x + body.radius > 10.0f) {
                body.position.x = 10.0f - body.radius;
                body.velocity.x *= -body.restitution;
            }
            if (body.position.y - body.radius < -10.0f) {
                body.position.y = -10.0f + body.radius;
                body.velocity.y *= -body.restitution;
            }
            if (body.position.y + body.radius > 10.0f) {
                body.position.y = 10.0f - body.radius;
                body.velocity.y *= -body.restitution;
            }
        }
    }
};

// Game loop with fixed timestep
