    PhysicsWorld world;
    world.addBody(RigidBody(Vec2(0, -10), 0.0f, 10.0f, 0.8f)); // Floor (static, infinite mass)
    world.addBody(RigidBody(Vec2(0, 5), 1.0f, 1.0f)); // Falling ball
    world.addBody(RigidBody(Vec2(3, 5), 1.0f, 1.0f)); // Another falling ball

