        lastTime = currentTime;

        // Cap frame time to avoid spiral of death
        frameTime = std::min(frameTime, 0.25f); // Max 4 FPS

        // Fixed timestep for physics
        const float fixedTimeStep = 1.0f / 60.0f;
        static float accumulator = 0.0f;

        accumulator += frameTime;
        while (accumulator >= fixedTimeStep) {
            world.update(fixedTimeStep);
            accumulator -= fixedTimeStep;
        }

        // Render at target FPS
        renderer.render(world, 80, 24); // 80x24 terminal size

        // Check for exit key
        if (_kbhit()) {
            char c = _getch();
            if (c == 'q' || c == 'Q') break;
        }

        // Sleep to maintain frame rate
        auto sleepTime = std::chrono::milliseconds(static_cast<int>((targetFrameTime - frameTime) * 1000));
        if (sleepTime.count() > 0) {
            std::this_thread::sleep_for(sleepTime);
        }

        // Clear screen (simple approach)
        std::cout << "\033[2J\033[1;1H"; // ANSI clear screen and move cursor to top
    }
}

int main() {
    PhysicsWorld world;
    Renderer renderer;

    // Add some bodies
    world.addBody(RigidBody(Vec2(10, 5), 1.0f));  // Dynamic body
    world.addBody(RigidBody(Vec2(20, 5), 1.0f));  // Dynamic body
    world.addBody(RigidBody(Vec2(15, 15), 0.0f)); // Static body (mass=0)
    world.addBody(RigidBody(Vec2(30, 10), 2.0f)); // Heavy dynamic body

    // Add a ground plane
    world.addBody(RigidBody(Vec2(0, 0), 0.0f)); // Static ground

    std::cout << "Real-time Physics Simulation (Press 'q' to quit)\n";
    runSimulation(world, renderer, 30.0f); // 30 FPS

    return 0;
}
