        SDL_Quit();
        return 1;
    }

    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (!renderer) {
        std::cerr << "Renderer could not be created! SDL_Error: " << SDL_GetError() << std::endl;
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 1;
    }

    // Initialize Box2D world with gravity
    b2Vec2 gravity(0.0f, 9.8f); // Earth gravity (m/s²)
    b2World world(gravity);

    // Create ground (static body)
    b2BodyDef groundBodyDef;
    groundBodyDef.position.Set(0.0f, SCREEN_HEIGHT / SCALE);
    b2Body* groundBody = world.CreateBody(&groundBodyDef);
    b2PolygonShape groundBox;
    groundBox.SetAsBox(SCREEN_WIDTH / SCALE, 0.5f); // Half-width, half-height
    groundBody->CreateFixture(&groundBox, 0.0f); // Density = 0 (static)

    // Create dynamic box (falling object)
    b2BodyDef bodyDef;
    bodyDef.type = b2_dynamicBody;
    bodyDef.position.Set(SCREEN_WIDTH / (2.0f * SCALE), SCREEN_HEIGHT / (4.0f * SCALE));
    b2Body* body = world.CreateBody(&bodyDef);
    b2PolygonShape dynamicBox;
    dynamicBox.SetAsBox(1.0f, 1.0f); // Half-width, half-height (2m x 2m)
    b2FixtureDef fixtureDef;
    fixtureDef.shape = &dynamicBox;
    fixtureDef.density = 1.0f; // Mass = density * area
    fixtureDef.friction = 0.3f;
    body->CreateFixture(&fixtureDef);

    // Main game loop
    bool quit = false;
    SDL_Event e;
    Uint32 previousTime = SDL_GetTicks();
    Uint32 lag = 0;

    while (!quit) {
        // Handle events
        while (SDL_PollEvent(&e) != 0) {
            if (e.type == SDL_QUIT) {
                quit = true;
            } else if (e.type == SDL_KEYDOWN) {
                if (e.key.keysym.sym == SDLK_ESCAPE) {
                    quit = true;
                }
            }
        }

        // Fixed timestep physics update
        Uint32 currentTime = SDL_GetTicks();
        Uint32 elapsed = currentTime - previousTime;
        previousTime = currentTime;
        lag += elapsed;

        while (lag >= TIME_STEP * 1000) { // Convert TIME_STEP to milliseconds
            world.Step(TIME_STEP, VELOCITY_ITERATIONS, POSITION_ITERATIONS);
            lag -= TIME_STEP * 1000;
        }

        // Rendering
        SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
        SDL_RenderClear(renderer);

        // Draw ground (white)
        SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
        SDL_Rect groundRect = {
            static_cast<int>(groundBody->GetPosition().x * SCALE - (SCREEN_WIDTH / 2)),
