```cpp
#pragma once
#include <vector>
#include <glm/glm.hpp>

struct RigidBody {
    glm::vec2 position;
    glm::vec2 velocity;
    float angle;        // Rotation in radians
    float angularVel;   // Angular velocity (rad/s)
    float mass;
    float invMass;      // Inverse mass for efficiency
    float radius;
    glm::vec3 color;

    RigidBody(glm::vec2 pos, float r, float m, glm::vec3 col)
        : position(pos), velocity(0.0f), angle(0.0f), angularVel(0.0f),
          radius(r), mass(m), color(col) {
        invMass = (m > 0.0f) ? 1.0f / m : 0.0f;
    }
};

class PhysicsWorld {
public:
    PhysicsWorld() : gravity(0.0f, -9.81f) {}

    void addBody(const RigidBody& body) {
        bodies.push_back(body);
    }

    void update(float dt) {
        // Apply gravity
        for (auto& body : bodies) {
            if (body.invMass > 0.0f) {
                body.velocity += gravity * dt;
            }
        }

        // Simple collision detection/resolution (circle-circle)
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                RigidBody& a = bodies[i];
                RigidBody& b = bodies[j];

                glm::vec2 delta = b.position - a.position;
                float distSq = glm::dot(delta, delta);
                float minDist = a.radius + b.radius;

                if (distSq < minDist * minDist) {
                    // Collision detected
                    float dist = glm::sqrt(distSq);
                    glm::vec2 normal = delta / dist;
                    float penetration = minDist - dist;

                    // Impulse-based collision response
                    glm::vec2 relVel = b.velocity - a.velocity;
                    float velAlongNormal = glm::dot(relVel, normal);

                    // Don't resolve if objects are moving apart
                    if (velAlongNormal > 0) continue;

                    // Coefficient of restitution (bounciness)
                    float e = 0.8f;
                    float j = -(1 + e) * velAlongNormal;
                    j /= (a.invMass + b.invMass);

                    glm::vec2 impulse = j * normal;
                    a.velocity -= impulse * a.invMass;
                    b.velocity += impulse * b.invMass;

                    // Positional correction (avoid sinking)
                    const float percent = 0.2f; // Penetration correction factor
                    glm::vec2 correction = normal * (penetration * percent);
                    a.position -= correction * a.invMass;
                    b.position += correction * b.invMass;
                }
            }
        }

        // Update positions (semi-implicit Euler)
        for (auto& body : bodies) {
            if (body.invMass > 0.0f) {
                body.position += body.velocity * dt;
                body.angle += body.angularVel * dt;
            }
        }
    }

    const std::vector<RigidBody>& getBodies() const { return bodies; }

private:
    std::vector<RigidBody> bodies;
    glm::vec2 gravity;
};
```

