#### **`main.cpp` – Simulation Loop**
```cpp
#include "physics.h"
#include "renderer.h"
#include <glm/gtc/matrix_transform.hpp>
#include <iostream>

int main() {
    const int width = 800;
    const int height = 600;
    const float fixedTimeStep = 1.0f / 60.0f; // 60 Hz physics
    const float maxFrameTime = 0.25f; // Prevent spiral of death

    try {
        Renderer renderer(width, height);
        PhysicsWorld world;

        // Add some bodies
        world.addBody(RigidBody(glm::vec2(0.0f, -10.0f), 100.0f, 0.0f, glm::vec3(0.5f, 0.5f, 0.5f))); // Ground
        for (int i = 0; i < 10; ++i) {
            float x = (i % 5) * 1.5f - 3.0f;
            float y = 5.0f + (i / 5) * 1.5f;
            world.addBody(RigidBody(glm::vec2(x, y), 0.5f, 1.0f, glm::vec3(1.0f, 0.0f, 0.0f)));
        }

        // Simulation loop
        float lastTime = SDL_GetTicks() / 1000.0f;
        float accumulator = 0.0f;

        while (!renderer.shouldClose()) {
            float currentTime = SDL_GetTicks() / 1000.0f;
            float frameTime = currentTime - lastTime;
            lastTime = currentTime;

            // Cap frame time to avoid spiral of death
            if (frameTime > maxFrameTime) frameTime = maxFrameTime;

            // Accumulate time for fixed timestep
            accumulator += frameTime;

            // Update physics at fixed timestep
            while (accumulator >= fixedTimeStep) {
                world.update(fixedTimeStep);
                accumulator -= fixedTimeStep;
            }

            // Render
            renderer.render(world);

            // Optional: Cap rendering to 60 FPS (uncomment for strict 60 FPS)
            // SDL_Delay(16); // ~60 FPS
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
