struct RigidBody {
    Vec2 position;
    Vec2 velocity;
    float orientation; // angle in radians
    float angularVelocity;
    float mass;
    float invMass; // 1/mass, 0 for static objects
    Vec2 forceAccum;
    float torqueAccum;

    RigidBody(Vec2 pos, float mass) : position(pos), mass(mass), invMass(mass > 0 ? 1.0f/mass : 0) {
        velocity = Vec2(0, 0);
        orientation = 0;
        angularVelocity = 0;
        forceAccum = Vec2(0, 0);
        torqueAccum = 0;
    }

    void addForce(Vec2 force) {
        forceAccum = forceAccum + force;
    }

    void addTorque(float torque) {
        torqueAccum += torque;
    }

    void integrate(float dt) {
        if (invMass == 0) return; // static object

        // Linear motion
        Vec2 acceleration = forceAccum * invMass;
        velocity = velocity + acceleration * dt;
        position = position + velocity * dt;

        // Angular motion
        float angularAcceleration = torqueAccum * invMass;
        angularVelocity += angularAcceleration * dt;
        orientation += angularVelocity * dt;

        // Clear accumulators
        forceAccum = Vec2(0, 0);
        torqueAccum = 0;
    }
};
