            Vec2 normal = delta.normalized();
            float relativeVelocity = (b.velocity - a.velocity).dot(normal);
            if (relativeVelocity < 0) { // Moving toward each other
                float restitution = 0.5f; // bounciness
                float impulse = -(1 + restitution) * relativeVelocity;
                impulse /= (a.invMass + b.invMass);

                Vec2 impulseVec = normal * impulse;
                a.velocity = a.velocity - impulseVec * a.invMass;
                b.velocity = b.velocity + impulseVec * b.invMass;
            }

            // Separate bodies to prevent sticking
            float overlap = threshold - distance;
            Vec2 separation = normal * overlap * 0.5f;
            a.position = a.position - separation;
            b.position = b.position + separation;
        }
    }
};
