#include <SDL2/SDL.h>
#include <Box2D/Box2D.h>
#include <iostream>

// Screen dimensions
const int SCREEN_WIDTH = 800;
const int SCREEN_HEIGHT = 600;

// Physics world settings
const float WORLD_SCALE = 100.0f; // Box2D uses meters, so we scale up for pixels
const float TIME_STEP = 1.0f / 60.0f;
const int VELOCITY_ITERATIONS = 8;
const int POSITION_ITERATIONS = 3;

// Convert Box2D coordinates to screen coordinates
b2Vec2 to_screen(const b2Vec2& vec) {
    return b2Vec2(vec.x * WORLD_SCALE, SCREEN_HEIGHT - vec.y * WORLD_SCALE);
}

int main(int argc, char* argv[]) {
    // Initialize SDL
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        std::cerr << "SDL could not initialize! SDL_Error: " << SDL_GetError() << std::endl;
        return 1;
    }

    // Create window
    SDL_Window* window = SDL_CreateWindow("Real-time Physics Simulation",
                                          SDL_WINDOWPOS_UNDEFINED,
                                          SDL_WINDOWPOS_UNDEFINED,
                                          SCREEN_WIDTH, SCREEN_HEIGHT,
                                          SDL_WINDOW_SHOWN);
    if (!window) {
        std::cerr << "Window could not be created! SDL_Error: " << SDL_GetError() << std::endl;
        SDL_Quit();
        return 1;
    }

    // Create renderer
    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (!renderer) {
        std::cerr << "Renderer could not be created! SDL_Error: " << SDL_GetError() << std::endl;
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 1;
    }

    // Initialize Box2D world with gravity
    b2Vec2 gravity(0.0f, -10.0f);
    b2World world(gravity);

    // Create ground body
    b2BodyDef groundBodyDef;
    groundBodyDef.position.Set(0.0f, 0.0f);
    b2Body* groundBody = world.CreateBody(&groundBodyDef);
    b2PolygonShape groundBox;
    groundBox.SetAsBox(50.0f, 1.0f);
    groundBody->CreateFixture(&groundBox, 0.0f);

    // Create dynamic body (a box)
    b2BodyDef bodyDef;
    bodyDef.type = b2_dynamicBody;
    bodyDef.position.Set(0.0f, 40.0f);
    b2Body* body = world.CreateBody(&bodyDef);
    b2PolygonShape dynamicBox;
    dynamicBox.SetAsBox(1.0f, 1.0f);
    b2FixtureDef fixtureDef;
    fixtureDef.shape = &dynamicBox;
    fixtureDef.density = 1.0f;
    fixtureDef.friction = 0.3f;
    body->CreateFixture(&fixtureDef);

    // Main loop flag
    bool quit = false;
    SDL_Event e;

    // For frame rate control
    Uint32 frameStart;
    int frameTime;

    // Main loop
    while (!quit) {
        frameStart = SDL_GetTicks();

        // Handle events
        while (SDL_PollEvent(&e) != 0) {
            if (e.type == SDL_QUIT) {
                quit = true;
            }
        }

        // Update physics
        world.Step(TIME_STEP, VELOCITY_ITERATIONS, POSITION_ITERATIONS);

        // Clear screen
        SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
        SDL_RenderClear(renderer);

        // Draw ground
        SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
        b2Vec2 groundStart = to_screen(groundBody->GetPosition() - b2Vec2(50.0f, 0.0f));
        b2Vec2 groundEnd = to_screen(groundBody->GetPosition() + b2Vec2(50.0f, 0.0f));
        SDL_RenderDrawLine(renderer, groundStart.x, groundStart.y, groundEnd.x, groundEnd.y);

        // Draw dynamic body
        SDL_SetRenderDrawColor(renderer, 255, 0, 0, 255);
        b2Vec2 bodyPos = to_screen(body->GetPosition());
        SDL_Rect rect;
        rect.x = bodyPos.x - 10; // Half of the box size in pixels (since WORLD_SCALE is 100)
        rect.y = bodyPos.y - 10;
        rect.w = 20;
        rect.h = 20;
        SDL_RenderFillRect(renderer, &rect);

        // Update screen
        SDL_RenderPresent(renderer);

        // Frame rate control
        frameTime = SDL_GetTicks() - frameStart;
        if (frameTime < 16) { // 16ms for ~60 FPS
            SDL_Delay(16 - frameTime);
        }
    }

    // Cleanup
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}
