const int SCREEN_WIDTH = 800;
const int SCREEN_HEIGHT = 600;
const float SCALE = 30.0f; // Scale for Box2D to pixels
const float TIME_STEP = 1.0f / 60.0f; // 60 Hz physics update
const int VELOCITY_ITERATIONS = 6;
const int POSITION_ITERATIONS = 2;

int main(int argc, char* argv[]) {
    // Initialize SDL
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        std::cerr << "SDL could not initialize! SDL_Error: " << SDL_GetError() << std::endl;
        return 1;
    }

    SDL_Window* window = SDL_CreateWindow("Physics Simulation", SDL_WINDOWPOS_UNDEFINED, SDL_WINDOWPOS_UNDEFINED, SCREEN_WIDTH, SCREEN_HEIGHT, SDL_WINDOW_SHOWN);
    if (!window) {
