    private final PaymentNotificationService notificationService;

    @Transactional
    public PaymentResponse processPayment(PaymentRequest request) {
        // 1. Validate request
        validatePaymentRequest(request);

        // 2. Check for fraud
        if (fraudDetectionService.isSuspicious(request)) {
            return createResponse(null, PaymentStatus.DECLINED, "Payment flagged as suspicious");
        }

        // 3. Check account balances (simplified)
        if (!accountService.hasSufficientFunds(request.getSenderAccount(), request.getAmount())) {
            return createResponse(null, PaymentStatus.DECLINED, "Insufficient funds");
        }

        // 4. Create and save payment record
