        payment.setSenderAccount(request.getSenderAccount());
        payment.setReceiverAccount(request.getReceiverAccount());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setPaymentMethod(request.getPaymentMethod());
        payment.setStatus(PaymentStatus.PROCESSING);
        payment.setDescription(request.getDescription());

        Payment savedPayment = paymentRepository.save(payment);

        try {
            // 5. Process the payment (would integrate with real payment gateways)
            processPaymentTransaction(savedPayment);

            // 6. Update status to completed
            savedPayment.setStatus(PaymentStatus.COMPLETED);
            paymentRepository.save(savedPayment);

            // 7. Send notifications
            notificationService.sendPaymentConfirmation(savedPayment);

            return createResponse(savedPayment.getPaymentReference(), PaymentStatus.COMPLETED, "Payment processed successfully");
        } catch (PaymentProcessingException e) {
            // 8. Handle failure
            savedPayment.setStatus(PaymentStatus.FAILED);
            paymentRepository.save(savedPayment);
            return createResponse(savedPayment.getPaymentReference(), PaymentStatus.FAILED, e.getMessage());
        }
    }

    @Transactional(readOnly = true)
    public PaymentResponse getPaymentStatus(String paymentReference) {
        return paymentRepository.findByPaymentReference(paymentReference)
                .map(payment -> createResponse(
                        payment.getPaymentReference(),
                        payment.getStatus(),
                        "Payment status retrieved"
                ))
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found"));
    }

    @Transactional
    public PaymentResponse reversePayment(String paymentReference) {
        Payment payment = paymentRepository.findByPaymentReference(paymentReference)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found"));

        if (payment.getStatus() != PaymentStatus.COMPLETED) {
            throw new InvalidPaymentStateException("Only completed payments can be reversed");
