import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.security.SecureRandom;
import java.time.Instant;

/**
 * Simplified Payment Processing Service for a financial institution.
 * This is a conceptual example and not production-ready.
 */
public class PaymentProcessingService {

    // In-memory storage for transactions (in reality, use a database)
    private final Map<String, Transaction> transactionStore = new ConcurrentHashMap<>();

    // Fraud detection thresholds
    private static final double HIGH_AMOUNT_THRESHOLD = 10000.00; // $10,000
    private static final double HIGH_FREQUENCY_THRESHOLD = 5; // transactions per minute

    // Secure random for generating transaction IDs
    private final SecureRandom secureRandom = new SecureRandom();

    /**
     * Process a payment transaction.
     * @param request Payment request containing transaction details
     * @return Transaction result with status and details
     */
    public TransactionResult processPayment(PaymentRequest request) {
        // 1. Validate the request
        ValidationResult validation = validateRequest(request);
        if (!validation.isValid()) {
            return new TransactionResult(TransactionStatus.FAILED, validation.getErrorMessage());
        }

        // 2. Check for fraud
        FraudCheckResult fraudCheck = checkForFraud(request);
        if (fraudCheck.isFraudulent()) {
            return new TransactionResult(TransactionStatus.FRAUD_DETECTED,
                                      "Transaction flagged for potential fraud: " + fraudCheck.getReason());
        }

        // 3. Generate transaction ID and timestamp
        String transactionId = generateTransactionId();
        Instant timestamp = Instant.now();

        // 4. Create and store the transaction (in reality, this would involve a database transaction)
        Transaction transaction = new Transaction(
            transactionId,
            request.getAccountId(),
            request.getAmount(),
            request.getCurrency(),
            request.getMerchantId(),
            timestamp,
            TransactionStatus.PROCESSING
        );

        transactionStore.put(transactionId, transaction);

        // 5. Simulate processing delay (in reality, this would be async)
        try {
            Thread.sleep(100); // Simulate processing time
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return new TransactionResult(TransactionStatus.FAILED, "Processing interrupted");
        }

        // 6. Update transaction status
        transaction.setStatus(TransactionStatus.COMPLETED);
        transactionStore.put(transactionId, transaction);

        // 7. Return success result
        return new TransactionResult(
            TransactionStatus.COMPLETED,
            "Payment processed successfully",
            transactionId,
            request.getAmount()
        );
    }

    /**
     * Validate payment request.
     */
    private ValidationResult validateRequest(PaymentRequest request) {
        if (request == null) {
            return new ValidationResult(false, "Payment request cannot be null");
        }
        if (request.getAccountId() == null || request.getAccountId().isEmpty()) {
            return new ValidationResult(false, "Account ID is required");
        }
        if (request.getAmount() <= 0) {
            return new ValidationResult(false, "Amount must be positive");
        }
        if (request.getCurrency() == null || request.getCurrency().isEmpty()) {
            return new ValidationResult(false, "Currency is required");
        }
        if (request.getMerchantId() == null || request.getMerchantId().isEmpty()) {
            return new ValidationResult(false, "Merchant ID is required");
        }
        return new ValidationResult(true, null);
    }

    /**
     * Basic fraud detection checks.
     */
    private FraudCheckResult checkForFraud(PaymentRequest request) {
        // Check for unusually large amounts
        if (request.getAmount() > HIGH_AMOUNT_THRESHOLD) {
            return new FraudCheckResult(true, "Large transaction amount");
        }

        // In a real system, we would check against historical patterns
        // For this example, we'll just simulate a simple frequency check
        int recentTransactions = countRecentTransactions(request.getAccountId());
        if (recentTransactions >= HIGH_FREQUENCY_THRESHOLD) {
            return new FraudCheckResult(true, "High transaction frequency");
        }

        return new FraudCheckResult(false, null);
    }

    /**
     * Count transactions for an account in the last minute (simplified).
     */
    private int countRecentTransactions(String accountId) {
        Instant oneMinuteAgo = Instant.now().minusSeconds(60);
        return (int) transactionStore.values().stream()
            .filter(t -> t.getAccountId().equals(accountId))
            .filter(t -> t.getTimestamp().isAfter(oneMinuteAgo))
            .count();
    }

    /**
     * Generate a secure random transaction ID.
     */
    private String generateTransactionId() {
        return "TXN-" + secureRandom.nextLong(1_000_000_000_000L);
    }

    // ========== Supporting Classes ==========

    public static class PaymentRequest {
        private final String accountId;
        private final double amount;
        private final String currency;
        private final String merchantId;
        private final String cardNumber; // In reality, this would be tokenized
        private final String cvv;
        private final String expiryDate;

        public PaymentRequest(String accountId, double amount, String currency,
                            String merchantId, String cardNumber, String cvv, String expiryDate) {
            this.accountId = accountId;
            this.amount = amount;
            this.currency = currency;
            this.merchantId = merchantId;
            this.cardNumber = cardNumber;
            this.cvv = cvv;
            this.expiryDate = expiryDate;
        }

        // Getters
        public String getAccountId() { return accountId; }
        public double getAmount() { return amount; }
        public String getCurrency() { return currency; }
        public String getMerchantId() { return merchantId; }
        public String getCardNumber() { return cardNumber; }
        public String getCvv() { return cvv; }
        public String getExpiryDate() { return expiryDate; }
    }

    public static class TransactionResult {
        private final TransactionStatus status;
        private final String message;
        private final String transactionId;
        private final double amount;

        public TransactionResult(TransactionStatus status, String message) {
            this(status, message, null, 0.0);
        }

        public TransactionResult(TransactionStatus status, String message,
                               String transactionId, double amount) {
            this.status = status;
            this.message = message;
            this.transactionId = transactionId;
            this.amount = amount;
        }

        // Getters
        public TransactionStatus getStatus() { return status; }
        public String getMessage() { return message; }
        public String getTransactionId() { return transactionId; }
        public double getAmount() { return amount; }
    }

    public static class Transaction {
        private final String transactionId;
        private final String accountId;
        private final double amount;
        private final String currency;
        private final String merchantId;
        private final Instant timestamp;
        private TransactionStatus status;

        public Transaction(String transactionId, String accountId, double amount,
                         String currency, String merchantId, Instant timestamp,
                         TransactionStatus status) {
            this.transactionId = transactionId;
            this.accountId = accountId;
            this.amount = amount;
            this.currency = currency;
            this.merchantId = merchantId;
            this.timestamp = timestamp;
            this.status = status;
        }

        // Getters and setters
        public String getTransactionId() { return transactionId; }
        public String getAccountId() { return accountId; }
        public double getAmount() { return amount; }
        public String getCurrency() { return currency; }
        public String getMerchantId() { return merchantId; }
        public Instant getTimestamp() { return timestamp; }
        public TransactionStatus getStatus() { return status; }
        public void setStatus(TransactionStatus status) { this.status = status; }
    }

    public enum TransactionStatus {
        PROCESSING,
        COMPLETED,
        FAILED,
        FRAUD_DETECTED
    }

    private static class ValidationResult {
        private final boolean valid;
        private final String errorMessage;

        public ValidationResult(boolean valid, String errorMessage) {
            this.valid = valid;
            this.errorMessage = errorMessage;
        }

        public boolean isValid() { return valid; }
        public String getErrorMessage() { return errorMessage; }
    }

    private static class FraudCheckResult {
        private final boolean isFraudulent;
        private final String reason;

        public FraudCheckResult(boolean isFraudulent, String reason) {
            this.isFraudulent = isFraudulent;
            this.reason = reason;
        }

        public boolean isFraudulent() { return isFraudulent; }
        public String getReason() { return reason; }
    }

    // ========== Example Usage ==========
    public static void main(String[] args) {
        PaymentProcessingService service = new PaymentProcessingService();

        // Example payment request
        PaymentRequest request = new PaymentRequest(
            "ACC-123456",
            150.50,
            "USD",
            "MERCH-789",
            "4111111111111111", // Example card number
            "123",
            "12/25"
        );

        // Process the payment
        TransactionResult result = service.processPayment(request);

        // Output the result
        System.out.println("Payment Status: " + result.getStatus());
        System.out.println("Message: " + result.getMessage());
        if (result.getTransactionId() != null) {
            System.out.println("Transaction ID: " + result.getTransactionId());
        }
    }
}
