### 1.7 Payment Service
```java
package com.example.payment.service;

import com.example.payment.dto.PaymentRequest;
import com.example.payment.dto.PaymentResponse;
import com.example.payment.exception.InsufficientFundsException;
import com.example.payment.exception.InvalidPaymentException;
import com.example.payment.exception.PaymentProcessingException;
import com.example.payment.model.Payment;
import com.example.payment.model.PaymentStatus;
import com.example.payment.repository.PaymentRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.UUID;

@Service
public class PaymentService {
    private final PaymentRepository paymentRepository;
    private final FraudDetectionService fraudDetectionService;
    private final AccountService accountService; // Assume this exists

    @Autowired
    public PaymentService(PaymentRepository paymentRepository,
                         FraudDetectionService fraudDetectionService,
                         AccountService accountService) {
        this.paymentRepository = paymentRepository;
        this.fraudDetectionService = fraudDetectionService;
        this.accountService = accountService;
    }

    @Transactional
    public PaymentResponse processPayment(PaymentRequest request) {
        // Validate payment request
        validatePaymentRequest(request);

        // Check for fraud
        if (fraudDetectionService.isFraudulent(request)) {
            throw new InvalidPaymentException("Payment flagged as potentially fraudulent");
        }

        // Check account balances
        if (!hasSufficientFunds(request)) {
            throw new InsufficientFundsException("Insufficient funds in sender account");
        }

        // Create and save payment record
        Payment payment = new Payment();
        payment.setSenderAccountNumber(request.getSenderAccountNumber());
        payment.setReceiverAccountNumber(request.getReceiverAccountNumber());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setPaymentMethod(request.getPaymentMethod());
        payment.setDescription(request.getDescription());
        payment.setStatus(PaymentStatus.PROCESSING.name());
        payment.setReferenceNumber(generateReferenceNumber());
        payment.setCreatedAt(LocalDateTime.now());

        payment = paymentRepository.save(payment);

        // Process the payment (in a real system, this would be async)
        try {
            // Deduct from sender account
            accountService.debit(request.getSenderAccountNumber(), request.getAmount());

            // Credit receiver account (in a real system, this might be async)
            accountService.credit(request.getReceiverAccountNumber(), request.getAmount());

            // Update payment status
            payment.setStatus(PaymentStatus.COMPLETED.name());
            payment.setCompletedAt(LocalDateTime.now());
            paymentRepository.save(payment);

            return createPaymentResponse(payment);
        } catch (Exception e) {
            // If processing fails, reverse the transaction if possible
            try {
                accountService.credit(request.getSenderAccountNumber(), request.getAmount());
            } catch (Exception ex) {
                // Log error but don't throw as we're already in an error state
            }
            payment.setStatus(PaymentStatus.FAILED.name());
            paymentRepository.save(payment);
            throw new PaymentProcessingException("Payment processing failed", e);
        }
    }

    private void validatePaymentRequest(PaymentRequest request) {
        if (request.getAmount() == null || request.getAmount().compareTo(BigDecimal.ZERO) <= 0) {
            throw new InvalidPaymentException("Amount must be positive");
        }

        if (request.getCurrency() == null || request.getCurrency().isEmpty()) {
            throw new InvalidPaymentException("Currency must be specified");
        }

        if (request.getSenderAccountNumber() == null || request.getSenderAccountNumber().isEmpty()) {
            throw new InvalidPaymentException("Sender account number is required");
        }

        if (request.getReceiverAccountNumber() == null || request.getReceiverAccountNumber().isEmpty()) {
            throw new InvalidPaymentException("Receiver account number is required");
        }

        if (request.getPaymentMethod() == null || request.getPaymentMethod().isEmpty()) {
            throw new InvalidPaymentException("Payment method is required");
        }
    }

    private boolean hasSufficientFunds(PaymentRequest request) {
        // In a real system, this would check the actual account balance
        // For this example, we'll assume sufficient funds
        return true;
    }

    private String generateReferenceNumber() {
        return "PAY-" + UUID.randomUUID().toString().replace("-", "").substring(0, 12);
    }

    private PaymentResponse createPaymentResponse(Payment payment) {
        PaymentResponse response = new PaymentResponse();
        response.setPaymentId(payment.getId());
        response.setStatus(payment.getStatus());
        response.setReferenceNumber(payment.getReferenceNumber());
        response.setCreatedAt(payment.getCreatedAt());
        return response;
    }

    public PaymentResponse getPaymentStatus(String referenceNumber) {
        Payment payment = paymentRepository.findByReferenceNumber(referenceNumber);
        if (payment == null) {
            throw new InvalidPaymentException("Payment not found with reference: " + referenceNumber);
        }
        return createPaymentResponse(payment);
    }
}
