package main

import (
	"log"
	"payment-service/internal/config"
	"payment-service/internal/controller"
	"payment-service/internal/repository"
	"payment-service/internal/service"

	"github.com/gin-gonic/gin"
	"gorm.io/driver/postgres"
	"gorm.io/gorm"
)

func main() {
	// Load configuration
	cfg, err := config.LoadConfig()
	if err != nil {
		log.Fatalf("Error loading config: %v", err)
	}

	// Initialize database
	dsn := cfg.DatabaseURL
	db, err := gorm.Open(postgres.Open(dsn), &gorm.Config{})
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}

	// Auto migrate models
	err = db.AutoMigrate(&model.Payment{})
	if err != nil {
		log.Fatalf("Failed to migrate database: %v", err)
	}

	// Initialize repositories
	paymentRepo := repository.NewPaymentRepository(db)

	// Initialize services
	fraudService := service.NewFraudDetectionService()
	accountService := service.NewAccountService() // Assume this exists
	paymentService := service.NewPaymentService(paymentRepo, fraudService, accountService)

	// Initialize controller
	paymentController := controller.NewPaymentController(paymentService)

	// Set up Gin router
	router := gin.Default()

	// API routes
	api := router.Group("/api")
	{
		payments := api.Group("/payments")
		{
			payments.POST("", paymentController.ProcessPayment)
			payments.GET("/:referenceNumber", paymentController.GetPaymentStatus)
		}
	}

	// Start server
	log.Printf("Server running on port %s", cfg.ServerPort)
	if err := router.Run(":" + cfg.ServerPort); err != nil {
		log.Fatalf("Failed to start server: %v", err)
	}
}
