### 2.7 Payment Service
```go
package service

import (
	"errors"
	"time"

	"payment-service/internal/dto"
	"payment-service/internal/model"
	"payment-service/internal/repository"
)

type PaymentService interface {
	ProcessPayment(request *dto.PaymentRequest) (*dto.PaymentResponse, error)
	GetPaymentStatus(referenceNumber string) (*dto.PaymentResponse, error)
}

type paymentService struct {
	repo              repository.PaymentRepository
	fraudService      FraudDetectionService
	accountService    AccountService
}

func NewPaymentService(
	repo repository.PaymentRepository,
	fraudService FraudDetectionService,
	accountService AccountService,
) PaymentService {
	return &paymentService{
		repo:           repo,
		fraudService:   fraudService,
		accountService: accountService,
	}
}

func (s *paymentService) ProcessPayment(request *dto.PaymentRequest) (*dto.PaymentResponse, error) {
	// Validate payment request
	if err := s.validatePaymentRequest(request); err != nil {
		return nil, err
	}

	// Check for fraud
	if s.fraudService.IsFraudulent(request) {
		return nil, errors.New("payment flagged as potentially fraudulent")
	}

	// Check account balances
	if !s.hasSufficientFunds(request) {
		return nil, errors.New("insufficient funds in sender account")
	}

	// Create payment record
	payment := &model.Payment{
		SenderAccountNumber:   request.SenderAccountNumber,
		ReceiverAccountNumber: request.ReceiverAccountNumber,
		Amount:               request.Amount,
		Currency:             request.Currency,
		PaymentMethod:        request.PaymentMethod,
		Status:               string(model.Pending),
		ReferenceNumber:      s.generateReferenceNumber(),
		Description:          request.Description,
	}

	if err := s.repo.Create(payment); err != nil {
		return nil, errors.New("failed to create payment record")
	}

	// Process the payment
	if err := s.processPayment(payment); err != nil {
		// If processing fails, try to reverse the transaction
		if reverseErr := s.accountService.Credit(request.SenderAccountNumber, request.Amount); reverseErr != nil {
			// Log error but don't return it as we're already in an error state
		}
		payment.Status = string(model.Failed)
		s.repo.Update(payment)
		return nil, errors.New("payment processing failed: " + err.Error())
	}

	// Update payment status to completed
	payment.Status = string(model.Completed)
	payment.CompletedAt = &time.Time{}
	s.repo.Update(payment)

	return s.createPaymentResponse(payment), nil
}

func (s *paymentService) validatePaymentRequest(request *dto.PaymentRequest) error {
	if request.Amount <= 0 {
		return errors.New("amount must be positive")
	}

	if request.Currency == "" {
		return errors.New("currency must be specified")
	}

	if request.SenderAccountNumber == "" {
		return errors.New("sender account number is required")
	}

	if request.ReceiverAccountNumber == "" {
		return errors.New("receiver account number is required")
	}

	if request.PaymentMethod == "" {
		return errors.New("payment method is required")
	}

	return nil
}

func (s *paymentService) hasSufficientFunds(request *dto.PaymentRequest) bool {
	// In a real system, this would check the actual account balance
	// For this example, we'll assume sufficient funds
	return true
}

func (s *paymentService) generateReferenceNumber() string {
	// In a real system, this would generate a unique reference number
	return "PAY-" + time.Now().Format("20060102150405")
}

func (s *paymentService) processPayment(payment *model.Payment) error {
	// Deduct from sender account
	if err := s.accountService.Debit(payment.SenderAccountNumber, payment.Amount); err != nil {
		return err
	}

	// Credit receiver account
	if err := s.accountService.Credit(payment.ReceiverAccountNumber, payment.Amount); err != nil {
		return err
	}

	return nil
}

func (s *paymentService) createPaymentResponse(payment *model.Payment) *dto.PaymentResponse {
	return &dto.PaymentResponse{
		PaymentID:       payment.ID,
		Status:          payment.Status,
		ReferenceNumber: payment.ReferenceNumber,
		CreatedAt:       payment.CreatedAt,
	}
}

func (s *paymentService) GetPaymentStatus(referenceNumber string) (*dto.PaymentResponse, error) {
	payment, err := s.repo.FindByReferenceNumber(referenceNumber)
	if err != nil {
		return nil, errors.New("payment not found")
	}

	return s.createPaymentResponse(payment), nil
}
