func (c *PaymentController) ProcessPayment(ctx *gin.Context) {
	var request dto.PaymentRequest
	if err := ctx.ShouldBindJSON(&request); err != nil {
		ctx.JSON(http.StatusBadRequest, gin.H{
			"status":  http.StatusBadRequest,
			"message": "Invalid request: " + err.Error(),
			"time":    time.Now().Format(time.RFC3339),
		})
		return
	}

	response, err := c.paymentService.ProcessPayment(&request)
	if err != nil {
		ctx.JSON(http.StatusBadRequest, gin.H{
			"status":  http.StatusBadRequest,
			"message": err.Error(),
			"time":    time.Now().Format(time.RFC3339),
		})
		return
	}

	ctx.JSON(http.StatusCreated, response)
}

func (c *PaymentController) GetPaymentStatus(ctx *gin.Context) {
	referenceNumber := ctx.Param("referenceNumber")

	response, err := c.paymentService.GetPaymentStatus(referenceNumber)
	if err != nil {
		ctx.JSON(http.StatusNotFound, gin.H{
			"status":  http.StatusNotFound,
			"message": err.Error(),
			"time":    time.Now().Format(time.RFC3339),
		})
		return
	}

	ctx.JSON(http.StatusOK, response)
}
