package com.example.payment.service;

import com.example.payment.dto.PaymentRequest;
import com.example.payment.dto.PaymentResponse;
import com.example.payment.exception.PaymentException;
import com.example.payment.model.Payment;
import com.example.payment.repository.PaymentRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.UUID;

@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final FraudDetectionService fraudDetectionService;
    private final ComplianceService complianceService;

    public PaymentService(
            PaymentRepository paymentRepository,
            FraudDetectionService fraudDetectionService,
            ComplianceService complianceService) {
        this.paymentRepository = paymentRepository;
        this.fraudDetectionService = fraudDetectionService;
        this.complianceService = complianceService;
    }

    @Transactional
    public PaymentResponse processPayment(PaymentRequest request) throws PaymentException {
        // 1. Validate input
        validatePaymentRequest(request);

        // 2. Check for fraud
        if (fraudDetectionService.isFraudulent(request)) {
            throw new PaymentException("Transaction flagged as fraudulent");
        }

        // 3. Check compliance (AML, KYC, etc.)
        if (!complianceService.isCompliant(request)) {
            throw new PaymentException("Transaction violates compliance rules");
        }

        // 4. Create and save payment record
        Payment payment = new Payment();
        payment.setTransactionId(UUID.randomUUID().toString());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setSourceAccount(request.getSourceAccount());
        payment.setDestinationAccount(request.getDestinationAccount());
        payment.setStatus("PROCESSING");
        payment.setCreatedAt(LocalDateTime.now());

        paymentRepository.save(payment);

        // 5. In a real system, we'd call the payment gateway here
        // For this example, we'll simulate success
        payment.setStatus("COMPLETED");
        paymentRepository.save(payment);

        return new PaymentResponse(
                payment.getTransactionId(),
                payment.getStatus(),
                "Payment processed successfully"
        );
    }

    public PaymentResponse getPaymentStatus(String transactionId) throws PaymentException {
        return paymentRepository.findById(transactionId)
                .map(payment -> new PaymentResponse(
                        payment.getTransactionId(),
                        payment.getStatus(),
                        "Payment retrieved successfully"
                ))
                .orElseThrow(() -> new PaymentException("Payment not found"));
    }

    private void validatePaymentRequest(PaymentRequest request) throws PaymentException {
        if (request.getAmount().compareTo(BigDecimal.ZERO) <= 0) {
            throw new PaymentException("Amount must be positive");
        }
        if (!request.getCurrency().matches("[A-Z]{3}")) {
            throw new PaymentException("Invalid currency format");
        }
        // Add more validations as needed
    }
