#### **PaymentService.java**
```java
package com.example.payment.service;

import com.example.payment.model.Account;
import com.example.payment.model.Transaction;
import com.example.payment.repository.TransactionRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.UUID;

@Service
public class PaymentService {
    private final AccountService accountService;
    private final TransactionRepository transactionRepository;

    public PaymentService(AccountService accountService, TransactionRepository transactionRepository) {
        this.accountService = accountService;
        this.transactionRepository = transactionRepository;
    }

    @Transactional
    public Transaction processPayment(String senderAccountNumber, String receiverAccountNumber,
                                    BigDecimal amount, String currency) {
        // Validate sender and receiver accounts
        Account sender = accountService.getAccountByNumber(senderAccountNumber)
                .orElseThrow(() -> new RuntimeException("Sender account not found"));
        Account receiver = accountService.getAccountByNumber(receiverAccountNumber)
                .orElseThrow(() -> new RuntimeException("Receiver account not found"));

        // Check sufficient balance
        if (sender.getBalance().compareTo(amount) < 0) {
            throw new RuntimeException("Insufficient funds");
        }

        // Deduct from sender and credit to receiver
        BigDecimal newSenderBalance = sender.getBalance().subtract(amount);
        BigDecimal newReceiverBalance = receiver.getBalance().add(amount);

        accountService.updateAccountBalance(senderAccountNumber, newSenderBalance);
        accountService.updateAccountBalance(receiverAccountNumber, newReceiverBalance);

        // Record transaction
        Transaction transaction = new Transaction();
        transaction.setSenderAccountNumber(senderAccountNumber);
        transaction.setReceiverAccountNumber(receiverAccountNumber);
        transaction.setAmount(amount);
        transaction.setCurrency(currency);
        transaction.setTimestamp(LocalDateTime.now());
        transaction.setStatus(Transaction.TransactionStatus.COMPLETED);

        return transactionRepository.save(transaction);
    }
}
```

