### 4. Payment Service (`service/PaymentService.java`)

```java
package com.financial.payment.service;

import com.financial.payment.dto.PaymentRequest;
import com.financial.payment.dto.PaymentResponse;
import com.financial.payment.exception.InsufficientFundsException;
import com.financial.payment.exception.InvalidPaymentException;
import com.financial.payment.exception.PaymentNotFoundException;
import com.financial.payment.model.Payment;
import com.financial.payment.model.PaymentStatus;
import com.financial.payment.repository.PaymentRepository;
import com.financial.payment.util.PaymentValidator;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.UUID;

@Service
public class PaymentService {
    private final PaymentRepository paymentRepository;
    private final FraudDetectionService fraudDetectionService;
    private final PaymentGatewayAdapter paymentGatewayAdapter;
    private final UserService userService;

    public PaymentService(PaymentRepository paymentRepository,
                         FraudDetectionService fraudDetectionService,
                         PaymentGatewayAdapter paymentGatewayAdapter,
                         UserService userService) {
        this.paymentRepository = paymentRepository;
        this.fraudDetectionService = fraudDetectionService;
        this.paymentGatewayAdapter = paymentGatewayAdapter;
        this.userService = userService;
    }

    @Transactional
    public PaymentResponse processPayment(PaymentRequest request) {
        // Validate payment request
        PaymentValidator.validate(request);

        // Check sender has sufficient funds (simplified)
        if (!userService.hasSufficientFunds(request.getSenderAccountNumber(), request.getAmount())) {
            throw new InsufficientFundsException("Insufficient funds in sender account");
        }

        // Check for fraud
        if (fraudDetectionService.isFraudulent(request)) {
            throw new InvalidPaymentException("Payment flagged as fraudulent");
        }

        // Create payment record
        Payment payment = new Payment();
        payment.setPaymentReference(UUID.randomUUID().toString());
        payment.setSenderAccountNumber(request.getSenderAccountNumber());
        payment.setReceiverAccountNumber(request.getReceiverAccountNumber());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setPaymentMethod(request.getPaymentMethod());
        payment.setStatus(PaymentStatus.PENDING);

        // Save initial payment record
        payment = paymentRepository.save(payment);

        try {
            // Process payment with external gateway
            String transactionId = paymentGatewayAdapter.processPayment(request);

            // Update payment status
            payment.setStatus(PaymentStatus.COMPLETED);
            payment.setTransactionId(transactionId);
            paymentRepository.save(payment);

            return convertToResponse(payment);
        } catch (Exception e) {
            // Handle payment failure
            payment.setStatus(PaymentStatus.FAILED);
            paymentRepository.save(payment);
            throw new InvalidPaymentException("Payment processing failed: " + e.getMessage());
        }
    }

    public PaymentResponse getPayment(String paymentReference) {
        Payment payment = paymentRepository.findByPaymentReference(paymentReference)
                .orElseThrow(() -> new PaymentNotFoundException("Payment not found"));

        return convertToResponse(payment);
    }

    private PaymentResponse convertToResponse(Payment payment) {
        PaymentResponse response = new PaymentResponse();
        response.setPaymentReference(payment.getPaymentReference());
        response.setStatus(payment.getStatus().name());
        response.setAmount(payment.getAmount());
        response.setCurrency(payment.getCurrency());
        response.setCreatedAt(payment.getCreatedAt());
        response.setTransactionId(payment.getTransactionId());
        return response;
    }
}
```

