```java
package com.example.payment.service;

import com.example.payment.model.Payment;
import com.example.payment.repository.PaymentRepository;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.util.Currency;
import java.util.Optional;

@Service
public class PaymentService {
    private final PaymentRepository paymentRepository;

    public PaymentService(PaymentRepository paymentRepository) {
        this.paymentRepository = paymentRepository;
    }

    public Payment processPayment(Payment payment) {
        // Basic validation
        if (payment.getAmount() == null || payment.getAmount().compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Amount must be positive");
        }

        try {
            Currency.getInstance(payment.getCurrency());
        } catch (IllegalArgumentException e) {
            throw new IllegalArgumentException("Invalid currency: " + payment.getCurrency());
        }

        // Fraud detection: simple check for high-value transactions
        if (payment.getAmount().compareTo(new BigDecimal("10000")) > 0) {
            payment.setStatus("FLAGGED_FOR_REVIEW");
        } else {
            payment.setStatus("COMPLETED");
        }

        return paymentRepository.save(payment);
