                    response.setPaymentId(payment.getPaymentId());
                    response.setStatus(payment.getStatus());
                    response.setTimestamp(payment.getTimestamp());
                    return ResponseEntity.ok(response);
                })
                .orElse(ResponseEntity.notFound().build());
    }
