### **2.4. Services**

#### **`PaymentService.java`** (Core transaction processing)
```java
package com.finance.payment.service;

import com.finance.payment.dto.PaymentRequest;
import com.finance.payment.dto.PaymentResponse;
import com.finance.payment.model.Account;
import com.finance.payment.model.Transaction;
import com.finance.payment.repository.AccountRepository;
import com.finance.payment.repository.TransactionRepository;
import com.finance.payment.util.EncryptionUtil;
import com.finance.payment.util.IdempotencyKeyUtil;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.UUID;

@Slf4j
@Service
@RequiredArgsConstructor
public class PaymentService {

    private final AccountRepository accountRepository;
    private final TransactionRepository transactionRepository;
    private final FraudDetectionService fraudDetectionService;

    @Transactional
    public PaymentResponse processPayment(PaymentRequest request) {
        // 1. Validate idempotency key (prevent duplicate transactions)
        if (transactionRepository.findByIdempotencyKey(request.getIdempotencyKey()).isPresent()) {
            log.warn("Duplicate transaction detected with idempotency key: {}", request.getIdempotencyKey());
            throw new IllegalArgumentException("Duplicate transaction detected");
        }

        // 2. Fetch accounts
        Account fromAccount = accountRepository.findByAccountNumber(request.getFromAccount())
                .orElseThrow(() -> new IllegalArgumentException("Source account not found"));
        Account toAccount = accountRepository.findByAccountNumber(request.getToAccount())
                .orElseThrow(() -> new IllegalArgumentException("Destination account not found"));

        // 3. Fraud detection
        if (fraudDetectionService.isFraudulent(request)) {
            log.warn("Fraud detected for transaction: {}", request.getTransactionId());
            return new PaymentResponse(
                    request.getTransactionId(),
                    "FAILED",
                    "Fraud detected"
            );
        }

        // 4. Validate balance
        if (fromAccount.getBalance().compareTo(request.getAmount()) < 0) {
            log.warn("Insufficient balance for account: {}", fromAccount.getAccountNumber());
            return new PaymentResponse(
                    request.getTransactionId(),
                    "FAILED",
                    "Insufficient balance"
            );
        }

        // 5. Process transaction
        BigDecimal newFromBalance = fromAccount.getBalance().subtract(request.getAmount());
        BigDecimal newToBalance = toAccount.getBalance().add(request.getAmount());

        fromAccount.setBalance(newFromBalance);
        toAccount.setBalance(newToBalance);

        // 6. Save transaction
        Transaction transaction = new Transaction();
        transaction.setTransactionId(request.getTransactionId());
        transaction.setFromAccountId(fromAccount.getAccountNumber());
        transaction.setToAccountId(toAccount.getAccountNumber());
        transaction.setAmount(request.getAmount());
        transaction.setCurrency(request.getCurrency());
        transaction.setStatus("COMPLETED");
        transaction.setTimestamp(LocalDateTime.now());
        transaction.setDescription(request.getDescription());
        transaction.setIdempotencyKey(request.getIdempotencyKey());

        transactionRepository.save(transaction);
        accountRepository.save(fromAccount);
        accountRepository.save(toAccount);

        log.info("Transaction completed: {}", request.getTransactionId());
        return new PaymentResponse(
                request.getTransactionId(),
                "COMPLETED",
                "Payment successful"
        );
    }
}
```

