### 4. Payment Service

```java
package com.example.payment.service;

import com.example.payment.dto.PaymentRequest;
import com.example.payment.dto.PaymentResponse;
import com.example.payment.exception.PaymentException;
import com.example.payment.model.Payment;
import com.example.payment.repository.PaymentRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.UUID;

@Slf4j
@Service
@RequiredArgsConstructor
public class PaymentService {

    private final PaymentRepository paymentRepository;

    @Transactional
    public PaymentResponse processPayment(PaymentRequest paymentRequest) {
        // Check for duplicate payment (idempotency)
        if (paymentRequest.getReferenceId() != null) {
            paymentRepository.findByReferenceId(paymentRequest.getReferenceId())
                .ifPresent(payment -> {
                    throw new PaymentException("Duplicate payment detected with reference ID: " + paymentRequest.getReferenceId());
                });
        }

        // Create and save payment entity
        Payment payment = new Payment();
        payment.setPaymentId(UUID.randomUUID().toString());
        payment.setSenderAccountNumber(paymentRequest.getSenderAccountNumber());
        payment.setReceiverAccountNumber(paymentRequest.getReceiverAccountNumber());
        payment.setAmount(paymentRequest.getAmount());
        payment.setCurrency(paymentRequest.getCurrency());
        payment.setStatus("PENDING");
        payment.setDescription(paymentRequest.getDescription());
        payment.setCreatedAt(LocalDateTime.now());
        payment.setPaymentMethod(paymentRequest.getPaymentMethod());
        payment.setIpAddress(paymentRequest.getIpAddress());
        payment.setUserAgent(paymentRequest.getUserAgent());
        payment.setReferenceId(paymentRequest.getReferenceId());

        payment = paymentRepository.save(payment);

        // In a real system, here you would integrate with payment gateways, banks, etc.
        // For this example, we'll simulate processing
        try {
            // Simulate processing delay
            Thread.sleep(100);

            // Simulate successful payment processing
            payment.setStatus("COMPLETED");
            payment.setCompletedAt(LocalDateTime.now());
            paymentRepository.save(payment);

            log.info("Payment processed successfully: {}", payment.getPaymentId());
            return buildPaymentResponse(payment, "Payment processed successfully");
        } catch (InterruptedException e) {
            payment.setStatus("FAILED");
            paymentRepository.save(payment);
            log.error("Payment processing failed: {}", payment.getPaymentId(), e);
            return buildPaymentResponse(payment, "Payment processing failed: " + e.getMessage());
        } catch (Exception e) {
            payment.setStatus("FAILED");
            paymentRepository.save(payment);
            log.error("Payment processing failed: {}", payment.getPaymentId(), e);
            throw new PaymentException("Payment processing failed: " + e.getMessage(), e);
        }
    }

    private PaymentResponse buildPaymentResponse(Payment payment, String message) {
        PaymentResponse response = new PaymentResponse();
        response.setPaymentId(payment.getPaymentId());
        response.setStatus(payment.getStatus());
        response.setCreatedAt(payment.getCreatedAt());
        response.setCompletedAt(payment.getCompletedAt());
        response.setMessage(message);
        return response;
    }

    public PaymentResponse getPaymentStatus(String paymentId) {
        Payment payment = paymentRepository.findByPaymentId(paymentId)
            .orElseThrow(() -> new PaymentException("Payment not found with ID: " + paymentId));

        return buildPaymentResponse(payment, "Payment status retrieved");
    }
}
```

