### 8. `service/impl/PaymentServiceImpl.java`
```java
package com.example.payment.service.impl;

import com.example.payment.dto.PaymentRequest;
import com.example.payment.dto.PaymentResponse;
import com.example.payment.exception.PaymentNotFoundException;
import com.example.payment.exception.PaymentProcessingException;
import com.example.payment.model.Payment;
import com.example.payment.model.PaymentStatus;
import com.example.payment.repository.PaymentRepository;
import com.example.payment.service.PaymentService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.LocalDateTime;
import java.util.List;
import java.util.UUID;
import java.util.stream.Collectors;

@Slf4j
@Service
@RequiredArgsConstructor
public class PaymentServiceImpl implements PaymentService {

    private final PaymentRepository paymentRepository;

    @Override
    @Transactional
    public PaymentResponse processPayment(PaymentRequest request) {
        // Idempotency check
        paymentRepository.findByIdempotencyKey(request.idempotencyKey())
            .ifPresent(payment -> {
                log.warn("Duplicate payment attempt with idempotency key: {}", request.idempotencyKey());
                throw new PaymentProcessingException("Payment already processed with this idempotency key");
            });

        // Create and save payment
        Payment payment = new Payment();
        payment.setSenderAccount(request.senderAccount());
        payment.setReceiverAccount(request.receiverAccount());
        payment.setAmount(request.amount());
        payment.setCurrency(request.currency());
        payment.setDescription(request.description());
        payment.setStatus(PaymentStatus.PENDING);
        payment.setCreatedAt(LocalDateTime.now());
        payment.setIdempotencyKey(request.idempotencyKey());

        // Simulate fraud check (in real system: integrate with fraud detection service)
        if (isFraudulent(request)) {
            payment.setStatus(PaymentStatus.FAILED);
            log.warn("Fraud detected for payment with idempotency key: {}", request.idempotencyKey());
        } else {
            // Simulate processing delay
            try {
                Thread.sleep(100); // Simulate network/database latency
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }

            payment.setStatus(PaymentStatus.COMPLETED);
            payment.setCompletedAt(LocalDateTime.now());
            log.info("Payment processed successfully: {}", payment.getId());
        }

        Payment savedPayment = paymentRepository.save(payment);
        return mapToResponse(savedPayment);
    }

    @Override
    @Transactional(readOnly = true)
    public PaymentResponse getPaymentById(UUID id) {
        return paymentRepository.findById(id)
            .map(this::mapToResponse)
            .orElseThrow(() -> new PaymentNotFoundException("Payment not found with id: " + id));
    }

    @Override
    @Transactional(readOnly = true)
    public List<PaymentResponse> getAllPayments(int page, int size) {
        Page<Payment> payments = paymentRepository.findAll(PageRequest.of(page, size));
        return payments.getContent().stream()
            .map(this::mapToResponse)
            .collect(Collectors.toList());
    }

    private boolean isFraudulent(PaymentRequest request) {
        // Simple fraud detection logic for demo
        // In production: integrate with a real fraud detection system
        String sender = request.senderAccount();
        String receiver = request.receiverAccount();
        BigDecimal amount = request.amount();

        // Example: flag if amount is too high or sender/receiver are suspicious
        return amount.compareTo(BigDecimal.valueOf(10000)) > 0 ||
               sender.equals(receiver) ||
               sender.startsWith("SUSPICIOUS") ||
               receiver.startsWith("SUSPICIOUS");
    }

    private PaymentResponse mapToResponse(Payment payment) {
        return new PaymentResponse(
            payment.getId(),
            payment.getSenderAccount(),
            payment.getReceiverAccount(),
            payment.getAmount(),
            payment.getCurrency(),
            payment.getStatus(),
            payment.getCreatedAt(),
            payment.getCompletedAt(),
            payment.getDescription()
        );
    }
}
```

