package com.example.payment.service;

import com.example.payment.dto.PaymentRequest;
import com.example.payment.model.Payment;
import com.example.payment.model.PaymentStatus;
import com.example.payment.repository.PaymentRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.UUID;

@Slf4j
@Service
@RequiredArgsConstructor
public class PaymentService {
    private final PaymentRepository paymentRepository;

    @Transactional
    public Payment processPayment(PaymentRequest request) {
        log.info("Processing payment: {}", request);

        // Validate sender has sufficient funds (simplified for demo)
        if (!hasSufficientFunds(request.getSenderAccount(), request.getAmount())) {
            throw new IllegalStateException("Insufficient funds");
        }

        // Create and save payment
        Payment payment = new Payment();
        payment.setSenderAccount(request.getSenderAccount());
        payment.setReceiverAccount(request.getReceiverAccount());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setTimestamp(LocalDateTime.now());
        payment.setStatus(PaymentStatus.COMPLETED);
        payment.setReference(UUID.randomUUID().toString());

        Payment savedPayment = paymentRepository.save(payment);
        log.info("Payment processed successfully: {}", savedPayment.getId());
        return savedPayment;
    }

    private boolean hasSufficientFunds(String account, BigDecimal amount) {
        // In a real system, this would query the account balance from a ledger service.
        // For demo, assume all accounts have sufficient funds.
        return true;
    }
}
