package com.example.paymentprocessing.service;

import com.example.paymentprocessing.model.Payment;
import com.example.paymentprocessing.model.PaymentStatus;
import com.example.paymentprocessing.repository.PaymentRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.util.Optional;

@Service
public class PaymentService {
    private final PaymentRepository paymentRepository;

    @Autowired
    public PaymentService(PaymentRepository paymentRepository) {
        this.paymentRepository = paymentRepository;
    }

    public Payment processPayment(String senderAccount, String receiverAccount, BigDecimal amount, String currency) {
        // Basic validation
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Amount must be positive");
        }
        if (senderAccount == null || receiverAccount == null || currency == null) {
            throw new IllegalArgumentException("Sender, receiver, and currency must not be null");
        }

        Payment payment = new Payment();
        payment.setSenderAccount(senderAccount);
        payment.setReceiverAccount(receiverAccount);
        payment.setAmount(amount);
        payment.setCurrency(currency);

        // In a real system, you'd have more complex logic here, like fraud detection, balance checks, etc.
        // For simplicity, we'll just save it as completed
        payment.setStatus(PaymentStatus.COMPLETED);

        return paymentRepository.save(payment);
    }

    public Optional<Payment> getPaymentById(Long id) {
        return paymentRepository.findById(id);
    }
}
