package com.example.payment.service;

import com.example.payment.dto.PaymentRequest;
import com.example.payment.dto.PaymentResponse;
import com.example.payment.model.Payment;
import com.example.payment.model.PaymentStatus;
import com.example.payment.repository.PaymentRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;

@Service
public class PaymentService {
    private static final Logger logger = LoggerFactory.getLogger(PaymentService.class);
    private final PaymentRepository paymentRepository;

    public PaymentService(PaymentRepository paymentRepository) {
        this.paymentRepository = paymentRepository;
    }

    @Transactional
    public PaymentResponse processPayment(PaymentRequest request) {
        logger.info("Processing payment from {} to {} for amount {} {}",
                request.getSenderAccount(),
                request.getReceiverAccount(),
                request.getAmount(),
                request.getCurrency());

        // Basic fraud detection: Check for suspicious amounts or accounts
        if (request.getAmount().compareTo(BigDecimal.valueOf(10000)) > 0) {
            logger.warn("Large transaction detected: {}", request.getAmount());
        }

        // Create and save payment
        Payment payment = new Payment();
        payment.setSenderAccount(request.getSenderAccount());
        payment.setReceiverAccount(request.getReceiverAccount());
        payment.setAmount(request.getAmount());
        payment.setCurrency(request.getCurrency());
        payment.setTimestamp(LocalDateTime.now());
        payment.setStatus(PaymentStatus.PENDING);
        payment.setReference(request.getReference());

        payment = paymentRepository.save(payment);

        // Simulate processing (e.g., calling an external payment gateway)
        // In a real system, this would involve more complex logic
        PaymentStatus status = PaymentStatus.COMPLETED;
        if (Math.random() < 0.01) { // 1% chance of failure for demo
            status = PaymentStatus.FAILED;
        }

        payment.setStatus(status);
        paymentRepository.save(payment);

        logger.info("Payment processed with status: {}", status);

        return new PaymentResponse() {{
            setId(payment.getId());
            setStatus(status.name());
            setMessage(status == PaymentStatus.COMPLETED ? "Payment successful" : "Payment failed");
        }};
    }

    public PaymentResponse getPayment(Long id) {
        Payment payment = paymentRepository.findById(id)
                .orElseThrow(() -> new RuntimeException("Payment not found"));

        return new PaymentResponse() {{
            setId(payment.getId());
            setStatus(payment.getStatus().name());
            setMessage("Payment retrieved");
        }};
    }
}
