// ========== CLIENT FOR EXTERNAL SERVICE ==========
@ConfigurationProperties(prefix = "user-service")
@Getter @Setter
class UserServiceConfig {
    private String baseUrl;
}

@Service
class UserServiceClient {
    private final RestClient restClient;

    public UserServiceClient(@Value("${user-service.base-url}") String baseUrl) {
        this.restClient = RestClient.builder()
                .baseUrl(baseUrl)
                .defaultHeader("Accept", "application/json")
                .defaultHeader("Content-Type", "application/json")
                .build();
    }

    public User getUser(Long userId) {
        try {
            return restClient.get()
                    .uri("/api/users/{id}", userId)
                    .retrieve()
                    .body(User.class);
        } catch (RestClientException e) {
            throw new ResponseStatusException(
                HttpStatus.SERVICE_UNAVAILABLE,
                "User service unavailable",
                e
            );
        }
    }
}

// ========== SERVICE LAYER ==========
@Service
@RequiredArgsConstructor
class OrderService {
    private final OrderRepository orderRepository;
    private final UserServiceClient userServiceClient;

    @Transactional
    public Order createOrder(Order order) {
        // Strict type safety: Validate user exists before creating order
        User user = userServiceClient.getUser(order.getUserId());
        if (user == null) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "User not found");
        }

        // Additional business validation
        if (order.getQuantity() > 100) {
            throw new ResponseStatusException(
                HttpStatus.BAD_REQUEST,
                "Maximum order quantity is 100"
            );
        }

        return orderRepository.save(order);
    }

    public List<Order> getOrdersByUser(Long userId) {
        return orderRepository.findByUserId(userId);
    }
}

// ========== CONTROLLER ==========
@RestController
@RequestMapping("/api/orders")
@RequiredArgsConstructor
class OrderController {
    private final OrderService orderService;

    @PostMapping
    public ResponseEntity<Order> createOrder(
            @Valid @RequestBody Order order,
            BindingResult bindingResult
    ) {
        if (bindingResult.hasErrors()) {
            throw new ResponseStatusException(
                HttpStatus.BAD_REQUEST,
                bindingResult.getAllErrors().get(0).getDefaultMessage()
            );
        }
        return ResponseEntity.ok(orderService.createOrder(order));
    }

    @GetMapping("/user/{userId}")
    public ResponseEntity<List<Order>> getUserOrders(@PathVariable @Positive Long userId) {
        return ResponseEntity.ok(orderService.getOrdersByUser(userId));
    }
}

// ========== EXCEPTION HANDLING ==========
@RestControllerAdvice
class GlobalExceptionHandler {
    @ExceptionHandler(ResponseStatusException.class)
    public ResponseEntity<Map<String, String>> handleResponseStatusException(
            ResponseStatusException ex
    ) {
        Map<String, String> body = new HashMap<>();
        body.put("error", ex.getReason());
        body.put("status", String.valueOf(ex.getStatusCode().value()));
        return new ResponseEntity<>(body, ex.getStatusCode());
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<Map<String, String>> handleGeneralException(Exception ex) {
        Map<String, String> body = new HashMap<>();
        body.put("error", "Internal server error");
        body.put("status", "500");
        return ResponseEntity.internalServerError().body(body);
    }
}

// ========== MAIN APPLICATION ==========
@SpringBootApplication
public class OrderServiceApplication {
    public static void main(String[] args) {
        SpringApplication.run(OrderServiceApplication.class, args);
    }
}
