```rust
use actix_web::{web, App, HttpServer, HttpResponse, Responder, middleware::Logger};
use serde::{Deserialize, Serialize};
use sqlx::postgres::PgPoolOptions;
use thiserror::Error;
use tracing::{info, error};
use utoipa::ToSchema;
use validator::Validate;

// ======================
// Domain Models (Strong Typing)
// ======================
#[derive(Debug, Serialize, Deserialize, sqlx::FromRow, ToSchema, Clone)]
pub struct Order {
    pub id: i64,
    pub customer_id: i64,
    pub product_code: String,
    pub quantity: i32,
    pub status: OrderStatus,
    pub created_at: chrono::DateTime<chrono::Utc>,
}

#[derive(Debug, Serialize, Deserialize, sqlx::Type, ToSchema, Clone, PartialEq)]
#[sqlx(type_name = "order_status", rename_all = "lowercase")]
pub enum OrderStatus {
    Pending,
    Processing,
    Completed,
    Cancelled,
}

#[derive(Debug, Serialize, Deserialize, Validate, ToSchema)]
pub struct CreateOrderRequest {
    #[validate(range(min = 1))]
    pub customer_id: i64,
    #[validate(length(min = 3, max = 20))]
    pub product_code: String,
    #[validate(range(min = 1, max = 100))]
    pub quantity: i32,
}

// ======================
// Repository Layer (Database Integration)
// ======================
pub struct OrderRepository {
    pool: sqlx::PgPool,
}

impl OrderRepository {
    pub async fn new(database_url: &str) -> Result<Self, sqlx::Error> {
        let pool = PgPoolOptions::new()
            .max_connections(20)
            .connect(database_url)
            .await?;

        Ok(Self { pool })
    }

    pub async fn create_order(&self, order: &CreateOrderRequest) -> Result<Order, sqlx::Error> {
        let status = OrderStatus::Pending;
        let row = sqlx::query_as!(
            Order,
            r#"
            INSERT INTO orders (customer_id, product_code, quantity, status)
            VALUES ($1, $2, $3, $4)
            RETURNING id, customer_id, product_code, quantity, status as "status: _", created_at
            "#,
            order.customer_id,
            order.product_code,
            order.quantity,
            status
        )
        .fetch_one(&self.pool)
        .await?;

        Ok(row)
    }

    pub async fn get_order(&self, order_id: i64) -> Result<Option<Order>, sqlx::Error> {
        let order = sqlx::query_as!(
            Order,
            r#"SELECT id, customer_id, product_code, quantity, status as "status: _", created_at
               FROM orders WHERE id = $1"#,
            order_id
        )
        .fetch_optional(&self.pool)
        .await?;

        Ok(order)
    }
}

// ======================
// Service Layer (Business Logic)
// ======================
pub struct OrderService {
    repo: OrderRepository,
}

impl OrderService {
    pub fn new(repo: OrderRepository) -> Self {
        Self { repo }
    }

    pub async fn create_order(
        &self,
        request: CreateOrderRequest,
    ) -> Result<Order, ServiceError> {
        request.validate()?;
        let order = self.repo.create_order(&request).await?;
        Ok(order)
    }

    pub async fn get_order(&self, order_id: i64) -> Result<Order, ServiceError> {
        let order = self.repo.get_order(order_id).await?
            .ok_or(ServiceError::NotFound(format!("Order {} not found", order_id)))?;
        Ok(order)
    }
}

// ======================
// Error Handling (Strict Type Safety)
// ======================
#[derive(Error, Debug)]
pub enum ServiceError {
    #[error("Validation error: {0}")]
    Validation(String),
    #[error("Database error: {0}")]
    Database(#[from] sqlx::Error),
    #[error("Not found: {0}")]
    NotFound(String),
    #[error("Internal server error")]
    InternalServerError,
}

impl actix_web::error::ResponseError for ServiceError {
    fn error_response(&self) -> HttpResponse {
        match self {
            ServiceError::Validation(msg) => HttpResponse::BadRequest().json(msg),
            ServiceError::Database(_) => HttpResponse::InternalServerError().json("Database error"),
            ServiceError::NotFound(msg) => HttpResponse::NotFound().json(msg),
            ServiceError::InternalServerError => HttpResponse::InternalServerError().json("Internal error"),
        }
    }
}

// ======================
// API Controllers (HTTP Layer)
// ======================
#[utoipa::path(
    post,
    path = "/orders",
    request_body = CreateOrderRequest,
    responses(
        (status = 201, description = "Order created", body = Order),
        (status = 400, description = "Validation error"),
    )
)]
async fn create_order(
    service: web::Data<OrderService>,
    request: web::Json<CreateOrderRequest>,
) -> Result<HttpResponse, ServiceError> {
    let order = service.create_order(request.into_inner()).await?;
    Ok(HttpResponse::Created().json(order))
}

#[utoipa::path(
    get,
    path = "/orders/{id}",
    responses(
        (status = 200, description = "Order found", body = Order),
        (status = 404, description = "Order not found"),
    ),
    params(
        ("id" = i64, Path, description = "Order ID")
    )
)]
async fn get_order(
    service: web::Data<OrderService>,
    order_id: web::Path<i64>,
) -> Result<HttpResponse, ServiceError> {
    let order = service.get_order(*order_id).await?;
    Ok(HttpResponse::Ok().json(order))
}

async fn health_check() -> impl Responder {
    HttpResponse::Ok().json("OK")
}

// ======================
// OpenAPI/Swagger Documentation
// ======================
#[derive(utoipa::OpenApi)]
#[openapi(
    paths(
        create_order,
        get_order,
        health_check,
    ),
    components(
        schemas(Order, OrderStatus, CreateOrderRequest)
    ),
    tags(
        (name = "orders", description = "Order management endpoints")
    )
)]
struct ApiDoc;

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    // Initialize logging
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    // Load configuration
    dotenv::dotenv().ok();
    let database_url = std::env::var("DATABASE_URL")
        .expect("DATABASE_URL must be set");

    // Initialize repository and service
    let repo = OrderRepository::new(&database_url)
        .await
        .expect("Failed to connect to database");
    let service = OrderService::new(repo);

    // Configure OpenAPI/Swagger
    let openapi = ApiDoc::openapi();

    info!("Starting microservice on 0.0.0.0:8080");

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(service.clone()))
            .service(
                web::scope("/api/v1")
                    .service(
                        web::resource("/orders")
                            .route(web::post().to(create_order))
                    )
                    .service(
                        web::resource("/orders/{id}")
                            .route(web::get().to(get_order))
                    )
            )
            .service(health_check)
            .service(
                web::resource("/swagger-ui")
                    .route(web::get().to(utoipa_swagger_ui::SwaggerUi::new("/api-doc/openapi.json").config(utoipa_swagger_ui::Config::default())))
            )
            .service(
                web::resource("/api-doc/openapi.json")
                    .route(web::get().to(|| async { openapi }))
            )
            .wrap(Logger::default())
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
