### `src/service.rs`
```rust
use crate::models::{CreateOrderRequest, Order, OrderResponse};
use sqlx::PgPool;
use thiserror::Error;
use validator::Validate;

#[derive(Error, Debug)]
pub enum ServiceError {
    #[error("Validation error: {0}")]
    ValidationError(String),
    #[error("Database error: {0}")]
    DatabaseError(#[from] sqlx::Error),
    #[error("Order not found")]
    NotFound,
}

pub struct OrderService {
    pool: PgPool,
}

impl OrderService {
    pub fn new(pool: PgPool) -> Self {
        Self { pool }
    }

    pub async fn create_order(
        &self,
        request: CreateOrderRequest,
    ) -> Result<OrderResponse, ServiceError> {
        request.validate().map_err(|e| {
            ServiceError::ValidationError(e.to_string())
        })?;

        let order = sqlx::query_as!(
            Order,
            r#"
            INSERT INTO orders (customer_id, product_ids, quantity, status, created_at)
            VALUES ($1, $2, $3, $4, $5)
            RETURNING id, customer_id, product_ids, quantity, status, created_at
            "#,
            request.customer_id,
            request.product_ids,
            request.quantity,
            "pending",
            chrono::Utc::now()
        )
        .fetch_one(&self.pool)
        .await?;

        Ok(OrderResponse {
            id: order.id,
            customer_id: order.customer_id,
            product_ids: order.product_ids,
            quantity: order.quantity,
            status: order.status,
            created_at: order.created_at,
        })
    }

    pub async fn get_order(&self, order_id: String) -> Result<OrderResponse, ServiceError> {
        let order = sqlx::query_as!(
            Order,
            r#"
            SELECT id, customer_id, product_ids, quantity, status, created_at
            FROM orders
            WHERE id = $1
            "#,
            order_id
        )
        .fetch_one(&self.pool)
        .await
        .map_err(|e| match e {
            sqlx::Error::RowNotFound => ServiceError::NotFound,
            _ => ServiceError::DatabaseError(e),
        })?;

        Ok(OrderResponse {
            id: order.id,
            customer_id: order.customer_id,
            product_ids: order.product_ids,
            quantity: order.quantity,
            status: order.status,
            created_at: order.created_at,
        })
    }
}
```

