use actix_web::{web, HttpResponse, Responder};
use crate::models::{CreateOrderRequest, HealthCheckResponse, OrderResponse};
use crate::service::{OrderService, ServiceError};

pub async fn health_check() -> impl Responder {
    HttpResponse::Ok().json(HealthCheckResponse {
        status: "healthy".to_string(),
        version: env!("CARGO_PKG_VERSION").to_string(),
    })
}

pub async fn create_order(
    order_service: web::Data<OrderService>,
    request: web::Json<CreateOrderRequest>,
) -> Result<HttpResponse, ServiceError> {
    let order = order_service.create_order(request.into_inner()).await?;
    Ok(HttpResponse::Created().json(order))
}

pub async fn get_order(
    order_service: web::Data<OrderService>,
    order_id: web::Path<String>,
) -> Result<HttpResponse, ServiceError> {
    let order = order_service.get_order(order_id.into_inner()).await?;
    Ok(HttpResponse::Ok().json(order))
}

pub fn configure(cfg: &mut web::ServiceConfig) {
    cfg.service(
        web::scope("/api/v1/orders")
            .route("", web::post().to(create_order))
            .route("/{order_id}", web::get().to(get_order)),
    )
    .route("/health", web::get().to(health_check));
}
