### 6. `CustomerService.kt` (Business Logic)
```kotlin
import org.springframework.stereotype.Service
import org.springframework.transaction.annotation.Transactional

@Service
class CustomerService(
    private val customerRepository: CustomerRepository,
    private val messageProducer: MessageProducer
) {
    @Transactional
    fun createCustomer(request: CreateCustomerRequest): CustomerResponse {
        if (customerRepository.existsByEmail(request.email)) {
            throw IllegalArgumentException("Email already in use")
        }

        val customer = Customer(
            customerId = request.customerId,
            firstName = request.firstName,
            lastName = request.lastName,
            email = request.email,
            dateOfBirth = request.dateOfBirth,
            corporateId = request.corporateId
        )

        val savedCustomer = customerRepository.save(customer)
        messageProducer.sendCustomerCreated(savedCustomer)

        return savedCustomer.toResponse()
    }

    fun getCustomerById(id: Long): CustomerResponse {
        return customerRepository.findById(id)
            .orElseThrow { NoSuchElementException("Customer not found") }
            .toResponse()
    }

    private fun Customer.toResponse() = CustomerResponse(
        id = id!!,
        customerId = customerId,
        firstName = firstName,
        lastName = lastName,
        email = email,
