### 5. `src/routes.rs`
```rust
use axum::{
    extract::{Path, State},
    http::StatusCode,
    response::IntoResponse,
    routing::{delete, get, post, put},
    Json, Router,
};
use uuid::Uuid;

use crate::{
    db::Db,
    error::AppError,
    models::{CreateEmployee, Employee, UpdateEmployee},
};

pub fn router() -> Router {
    Router::new()
        .route("/employees", post(create_employee))
        .route("/employees/:id", get(get_employee))
        .route("/employees/:id", put(update_employee))
        .route("/employees/:id", delete(delete_employee))
}

async fn create_employee(
    State(db): State<Db>,
    Json(payload): Json<CreateEmployee>,
) -> Result<impl IntoResponse, AppError> {
    // Validation
    if payload.first_name.trim().is_empty() {
        return Err(AppError::ValidationError("First name cannot be empty".to_string()));
    }
    if payload.last_name.trim().is_empty() {
        return Err(AppError::ValidationError("Last name cannot be empty".to_string()));
    }
    if !payload.email.contains('@') {
        return Err(AppError::ValidationError("Invalid email format".to_string()));
    }

    let employee = db.create_employee(payload).await?;
    Ok((StatusCode::CREATED, Json(employee)))
}

async fn get_employee(
    State(db): State<Db>,
    Path(id): Path<Uuid>,
) -> Result<impl IntoResponse, AppError> {
    let employee = db.get_employee(id).await.map_err(|_| AppError::NotFound(id))?;
    Ok(Json(employee))
}

async fn update_employee(
    State(db): State<Db>,
    Path(id): Path<Uuid>,
    Json(payload): Json<UpdateEmployee>,
) -> Result<impl IntoResponse, AppError> {
    // Validation
    if let Some(first_name) = &payload.first_name {
        if first_name.trim().is_empty() {
            return Err(AppError::ValidationError("First name cannot be empty".to_string()));
        }
    }
    if let Some(last_name) = &payload.last_name {
        if last_name.trim().is_empty() {
            return Err(AppError::ValidationError("Last name cannot be empty".to_string()));
        }
    }
    if let Some(email) = &payload.email {
        if !email.contains('@') {
            return Err(AppError::ValidationError("Invalid email format".to_string()));
        }
    }

    let employee = db.update_employee(id, payload).await?;
    Ok(Json(employee))
}

async fn delete_employee(
    State(db): State<Db>,
    Path(id): Path<Uuid>,
) -> Result<impl IntoResponse, AppError> {
    db.delete_employee(id).await?;
    Ok(StatusCode::NO_CONTENT)
}
