impl Db {
    pub fn new(pool: PgPool) -> Self {
        Self { pool }
    }

    pub async fn create_employee(&self, employee: CreateEmployee) -> Result<Employee, sqlx::Error> {
        let employee = sqlx::query_as!(
            Employee,
            r#"
            INSERT INTO employees (first_name, last_name, email, department, hire_date, is_active)
            VALUES ($1, $2, $3, $4, NOW(), true)
            RETURNING *
            "#,
            employee.first_name,
            employee.last_name,
            employee.email,
            employee.department
        )
        .fetch_one(&self.pool)
        .await?;

        Ok(employee)
    }

    pub async fn get_employee(&self, id: Uuid) -> Result<Employee, sqlx::Error> {
        let employee = sqlx::query_as!(
            Employee,
            "SELECT * FROM employees WHERE id = $1",
            id
        )
        .fetch_one(&self.pool)
        .await?;

        Ok(employee)
    }

    pub async fn update_employee(
        &self,
        id: Uuid,
        employee: UpdateEmployee,
    ) -> Result<Employee, sqlx::Error> {
        let employee = sqlx::query_as!(
            Employee,
            r#"
            UPDATE employees
            SET
                first_name = COALESCE($1, first_name),
                last_name = COALESCE($2, last_name),
                email = COALESCE($3, email),
                department = COALESCE($4, department),
                is_active = COALESCE($5, is_active)
            WHERE id = $6
            RETURNING *
            "#,
            employee.first_name,
            employee.last_name,
            employee.email,
            employee.department,
            employee.is_active,
            id
        )
        .fetch_one(&self.pool)
        .await?;

        Ok(employee)
    }

    pub async fn delete_employee(&self, id: Uuid) -> Result<(), sqlx::Error> {
        sqlx::query!("DELETE FROM employees WHERE id = $1", id)
            .execute(&self.pool)
            .await?;

        Ok(())
    }
