### 3. **Service Layer with Business Logic**

```java
// service/OrderService.java
package com.example.ordermanagement.service;

import com.example.ordermanagement.exception.OrderNotFoundException;
import com.example.ordermanagement.model.*;
import com.example.ordermanagement.repository.OrderRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.validation.annotation.Validated;
import jakarta.validation.Valid;
import java.util.List;
import java.util.stream.Collectors;

@Service
@Validated
@Transactional
public class OrderService {
    private final OrderRepository orderRepository;
    private final OrderEventService orderEventService;

    public OrderService(OrderRepository orderRepository, OrderEventService orderEventService) {
        this.orderRepository = orderRepository;
        this.orderEventService = orderEventService;
    }

    public Order createOrder(@Valid CreateOrderRequest request) {
        Customer customer = new Customer(
            request.getCustomerId(),
            request.getCustomerName(),
            request.getCustomerEmail()
        );

        OrderId orderId = new OrderId(generateOrderId());
        Order order = new Order(orderId, customer, request.getTotalAmount());

        request.getItems().forEach(itemRequest -> {
            OrderItem item = new OrderItem(
                itemRequest.getProductId(),
                itemRequest.getProductName(),
                itemRequest.getQuantity(),
                itemRequest.getUnitPrice()
            );
            order.addItem(item);
        });

        Order savedOrder = orderRepository.save(order);
        orderEventService.publishOrderCreated(savedOrder);
        return savedOrder;
    }

    @Transactional(readOnly = true)
    public Order getOrder(OrderId id) {
        return orderRepository.findByIdWithCustomer(id)
                .orElseThrow(() -> new OrderNotFoundException(id));
    }

    public List<Order> getOrdersByCustomer(String customerId) {
        return orderRepository.findByCustomerId(customerId);
    }

    public Order updateOrderStatus(OrderId id, OrderStatus newStatus) {
        Order order = orderRepository.findById(id)
                .orElseThrow(() -> new OrderNotFoundException(id));
        order.setStatus(newStatus);
        Order updatedOrder = orderRepository.save(order);
        orderEventService.publishOrderStatusChanged(updatedOrder);
        return updatedOrder;
    }

    private String generateOrderId() {
        return "ORD-" + java.time.LocalDateTime.now()
                .format(java.time.format.DateTimeFormatter.ofPattern("yyyyMMdd"));
    }
}
