// service/OrderEventService.java
package com.example.ordermanagement.service;

import com.example.ordermanagement.integration.kafka.KafkaOrderEventProducer;
import com.example.ordermanagement.integration.kafka.OrderEvent;
import com.example.ordermanagement.model.Order;
import org.springframework.stereotype.Service;

@Service
public class OrderEventService {
    private final KafkaOrderEventProducer kafkaProducer;

    public OrderEventService(KafkaOrderEventProducer kafkaProducer) {
        this.kafkaProducer = kafkaProducer;
    }

    public void publishOrderCreated(Order order) {
        OrderEvent event = new OrderEvent(
            "ORDER_CREATED",
            order.getId().getValue(),
            order.getCustomer().getId(),
            order.getTotalAmount(),
            order.getStatus().name(),
            order.getItems().stream()
                .map(item -> new OrderEvent.Item(
                    item.getProductId(),
                    item.getQuantity(),
                    item.getUnitPrice()
                ))
                .collect(Collectors.toList())
        );
        kafkaProducer.publish(event);
    }

    public void publishOrderStatusChanged(Order order) {
        OrderEvent event = new OrderEvent(
            "ORDER_STATUS_CHANGED",
            order.getId().getValue(),
            order.getCustomer().getId(),
            order.getTotalAmount(),
            order.getStatus().name(),
            null
        );
        kafkaProducer.publish(event);
    }
}
