package com.example.corporate.service;

import com.example.corporate.dto.EmployeeDto;
import com.example.corporate.exception.EmployeeNotFoundException;
import com.example.corporate.integration.CorporateSystemClient;
import com.example.corporate.model.Employee;
import com.example.corporate.repository.EmployeeRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
public class EmployeeService {
    private final EmployeeRepository employeeRepository;
    private final CorporateSystemClient corporateSystemClient;

    @Transactional
    public EmployeeDto.Response createEmployee(EmployeeDto.Request request) {
        // Validate department
        Employee.Department department = Employee.Department.valueOf(request.getDepartment());

        // Check if employee already exists in corporate system
        corporateSystemClient.validateEmployee(request.getEmail());

        // Save to local DB
        Employee employee = Employee.builder()
                .name(request.getName())
                .email(request.getEmail())
                .department(department)
                .build();

        employee = employeeRepository.save(employee);

        return mapToResponse(employee);
    }

    @Transactional(readOnly = true)
    public List<EmployeeDto.Response> getAllEmployees() {
        return employeeRepository.findAll().stream()
                .map(this::mapToResponse)
                .collect(Collectors.toList());
    }

    @Transactional(readOnly = true)
    public EmployeeDto.Response getEmployeeById(Long id) {
        return employeeRepository.findById(id)
                .map(this::mapToResponse)
                .orElseThrow(() -> new EmployeeNotFoundException(id));
    }

    private EmployeeDto.Response mapToResponse(Employee employee) {
        return EmployeeDto.Response.builder()
                .id(employee.getId())
                .name(employee.getName())
                .email(employee.getEmail())
                .department(employee.getDepartment().name())
                .build();
    }
}
