// src/main/java/com/example/enterprisemicro/service/OrderService.java
package com.example.enterprisemicro.service;

import com.example.enterprisemicro.dto.OrderRequest;
import com.example.enterprisemicro.dto.OrderResponse;
import com.example.enterprisemicro.exception.OrderNotFoundException;
import com.example.enterprisemicro.model.CustomerId;
import com.example.enterprisemicro.model.Order;
import com.example.enterprisemicro.repository.OrderRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
@Slf4j
@Transactional(readOnly = true)
public class OrderService {
    private final OrderRepository orderRepository;
    private final CorporateIntegrationService corporateIntegrationService;

    @Transactional
    public OrderResponse placeOrder(OrderRequest request) {
        log.info("Placing order for customer {}: {}", request.customerId(), request);

        // Validate customer exists in corporate system
        if (!corporateIntegrationService.customerExists(request.customerId())) {
            throw new IllegalArgumentException("Customer does not exist: " + request.customerId());
        }

        // Validate product exists in corporate system
        if (!corporateIntegrationService.productExists(request.productId())) {
            throw new IllegalArgumentException("Product does not exist: " + request.productId());
        }

        Order order = new Order();
        order.setCustomerId(request.customerId());
        order.setProductId(request.productId());
        order.setQuantity(request.quantity());
        order.setStatus(Order.OrderStatus.PROCESSING);

        // Process payment with corporate system
        corporateIntegrationService.processPayment(order);

        order.setStatus(Order.OrderStatus.COMPLETED);
        Order savedOrder = orderRepository.save(order);

        log.info("Order placed successfully: {}", savedOrder.getId());
        return OrderResponse.fromEntity(savedOrder);
    }

    public List<OrderResponse> getOrdersByCustomer(CustomerId customerId) {
        return orderRepository.findByCustomerId(customerId)
            .stream()
            .map(OrderResponse::fromEntity)
            .collect(Collectors.toList());
    }

    public OrderResponse getOrderDetails(CustomerId customerId, Long orderId) {
        return orderRepository.findByIdAndCustomerId(orderId, customerId)
            .map(OrderResponse::fromEntity)
            .orElseThrow(() -> new OrderNotFoundException(
                "Order not found for customer " + customerId + " with ID " + orderId));
    }
}
