// src/main/java/com/example/enterprisemicro/service/CorporateIntegrationService.java
package com.example.enterprisemicro.service;

import com.example.enterprisemicro.model.CustomerId;
import com.example.enterprisemicro.model.Order;
import com.example.enterprisemicro.model.ProductId;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestClient;

@Service
@RequiredArgsConstructor
@Slf4j
public class CorporateIntegrationService {
    private final RestClient restClient;

    public boolean customerExists(CustomerId customerId) {
        try {
            return restClient.get()
                .uri("/customers/{id}", customerId.value())
                .retrieve()
                .body(Boolean.class);
        } catch (Exception e) {
            log.error("Failed to check customer existence: {}", e.getMessage());
            return false;
        }
    }

    public boolean productExists(ProductId productId) {
        try {
            return restClient.get()
                .uri("/products/{id}", productId.value())
                .retrieve()
                .body(Boolean.class);
        } catch (Exception e) {
            log.error("Failed to check product existence: {}", e.getMessage());
            return false;
        }
    }

    public void processPayment(Order order) {
        try {
            restClient.post()
                .uri("/payments/process")
                .body(order)
                .retrieve()
                .toBodilessEntity();
        } catch (Exception e) {
            log.error("Payment processing failed: {}", e.getMessage());
            throw new RuntimeException("Payment processing failed", e);
        }
    }
}
