import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/v1/orders")
@RequiredArgsConstructor
@Tag(name = "Order Management", description = "Operations pertaining to orders")
public class OrderController {
    private final OrderService orderService;

    @PostMapping
    @Operation(summary = "Place a new order")
    public ResponseEntity<OrderResponse> placeOrder(@Valid @RequestBody OrderRequest request) {
        OrderResponse response = orderService.placeOrder(request);
        return ResponseEntity.status(HttpStatus.CREATED).body(response);
    }

    @GetMapping("/customer/{customerId}")
    @Operation(summary = "Get all orders for a customer")
    public ResponseEntity<List<OrderResponse>> getOrdersByCustomer(
            @PathVariable CustomerId customerId) {
        List<OrderResponse> orders = orderService.getOrdersByCustomer(customerId);
        return ResponseEntity.ok(orders);
    }

    @GetMapping("/customer/{customerId}/{orderId}")
    @Operation(summary = "Get order details")
    public ResponseEntity<OrderResponse> getOrderDetails(
            @PathVariable CustomerId customerId,
            @PathVariable Long orderId) {
        OrderResponse order = orderService.getOrderDetails(customerId, orderId);
        return ResponseEntity.ok(order);
    }
}
