package com.example.orderservice.service;

import com.example.orderservice.client.InventoryClient;
import com.example.orderservice.exception.InsufficientInventoryException;
import com.example.orderservice.model.Order;
import com.example.orderservice.model.OrderStatus;
import com.example.orderservice.repository.OrderRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;

@Service
@RequiredArgsConstructor
@Slf4j
public class OrderService {
    private final OrderRepository orderRepository;
    private final InventoryClient inventoryClient;

    @Transactional
    public Order createOrder(Order order) {
        // 1. Validate inventory (corporate system integration)
        boolean isInventoryAvailable = inventoryClient.checkInventory(
            order.getProductId(),
            order.getQuantity()
        );

        if (!isInventoryAvailable) {
            throw new InsufficientInventoryException(
                "Insufficient inventory for product: " + order.getProductId()
            );
        }

        // 2. Save order
        order.setStatus(OrderStatus.PROCESSING);
        Order savedOrder = orderRepository.save(order);

        // 3. Update inventory (async in production)
        inventoryClient.reserveInventory(order.getProductId(), order.getQuantity());

        log.info("Order created: {}", savedOrder.getId());
        return savedOrder;
    }

    public Order getOrder(Long id, String customerId) {
        return orderRepository.findByIdAndCustomerId(id, customerId)
            .orElseThrow(() -> new RuntimeException("Order not found"));
    }
}
