package com.example.orderservice.client;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.HttpStatusCode;
import org.springframework.stereotype.Component;
import org.springframework.web.reactive.function.client.WebClient;
import reactor.core.publisher.Mono;

@Component
@RequiredArgsConstructor
@Slf4j
public class InventoryClient {
    private final WebClient webClient;
    private final String inventoryServiceUrl;

    public boolean checkInventory(String productId, int quantity) {
        return webClient.get()
            .uri("/api/inventory/check?productId={productId}&quantity={quantity}",
                productId, quantity)
            .retrieve()
            .onStatus(HttpStatusCode::isError, (request, response) -> {
                log.error("Inventory check failed: {}", response.getStatusText());
                return Mono.error(new RuntimeException("Inventory service unavailable"));
            })
            .bodyToMono(Boolean.class)
            .block(); // Use block() for synchronous calls (async in production)
    }

    public void reserveInventory(String productId, int quantity) {
        webClient.post()
            .uri("/api/inventory/reserve")
            .bodyValue(Map.of("productId", productId, "quantity", quantity))
            .retrieve()
            .toBodilessEntity()
            .block();
    }
}
