```java
package com.example.corporate.service;

import com.example.corporate.dto.EmployeeRequest;
import com.example.corporate.dto.EmployeeResponse;
import com.example.corporate.exception.CorporateIntegrationException;
import com.example.corporate.integration.CorporateDirectoryClient;
import com.example.corporate.model.Employee;
import com.example.corporate.repository.EmployeeRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.stream.Collectors;

@Service
@Transactional
public class EmployeeServiceImpl implements EmployeeService {

    private final EmployeeRepository employeeRepository;
    private final CorporateDirectoryClient corporateDirectoryClient;

    public EmployeeServiceImpl(EmployeeRepository employeeRepository,
                             CorporateDirectoryClient corporateDirectoryClient) {
        this.employeeRepository = employeeRepository;
        this.corporateDirectoryClient = corporateDirectoryClient;
    }

    @Override
    public EmployeeResponse createEmployee(EmployeeRequest request) {
        // Check if employee already exists in corporate directory
        if (corporateDirectoryClient.employeeExists(request.employeeId())) {
            throw new CorporateIntegrationException(
                "Employee with ID " + request.employeeId() + " already exists in corporate systems");
        }

        // Create new employee
        Employee employee = new Employee();
        employee.setEmployeeId(request.employeeId());
        employee.setFirstName(request.firstName());
        employee.setLastName(request.lastName());
        employee.setEmail(request.email());
        employee.setDepartment(determineDepartment(request.email()));

        Employee savedEmployee = employeeRepository.save(employee);

        // Notify corporate directory (simulated)
        corporateDirectoryClient.registerEmployee(savedEmployee.getEmployeeId());

        return mapToResponse(savedEmployee);
    }

    @Override
    @Transactional(readOnly = true)
    public EmployeeResponse getEmployeeById(String employeeId) {
        Employee employee = employeeRepository.findByEmployeeId(employeeId)
            .orElseThrow(() -> new CorporateIntegrationException(
                "Employee with ID " + employeeId + " not found"));

        return mapToResponse(employee);
    }

    @Override
    @Transactional(readOnly = true)
    public List<EmployeeResponse> getAllEmployees() {
        return employeeRepository.findAll().stream()
            .map(this::mapToResponse)
            .collect(Collectors.toList());
    }

    @Override
    public void deleteEmployee(String employeeId) {
        Employee employee = employeeRepository.findByEmployeeId(employeeId)
            .orElseThrow(() -> new CorporateIntegrationException(
                "Employee with ID " + employeeId + " not found"));

        employeeRepository.delete(employee);
        corporateDirectoryClient.deactivateEmployee(employeeId);
    }

    private String determineDepartment(String email) {
        if (email.endsWith("@finance.corp")) return "Finance";
        if (email.endsWith("@hr.corp")) return "HR";
        if (email.endsWith("@it.corp")) return "IT";
        return "General";
    }

    private EmployeeResponse mapToResponse(Employee employee) {
        return new EmployeeResponse(
            employee.getEmployeeId(),
            employee.getFirstName(),
            employee.getLastName(),
            employee.getEmail(),
            employee.getCreatedAt(),
            employee.getDepartment()
        );
    }
}
```

