package com.example.enterprisemicro.service;

import com.example.enterprisemicro.dto.CustomerRequest;
import com.example.enterprisemicro.dto.CustomerResponse;
import com.example.enterprisemicro.exception.ResourceNotFoundException;
import com.example.enterprisemicro.model.Customer;
import com.example.enterprisemicro.repository.CustomerRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class CustomerService {
    private final CustomerRepository customerRepository;
    private final CorporateSystemClient corporateSystemClient; // Integration

    public CustomerService(CustomerRepository customerRepository, CorporateSystemClient corporateSystemClient) {
        this.customerRepository = customerRepository;
        this.corporateSystemClient = corporateSystemClient;
    }

    @Transactional
    public CustomerResponse createCustomer(CustomerRequest request) {
        // Validate email uniqueness (example)
        if (customerRepository.findByEmail(request.email()).isPresent()) {
            throw new IllegalArgumentException("Email already exists");
        }

        // Save to local DB
        Customer customer = new Customer(request.name(), request.email());
        customer = customerRepository.save(customer);

        // Integrate with corporate system (e.g., send notification)
        corporateSystemClient.notifyCorporateSystem(customer.getId());

        return new CustomerResponse(customer.getId(), customer.getName(), customer.getEmail());
    }

    public CustomerResponse getCustomer(Long id) {
        Customer customer = customerRepository.findById(id)
            .orElseThrow(() -> new ResourceNotFoundException("Customer not found"));
        return new CustomerResponse(customer.getId(), customer.getName(), customer.getEmail());
    }
}
