using EnterpriseBackend.Models;
using Microsoft.Extensions.Logging;

namespace EnterpriseBackend.Services
{
    public class ProductService : IProductService
    {
        private readonly ILogger<ProductService> _logger;
        private readonly List<Product> _products = new();

        public ProductService(ILogger<ProductService> logger)
        {
            _logger = logger;
            // Seed with initial data
            if (!_products.Any())
            {
                _products.AddRange(new[]
                {
                    new Product { Id = 1, Name = "Enterprise Laptop", Price = 1299.99m },
                    new Product { Id = 2, Name = "Cloud Server", Price = 899.99m },
                    new Product { Id = 3, Name = "DevOps Toolkit", Price = 499.99m }
                });
            }
        }

        public Task<IEnumerable<Product>> GetProductsAsync()
        {
            _logger.LogInformation("Retrieving all products");
            return Task.FromResult(_products.AsEnumerable());
        }

        public Task<Product> GetProductAsync(int id)
        {
            _logger.LogInformation("Retrieving product with id {Id}", id);
            var product = _products.FirstOrDefault(p => p.Id == id);
            return Task.FromResult(product);
        }

        public Task<Product> CreateProductAsync(Product product)
        {
            _logger.LogInformation("Creating new product: {ProductName}", product.Name);
            product.Id = _products.Max(p => p.Id) + 1;
            _products.Add(product);
            return Task.FromResult(product);
        }
    }
}
```

