            {
                var products = await _productService.GetProductsAsync();
                return products.Any()
                    ? HealthCheckResult.Healthy("Product service is healthy")
                    : HealthCheckResult.Degraded("No products available");
            }
            catch (Exception ex)
            {
                return HealthCheckResult.Unhealthy("Product service is unhealthy", ex);
            }
        }
