using EnterpriseBackend.Application.Interfaces;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Interfaces;

namespace EnterpriseBackend.Application.Services;

public class OrderService : IOrderService
{
    private readonly IOrderRepository _orderRepository;
    private readonly ILogger<OrderService> _logger;
    private readonly IAzureStorageService _storageService;

    public OrderService(
        IOrderRepository orderRepository,
        ILogger<OrderService> logger,
        IAzureStorageService storageService)
    {
        _orderRepository = orderRepository;
        _logger = logger;
        _storageService = storageService;
    }

    public async Task<Order> GetOrderByIdAsync(Guid orderId)
    {
        _logger.LogInformation("Retrieving order {OrderId}", orderId);
        return await _orderRepository.GetByIdAsync(orderId);
    }

    public async Task<IEnumerable<Order>> GetOrdersByCustomerAsync(string customerId)
    {
        _logger.LogInformation("Retrieving orders for customer {CustomerId}", customerId);
        return await _orderRepository.GetByCustomerAsync(customerId);
    }

    public async Task<Order> CreateOrderAsync(Order order)
    {
        _logger.LogInformation("Creating new order for customer {CustomerId}", order.CustomerId);

        // Validate order
        if (order.Items == null || !order.Items.Any())
        {
            throw new ArgumentException("Order must contain at least one item");
        }

        // Calculate total
        order.TotalAmount = order.Items.Sum(i => i.Quantity * i.UnitPrice);
        order.OrderDate = DateTime.UtcNow;
        order.Status = OrderStatus.Pending;

        // Store in repository
        var createdOrder = await _orderRepository.AddAsync(order);

        // Optionally store order details in blob storage
        await _storageService.UploadOrderDetailsAsync(createdOrder);

        _logger.LogInformation("Order {OrderId} created successfully", createdOrder.Id);
        return createdOrder;
    }

    public async Task UpdateOrderStatusAsync(Guid orderId, OrderStatus status)
    {
        _logger.LogInformation("Updating order {OrderId} status to {Status}", orderId, status);
        await _orderRepository.UpdateStatusAsync(orderId, status);
    }

    public async Task DeleteOrderAsync(Guid orderId)
    {
        _logger.LogInformation("Deleting order {OrderId}", orderId);
        await _orderRepository.DeleteAsync(orderId);
    }
}
