// src/EnterpriseBackend.Infrastructure/Repositories/OrderRepository.cs
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Interfaces;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Infrastructure.Repositories;

public class OrderRepository : IOrderRepository
{
    private readonly AppDbContext _context;

    public OrderRepository(AppDbContext context)
    {
        _context = context;
    }

    public async Task<Order> GetByIdAsync(Guid id)
    {
        return await _context.Orders
            .Include(o => o.Items)
            .FirstOrDefaultAsync(o => o.Id == id)
            ?? throw new KeyNotFoundException($"Order with ID {id} not found");
    }

    public async Task<IEnumerable<Order>> GetByCustomerAsync(string customerId)
    {
        return await _context.Orders
            .Include(o => o.Items)
            .Where(o => o.CustomerId == customerId)
            .ToListAsync();
    }

    public async Task<Order> AddAsync(Order order)
    {
        _context.Orders.Add(order);
        await _context.SaveChangesAsync();
        return order;
    }

    public async Task UpdateStatusAsync(Guid orderId, OrderStatus status)
    {
        var order = await _context.Orders.FindAsync(orderId);
        if (order == null) throw new KeyNotFoundException($"Order with ID {orderId} not found");

        order.Status = status;
        await _context.SaveChangesAsync();
    }

    public async Task DeleteAsync(Guid id)
    {
        var order = await _context.Orders.FindAsync(id);
        if (order != null)
        {
            _context.Orders.Remove(order);
            await _context.SaveChangesAsync();
        }
    }
}

// src/EnterpriseBackend.Infrastructure/Services/AzureStorageService.cs
using Azure.Storage.Blobs;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Interfaces;
using Microsoft.Extensions.Options;

namespace EnterpriseBackend.Infrastructure.Services;

public class AzureStorageService : IAzureStorageService
{
    private readonly BlobServiceClient _blobServiceClient;
    private readonly string _containerName;

    public AzureStorageService(IOptions<AzureStorageSettings> settings)
    {
        _blobServiceClient = new BlobServiceClient(settings.Value.ConnectionString);
        _containerName = settings.Value.ContainerName;
    }

    public async Task UploadOrderDetailsAsync(Order order)
    {
        var containerClient = _blobServiceClient.GetBlobContainerClient(_containerName);
        await containerClient.CreateIfNotExistsAsync();

        var blobClient = containerClient.GetBlobClient($"orders/{order.Id}.json");
        var orderJson = System.Text.Json.JsonSerializer.Serialize(order);

        using var stream = new MemoryStream(System.Text.Encoding.UTF8.GetBytes(orderJson));
        await blobClient.UploadAsync(stream, overwrite: true);
    }

    public async Task<string> GetOrderDetailsAsync(Guid orderId)
    {
        var containerClient = _blobServiceClient.GetBlobContainerClient(_containerName);
        var blobClient = containerClient.GetBlobClient($"orders/{orderId}.json");

        if (!await blobClient.ExistsAsync())
        {
            throw new FileNotFoundException($"Order details for {orderId} not found in storage");
        }

        var download = await blobClient.DownloadAsync();
        using var reader = new StreamReader(download.Value.Content);
        return await reader.ReadToEndAsync();
    }
}
