// src/EnterpriseBackend.Api/Middleware/ExceptionHandlingMiddleware.cs
using System.Net;
using System.Text.Json;

namespace EnterpriseBackend.Api.Middleware;

public class ExceptionHandlingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<ExceptionHandlingMiddleware> _logger;

    public ExceptionHandlingMiddleware(
        RequestDelegate next,
        ILogger<ExceptionHandlingMiddleware> logger)
    {
        _next = next;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        try
        {
            await _next(context);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An unhandled exception occurred");
            await HandleExceptionAsync(context, ex);
        }
    }

    private static Task HandleExceptionAsync(HttpContext context, Exception exception)
    {
        var code = HttpStatusCode.InternalServerError; // 500 if unexpected

        if (exception is KeyNotFoundException) code = HttpStatusCode.NotFound;
        else if (exception is ArgumentException) code = HttpStatusCode.BadRequest;

        var result = JsonSerializer.Serialize(new
        {
            error = exception.Message,
            stackTrace = exception.StackTrace // In production, consider removing this
        });

        context.Response.ContentType = "application/json";
        context.Response.StatusCode = (int)code;

        return context.Response.WriteAsync(result);
    }
}
