// Services/ProductService.cs
using Microsoft.Extensions.Logging;

namespace EnterpriseBackend.Services;

public class ProductService : IProductService
{
    private readonly ILogger<ProductService> _logger;
    private readonly List<ProductDto> _products = new();
    private int _nextId = 1;

    public ProductService(ILogger<ProductService> logger)
    {
        _logger = logger;

        // Seed some initial data
        _products.Add(new ProductDto { Id = _nextId++, Name = "Laptop", Description = "High-performance laptop", Price = 999.99m, StockQuantity = 50 });
        _products.Add(new ProductDto { Id = _nextId++, Name = "Smartphone", Description = "Latest smartphone model", Price = 699.99m, StockQuantity = 100 });
    }

    public Task<IEnumerable<ProductDto>> GetAllProductsAsync()
    {
        _logger.LogInformation("Retrieving all products");
        return Task.FromResult<IEnumerable<ProductDto>>(_products);
    }

    public Task<ProductDto?> GetProductByIdAsync(int id)
    {
        _logger.LogInformation("Retrieving product with ID {Id}", id);
        return Task.FromResult(_products.FirstOrDefault(p => p.Id == id));
    }

    public Task<int> CreateProductAsync(ProductDto productDto)
    {
        _logger.LogInformation("Creating new product: {ProductName}", productDto.Name);

        var product = new ProductDto
        {
            Id = _nextId++,
            Name = productDto.Name,
            Description = productDto.Description,
            Price = productDto.Price,
            StockQuantity = productDto.StockQuantity
        };

        _products.Add(product);
        return Task.FromResult(product.Id);
    }

    public Task UpdateProductAsync(int id, ProductDto productDto)
    {
        _logger.LogInformation("Updating product with ID {Id}", id);

        var existingProduct = _products.FirstOrDefault(p => p.Id == id);
        if (existingProduct == null)
        {
            throw new KeyNotFoundException($"Product with ID {id} not found.");
        }

        existingProduct.Name = productDto.Name;
        existingProduct.Description = productDto.Description;
        existingProduct.Price = productDto.Price;
        existingProduct.StockQuantity = productDto.StockQuantity;

        return Task.CompletedTask;
    }

    public Task DeleteProductAsync(int id)
    {
        _logger.LogInformation("Deleting product with ID {Id}", id);

        var product = _products.FirstOrDefault(p => p.Id == id);
        if (product != null)
        {
            _products.Remove(product);
        }

        return Task.CompletedTask;
    }
}
