```csharp
using EnterpriseBackendService.Models;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackendService.Services;

public class OrderService : IOrderService
{
    private readonly AppDbContext _context;
    private readonly ILogger<OrderService> _logger;
    private readonly ICacheService _cache;

    public OrderService(AppDbContext context, ILogger<OrderService> logger, ICacheService cache)
    {
        _context = context;
        _logger = logger;
        _cache = cache;
    }

    public async Task<IEnumerable<Order>> GetAllOrdersAsync()
    {
        const string cacheKey = "all_orders";
        var cachedOrders = await _cache.GetAsync<IEnumerable<Order>>(cacheKey);

        if (cachedOrders != null)
        {
            _logger.LogInformation("Retrieved orders from cache");
            return cachedOrders;
        }

        var orders = await _context.Orders
            .Include(o => o.Items)
            .ToListAsync();

        await _cache.SetAsync(cacheKey, orders, TimeSpan.FromMinutes(5));

        return orders;
    }

    public async Task<Order?> GetOrderByIdAsync(Guid id)
    {
        const string cacheKey = "order_{0}";
        var cachedOrder = await _cache.GetAsync<Order>(string.Format(cacheKey, id));

        if (cachedOrder != null)
        {
            _logger.LogInformation("Retrieved order {OrderId} from cache", id);
            return cachedOrder;
        }

        var order = await _context.Orders
            .Include(o => o.Items)
            .FirstOrDefaultAsync(o => o.Id == id);

        if (order != null)
        {
            await _cache.SetAsync(string.Format(cacheKey, id), order, TimeSpan.FromMinutes(5));
        }

        return order;
    }

    public async Task<Order> CreateOrderAsync(Order order)
    {
        order.Id = Guid.NewGuid();
        order.OrderDate = DateTime.UtcNow;

        _context.Orders.Add(order);
        await _context.SaveChangesAsync();

        // Invalidate cache
        await _cache.RemoveAsync("all_orders");

        return order;
    }

    public async Task<bool> UpdateOrderAsync(Order order)
    {
        var existingOrder = await _context.Orders.FindAsync(order.Id);
        if (existingOrder == null) return false;

        _context.Entry(existingOrder).CurrentValues.SetValues(order);
        await _context.SaveChangesAsync();

        // Update cache
        await _cache.SetAsync(string.Format("order_{0}", order.Id), order, TimeSpan.FromMinutes(5));

        return true;
    }

    public async Task<bool> DeleteOrderAsync(Guid id)
    {
        var order = await _context.Orders.FindAsync(id);
        if (order == null) return false;

        _context.Orders.Remove(order);
        await _context.SaveChangesAsync();

        // Invalidate cache
        await _cache.RemoveAsync("all_orders");
        await _cache.RemoveAsync(string.Format("order_{0}", id));

        return true;
    }
}
