```csharp
using Azure;
using Azure.Data.Tables;
using EnterpriseBackendService.Models;

namespace EnterpriseBackendService.Services;

public class AzureCacheService : ICacheService
{
    private readonly TableClient _tableClient;
    private readonly ILogger<AzureCacheService> _logger;

    public AzureCacheService(IConfiguration configuration, ILogger<AzureCacheService> logger)
    {
        var connectionString = configuration["AzureStorage:ConnectionString"];
        var tableName = configuration["AzureStorage:CacheTableName"] ?? "Cache";

        _tableClient = new TableClient(connectionString, tableName);
        _tableClient.CreateIfNotExists();
        _logger = logger;
    }

    public async Task<T?> GetAsync<T>(string key)
    {
        try
        {
            var entity = await _tableClient.GetEntityAsync<CacheEntity>(key, "default");
            return entity.Value.Deserialize<T>();
        }
        catch (RequestFailedException ex) when (ex.Status == 404)
        {
            _logger.LogDebug("Cache miss for key: {Key}", key);
            return default;
        }
    }

    public async Task SetAsync<T>(string key, T value, TimeSpan expiration)
    {
        var entity = new CacheEntity
        {
            PartitionKey = key,
            RowKey = "default",
            Value = value.Serialize(),
            ExpirationTime = DateTimeOffset.UtcNow.Add(expiration)
        };

        await _tableClient.UpsertEntityAsync(entity);
    }

    public async Task RemoveAsync(string key)
    {
        await _tableClient.DeleteEntityAsync(key, "default");
    }
}

public class CacheEntity : ITableEntity
{
    public string PartitionKey { get; set; } = string.Empty;
    public string RowKey { get; set; } = string.Empty;
    public DateTimeOffset? Timestamp { get; set; }
    public ETag ETag { get; set; }
    public string Value { get; set; } = string.Empty;
    public DateTimeOffset ExpirationTime { get; set; }
}
