```csharp
using Microsoft.Azure.Cosmos;
using OrderManagementService.Core.Entities;
using OrderManagementService.Core.Interfaces;

namespace OrderManagementService.Infrastructure.Repositories;

public class OrderRepository : IOrderRepository
{
    private readonly CosmosDbContext _context;
    private readonly ILogger<OrderRepository> _logger;

    public OrderRepository(CosmosDbContext context, ILogger<OrderRepository> logger)
    {
        _context = context;
        _logger = logger;
    }

    public async Task<Order> GetByIdAsync(string id)
    {
        try
        {
            var response = await _context.Container.ReadItemAsync<Order>(id, new PartitionKey(id));
            return response.Resource;
        }
        catch (CosmosException ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            _logger.LogWarning("Order with id {OrderId} not found", id);
            return null;
        }
    }

    public async Task<IEnumerable<Order>> GetByCustomerIdAsync(string customerId)
    {
        var query = new QueryDefinition(
            "SELECT * FROM c WHERE c.customerId = @customerId")
            .WithParameter("@customerId", customerId);

        var iterator = _context.Container.GetItemQueryIterator<Order>(query);
        var results = new List<Order>();

        while (iterator.HasMoreResults)
        {
            var response = await iterator.ReadNextAsync();
            results.AddRange(response);
        }

        return results;
    }

    public async Task<Order> AddAsync(Order order)
    {
        var response = await _context.Container.CreateItemAsync(order, new PartitionKey(order.Id));
        return response.Resource;
    }

    public async Task<Order> UpdateAsync(Order order)
    {
        order.LastUpdated = DateTime.UtcNow;
        var response = await _context.Container.UpsertItemAsync(order, new PartitionKey(order.Id));
        return response.Resource;
    }

    public async Task DeleteAsync(string id)
    {
        await _context.Container.DeleteItemAsync<Order>(id, new PartitionKey(id));
    }

    public async Task<bool> ExistsAsync(string id)
    {
        try
        {
            var response = await _context.Container.ReadItemAsync<Order>(id, new PartitionKey(id));
            return response.StatusCode == System.Net.HttpStatusCode.OK;
        }
        catch (CosmosException ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            return false;
        }
    }
}
