using Microsoft.AspNetCore.Mvc;
using OrderManagementService.Core.Entities;
using OrderManagementService.Core.Interfaces;
using OrderManagementService.Dtos;

namespace OrderManagementService.Controllers;

[ApiController]
[Route("api/[controller]")]
public class OrdersController : ControllerBase
{
    private readonly IOrderRepository _orderRepository;
    private readonly ILogger<OrdersController> _logger;

    public OrdersController(IOrderRepository orderRepository, ILogger<OrdersController> logger)
    {
        _orderRepository = orderRepository;
        _logger = logger;
    }

    [HttpGet("{id}")]
    [ProducesResponseType(StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<ActionResult<OrderDto>> GetOrder(string id)
    {
        var order = await _orderRepository.GetByIdAsync(id);
        if (order == null)
        {
            return NotFound();
        }

        return Ok(OrderDto.FromOrder(order));
    }

    [HttpGet("customer/{customerId}")]
    [ProducesResponseType(StatusCodes.Status200OK)]
    public async Task<ActionResult<IEnumerable<OrderDto>>> GetOrdersByCustomer(string customerId)
    {
        var orders = await _orderRepository.GetByCustomerIdAsync(customerId);
        return Ok(orders.Select(OrderDto.FromOrder));
    }

    [HttpPost]
    [ProducesResponseType(StatusCodes.Status201Created)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    public async Task<ActionResult<OrderDto>> CreateOrder(CreateOrderDto createOrderDto)
    {
        var order = new Order
        {
            CustomerId = createOrderDto.CustomerId,
            Items = createOrderDto.Items.Select(i => new OrderItem
            {
                ProductId = i.ProductId,
                ProductName = i.ProductName,
                Quantity = i.Quantity,
                UnitPrice = i.UnitPrice
            }).ToList(),
            ShippingAddress = createOrderDto.ShippingAddress,
            PaymentMethod = createOrderDto.PaymentMethod,
            TotalAmount = createOrderDto.Items.Sum(i => i.Quantity * i.UnitPrice)
        };

        var createdOrder = await _orderRepository.AddAsync(order);
        return CreatedAtAction(nameof(GetOrder), new { id = createdOrder.Id }, OrderDto.FromOrder(createdOrder));
    }

    [HttpPut("{id}")]
    [ProducesResponseType(StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<ActionResult<OrderDto>> UpdateOrder(string id, UpdateOrderDto updateOrderDto)
    {
        var existingOrder = await _orderRepository.GetByIdAsync(id);
        if (existingOrder == null)
        {
            return NotFound();
        }

        existingOrder.Status = updateOrderDto.Status;
        existingOrder.ShippingAddress = updateOrderDto.ShippingAddress;
        existingOrder.PaymentMethod = updateOrderDto.PaymentMethod;
        existingOrder.Items = updateOrderDto.Items.Select(i => new OrderItem
        {
            ProductId = i.ProductId,
            ProductName = i.ProductName,
            Quantity = i.Quantity,
            UnitPrice = i.UnitPrice
        }).ToList();
        existingOrder.TotalAmount = updateOrderDto.Items.Sum(i => i.Quantity * i.UnitPrice);

        var updatedOrder = await _orderRepository.UpdateAsync(existingOrder);
        return Ok(OrderDto.FromOrder(updatedOrder));
    }

    [HttpDelete("{id}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<IActionResult> DeleteOrder(string id)
    {
        var exists = await _orderRepository.ExistsAsync(id);
        if (!exists)
        {
            return NotFound();
        }

        await _orderRepository.DeleteAsync(id);
        return NoContent();
    }
}
