```csharp
using FluentValidation;
using OrderManagementService.Dtos;

namespace OrderManagementService.Validators;

public class CreateOrderValidator : AbstractValidator<CreateOrderDto>
{
    public CreateOrderValidator()
    {
        RuleFor(x => x.CustomerId)
            .NotEmpty().WithMessage("Customer ID is required")
            .MaximumLength(50).WithMessage("Customer ID must be less than 50 characters");

        RuleFor(x => x.Items)
            .NotEmpty().WithMessage("At least one order item is required")
            .Must(items => items.Sum(i => i.Quantity) > 0).WithMessage("Total quantity must be greater than 0");

        RuleForEach(x => x.Items).ChildRules(items =>
        {
            items.RuleFor(i => i.ProductId)
                .NotEmpty().WithMessage("Product ID is required")
                .MaximumLength(50).WithMessage("Product ID must be less than 50 characters");

            items.RuleFor(i => i.ProductName)
                .NotEmpty().WithMessage("Product name is required")
                .MaximumLength(100).WithMessage("Product name must be less than 100 characters");

            items.RuleFor(i => i.Quantity)
                .GreaterThan(0).WithMessage("Quantity must be greater than 0");

            items.RuleFor(i => i.UnitPrice)
                .GreaterThan(0).WithMessage("Unit price must be greater than 0");
        });

        RuleFor(x => x.ShippingAddress)
            .NotEmpty().WithMessage("Shipping address is required")
            .MaximumLength(200).WithMessage("Shipping address must be less than 200 characters");

        RuleFor(x => x.PaymentMethod)
            .NotEmpty().WithMessage("Payment method is required")
            .MaximumLength(50).WithMessage("Payment method must be less than 50 characters");
    }
}
