```rust
use actix_web::{
    web, App, HttpServer, Responder, HttpResponse, middleware::Logger,
    http::header, error::ResponseError
};
use serde::{Serialize, Deserialize};
use std::{io, time::Instant};
use actix_web::dev::Server;
use actix_web_httpauth::middleware::HttpAuthentication;
use log::{info, error};

// Configuration struct
#[derive(Debug, Serialize, Deserialize, Clone)]
struct Config {
    host: String,
    port: u16,
    workers: usize,
    max_connections: usize,
    request_timeout_secs: u64,
}

// Response structures
#[derive(Serialize)]
struct HealthCheckResponse {
    status: String,
    message: String,
    workers: usize,
    uptime: f64,
}

#[derive(Serialize)]
struct ErrorResponse {
    error: String,
    message: String,
}

// Custom error type
#[derive(Debug)]
struct AppError {
    message: String,
}

impl ResponseError for AppError {
    fn error_response(&self) -> HttpResponse {
        HttpResponse::BadRequest().json(ErrorResponse {
            error: "Bad Request".to_string(),
            message: self.message.clone(),
        })
    }
}

// Route handlers
async fn hello() -> impl Responder {
    HttpResponse::Ok().body("Hello, world!")
}

async fn health_check(start_time: web::Data<Instant>) -> impl Responder {
    let uptime = start_time.elapsed().as_secs_f64();
    web::Json(HealthCheckResponse {
        status: "ok".to_string(),
        message: "Server is healthy".to_string(),
        workers: num_cpus::get(),
        uptime,
    })
}

async fn echo(req_body: String) -> impl Responder {
    HttpResponse::Ok()
        .insert_header(header::ContentType::plaintext())
        .body(req_body)
}

async fn validate_token(
    req: actix_web::HttpRequest,
    credentials: HttpAuthentication,
) -> Result<actix_web::dev::ServiceRequest, actix_web::Error> {
    // Simple token validation (replace with your auth logic)
    if let Some(auth_header) = req.headers().get("Authorization") {
        if auth_header.to_str().unwrap_or("") == "Bearer valid-token" {
            return Ok(req.into());
        }
    }
    Err(actix_web::error::ErrorUnauthorized("Invalid token"))
}

// Application setup
pub fn create_server(config: Config) -> io::Result<Server> {
    // Initialize logger
    std::env::set_var("RUST_LOG", "actix_web=info,actix_server=info");
    env_logger::init();

    info!("Starting server with {} workers", config.workers);

    let start_time = Instant::now();
    let start_time_data = web::Data::new(start_time);

    let server = HttpServer::new(move || {
        App::new()
            // Middleware
            .wrap(Logger::default())
            .wrap(HttpAuthentication::with_fn(validate_token))
            .app_data(start_time_data.clone())

            // Configure JSON and form data handling
            .app_data(web::JsonConfig::default().error_handler(|err, _req| {
                AppError {
                    message: format!("Invalid JSON: {}", err),
                }
                .into()
            }))
            .app_data(web::FormConfig::default().error_handler(|err, _req| {
                AppError {
                    message: format!("Invalid form data: {}", err),
                }
                .into()
            }))

            // Routes
            .route("/", web::get().to(hello))
            .route("/health", web::get().to(health_check))
            .route("/echo", web::post().to(echo))
            .route("/metrics", web::get().to(metrics))
    })
    .bind((config.host.as_str(), config.port))?
    .workers(config.workers)
    .max_connections(config.max_connections)
    .client_request_timeout(std::time::Duration::from_secs(config.request_timeout_secs))
    .shutdown_timeout(30) // Graceful shutdown timeout in seconds
    .run();

    Ok(server)
}

// Example metrics endpoint
async fn metrics() -> impl Responder {
    HttpResponse::Ok().body("Metrics endpoint")
}

#[actix_web::main]
async fn main() -> io::Result<()> {
    // Load configuration (in production, use config files or env vars)
    let config = Config {
        host: "0.0.0.0".to_string(),
        port: 8080,
        workers: num_cpus::get(),
        max_connections: 100_000,
        request_timeout_secs: 30,
    };

    info!("Starting server on {}:{}", config.host, config.port);

    let server = create_server(config)?;

    // Run the server
    if let Err(e) = server.await {
        error!("Server error: {}", e);
        std::process::exit(1);
    }

    Ok(())
}
```

