/// Middleware to log request timing
async fn logging_middleware(
    req: Request<Body>,
    next: impl Fn(Request<Body>) -> std::future::Ready<Result<Response<Body>, Infallible>>,
) -> Result<Response<Body>, Infallible> {
    let start = Instant::now();
    let path = req.uri().path().to_string();

    let response = next(req).await;

    let duration = start.elapsed();
    println!(
        "{} {} - {:?}",
        response.as_ref().map_or(0, |r| r.status().as_u16()),
        path,
        duration
    );

    response
}

/// Rate limiting middleware
async fn rate_limiting_middleware(
    req: Request<Body>,
    semaphore: Arc<Semaphore>,
    next: impl Fn(Request<Body>) -> std::future::Ready<Result<Response<Body>, Infallible>>,
) -> Result<Response<Body>, Infallible> {
    // Acquire permit with timeout to prevent waiting indefinitely
    match semaphore.try_acquire() {
        Ok(_) => next(req).await,
        Err(_) => Ok(Response::new(Body::from("Too many requests"))
            .with_status(StatusCode::TOO_MANY_REQUESTS)),
    }
}

