use tokio::sync::Semaphore;
use std::time::Instant;

// Custom service to handle requests with concurrency limiting
struct AppService {
    semaphore: Arc<Semaphore>,
}

impl AppService {
    fn new(max_concurrent: usize) -> Self {
        Self {
            semaphore: Arc::new(Semaphore::new(max_concurrent)),
        }
    }
}

async fn handle_request(
    req: Request<Body>,
    _: Arc<Semaphore>,
) -> Result<Response<Body>, Infallible> {
    let start = Instant::now();

    // Simulate some work (e.g., database query, file I/O)
    tokio::time::sleep(std::time::Duration::from_millis(10)).await;

    let response = match req.method() {
        &Method::GET => {
            if req.uri().path() == "/" {
                Response::new(Body::from("Hello, World!"))
            } else {
                let mut not_found = Response::default();
                *not_found.status_mut() = StatusCode::NOT_FOUND;
                not_found
            }
        }
        _ => {
            let mut method_not_allowed = Response::default();
            *method_not_allowed.status_mut() = StatusCode::METHOD_NOT_ALLOWED;
            method_not_allowed
        }
    };

    println!(
        "Handled {} request to {} in {:?}",
        req.method(),
        req.uri().path(),
        start.elapsed()
    );

    Ok(response)
}

#[tokio::main]
