    let service = AppService::new(max_concurrent);

    // Create a service to handle each connection
    let make_svc = make_service_fn(move |_conn| {
        let service = AppService {
            semaphore: service.semaphore.clone(),
        };
        async move {
            Ok::<_, Infallible>(service_fn(move |req| {
                handle_request(req, service.semaphore.clone())
            }))
        }
    });

    // Create the server
    let server = Server::bind(&addr).serve(make_svc);

    println!("Server running on http://{} (max concurrent: {})", addr, max_concurrent);

    // Run forever
